try:
    import customtkinter as ctk
except ImportError:
    print("This app requires the 'customtkinter' package.")
    print("Install it with:\n\n    pip install customtkinter\n")
    sys.exit(1)

# This app's palette (navy/parchment/brass) is a single fixed light design --
# it was never built with a dark variant. Without forcing this, CustomTkinter
# defaults to "System" appearance mode, and on a machine running Windows/macOS
# Dark Mode, every widget property we did NOT explicitly color (e.g. CTkEntry
# boxes) silently flips to dark-mode defaults -- typically dark text on a dark
# background, or vice versa, sitting inside our explicitly-light cards. That
# mismatch is what caused text to become unreadable/invisible for users in
# Dark Mode. Forcing light mode here makes rendering identical regardless of
# the host OS's theme.
ctk.set_appearance_mode("light")
ctk.set_default_color_theme("blue")

# ============================================================================
# PATHS / DB -- shared with the CLI trainer
# ============================================================================

APP_DIR = os.path.join(os.path.expanduser("~"), ".nj_re_trainer")
DB_PATH = os.path.join(APP_DIR, "progress.db")

def ensure_app_dir():
    os.makedirs(APP_DIR, exist_ok=True)

def _safe_query(conn, sql, params=(), default=None):
    """Run a query that must not take the app down if the schema is not what
    this build expects.

    Real databases drift: a file from an older build lacks columns added
    since, a partially-restored backup can be missing a table, and a user
    who edits the file externally can produce anything. Previously an
    OperationalError from any of those cases propagated straight out of an
    analytics function and killed the view. Analytics are advisory -- the
    right behaviour is to report nothing rather than crash."""
    try:
        return conn.execute(sql, params).fetchall()
    except sqlite3.OperationalError:
        return [] if default is None else default
    except Exception:
        return [] if default is None else default

def table_has_columns(conn, table, cols):
    """True when every named column exists. Lets callers degrade knowingly
    rather than discovering the gap through an exception."""
    try:
        have = {r[1] for r in conn.execute(f"PRAGMA table_info({table})")}
        return set(cols).issubset(have)
    except Exception:
        return False

def db_connect():
    ensure_app_dir()
    conn = sqlite3.connect(DB_PATH, timeout=10.0)
    conn.row_factory = sqlite3.Row
    try:
        # Worker threads open their own connections; WAL lets readers and one
        # writer proceed together, and the busy timeout turns a momentary lock
        # into a short wait instead of an exception swallowed downstream.
        conn.execute("PRAGMA journal_mode=WAL")
        conn.execute("PRAGMA busy_timeout=10000")
    except sqlite3.Error:
        pass
    return conn

def init_schema(conn):
    conn.executescript("""
    CREATE TABLE IF NOT EXISTS card_progress (
        card_id TEXT PRIMARY KEY,
        half_life REAL DEFAULT 1.0,
        reps INTEGER DEFAULT 0,
        due_date TEXT,
        last_reviewed TEXT
    );
    CREATE TABLE IF NOT EXISTS checklist (
        topic_id TEXT PRIMARY KEY,
        done INTEGER DEFAULT 0
    );
    CREATE TABLE IF NOT EXISTS attempts (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        timestamp TEXT,
        mode TEXT,
        question_id TEXT,
        topic_id TEXT,
        correct INTEGER,
        hint_level INTEGER DEFAULT 0,
        a_irt REAL,
        b_irt REAL,
        time_taken REAL
    );
    CREATE TABLE IF NOT EXISTS sessions (
        date TEXT PRIMARY KEY
    );
    CREATE TABLE IF NOT EXISTS exam_results (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        timestamp TEXT,
        total INTEGER,
        correct INTEGER,
        pct REAL,
        time_used REAL,
        national_pct REAL,
        nj_pct REAL
    );
    CREATE TABLE IF NOT EXISTS quiz_results (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        timestamp TEXT,
        total INTEGER,
        correct INTEGER,
        pct REAL,
        scope TEXT
    );
    CREATE TABLE IF NOT EXISTS topic_mastery (
        topic_id TEXT PRIMARY KEY,
        p_mastery REAL DEFAULT 0.3
    );
    CREATE TABLE IF NOT EXISTS settings (
        key TEXT PRIMARY KEY,
        value TEXT
    );
    CREATE TABLE IF NOT EXISTS error_log (
        question_id TEXT PRIMARY KEY,
        topic_id TEXT,
        error_type TEXT,
        tagged_at TEXT,
        consecutive_correct INTEGER DEFAULT 0,
        active INTEGER DEFAULT 1
    );
    CREATE TABLE IF NOT EXISTS interventions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        timestamp TEXT,
        mode TEXT,
        signal TEXT,
        question_index INTEGER,
        acc_before REAL,
        acc_after REAL,
        resolved INTEGER DEFAULT 0
    );
    CREATE TABLE IF NOT EXISTS diagnostic_results (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        timestamp TEXT,
        n INTEGER,
        timed_correct INTEGER,
        missed_count INTEGER,
        untimed_redo_correct INTEGER,
        timed_pct REAL,
        untimed_equiv_pct REAL,
        gap_pct REAL,
        classification TEXT
    );
    """)
    conn.commit()
    # theta_at: the learner's ability estimate at the moment the attempt was
    # recorded (before the answer was folded in). Item-fit residuals need
    # the expectation the model held AT THE TIME; recomputing them against
    # today's theta turns ordinary learning into apparent misfit.
    for col, coltype in [("confidence", "INTEGER"), ("error_type", "TEXT"),
                          ("initial_answer", "INTEGER"), ("chosen", "INTEGER"),
                          ("theta_at", "REAL")]:
        try:
            conn.execute(f"ALTER TABLE attempts ADD COLUMN {col} {coltype}")
        except sqlite3.OperationalError:
            pass
    # FSRS-6 migration: the scheduler moved from a single half-life number to
    # FSRS's stability/difficulty/state model. New columns are additive so an
    # existing card_progress table (and its half_life history) is untouched;
    # cards simply start fresh under FSRS on their next review.
    for col, coltype in [("stability", "REAL"), ("difficulty", "REAL"),
                          ("fsrs_state", "INTEGER"), ("fsrs_step", "INTEGER")]:
        try:
            conn.execute(f"ALTER TABLE card_progress ADD COLUMN {col} {coltype}")
        except sqlite3.OperationalError:
            pass
    # BKT+Forget migration: track when each topic's mastery was last touched
    # so a time-decay forgetting term can be applied on the next update
    # (Khajah, Lindsey & Mozer 2016 -- enabling BKT's forget parameter closes
    # most of the gap to deep knowledge-tracing models on several datasets).
    try:
        conn.execute("ALTER TABLE topic_mastery ADD COLUMN last_updated TEXT")
    except sqlite3.OperationalError:
        pass
    # Intervention outcome tracking: distinguishes a cue that ran its full
    # recovery window from one cut short by the learner quitting, so
    # effectiveness stats can report abandonment instead of silently
    # dropping those cases (which biased the figure optimistic).
    for col, coltype in [("outcome", "TEXT"), ("answers_after", "INTEGER")]:
        try:
            conn.execute(f"ALTER TABLE interventions ADD COLUMN {col} {coltype}")
        except sqlite3.OperationalError:
            pass
    # Successive-relearning mastery gate (Rawson & Dunlosky 2011/2022): a
    # card should not be treated as truly mastered just because FSRS has
    # pushed its interval out after a couple of good reviews. The
    # prescriptively optimal criterion is 3 consecutive correct recalls at
    # initial learning, THEN 1 correct recall in each of 3 further sessions
    # spaced on separate days. This tracks that criterion as a layer on top
    # of (not a replacement for) FSRS's own interval scheduling.
    for col, coltype in [("initial_streak", "INTEGER DEFAULT 0"),
                         ("initial_criterion_met", "INTEGER DEFAULT 0"),
                         ("relearn_sessions_completed", "INTEGER DEFAULT 0"),
                         ("relearn_last_date", "TEXT"),
                         ("successive_relearning_complete", "INTEGER DEFAULT 0")]:
        try:
            conn.execute(f"ALTER TABLE card_progress ADD COLUMN {col} {coltype}")
        except sqlite3.OperationalError:
            pass
    # Per-review log, append-only. Everything above (card_progress) only
    # ever stored the CURRENT aggregated FSRS state per card -- fine for
    # scheduling, but fitting personalized FSRS parameters (Section 4.6 of
    # the fused research: "re-optimize, don't replace") needs the full
    # sequence of individual review events per card, which was never being
    # captured. This starts capturing it going forward; re-optimization
    # only becomes meaningful once enough NEW reviews accumulate under this
    # logging -- there is no way to reconstruct it retroactively for
    # reviews graded before this table existed.
    conn.execute("""
        CREATE TABLE IF NOT EXISTS review_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            card_id TEXT,
            rating INTEGER,
            reviewed_at TEXT
        )""")
    # Review LATENCY -- how long the learner sat with the card before
    # grading it. The app has always measured response time meticulously for
    # quiz items and never once for flashcards, which discards the single
    # most useful objective signal about memory strength available here.
    # See fluency_adjusted_grade() for why it matters.
    try:
        conn.execute("ALTER TABLE review_log ADD COLUMN duration_ms INTEGER")
    except sqlite3.OperationalError:
        pass
    # ---- Restructuring spec (learner-phase / composer / detect-to-adapt) ----
    # session_events: start/complete/abandon/pause per session. The phase
    # state machine (learner_phase) reads abandonment and completion counts
    # from here; `show_view` already calls active_session.abandon(), which
    # previously left no trace at all.
    conn.execute("""
        CREATE TABLE IF NOT EXISTS session_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            ts TEXT, kind TEXT, mode TEXT,
            n_items INTEGER, n_correct INTEGER, phase TEXT
        )""")
    # session_events.planned_mean_p: the mean success probability the
    # composer planned for a session, so the phase gate can judge accuracy
    # against what was actually served rather than an absolute bar the bank
    # may not be able to supply at this ability.
    try:
        conn.execute("ALTER TABLE session_events ADD COLUMN planned_mean_p REAL")
    except sqlite3.OperationalError:
        pass
    init_pending_retests_schema(conn)
    # exam_plan: the learner's own "if ... then I will ..." plan for exam
    # day (view_exam_eve). Written locally, read back on Today, sent
    # nowhere. The expressive-writing text that precedes it is never
    # stored -- its value is in the writing, not the record.
    conn.execute("""
        CREATE TABLE IF NOT EXISTS exam_plan (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            ts TEXT, exam_date TEXT, cue TEXT, response TEXT
        )""")
    # skill_views: authored rule statement / worked scenario per sub-skill,
    # used as the pretest instruction step, the controller's scaffold
    # action, and expertise-reversal-aware fading. Empty until authored; every
    # reader degrades gracefully (falls back to the item rationale / cue).
    conn.execute("""
        CREATE TABLE IF NOT EXISTS skill_views (
            skill_id TEXT, kind TEXT, body TEXT, provenance TEXT,
            PRIMARY KEY (skill_id, kind)
        )""")
    # interventions.action: which ADAPTIVE ACTION (not just cue) the
    # controller took, so close_intervention's acc_after harm-learning
    # applies per action, not just per signal.
    try:
        conn.execute("ALTER TABLE interventions ADD COLUMN action TEXT")
    except sqlite3.OperationalError:
        pass
    conn.commit()
    _build_content_search_index(conn)

def _build_content_search_index(conn):
    """Global search index over questions, flashcards, and topic notes.

    Rebuilt every startup (drop + re-insert) rather than incrementally
    maintained: the content is static per build (no user data touches this
    table), so idempotent rebuild is simpler and safer than trying to keep
    an index in sync with a bank that never actually changes at runtime.
    Cheap at this scale -- under 400 rows."""
    try:
        conn.executescript("""
            CREATE VIRTUAL TABLE IF NOT EXISTS content_search
            USING fts5(kind, item_id, topic_id, title, body);
        """)
    except sqlite3.OperationalError:
        return  # FTS5 unavailable; search feature will report unavailable
    conn.execute("DELETE FROM content_search")
    rows = []
    for q in QUIZ_LIST:
        body = q["q"] + "\n" + "\n".join(q["opts"]) + "\n" + q.get("exp", "")
        rows.append(("question", q["id"], q["topic"], q["q"][:120], body))
    for c in FLASHCARDS:
        rows.append(("flashcard", c["id"], c["topic"], c["term"], c.get("def", "")))
    for tid, t in TOPICS.items():
        rows.append(("note", tid, tid, t["short"], t.get("notes", "")))
    # Skills join the same index, so the map and the Search view retrieve
    # concepts from one place (kind='skill').
    try:
        rows.extend(vis_skill_search_rows())
    except NameError:
        pass
    conn.executemany(
        "INSERT INTO content_search (kind,item_id,topic_id,title,body) VALUES (?,?,?,?,?)",
        rows)
    conn.commit()

def search_content(conn, query, limit=20):
    """Ranked full-text search across the whole bank. Returns a list of
    dicts with kind, item_id, topic_id, title, and a short snippet."""
    query = (query or "").strip()
    if not query:
        return []
    # FTS5 query syntax breaks on bare punctuation/quotes in free-typed
    # search boxes; quote each token so the user's literal words are
    # searched rather than being parsed as FTS5 operators.
    tokens = re.findall(r"[A-Za-z0-9']+", query)
    if not tokens:
        return []
    fts_query = " ".join(f'"{t}"' for t in tokens)
    try:
        rows = conn.execute("""
            SELECT kind, item_id, topic_id, title,
                   snippet(content_search, 4, '[', ']', '...', 12) AS snip
            FROM content_search WHERE content_search MATCH ?
            ORDER BY rank LIMIT ?""", (fts_query, limit)).fetchall()
    except sqlite3.OperationalError:
        return []
    return [{"kind": r["kind"], "item_id": r["item_id"], "topic_id": r["topic_id"],
            "title": r["title"], "snippet": r["snip"]} for r in rows]

def search_content_any(conn, terms, limit=8):
    """OR-based variant of search_content, for callers that want the best
    available match among a set of salient terms rather than a strict
    all-terms match. Kept deliberately SEPARATE from search_content rather
    than adding an OR mode there: the Search view's AND behavior is the
    right one for a person typing a specific short phrase (e.g. "trust
    account six years" should match a document containing all of those
    words, not just any one). This variant exists for the hint system,
    where the source is a single long question sentence being reduced to
    its most distinctive words -- there, requiring every one of those words
    to appear verbatim in the same note was tested and found far too
    strict: only 7 of 40 real questions found a relevant note. Loosening to
    OR raised that to 25 of 40, since FTS5's bm25 ranking still sorts a note
    matching MORE of the terms above one matching only one."""
    terms = [t for t in (terms or []) if t]
    if not terms:
        return []
    fts_query = " OR ".join(f'"{t}"' for t in terms)
    try:
        rows = conn.execute("""
            SELECT kind, item_id, topic_id, title,
                   snippet(content_search, 4, '[', ']', '...', 12) AS snip
            FROM content_search WHERE content_search MATCH ? AND kind != 'skill'
            ORDER BY rank LIMIT ?""", (fts_query, limit)).fetchall()
    except sqlite3.OperationalError:
        return []
    return [{"kind": r["kind"], "item_id": r["item_id"], "topic_id": r["topic_id"],
            "title": r["title"], "snippet": r["snip"]} for r in rows]

def mark_session_today(conn):
    today = date.today().isoformat()
    conn.execute("INSERT OR IGNORE INTO sessions (date) VALUES (?)", (today,))
    conn.commit()

def get_setting(conn, key, default=None):
    row = conn.execute("SELECT value FROM settings WHERE key=?", (key,)).fetchone()
    return row["value"] if row else default

def set_setting(conn, key, value):
    conn.execute("""INSERT INTO settings (key, value) VALUES (?,?)
                     ON CONFLICT(key) DO UPDATE SET value=excluded.value""", (key, value))
    conn.commit()

