def load_data():
    raw = base64.b64decode(_DATA_B64).decode("utf-8")
    data = json.loads(raw)
    topics = {t["id"]: t for t in data["TOPICS"]}
    flashcards = data["FLASHCARDS"]
    quiz_bank = {q["id"]: q for q in data["QUIZ_BANK"]}
    return topics, flashcards, quiz_bank

TOPICS, FLASHCARDS, QUIZ_BANK = load_data()
QUIZ_LIST = list(QUIZ_BANK.values())

# ============================================================================
# GENERATIVE MATH ENGINE (same templates as the CLI trainer)
# ============================================================================

def _money(x):
    return f"${x:,.0f}"

def _shuffle_opts(correct_val, distractors, fmt):
    vals = [correct_val] + list(distractors)
    for i in range(1, len(vals)):
        attempts = 0
        while attempts < 12 and any(
            fmt(vals[i]) == fmt(vals[j]) for j in range(len(vals)) if j != i
        ):
            bump = random.choice([1.07, 0.93, 1.13, 0.87, 1.21, 0.79])
            nudged = vals[i] * bump
            if nudged == vals[i]:
                nudged = vals[i] + (1 if vals[i] >= 0 else -1)
            vals[i] = nudged
            attempts += 1
    labeled = [fmt(v) for v in vals]
    idx = list(range(4))
    random.shuffle(idx)
    shuffled_opts = [labeled[i] for i in idx]
    correct_idx = idx.index(0)
    return shuffled_opts, correct_idx

def gen_commission_split():
    price = random.choice(range(180000, 950000, 5000))
    rate = random.choice([4.5, 5, 5.5, 6, 6.5]) / 100
    splits = random.choice([2, 3])
    total_comm = price * rate
    each = total_comm / splits
    distractors = [total_comm, total_comm / (splits + 1), each * 2]
    opts, correct_idx = _shuffle_opts(each, distractors, _money)
    q = (f"A property sells for {_money(price)} with a {rate*100:.1f}% commission, "
         f"split evenly {splits} ways. How much does each side receive?")
    exp = f"Total commission = {_money(price)} \u00d7 {rate*100:.1f}% = {_money(total_comm)}; split {splits} ways = {_money(each)} each."
    return {"q": q, "opts": opts, "a": correct_idx, "exp": exp, "difficulty": "medium", "b": -0.1, "a_irt": 1.1}

def gen_ltv():
    price = random.choice(range(200000, 900000, 5000))
    down_pct = random.choice([5, 10, 15, 20, 25])
    loan = price * (100 - down_pct) / 100
    ltv = loan / price * 100
    distractors = [ltv - 10, ltv + 10, down_pct]
    opts, correct_idx = _shuffle_opts(ltv, distractors, lambda v: f"{v:.0f}%")
    q = (f"A buyer purchases a {_money(price)} home with a {down_pct}% down payment. "
         f"What is the loan-to-value (LTV) ratio?")
    exp = f"Down payment leaves a loan of {100-down_pct}% of price, so LTV = {100-down_pct}%."
    return {"q": q, "opts": opts, "a": correct_idx, "exp": exp, "difficulty": "easy", "b": -0.8, "a_irt": 0.9}

def gen_cap_rate_value():
    noi = random.choice(range(30000, 120000, 1000))
    cap = random.choice([5, 5.5, 6, 6.5, 7, 7.5, 8]) / 100
    value = noi / cap
    distractors = [noi * cap, value * 1.3, value * 0.7]
    opts, correct_idx = _shuffle_opts(value, distractors, _money)
    q = f"A property generates {_money(noi)} in annual NOI. At a {cap*100:.1f}% cap rate, what is its indicated value?"
    exp = f"Value = NOI \u00f7 Cap Rate = {_money(noi)} \u00f7 {cap*100:.1f}% = {_money(value)}."
    return {"q": q, "opts": opts, "a": correct_idx, "exp": exp, "difficulty": "medium", "b": 0.2, "a_irt": 1.2}

def gen_tax_proration():
    annual_tax = random.choice(range(3600, 12000, 200))
    days_remaining = random.choice(range(30, 330, 15))
    daily = annual_tax / 360
    owed = daily * days_remaining
    distractors = [daily * (360 - days_remaining), annual_tax - owed, owed * 2]
    opts, correct_idx = _shuffle_opts(owed, distractors, _money)
    q = (f"Annual property taxes of {_money(annual_tax)} were prepaid in full by the seller. "
         f"At closing, {days_remaining} days remain in the tax year for the buyer's period of ownership. "
         f"Using a 360-day year, how much does the buyer owe the seller in proration?")
    exp = f"Daily rate = {_money(annual_tax)} \u00f7 360 = {_money(daily)}/day. {_money(daily)} \u00d7 {days_remaining} days = {_money(owed)}."
    return {"q": q, "opts": opts, "a": correct_idx, "exp": exp, "difficulty": "hard", "b": 1.0, "a_irt": 1.3}

def gen_property_tax():
    assessed = random.choice(range(150000, 500000, 5000))
    rate_per_100 = random.choice([1.8, 2.1, 2.35, 2.6, 2.85, 3.1])
    tax = (assessed / 100) * rate_per_100
    distractors = [tax * 0.1, tax * 1.5, tax * 2.5]
    opts, correct_idx = _shuffle_opts(tax, distractors, _money)
    q = f"A property is assessed at {_money(assessed)} with a tax rate of ${rate_per_100:.2f} per $100 of assessed value. What is the annual property tax?"
    exp = f"({_money(assessed)} \u00f7 100) \u00d7 ${rate_per_100:.2f} = {tax:,.0f} \u2192 {_money(tax)}."
    return {"q": q, "opts": opts, "a": correct_idx, "exp": exp, "difficulty": "medium", "b": -0.2, "a_irt": 1.0}

def gen_discount_points():
    loan = random.choice(range(150000, 600000, 5000))
    points = random.choice([1, 1.5, 2, 2.5, 3])
    cost = loan * points / 100
    distractors = [cost * 2, cost / 2, loan * 0.005]
    opts, correct_idx = _shuffle_opts(cost, distractors, _money)
    q = f"A borrower pays {points} discount point(s) on a {_money(loan)} loan. What is the dollar cost?"
    exp = f"{points} point(s) \u00d7 1% \u00d7 {_money(loan)} = {_money(cost)}."
    return {"q": q, "opts": opts, "a": correct_idx, "exp": exp, "difficulty": "easy", "b": -0.7, "a_irt": 0.9}

def gen_grm():
    price = random.choice(range(200000, 800000, 5000))
    monthly_rent = random.choice(range(1200, 4500, 100))
    grm = price / monthly_rent
    distractors = [monthly_rent / price, grm * 1.4, grm * 0.6]
    opts, correct_idx = _shuffle_opts(grm, distractors, lambda v: f"{v:.1f}")
    q = f"A rental property sells for {_money(price)} and rents for {_money(monthly_rent)}/month. What is the gross rent multiplier (GRM)?"
    exp = f"GRM = Price \u00f7 Monthly Rent = {_money(price)} \u00f7 {_money(monthly_rent)} \u2248 {grm:.1f}."
    return {"q": q, "opts": opts, "a": correct_idx, "exp": exp, "difficulty": "medium", "b": 0.1, "a_irt": 1.05}

def gen_area():
    length = random.choice(range(40, 220, 5))
    width = random.choice(range(30, 200, 5))
    area = length * width
    distractors = [2 * (length + width), area / 2, area * 2]
    opts, correct_idx = _shuffle_opts(area, distractors, lambda v: f"{v:,.0f} sq ft")
    q = f"A rectangular lot measures {length} feet by {width} feet. What is its area?"
    exp = f"{length} \u00d7 {width} = {area:,} square feet."
    return {"q": q, "opts": opts, "a": correct_idx, "exp": exp, "difficulty": "easy", "b": -1.1, "a_irt": 0.85}

def gen_acreage_cost():
    acres = random.choice([0.5, 1, 1.5, 2, 2.5, 3, 5, 7.5, 10])
    per_acre = random.choice(range(30000, 150000, 5000))
    total = acres * per_acre
    distractors = [total / 2, total * 0.75, total * 1.25]
    opts, correct_idx = _shuffle_opts(total, distractors, _money)
    q = f"A {acres} acre parcel is priced at {_money(per_acre)} per acre. What is the total price?"
    exp = f"{acres} \u00d7 {_money(per_acre)} = {_money(total)}."
    return {"q": q, "opts": opts, "a": correct_idx, "exp": exp, "difficulty": "easy", "b": -0.9, "a_irt": 0.85}

def gen_seller_net():
    net_target = random.choice(range(200000, 600000, 5000))
    rate = random.choice([5, 5.5, 6]) / 100
    gross = net_target / (1 - rate)
    distractors = [net_target * (1 + rate), gross * 1.1, gross * 0.9]
    opts, correct_idx = _shuffle_opts(gross, distractors, _money)
    q = f"A seller wants to net {_money(net_target)} after paying a {rate*100:.1f}% commission. What gross sale price is required?"
    exp = f"Gross = Net \u00f7 (1 \u2212 rate) = {_money(net_target)} \u00f7 {1-rate:.3f} \u2248 {_money(gross)}."
    return {"q": q, "opts": opts, "a": correct_idx, "exp": exp, "difficulty": "hard", "b": 0.8, "a_irt": 1.25}

def gen_dti():
    income = random.choice(range(4000, 12000, 250))
    debt = random.choice(range(800, 4000, 100))
    dti = debt / income * 100
    distractors = [dti / 2, dti * 1.5, (income - debt) / income * 100]
    opts, correct_idx = _shuffle_opts(dti, distractors, lambda v: f"{v:.0f}%")
    q = f"A buyer has {_money(debt)}/month in total debt payments against {_money(income)}/month gross income. What is the back-end DTI ratio?"
    exp = f"DTI = {_money(debt)} \u00f7 {_money(income)} \u2248 {dti:.0f}%."
    return {"q": q, "opts": opts, "a": correct_idx, "exp": exp, "difficulty": "medium", "b": 0.0, "a_irt": 1.0}

def gen_simple_interest():
    loan = random.choice(range(100000, 500000, 5000))
    rate = random.choice([4.5, 5, 5.5, 6, 6.5]) / 100
    monthly = loan * rate / 12
    distractors = [loan * rate, monthly * 2, monthly / 2]
    opts, correct_idx = _shuffle_opts(monthly, distractors, _money)
    q = f"A {_money(loan)} loan carries {rate*100:.1f}% annual simple interest. What is roughly one month's interest?"
    exp = f"Annual interest = {_money(loan)} \u00d7 {rate*100:.1f}% = {_money(loan*rate)}; \u00f7 12 \u2248 {_money(monthly)}."
    return {"q": q, "opts": opts, "a": correct_idx, "exp": exp, "difficulty": "medium", "b": 0.1, "a_irt": 1.05}

MATH_TEMPLATES = [
    gen_commission_split, gen_ltv, gen_cap_rate_value, gen_tax_proration,
    gen_property_tax, gen_discount_points, gen_grm, gen_area,
    gen_acreage_cost, gen_seller_net, gen_dti, gen_simple_interest,
]

def generate_math_item():
    template = random.choice(MATH_TEMPLATES)
    raw = template()
    uid = f"gen-{template.__name__}-{random.randint(100000,999999)}"
    return {
        "id": uid, "topic": "t10", "q": raw["q"], "opts": raw["opts"], "a": raw["a"],
        "exp": raw["exp"], "difficulty": raw["difficulty"],
        "b_irt": raw["b"], "a_irt": raw["a_irt"], "generated": True,
    }

# ============================================================================
# IRT: 2PL MAP ESTIMATOR (legacy) + THE ONE ABILITY NUMBER THE APP SHOWS
# ============================================================================
# `estimate_theta` is the original 2PL Newton MAP. It is kept for the trend
# plot only; every ability number a learner sees, and everything that
# selects or forecasts on ability, goes through `current_theta`, which is
# the 3PL EAP in `ability_with_se` (hint-excluded, ladder-gated, anchored
# prior). Two estimators on two scales feeding different screens is how the
# learner ends up shown "+1.55" in one header and "+1.08" in another.

def irt_p(theta, a, b, c=0.0):
    z = a * (theta - b)
    z = max(-30, min(30, z))
    return c + (1.0 - c) / (1.0 + math.exp(-z))

def estimate_theta(responses, prior_var=4.0, iters=25, tol=1e-5):
    """2PL Newton MAP with an N(0, prior_var) prior. Legacy point estimate;
    not the 3PL EAP the app displays (see current_theta)."""
    if not responses:
        return 0.0
    theta = 0.0
    for _ in range(iters):
        grad = -theta / prior_var
        hess = -1.0 / prior_var
        for a, b, y in responses:
            p = irt_p(theta, a, b)
            grad += a * (y - p)
            hess += -(a ** 2) * p * (1 - p)
        if hess == 0:
            break
        step = grad / hess
        theta -= step
        theta = max(-4.0, min(4.0, theta))
        if abs(step) < tol:
            break
    return round(theta, 4)

def fisher_info(theta, a, b):
    p = irt_p(theta, a, b)
    return (a ** 2) * p * (1 - p)

def get_response_history(conn, topic_id=None, limit=500):
    """(a, b, correct) triples under the same evidence rules as
    ability_with_se: heavily-hinted answers are not unaided knowledge, and
    template / uncalibrated candidate items are practice, not measurement.
    Newest first."""
    where = ["a_irt IS NOT NULL", "(hint_level IS NULL OR hint_level < ?)"]
    params = [HEAVY_HINT_THRESHOLD]
    if topic_id:
        where.append("topic_id=?")
        params.append(topic_id)
    params.append(limit)
    rows = conn.execute(f"""SELECT question_id, a_irt, b_irt, correct FROM attempts
                             WHERE {' AND '.join(where)} ORDER BY id DESC LIMIT ?""",
                        params).fetchall()
    rows = model_feed_filter(conn, rows)
    return [(r["a_irt"], r["b_irt"], r["correct"]) for r in rows if r["a_irt"] is not None]

def current_theta(conn, topic_id=None):
    """The app's single ability estimate: 3PL EAP from ability_with_se."""
    return ability_with_se(conn, topic_id)[0]

def _phi(z):
    return 0.5 * (1.0 + math.erf(z / math.sqrt(2.0)))

def predict_pass_probability(conn):
    """(theta, expected exam score %, P(both portions pass)).

    The examination is passed only when the national AND the state portion
    are passed at the same sitting, so readiness is the probability that both
    clear, each from its own partially pooled ability posterior (see
    portion_readiness). The expected score remains the pooled blueprint score.
    If the portion computation cannot run, readiness is reported as 0 rather
    than falling back to a pooled probability that can overstate it."""
    theta, mean_score, _pooled = predict_pass_probability_pooled(conn)
    try:
        p_both = portion_readiness(conn)["p_both"]
    except (sqlite3.Error, ValueError, TypeError, KeyError, ZeroDivisionError) as e:
        _audit(conn, "portion_readiness_failed", f"{type(e).__name__}: {e}")
        p_both = None
    return theta, mean_score, (0.0 if p_both is None else p_both)


def predict_pass_probability_pooled(conn):
    """(theta, expected exam score %, P(pooled score >= 70)) -- analytical only.

    Deterministic: the expected score is taken over the WHOLE bank, each
    content group weighted to the exam blueprint (80 national / 30 NJ of
    110), rather than a fresh random 110-item sample per call -- the old
    sampling made the number jitter by a few points on every redraw with
    no new evidence. Uncertainty about theta is folded in by integrating
    over a normal posterior N(theta, se^2) on the EAP grid (se already
    carries the calibration inflation), so P(pass) is a posterior
    predictive, not a point-estimate plug-in; the score variance at each
    theta is the binomial variance of a 110-item exam."""
    theta, se, _n = ability_with_se(conn)
    groups = {"National": [], "NJ-Specific": []}
    for q in QUIZ_LIST:
        g = TOPICS.get(q.get("topic"), {}).get("group")
        if g in groups:
            groups[g].append((q.get("a_irt", 1.0), q.get("b_irt", 0.0)))
    blueprint = {"National": 80, "NJ-Specific": 30}
    n_exam = sum(blueprint[g] for g in groups if groups[g])
    if n_exam == 0:
        return theta, 0.0, 0.0
    se = max(float(se or 0.0), 0.05)
    grid_w = [math.exp(-0.5 * ((t - theta) / se) ** 2) for t in THETA_GRID]
    tot_w = sum(grid_w)
    mean_score = 0.0
    p_pass = 0.0
    for t, w in zip(THETA_GRID, grid_w):
        w /= tot_w
        if w < 1e-7:
            continue
        exp_count = 0.0
        var_count = 0.0
        for g, items in groups.items():
            if not items:
                continue
            ps = [irt_p3(t, a, b, GUESS_C) for a, b in items]
            exp_count += blueprint[g] * sum(ps) / len(ps)
            var_count += blueprint[g] * sum(p * (1 - p) for p in ps) / len(ps)
        e_pct = exp_count / n_exam * 100.0
        sd_pct = math.sqrt(max(var_count, 1e-9)) / n_exam * 100.0
        mean_score += w * e_pct
        p_pass += w * (1.0 - _phi((70.0 - e_pct) / sd_pct))
    return theta, mean_score, max(0.0, min(1.0, p_pass))

# ============================================================================
# BAYESIAN KNOWLEDGE TRACING
# ============================================================================

BKT_P_INIT = 0.30
BKT_P_TRANSIT = 0.15
BKT_P_SLIP = 0.10
BKT_P_GUESS = 0.25
BKT_P_FORGET_PER_DAY = 0.008   # small daily decay applied between sessions

def get_mastery(conn, topic_id):
    row = conn.execute("SELECT p_mastery, last_updated FROM topic_mastery WHERE topic_id=?",
                       (topic_id,)).fetchone()
    if not row:
        return BKT_P_INIT
    p = row["p_mastery"]
    # BKT+Forget: apply time-decay toward the population prior for however
    # long it has been since this topic was last touched, rather than
    # assuming mastery is frozen between sessions (the standard BKT
    # assumption, and the one the "+Forget" literature specifically relaxes).
    last = row["last_updated"]
    if last:
        try:
            days = max(0.0, (datetime.now() - datetime.fromisoformat(last)).total_seconds() / 86400.0)
        except Exception:
            days = 0.0
        decay = 1.0 - math.exp(-BKT_P_FORGET_PER_DAY * days)
        p = p + (BKT_P_INIT - p) * decay
    return p

def set_mastery(conn, topic_id, val):
    conn.execute("""INSERT INTO topic_mastery (topic_id, p_mastery, last_updated) VALUES (?,?,?)
                     ON CONFLICT(topic_id) DO UPDATE SET
                        p_mastery=excluded.p_mastery, last_updated=excluded.last_updated""",
                 (topic_id, val, datetime.now().isoformat()))
    conn.commit()

def effective_credit(correct, hint_level):
    """How much a correct answer should count as evidence of unaided
    knowledge, graduated by how much scaffolding it took to get there.
    Level 3 (near-answer: two options eliminated + the governing citation
    shown) is deliberately steep -- getting it right after that is only
    weakly informative, much closer to a coin flip between what's left than
    to genuinely knowing the material."""
    if not correct:
        return 0.0
    return {0: 1.0, 1: 0.75, 2: 0.45, 3: 0.2}.get(hint_level, 1.0)

HEAVY_HINT_THRESHOLD = 2  # hint_level at/above this is excluded from IRT/PFA

# ---- which attempt rows are MEASUREMENT --------------------------------
# record_attempt documents the rule: a pretest answer is a sanctioned
# first-encounter guess (an expected miss, not evidence of non-mastery), a
# free-recall row is a rubric pass/fail with no option chosen, and a
# heavily-hinted answer is scaffolded rather than retrieved. Theta and BKT
# already skipped these; every OTHER reader of `attempts` (PFA, fragility,
# weakest items, clusters, skill retention, Thompson, item analysis, the
# dossier) had its own copy of the query with no such filter, so the same
# sanctioned guess that the estimator ignored still moved the mastery bar.
# One predicate, used everywhere, so the readers cannot drift apart again.
# `hint_level` is intentionally inside the predicate; a reader that
# accounts for hints itself (effective_credit, a hint-rate) uses the
# mode-only form.
MEASUREMENT_MODE_SQL = "(mode IS NULL OR mode NOT IN ('pretest','freerecall'))"
MEASUREMENT_ROW_SQL = (MEASUREMENT_MODE_SQL +
                       " AND (hint_level IS NULL OR hint_level < %d)" % HEAVY_HINT_THRESHOLD)

def measurement_rows(conn, where="", params=(), columns="*", order="id ASC", limit=None):
    """Attempt rows that count as measurement (see MEASUREMENT_ROW_SQL).
    `where` is an extra SQL condition ANDed onto the predicate."""
    sql = "SELECT %s FROM attempts WHERE %s" % (columns, MEASUREMENT_ROW_SQL)
    if where:
        sql += " AND (%s)" % where
    if order:
        sql += " ORDER BY " + order
    params = tuple(params)
    if limit is not None:
        sql += " LIMIT ?"
        params = params + (int(limit),)
    return _safe_query(conn, sql, params) or []

# ---- KT-IDEM: per-item guess/slip instead of one topic-wide pair ---------
# Pardos & Heffernan (2011) -- items vary in how easy they are to slip on or
# guess correctly, so a single global slip/guess for an entire topic is a
# coarse approximation. Difficulty-tiered slip/guess is the lightweight
# stand-in usable without per-item calibration data of our own.
_ITEM_SLIP_GUESS = {
    "easy":   (0.06, 0.32),
    "medium": (0.10, 0.25),
    "hard":   (0.16, 0.18),
}

def item_slip_guess(question):
    diff = (question or {}).get("difficulty", "medium")
    return _ITEM_SLIP_GUESS.get(diff, (BKT_P_SLIP, BKT_P_GUESS))

# ============================================================================
# DINA / G-DINA COGNITIVE DIAGNOSIS -- single-learner-valid skill-mastery
# classification, distinct from and complementary to BKT/PFA above.
# ============================================================================
# Junker & Sijtsma (2001, Applied Psychological Measurement 25:258-272);
# generalized as G-DINA by de la Torre (2011, Psychometrika 76:179-199).
#
# The population-scale calibration burden in the CDM literature exists only
# because the Q-matrix, slip, and guess are normally ALL unknown and fit from
# a large response matrix. Here they are authored (the Q-matrix below, and
# slip/guess reused directly from item_slip_guess -- the same KT-IDEM values
# BKT already uses), which leaves a pure per-person classification problem
# solvable in closed form from one learner's own responses alone:
#
#   eta_ij = 1 iff the learner has mastered EVERY skill item j requires
#   P(correct | alpha) = (1 - slip_j)^eta_ij * guess_j^(1 - eta_ij)
#
# This is a genuinely different question from what BKT/PFA answer. BKT/PFA
# track one mastery probability PER TOPIC, evolving over time (a dynamic
# HMM). DINA classifies a learner into one of 2^K joint skill-mastery
# profiles from a snapshot of recent responses (a static latent-class model)
# -- it does not model learning happening mid-sequence, which is why it is
# scored from RECENT attempts only (see max_recent below), not the full
# history BKT integrates over.
#
# Inference is scoped PER TOPIC rather than one global 2^(all skills)
# enumeration: skills in different topics are already treated as
# independent everywhere else in this app, and it keeps enumeration cheap
# (2^1=2 for an ordinary single-skill topic, 2^10=1024 for the one topic
# below with a real multi-skill breakdown) instead of computationally
# infeasible (2^27+ across the whole bank at once).

# ---------------------------------------------------------------------------
# PRECOMPUTED ENRICHMENT ARTIFACT
# ---------------------------------------------------------------------------
# Built by a separate offline pipeline (build_enrichment.py) and embedded
# here as compressed data. Loading it costs one zlib inflate and one JSON
# parse -- no torch, no transformers, no network, no API key, no model
# download, no first-run delay.
#
# The design point: the item bank is FIXED, so every expensive analysis over
# it can be done once at build time instead of repeatedly at runtime. That
# converts the app's most fragile dependency (a live ML model on the
# critical path of a study session, which failed in the field three separate
# ways) into an inert lookup table that cannot fail. It also removes the
# quality ceiling that runtime cost imposed -- build-time analysis can be
# arbitrarily expensive because the learner never waits for it.
#
# Everything here is AUTHORED analysis, not measurement. The app labels it
# as such wherever it is surfaced, and never lets it override a figure
# computed from the learner's own responses.
_ENRICHMENT = None

# ===========================================================================
# SPLASH AMBIENCE
# ===========================================================================
# Soothing audio for the startup screen, SYNTHESISED at runtime rather than
# shipped as an asset. The `wave` module is stdlib, so this adds no
# dependency, no binary blob in the repo, and nothing to license.
#
# Design constraints, in priority order:
#   1. It must NEVER block or break startup. Every step is wrapped; if
#      synthesis or playback fails for any reason the app proceeds in
#      silence and says nothing.
#   2. It must be instantly silenceable and REMEMBER that choice. Audio
#      that starts unbidden is a genuine hazard -- someone may open this in
#      an office, a library, or a meeting. The mute control is on the
#      splash itself, not buried in Settings, and the preference persists.
#   3. It must stop the moment the splash does. Music outliving its screen
#      is worse than no music.
#
# The sound itself is a slow drone built from a root and two harmonically
# related partials (a fifth and an octave), each detuned by a fraction of a
# hertz so they beat gently against one another. That beating is what makes
# a synthesised pad sound alive rather than like a test tone. A slow
# amplitude LFO breathes the whole thing, and the file is windowed at both
# ends so it loops without a click.

_AMBIENCE_PATH = None
_AMBIENCE_PROC = None
# Set by ambience_stop(), cleared by ambience_start(). Synthesis takes about
# a second on the warm thread, and a mute (or Skip) clicked inside that
# second used to be ignored: the worker went on to launch the player after
# the stop had already run. The flag is re-checked right before spawning.
_AMBIENCE_MUTED = False
# Whether the running player loops by itself. Only ffplay and winsound do;
# paplay/afplay/aplay play the file once, so a timer respawns them.
_AMBIENCE_LOOPS = False
_AMBIENCE_CMD = None

def _synthesise_ambience(path, seconds=24, rate=22050):
    """Write a soft looping ambient drone to `path` as 16-bit mono WAV."""
    import wave as _wave
    import struct as _struct

    n = int(seconds * rate)
    # A low, warm root with a fifth and an octave above it. Kept quiet and
    # low-passed by construction (pure sines have no harsh harmonics).
    partials = [
        (110.00, 0.55, 0.00),   # A2 root
        (110.37, 0.28, 1.10),   # detuned root -> slow beating
        (164.81, 0.22, 2.30),   # E3, a fifth up
        (220.00, 0.14, 0.50),   # A3, an octave up
        (329.63, 0.07, 3.10),   # E4, adds air without brightness
    ]
    frames = bytearray()
    for i in range(n):
        t = i / rate
        # Two slow LFOs at incommensurate rates, so the swell never
        # repeats audibly within the loop.
        lfo = (0.72
               + 0.18 * math.sin(2 * math.pi * 0.033 * t)
               + 0.10 * math.sin(2 * math.pi * 0.017 * t + 1.7))
        s = 0.0
        for freq, amp, phase in partials:
            s += amp * math.sin(2 * math.pi * freq * t + phase)
        s *= lfo / sum(p[1] for p in partials)
        # Equal-power-ish window at both ends so the loop point is silent
        # and therefore inaudible.
        edge = min(t, seconds - t)
        if edge < 2.5:
            s *= math.sin((edge / 2.5) * math.pi / 2) ** 2
        v = int(max(-1.0, min(1.0, s * 0.34)) * 32767)
        frames += _struct.pack("<h", v)

    with _wave.open(path, "wb") as f:
        f.setnchannels(1)
        f.setsampwidth(2)
        f.setframerate(rate)
        f.writeframes(bytes(frames))
    return path

# Players in preference order. ffplay first because it is the only
# command-line player here that loops by itself (`-loop 0`); paplay has no
# loop option at all (the old `--loop=999` made it exit on "unrecognized
# option" while we reported audio as running), and afplay/aplay play the
# file once and exit -- those are respawned by ambience_tick().
_AMBIENCE_PLAYERS = (
    (["ffplay", "-nodisp", "-autoexit", "-loglevel", "quiet", "-loop", "0"], True),
    (["paplay"], False),
    (["afplay"], False),
    (["aplay", "-q"], False),
)

def _spawn_ambience_player():
    """Launch the first available player on the synthesised file. Returns
    True if one started. Detached, output discarded, nothing on the console."""
    global _AMBIENCE_PROC, _AMBIENCE_LOOPS, _AMBIENCE_CMD
    import shutil as _sh
    import subprocess as _sp
    if _AMBIENCE_CMD is None:
        for cmd, loops in _AMBIENCE_PLAYERS:
            if _sh.which(cmd[0]):
                _AMBIENCE_CMD, _AMBIENCE_LOOPS = cmd, loops
                break
    if _AMBIENCE_CMD is None or _AMBIENCE_MUTED or not _AMBIENCE_PATH:
        return False
    _AMBIENCE_PROC = _sp.Popen(_AMBIENCE_CMD + [_AMBIENCE_PATH],
                               stdout=_sp.DEVNULL, stderr=_sp.DEVNULL,
                               stdin=_sp.DEVNULL)
    return True

def ambience_start():
    """Begin looping playback. Returns True if audio actually started."""
    global _AMBIENCE_PATH, _AMBIENCE_PROC, _AMBIENCE_MUTED
    _AMBIENCE_MUTED = False
    try:
        if _AMBIENCE_PATH is None or not os.path.exists(_AMBIENCE_PATH):
            import tempfile
            fd, p = tempfile.mkstemp(suffix=".wav", prefix="recursa_ambience_")
            os.close(fd)
            _synthesise_ambience(p)
            _AMBIENCE_PATH = p

        # A mute or Skip may have landed while the file was being written.
        if _AMBIENCE_MUTED:
            _discard_ambience_file()
            return False

        if platform.system() == "Windows":
            import winsound
            winsound.PlaySound(_AMBIENCE_PATH,
                               winsound.SND_FILENAME | winsound.SND_ASYNC | winsound.SND_LOOP)
            _AMBIENCE_PROC = "winsound"
            return True

        return _spawn_ambience_player()
    except Exception:
        pass
    return False

def ambience_tick():
    """Keep a non-looping player going. Called from the splash's own
    `after` loop, so it stops being called the moment the splash is gone;
    it is a no-op for players that loop by themselves."""
    global _AMBIENCE_PROC
    try:
        if (_AMBIENCE_MUTED or _AMBIENCE_LOOPS or _AMBIENCE_PROC is None
                or _AMBIENCE_PROC == "winsound" or not _AMBIENCE_PATH):
            return
        if _AMBIENCE_PROC.poll() is None:
            return
        # It finished the file: play it again. ambience_stop() sets the
        # muted flag first and terminates the process second, so a stop
        # racing this call cannot leave a fresh player behind.
        _spawn_ambience_player()
    except Exception:
        pass

def _discard_ambience_file():
    global _AMBIENCE_PATH
    try:
        if _AMBIENCE_PATH and os.path.exists(_AMBIENCE_PATH):
            os.unlink(_AMBIENCE_PATH)
    except Exception:
        pass
    _AMBIENCE_PATH = None

def ambience_stop():
    """Silence playback and clean up. Safe to call repeatedly."""
    global _AMBIENCE_PROC, _AMBIENCE_MUTED
    _AMBIENCE_MUTED = True
    try:
        if _AMBIENCE_PROC == "winsound":
            import winsound
            winsound.PlaySound(None, winsound.SND_PURGE)
        elif _AMBIENCE_PROC is not None:
            _AMBIENCE_PROC.terminate()
            # Escalate if the player ignores SIGTERM. A stubborn detached
            # audio process outliving the app is not hypothetical -- during
            # development, leaked players saturated a single-core machine
            # badly enough to wedge unrelated work. Terminate, wait briefly,
            # then kill.
            try:
                _AMBIENCE_PROC.wait(timeout=1.5)
            except Exception:
                try:
                    _AMBIENCE_PROC.kill()
                except Exception:
                    pass
    except Exception:
        pass
    _AMBIENCE_PROC = None
    _discard_ambience_file()


def enrichment():
    """Lazy-load the precomputed artifact. Returns {} if absent or corrupt,
    so every consumer degrades to the app's prior behaviour rather than
    failing -- the artifact is an enhancement, never a requirement."""
    global _ENRICHMENT
    if _ENRICHMENT is not None:
        return _ENRICHMENT
    try:
        packed = "".join(_ENRICHMENT_B64.split())
        _ENRICHMENT = json.loads(zlib.decompress(base64.b64decode(packed)).decode("utf-8"))
    except Exception:
        _ENRICHMENT = {}
    return _ENRICHMENT

# ---- Precomputed embeddings: runtime side, pure stdlib -------------------
# Loading is one base64 decode into a bytes object; similarity is an integer
# dot product. No numpy, no torch, no model. For a 389-document corpus this
# is fast enough that the whole thing is imperceptible.
_EMB_CACHE = None

def embeddings_available():
    return _load_embeddings() is not None

def _load_embeddings():
    """Returns (id_list, index_map, raw_bytes, dims) or None."""
    global _EMB_CACHE
    if _EMB_CACHE is not None:
        return _EMB_CACHE or None
    e = enrichment().get("embeddings")
    if not e:
        _EMB_CACHE = False
        return None
    try:
        raw = base64.b64decode(e["int8"])
        ids = e["ids"]
        dims = int(e["dims"])
        if len(raw) != len(ids) * dims:
            _EMB_CACHE = False
            return None
        _EMB_CACHE = (ids, {k: i for i, k in enumerate(ids)}, raw, dims)
    except Exception:
        _EMB_CACHE = False
        return None
    return _EMB_CACHE

def _emb_vec(raw, dims, idx):
    off = idx * dims
    return [(b - 256 if b > 127 else b) for b in raw[off:off + dims]]

def embedding_similarity(key_a, key_b):
    """Cosine similarity between two corpus keys ('q:q94', 'f:f45', 'n:t9').
    Vectors were unit-normalised before quantization, so a plain dot product
    over the int8 values is proportional to cosine."""
    data = _load_embeddings()
    if not data:
        return None
    ids, index, raw, dims = data
    ia, ib = index.get(key_a), index.get(key_b)
    if ia is None or ib is None:
        return None
    va, vb = _emb_vec(raw, dims, ia), _emb_vec(raw, dims, ib)
    dot = sum(x * y for x, y in zip(va, vb))
    return dot / (127.0 * 127.0)

def embedding_neighbors(key, limit=5, kinds=None):
    """Nearest corpus documents to `key`, optionally restricted by kind
    ('q' questions, 'f' flashcards, 'n' topic notes)."""
    data = _load_embeddings()
    if not data:
        return []
    ids, index, raw, dims = data
    i = index.get(key)
    if i is None:
        return []
    v = _emb_vec(raw, dims, i)
    out = []
    for j, other in enumerate(ids):
        if j == i:
            continue
        if kinds and other.split(":", 1)[0] not in kinds:
            continue
        w = _emb_vec(raw, dims, j)
        out.append((sum(a * b for a, b in zip(v, w)) / (127.0 * 127.0), other))
    out.sort(reverse=True)
    return out[:limit]

def cluster_missed_offline(conn, max_recent=60, min_size=2, sim_threshold=0.45,
                           max_clusters=8):
    """Failure Explorer clustering with NO model and NO API call.

    Greedy agglomeration over the precomputed vectors: seed a cluster with
    the most-missed item, absorb everything above the similarity threshold,
    repeat. Simpler than the embedding-model path it replaces, but it runs
    everywhere, instantly, and on the same corpus the model path was
    clustering anyway."""
    if not embeddings_available():
        return None
    rows = conn.execute("""SELECT question_id, COUNT(*) c FROM attempts
                            WHERE correct=0 AND question_id NOT LIKE 'gen-%'
                              AND """ + MEASUREMENT_MODE_SQL + """
                            GROUP BY question_id ORDER BY c DESC LIMIT ?""",
                        (max_recent,)).fetchall()
    pool = [r["question_id"] for r in rows if r["question_id"] in QUIZ_BANK]
    clusters, used = [], set()
    for seed in pool:
        if seed in used:
            continue
        members = [seed]
        for other in pool:
            if other in used or other == seed:
                continue
            sim = embedding_similarity("q:" + seed, "q:" + other)
            if sim is not None and sim >= sim_threshold:
                members.append(other)
        if len(members) >= min_size:
            used.update(members)
            clusters.append({"members": members, "centroid": None,
                             "rep_id": seed, "label": None})
        if len(clusters) >= max_clusters:
            break
    return clusters

def enriched_misconception(question_id, chosen_idx=None):
    """The authored diagnosis for a specific wrong answer, if one exists."""
    m = enrichment().get("misconceptions", {}).get(question_id)
    if not m:
        return None
    d = m.get("distractors", {})
    return {"concept": m.get("concept"),
            "diagnosis": d.get(str(chosen_idx)) or d.get("generic")}

def enriched_confusion_partner(question_id):
    """The item most mistakable for this one, for contrast drilling. Serving
    two confusable items in sequence trains the discrimination directly,
    which serving either alone cannot do."""
    for pair in enrichment().get("confusion_pairs", []):
        if pair.get("a") == question_id:
            return pair.get("b"), pair.get("why")
        if pair.get("b") == question_id:
            return pair.get("a"), pair.get("why")
    return None, None

def enriched_difficulty_prior(question_id, fallback):
    v = enrichment().get("difficulty_priors", {}).get(question_id)
    return float(v) if isinstance(v, (int, float)) else fallback

SKILLS = {}    # skill_id -> {"label": str, "topic": topic_id}
Q_MATRIX = {}  # question_id -> [skill_id, ...] (the skills that item requires)

# Default: one skill per topic. This is an honest, immediately-functional
# degenerate case of DINA (a single-skill Q-matrix row makes the AND-gate
# trivial, so it reduces to a straightforward Bayesian mastered/not-mastered
# classifier per topic) -- not a claim that every topic has been broken into
# genuine sub-skills. It is deliberately NOT the same computation as BKT even
# in this degenerate case: DINA here is a static snapshot classification
# with an authored slip/guess likelihood, while BKT is a dynamic HMM with a
# learn-transition probability, so the two numbers can and do disagree, and
# that disagreement is itself informative the same way the BKT/PFA
# disagreement already tracked elsewhere is.
for _tid in TOPICS:
    if _tid != "t17":
        SKILLS[_tid] = {"label": TOPICS[_tid]["short"], "topic": _tid}
for _qid, _q in QUIZ_BANK.items():
    if _q["topic"] != "t17":
        Q_MATRIX[_qid] = [_q["topic"]]

# Overlay the precomputed multi-skill decompositions. This is what lifts
# cognitive diagnosis from a single topic to every topic the offline
# pipeline has decomposed -- the app's weakest layer, fixed with data
# rather than code. Topics the artifact does not cover keep their
# single-skill default and behave exactly as before.
_ENR = enrichment()
if _ENR:
    for _sid, _meta in _ENR.get("skills", {}).items():
        SKILLS[_sid] = {"label": _meta["label"], "topic": _meta["topic"]}
    _enriched_topics = {m["topic"] for m in _ENR.get("skills", {}).values()}
    # A decomposed topic must drop its old catch-all single skill, or the
    # topic would carry both the coarse skill and its own refinements and
    # double-count evidence in the DINA posterior.
    for _tid in _enriched_topics:
        SKILLS.pop(_tid, None)
    for _qid, _sk in _ENR.get("q_matrix", {}).items():
        Q_MATRIX[_qid] = list(_sk)

# Escrow & Trust (t17) gets a genuine multi-skill breakdown instead of the
# singleton default, because it demonstrably contains distinguishable
# sub-facts rather than one undifferentiated idea -- confirmed directly
# against the bank's own 13 questions, not asserted: commingling/fund
# separation, record retention, disputed-deposit procedure, interest
# disposition, shortage correction, three-way reconciliation, pooled
# sub-ledger accounts, NSF checks, REC audit scope, and the narrow
# short-term-rental credit-card exception are each tested by their own
# question(s) and are each things a learner could know independently of the
# others. This is the topic where the conjunctive/joint-profile benefit of
# DINA over a flat per-topic score is real and checkable, not aspirational.
T17_SKILLS = {
    "t17_commingling":   "Commingling / fund separation",
    "t17_retention":     "Trust-record retention & consequences",
    "t17_disputed":      "Disputed deposit procedure",
    "t17_interest":      "Trust account interest disposition",
    "t17_shortage":      "Bookkeeping shortage correction",
    "t17_reconciliation": "Three-way reconciliation",
    "t17_pooled":        "Pooled accounts with sub-ledgers",
    "t17_nsf":           "NSF check handling",
    "t17_audit":         "REC audit scope",
    "t17_creditcard":    "Credit-card escrow exception",
}
for _sid, _label in T17_SKILLS.items():
    SKILLS[_sid] = {"label": _label, "topic": "t17"}

T17_Q_SKILLS = {
    "q173": ["t17_commingling"], "q175": ["t17_commingling"], "q177": ["t17_commingling"],
    "q174": ["t17_retention"], "q178": ["t17_retention"],
    "q176": ["t17_disputed"],
    "q179": ["t17_interest"],
    "q180": ["t17_shortage"],
    "q272": ["t17_reconciliation"],
    "q273": ["t17_pooled"],
    "q274": ["t17_nsf"],
    "q275": ["t17_audit"],
    "q294": ["t17_creditcard"],
}
Q_MATRIX.update(T17_Q_SKILLS)

def topic_skill_ids(topic_id):
    """All skill ids belonging to a topic, in a stable order (dict/set
    iteration order is not guaranteed stable across runs without sorting)."""
    return sorted(sid for sid, s in SKILLS.items() if s["topic"] == topic_id)

def _dina_response_prob(alpha, item_skills, skill_index, slip, guess):
    """alpha: tuple of 0/1, one per skill in this topic, same order as
    skill_index. Returns P(correct | alpha) under the DINA conjunctive
    (AND-gate) response function."""
    eta = 1
    for sid in item_skills:
        idx = skill_index.get(sid)
        if idx is None or alpha[idx] == 0:
            eta = 0
            break
    return (1.0 - slip) if eta == 1 else guess

# Posterior cache. Item selection asks for the class posterior of every
# multi-skill topic on EVERY call, and with 11 decomposed topics that was
# measured at 84ms per selection -- perceptible lag between questions, and
# entirely wasted work, because the posterior can only change when a new
# attempt is recorded for that topic. Keyed on the topic's attempt count and
# newest row id, so it invalidates exactly when the evidence changes and
# never serves a stale distribution.
_DINA_CACHE = {}

def _dina_cache_key(conn, topic_id):
    row = conn.execute("""SELECT COUNT(*) n, COALESCE(MAX(id), 0) m FROM attempts
                           WHERE topic_id=? AND question_id NOT LIKE 'gen-%'""",
                       (topic_id,)).fetchone()
    return (topic_id, row["n"], row["m"])

def _dina_class_posterior(conn, topic_id, max_recent=40):
    try:
        key = _dina_cache_key(conn, topic_id)
        hit = _DINA_CACHE.get(topic_id)
        if hit and hit[0] == key:
            return hit[1]
    except Exception:
        key = None
    result = _dina_class_posterior_uncached(conn, topic_id, max_recent)
    if key is not None:
        _DINA_CACHE[topic_id] = (key, result)
    return result

# ---------------------------------------------------------------------------
# OBSERVATION WEIGHT: how much one answer should count
# ---------------------------------------------------------------------------
# Every response was weighted 1.0 in the DINA posterior: a guess answered in
# four seconds with "no idea" confidence moved the mastery estimate exactly
# as far as a considered answer with "certain" confidence, and an answer
# from three months ago counted the same as one from this morning. Three
# well-established signals were being recorded and ignored.
#
#   RESPONSE TIME  (van der Linden 2007): a wrong answer far faster than the
#   learner's own median is more likely a guess than a held belief, and a
#   correct answer far slower than target is effortful retrieval rather
#   than fluent knowledge. Both are weaker evidence than a normal-paced
#   answer -- in opposite directions.
#
#   CONFIDENCE  (metacognitive KT): high-confidence-wrong is the strongest
#   evidence there is of a held misconception, and should move the
#   estimate MORE. Low-confidence-right is consistent with a lucky guess and
#   should move it LESS.
#
#   RECENCY: evidence decays. A half-life of 14 days means last month's
#   answers still count, but this week's count more.
#
# Weights are bounded so no single answer can dominate; this reshapes the
# likelihood, it does not replace it.

OBS_HALF_LIFE_DAYS = 14.0
DINA_SEQ_DECAY = 0.965          # per-position decay (multi-skill joint path only); the 20th-most-recent answer ~ half weight
# Per-skill learning-transition probability for the single-skill forward
# pass in _dina_class_posterior_uncached: the chance the skill moves from
# unmastered to mastered after any one observation. Same value BKT uses
# per topic; here it is applied per SKILL, on that skill's own responses.
DINA_SKILL_P_TRANSIT = BKT_P_TRANSIT

# ---------------------------------------------------------------------------
# WITHIN-PERSON LOGNORMAL RESPONSE TIME  (van der Linden 2006/2007)
# ---------------------------------------------------------------------------
# The first version flagged "fast" as < 25% of the median: a fixed ratio
# that does not know how variable THIS learner's pace is. The research
# note is precise on what survives at n=1: item time-intensity parameters
# are population-based and unidentified, but the PERSON's speed and a
# within-person lognormal on log-RT are estimable from one learner's own
# history. So the aberrance test becomes a z-score on that learner's own
# log-RT distribution rather than a magic ratio. A learner who is always
# fast is no longer penalised for being fast; a learner who is normally
# slow and suddenly answers in four seconds is.

def personal_rt_model(times):
    """Fit log-RT ~ Normal(mu, sigma) to one learner's own times.

    Returns (mu, sigma) in log-seconds, or None if there is too little
    history to say anything. Sigma is floored so a learner with three
    near-identical times does not get a degenerate model that flags
    everything."""
    ts = [t for t in (times or []) if t and t > 0]
    if len(ts) < 5:
        return None
    logs = [math.log(t) for t in ts]
    mu = sum(logs) / len(logs)
    var = sum((x - mu) ** 2 for x in logs) / max(1, len(logs) - 1)
    return (mu, max(0.25, math.sqrt(var)))

def rt_zscore(time_taken, rt_model):
    if not rt_model or not time_taken or time_taken <= 0:
        return 0.0
    mu, sigma = rt_model
    return (math.log(time_taken) - mu) / sigma

def observation_weight(correct, time_taken=None, confidence=None,
                       age_days=None, target_secs=None, median_secs=None,
                       rt_model=None):
    w = 1.0
    # ---- response time: z-score on the learner's OWN log-RT ----
    if time_taken is not None and time_taken > 0:
        if rt_model:
            z = rt_zscore(time_taken, rt_model)
            if not correct and z < -1.5:
                w *= 0.55      # aberrantly fast for THIS person and wrong: a guess
            elif correct and z < -1.5:
                w *= 0.85      # aberrantly fast and right: fluent or recognised
            elif correct and z > 1.5:
                w *= 0.75      # aberrantly slow and right: effortful, not fluent
        else:
            # fallback before enough history exists for a personal model
            med = median_secs or target_secs or 60.0
            if not correct and time_taken < 0.25 * med:
                w *= 0.55
            elif correct and time_taken < 0.25 * med:
                w *= 0.85
            elif correct and target_secs and time_taken > 2.0 * target_secs:
                w *= 0.75
    # ---- confidence (1 = guessing, 2 = somewhat, 3 = confident) ----
    if confidence is not None:
        try:
            cf = int(confidence)
        except Exception:
            cf = None
        if cf is not None:
            if not correct and cf >= 3:
                w *= 1.45      # confidently wrong: a held wrong rule
            elif correct and cf <= 1:
                w *= 0.6       # right but guessing: weak evidence of mastery
            elif not correct and cf <= 1:
                w *= 0.8       # wrong and knew it: less diagnostic
    # ---- recency ----
    if age_days is not None and age_days > 0:
        w *= 0.5 ** (age_days / OBS_HALF_LIFE_DAYS)
    return max(0.15, min(1.6, w))

def _prereq_edges_within(conn, skill_ids, skill_index):
    """(dependent_idx, prerequisite_idx) pairs among one topic's skills.

    Read from the evidence graph and cached per skill set because the
    posterior is recomputed on every answer. Only AUTHORED or VERIFIED
    edges are honoured here: an edge that infer_prerequisites derived from
    this learner's own posterior is the same datum the posterior is about
    to be computed from, and feeding it back as a prior is a rich-get-
    richer loop (every low skill gets lower on each restart). Inferred
    edges stay in the graph for display (upstream_bottleneck) but never
    enter the likelihood."""
    key = tuple(skill_ids)
    hit = _PREREQ_EDGE_CACHE.get(key)
    if hit is not None:
        return hit
    out = []
    try:
        # Edge direction: src is the PREREQUISITE, dst is what depends on it.
        rows = conn.execute(
            """SELECT src_id, dst_id FROM graph_edges
                WHERE edge_type='prerequisite_of'
                  AND src_type='skill' AND dst_type='skill'
                  AND (provenance IS NULL OR provenance != 'inferred'
                       OR COALESCE(verified, 0) = 1)"""
        ).fetchall()
        for r in rows:
            pre, dep = r["src_id"], r["dst_id"]
            if dep in skill_index and pre in skill_index and dep != pre:
                out.append((skill_index[dep], skill_index[pre]))
    except Exception:
        out = []
    _PREREQ_EDGE_CACHE[key] = out
    return out

_PREREQ_EDGE_CACHE = {}

def _dina_class_posterior_uncached(conn, topic_id, max_recent=40):
    """Shared internal computation: the raw posterior over all 2^K classes,
    plus the skill index and item-level evidence used. Both
    dina_topic_posterior (the UI-facing summary) and dina_item_information
    (CD-CAT item selection, below) need the FULL class array, not just the
    marginal per-skill mastery a summary can get away with -- PWKL selection
    specifically needs to know how probability mass is spread across pairs
    of classes, which marginals alone cannot reconstruct. Returns None when
    there is no scoreable data yet."""
    skill_ids = topic_skill_ids(topic_id)
    K = len(skill_ids)
    if K == 0:
        return None
    skill_index = {sid: i for i, sid in enumerate(skill_ids)}
    rows = measurement_rows(conn, "topic_id=? AND question_id NOT LIKE 'gen-%'", (topic_id,),
                            columns="question_id, correct, time_taken, confidence, timestamp",
                            order="id DESC", limit=max_recent)
    scored = [r for r in rows if Q_MATRIX.get(r["question_id"])]
    # Uncalibrated candidates are practice, not measurement (see the
    # calibration ladder). model_feed_filter lives later in the file; look
    # it up lazily so this module has no load-order dependency on it.
    _mff = globals().get("model_feed_filter")
    if _mff:
        try:
            scored = _mff(conn, scored)
        except Exception:
            pass
    # The learner's own median pace on this topic, so "fast" is relative to
    # them rather than to a fixed number.
    _times = sorted(r["time_taken"] for r in scored
                    if r["time_taken"] and r["time_taken"] > 0)
    _median = _times[len(_times) // 2] if _times else None
    _rt_model = personal_rt_model(_times)
    _now = datetime.now()
    if not scored:
        return None

    n_classes = 1 << K
    # Evidence-weighted observations, most-recent-first, plus how many
    # observations actually touched each skill. The per-skill count is
    # part of the result: a skill with n=0 is a PRIOR, not a measurement,
    # and consumers must be able to tell the two apart.
    obs = []
    n_by_skill = {sid: 0 for sid in skill_ids}
    for r in scored:
        qid = r["question_id"]
        item_skills = Q_MATRIX[qid]
        q = QUIZ_BANK.get(qid)
        slip, guess = item_slip_guess(q)
        x = 1 if r["correct"] else 0
        try:
            age = (_now - datetime.fromisoformat(r["timestamp"])).total_seconds() / 86400.0
        except Exception:
            age = None
        w = observation_weight(bool(r["correct"]), r["time_taken"], r["confidence"],
                               age, target_secs=globals().get("PACE_TARGET_SECONDS", 130),
                               median_secs=_median, rt_model=_rt_model)
        obs.append((item_skills, slip, guess, x, w))
        for sid in item_skills:
            if sid in n_by_skill:
                n_by_skill[sid] += 1

    # STRUCTURED PRIOR. A flat prior over 2^K profiles treats "has mastered
    # the dependent skill but not the one it rests on" as exactly as likely
    # as any other profile. The prerequisite graph says it is not. Following
    # the attribute-hierarchy / HO-DINA idea (Leighton, Gierl & Hunka 2004;
    # de la Torre & Douglas 2004), profiles that violate an AUTHORED
    # prerequisite edge are down-weighted -- not forbidden, because an
    # authored edge can still be wrong, and a hard zero would make a single
    # bad edge unrecoverable. This shrinks the hypothesis space using
    # STRUCTURE rather than population data, which is the only lever that
    # exists at n=1. The penalty is deliberately mild.
    log_post = [0.0] * n_classes
    try:
        _edges = _prereq_edges_within(conn, skill_ids, skill_index)
    except Exception:
        _edges = []
    if _edges:
        for c in range(n_classes):
            alpha = tuple((c >> i) & 1 for i in range(K))
            viol = sum(1 for (dep, pre) in _edges if alpha[dep] and not alpha[pre])
            if viol:
                log_post[c] -= 0.9 * viol

    conjunctive = any(len(item_skills) > 1 for (item_skills, _s, _g, _x, _w) in obs)
    if not conjunctive:
        # DINA assumes ONE fixed knowledge state produced every answer. A
        # learner who was wrong six times and then right six times is not
        # in one state -- they learned -- and a static latent-class model
        # concludes "six misses outvote six hits" long after the learner
        # has demonstrated the skill. Every item in the bank requires
        # exactly one skill, so the DINA likelihood for each skill is a
        # mastered/not-mastered Bernoulli with that item's KT-IDEM
        # slip/guess -- and allowing one unmastered->mastered transition
        # per observation (HMM-DINA, Chen, Culpepper, Wang & Douglas 2018;
        # identical to the BKT forward recursion of Corbett & Anderson
        # 1995 for single-attribute items) is exactly identifiable from one
        # learner's own responses with no new parameters. The recursion runs
        # oldest-first over each skill's own responses; the observation
        # weight tempers each likelihood term rather than replacing it.
        marg = {sid: 0.5 for sid in skill_ids}      # flat prior, as before
        for (item_skills, slip, guess, x, w) in reversed(obs):    # oldest first
            sid = item_skills[0]
            if sid not in marg:
                continue
            p = marg[sid]
            lik1 = ((1.0 - slip) if x else slip) ** w      # mastered
            lik0 = (guess if x else (1.0 - guess)) ** w    # not mastered
            denom = p * lik1 + (1.0 - p) * lik0
            if denom > 0:
                p = p * lik1 / denom
            p = p + (1.0 - p) * DINA_SKILL_P_TRANSIT
            marg[sid] = min(max(p, 1e-6), 1 - 1e-6)
        # The joint class array is what CD-CAT item selection reads; with
        # single-skill items the skills are conditionally independent given
        # the responses, so the joint is the product of the marginals, with
        # the structural prior applied on top.
        for c in range(n_classes):
            for sid, idx in skill_index.items():
                mv = marg[sid]
                log_post[c] += math.log(mv) if (c >> idx) & 1 else math.log(1.0 - mv)
    else:
        # Genuinely conjunctive items (none authored today): full joint
        # enumeration. This static model cannot represent learning, so
        # evidence decays by POSITION in the sequence -- the most recent
        # answer counts fully, the twentieth-most-recent about half -- which
        # at least makes the posterior lean toward the learner's CURRENT
        # state rather than the average of every state passed through.
        for _pos, (item_skills, slip, guess, x, w) in enumerate(obs):   # most-recent-first
            w *= DINA_SEQ_DECAY ** _pos
            for c in range(n_classes):
                alpha = tuple((c >> i) & 1 for i in range(K))
                pc = _dina_response_prob(alpha, item_skills, skill_index, slip, guess)
                pc = min(max(pc, 1e-6), 1 - 1e-6)
                log_post[c] += w * (x * math.log(pc) + (1 - x) * math.log(1 - pc))

    m = max(log_post)
    exps = [math.exp(v - m) for v in log_post]
    total = sum(exps)
    post = [e / total for e in exps]
    return {"skill_ids": skill_ids, "skill_index": skill_index, "K": K,
            "n_classes": n_classes, "post": post, "n": len(scored),
            "skill_n": n_by_skill}

def dina_topic_posterior(conn, topic_id, max_recent=40):
    """Closed-form MAP/EAP posterior over the 2^K joint skill-mastery
    classes for this topic, from this learner's own recent responses only.
    Returns None when there is no data yet, rather than a manufactured
    50/50 guess. Within a topic that HAS data, a skill nobody has been
    tested on still carries the 0.5 prior in `skill_mastery`; `skill_n`
    says which those are (n=0) and `map_profile` reports None for them, so
    "never assessed" cannot be rendered as "not mastered"."""
    raw = _dina_class_posterior(conn, topic_id, max_recent)
    if raw is None:
        return None
    skill_ids, skill_index, K, n_classes, post = (
        raw["skill_ids"], raw["skill_index"], raw["K"], raw["n_classes"], raw["post"])
    skill_n = raw.get("skill_n") or {sid: 0 for sid in skill_ids}
    skill_mastery = {sid: sum(post[c] for c in range(n_classes) if (c >> idx) & 1)
                     for sid, idx in skill_index.items()}
    map_class = max(range(n_classes), key=lambda c: post[c])
    map_alpha = tuple((map_class >> i) & 1 for i in range(K))
    return {
        "skill_ids": skill_ids,
        "skill_mastery": skill_mastery,       # EAP marginal per skill, 0-1
        "map_profile": {sid: (map_alpha[skill_index[sid]] if skill_n.get(sid) else None)
                        for sid in skill_ids},
        "skill_n": skill_n,                   # observations behind each skill; 0 = prior only
        "n": raw["n"],
        "map_confidence": post[map_class],    # posterior mass on the single most likely joint profile
    }

def _bernoulli_kl(p, q):
    p = min(max(p, 1e-6), 1 - 1e-6)
    q = min(max(q, 1e-6), 1 - 1e-6)
    return p * math.log(p / q) + (1 - p) * math.log((1 - p) / (1 - q))

def dina_item_information(conn, topic_id, question_id, raw=None):
    """CD-CAT diagnostic item selection: Posterior-Weighted Kullback-Leibler
    information (Cheng 2009, Psychometrika 74:619-632) -- how much this item
    would narrow down WHICH joint skill-mastery class the learner is in,
    given the current posterior. Items that best discriminate between the
    classes currently holding the most posterior mass score highest.

    Returns 0.0 for single-skill topics or items outside a multi-skill
    Q-matrix: with only one skill in play there is no separate diagnostic
    discrimination to gain beyond what IRT information-based selection
    already provides, so this deliberately contributes nothing there rather
    than duplicating that signal under a different name.

    `raw` lets a caller ranking many candidate items for the SAME topic
    compute the class posterior once and reuse it, instead of recomputing
    an identical Bayesian update per candidate.

    PERFORMANCE NOTE, kept because it explains why the code below branches:
    a naive full pairwise double loop over all class pairs was benchmarked
    at ~700ms per item at K=10 (1024 classes) -- an unacceptable UI-thread
    delay if called live during item selection, the exact class of freeze
    bug this app has hit and fixed more than once. Every item currently
    authored in the Q-matrix requires exactly ONE skill (no genuine
    conjunction exists yet), which means _dina_response_prob only takes 2
    distinct values across all 2^K classes -- so the O(n_classes^2) pairwise
    sum collapses to a closed-form O(1) expression using the marginal mass
    already available from skill_mastery, verified to match the brute-force
    double loop to float precision before being trusted here. Any item that
    later requires 2+ skills conjunctively falls back to the general (slow)
    path automatically, correct but not fast -- that combination doesn't
    exist in the bank today."""
    skill_ids = topic_skill_ids(topic_id)
    if len(skill_ids) < 2:
        return 0.0
    item_skills = Q_MATRIX.get(question_id)
    q = QUIZ_BANK.get(question_id)
    if not item_skills or not q:
        return 0.0
    if raw is None:
        raw = _dina_class_posterior(conn, topic_id)
    if raw is None:
        return 0.0
    skill_index, K, n_classes, post = raw["skill_index"], raw["K"], raw["n_classes"], raw["post"]
    slip, guess = item_slip_guess(q)

    if len(item_skills) == 1:
        idx = skill_index.get(item_skills[0])
        if idx is None:
            return 0.0
        mass1 = sum(post[c] for c in range(n_classes) if (c >> idx) & 1)
        mass0 = 1.0 - mass1
        return mass1 * mass0 * (_bernoulli_kl(1 - slip, guess) + _bernoulli_kl(guess, 1 - slip))

    # General (slower) path for a genuinely multi-skill conjunctive item.
    p_by_class = []
    for c in range(n_classes):
        alpha = tuple((c >> i) & 1 for i in range(K))
        p_by_class.append(_dina_response_prob(alpha, item_skills, skill_index, slip, guess))
    active = [c for c in range(n_classes) if post[c] > 1e-6]
    total = 0.0
    for a in active:
        pa = post[a]
        for b in active:
            if b == a:
                continue
            total += pa * post[b] * _bernoulli_kl(p_by_class[a], p_by_class[b])
    return total

def bkt_update(conn, topic_id, correct, hint_level, question=None, rushing=False,
               fractional_credit=None):
    """fractional_credit, when given, OVERRIDES the hint-based credit with a
    continuous 0-1 signal from a non-multiple-choice source (currently: NLI
    entailment score on a free-recall answer). This reuses the existing
    credit-blending slot rather than adding new machinery: `credit` already
    means "how much of a correct observation should this count as" -- hint
    level was simply the first source that needed a fractional value.

    This is a soft blend of the correct/incorrect emission probabilities,
    not a formally re-derived continuous-observation HMM (the BKT literature
    on that -- 'fuzzy BKT' -- is a real but narrow research corner, not
    something to invent informally here). Treat it as a defensible
    approximation: a 0.82 entailment score nudges mastery in between where a
    clean pass and a clean miss would land, weighted by how close to either
    extreme it is."""
    p_prev = get_mastery(conn, topic_id)
    if fractional_credit is not None:
        credit = max(0.0, min(1.0, fractional_credit))
    else:
        credit = effective_credit(correct, hint_level)
    # Locus D evidence discount: a response to an item that answers
    # inconsistently against itself is weak evidence about the LEARNER and
    # strong evidence about the ITEM. Shrinking credit toward the neutral
    # 0.5 point pulls the update toward "this told us little" rather than
    # letting an ambiguous question move mastery as much as a clean one.
    if question is not None and conn is not None:
        try:
            ew = item_evidence_weight(conn, question.get("id"))
            if ew < 1.0:
                credit = 0.5 + (credit - 0.5) * ew
        except Exception:
            pass
    slip, guess = item_slip_guess(question) if question else (BKT_P_SLIP, BKT_P_GUESS)
    if rushing:
        # Contextual slip (Baker, Corbett & Aleven 2008): a wrong answer
        # produced during a detected rushing episode is more likely a slip
        # than a genuine knowledge gap, so it should move mastery down less.
        slip = min(0.45, slip * 2.2)

    denom_c = p_prev * (1 - slip) + (1 - p_prev) * guess
    p_obs_correct = (p_prev * (1 - slip) / denom_c) if denom_c > 0 else p_prev
    denom_i = p_prev * slip + (1 - p_prev) * (1 - guess)
    p_obs_incorrect = (p_prev * slip / denom_i) if denom_i > 0 else p_prev
    p_obs = credit * p_obs_correct + (1 - credit) * p_obs_incorrect
    p_new = p_obs + (1 - p_obs) * BKT_P_TRANSIT
    p_new = max(0.01, min(0.99, p_new))
    set_mastery(conn, topic_id, p_new)
    return p_new

# ---- Performance Factor Analysis (PFA) -- a second, independent read -----
# Pavlik, Cen & Koedinger (2009). Rather than a single latent binary
# mastery state (BKT), PFA fits mastery as a smooth logistic function of how
# many times the skill has been seen right vs. wrong:
#     logit p = beta + gamma * (# prior successes) + rho * (# prior failures)
# Fitting gamma/rho/beta per topic via logistic regression on our own small
# per-topic n would overfit badly (a handful of dozens of points for a
# three-parameter model) -- exactly the overfitting risk the research
# flagged for deep KT at this data scale, just smaller in degree. Instead
# this uses fixed coefficients in the range the original PFA paper reports
# as typical, which keeps PFA meaningfully independent of BKT (different
# functional form, different failure mode) without inventing precision the
# data doesn't support.
PFA_BETA = 0.0
PFA_GAMMA = 0.32   # reward per prior success
PFA_RHO = -0.62    # penalty per prior failure
PFA_RECENCY_HALFLIFE = 6   # attempts; matches topic_fragility's halflife_attempts

def pfa_mastery(conn, topic_id):
    # Same exclusion as ability_with_se: a heavily-hinted correct answer is
    # not a clean "success" for PFA's raw success/failure count, for the
    # same reason it isn't full evidence for IRT -- keeping all three
    # estimators (BKT via effective_credit, IRT, PFA) consistent about what
    # heavy scaffolding is worth.
    rows = measurement_rows(conn, "topic_id=?", (topic_id,), columns="correct")
    if not rows:
        return 0.5, 0
    # Recency-weighted counts (same half-life topic_fragility uses), so the
    # logit is bounded by ~1/(1 - 0.5^(1/h)) effective observations instead
    # of growing without limit: raw lifetime counts made PFA a step function
    # of lifetime accuracy that no later learning could move.
    n = len(rows)
    succ = fail = 0.0
    for i, r in enumerate(rows):
        w = 0.5 ** ((n - 1 - i) / PFA_RECENCY_HALFLIFE)
        if r["correct"]:
            succ += w
        else:
            fail += w
    logit = PFA_BETA + PFA_GAMMA * succ + PFA_RHO * fail
    logit = max(-30.0, min(30.0, logit))
    return 1.0 / (1.0 + math.exp(-logit)), n

# n at which BKT's structured prior and PFA's larger-sample count-based
# estimate are treated as equally trustworthy. Below this, BKT's forgetting-
# aware posterior leads (it converges fast and behaves sensibly on sparse
# data); above it, PFA's estimate -- built directly from the accumulated
# success/failure counts -- gets more say, since it has more evidence behind
# it. This replaces a flat 50/50 average with a weighting that at least
# tracks something real (how much data exists), rather than a static blend
# or an invented confidence interval neither model actually produces: BKT's
# output already IS a probability rather than a point estimate needing a
# separate CI, and PFA here uses fixed literature-typical coefficients
# rather than ones fit to this user's data, so there is no sampling
# variance to compute a standard error from.
PFA_CROSSOVER_N = 20

def blended_mastery(conn, topic_id):
    """BKT and PFA fail differently (one is a latent on/off state with
    forgetting, the other a smooth success/failure count model with no
    forgetting), so combining them is more robust than trusting either
    alone -- and a large disagreement between them is itself informative."""
    bkt = get_mastery(conn, topic_id)
    pfa, n = pfa_mastery(conn, topic_id)
    if n == 0:
        return bkt, bkt, pfa, 0.0
    # w_pfa: 0 at n=0 (trust BKT's structured prior), rising to an even
    # split at n=PFA_CROSSOVER_N and capped there. BKT is the only one of
    # the two with forgetting and recency, so it must keep at least half
    # the weight however long the history grows; letting PFA take over
    # entirely past n=40 erased a demonstrated recovery on a well-practised
    # topic from every mastery number the learner sees.
    w_pfa = max(0.0, min(0.5, 0.5 * (n / PFA_CROSSOVER_N)))
    blend = (1 - w_pfa) * bkt + w_pfa * pfa
    disagreement = abs(bkt - pfa)
    return blend, bkt, pfa, disagreement



# ============================================================================
# FRAGILITY / ERROR LOG / RECORDING
# ============================================================================

def update_error_log(conn, question_id, topic_id, correct, error_type):
    row = conn.execute("SELECT * FROM error_log WHERE question_id=?", (question_id,)).fetchone()
    if correct:
        if row and row["active"]:
            new_streak = row["consecutive_correct"] + 1
            active = 0 if new_streak >= 2 else 1
            conn.execute("UPDATE error_log SET consecutive_correct=?, active=? WHERE question_id=?",
                         (new_streak, active, question_id))
            conn.commit()
    else:
        et = error_type or "Content"
        if row:
            conn.execute("""UPDATE error_log SET topic_id=?, error_type=?, tagged_at=?,
                             consecutive_correct=0, active=1 WHERE question_id=?""",
                         (topic_id, et, datetime.now().isoformat(), question_id))
        else:
            conn.execute("""INSERT INTO error_log
                (question_id, topic_id, error_type, tagged_at, consecutive_correct, active)
                VALUES (?,?,?,?,0,1)""", (question_id, topic_id, et, datetime.now().isoformat()))
        conn.commit()

def record_attempt(conn, mode, question_id, topic_id, correct, hint_level, a_irt, b_irt, time_taken,
                    confidence=None, error_type=None, initial_answer=None, chosen=None, rushing=False,
                    update_bkt=True, log_error=True, question=None):
    """`update_bkt` / `log_error` exist for callers that need the attempt
    ROW (so PFA and per-topic counts can see the evidence) but handle the
    mastery update themselves or shouldn't touch the error log. Free recall
    is the case: it applies its own fractional-credit BKT update, and its
    items are flashcards rather than quiz questions, so logging them to the
    error log would fill it with IDs that aren't in QUIZ_BANK.

    PRETEST (spec 7.6): a first encounter served as a sanctioned guess is an
    EXPECTED miss, not evidence of non-mastery. Its row is kept (so the
    session and the retest hook can see it) but stored with a_irt=NULL,
    which every theta estimator already filters on, and it skips BKT, the
    error log, flashcard pull-forward, and skill-level FSRS. DINA and the
    selector's empirical-difficulty query exclude mode='pretest' explicitly."""
    is_pretest = (mode == "pretest")
    # Ability BEFORE this answer is folded in -- the expectation the model
    # held when the item was served, which is what item fit (Locus D) must
    # score against. A failure here leaves NULL and the reader falls back
    # to a reconstructed running estimate.
    try:
        theta_at = float(ability_with_se(conn)[0])
    except (sqlite3.Error, ValueError, TypeError, KeyError) as e:
        theta_at = None
        _audit(conn, "theta_at_error", f"{question_id}: {type(e).__name__}: {e}")
    cur = conn.execute("""INSERT INTO attempts
        (timestamp, mode, question_id, topic_id, correct, hint_level, a_irt, b_irt, time_taken,
         confidence, error_type, initial_answer, chosen, theta_at)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (datetime.now().isoformat(), mode, question_id, topic_id,
         1 if correct else 0, hint_level, None if is_pretest else a_irt, b_irt, time_taken,
         confidence, error_type, initial_answer, chosen, theta_at))
    conn.commit()
    # The new row id is returned so a caller that may later amend the row in
    # place (exam back-navigation) can find it without re-querying.
    row_id = cur.lastrowid
    stamp_attempt_context(conn, row_id, question_id)
    if is_pretest:
        return row_id
    # KT-IDEM: look the full question up so bkt_update gets its difficulty
    # and can use the right per-item slip/guess pair, at every call site,
    # with no caller changes required. A caller that holds a dict the bank
    # does not (a generated `gen-` item, a candidate) passes it as
    # `question` so its own difficulty is used rather than the medium
    # default.
    if question is None:
        question = QUIZ_BANK.get(question_id)
    # THE LADDER GATE, learner-facing side. An uncalibrated candidate is
    # practice, not measurement: its row is kept (the ladder needs it to
    # estimate an empirical difficulty) but it must not move topic mastery,
    # the error log, the flashcard queue or skill-level FSRS -- theta and
    # DINA already gate it out, and the mastery number the learner actually
    # sees must follow the same rule.
    if str(question_id).startswith("cand-") and question_id not in calibrated_candidate_ids(conn):
        update_bkt = False
        log_error = False
        shadow_item = True
    else:
        shadow_item = False
    if update_bkt:
        bkt_update(conn, topic_id, correct, hint_level, question=question,
                   rushing=rushing)
    if log_error and not str(question_id).startswith("gen-"):
        update_error_log(conn, question_id, topic_id, correct, error_type)
    if not correct and not shadow_item:
        # A quiz miss is direct, strong evidence that this topic's flashcards
        # are worth reviewing sooner than FSRS's normal spacing would have
        # scheduled -- previously the quiz/exam engine and the flashcard
        # scheduler never spoke to each other, so acing (or bombing) a topic
        # in one had zero effect on the other's queue.
        pull_related_flashcards_forward(conn, topic_id)
    # Spec 7.1 (Fault A): every exam-format item now feeds skill-level FSRS
    # and the successive-relearning criterion, once per Q-matrix skill it
    # loads on. Heavily-hinted answers are not unaided recall and are
    # excluded, mirroring the theta/BKT discount.
    if update_bkt and (hint_level is None or hint_level < HEAVY_HINT_THRESHOLD):
        # This loop is the whole skill-FSRS pipeline; a fault here must not
        # abort the attempt (the row is already committed and the caller is
        # mid-session) but it must leave a trace, or every skill silently
        # freezes at "building" with nothing to show why.
        for sid in Q_MATRIX.get(question_id, []):
            if sid not in SKILLS:
                continue
            try:
                record_skill_evidence(conn, sid, correct, time_taken, confidence, mode,
                                      question=question)
            except (sqlite3.Error, ValueError, TypeError, KeyError, AttributeError) as e:
                _audit(conn, "skill_fsrs_error",
                       f"{sid} on {question_id}: {type(e).__name__}: {e}")
    return row_id

# ---------------------------------------------------------------------------
# SKILL-LEVEL RETRIEVAL STATE (spec 7.1)
# ---------------------------------------------------------------------------
# The Q-matrix becomes the unit of spaced retrieval. Card state keyed on
# "skill:<id>" lives in the same card_progress table with the same FSRS +
# relearning columns, so `successive_relearning_complete` on a skill row is
# the literature-grounded definition of a SOLID skill (Rawson & Dunlosky).
# FSRS decides WHEN a skill is due; select_next_item decides WHICH item
# serves it. Multi-skill items update every loaded skill (approximate --
# apportioning blame via DINA slip/guess is the principled refinement).

def skill_card_id(skill_id):
    return f"skill:{skill_id}"

SKILL_EASY_RT_Z = -1.0   # a correct answer this far below the learner's own pace counts as effortless

def skill_grades(correct, elapsed, confidence, conn=None, question=None, mode=None):
    """(raw_grade, effective_grade) for one exam-format answer on a skill
    row; 0=Again, 1=Hard, 2=Good, 3=Easy.

    A correct answer is Good. FSRS-6's Easy is the "effortless" rating
    (initial stability w3 ~8.3 d vs w2 ~2.3 d for Good, plus the easy
    bonus on every later recall) and is meant to be rare; on a four-option
    item a "Confident" click carries little of that information -- the
    calibration data in this app show ~90% stated confidence against ~52%
    accuracy -- so confidence alone never earns it. Easy needs confidence
    3 AND a response time clearly fast for THIS learner on items of this
    difficulty (personal RT z-score, never the generic default basis).
    Confidence 1 caps a fragile hit at Hard (spec 7.1). The effective
    grade then takes the same hesitation downgrade the flashcard path
    applies; the raw grade is what gets logged."""
    if not correct:
        return 0, 0
    raw = 2
    if confidence == 1:
        raw = 1
    elif confidence == 3 and conn is not None and elapsed:
        try:
            z, basis = timing_z(conn, question or {}, float(elapsed),
                                regime=baseline_regime_for_mode(mode))
        except (sqlite3.Error, TypeError, ValueError, ZeroDivisionError):
            z, basis = 0.0, "default"
        if basis == "personal" and z < SKILL_EASY_RT_Z:
            raw = 3
    eff = raw
    if conn is not None and elapsed:
        try:
            eff, _adj, _why = fluency_adjusted_grade(conn, raw, int(elapsed * 1000),
                                                     family="skill", question=question,
                                                     regime=baseline_regime_for_mode(mode))
        except (sqlite3.Error, TypeError, ValueError, ZeroDivisionError):
            eff = raw
    return raw, eff

def grade_from_outcome(correct, elapsed, confidence, conn=None, question=None, mode=None):
    """Effective (scheduling) grade for a skill row; see skill_grades."""
    return skill_grades(correct, elapsed, confidence, conn=conn, question=question, mode=mode)[1]

def record_skill_evidence(conn, skill_id, correct, elapsed, confidence, mode, question=None):
    if mode == "pretest":
        return
    cid = skill_card_id(skill_id)
    state = get_card_state(conn, cid)
    raw, grade = skill_grades(correct, elapsed, confidence, conn=conn, question=question, mode=mode)
    new_state = hlr_update(state, grade, conn=conn)
    apply_successive_relearning_criterion(new_state, correct=bool(correct))
    save_card_state(conn, cid, new_state)
    # Log the RAW grade and schedule on the adjusted one, exactly as the
    # flashcard path does, so the fluency adjustment stays auditable and
    # reversible for skill rows too.
    log_review(conn, cid, raw, int((elapsed or 0) * 1000) or None)

def _skill_rows(conn):
    """All skill-keyed card rows as {skill_id: state}."""
    out = {}
    try:
        rows = conn.execute("SELECT card_id FROM card_progress WHERE card_id LIKE 'skill:%'").fetchall()
    except Exception:
        return out
    for r in rows:
        sid = r["card_id"][6:]
        if sid in SKILLS:
            out[sid] = get_card_state(conn, r["card_id"])
    return out

def skill_status(conn):
    """Solid / building / not started, plus which skills are due today.
    Building carries a 'progress' string like '2 of 3' for the Progress
    screen. Not-started is neutral: never coloured, never ranked."""
    rows = _skill_rows(conn)
    solid, building, due = [], [], []
    for sid, st in rows.items():
        if st.get("successive_relearning_complete"):
            solid.append(sid)
        else:
            if st.get("initial_criterion_met"):
                prog = f"{st.get('relearn_sessions_completed', 0)} of {RELEARN_SESSIONS_REQUIRED} sessions"
            else:
                prog = f"{st.get('initial_streak', 0)} of {INITIAL_CRITERION_STREAK} to criterion"
            building.append((sid, prog))
        if card_due_today(st):
            due.append((sid, predicted_recall(st)))
    started = set(rows)
    not_started = [sid for sid in SKILLS if sid not in started]
    # Consolidation first: a skill one spaced day from solid outranks one
    # that has barely started, and both outrank a solid skill merely due
    # for maintenance. Spreading a short session thinly across every due
    # skill would leave all of them building and none of them finished;
    # successive relearning only pays when its sessions actually land on
    # the scheduled days. Within a band, lowest predicted recall first.
    def _due_key(item):
        sid, recall = item
        st = rows.get(sid) or {}
        if st.get("successive_relearning_complete"):
            band = 2
            steps_left = 0
        elif st.get("initial_criterion_met"):
            band = 0
            steps_left = RELEARN_SESSIONS_REQUIRED - int(st.get("relearn_sessions_completed", 0))
        else:
            band = 1
            steps_left = INITIAL_CRITERION_STREAK - int(st.get("initial_streak", 0))
        return (band, steps_left, recall)
    due.sort(key=_due_key)
    return {"solid": solid, "building": building, "not_started": not_started,
            "due": due, "n_total": len(SKILLS)}

def skills_solid_count(conn):
    return len(skill_status(conn)["solid"])

_SUMMARY_CACHE = {"at": 0.0, "solid": 0, "est": None, "attempts": -1}

def session_summary_cached(conn, ttl_s=900):
    """(solid count, next-session minutes) for the sidebar footer, refreshed
    at most every ttl_s or when the attempt count changes -- the footer runs
    on every navigation and must not recompute the composer each time."""
    try:
        n_att = conn.execute("SELECT COUNT(*) c FROM attempts").fetchone()["c"]
    except Exception:
        n_att = -1
    now = time.monotonic()
    if (now - _SUMMARY_CACHE["at"] < ttl_s) and _SUMMARY_CACHE["attempts"] == n_att:
        return _SUMMARY_CACHE["solid"], _SUMMARY_CACHE["est"]
    solid = skills_solid_count(conn)
    try:
        # Today only offers a composed session once a diagnostic exists;
        # before that its single action is the diagnostic, so quoting the
        # composer's estimate would describe a session nobody is offered.
        has_diag = conn.execute(
            "SELECT 1 FROM diagnostic_results LIMIT 1").fetchone() is not None
        if n_att == 0 or not has_diag:
            est = None
        else:
            est = compose_session(conn)["est_minutes"]
    except Exception:
        est = None
    _SUMMARY_CACHE.update({"at": now, "solid": solid, "est": est, "attempts": n_att})
    return solid, est

def items_for_skill(skill_id):
    return [q for q in QUIZ_LIST if skill_id in Q_MATRIX.get(q["id"], [])]

def flashcards_for_topic(topic_id):
    return [c for c in FLASHCARDS if c.get("topic") == topic_id]

def pull_related_flashcards_forward(conn, topic_id, max_cards=2):
    """Move up to max_cards of this topic's flashcards to be due today,
    prioritizing the ones with the lowest current stability (weakest
    memory), since those benefit most from an earlier review. Deliberately
    capped and gentle: pulling an entire topic's deck forward on a single
    miss would flood the next flashcard session instead of nudging it, and
    a card already due soon is left alone rather than reset."""
    cards = flashcards_for_topic(topic_id)
    if not cards:
        return
    today = date.today()
    candidates = []
    for c in cards:
        st = get_card_state(conn, c["id"])
        due = due_local_date(st)
        if due <= today + timedelta(days=1):
            continue  # already due soon; nothing to pull forward
        stability = st.get("stability")
        candidates.append((stability if stability is not None else 0.0, c["id"], st))
    candidates.sort(key=lambda x: x[0])  # weakest memory first
    for _stability, card_id, st in candidates[:max_cards]:
        st = dict(st)
        st["due_date"] = _dt_now().isoformat()
        save_card_state(conn, card_id, st)

def topic_fragility(conn, topic_id, halflife_attempts=6, stale_cap_days=21):
    # Hinted rows stay in: effective_credit and hint_rate below are what
    # account for them. Sanctioned pretest guesses and free-recall rows
    # are not measurement of this kind at all (MEASUREMENT_MODE_SQL).
    rows = _safe_query(conn, """SELECT correct, hint_level, timestamp FROM attempts
                            WHERE topic_id=? AND """ + MEASUREMENT_MODE_SQL + """
                            ORDER BY timestamp ASC""", (topic_id,))
    # Use the BKT/PFA blend rather than raw BKT. Previously PFA and
    # blended_mastery() existed but had ZERO callers -- every mastery number
    # the app displayed was raw BKT, so the entire PFA integration was
    # ornamental. topic_fragility is the single funnel feeding the dashboard,
    # Case File, Analytics and Study Notes, so routing it here wires the
    # blend into all of them at once.
    mastery, bkt_only, pfa_only, disagreement = blended_mastery(conn, topic_id)
    if not rows:
        return {"score": 50.0, "n": 0, "accuracy": None, "hint_rate": None,
                "days_since": None, "label": "Unstudied", "mastery": mastery,
                "mastery_bkt": bkt_only, "mastery_pfa": pfa_only,
                "mastery_disagreement": disagreement}
    n = len(rows)
    weighted_sum = 0.0
    weight_total = 0.0
    hint_uses = 0
    for i, r in enumerate(rows):
        age_rank = n - 1 - i
        w = 0.5 ** (age_rank / halflife_attempts)
        eff = effective_credit(bool(r["correct"]), r["hint_level"] or 0)
        if r["hint_level"]:
            hint_uses += 1
        weighted_sum += eff * w
        weight_total += w
    accuracy = weighted_sum / weight_total if weight_total else 0.0
    hint_rate = hint_uses / n
    last_ts = rows[-1]["timestamp"]
    try:
        days_since = (datetime.now() - datetime.fromisoformat(last_ts)).days
    except Exception:
        days_since = 0
    staleness = min(days_since, stale_cap_days) / stale_cap_days
    raw = (1 - accuracy) * 55 + hint_rate * 15 + staleness * 10 + (1 - mastery) * 20
    score = max(0.0, min(100.0, raw))
    label = "Fragile" if score >= 60 else ("Developing" if score >= 35 else "Solid")
    return {"score": round(score, 1), "n": n, "accuracy": round(accuracy * 100, 1),
            "hint_rate": round(hint_rate * 100, 1), "days_since": days_since,
            "label": label, "mastery": round(mastery * 100, 1),
            "mastery_bkt": round(bkt_only * 100, 1),
            "mastery_pfa": round(pfa_only * 100, 1),
            "mastery_disagreement": round(disagreement * 100, 1)}

def all_topic_fragility(conn):
    return {tid: topic_fragility(conn, tid) for tid in TOPICS}

def weakest_topics(conn, n=6):
    frag = all_topic_fragility(conn)
    studied = {tid: f for tid, f in frag.items() if f["n"] > 0}
    return sorted(studied.items(), key=lambda kv: kv[1]["score"], reverse=True)[:n]

def weakest_questions(conn, n=8):
    rows = conn.execute("""
        SELECT question_id, topic_id,
               SUM(CASE WHEN correct=1 THEN 1 ELSE 0 END) as correct_ct,
               COUNT(*) as total_ct,
               SUM(CASE WHEN hint_level>0 THEN 1 ELSE 0 END) as hint_ct
        FROM attempts WHERE question_id NOT LIKE 'gen-%'
          AND """ + MEASUREMENT_MODE_SQL + """
        GROUP BY question_id HAVING total_ct >= 1
    """).fetchall()
    scored = []
    for r in rows:
        acc = r["correct_ct"] / r["total_ct"]
        hint_rate = r["hint_ct"] / r["total_ct"]
        frag_score = (1 - acc) * 80 + hint_rate * 20
        scored.append((frag_score, r))
    scored.sort(key=lambda x: x[0], reverse=True)
    return scored[:n]

def current_streak(conn):
    rows = conn.execute("SELECT date FROM sessions ORDER BY date DESC").fetchall()
    if not rows:
        return 0
    dates = set(r["date"] for r in rows)
    streak = 0
    cursor = date.today()
    while cursor.isoformat() in dates:
        streak += 1
        cursor -= timedelta(days=1)
    return streak

# ============================================================================
# LINEAR REGRESSION / TREND / READINESS FORECAST
# ============================================================================

def linreg(xs, ys):
    n = len(xs)
    if n < 2:
        return 0.0, ys[0] if ys else 0.0
    mean_x = sum(xs) / n
    mean_y = sum(ys) / n
    num = sum((x - mean_x) * (y - mean_y) for x, y in zip(xs, ys))
    den = sum((x - mean_x) ** 2 for x in xs)
    slope = num / den if den else 0.0
    intercept = mean_y - slope * mean_x
    return slope, intercept

def linreg_slope_se(xs, ys, slope, intercept):
    """Standard error of the OLS slope from the residuals; None below 3
    points (no residual degrees of freedom)."""
    n = len(xs)
    if n < 3:
        return None
    mean_x = sum(xs) / n
    sxx = sum((x - mean_x) ** 2 for x in xs)
    if sxx <= 0:
        return None
    sse = sum((y - (slope * x + intercept)) ** 2 for x, y in zip(xs, ys))
    return math.sqrt(max(sse, 0.0) / (n - 2) / sxx)

def theta_trend(conn, limit=600):
    """Running ability at ~20 checkpoints over the measurement rows, on the
    same evidence rules and the same 3PL EAP as ability_with_se (so the
    trend ends where the displayed theta is), plus the OLS slope and its
    standard error."""
    rows = conn.execute("""SELECT question_id, a_irt, b_irt, correct, timestamp FROM attempts
                            WHERE a_irt IS NOT NULL AND (hint_level IS NULL OR hint_level < ?)
                            ORDER BY id DESC LIMIT ?""", (HEAVY_HINT_THRESHOLD, limit)).fetchall()
    rows = list(reversed(model_feed_filter(conn, rows)))
    if len(rows) < 6:
        return None
    thetas, xs, running = [], [], []
    step = max(1, len(rows) // 20)
    for i, r in enumerate(rows):
        running.append((r["a_irt"], r["b_irt"], r["correct"]))
        if i % step == 0 or i == len(rows) - 1:
            thetas.append(eap_theta(running)[0])
            xs.append(i)
    slope, intercept = linreg(xs, thetas)
    return {"slope": slope, "intercept": intercept, "thetas": thetas, "xs": xs, "n": len(rows),
            "slope_se": linreg_slope_se(xs, thetas, slope, intercept),
            "first_ts": rows[0]["timestamp"], "last_ts": rows[-1]["timestamp"]}

FORECAST_HORIZON_MULT = 2.0   # never extrapolate the trend beyond 2x the attempts it was fit on

def readiness_forecast(conn):
    """Pace is attempts per ACTIVE study day, not per day of the current
    streak (a learner with 400 attempts who skipped yesterday has streak
    0-1 and was projected to do 400 attempts a day, which drove the linear
    trend straight to the +/-4 clamp). The extrapolation horizon is capped
    at FORECAST_HORIZON_MULT times the fitted span, and when the slope's
    95% CI includes zero there is no trend to extrapolate: projected_theta
    is None and the report says so."""
    trend = theta_trend(conn)
    theta, mean_score, p_pass = predict_pass_probability(conn)
    target_date_str = get_setting(conn, "target_exam_date")
    forecast = None
    if trend and target_date_str:
        try:
            target_date = date.fromisoformat(target_date_str)
            days_left = (target_date - date.today()).days
            active_days = conn.execute(
                """SELECT COUNT(DISTINCT substr(timestamp, 1, 10)) c FROM attempts
                    WHERE a_irt IS NOT NULL""").fetchone()["c"]
            attempts_per_day = trend["n"] / max(1, active_days or 1)
            span = trend["xs"][-1] if trend["xs"] else 0
            projected_extra_attempts = min(attempts_per_day * max(0, days_left),
                                           FORECAST_HORIZON_MULT * max(1, span))
            projected_x = span + projected_extra_attempts
            se = trend.get("slope_se")
            significant = se is not None and abs(trend["slope"]) > 1.96 * se
            if significant:
                projected_theta = trend["slope"] * projected_x + trend["intercept"]
                projected_theta = max(-4.0, min(4.0, projected_theta))
            else:
                projected_theta = None
            forecast = {"days_left": days_left, "projected_theta": projected_theta,
                        "target_date": target_date_str, "attempts_per_day": attempts_per_day,
                        "active_days": active_days, "horizon_capped": projected_extra_attempts
                        < attempts_per_day * max(0, days_left)}
        except (ValueError, sqlite3.Error):
            forecast = None
    return theta, mean_score, p_pass, trend, forecast

# ============================================================================
# FSRS-6 FLASHCARD SCHEDULER
# ============================================================================
# Replaces the earlier hand-rolled half-life-regression scheduler with the
# REAL, official FSRS (Free Spaced Repetition Scheduler) algorithm via the
# `fsrs` PyPI package (maintained by the algorithm's own author). FSRS is the
# current state of the art in spaced repetition, built on a three-component
# memory model -- Stability, Difficulty, Retrievability -- and is the
# scheduler Anki itself now ships as default, benchmarked as outperforming
# SM-2 for the overwhelming majority of users even WITHOUT per-user parameter
# optimization (https://github.com/open-spaced-repetition).
#
# Deliberately NOT doing: per-user gradient-descent parameter optimization.
# FSRS's own optimizer is designed for hundreds to low-thousands of reviews
# per deck; below roughly 1000 reviews the community guidance is that
# optimizing fits noise and the published defaults perform better. This app
# uses the published default 21-parameter set and instead adapts the
# DESIRED-RETENTION target to the exam date -- which is exactly the lever
# FSRS exposes for deadline-aware scheduling, rather than an unbounded
# maximize-long-run-retention objective that would be the wrong goal here.
#
# Falls back to the earlier half-life model if the `fsrs` package is not
# installed, so nothing breaks for a user who hasn't run `pip install fsrs`.

try:
    import fsrs as _fsrs_lib
    FSRS_AVAILABLE = True
except ImportError:
    _fsrs_lib = None
    FSRS_AVAILABLE = False

TARGET_RECALL = 0.85          # fallback-mode target only; FSRS uses desired_retention below
_FSRS_SCHEDULER_CACHE = {}    # (desired_retention, params_version) -> Scheduler instance
# False once a stored custom parameter set has been rejected (and cleared),
# or an FSRS review has raised and been scheduled by the fallback instead;
# the Settings view can show it so the learner is never told "personalised
# FSRS-6" while the legacy heuristic is doing the scheduling.
FSRS_PARAMS_OK = True

def fsrs_desired_retention(conn):
    """The deadline-aware lever the research calls for: FSRS's own
    'desired retention' knob directly controls how tightly intervals are
    packed. With an open-ended horizon a lower retention target (fewer,
    longer-spaced reviews) is efficient; as an exam date approaches, raising
    the target compresses intervals so weak material gets one more retrieval
    before it counts. Below is a simple, defensible ramp, not a claim of
    provably optimal finite-horizon scheduling (the research found that
    question genuinely less settled than the open-ended case)."""
    # Calibration feeds scheduling. A learner who cannot tell whether they
    # know something is exactly the learner who should be tested on it
    # sooner -- overconfidence raises the retention target, which tightens
    # intervals. Underconfidence deliberately does nothing: that learner is
    # at risk of over-reviewing, not under-reviewing.
    bump = 0.0
    try:
        cal = calibration_metrics(conn)
        if cal and cal.get("n", 0) >= 12 and cal["bias"] > 0.10:
            bump = min(0.04, (cal["bias"] - 0.10) * 0.15)
    except Exception:
        bump = 0.0

    days = days_to_exam(conn)
    if days is None:
        return min(0.97, 0.88 + bump)
    if days <= 5:
        return min(0.98, 0.97 + bump)
    if days <= 14:
        return min(0.97, 0.94 + bump)
    if days <= 30:
        return min(0.96, 0.90 + bump)
    if days <= 60:
        return min(0.95, 0.88 + bump)
    return min(0.94, 0.85 + bump)

def _custom_fsrs_parameters(conn):
    """Per-user re-optimized FSRS parameters, if fitting has been run and
    succeeded (see reoptimize_fsrs_parameters below). None means: use the
    library's own published defaults, which the FSRS project's own
    benchmark found out-predict SM-2 for 99.5% of users even with zero
    personalization -- a reasonable floor, not a broken fallback."""
    global FSRS_PARAMS_OK
    raw = get_setting(conn, "fsrs_custom_parameters", "")
    if not raw:
        return None
    # FSRS-6 takes exactly 21 parameters, each within the library's own
    # bounds; a 17-19 element set (what an earlier fsrs optimizer wrote) or
    # an out-of-range value makes Scheduler() raise on every review, which
    # used to drop every card onto the legacy heuristic with the UI still
    # advertising personalised FSRS-6. Validate once here by constructing
    # a throwaway scheduler; a bad set is cleared and recorded, and the
    # published defaults take over visibly (FSRS_PARAMS_OK).
    why = None
    try:
        params = json.loads(raw)
        if not (isinstance(params, list) and len(params) == 21):
            why = f"expected 21 parameters, got {len(params) if isinstance(params, list) else type(params).__name__}"
        else:
            params = [float(p) for p in params]
            if FSRS_AVAILABLE:
                _fsrs_lib.Scheduler(parameters=params)
    except (ValueError, TypeError, json.JSONDecodeError) as e:
        why = f"{type(e).__name__}: {e}"
    if why is None:
        FSRS_PARAMS_OK = True
        return params
    FSRS_PARAMS_OK = False
    set_setting(conn, "fsrs_custom_parameters", "")
    _audit(conn, "fsrs_params_rejected", f"{why}; reverted to FSRS-6 defaults")
    return None

def _get_fsrs_scheduler(conn):
    dr = round(fsrs_desired_retention(conn), 2)
    custom = _custom_fsrs_parameters(conn)
    # Cache key includes whether custom params are active (and their
    # fingerprint) so a scheduler built from stale/default parameters isn't
    # silently served after re-optimization changes them.
    cache_key = (dr, tuple(custom) if custom else None)
    sched = _FSRS_SCHEDULER_CACHE.get(cache_key)
    if sched is None:
        sched = (_fsrs_lib.Scheduler(parameters=custom, desired_retention=dr) if custom
                else _fsrs_lib.Scheduler(desired_retention=dr))
        _FSRS_SCHEDULER_CACHE[cache_key] = sched
    return sched

# ---------------------------------------------------------------------------
# Per-user FSRS parameter re-optimization ("re-optimize, don't replace" --
# no released successor to FSRS-6 exists; the proven personalization move is
# refitting its own 21 parameters against this learner's actual review
# history, not chasing a different algorithm).
#
# fsrs.Optimizer is a LAZY submodule import that pulls in the full torch
# stack the moment it's touched (confirmed directly: `import fsrs` alone
# does not import torch; accessing fsrs.Optimizer does). Given this exact
# class of dependency has already caused real, confirmed failures for a
# real user on this exact app (a stray file shadowing a stdlib module, a
# missing transitive dependency, Windows Security blocking a compiled
# extension -- three separate incidents, not a hypothetical risk), this is
# treated as an explicitly OPTIONAL feature: never imported at startup,
# only on an explicit user action, run off the UI thread, and gracefully
# degrading to "kept the defaults" on any failure rather than blocking
# anything else in the app.
# ---------------------------------------------------------------------------
MIN_REVIEWS_FOR_REOPTIMIZATION = 30  # a soft floor, not a hard technical
# minimum -- modern FSRS tooling (Anki 24.06+) imposes none, and a public
# benchmark found optimized parameters beating the shipped defaults after as
# few as ~16 reviews. 30 is chosen a little more conservatively to avoid
# fitting 21 parameters to a very small, noisy log, not because fewer
# reviews would fail technically.

_FSRS_OPTIMIZER_AVAILABLE = None
_FSRS_OPTIMIZER_FAILED_AT = None

def fsrs_optimizer_available(force=False):
    """Mirrors semantic_available()'s pattern exactly: a failed check
    expires after a cooldown rather than poisoning the rest of the running
    session, and `force=True` (wired to a manual retry) bypasses the
    cooldown for an immediate recheck -- the same fix applied earlier this
    build after a permanently-cached failure caused real user-visible
    confusion.

    Checked directly against the installed package: merely accessing
    fsrs.Optimizer as a class reference always succeeds, even when the
    actual torch-backed implementation isn't installed (it's a separate
    PyPI extra, `fsrs[optimizer]`) -- the real "not installed" error only
    surfaces when constructing one. So this probes with a throwaway
    zero-length construction rather than a bare attribute check, which was
    measured giving a false positive."""
    global _FSRS_OPTIMIZER_AVAILABLE, _FSRS_OPTIMIZER_FAILED_AT
    if _FSRS_OPTIMIZER_AVAILABLE is True:
        return True
    if not force and _FSRS_OPTIMIZER_FAILED_AT is not None and \
            (time.time() - _FSRS_OPTIMIZER_FAILED_AT) < _LOAD_RETRY_COOLDOWN:
        return False
    try:
        import fsrs as _f
        _f.Optimizer([])
        _FSRS_OPTIMIZER_AVAILABLE = True
        _FSRS_OPTIMIZER_FAILED_AT = None
    except Exception:
        _FSRS_OPTIMIZER_AVAILABLE = False
        _FSRS_OPTIMIZER_FAILED_AT = time.time()
    return _FSRS_OPTIMIZER_AVAILABLE

def reoptimize_fsrs_parameters(conn):
    """Fit personalized FSRS-6 parameters from this learner's own
    review_log. Returns (params_or_None, message). Deliberately synchronous
    -- the CALLER (a UI button handler) is responsible for running this off
    the UI thread, exactly like every other heavy-import feature in this
    app; this function itself has no thread-safety opinion baked in beyond
    using its own short-lived connection-free query (rows are read once,
    up front, before any slow import happens)."""
    rows = conn.execute("SELECT card_id, rating, reviewed_at FROM review_log "
                        "ORDER BY card_id, reviewed_at ASC").fetchall()
    # The fit is FLASHCARDS-ONLY: skill rows (`skill:<id>`, one per Q-matrix
    # skill per quiz answer) are excluded below, so the count gate must be
    # on the rows the fit can actually use, or a learner who studies mostly
    # via Today sessions is told "30+ reviews" while the usable count is
    # near zero. The fitted parameters still govern skill rows.
    rows = [r for r in rows if re.match(r"^f(\d+)$", r["card_id"] or "")]
    if len(rows) < MIN_REVIEWS_FOR_REOPTIMIZATION:
        return None, (f"Only {len(rows)} flashcard reviews logged so far -- "
                      f"{MIN_REVIEWS_FOR_REOPTIMIZATION}+ gives the fit enough to work with. The fit "
                      "uses Flashcards/Free Recall reviews only (quiz-based skill reviews are not "
                      "counted), so keep using those and try again later.")
    if not FSRS_AVAILABLE:
        return None, ("The fsrs package is not installed, so there is nothing to fit -- your "
                      "schedule is using the built-in half-life fallback, not FSRS-6. Install it "
                      "with pip install fsrs (and \"fsrs[optimizer]\" for fitting) and restart.")
    if not fsrs_optimizer_available():
        return None, ("Could not load the optimizer (it needs an extra package, PyTorch, on top of "
                      "the base fsrs library). Your schedule keeps using the published FSRS-6 "
                      "defaults, which the algorithm's own benchmark found accurate for 99.5% of "
                      "users even with no personalization -- nothing is broken.")
    try:
        import fsrs as _f
        review_logs = []
        for r in rows:
            m = re.match(r"^f(\d+)$", r["card_id"])
            if not m:
                continue  # skip anything not matching this app's flashcard id scheme
            try:
                rating = _f.Rating(int(r["rating"]) + 1)  # this app stores 0-3, fsrs.Rating is 1-4
                # fsrs.ReviewLog requires a timezone-AWARE datetime; every
                # timestamp this app stores is naive local time
                # (datetime.now().isoformat(), used everywhere, not just
                # here), so this tags it UTC on parse rather than trying to
                # retrofit real timezone tracking across the whole app. What
                # the optimizer actually needs is consistent RELATIVE
                # spacing between a card's reviews, not true UTC alignment,
                # so treating the existing naive timestamps as UTC is
                # internally consistent with how the app already handles
                # dates everywhere else.
                when = datetime.fromisoformat(r["reviewed_at"]).replace(tzinfo=timezone.utc)
            except Exception:
                continue
            review_logs.append(_f.ReviewLog(card_id=int(m.group(1)), rating=rating,
                                            review_datetime=when, review_duration=None))
        if len(review_logs) < MIN_REVIEWS_FOR_REOPTIMIZATION:
            return None, "Not enough usable review history after filtering. Try again after more reviews."
        optimizer = _f.Optimizer(review_logs)
        params = optimizer.compute_optimal_parameters()
        params = [float(p) for p in params]
        if len(params) != 21:
            raise ValueError(f"optimizer returned {len(params)} parameters, FSRS-6 needs 21")
        _f.Scheduler(parameters=params)   # rejects an out-of-range set before it is stored
    except Exception as e:
        return None, f"Optimization failed ({e}). Your schedule keeps using the published defaults."
    set_setting(conn, "fsrs_custom_parameters", json.dumps(params))
    set_setting(conn, "fsrs_reoptimized_at", datetime.now().isoformat())
    set_setting(conn, "fsrs_reoptimized_n", str(len(review_logs)))
    _FSRS_SCHEDULER_CACHE.clear()  # old cached schedulers used the old parameters
    return params, (f"Re-optimized from {len(review_logs)} of your own flashcard reviews "
                    "(the fit is flashcards-only; the parameters also schedule skill reviews).")

def _dt_from_iso(s):
    if not s:
        return None
    # ONE CLOCK. card_progress.last_reviewed / due_date are stored as full
    # UTC timestamps (see hlr_update). Rows written before that carry a bare
    # LOCAL calendar date; those are read as local noon converted to UTC,
    # so a legacy date can never straddle a UTC midnight and turn a same-
    # day repeat into a one-day spaced review. A naive datetime is taken
    # as UTC, which is what this module writes.
    if len(s) == 10:
        d0 = date.fromisoformat(s)
        local_noon = datetime(d0.year, d0.month, d0.day, 12, 0).astimezone()
        return local_noon.astimezone(timezone.utc)
    d = datetime.fromisoformat(s)
    if d.tzinfo is None:
        d = d.replace(tzinfo=timezone.utc)
    return d

def _dt_now():
    return datetime.now(timezone.utc)

def due_local_date(state):
    """The LOCAL calendar date a card is due, whichever form due_date was
    stored in. Every 'due today' decision in the app goes through this (or
    card_due_today) so the sidebar, Today, Flashcards, Free Recall and the
    skill list can never disagree about what day it is."""
    try:
        d = _dt_from_iso(state.get("due_date"))
    except (TypeError, ValueError):
        d = None
    if d is None:
        return date.today()
    return d.astimezone().date()

def card_due_today(state):
    """Due on this local calendar day -- with one exception. A card in a
    learning/relearning step whose next step is still minutes away (a full
    timestamp in the future, i.e. it was graded moments ago) is not counted:
    the sitting that started it re-serves it (see view_flashcards), and
    counting it would show a learner who has just worked through the whole
    deck the same "N due today" they started with."""
    if state.get("state") in (1, 3):
        raw = state.get("due_date") or ""
        if len(raw) > 10:          # a bare legacy date carries no time of day
            try:
                if _dt_from_iso(raw) > _dt_now():
                    return False
            except (TypeError, ValueError):
                pass
    return due_local_date(state) <= date.today()

def get_card_state(conn, card_id):
    row = conn.execute("SELECT * FROM card_progress WHERE card_id=?", (card_id,)).fetchone()
    if row is None:
        return {"stability": None, "difficulty": None, "state": 1, "step": 0,
                "reps": 0, "due_date": _dt_now().isoformat(), "last_reviewed": None,
                "initial_streak": 0, "initial_criterion_met": False,
                "relearn_sessions_completed": 0, "relearn_last_date": None,
                "successive_relearning_complete": False}
    # Read new FSRS columns if present; tolerate an old pre-migration row.
    keys = row.keys()
    return {
        "stability": row["stability"] if "stability" in keys else None,
        "difficulty": row["difficulty"] if "difficulty" in keys else None,
        "state": row["fsrs_state"] if "fsrs_state" in keys and row["fsrs_state"] is not None else 1,
        "step": row["fsrs_step"] if "fsrs_step" in keys else 0,
        "reps": row["reps"],
        # The column has no NOT NULL/DEFAULT and the file is shared with the
        # CLI trainer; a NULL here must read as "due now", not crash the
        # due lists.
        "due_date": row["due_date"] or _dt_now().isoformat(),
        "last_reviewed": row["last_reviewed"],
        "initial_streak": row["initial_streak"] if "initial_streak" in keys and row["initial_streak"] is not None else 0,
        "initial_criterion_met": bool(row["initial_criterion_met"]) if "initial_criterion_met" in keys else False,
        "relearn_sessions_completed": row["relearn_sessions_completed"] if "relearn_sessions_completed" in keys and row["relearn_sessions_completed"] is not None else 0,
        "relearn_last_date": row["relearn_last_date"] if "relearn_last_date" in keys else None,
        "successive_relearning_complete": bool(row["successive_relearning_complete"]) if "successive_relearning_complete" in keys else False,
    }

def save_card_state(conn, card_id, state):
    conn.execute("""INSERT INTO card_progress
            (card_id, stability, difficulty, fsrs_state, fsrs_step, reps, due_date, last_reviewed,
             initial_streak, initial_criterion_met, relearn_sessions_completed, relearn_last_date,
             successive_relearning_complete)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)
            ON CONFLICT(card_id) DO UPDATE SET
                stability=excluded.stability, difficulty=excluded.difficulty,
                fsrs_state=excluded.fsrs_state, fsrs_step=excluded.fsrs_step,
                reps=excluded.reps, due_date=excluded.due_date,
                last_reviewed=excluded.last_reviewed,
                initial_streak=excluded.initial_streak,
                initial_criterion_met=excluded.initial_criterion_met,
                relearn_sessions_completed=excluded.relearn_sessions_completed,
                relearn_last_date=excluded.relearn_last_date,
                successive_relearning_complete=excluded.successive_relearning_complete""",
        (card_id, state.get("stability"), state.get("difficulty"), state.get("state", 1),
         state.get("step"), state["reps"], state["due_date"], state["last_reviewed"],
         state.get("initial_streak", 0), 1 if state.get("initial_criterion_met") else 0,
         state.get("relearn_sessions_completed", 0), state.get("relearn_last_date"),
         1 if state.get("successive_relearning_complete") else 0))
    conn.commit()

# ---------------------------------------------------------------------------
# RETRIEVAL FLUENCY -> SCHEDULING
# ---------------------------------------------------------------------------
# FSRS already consumes a self-reported difficulty grade (Again/Hard/Good/
# Easy). What it cannot see is HOW the answer arrived. Two reviews both
# graded "Good" -- one recalled in two seconds, one dragged out of memory
# after twenty -- are the same input to FSRS and materially different
# memory strengths.
#
# The judgment-of-learning literature is consistent that retrieval LATENCY
# is often a better predictor of durable retention than the learner's own
# stated judgment, precisely because self-report carries the overconfidence
# bias this app already measures elsewhere (see calibration_metrics: a real
# test run showed 90% stated confidence against 52% actual accuracy). A
# learner who hesitates and then reports "Good" is telling you something
# their grade is not.
#
# So this discounts a self-reported grade by measured hesitation, against
# the learner's OWN median review time rather than an absolute threshold --
# people work at very different speeds, and an absolute cutoff would
# systematically punish slow-but-fluent readers.
#
# Deliberately conservative in both directions:
#   * It only ever moves a grade DOWN, never up. Answering fast is not
#     evidence of strength -- it is equally consistent with a lucky guess
#     or a card that is simply easy -- whereas hesitation is fairly direct
#     evidence that retrieval was effortful.
#   * It never promotes "Again" or demotes below "Hard", so the learner's
#     own failure report is always respected and the adjustment cannot
#     collapse an entire deck to the minimum interval.
FLUENCY_HESITATION_RATIO = 2.5   # multiples of personal median that count as hesitation
FLUENCY_MIN_REVIEWS = 12         # below this there is no trustworthy personal baseline

def personal_review_median(conn, family="flashcard", regime="calm", difficulty=None):
    """Median review duration (ms) for this learner in one card FAMILY, or
    None until enough reviews exist to be meaningful.

    The two families are bimodal by construction -- a flashcard flip takes
    a few seconds, an exam-format item tens of seconds -- and review_log
    holds both (skill rows log the whole item's answer time, once per
    Q-matrix skill). One pooled median is the wrong baseline for whichever
    family is in the minority, so:
      * "flashcard": review_log rows that are not skill rows;
      * "skill": the learner's own quiz pace from personal_baselines(regime)
        for this item difficulty when that baseline exists (it is built
        from attempts.time_taken, i.e. exactly this population), else the
        review_log median over skill rows."""
    if family == "skill":
        try:
            b = personal_baselines(conn, regime=regime or "calm")
        except (sqlite3.Error, TypeError, ValueError):
            b = {}
        info = b.get(difficulty) or b.get("medium")
        if info is None and b:
            info = min(b.values(), key=lambda v: -v["n"])
        if info:
            return int(info["median"] * 1000)
        cond = "card_id LIKE 'skill:%'"
    else:
        cond = "card_id NOT LIKE 'skill:%'"
    rows = conn.execute(f"""SELECT duration_ms FROM review_log
                             WHERE duration_ms IS NOT NULL AND duration_ms > 0 AND {cond}
                             ORDER BY id DESC LIMIT 200""").fetchall()
    vals = sorted(r["duration_ms"] for r in rows)
    if len(vals) < FLUENCY_MIN_REVIEWS:
        return None
    return vals[len(vals) // 2]

def fluency_adjusted_grade(conn, grade, duration_ms, family="flashcard", question=None, regime="calm"):
    """Return (effective_grade, was_adjusted, reason).

    The returned grade is what FSRS should schedule against; the learner's
    ORIGINAL grade is still what gets logged to review_log, so the raw
    self-report is never overwritten and this adjustment stays auditable
    and reversible. `family` picks the baseline population (see
    personal_review_median); skill callers pass the item so the baseline
    is for its difficulty."""
    if duration_ms is None or grade <= 1:
        return grade, False, None      # respect Again/Hard as reported
    median = personal_review_median(conn, family=family, regime=regime,
                                    difficulty=(question or {}).get("difficulty"))
    if not median:
        return grade, False, None      # no personal baseline yet
    ratio = duration_ms / float(median)
    if ratio < FLUENCY_HESITATION_RATIO:
        return grade, False, None
    # Hesitation detected: step the grade down one notch, floored at Hard.
    return max(1, grade - 1), True, (
        f"took {ratio:.1f}\u00d7 your usual time \u2014 scheduled as "
        f"{['Again', 'Hard', 'Good', 'Easy'][max(1, grade - 1)]} rather than "
        f"{['Again', 'Hard', 'Good', 'Easy'][grade]}")

INITIAL_CRITERION_STREAK = 3      # consecutive correct recalls to finish initial learning
RELEARN_SESSIONS_REQUIRED = 3     # further correct recalls, each on a separate day

def log_review(conn, card_id, rating, duration_ms=None):
    """Append-only log of one graded review, the raw material FSRS
    parameter re-optimization needs (see review_log's creation comment in
    init_schema). Called alongside, not instead of, save_card_state -- this
    never overwrites, only appends."""
    conn.execute("INSERT INTO review_log (card_id, rating, reviewed_at, duration_ms) "
                 "VALUES (?,?,?,?)",
                 (card_id, rating, datetime.now().isoformat(), duration_ms))
    conn.commit()

def apply_successive_relearning_criterion(state, correct):
    """Rawson & Dunlosky (2011, Journal of Experimental Psychology: General
    140:283-302; 2022, Current Directions in Psychological Science
    31:362-368): the prescriptively optimal schedule is practice to an
    INITIAL criterion of 3 consecutive correct recalls, then relearning to 1
    correct recall in each of 3 further sessions spaced on separate days --
    field-replicated on a high-stakes exam (Janes et al. 2020). A card is
    not "successive-relearning mastered" merely because FSRS has pushed its
    interval out after a couple of good reviews; this layer tracks the
    stricter criterion on top of (not instead of) FSRS's own scheduling.

    Mutates and returns `state` in place; caller still saves it via
    save_card_state exactly as before."""
    today_iso = date.today().isoformat()
    if not state.get("initial_criterion_met"):
        if correct:
            state["initial_streak"] = state.get("initial_streak", 0) + 1
            if state["initial_streak"] >= INITIAL_CRITERION_STREAK:
                state["initial_criterion_met"] = True
                # The day initial learning is completed doesn't itself count
                # as a spaced relearning session -- spacing requires a LATER
                # separate day, which is the entire point of the criterion.
                # Stamping today here is what enforces that: the same-day
                # test below compares against it, so a fourth correct
                # answer this afternoon cannot be counted as session 1.
                state["relearn_last_date"] = today_iso
        else:
            state["initial_streak"] = 0
        return state
    # Initial criterion already met: count a correct recall on a NEW
    # calendar day (relative to the last one counted) as one relearning
    # session. A correct answer on the SAME day as the last counted session,
    # or a second correct answer later the same day, does not add a second
    # session -- same-day repetition is not spaced practice.
    if correct and state.get("relearn_last_date") != today_iso:
        state["relearn_sessions_completed"] = state.get("relearn_sessions_completed", 0) + 1
        state["relearn_last_date"] = today_iso
        if state["relearn_sessions_completed"] >= RELEARN_SESSIONS_REQUIRED:
            state["successive_relearning_complete"] = True
    # A wrong answer after the initial criterion does NOT reset progress
    # toward the 3 completed sessions -- Rawson & Dunlosky's protocol
    # measures sessions where the criterion was met, not a fragile streak;
    # FSRS's own stability/interval already responds to the miss.
    return state

def _state_to_fsrs_card(state):
    return _fsrs_lib.Card(
        state=_fsrs_lib.State(state.get("state") or 1),
        step=state.get("step"),
        stability=state.get("stability"),
        difficulty=state.get("difficulty"),
        due=_dt_from_iso(state.get("due_date")) if state.get("due_date") else _dt_now(),
        last_review=_dt_from_iso(state["last_reviewed"]) if state.get("last_reviewed") else None,
    )

# FSRS stability is the interval at which retrievability falls to 0.9, not
# a half-life; the fallback's exponential model needs the R=0.5 point.
_FSRS_STABILITY_TO_HALFLIFE = math.log(2) / math.log(1 / 0.9)   # ~6.58

def _fallback_halflife(state):
    """Half-life (days) for the fallback scheduler, whichever scheduler
    wrote the row. FSRS always stores a difficulty in 1..10; the heuristic
    has no such notion and writes None (older heuristic rows wrote exactly
    5.0). Reading an FSRS stability as a half-life under-reported recall
    (0.5 instead of 0.9 at t=S) and would flood the deck the day `fsrs`
    went missing."""
    stab = state.get("stability") or 1.0
    d = state.get("difficulty")
    if d is not None and d != 5.0:
        return stab * _FSRS_STABILITY_TO_HALFLIFE
    return stab

def predicted_recall(state, as_of=None):
    """Current retrievability -- probability of correct recall right now."""
    if not state.get("last_reviewed"):
        return 0.0
    if FSRS_AVAILABLE:
        try:
            card = _state_to_fsrs_card(state)
            when = _dt_from_iso(as_of.isoformat()) if hasattr(as_of, "isoformat") else _dt_now()
            sched = _fsrs_lib.Scheduler()  # retrievability query doesn't depend on desired_retention
            return sched.get_card_retrievability(card, current_datetime=when)
        except (ValueError, TypeError, AttributeError, AssertionError):
            pass
    # Fallback: simple exponential decay with the half-life as time constant.
    when = _dt_from_iso(as_of.isoformat()) if hasattr(as_of, "isoformat") else _dt_now()
    last = _dt_from_iso(state["last_reviewed"])
    elapsed = max(0.0, (when - last).total_seconds() / 86400.0)
    return 0.5 ** (elapsed / max(0.1, _fallback_halflife(state)))

def _carry_relearning(old_state, new_state):
    """hlr_update builds a FRESH dict of FSRS fields. The successive-
    relearning counters (initial_streak, initial_criterion_met,
    relearn_sessions_completed, relearn_last_date,
    successive_relearning_complete) were NOT carried across, so every call
    site that did `new = hlr_update(st, g); apply_successive_relearning_
    criterion(new, ...)` was applying the criterion to a state with zeroed
    counters: initial_streak reset to 1 on every single review and the
    criterion could never be met for any card. This restores continuity;
    the criterion function itself was always correct."""
    for k in ("initial_streak", "initial_criterion_met", "relearn_sessions_completed",
              "relearn_last_date", "successive_relearning_complete"):
        if k in old_state and k not in new_state:
            new_state[k] = old_state[k]
    return new_state

def hlr_update(state, grade, conn=None):
    """Record a flashcard review and return the new schedule.

    Name kept as `hlr_update` for compatibility with every call site across
    the app; internally this now runs the real FSRS-6 algorithm rather than
    the original half-life-regression heuristic. `grade` stays 0=Again,
    1=Hard, 2=Good, 3=Easy to match the existing UI buttons."""
    global FSRS_PARAMS_OK
    now = _dt_now()
    if FSRS_AVAILABLE:
        try:
            sched = _get_fsrs_scheduler(conn) if conn is not None else _fsrs_lib.Scheduler()
            card = _state_to_fsrs_card(state) if state.get("last_reviewed") else _fsrs_lib.Card()
            rating = _fsrs_lib.Rating(grade + 1)
            new_card, _log = sched.review_card(card, rating, review_datetime=now)
            # Full UTC timestamps on one clock: FSRS measures elapsed time
            # between last_review and the review instant, so a same-evening
            # repeat must read as minutes, not as a whole day because the
            # local date and the UTC clock disagreed about midnight.
            return _carry_relearning(state, {
                "stability": new_card.stability, "difficulty": new_card.difficulty,
                "state": int(new_card.state), "step": new_card.step,
                "reps": state.get("reps", 0) + 1,
                "due_date": new_card.due.isoformat(),
                "last_reviewed": now.isoformat(),
            })
        except (ValueError, TypeError, AttributeError, AssertionError, KeyError) as e:
            # Scheduling by the heuristic while the UI says FSRS-6 must not
            # be silent: record it, flag it, then degrade.
            FSRS_PARAMS_OK = False
            if conn is not None:
                _audit(conn, "fsrs_error", f"{type(e).__name__}: {e}; scheduled by fallback")
    # Fallback: original half-life heuristic, reached without `fsrs`
    # installed (or after an FSRS failure recorded above). Works in
    # half-life units; an FSRS-written row is converted on the way in and
    # the result carries no difficulty, which marks it as heuristic-scaled.
    p_recall = predicted_recall(state)
    hl = _fallback_halflife(state)
    if grade == 0:
        new_hl = max(0.5, hl * 0.5)
    else:
        bonus = {1: 1.2, 2: 1.8, 3: 2.6}[grade]
        difficulty_bonus = 1 + (1 - p_recall)
        new_hl = min(365.0, hl * bonus * difficulty_bonus)
    days_to_target = max(1, round(new_hl * math.log(1 / TARGET_RECALL, 2)))
    return _carry_relearning(state, {"stability": round(new_hl, 3), "difficulty": None, "state": 2, "step": None,
            "reps": state.get("reps", 0) + 1,
            "due_date": (now + timedelta(days=days_to_target)).isoformat(),
            "last_reviewed": now.isoformat()})

# ============================================================================
# SEMANTIC FAILURE ANALYSIS (optional -- sentence-transformers)
# ============================================================================

_EMBED_MODEL = None
_EMBED_CACHE_PATH = os.path.join(APP_DIR, "embeddings_cache.json")
_EMBED_LOAD_FAILED_AT = None
_NLI_LOAD_FAILED_AT = None
_LOAD_RETRY_COOLDOWN = 300   # seconds before retrying a failed model load

_SEMANTIC_AVAILABLE_CACHE = None
_SEMANTIC_CHECK_FAILED_AT = None

def semantic_available(force=False):
    """NOTE: the first call actually imports sentence_transformers, which
    pulls in transformers/torch and can block for many seconds. Callers on
    the UI thread must treat this as expensive -- it is cached after the
    first call, and background loaders should probe it from inside their
    worker thread rather than before starting it.

    A FAILED check previously cached forever for the life of the running
    process -- if the real cause was transient or external (a stray
    secrets.py shadowing the stdlib module was one actual case), fixing it
    while the app kept running had no effect until a full restart, because
    nothing ever re-checked. Failures now expire after the same cooldown the
    model loaders use, and `force=True` (wired to a "Check again" button)
    bypasses the cooldown entirely for an immediate manual re-check."""
    global _SEMANTIC_AVAILABLE_CACHE, _SEMANTIC_CHECK_FAILED_AT
    if _SEMANTIC_AVAILABLE_CACHE is True:
        return True
    if not force and _SEMANTIC_CHECK_FAILED_AT is not None and \
            (time.time() - _SEMANTIC_CHECK_FAILED_AT) < _LOAD_RETRY_COOLDOWN:
        return False
    try:
        # find_spec answers "is it installed?" WITHOUT executing the package.
        # This used to be a real `import sentence_transformers`, which pulls
        # in transformers and torch (measured: ~800 MB RSS and several
        # seconds) merely to answer a yes/no question -- and triggered the
        # Hugging Face Hub call responsible for the "unauthenticated
        # requests to the HF Hub" warning at startup. The actual import now
        # happens only in _get_embed_model(), where the model is genuinely
        # needed and the caller is already on a background thread.
        import importlib.util
        found = importlib.util.find_spec("sentence_transformers") is not None
        _SEMANTIC_AVAILABLE_CACHE = found
        _SEMANTIC_CHECK_FAILED_AT = None if found else time.time()
    except Exception:
        _SEMANTIC_AVAILABLE_CACHE = False
        _SEMANTIC_CHECK_FAILED_AT = time.time()
    return _SEMANTIC_AVAILABLE_CACHE

def semantic_available_cached():
    """Non-blocking view of semantic availability for UI-thread callers.
    Returns None when not yet determined, so the UI can render a neutral
    'checking...' state instead of freezing on the import."""
    return _SEMANTIC_AVAILABLE_CACHE

def reset_semantic_check():
    """Force the next semantic_available() call to actually re-import,
    bypassing both the success cache and the failure cooldown. Wired to a
    manual 'Check again' button so a user who just fixed the real cause
    (e.g. removed a shadowing file) doesn't have to wait out the cooldown or
    restart the whole app to see it take effect."""
    global _SEMANTIC_AVAILABLE_CACHE, _SEMANTIC_CHECK_FAILED_AT
    _SEMANTIC_AVAILABLE_CACHE = None
    _SEMANTIC_CHECK_FAILED_AT = None
    # The model loaders have their own independent failure-cooldown state;
    # clear those too so a manual recheck retries everything, not just the
    # base import.
    global _EMBED_LOAD_FAILED_AT, _NLI_LOAD_FAILED_AT
    _EMBED_LOAD_FAILED_AT = None
    _NLI_LOAD_FAILED_AT = None

def _get_embed_model(status_cb=None):
    """Loads (and caches) the local embedding model.

    Caches FAILURE as well as success: a slow or blocked connection means
    this call can take several seconds to time out, and both the Free
    Recall and Failure Explorer screens call it independently. Without a
    cooldown, opening either screen after a failed attempt silently retried
    the same slow failure from scratch every single time -- on a bad
    connection the app could feel like it was hanging repeatedly for no
    visible reason."""
    global _EMBED_MODEL, _EMBED_LOAD_FAILED_AT
    if _EMBED_MODEL is not None:
        return _EMBED_MODEL
    if _EMBED_LOAD_FAILED_AT is not None and (time.time() - _EMBED_LOAD_FAILED_AT) < _LOAD_RETRY_COOLDOWN:
        return None
    try:
        from sentence_transformers import SentenceTransformer
    except ImportError:
        return None
    if status_cb:
        status_cb("Loading local semantic model (first run downloads ~80MB)...")
    try:
        _EMBED_MODEL = SentenceTransformer("all-MiniLM-L6-v2")
    except Exception as e:
        _EMBED_LOAD_FAILED_AT = time.time()
        if status_cb:
            status_cb(f"Could not load model: {e}")
        return None
    return _EMBED_MODEL

# ---- NLI entailment (second, independent scoring channel for free recall) --
# The ASAG (automatic short-answer grading) literature -- SemEval-2013 Task 7
# framed short-answer grading explicitly as textual entailment, and recent
# analyses find NLI entailment against the reference is one of the strongest
# lightweight predictors of correctness. Cosine similarity alone misses two
# things entailment catches: a correct PARAPHRASE that scores only middling
# on raw word/embedding overlap, and a confident WRONG answer (negation,
# swapped roles) that can still look similar in embedding space. Uses a
# small local cross-encoder -- no cloud call, runs on CPU.

_NLI_MODEL = None

def _get_nli_model(status_cb=None):
    global _NLI_MODEL, _NLI_LOAD_FAILED_AT
    if _NLI_MODEL is not None:
        return _NLI_MODEL
    if _NLI_LOAD_FAILED_AT is not None and (time.time() - _NLI_LOAD_FAILED_AT) < _LOAD_RETRY_COOLDOWN:
        return None
    try:
        from sentence_transformers import CrossEncoder
    except ImportError:
        return None
    if status_cb:
        status_cb("Loading local entailment model (first run downloads ~90MB)...")
    try:
        _NLI_MODEL = CrossEncoder("cross-encoder/nli-MiniLM2-L6-H768")
    except Exception as e:
        _NLI_LOAD_FAILED_AT = time.time()
        if status_cb:
            status_cb(f"Could not load entailment model: {e}")
        return None
    return _NLI_MODEL

def nli_entailment_prob(nli_model, premise, hypothesis):
    """P(premise entails hypothesis). Premise = the learner's own answer,
    hypothesis = the authored reference -- this asks 'if what the learner
    wrote is true, does it imply the reference fact is also true', which is
    the direction that rewards correct paraphrase and penalizes omission or
    contradiction (a negated or reversed claim scores as contradiction, not
    entailment, even when it shares most of the same words).

    Handles the model's label ordering defensively: NLI cross-encoders don't
    all agree on whether index 0 or 1 is 'entailment', so this reads the
    model's own label map when available instead of assuming a fixed order."""
    try:
        scores = nli_model.predict([(premise, hypothesis)], apply_softmax=True)
        row = scores[0] if hasattr(scores[0], "__len__") else scores
        entail_idx = 1
        try:
            id2label = nli_model.model.config.id2label
            for idx, label in id2label.items():
                if "entail" in str(label).lower():
                    entail_idx = int(idx)
                    break
        except Exception:
            pass
        return float(row[entail_idx])
    except Exception:
        return None

def _load_embed_cache():
    ensure_app_dir()
    if os.path.exists(_EMBED_CACHE_PATH):
        try:
            with open(_EMBED_CACHE_PATH) as f:
                return json.load(f)
        except Exception:
            return {}
    return {}

def _save_embed_cache(cache):
    ensure_app_dir()
    with open(_EMBED_CACHE_PATH, "w") as f:
        json.dump(cache, f)

def cosine(a, b):
    return sum(x * y for x, y in zip(a, b))

def get_question_embeddings(model):
    cache = _load_embed_cache()
    missing = [q for q in QUIZ_LIST if q["id"] not in cache]
    if missing:
        texts = [f"{q['q']} {q['exp']}" for q in missing]
        vecs = model.encode(texts, show_progress_bar=False, normalize_embeddings=True)
        for q, v in zip(missing, vecs):
            cache[q["id"]] = [float(x) for x in v]
        _save_embed_cache(cache)
    return cache

def get_note_embeddings(model):
    cache = _load_embed_cache()
    missing = [t for t in TOPICS.values() if ("note::" + t["id"]) not in cache]
    if missing:
        texts = [t["notes"] for t in missing]
        vecs = model.encode(texts, show_progress_bar=False, normalize_embeddings=True)
        for t, v in zip(missing, vecs):
            cache["note::" + t["id"]] = [float(x) for x in v]
        _save_embed_cache(cache)
    return cache

def cluster_failure_points(conn, model, threshold=0.55):
    q_cache = get_question_embeddings(model)
    rows = conn.execute("""SELECT DISTINCT question_id FROM attempts
                            WHERE correct=0 AND question_id NOT LIKE 'gen-%'""").fetchall()
    ids = [r["question_id"] for r in rows if r["question_id"] in q_cache]
    if len(ids) < 2:
        return []
    clusters = []
    for qid in ids:
        v = q_cache[qid]
        best_cluster, best_sim = None, -1.0
        for c in clusters:
            sim = cosine(v, c["centroid"])
            if sim > best_sim:
                best_sim, best_cluster = sim, c
        if best_cluster is not None and best_sim >= threshold:
            best_cluster["members"].append(qid)
            n = len(best_cluster["members"])
            best_cluster["centroid"] = [(best_cluster["centroid"][i] * (n - 1) + v[i]) / n
                                         for i in range(len(v))]
        else:
            clusters.append({"members": [qid], "centroid": list(v)})
    clusters = [c for c in clusters if len(c["members"]) >= 2]
    clusters.sort(key=lambda c: len(c["members"]), reverse=True)
    return clusters

def get_cluster_boost_ids(conn, max_size=12, max_share=0.30):
    """Question IDs belonging to the failure cluster the user is currently
    most concentrated in -- used to bias adaptive item selection toward the
    specific concept they keep confusing, rather than leaving semantic
    clustering as a purely descriptive Failure Explorer display with no
    effect on what gets served next.

    Capped deliberately. Uncapped, the largest cluster reached ~47% of all
    distinct misses on realistic data, which is not concept-targeting at
    all -- it is a blanket "prefer things you got wrong" bias, something the
    Thompson topic sampler already does more defensibly. A boost is only
    meaningful if it points at a genuinely narrow slice, so the cluster is
    rejected when it exceeds either an absolute size cap or a share of all
    misses.

    Deliberately never triggers a fresh model download: if the embedding
    model hasn't already been warmed up by a prior visit to Free Recall or
    the Explorer, this returns an empty set immediately rather than
    blocking the adaptive item-selection path on a first-time load."""
    if _EMBED_MODEL is None:
        return set()
    try:
        clusters = cluster_failure_points(conn, _EMBED_MODEL)
    except Exception:
        return set()
    if not clusters:
        return set()
    biggest = max(clusters, key=lambda c: len(c["members"]))
    members = set(biggest["members"])
    if len(members) > max_size:
        return set()
    try:
        distinct_missed = conn.execute(
            "SELECT COUNT(DISTINCT question_id) c FROM attempts WHERE correct=0"
        ).fetchone()["c"] or 0
    except Exception:
        distinct_missed = 0
    if distinct_missed and (len(members) / distinct_missed) > max_share:
        return set()
    return members

def describe_cluster(conn, cluster):
    from collections import Counter
    members = cluster["members"]
    topic_counts = Counter(QUIZ_BANK[m]["topic"] for m in members if m in QUIZ_BANK)
    # API-based clustering (see cluster_via_api) has the model nominate its
    # own representative item directly, since it has no embedding centroid
    # to measure cosine distance against. Only fall back to the centroid
    # method when one is actually present.
    rep_id = cluster.get("rep_id")
    if not rep_id or rep_id not in QUIZ_BANK:
        if cluster.get("centroid") is not None:
            q_cache = _load_embed_cache()
            rep_id = max(members, key=lambda m: cosine(q_cache[m], cluster["centroid"]))
        else:
            rep_id = members[0]
    rep_q = QUIZ_BANK.get(rep_id)
    placeholders = ",".join("?" * len(members))
    stats = conn.execute(
        f"SELECT error_type FROM attempts WHERE question_id IN ({placeholders}) AND correct=0",
        members).fetchall()
    error_type_counts = Counter(s["error_type"] for s in stats if s["error_type"])
    return {"members": members, "topic_counts": topic_counts, "rep_q": rep_q,
            "error_type_counts": error_type_counts}

