def pick_font(preferred_list, default):
    try:
        available = set(tkfont.families())
    except Exception:
        return default
    for name in preferred_list:
        if name in available:
            return name
    return default

FONT_DISPLAY = None   # resolved once a Tk root exists
FONT_BODY = None
FONT_MONO = None

def resolve_fonts():
    global FONT_DISPLAY, FONT_BODY, FONT_MONO
    FONT_DISPLAY = pick_font(["Georgia", "Constantia", "Palatino Linotype", "DejaVu Serif", "Times New Roman"], "Times New Roman")
    FONT_BODY = pick_font(["Segoe UI", "Helvetica Neue", "Helvetica", "Arial", "DejaVu Sans"], "Arial")
    FONT_MONO = pick_font(["Consolas", "Menlo", "DejaVu Sans Mono", "Courier New"], "Courier New")

