def run_adversarial_catalogue(names=None, verify_probes=True):
    """Run the catalogue headless and report per class.

    Each probe gets its OWN temporary database, because a probe that inserts
    rows must not decide what the next probe sees. `verify_probes` runs the
    injected instance of each class as well; leaving it off makes the run
    faster and the result weaker, and the report says which it was."""
    import shutil
    entries = []
    for name, spec in ADVERSARIAL_CLASSES.items():
        if names and name not in names:
            continue
        row = {"name": name, "title": spec["title"],
               "failure_class": spec["failure_class"],
               "invariant": spec["invariant"], "found_in": spec["found_in"],
               "passed": None, "detail": "", "caught_injection": None,
               "injection_detail": ""}
        for inject in ((False, True) if verify_probes else (False,)):
            conn, tmp = _probe_db()
            try:
                ok, detail = spec["probe"](conn, inject=inject)
            except Exception as e:
                ok, detail = False, f"the probe raised {type(e).__name__}: {e}"
            finally:
                try:
                    conn.close()
                except sqlite3.Error:
                    pass
                shutil.rmtree(tmp, ignore_errors=True)
            if inject:
                # The injected instance must FAIL. A probe that passes it is
                # not checking anything.
                row["caught_injection"] = (not ok)
                row["injection_detail"] = detail
            else:
                row["passed"] = bool(ok)
                row["detail"] = detail
        entries.append(row)
    failed = [e for e in entries if not e["passed"]]
    unfalsifiable = [e for e in entries if e["caught_injection"] is False]
    return {"entries": entries, "n": len(entries),
            "n_failed": len(failed), "n_unfalsifiable": len(unfalsifiable),
            "verified": bool(verify_probes),
            "ok": not failed and not unfalsifiable}


def adversarial_catalogue_report(result):
    """The run as plain lines, for a log or a console."""
    out = [f"adversarial catalogue: {result['n']} classes, "
           f"{result['n'] - result['n_failed']} pass, "
           f"{result['n_failed']} fail"
           + (f", {result['n_unfalsifiable']} unfalsifiable"
              if result["n_unfalsifiable"] else "")]
    for e in result["entries"]:
        mark = "PASS" if e["passed"] else "FAIL"
        out.append(f"  [{mark}] {e['name']}: {e['detail']}")
        if e["caught_injection"] is False:
            out.append(f"         UNFALSIFIABLE — the injected instance of "
                       f"this class also passed: {e['injection_detail']}")
    return "\n".join(out)


# ===========================================================================
# WIDER POLICY COVERAGE
# ===========================================================================
# Governance handled three policy kinds. The schema was always generic; only
# the proposers were narrow. These add the artefact kinds the blueprint
# treats as equally patchable -- prompts and thresholds -- so a change to
# how the app talks or when it intervenes goes through the same gate as a
# change to item difficulty.

GOVERNED_POLICY_KINDS = (
    "difficulty_priors", "unreliable_set", "routing_policy",
    "hint_prompt", "thresholds",
)

def default_thresholds():
    """Resolved lazily. As a module-level dict this evaluated at import time,
    before the constants it references were defined further down the
    assembled file -- a NameError on startup. Reading them at call time also
    means a constant edited elsewhere stays the single source of truth."""
    return {
        "competence_gate_mastery": globals().get("COMPETENCE_GATE_MASTERY", 0.55),
        "unreliable_selection_weight": globals().get("UNRELIABLE_SELECTION_WEIGHT", 0.35),
        "calibration_max_boost": globals().get("CALIBRATION_MAX_BOOST", 0.45),
        "cue_floor_rate": globals().get("CUE_FLOOR_RATE", 0.25),
        # Spec 7 knobs, read at their call sites through active_threshold.
        "target_p_A": 0.86, "target_p_B": 0.80, "target_p_C": 0.76,
        "phase_b_min_sessions": 5, "phase_c_min_solid": 15, "phase_min_dwell": 3,
        "sliding_acc": 0.50, "retest_max_per_session": 3, "pool_floor": 12,
        # Dispersion, not latency: on the seeded histories the observed CV of
        # a five-item window sits around 0.54 (p75 0.67, p90 0.78), so 0.75
        # fires on the genuinely uneven tail rather than on ordinary spread.
        "rt_variability_cv": 0.75,
        "ladder_rung2_min_solid": 20, "ladder_rung3_acc": 0.70, "ladder_rung4_acc": 0.70,
        # Directive XII's two weights. Information is worth having but it is
        # not learning, and time is the one resource the learner cannot get
        # more of, so both sit well below the gain term they trade against.
        "objective_lambda_info": 0.35, "objective_lambda_cost": 0.25,
    }

def active_threshold(conn, name, default=None, key=None):
    """Read a tunable through the governed path, falling back to the shipped
    constant. This is what makes a threshold a versioned artefact rather
    than a number someone once chose. `key` is the decision the threshold
    is being applied to (an item or session id) so a canary governs a share
    of decisions; without one the name stands in."""
    gov = active_policy(conn, "thresholds", default=None,
                        key=key or f"thresholds:{name}")
    if gov and name in gov:
        v = gov[name]
        if isinstance(v, (int, float)) and math.isfinite(v):
            return float(v)
    return default_thresholds().get(name, default)

def propose_thresholds(conn):
    """Propose threshold adjustments from the VISIBLE slice only.

    Deliberately small steps. A proposer that can move a threshold from 0.55
    to 0.95 in one promotion is not tuning, it is thrashing -- and the
    sealed gate cannot catch that, because a large move may still score
    marginally better."""
    visible, _sealed = split_attempts(conn)
    if len(visible) < 60:
        return {}
    # Step from the value CURRENTLY in force, not the shipped constant:
    # stepping from the constant re-proposed the same number every run once
    # it had been promoted, and a proposal equal to what is live is not a
    # proposal.
    live = active_policy(conn, "thresholds", default=None, staged=False) or {}
    def current(name):
        v = live.get(name)
        return float(v) if isinstance(v, (int, float)) else default_thresholds()[name]
    out = {}
    # If flagged items are almost never released, the gate may be too tight.
    try:
        gated = len(gated_item_ids(conn))
        cur = current("competence_gate_mastery")
        if gated > len(QUIZ_LIST) * 0.25:
            out["competence_gate_mastery"] = round(max(0.35, cur - 0.05), 3)
        elif gated == 0:
            out["competence_gate_mastery"] = round(min(0.75, cur + 0.05), 3)
    except (sqlite3.Error, KeyError, TypeError, ValueError) as e:
        _audit(conn, "propose_thresholds_failed", f"{type(e).__name__}: {e}")
    # The phase-A success target must be one the bank can serve: at a low
    # theta the easiest item may sit below 0.86, and a target no item can
    # reach is a target the composer quietly ignores. Proposed from the
    # visible rows' theta, one small step at a time.
    try:
        theta = _theta_from_rows(visible)
        reachable = round(min(0.86, bank_max_p(theta) - 0.02), 2)
        cur = current("target_p_A")
        if reachable < cur - 0.005:
            out["target_p_A"] = round(max(reachable, cur - 0.05), 2)
    except (KeyError, TypeError, ValueError) as e:
        _audit(conn, "propose_thresholds_failed", f"target_p_A {type(e).__name__}: {e}")
    return {k: v for k, v in out.items() if abs(v - current(k)) >= 0.005}

def run_full_improvement_cycle(conn, activate=False):
    """Every governed policy kind, each through gate -> shadow -> rung ->
    stage. Nothing reaches full release without clearing the shadow trial."""
    init_governance_schema(conn)
    init_staging_schema(conn)
    proposals = propose_policies(conn)
    proposals.pop("_n_visible", None)
    try:
        th = propose_thresholds(conn)
        if th:
            proposals["thresholds"] = th
    except Exception:
        pass

    # n_visible is what the panel reports as the evidence base for these
    # proposals; the flat cycle returned it and this one did not, so the UI
    # rendered "Proposed from None visible observations".
    try:
        _vis, _sealed = split_attempts(conn)
        _n_visible = len(_vis)
    except sqlite3.Error as e:
        _audit(conn, "split_attempts_failed", f"{type(e).__name__}: {e}")
        _n_visible, _sealed = None, []
    report = {"results": {}, "release_id": None, "stage": None,
              "n_visible": _n_visible, "n_sealed": (len(_sealed) if _sealed else 0)}
    members = {}
    best_rung = 4
    for kind, body in proposals.items():
        baseline = active_policy(conn, kind, staged=False,
                                 default=([] if kind == "unreliable_set" else {}))
        decision = evaluate_candidate(conn, kind, body, baseline)
        shadow = None
        if decision.get("verdict") == "promote":
            try:
                shadow = shadow_trial(conn, kind, body)
            except Exception as e:
                _audit(conn, "shadow_trial_failed", f"{kind} {type(e).__name__}: {e}")
                shadow = None
        rung = classify_evidence_rung(decision, shadow,
                                      prior_confirmations=prior_confirmations(conn, kind))
        rev = write_revision(conn, kind, body, proposer="auto_proposer",
                             n_visible=_n_visible)
        record_decision(conn, kind, rev, None,
                        {**decision, "reason": decision.get("reason", "")
                         + f" | rung: {rung['label']}"})
        report["results"][kind] = {**decision, "revision_id": rev,
                                   "rung": rung, "shadow": shadow,
                                   "size": len(body)}
        if decision.get("verdict") == "promote":
            members[kind] = rev
            best_rung = min(best_rung, rung["rung"])

    if members and activate:
        rid = create_release(conn, members, note="staged improvement cycle")
        # Stage FIRST, then activate only what the stage lets govern. A
        # shadow release is recorded and inspectable but never becomes the
        # active pointer -- activating it and then labelling it "0% of
        # selections" made the label false for every kind at once.
        staged = stage_release(conn, rid, rung_record(
            best_rung, why="weakest member's rung governs the release"))
        if staged["stage"] != "shadow":
            activate_release(conn, rid, reason="passed gate; staged by evidence rung")
        report["release_id"] = rid
        report["stage"] = staged
    return report


# ===========================================================================
# A REAL GENERATOR FOR THE FACTORY
# ===========================================================================
# run_factory() takes a `generator` argument and nothing ever supplied one,
# so the whole verified-authoring pipeline sat downstream of content that
# never arrived. This supplies a DETERMINISTIC generator: it cannot invent
# prose, but it can assemble a genuine candidate from template-backed math
# items, whose keys are correct by construction.
#
# Stated plainly: this activates the pipeline for the one family that can be
# generated safely without a model. Structural, adversarial and
# compositional candidates still return contracts for authoring, because
# faking them would produce paraphrases that measure nothing.

def deterministic_generator(packet):
    """Assemble a candidate for the factory without any model.

    Returns None when it cannot do so honestly, which is most of the time --
    and that is the correct behaviour, not a failure."""
    topic = packet.get("topic")
    if topic != "t10":
        return None            # only math is template-backed
    skill = packet["target_distinction"]["skill"]
    raw = generate_math_item()
    return {"topic": topic,
            "skills": [skill] if skill else [],
            "q": raw["q"], "opts": raw["opts"], "a": raw["a"],
            "exp": raw.get("exp", ""),
            "source": (packet.get("approved_sources") or ["computed by construction"])[0],
            "provenance": "deterministic_template",
            "note": "Key computed by construction; no model involved."}

def factory_with_generator(conn, target=None, knowledge_dependence_fn=None):
    """Run the factory with the deterministic generator attached.

    The generator refuses most targets (only maths is template-backed), so
    with no explicit target the audit's list is walked in order until one
    is accepted by the generator; the report says which targets were
    passed over, so "no_candidate" on the shipped bank is a statement about
    every target rather than about whichever happened to sort first."""
    if target is not None:
        return run_factory(conn, target=target, generator=deterministic_generator,
                           knowledge_dependence_fn=knowledge_dependence_fn)
    skipped = []
    last = None
    for tgt in factory_targets(conn, limit=None):
        last = run_factory(conn, target=tgt, generator=deterministic_generator,
                           knowledge_dependence_fn=knowledge_dependence_fn)
        if last.get("status") != "no_candidate":
            last["skipped_targets"] = skipped
            return last
        skipped.append({"topic": tgt["topic"], "skill": tgt.get("skill")})
    if last is None:
        return {"status": "no_targets",
                "note": "The audit found nothing the bank cannot already separate."}
    last["skipped_targets"] = skipped
    last["note"] = (f"The generator declined all {len(skipped)} audit target(s): only "
                    "template-backed maths can be produced without a model.")
    return last


# ===========================================================================
# THE CANDIDATE BANK  --  generated content never enters the live bank directly
# ===========================================================================
# Every generative target in the review shares one prerequisite: somewhere
# for a candidate to LIVE while it is being checked. Writing generated items
# straight into the quiz bank would make generation irreversible and put
# unreviewed content in front of a learner, which is precisely what the
# governance work exists to prevent.
#
# So candidates land in a versioned staging bank with their own lifecycle:
#
#   draft -> verified -> approved -> promoted        (or -> rejected)
#
# Only `promoted` items are ever served, and promotion is a human action.
# The generator, the solver, the verifier and the approver are four
# different authorities, and none of them can do another's job.
#
# Everything below except the generation call itself works with no model.

CANDIDATE_STATES = ("draft", "verified", "rejected", "approved", "promoted")

# The lifecycle above, as the moves that are actually legal. A rejected
# candidate has to go back through the gates (-> draft) before it can be
# served; nothing jumps straight from draft to promoted. Re-entering the
# current state is a no-op that is allowed, so a verifier can re-record
# its notes on a row without an illegal-move failure.
CANDIDATE_TRANSITIONS = {
    "draft":    {"verified", "rejected"},
    # verified -> approved -> promoted are human moves: they exist in this
    # table so the lifecycle is complete, and set_candidate_state refuses them
    # to any caller without the approval authority (PRIVILEGED_CANDIDATE_MOVES).
    "verified": {"approved", "rejected"},
    "approved": {"promoted", "rejected"},
    "promoted": {"rejected"},
    "rejected": {"draft"},
}

def init_candidate_schema(conn):
    conn.executescript("""
    CREATE TABLE IF NOT EXISTS candidate_items (
        candidate_id  INTEGER PRIMARY KEY AUTOINCREMENT,
        created_at    TEXT NOT NULL,
        state         TEXT NOT NULL DEFAULT 'draft',
        family        TEXT,
        seed_id       TEXT,
        topic         TEXT,
        skills        TEXT,
        stem          TEXT NOT NULL,
        options       TEXT NOT NULL,
        answer        INTEGER NOT NULL,
        explanation   TEXT,
        source        TEXT,
        provenance    TEXT,
        generator     TEXT,
        solver_answer INTEGER,
        solver_agrees INTEGER,
        verify_notes  TEXT,
        separation    REAL,
        reviewed_at   TEXT,
        reviewer_note TEXT
    );
    """)
    conn.commit()

def store_candidate(conn, cand, generator="unknown"):
    """Persist a candidate as a draft. Nothing is served from here."""
    init_candidate_schema(conn)
    cur = conn.execute("""INSERT INTO candidate_items
        (created_at, state, family, seed_id, topic, skills, stem, options,
         answer, explanation, source, provenance, generator)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (datetime.now().isoformat(), "draft", cand.get("family", "structural"),
         cand.get("seed_id"), cand.get("topic"),
         json.dumps(cand.get("skills", [])), cand.get("q", ""),
         json.dumps(cand.get("opts", [])), int(cand.get("a", 0)),
         cand.get("exp", ""), cand.get("source", ""),
         cand.get("provenance", ""), generator))
    conn.commit()
    _audit(conn, "candidate_stored", f"id={cur.lastrowid} by={generator}")
    return cur.lastrowid

def candidates(conn, state=None, limit=50):
    sql = "SELECT * FROM candidate_items"
    params = []
    if state:
        sql += " WHERE state=?"
        params.append(state)
    sql += " ORDER BY candidate_id DESC LIMIT ?"
    params.append(limit)
    init_candidate_schema(conn)
    return _safe_query(conn, sql, tuple(params))

def set_candidate_state(conn, candidate_id, state, note="", authority=None):
    """Move a candidate along its lifecycle. Returns False, and changes
    nothing, for an unknown state, an unknown row or an illegal move --
    the guard is what makes "only promoted items are served" a property
    rather than a convention."""
    if state not in CANDIDATE_STATES:
        return False
    init_candidate_schema(conn)
    row = conn.execute("SELECT state FROM candidate_items WHERE candidate_id=?",
                       (candidate_id,)).fetchone()
    if row is None:
        return False
    current = row["state"] or "draft"
    if (current, state) in PRIVILEGED_CANDIDATE_MOVES and authority is not _HUMAN_APPROVAL:
        _audit(conn, "candidate_state_refused",
               f"id={candidate_id} {current} -> {state} requires the human approval action")
        return False
    if state != current and state not in CANDIDATE_TRANSITIONS.get(current, set()):
        _audit(conn, "candidate_state_refused",
               f"id={candidate_id} {current} -> {state} is not a legal move")
        return False
    conn.execute("""UPDATE candidate_items SET state=?, reviewed_at=?, reviewer_note=?
                     WHERE candidate_id=?""",
                 (state, datetime.now().isoformat(), note[:300], candidate_id))
    conn.commit()
    _audit(conn, "candidate_state", f"id={candidate_id} {current} -> {state}")
    return True

# ===========================================================================
# THE CALIBRATION LADDER  --  practice content vs measurement content
# ===========================================================================
# A promoted candidate entered the selection pool and its first answer fed
# theta and DINA with a difficulty parameter that was an authored guess.
# That is the one thing generated content must never do: the learner model
# is only trustworthy because every parameter that updates it was either
# authored and reviewed or empirically fitted. Generated items are neither,
# on day one.
#
# So a candidate climbs a ladder, and only the top rung touches the model:
#
#   shadow      served for PRACTICE; answers recorded, model untouched
#   monitored   enough answers to estimate an empirical difficulty
#   calibrated  empirical difficulty is stable and non-degenerate; the item
#               now updates ability and mastery like an authored one
#   demoted     post-release diagnostics degraded; back to shadow
#
# This is the distinction between content that is useful to practise with
# and content trustworthy enough to change what the system believes.

LADDER_MIN_N = 8            # answers before an empirical difficulty means anything
LADDER_P_BAND = (0.12, 0.93)  # outside this the item is not measuring anything
LADDER_STABLE_WINDOW = 4    # last-N vs prior-N agreement required

def init_ladder_schema(conn):
    """Idempotent, and SAFE ON A READ-ONLY CONNECTION. The ladder is
    consulted from the ability estimator -- a read path -- so a schema
    migration that raises on a read-only database would take the whole
    learner model down with it. Migration failures are swallowed here and
    the reader degrades to 'no calibrated candidates', which is correct."""
    try:
        init_candidate_schema(conn)
        cols = {r[1] for r in conn.execute("PRAGMA table_info(candidate_items)")}
        if "ladder" not in cols:
            conn.execute("ALTER TABLE candidate_items ADD COLUMN ladder TEXT DEFAULT 'shadow'")
        if "empirical_b" not in cols:
            conn.execute("ALTER TABLE candidate_items ADD COLUMN empirical_b REAL")
        if "ladder_n" not in cols:
            conn.execute("ALTER TABLE candidate_items ADD COLUMN ladder_n INTEGER DEFAULT 0")
        if "calibrated_at" not in cols:
            conn.execute("ALTER TABLE candidate_items ADD COLUMN calibrated_at TEXT")
        conn.commit()
        return True
    except Exception:
        return False

_CAL_CACHE = {"key": None, "ids": set(), "since": {}}

def calibrated_candidate_since(conn):
    """{cand-id: calibrated_at} for every candidate on the top rung. Cached
    on the candidate table's row count, max id and calibrated count, so a
    promotion or a ladder change refreshes it and an ordinary answer does
    not. calibrated_at is None for rows calibrated before the column
    existed."""
    if not init_ladder_schema(conn):
        return {}                # read-only or no candidate table: nothing calibrated
    try:
        key = conn.execute("SELECT COUNT(*), COALESCE(MAX(candidate_id),0), "
                           "SUM(CASE WHEN ladder='calibrated' THEN 1 ELSE 0 END) "
                           "FROM candidate_items").fetchone()
        key = tuple(key)
    except Exception:
        return {}
    if _CAL_CACHE["key"] == key:
        return _CAL_CACHE["since"]
    since = {f"cand-{r['candidate_id']}": r["calibrated_at"] for r in _safe_query(
        conn, "SELECT candidate_id, calibrated_at FROM candidate_items WHERE ladder='calibrated'")}
    _CAL_CACHE.update(key=key, ids=set(since), since=since)
    return since

def calibrated_candidate_ids(conn):
    """The cand- ids allowed to update the learner model."""
    return set(calibrated_candidate_since(conn))

def model_feed_filter(conn, rows, id_key="question_id"):
    """Drop rows the learner model must not learn from: template items and
    uncalibrated candidates. One place, so every estimator agrees.

    A candidate's answers from BEFORE it reached the calibrated rung are
    dropped too: they were recorded against the placeholder difficulty
    (b_irt=0.0), not the fitted one, so letting them in at the moment of
    calibration would move theta by however many shadow answers the item
    collected, scored against a difficulty nobody believes. Rows that carry
    no timestamp (callers that did not select it) are gated by id only."""
    since = calibrated_candidate_since(conn)
    out = []
    for r in rows:
        q = r[id_key]
        if not q:
            continue
        # A transfer variant (var-<family>-<seed>) is a fresh template draw,
        # exactly as uncalibrated as the gen- seed it came from.
        if str(q).startswith(("gen-", VARIANT_ID_PREFIX + "-")):
            continue
        if str(q).startswith("cand-"):
            if q not in since:
                continue
            cal_at = since.get(q)
            try:
                ts = r["timestamp"]
            except (KeyError, IndexError):
                ts = None
            if cal_at and ts and str(ts) < str(cal_at):
                continue
        out.append(r)
    return out

def advance_ladder(conn):
    """Move candidates up (or down) the ladder from their own evidence.

    Runs after any session. Returns what changed, so it can be shown."""
    init_ladder_schema(conn)
    changes = []
    for r in _safe_query(conn, """SELECT candidate_id, ladder, empirical_b FROM
                                   candidate_items WHERE state='promoted'"""):
        qid = f"cand-{r['candidate_id']}"
        att = _safe_query(conn, """SELECT correct FROM attempts WHERE question_id=?
                                   ORDER BY id DESC LIMIT 40""", (qid,))
        n = len(att)
        # The rung an item must reach before its behaviour is identified even
        # for this one learner. Asking the registry rather than the constant
        # keeps this promotion and the author-facing ladder in step.
        if not capability_available(conn, "item_difficulty_within_learner",
                                    have=n)["available"]:
            new = "shadow"
        else:
            p = sum(1 for a in att if a["correct"]) / n
            lo, hi = LADDER_P_BAND
            if not (lo <= p <= hi):
                new = "monitored"           # degenerate: everyone or no one
            else:
                # stability: recent window agrees with the rest
                recent = att[:LADDER_STABLE_WINDOW]
                rest = att[LADDER_STABLE_WINDOW:]
                pr = sum(1 for a in recent if a["correct"]) / max(1, len(recent))
                po = (sum(1 for a in rest if a["correct"]) / max(1, len(rest))
                      if rest else pr)
                new = "calibrated" if abs(pr - po) <= 0.35 else "monitored"
            # empirical difficulty on the logit scale, anchored to theta
            try:
                theta = ability_with_se(conn)[0]
                p_c = min(max(p, 0.02), 0.98)
                emp_b = theta - math.log(p_c / (1 - p_c))
            except Exception:
                emp_b = None
            if emp_b is not None:
                conn.execute("UPDATE candidate_items SET empirical_b=? WHERE candidate_id=?",
                             (emp_b, r["candidate_id"]))
        if r["ladder"] == "calibrated" and new != "calibrated":
            new = "demoted"
        if new != (r["ladder"] or "shadow"):
            conn.execute("UPDATE candidate_items SET ladder=?, ladder_n=? WHERE candidate_id=?",
                         (new, n, r["candidate_id"]))
            if new == "calibrated":
                # The moment the item starts counting. model_feed_filter
                # uses this to keep the shadow-era answers (placeholder
                # difficulty) out of the model.
                conn.execute("UPDATE candidate_items SET calibrated_at=? WHERE candidate_id=?",
                             (datetime.now().isoformat(), r["candidate_id"]))
            changes.append({"candidate_id": r["candidate_id"], "from": r["ladder"],
                            "to": new, "n": n})
            _audit(conn, "ladder", f"cand-{r['candidate_id']}: {r['ladder']} -> {new} (n={n})")
    conn.commit()
    if changes:
        _CAL_CACHE["key"] = None
    return changes

def ladder_status(conn):
    init_ladder_schema(conn)
    rows = _safe_query(conn, """SELECT ladder, COUNT(*) n FROM candidate_items
                                 WHERE state='promoted' GROUP BY ladder""")
    return {(r["ladder"] or "shadow"): r["n"] for r in rows}

def promoted_candidates(conn):
    """Approved-and-promoted candidates, in the shape the app serves.

    Given ids prefixed `cand-` so every downstream analysis can tell
    generated content from authored content without a lookup -- the
    provenance distinction the whole pipeline rests on."""
    out = []
    init_ladder_schema(conn)
    for r in candidates(conn, state="promoted", limit=200):
        try:
            rung = r["ladder"] if "ladder" in r.keys() else "shadow"
            emp = r["empirical_b"] if "empirical_b" in r.keys() else None
            out.append({"id": f"cand-{r['candidate_id']}",
                        "topic": r["topic"], "q": r["stem"],
                        "opts": json.loads(r["options"]),
                        "a": r["answer"], "exp": r["explanation"] or "",
                        # Only a CALIBRATED item carries an empirical
                        # difficulty; below that rung the authored guess is
                        # kept but the item is filtered out of the model.
                        "b_irt": (emp if (rung == "calibrated" and emp is not None) else 0.0),
                        "a_irt": 1.0, "ladder": rung,
                        "source": r["source"] or "",
                        "generated": True,
                        "skills": json.loads(r["skills"] or "[]")})
        except Exception:
            continue
    return out


# ===========================================================================
# THE SAMPLE-SIZE LADDER  --  which model is identified, and by what
# ===========================================================================
# Directive VII states the constraint that binds everything after it: a
# transition model is estimated from many trajectories, one learner produces
# one trajectory, and the parameters are not identified from it. The
# consequence is a ladder of rungs -- n=1, ~10, ~100, ~1000 -- and the ladder
# is a schedule rather than an excuse.
#
# A schedule that lives in a document governs nothing. This makes it machinery:
# every model-bearing capability declares the quantity it needs to be
# identified, the threshold, and one sentence saying why that threshold and
# not a smaller one; `capability_available` computes the quantity from this
# database and answers; `require_capability` refuses, loudly, anything asked
# for below its threshold.
#
# The registry is deliberately the WHOLE picture. The capabilities already
# live at one learner are registered as satisfied, with the same declared
# requirement as the ones that are not, so the ladder reads as a position
# rather than as a list of absences.

CAPABILITY_QUANTITIES = {
    "learners":          "learners with a record in this database",
    "trajectories":      "learner trajectories (one learner contributes one)",
    "measurement_rows":  "measured responses",
    "distinct_items":    "distinct items with a measured response",
    "paired_occasions":  "randomised occasions paired against their reference arm",
    "item_exposures":    "answers to this one item",
    "routing_outcomes":  "recorded routing outcomes",
}

# Per-object quantities cannot be counted database-wide: "answers to this one
# item" is a property of an item, so the caller passes the count it holds.
CAPABILITY_PER_OBJECT = ("item_exposures",)

CAPABILITY_RUNGS = ("n=1", "~10 learners", "~100 learners", "~1000 learners")

CAPABILITIES = {}


class CapabilityNotIdentified(RuntimeError):
    """Raised when a model is asked for below the sample size that identifies it."""

    def __init__(self, gate):
        self.capability = gate["name"]
        self.gate = gate
        super().__init__(gate["refusal"])


def register_capability(name, **spec):
    """Declare a model-bearing capability and what identifies it.

    Four things are mandatory and none of them has a default: the quantity,
    the threshold, one plain sentence saying why THAT threshold, and what
    passing it unlocks. A capability that cannot say why its threshold is not
    smaller has not thought about identification, and registering it would
    put a number in the ladder that nobody can defend."""
    quantity = spec.get("quantity")
    if quantity not in CAPABILITY_QUANTITIES:
        raise ValueError(f"capability {name!r}: unknown quantity {quantity!r}")
    threshold = spec.get("threshold")
    if not isinstance(threshold, int) or threshold < 1:
        raise ValueError(f"capability {name!r}: threshold must be a positive integer")
    for field in ("label", "why", "unlocks"):
        if not str(spec.get(field) or "").strip():
            raise ValueError(f"capability {name!r}: must state {field}")
    rung = spec.get("rung")
    if rung not in CAPABILITY_RUNGS:
        raise ValueError(f"capability {name!r}: rung must be one of {CAPABILITY_RUNGS}")
    out = dict(spec)
    out["name"] = name
    out.setdefault("satisfied_by", "")
    out.setdefault("live", False)
    CAPABILITIES[name] = out
    return out


# ---- rung one: what one learner's own record identifies -------------------

