def capability_counts(conn):
    """Every database-wide quantity the registry can be measured against.

    One desktop database holds one learner's record: `learners` is therefore 0
    on an empty file and 1 once anything has been measured. Saying so plainly
    is the point -- an app that counted its own sessions as learners would
    climb its own ladder without a single new person."""
    counts = {q: 0 for q in CAPABILITY_QUANTITIES if q not in CAPABILITY_PER_OBJECT}
    rows = _safe_query(conn, "SELECT COUNT(*) c, COUNT(DISTINCT question_id) d "
                             "FROM attempts WHERE " + MEASUREMENT_ROW_SQL)
    if rows:
        counts["measurement_rows"] = rows[0]["c"] or 0
        counts["distinct_items"] = rows[0]["d"] or 0
    counts["learners"] = 1 if counts["measurement_rows"] else 0
    counts["trajectories"] = trajectory_counts(conn)["trajectories"]
    rows = _safe_query(conn, "SELECT COUNT(*) c FROM expert_invocations")
    counts["routing_outcomes"] = (rows[0]["c"] if rows else 0) or 0
    best = 0
    for name in INTERVENTION_TRIALS:
        try:
            st = intervention_trial_state(conn, name)
        except sqlite3.Error:
            continue
        for v in (st or {}).get("contrasts", {}).values():
            best = max(best, int(v.get("pairs") or 0))
    counts["paired_occasions"] = best
    return counts


def capability_available(conn, name, have=None, counts=None):
    """The gate. Is this capability identified by what this database holds?

    Returns the answer WITH its reason in both directions: an available
    capability says what makes it available, and an unavailable one states the
    distance and what would close it. Nothing here is advisory -- callers that
    fit a model go through `require_capability`, which raises on the same
    answer rather than degrading into a quiet no-op."""
    spec = CAPABILITIES.get(name)
    if spec is None:
        raise KeyError(f"unknown capability {name!r}")
    quantity = spec["quantity"]
    if quantity in CAPABILITY_PER_OBJECT:
        if have is None:
            raise ValueError(f"capability {name!r} is measured per object; "
                             f"pass have=<{quantity}>")
    elif have is None:
        have = (counts if counts is not None else capability_counts(conn)).get(quantity, 0)
    have = int(have or 0)
    needed = int(spec["threshold"])
    available = have >= needed
    qlabel = CAPABILITY_QUANTITIES[quantity]
    distance = max(0, needed - have)
    if available:
        reason = (f"Identified: {have} {qlabel} against the {needed} required. "
                  + spec["why"])
        refusal = ""
    else:
        reason = (f"Not identified: {have} of {needed} {qlabel}. " + spec["why"])
        refusal = (f"{spec['label']} is not identified here: {have} of {needed} "
                   f"{qlabel}, {distance} short. {spec['why']} "
                   f"What would satisfy it: {spec['satisfied_by']}")
    return {"name": name, "label": spec["label"], "rung": spec["rung"],
            "quantity": quantity, "quantity_label": qlabel,
            "have": have, "needed": needed, "distance": distance,
            "available": available, "why": spec["why"],
            "unlocks": spec["unlocks"], "satisfied_by": spec["satisfied_by"],
            "reason": reason, "refusal": refusal}


def require_capability(conn, name, have=None, counts=None):
    """Gate a fitting run. Returns the gate when identified; raises
    CapabilityNotIdentified, carrying the distance and what would close it,
    when it is not. Asking directly is not a way around the ladder."""
    gate = capability_available(conn, name, have=have, counts=counts)
    if not gate["available"]:
        _audit(conn, "capability_refused",
               f"{name}: {gate['have']}/{gate['needed']} {gate['quantity']}")
        raise CapabilityNotIdentified(gate)
    return gate


def fit_gated_model(conn, name, fitter, have=None):
    """The single door every fitting run goes through: gate, then fit.

    Nothing in this build may estimate a registered model without passing
    here, which is what makes the ladder enforcement rather than documentation."""
    gate = require_capability(conn, name, have=have)
    _audit(conn, "capability_fit", f"{name}: {gate['have']} {gate['quantity']}")
    return fitter(conn)


def capability_report(conn):
    """Every capability, its rung, where the data stands and what it unlocks --
    ordered by rung, so the report reads as a position on the ladder."""
    counts = capability_counts(conn)
    out = []
    for rung in CAPABILITY_RUNGS:
        for name, spec in CAPABILITIES.items():
            if spec["rung"] != rung:
                continue
            if spec["quantity"] in CAPABILITY_PER_OBJECT:
                # Per-object capabilities have no single database-wide count;
                # the ladder reports the requirement and the object it applies
                # to rather than inventing an aggregate.
                qlabel = CAPABILITY_QUANTITIES[spec["quantity"]]
                gate = {"name": name, "label": spec["label"], "rung": rung,
                        "quantity": spec["quantity"], "quantity_label": qlabel,
                        "have": None, "needed": int(spec["threshold"]),
                        "distance": None, "available": None,
                        "why": spec["why"], "unlocks": spec["unlocks"],
                        "satisfied_by": spec["satisfied_by"],
                        "reason": (f"Decided per item: {spec['threshold']} "
                                   f"{qlabel}. " + spec["why"]),
                        "refusal": ""}
            else:
                gate = capability_available(conn, name, counts=counts)
            out.append(gate)
    return {"counts": counts, "capabilities": out,
            "trajectories": trajectory_counts(conn)}


# ===========================================================================
# THE TRAJECTORY RECORD  --  built now, fitted when the ladder allows
# ===========================================================================
# Section VII's requirement at one learner is not the transition model; it is
# the record the model will eventually be fitted on. An occasion is written as
# the tuple a kernel is estimated from: the inferred state before, the action,
# HOW the action was assigned, the evidence observed, and the inferred state
# after -- at a delay long enough that the after-state is about retention
# rather than about the minute after the treatment.
#
# The state snapshots come from the same gatherers the learner-state contract
# reads, so the record cannot drift away from what the app believed at the
# time, and are stored as JSON because the state vector will change shape long
# before the kernel is fittable.

TRAJECTORY_LEARNER = "local"          # one database, one learner's record
TRAJECTORY_AFTER_DELAY_HOURS = 20.0   # an after-state sooner than this is the
                                      # treatment still echoing, not retention


def init_trajectory_schema(conn):
    conn.executescript("""
    CREATE TABLE IF NOT EXISTS state_trajectories (
        trajectory_id INTEGER PRIMARY KEY AUTOINCREMENT,
        learner       TEXT NOT NULL,
        occasion_key  TEXT NOT NULL,
        action        TEXT NOT NULL,
        assignment    TEXT NOT NULL,
        trial         TEXT,
        subject       TEXT,
        state_tag     TEXT,
        state_before  TEXT,
        opened_at     TEXT,
        evidence      TEXT,
        state_after   TEXT,
        closed_at     TEXT,
        delay_hours   REAL,
        UNIQUE (learner, occasion_key)
    );
    CREATE INDEX IF NOT EXISTS idx_trajectory_open
        ON state_trajectories(state_after, opened_at);
    """)
    conn.commit()
    _ensure_column(conn, "state_trajectories", "propensity", "REAL")
    _ensure_column(conn, "state_trajectories", "arm_set", "TEXT")


def open_trajectory(conn, occasion_key, action, assignment="policy", trial=None,
                    subject=None, state_tag=None, learner=TRAJECTORY_LEARNER,
                    propensity=None, arm_set=None):
    """Record the before-state of one intervention occasion.

    `assignment` is the field the eventual fit cannot do without: a randomised
    occasion supports a causal transition, a policy-assigned one supports a
    descriptive one, and a record that did not say which would make them
    indistinguishable later."""
    try:
        init_trajectory_schema(conn)
        close_due_trajectories(conn)
        _ensure_column(conn, "state_trajectories", "propensity", "REAL")
        _ensure_column(conn, "state_trajectories", "arm_set", "TEXT")
        conn.execute("INSERT OR IGNORE INTO state_trajectories "
                     "(learner, occasion_key, action, assignment, trial, subject, "
                     " state_tag, state_before, opened_at, propensity, arm_set) "
                     "VALUES (?,?,?,?,?,?,?,?,?,?,?)",
                     (learner, str(occasion_key), str(action),
                      "randomized" if assignment in ("trial", "randomized")
                      else "policy",
                      trial, None if subject is None else str(subject)[:200],
                      None if state_tag is None else str(state_tag),
                      json.dumps(trajectory_state_snapshot(conn)),
                      datetime.now().isoformat(),
                      None if propensity is None else float(propensity),
                      None if arm_set is None else json.dumps(list(arm_set))))
        conn.commit()
        row = _safe_query(conn, "SELECT trajectory_id FROM state_trajectories "
                                "WHERE learner=? AND occasion_key=?",
                          (learner, str(occasion_key)))
        return row[0]["trajectory_id"] if row else None
    except (sqlite3.Error, TypeError, ValueError) as e:
        _audit(conn, "trajectory_open_failed", f"{occasion_key} {type(e).__name__}: {e}")
        return None


def record_trajectory_evidence(conn, occasion_key, evidence,
                               learner=TRAJECTORY_LEARNER):
    """Attach what was actually observed on this occasion. Merged, so a probe
    result and a later note do not overwrite each other."""
    try:
        init_trajectory_schema(conn)
        rows = _safe_query(conn, "SELECT evidence FROM state_trajectories "
                                 "WHERE learner=? AND occasion_key=?",
                           (learner, str(occasion_key)))
        if not rows:
            return False
        try:
            merged = json.loads(rows[0]["evidence"] or "{}")
        except (ValueError, TypeError):
            merged = {}
        merged.update(evidence or {})
        conn.execute("UPDATE state_trajectories SET evidence=? "
                     "WHERE learner=? AND occasion_key=?",
                     (json.dumps(merged), learner, str(occasion_key)))
        conn.commit()
        return True
    except (sqlite3.Error, TypeError, ValueError) as e:
        _audit(conn, "trajectory_evidence_failed",
               f"{occasion_key} {type(e).__name__}: {e}")
        return False


def close_due_trajectories(conn, min_delay_hours=TRAJECTORY_AFTER_DELAY_HOURS):
    """Write the after-state of every occasion old enough for one to mean
    something. The real elapsed delay is stored beside it, because a sweep
    that runs three days late produces a three-day transition and a fit that
    treated it as a one-day transition would be wrong."""
    try:
        init_trajectory_schema(conn)
        rows = _safe_query(conn, "SELECT trajectory_id, opened_at FROM "
                                 "state_trajectories WHERE state_after IS NULL")
        if not rows:
            capture_trajectory_observations(conn)
            return 0
        now = datetime.now()
        snap = None
        closed = 0
        for r in rows:
            try:
                opened = datetime.fromisoformat(r["opened_at"])
            except (ValueError, TypeError):
                continue
            hours = (now - opened).total_seconds() / 3600.0
            if hours < min_delay_hours:
                continue
            if snap is None:
                snap = json.dumps(trajectory_state_snapshot(conn))
            conn.execute("UPDATE state_trajectories SET state_after=?, closed_at=?, "
                         "delay_hours=? WHERE trajectory_id=?",
                         (snap, now.isoformat(), round(hours, 2), r["trajectory_id"]))
            closed += 1
        if closed:
            conn.commit()
        capture_trajectory_observations(conn)
        return closed
    except (sqlite3.Error, TypeError, ValueError) as e:
        _audit(conn, "trajectory_close_failed", f"{type(e).__name__}: {e}")
        return 0


def trajectory_counts(conn):
    """Both numbers, and which one the ladder reads.

    One learner produces ONE trajectory in the sense the transition kernel
    needs, however many occasions that trajectory contains. Counting occasions
    as trajectories is exactly the inflation the directive warns against, so
    both are reported and the ladder is pointed at the honest one."""
    occasions = closed = learners = 0
    rows = _safe_query(conn, "SELECT COUNT(*) c, SUM(state_after IS NOT NULL) k, "
                             "COUNT(DISTINCT learner) L FROM state_trajectories")
    if rows and rows[0]["c"] is not None:
        occasions = rows[0]["c"] or 0
        closed = rows[0]["k"] or 0
        learners = rows[0]["L"] or 0
    return {"occasions": occasions, "closed": closed,
            "open": occasions - closed, "learners": learners,
            "trajectories": learners,
            "ladder_reads": "trajectories",
            "grain": ("One learner is one trajectory. This database holds "
                      f"{learners} learner trajector{'y' if learners == 1 else 'ies'} "
                      f"made of {occasions} intervention occasion"
                      f"{'' if occasions == 1 else 's'}; the ladder reads the "
                      "trajectory count, not the occasion count.")}


def legacy_descriptive_transition_training_set(conn, include_open=False):
    """The export a future fitting run consumes.

    Per learner, the time-ordered occasions as (state_before, action,
    assignment, evidence, state_after, delay_hours). Open occasions are left
    out by default: a transition with no after-state is not a transition."""
    close_due_trajectories(conn)
    rows = _safe_query(conn, "SELECT * FROM state_trajectories ORDER BY learner ASC, "
                             "opened_at ASC, trajectory_id ASC")
    sequences = {}

    def _j(text):
        try:
            return json.loads(text) if text else None
        except (ValueError, TypeError):
            return None

    transitions = 0
    randomized = 0
    for r in rows:
        if r["state_after"] is None and not include_open:
            continue
        rec = {"occasion_key": r["occasion_key"], "action": r["action"],
               "assignment": r["assignment"], "trial": r["trial"],
               "subject": r["subject"], "state_tag": r["state_tag"],
               "opened_at": r["opened_at"], "closed_at": r["closed_at"],
               "delay_hours": r["delay_hours"],
               "state_before": _j(r["state_before"]),
               "evidence": _j(r["evidence"]),
               "state_after": _j(r["state_after"])}
        sequences.setdefault(r["learner"], []).append(rec)
        if rec["state_after"] is not None:
            transitions += 1
            if rec["assignment"] == "randomized":
                randomized += 1
    counts = trajectory_counts(conn)
    return {"schema": "recursa.transition_training_set.v1",
            # NOT for causal or transition fitting: state_after is one sweep
            # snapshot shared by every occasion due at that moment, and later
            # treatments are not represented. Use trajectory_observation_set().
            "causal_use": False,
            "state_after_basis": "shared_sweep_snapshot",
            "exported_at": datetime.now().isoformat(),
            "min_delay_hours": TRAJECTORY_AFTER_DELAY_HOURS,
            "trajectories": len(sequences),
            "occasions": counts["occasions"],
            "transitions": transitions,
            "randomized_transitions": randomized,
            "grain": counts["grain"],
            "sequences": sequences}


def trajectory_report(conn):
    """How many trajectories exist, and what the ladder says that supports."""
    counts = trajectory_counts(conn)
    gate = capability_available(conn, "transition_model_learned",
                                have=counts["trajectories"])
    return {**counts,
            "gate": gate,
            "supports": (gate["reason"] if gate["available"] else gate["refusal"]),
            "now": ("The record accumulates so the model is fittable later; "
                    "building the record is the prerequisite, fitting it is "
                    "gated on the ladder.")}


def fit_transition_model(conn, fitter=None):
    """The fitting run section VII describes -- gated, and therefore refusing.

    It exists so the refusal is a real code path with a real answer rather
    than a paragraph in a design document. Above the threshold it hands the
    export to `fitter`; there is no fitter shipped, because shipping one that
    could never be reached would be the same fiction from the other side."""
    def _fit(c):
        data = trajectory_observation_set(c, 72.0)
        if fitter is None:
            raise NotImplementedError(
                "No transition-model fitter is shipped with the desktop app; the "
                f"observation export ({data['captured']} captured, {data['missed']} missed, "
                f"{data['randomized_with_propensity']} randomized) is ready for one, "
                "and it requires the fitter to declare its estimand.")
        return fitter(data)
    return fit_gated_model(conn, "transition_model_learned", _fit,
                           have=trajectory_counts(conn)["trajectories"])


# ===========================================================================
# INDEPENDENT BLIND SOLVER
# ===========================================================================
# The review's sixth target, and the one that does most of the work: a
# solver that must answer the candidate WITHOUT seeing which option the
# generator keyed.
#
# This is not a formality. A generator asked to check its own item will
# confirm its own answer essentially always -- it already believes it. An
# independent solve is the only cheap way to catch the two failure modes
# that matter: a keyed answer that is simply wrong, and an item where more
# than one option is defensible. If the solver picks a different option, at
# least one of those is true, and either way the item is not ready.

def blind_solve(conn, cand, solver_fn=None):
    """Solve a candidate without access to its key.

    `solver_fn(stem, options, context) -> index or None`. When no solver is
    available this returns an explicit 'unavailable' rather than a pass:
    treating an absent check as a successful one is how unverified content
    reaches learners."""
    opts = cand.get("opts") or []
    if len(opts) < 2:
        return {"status": "invalid", "reason": "fewer than two options"}
    if solver_fn is None:
        return {"status": "unavailable",
                "reason": "no independent solver on this machine; the candidate "
                          "cannot be verified by solving and must not be "
                          "auto-approved"}
    # The solver is handed the stem, the shuffled options and the source --
    # never the keyed index, and never the explanation, which usually names
    # the answer outright. The shuffle is what stops a generator that
    # habitually keys option 0 and a solver that prefers option 0 from
    # agreeing without either reading the item; it is seeded from the stem
    # so re-verifying the same candidate is reproducible, and the pick is
    # mapped back through the recorded permutation.
    ctx = {"topic": cand.get("topic"), "source": cand.get("source", "")}
    perm = list(range(len(opts)))
    random.Random(zlib.crc32(str(cand.get("q", "")).encode("utf-8"))).shuffle(perm)
    shuffled = [opts[i] for i in perm]          # shuffled[j] == opts[perm[j]]
    try:
        picked = solver_fn(cand.get("q", ""), shuffled, ctx)
    except Exception as e:
        return {"status": "error", "reason": f"{type(e).__name__}: {e}"}
    if picked is None:
        return {"status": "abstained",
                "reason": "the solver could not determine a single best answer, "
                          "which is itself evidence the item is ambiguous"}
    try:
        picked = perm[int(picked)]
    except (ValueError, TypeError, IndexError):
        return {"status": "error",
                "reason": f"the solver returned an index outside the options ({picked!r})"}
    agrees = (int(picked) == int(cand.get("a", -1)))
    return {"status": "solved", "picked": int(picked), "agrees": agrees,
            "permutation": perm,
            "reason": ("independent solve matched the key" if agrees else
                       "independent solve chose a DIFFERENT option: either the "
                       "key is wrong or more than one answer is defensible")}

def verify_candidate_full(conn, cand, packet=None, solver_fn=None,
                          knowledge_dependence_fn=None):
    """All gates a candidate must clear, each an independent authority.

    Returns (state, notes). Only reaches 'verified' when structure, the
    blind solve and the analytic separation all agree and the knowledge-
    dependence gate, when a weak solver is attached, passes. Without one
    that gate abstains: it is noted as untested, never counted as passed,
    and the blind solve remains the independent authority."""
    notes = []

    ok_struct, why = verify_variant_item(
        {**cand, "topic": cand.get("topic")},
        {"q": cand.get("seed_stem", ""), "topic": cand.get("topic")})
    if not ok_struct:
        notes.append(f"structural: {why}")

    if packet:
        ok_p, reasons = verify_candidate_structural(conn, cand, packet)
        if not ok_p:
            notes.extend(f"contract: {r}" for r in reasons)

    solve = blind_solve(conn, cand, solver_fn)
    notes.append(f"solver: {solve['reason']}")
    if solve["status"] == "solved" and not solve["agrees"]:
        return "rejected", notes
    if solve["status"] in ("abstained", "invalid", "error"):
        return "rejected", notes

    emp = simulate_separation(cand.get("skills") or [],
                              target_skill=(cand.get("skills") or [None])[0])
    notes.append(f"separation {emp.get('separation')}: {emp.get('reason','')}")
    if not emp.get("passes"):
        return "rejected", notes

    kd = knowledge_dependence(cand, knowledge_dependence_fn)
    notes.append(f"knowledge: {kd['reason']}")
    if kd["passes"] is False:
        return "rejected", notes

    if notes and any(n.startswith(("structural:", "contract:")) for n in notes):
        return "rejected", notes
    if solve["status"] == "unavailable":
        # Structure and separation passed but nothing solved it independently.
        # That is a draft awaiting a solver, not a verified item.
        return "draft", notes
    return "verified", notes


# ===========================================================================
# SOURCE-GROUNDED GENERATION
# ===========================================================================
# Targets 1-5. The generator consumes the packet and contract the app
# already produces, and is routed through the expert pool so it uses a
# frontier model only when the learner has supplied a key and opted in.
#
# The prompt is built from the contract rather than freehand: it states what
# may vary, what may not, and that the cited authority governs. A generator
# given a contract is constrained; one given a topic name is improvising.

def _candidate_prompt(contract_or_packet, family="structural"):
    c = contract_or_packet or {}
    may = c.get("may_vary") or []
    # variant_contract() carries the invariants as must_not_change;
    # challenge_packet() carries none, so a packet-driven generation gets
    # the generic three. The packet's deterministic_checks are a different
    # thing -- post-hoc gates the verifier runs -- and are told to the
    # generator as such, under "rejected unless", not as invariants.
    must_not = c.get("must_not_change") or ["the governing rule being tested",
                                             "the required skill tags",
                                             "single-best-answer status"]
    rejected_unless = c.get("deterministic_checks") or c.get("verification") or []
    src = c.get("source_evidence") or ", ".join(c.get("approved_sources") or [])
    tgt = c.get("target_distinction") or {}
    lines = [
        f"Write ONE {family} variant of a New Jersey real-estate exam question.",
        f"Topic: {c.get('target_topic') or c.get('topic')}",
    ]
    if tgt.get("label"):
        lines.append(f"It must test: {tgt['label']}")
    if tgt.get("contrast_label"):
        lines.append(f"It must NOT be answerable by knowing only: {tgt['contrast_label']}")
    if src:
        lines.append(f"Governing authority (the answer must follow this): {src}")
    if may:
        lines.append("You MAY change: " + ", ".join(may))
    if must_not:
        lines.append("You MUST NOT change: " + ", ".join(must_not))
    if rejected_unless:
        lines.append("Your output will be rejected unless: " + "; ".join(rejected_unless))
    lines += [
        "Exactly one option may be defensible. Write four options.",
        "Each wrong option should correspond to a distinct, nameable misconception.",
        "Return ONLY JSON: {\"q\":str,\"opts\":[str,str,str,str],\"a\":int,"
        "\"exp\":str,\"distractor_reasons\":[str,str,str]}",
        "If you cannot satisfy every constraint, return {\"refuse\":true} instead "
        "of a weaker item.",
    ]
    return "\n".join(lines)

def llm_candidate_generator(api_key, contract_or_packet, family="structural", _call=None):
    """Generate one candidate under contract. Returns None when it cannot.

    The refusal path is deliberate and prompted for: an item that quietly
    drops a constraint is worse than no item, because it will pass a
    structural check while testing the wrong thing."""
    if not api_key and _call is None:
        return None
    sys_p = ("You author licensing-exam items. You follow the supplied contract "
             "exactly. You never introduce a second governing rule, never "
             "weaken a citation requirement, and refuse rather than produce a "
             "item that violates a constraint.")
    if _call is not None:
        raw, err = _call(sys_p, _candidate_prompt(contract_or_packet, family))
    else:
        raw, err = _anthropic_call(api_key, sys_p,
                                   _candidate_prompt(contract_or_packet, family),
                                   max_tokens=900)
    if err or not raw:
        return None
    try:
        txt = raw if isinstance(raw, str) else json.dumps(raw)
        txt = txt.strip().removeprefix("```json").removeprefix("```").removesuffix("```").strip()
        data = json.loads(txt)
        if data.get("refuse"):
            return None
        opts = data.get("opts") or []
        if len(opts) < 3 or not isinstance(data.get("a"), int):
            return None
        c = contract_or_packet or {}
        return {"q": data.get("q", ""), "opts": opts, "a": int(data["a"]),
                "exp": data.get("exp", ""),
                "topic": c.get("target_topic") or c.get("topic"),
                "skills": (c.get("required_skills")
                           or [(c.get("target_distinction") or {}).get("skill")]),
                "source": (c.get("source_evidence")
                           or (c.get("approved_sources") or [""])[0]),
                "family": family, "seed_id": c.get("seed_item"),
                "provenance": "llm_under_contract",
                "distractor_reasons": data.get("distractor_reasons", [])}
    except Exception:
        return None

def llm_blind_solver(api_key, model=ANTHROPIC_SOLVER_MODEL):
    """A solver that never sees the key. Returns a callable or None.

    Runs on a DIFFERENT model id from the generator (ANTHROPIC_MODEL), for
    the same reason the local path refuses a solver equal to the generator:
    a model checking an item it just wrote confirms its own key. The
    callable carries the model id as `.model` so it can be recorded."""
    if not api_key:
        return None

    def _solve(stem, options, ctx):
        listed = "\n".join(f"{i}: {o}" for i, o in enumerate(options))
        sys_p = ("You answer New Jersey real-estate licensing questions. Solve "
                 "the question from the options as written -- do not recall a "
                 "remembered item. Reply with ONLY the index of the single "
                 "best option, or the word AMBIGUOUS if more than one is "
                 "defensible.")
        user = (f"Question: {stem}\nOptions:\n{listed}\n"
                + (f"Governing authority: {ctx.get('source')}\n" if ctx.get("source") else "")
                + "Answer with one number, or AMBIGUOUS.")
        # Plain text: "AMBIGUOUS" is a valid reply and is not JSON.
        raw, err = _anthropic_call(api_key, sys_p, user, max_tokens=12,
                                   parse_json=False, model=model)
        if err or not raw:
            return None
        t = (raw if isinstance(raw, str) else str(raw)).strip().upper()
        # Word match, not substring: "AMBIG" in t fired on the JSON key
        # "ambiguities" and turned every structured reply into an abstention.
        if re.search(r"\bAMBIGUOUS\b", t):
            return None
        m = re.search(r"\d+", t)
        return int(m.group()) if m else None

    _solve.model = model
    return _solve

def _ensure_solver_model_column(conn):
    """candidate_items gained `solver_model` after the table shipped; the
    guarded ALTER is the app's migration pattern."""
    try:
        conn.execute("ALTER TABLE candidate_items ADD COLUMN solver_model TEXT")
        conn.commit()
    except sqlite3.OperationalError:
        pass

def _record_solver_model(conn, cid, solver_model):
    if not solver_model:
        return
    _ensure_solver_model_column(conn)
    try:
        conn.execute("UPDATE candidate_items SET solver_model=? WHERE candidate_id=?",
                     (str(solver_model), cid))
        conn.commit()
    except sqlite3.OperationalError as e:
        _audit(conn, "candidate_solver_model_failed", f"id={cid} {e}")

def generate_and_verify(conn, target=None, family="structural", allow_paid=False):
    """The full pipeline: contract -> generate -> blind solve -> verify ->
    candidate bank. Human approval remains a separate step.

    Works end to end with no model: it simply produces no candidate and says
    so, which is the honest outcome rather than a silent no-op."""
    init_candidate_schema(conn)
    tgt = target or (factory_targets(conn, limit=1) or [None])[0]
    if tgt is None:
        return {"status": "no_targets"}
    packet = challenge_packet(conn, tgt)

    # Local models first: they cost nothing, need no network, and keep the
    # learner's material on their own machine. The API is a fallback, not
    # the default -- treating it as the default is what made this whole
    # pipeline read as unavailable on a machine that could run it.
    api = get_setting(conn, "anthropic_api_key", "") if allow_paid else ""
    cand = None
    gen_name = "none"
    _local = local_generation_status()
    if _local.get("ready"):
        cand = local_candidate_generator(packet, family)
        gen_name = f"local:{_local['generator']}"
    _gpu = gpu_config(conn)
    _gen_model = _local.get("generator") if cand is not None else None
    if cand is None and _gpu:
        # Content generation is batch work: it may wait for a sleeping node.
        _gcall = gpu_caller(_gpu, "generator", 900, False, 0.7, latency="batch")
        cand = llm_candidate_generator(None, packet, family, _call=_gcall)
        if cand is not None:
            cand["provenance"] = "gpu_under_contract"
            _gen_model = _gcall.used.get("model")
            gen_name = f"gpu:{_gen_model}"
    if cand is None and api:
        cand = llm_candidate_generator(api, packet, family)
        gen_name = "llm_under_contract"
    if cand is None and (tgt.get("topic") == "t10"):
        cand = deterministic_generator(packet)
        gen_name = "deterministic_template"
    if cand is None:
        return {"status": "no_generator", "packet": packet, "target": tgt,
                "note": ("No generator is available for this target. Template-backed "
                         "maths can be generated deterministically; everything else "
                         "needs a model, and inventing content without one would "
                         "produce items nothing verified.")}

    solver = gpu_consensus_solver(_gpu, exclude_model=_gen_model, latency="batch") \
        if _gpu else None
    if solver is None:
        solver = local_blind_solver() if _local.get("ready") else None
    if solver is None and api:
        # Generator and solver are different model ids by construction
        # (ANTHROPIC_MODEL vs ANTHROPIC_SOLVER_MODEL).
        solver = llm_blind_solver(api)
    solver_model = getattr(solver, "model", None) if solver is not None else None
    state, notes = verify_candidate_full(conn, cand, packet, solver)
    if state == "verified" and _gpu:
        # Additive gate: it can only hold an item back. An abstention is
        # recorded as an abstention, never as a pass.
        blocking, findings, reviewer, rerr = gpu_review_candidate(_gpu, cand,
                                                                  exclude_model=_gen_model,
                                                                  latency="batch")
        if blocking is None:
            notes.append(f"adversarial review abstained: {rerr}")
        elif blocking:
            state = "rejected"
            notes.append(f"adversarial review ({reviewer}) blocking: "
                         + "; ".join(f"{f['kind']}: {str(f.get('detail', ''))[:90]}"
                                     for f in findings if f.get("severity") == "blocking"))
        else:
            notes.append(f"adversarial review ({reviewer}) found no blocking defect"
                         + (f"; {len(findings)} minor" if findings else ""))
    cid = store_candidate(conn, cand, generator=gen_name)
    set_candidate_state(conn, cid, state, "; ".join(notes)[:280])
    _record_solver_model(conn, cid, solver_model)
    try:
        conn.execute("UPDATE candidate_items SET verify_notes=? WHERE candidate_id=?",
                     ("; ".join(notes)[:400], cid))
        conn.commit()
    except Exception:
        pass
    return {"status": "generated", "candidate_id": cid, "state": state,
            "notes": notes, "candidate": cand, "generator": gen_name,
            "solver_model": solver_model, "target": tgt}

# ===========================================================================
# LOCAL SLM BACKEND
# ===========================================================================
# The candidate pipeline was hardcoded to _anthropic_call, so "the generator
# is off" really meant "no API key", and the whole verified-authoring path
# sat idle on a machine that could have run it locally. transformers and
# torch are already the app's optional semantic tier; the same runtime
# generates.
#
# THE CONSTRAINT THAT MATTERS MOST: the generator and the blind solver MUST
# BE DIFFERENT MODELS. A model asked to solve an item it just wrote will
# reproduce its own reasoning and agree with itself, which converts the
# independent check into a rubber stamp while leaving every log line looking
# correct. That failure is silent and it invalidates the entire candidate
# bank, so a single-model machine is refused rather than quietly accepted.

LOCAL_GEN_MODELS = ("HuggingFaceTB/SmolLM3-3B", "Qwen/Qwen3-1.7B",
                    "Qwen/Qwen3-0.6B")
LOCAL_SOLVE_MODELS = ("microsoft/Phi-4-mini-instruct", "Qwen/Qwen3-1.7B",
                      "Qwen/Qwen3-0.6B")

_LOCAL_PIPES = {}

def local_runtime_available():
    """Whether a local generation runtime exists at all."""
    try:
        import importlib.util as _u
        return bool(_u.find_spec("transformers")) and bool(_u.find_spec("torch"))
    except Exception:
        return False

def local_model_cached(repo):
    """True when the weights are already on disk.

    Checked rather than assumed: triggering a multi-gigabyte download in the
    middle of a study session is not an acceptable way to discover a model
    is missing."""
    try:
        from huggingface_hub import snapshot_download
        snapshot_download(repo, local_files_only=True)
        return True
    except Exception:
        return False

def scan_hf_cache():
    """Any instruct-style causal LM already in the Hugging Face cache.

    The catalogue lists are a preference, not a requirement. Insisting on
    exactly the named repos meant a machine that already held two perfectly
    usable models still reported 'no generator', and sent the user back to
    a download that keeps failing. Whatever is on disk is what gets used.

    "Usable" is decided by the model's own config.json, not by its name: a
    cached Whisper, T5 or diffusion repo has weights too, and nominating it
    as the generator fails opaquely at load time. Only a repo whose declared
    architecture is a causal LM is offered."""
    found = []
    try:
        from huggingface_hub import scan_cache_dir
        info = scan_cache_dir()
        for repo in info.repos:
            if repo.repo_type != "model":
                continue
            rid = repo.repo_id
            low = rid.lower()
            # Exclude the embedding / reranker / NLI models: they are not
            # text generators and loading one as a generator fails opaquely.
            if any(k in low for k in ("embedding", "bge", "cross-encoder",
                                      "mnli", "deberta", "sentence-",
                                      "e5-", "gte-")):
                continue
            # A generator needs weights, not just a tokenizer.
            has_weights = any(
                f.file_name.endswith((".safetensors", ".bin", ".gguf"))
                for rev in repo.revisions for f in rev.files)
            if not has_weights or not _hf_repo_is_causal_lm(repo):
                continue
            found.append({"repo": rid,
                          "size_gb": round(repo.size_on_disk / 1e9, 2)})
    except Exception:
        return []
    return sorted(found, key=lambda r: -r["size_gb"])

def _hf_repo_is_causal_lm(repo):
    """True when a cached revision's config.json declares a *ForCausalLM
    architecture. No config, or any other architecture, is a no."""
    for rev in repo.revisions:
        for f in rev.files:
            if f.file_name != "config.json":
                continue
            try:
                with open(f.file_path, "r", encoding="utf-8") as fh:
                    cfg = json.load(fh)
            except (OSError, ValueError):
                continue
            archs = cfg.get("architectures") or []
            return bool(archs) and str(archs[0]).endswith("ForCausalLM")
    return False

def local_models_present():
    """Every usable local model: catalogue first, then anything else cached."""
    gen = [m for m in LOCAL_GEN_MODELS if local_model_cached(m)]
    solve = [m for m in LOCAL_SOLVE_MODELS if local_model_cached(m)]
    known = set(gen) | set(solve)
    other = [r["repo"] for r in scan_hf_cache() if r["repo"] not in known]
    # Anything cached can do either job. Preferring the catalogue keeps the
    # known-good models first without excluding the rest.
    return {"generators": gen + other, "solvers": solve + other,
            "discovered": other}

_LOCAL_STATUS_CACHE = None

def local_generation_status(conn=None, rescan=False):
    """A plain answer to 'can this machine author content, and if not why'.

    Memoised for the process: the answer costs several cache probes plus a
    full scan of the Hugging Face cache, and it was being recomputed on
    the Tk thread every time a section expanded and several times per
    pipeline run. Models do not appear mid-session without the learner
    doing something, so `rescan=True` (the explicit "Rescan" action) is the
    only way the answer changes."""
    global _LOCAL_STATUS_CACHE
    if _LOCAL_STATUS_CACHE is not None and not rescan:
        return dict(_LOCAL_STATUS_CACHE)
    _LOCAL_STATUS_CACHE = _local_generation_status_uncached()
    return dict(_LOCAL_STATUS_CACHE)

def _local_generation_status_uncached():
    if not local_runtime_available():
        return {"ready": False, "reason":
                "No local model runtime. Install torch and transformers "
                "(see Setup) or set an API key."}
    have = local_models_present()
    if not have["generators"]:
        return {"ready": False, "reason":
                "Runtime present but no generator model downloaded. "
                f"Fetch one of: {', '.join(LOCAL_GEN_MODELS)}.", **have}
    # DISTINCTNESS is about the two models CHOSEN, not about the catalogue
    # lists. Several models appear in both lists because they can do either
    # job; excluding any model that appears in both meant a machine holding
    # SmolLM3 plus Qwen3-1.7B -- two genuinely different models -- was told
    # it had only one. The rule is simply that the solver must not be the
    # model that wrote the item.
    gen = have["generators"][0]
    solver_pool = [m for m in have["solvers"] if m != gen]
    if not solver_pool:
        # A second generator-capable model can still solve; only being down
        # to one model on the whole machine is fatal.
        solver_pool = [m for m in have["generators"] if m != gen]
    if not solver_pool:
        return {"ready": False, "reason":
                "Only one local model is downloaded, so the blind solver "
                "would be the same model that wrote the item. A model "
                "checking its own work agrees with itself, which makes the "
                "verification meaningless while still looking like it "
                "passed. Any second causal LM already in your Hugging Face "
                "cache will be used automatically \u2014 it does not have to "
                "be one of the suggested repos.", **have}
    return {"ready": True, "generator": gen, "solver": solver_pool[0], **have}

def _local_pipe(repo):
    """Load once, reuse. Loading is slow and memory-heavy; a per-call load
    would make the factory unusable. Returns (pipeline, None) or
    (None, error_string).

    The pipeline is built WITHOUT generation settings: it is cached by repo
    and shared by the generator (sampled, long) and the structured solver
    (greedy, short), so those are passed per call in _local_chat. Loading
    is pinned to the local cache -- the weights were already verified to be
    on disk, and the Hub must not be contacted mid-session to resolve a
    revision."""
    if repo in _LOCAL_PIPES:
        return _LOCAL_PIPES[repo], None
    prev_offline = os.environ.get("HF_HUB_OFFLINE")
    os.environ["HF_HUB_OFFLINE"] = "1"
    try:
        from transformers import pipeline
        p = pipeline("text-generation", model=repo,
                     model_kwargs={"local_files_only": True})
        _LOCAL_PIPES[repo] = p
        return p, None
    except Exception as e:
        return None, f"could not load {repo}: {type(e).__name__}: {str(e)[:200]}"
    finally:
        if prev_offline is None:
            os.environ.pop("HF_HUB_OFFLINE", None)
        else:
            os.environ["HF_HUB_OFFLINE"] = prev_offline

# Closed block, or an unclosed one that the token budget cut off: either
# way nothing inside it is an answer.
_THINK_BLOCK_RE = re.compile(r"<think>.*?(?:</think>\s*|\Z)", re.DOTALL)

def _is_thinking_model(repo):
    """Qwen3 and SmolLM3 chat templates emit a <think> block by default;
    both honour a '/no_think' soft switch in the system prompt."""
    low = (repo or "").lower()
    return "qwen3" in low or "smollm3" in low

def _local_chat(repo, system, user, max_new_tokens=700, do_sample=True,
                temperature=0.7, with_error=False):
    """One chat turn on a cached local pipeline. Returns the reply text
    (None on failure); with_error=True returns (text, error) so a caller
    can tell a model that would not answer from one that could not load."""
    p, err = _local_pipe(repo)
    if p is None:
        return (None, err) if with_error else None
    if _is_thinking_model(repo):
        system = (system or "").rstrip() + "\n/no_think"
    gen_kwargs = {"max_new_tokens": max_new_tokens, "do_sample": bool(do_sample)}
    if do_sample:
        gen_kwargs["temperature"] = temperature
    try:
        out = p([{"role": "system", "content": system},
                 {"role": "user", "content": user}], **gen_kwargs)
    except Exception as e:
        err = f"generation failed on {repo}: {type(e).__name__}: {str(e)[:200]}"
        return (None, err) if with_error else None
    text = None
    if isinstance(out, list) and out:
        gen = out[0].get("generated_text")
        if isinstance(gen, list) and gen:
            text = gen[-1].get("content", "")
        else:
            text = str(gen)
    if text is not None:
        # A thinking model that ignored the soft switch still gets its
        # reasoning stripped before anything downstream regex-matches it.
        text = _THINK_BLOCK_RE.sub("", text)
    return (text, None) if with_error else text

def local_candidate_generator(contract_or_packet, family="structural",
                              model=None, with_error=False):
    """Generate one candidate locally, under the same contract the API path
    uses. Returns None rather than a weaker item. With with_error=True the
    result is (candidate_or_None, load_error_or_None): a model that refused
    or produced unparseable text is (None, None); a model that could not be
    loaded or run at all is (None, "could not load ...") -- the two must not
    be reported to the author as the same thing."""
    def _ret(cand, err):
        return (cand, err) if with_error else cand

    st = local_generation_status()
    if not st.get("ready"):
        return _ret(None, None)
    repo = model or st["generator"]
    sys_p = ("You author licensing-exam items. You follow the supplied "
             "contract exactly. You never introduce a second governing rule "
             "and you refuse rather than produce an item that violates a "
             "constraint. Reply with JSON only.")
    raw, err = _local_chat(repo, sys_p,
                           _candidate_prompt(contract_or_packet, family),
                           with_error=True)
    if err:
        return _ret(None, err)
    if not raw:
        return _ret(None, None)
    try:
        txt = str(raw).strip()
        txt = txt[txt.index("{"):txt.rindex("}") + 1]
        data = json.loads(txt)
        if data.get("refuse"):
            return _ret(None, None)
        opts = data.get("opts") or []
        if len(opts) < 3 or not isinstance(data.get("a"), int):
            return _ret(None, None)
        c = contract_or_packet or {}
        return _ret({"q": data.get("q", ""), "opts": opts, "a": int(data["a"]),
                     "exp": data.get("exp", ""),
                     "topic": c.get("target_topic") or c.get("topic"),
                     "skills": (c.get("required_skills")
                                or [(c.get("target_distinction") or {}).get("skill")]),
                     "source": (c.get("source_evidence")
                                or (c.get("approved_sources") or [""])[0]),
                     "family": family, "seed_id": c.get("seed_item"),
                     "provenance": f"local:{repo}"}, None)
    except (ValueError, TypeError, AttributeError):
        # Not JSON, or JSON of the wrong shape: the model did not comply.
        return _ret(None, None)

def local_blind_solver(model=None):
    """A solver that never sees the key, running on a DIFFERENT local model
    from the generator. Returns a callable, or None if that cannot be
    guaranteed."""
    st = local_generation_status()
    if not st.get("ready"):
        return None
    repo = model or st["solver"]
    if repo == st.get("generator"):
        return None          # never let one model check its own work

    def _solve(stem, options, ctx):
        listed = "\n".join(f"{i}: {o}" for i, o in enumerate(options))
        sys_p = ("You answer New Jersey real-estate licensing questions. "
                 "Reply with ONLY the index of the single best option, or the "
                 "word AMBIGUOUS if more than one is defensible.")
        user = (f"Question: {stem}\nOptions:\n{listed}\n"
                + (f"Governing authority: {ctx.get('source')}\n"
                   if ctx.get("source") else "")
                + "Answer with one number, or AMBIGUOUS.")
        # Greedy, so the same item verifies the same way twice; 32 tokens
        # leaves room for a model that prefixes a few words (or an empty
        # think block) before the digit.
        raw = _local_chat(repo, sys_p, user, max_new_tokens=32, do_sample=False)
        if not raw:
            return None
        t = str(raw).strip().upper()
        # Word match, not substring: "AMBIG" in t fired on the JSON key
        # "ambiguities" and turned every structured reply into an abstention.
        if re.search(r"\bAMBIGUOUS\b", t):
            return None
        m = re.search(r"\d+", t)
        return int(m.group()) if m else None

    _solve.model = repo
    return _solve

def generate_and_verify_local(conn, target=None, family="structural"):
    """The full pipeline on local models: contract -> generate -> blind solve
    by a different model -> verify -> candidate bank -> human approval.

    Identical gates to the API path. The only difference is where the text
    comes from, which is exactly the property the verification layer exists
    to make safe."""
    init_candidate_schema(conn)
    st = local_generation_status()
    if not st.get("ready"):
        return {"status": "no_local_generator", "reason": st.get("reason"),
                "detail": st}

    tgt = target or (factory_targets(conn, limit=1) or [None])[0]
    if tgt is None:
        return {"status": "no_targets"}
    packet = challenge_packet(conn, tgt)

    cand, load_err = local_candidate_generator(packet, family, with_error=True)
    if load_err:
        # Not a refusal: the model never ran. Reporting this as "designed
        # behaviour" would hide a broken install behind a green toast.
        _audit(conn, "local_generation_load_failed", load_err[:200])
        return {"status": "load_failed", "packet": packet, "target": tgt,
                "reason": load_err,
                "note": (f"The local generator ({st['generator']}) could not be "
                         "loaded or run, so nothing was generated. Check the "
                         "model files and the torch/transformers install; use "
                         "Rescan after fixing it.")}
    if cand is None:
        return {"status": "refused", "packet": packet, "target": tgt,
                "note": ("The local model declined to produce an item that "
                         "satisfies the contract, or its output did not parse. "
                         "That is the designed behaviour \u2014 a weaker item "
                         "would pass the structural check while testing the "
                         "wrong thing.")}

    solver = local_blind_solver()
    state, notes = verify_candidate_full(conn, cand, packet, solver)
    cid = store_candidate(conn, cand, generator=cand.get("provenance", "local"))
    set_candidate_state(conn, cid, state, "; ".join(notes)[:280])
    _record_solver_model(conn, cid, getattr(solver, "model", None))
    try:
        conn.execute("UPDATE candidate_items SET verify_notes=? "
                     "WHERE candidate_id=?", ("; ".join(notes)[:400], cid))
        conn.commit()
    except Exception:
        pass
    return {"status": "generated", "candidate_id": cid, "state": state,
            "notes": notes, "candidate": cand, "target": tgt,
            "generator": st["generator"], "solver": st["solver"]}


# ===========================================================================
# PASS 1: PLAN THE ASSET  --  generation driven by what is actually missing
# ===========================================================================
# The factory picked its targets from the distinguishability audit alone:
# it generated when two skill profiles could not be told apart. That is one
# reason to author, and not the commonest. The completeness audit knows a
# far larger gap -- non-decisive facts missing on 172/172 skills, decision
# questions on 141 -- and the loop's authoring queue now names the skills
# it refused to assess. None of that reached the generator. The planner
# consumes those signals and says WHAT to create, for WHICH skill, and WHY,
# before any model is asked to write anything.

ASSET_PLANS = {
    "decision question": ("minimal_pair",
        "a pair of items differing in ONE decisive fact, so the learner must "
        "identify what decides the outcome rather than match surface wording"),
    "non-decisive facts": ("surface_adversarial",
        "an item whose surface cue points the wrong way, so that reading the "
        "decisive fact is the only route to the key"),
    "contrast pair": ("minimal_pair",
        "a contrast against the nearest lookalike skill"),
    "common trap": ("misconception_probe",
        "an item whose distractors each encode a named wrong rule"),
    "worked example": ("worked_example",
        "a fully reasoned case, stem through answer through why"),
    "transfer item": ("structural_variant",
        "the same rule on changed facts, so transfer can be tested at all"),
    "free-recall prompt": ("free_recall",
        "a prompt answerable without options in front of the learner"),
    "counterexample": ("boundary_case",
        "an exception or boundary where the ordinary rule does not apply"),
    # These two are NEVER generated. A canonical statement of the rule and
    # its authority are the things the app must not invent: everything
    # else is verified against them, so a model-written rule would be
    # circular. They are routed to a human with the gap named.
    "canonical rule": ("human_authored",
        "a reviewed statement of the rule, written by a person against the "
        "source \u2014 not generated"),
    "source": ("human_authored",
        "a citation to current authority, supplied by a person \u2014 not generated"),
}

HUMAN_ONLY_ASSETS = ("canonical rule", "source")

def plan_asset(conn, skill_id, for_generator=False):
    """Decide what to author for one skill, from measured need.

    Input: the completeness audit and the dossier. Output: the single most
    valuable asset to create, the reason, the misconception it should
    target if one is known, and the contrast skill if it is a pair.

    `for_generator` plans for the generation pipeline: the human-only
    assets (a canonical rule, a source) are what generated items are
    verified against, so they are passed over in favour of something the
    generator can actually produce; only when nothing else is missing does
    the plan name the human-only gap, so the pipeline can say so."""
    cc = skill_completeness(conn, skill_id)
    if cc["score"] >= 0.999:
        return None
    try:
        d = build_skill_dossier(conn, skill_id)
    except Exception:
        d = None
    meta = SKILLS.get(skill_id) or {}
    # Priority order among missing assets: the ones that make the skill
    # TEACHABLE first (a rule and an example), then the ones that make it
    # DISTINGUISHABLE (decision question, contrast), then the rest.
    order = ["worked example", "canonical rule", "decision question", "contrast pair",
             "transfer item", "common trap", "non-decisive facts",
             "free-recall prompt", "counterexample", "source"]
    missing = [m["asset"] for m in cc["missing"]]
    if for_generator:
        generable = [a for a in missing if a not in HUMAN_ONLY_ASSETS]
        if generable:
            missing = generable
    target = next((a for a in order if a in missing), missing[0] if missing else None)
    if not target:
        return None
    kind, purpose = ASSET_PLANS.get(target, ("structural_variant", "more coverage"))

    misconception = None
    contrast = None
    if d:
        wrong = [s for s in d["sections"] if s["key"] == "wrong"]
        if wrong and wrong[0]["lines"]:
            misconception = wrong[0]["lines"][0][:220]
        disc = [s for s in d["sections"] if s["key"] in ("disc", "disc2")]
        if disc and disc[0]["lines"]:
            contrast = disc[0]["lines"][0][:160]

    return {"skill": skill_id, "label": meta.get("label", skill_id),
            "topic": meta.get("topic"),
            "missing_asset": target, "asset_kind": kind, "purpose": purpose,
            "completeness": cc["score"],
            "maturity": content_maturity(conn, skill_id)["key"],
            "targeted_misconception": misconception,
            "contrast": contrast,
            "reason": (f"Skill is {content_maturity(conn, skill_id)['label']} at "
                       f"{cc['score']*100:.0f}% complete; the highest-leverage "
                       f"missing asset is a {target}.")}

def authoring_plan(conn, limit=10, for_generator=False):
    """The generation work order: what to author next across the bank,
    worst-maturity first, each with a concrete asset plan."""
    plans = []
    for sid in SKILLS:
        try:
            pl = plan_asset(conn, sid, for_generator=for_generator)
        except Exception:
            pl = None
        if pl:
            plans.append(pl)
    rank = {"gap": 0, "draft": 1, "bronze": 2, "silver": 3, "gold": 4}
    plans.sort(key=lambda p: (rank.get(p["maturity"], 9), p["completeness"]))
    return plans[:limit]

# ===========================================================================
# PASS 3: GENERATE ALTERNATIVES  --  several drafts, deliberately varied
# ===========================================================================
# One draft gives the verifier nothing to choose between. Asking for
# several with DIFFERENT intended error modes lets it keep only the ones
# that are materially different, source-supported and diagnostically
# useful, and discard the rest. The variation is prompted for explicitly;
# a model asked for "three items" produces three paraphrases.

ALTERNATIVE_MODES = (
    ("structural_variant", "the same rule applied to different parties, "
                           "numbers and setting"),
    ("minimal_pair",       "a case that differs from the seed in exactly ONE "
                           "decisive fact, which flips the answer"),
    ("boundary_case",      "an exception or edge where the ordinary rule does "
                           "not apply"),
    ("surface_adversarial","a case where the obvious surface cue points to the "
                           "WRONG answer and only the decisive fact gives the key"),
)

# ---------------------------------------------------------------------------
# BATCHGEN BACKEND  --  schema-validated, batched generation
# ---------------------------------------------------------------------------
# generate_alternatives() made N sequential model calls and parsed each
# reply by slicing from the first "{" to the last "}" and hoping. Two real
# costs: every alternative was a full separate forward pass, and a
# malformed reply was indistinguishable from a principled refusal -- both
# came back as "the model declined", which hid generator faults behind the
# safety story.
#
# qwen_batchgen fixes both when present. Its Transformers backend batches
# all N prompts into ONE generate() call (left-padded tensor batch), and
# every reply is validated against a Draft 2020-12 JSON Schema with retry
# on failure. With a vLLM server it goes further: the schema is enforced
# at token level, so a structurally invalid reply cannot be produced at
# all. The candidate CONTRACT is now that schema, formally.
#
# What batchgen does not do, and is not asked to: it knows nothing about
# blind solving, model distinctness, contracts, or human review. Those
# stay exactly where they are.

CANDIDATE_SCHEMA = {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "type": "object",
    "properties": {
        "refuse": {"type": "boolean"},
        "q":    {"type": "string", "minLength": 20},
        "opts": {"type": "array", "minItems": 3, "maxItems": 5,
                 "items": {"type": "string", "minLength": 1},
                 "uniqueItems": True},
        "a":    {"type": "integer", "minimum": 0, "maximum": 4},
        "exp":  {"type": "string", "minLength": 10},
        "distractor_reasons": {"type": "array", "items": {"type": "string"}},
    },
    "required": ["q", "opts", "a", "exp"],
    "additionalProperties": False,
}

def batchgen_available():
    try:
        import batchgen  # noqa: F401
        from batchgen.backends import TransformersBackend  # noqa: F401
        return True
    except Exception:
        return False

_BATCHGEN_BACKEND = {}

def _batchgen_backend(model_repo):
    """Load once per model. The backend holds the weights, so reloading
    per call would be far worse than the sequential path it replaces."""
    if model_repo in _BATCHGEN_BACKEND:
        return _BATCHGEN_BACKEND[model_repo]
    try:
        from batchgen.config import PipelineConfig
        from batchgen.backends import TransformersBackend
        cfg = PipelineConfig(backend="transformers", model=model_repo,
                             max_new_tokens=700, temperature=0.7, top_p=0.95,
                             batch_size=8)
        be = TransformersBackend(cfg)
        _BATCHGEN_BACKEND[model_repo] = be
        return be
    except Exception:
        return None

def generate_alternatives_batched(conn, plan, packet, model_repo, n=3):
    """All N alternatives in one batched, schema-validated call.

    Returns [(mode, candidate)] for replies that validated and did not
    refuse, plus a diagnostics dict separating REFUSED from INVALID --
    the distinction the sequential path could not make."""
    be = _batchgen_backend(model_repo)
    if be is None:
        return [], {"error": "batchgen backend unavailable"}
    try:
        from batchgen.models import InputRecord
        from jsonschema import Draft202012Validator
    except Exception as e:
        return [], {"error": f"batchgen import failed: {e}"}

    records = []
    modes = ALTERNATIVE_MODES[:n]
    for mode, desc in modes:
        records.append(InputRecord(
            id=mode,
            system=("You author licensing-exam items under a contract. Refuse "
                    "(refuse=true) rather than weaken a constraint."),
            prompt=_alternative_prompt(packet, plan, mode, desc),
            metadata={"mode": mode}))
    try:
        outputs = be._generate_sync(records, CANDIDATE_SCHEMA)
    except Exception as e:
        return [], {"error": f"batched generate failed: {e}"}

    validator = Draft202012Validator(CANDIDATE_SCHEMA)
    kept, diag = [], {"refused": 0, "invalid": 0, "kept": 0}
    for rec, out in zip(records, outputs):
        txt = getattr(out, "text", None) or getattr(out, "raw_text", "") or ""
        try:
            data = json.loads(txt[txt.index("{"):txt.rindex("}") + 1])
        except Exception:
            data = None
        if data is None:
            diag["invalid"] += 1
            continue
        # A refusal is checked BEFORE the content schema: a model that
        # declines is not obliged to also produce a well-formed item, and
        # counting its refusal as "invalid" would misfile the one outcome
        # the contract explicitly asks for.
        if data.get("refuse"):
            diag["refused"] += 1
            continue
        errs = list(validator.iter_errors(data))
        if errs:
            diag["invalid"] += 1
            continue
        if data["a"] >= len(data["opts"]):
            diag["invalid"] += 1
            continue
        mode = rec.metadata["mode"]
        kept.append((mode, {
            "q": data["q"], "opts": data["opts"], "a": int(data["a"]),
            "exp": data["exp"], "topic": plan["topic"], "skills": [plan["skill"]],
            "source": (packet.get("approved_sources") or [""])[0],
            "family": mode, "seed_id": packet.get("seed_item"),
            "provenance": f"batchgen:{model_repo}:{mode}",
            "distractor_reasons": data.get("distractor_reasons", [])}))
        diag["kept"] += 1
    return kept, diag

def _alternative_prompt(packet, plan, mode, mode_desc):
    base = _candidate_prompt(packet, plan.get("asset_kind", "structural"))
    extra = [f"INTENDED VARIATION: {mode} \u2014 {mode_desc}."]
    if plan.get("targeted_misconception"):
        extra.append("At least one distractor must encode this wrong rule: "
                     + plan["targeted_misconception"])
    if plan.get("contrast"):
        extra.append("The item must NOT be answerable by knowing only: "
                     + plan["contrast"])
    return base + "\n" + "\n".join(extra)

def _stem_tokens(text):
    return {w for w in re.findall(r"[a-z]{4,}", (text or "").lower())}

def dedupe_candidates(cands, max_jaccard=0.6):
    """Candidate-to-candidate deduplication within one plan.

    Checking each draft against the ACTIVE bank does not stop a batch from
    producing five versions of the same scenario -- they are all novel
    relative to the bank and near-identical to each other. Two drafts are
    duplicates when their stems overlap heavily (Jaccard on content words)
    OR they share the same keyed answer text AND the same set of options.
    The first survivor of each cluster is kept; the rest are reported so
    the count is visible rather than silently smaller."""
    kept, dropped = [], []
    for mode, c in cands:
        toks = _stem_tokens(c.get("q", ""))
        key_txt = (c.get("opts") or [""])[c.get("a", 0)].strip().lower() \
                  if c.get("a", 0) < len(c.get("opts") or []) else ""
        opt_set = frozenset(o.strip().lower() for o in (c.get("opts") or []))
        dup = False
        for _m2, k in kept:
            kt = _stem_tokens(k.get("q", ""))
            jac = len(toks & kt) / max(1, len(toks | kt))
            k_key = (k.get("opts") or [""])[k.get("a", 0)].strip().lower() \
                    if k.get("a", 0) < len(k.get("opts") or []) else ""
            k_opts = frozenset(o.strip().lower() for o in (k.get("opts") or []))
            if jac >= max_jaccard or (key_txt and key_txt == k_key and opt_set == k_opts):
                dup = True
                break
        (dropped if dup else kept).append((mode, c))
    return kept, dropped

def generate_alternatives(conn, plan, packet, n=3, allow_paid=False):
    """Produce up to n candidate drafts for one plan, each with a distinct
    intended variation, through whatever generator is available (local
    first, API second, deterministic template for maths). Returns the
    list of (mode, candidate) that parsed; refusals are dropped silently
    because a refusal is the model doing its job."""
    out = []
    st = local_generation_status()
    api = get_setting(conn, "anthropic_api_key", "") if allow_paid else ""
    # Batched, schema-validated path first. One forward pass for all N,
    # and refusals are told apart from malformed output.
    if st.get("ready") and batchgen_available():
        kept, diag = generate_alternatives_batched(conn, plan, packet,
                                                   st["generator"], n=n)
        if kept:
            return kept
        # fall through to the sequential path only if batching itself failed,
        # not if the model refused everything -- a refusal is an answer.
        if diag.get("refused", 0) >= n:
            return []
    for mode, desc in ALTERNATIVE_MODES[:n]:
        prompt_packet = dict(packet)
        prompt_packet["__mode_note"] = desc
        cand = None
        if st.get("ready"):
            _p = _alternative_prompt(packet, plan, mode, desc)
            raw = _local_chat(st["generator"],
                              "You author licensing-exam items under a contract. "
                              "Reply with JSON only. Refuse rather than weaken a "
                              "constraint.", _p)
            if raw:
                try:
                    txt = str(raw).strip()
                    txt = txt[txt.index("{"):txt.rindex("}") + 1]
                    data = json.loads(txt)
                    if not data.get("refuse") and len(data.get("opts") or []) >= 3:
                        cand = {"q": data.get("q", ""), "opts": data["opts"],
                                "a": int(data.get("a", 0)),
                                "exp": data.get("exp", ""),
                                "topic": plan["topic"], "skills": [plan["skill"]],
                                "source": (packet.get("approved_sources") or [""])[0],
                                "family": mode, "seed_id": packet.get("seed_item"),
                                "provenance": f"local:{st['generator']}:{mode}"}
                except Exception:
                    cand = None
        if cand is None and api:
            cand = llm_candidate_generator(api, packet, mode)
        if cand is None and plan.get("topic") == "t10":
            cand = deterministic_generator(packet)
        if cand:
            out.append((mode, cand))
    return out

def generate_and_verify_planned(conn, skill_id=None, allow_paid=False):
    """The full six-pass pipeline for ONE planned asset:
    plan -> bounded packet -> alternatives -> blind solve -> deterministic
    checks -> psychometric checks -> candidate bank (draft/verified/rejected).

    Returns a report listing what was kept and why each discard happened,
    so a run that produces nothing still explains itself."""
    init_candidate_schema(conn)
    plans = ([plan_asset(conn, skill_id, for_generator=True)] if skill_id
             else authoring_plan(conn, 1, for_generator=True))
    plans = [p for p in plans if p]
    if not plans:
        return {"status": "nothing_to_author",
                "note": "Every skill is complete, or none could be planned."}
    plan = plans[0]
    if plan["asset_kind"] == "human_authored":
        return {"status": "human_required", "plan": plan,
                "note": (f"The missing asset is a {plan['missing_asset']}, which "
                         "is never generated: it is what generated items are "
                         "verified against. Add it to RULE_CARDS by hand.")}

    # Pass 2: the bounded packet, reusing the factory's packet builder.
    tgt = {"kind": "completeness", "topic": plan["topic"], "skill": plan["skill"],
           "certificate": CERT_QUASI_HARD, "why": plan["reason"]}
    packet = challenge_packet(conn, tgt)

    # Pass 3, then intra-batch dedup so the verifier is not asked to bless
    # the same scenario three times under three labels.
    alts = generate_alternatives(conn, plan, packet, n=3, allow_paid=allow_paid)
    alts, dupes = dedupe_candidates(alts)
    if not alts:
        st = local_generation_status()
        return {"status": "no_generator", "plan": plan,
                "reason": st.get("reason") or "no generator produced a draft"}

    # Passes 4-6, per alternative
    _gpu = gpu_config(conn)
    solver = gpu_consensus_solver(_gpu) if _gpu else None
    if solver is None:
        solver = local_blind_solver() if local_generation_status().get("ready") else None
    if solver is None:
        api = get_setting(conn, "anthropic_api_key", "") if allow_paid else ""
        solver = llm_blind_solver(api) if api else None
    # Prefer the STRUCTURED solve: it must name the decisive fact and flag
    # ambiguity, which an index-only solve cannot. Fall back to the index
    # solver only when no chat-capable solver exists.
    st_local = local_generation_status()
    solver_chat = None
    if st_local.get("ready"):
        solver_chat = lambda sy, us, _r=st_local["solver"]: _local_chat(_r, sy, us, 400)
    elif _gpu:
        solver_chat = lambda sy, us: (gpu_chat(_gpu, "solver", sy, us, 400, parse_json=False,
                                               latency="batch")[0])

    # A "weak" structured solve -- the right index with no decisive fact --
    # is what the structured check exists to tell apart from a real solve,
    # so it must not collapse into the index-only pass. The pick is still
    # handed to the blind solve (a DISAGREEING weak pick is still evidence
    # against the key), but the weakness is remembered here and a candidate
    # that would otherwise verify on it stays a draft, awaiting a solve that
    # can say why.
    weak_solve = {}

    def _solve_fn(stem, options, ctx):
        weak_solve.pop("reason", None)
        if solver_chat is None:
            return solver(stem, options, ctx) if solver else None
        res = structured_blind_solve(conn, {"q": stem, "opts": options,
                                            "a": -1, "source": ctx.get("source")},
                                     solver_chat)
        if res["status"] == "weak":
            weak_solve["reason"] = res["reason"]
            return res["picked"]
        if res["status"] == "solved":
            return res["picked"]
        return None            # abstained / error -> treated as no answer

    kept, discarded = [], []
    for mode, cand in alts:
        state, notes = verify_candidate_full(conn, cand, packet, _solve_fn)
        if state == "verified" and weak_solve.get("reason"):
            state = "draft"
            notes.append(f"solver: weak — {weak_solve['reason']}; held as draft")
        cid = store_candidate(conn, cand, generator=cand.get("provenance", mode))
        set_candidate_state(conn, cid, state, "; ".join(notes)[:280])
        (kept if state in ("verified", "draft") else discarded).append(
            {"mode": mode, "candidate_id": cid, "state": state, "notes": notes})
    return {"status": "generated", "plan": plan, "kept": kept,
            "discarded": discarded, "n_alternatives": len(alts),
            "deduplicated": len(dupes)}

# ===========================================================================
# CONTENT ASSETS  --  versioned, typed, reviewable; they CLOSE the gap
# ===========================================================================
# The completeness audit could measure the absence of an asset. Nothing
# could record its presence. An approved candidate entered the item pool
# and the skill it was authored for stayed at the same completeness score,
# because "a minimal pair now exists for this skill" was not a fact the
# system could hold. This table is that fact. Approving a candidate now
# registers the asset the plan targeted, the completeness audit reads it,
# and the score rises -- which is the whole point of generating.

ASSET_TYPES = ("canonical_rule", "decision_question", "required_fact",
               "nondecisive_fact", "exception", "counterexample", "misconception",
               "contrast_pair", "worked_example", "free_recall_prompt", "hint",
               "structural_variant", "minimal_pair", "boundary_case",
               "surface_adversarial", "source")

# plan asset names -> asset types
_PLAN_TO_ASSET = {"decision question": "decision_question",
                  "non-decisive facts": "nondecisive_fact",
                  "contrast pair": "contrast_pair", "common trap": "misconception",
                  "worked example": "worked_example", "transfer item": "structural_variant",
                  "free-recall prompt": "free_recall_prompt",
                  "counterexample": "counterexample", "canonical rule": "canonical_rule",
                  "source": "source", "decisive facts": "required_fact"}

def init_asset_schema(conn):
    conn.executescript("""
    CREATE TABLE IF NOT EXISTS content_assets (
        asset_id       INTEGER PRIMARY KEY AUTOINCREMENT,
        skill_id       TEXT NOT NULL,
        asset_type     TEXT NOT NULL,
        body_json      TEXT NOT NULL,
        source_id      TEXT,
        source_locator TEXT,
        provenance     TEXT,
        generated_by   TEXT,
        parent_asset   INTEGER,
        candidate_id   INTEGER,
        status         TEXT NOT NULL DEFAULT 'draft',
        review_status  TEXT NOT NULL DEFAULT 'unreviewed',
        reviewer_notes TEXT,
        created_at     TEXT NOT NULL,
        approved_at    TEXT,
        retired_at     TEXT
    );
    CREATE INDEX IF NOT EXISTS ix_assets_skill ON content_assets(skill_id, status);
    """)
    conn.commit()

def register_asset(conn, skill_id, asset_type, body, source_id="", locator="",
                   provenance="", generated_by="", candidate_id=None,
                   status="draft"):
    if asset_type not in ASSET_TYPES:
        return None
    init_asset_schema(conn)
    cur = conn.execute("""INSERT INTO content_assets
        (skill_id, asset_type, body_json, source_id, source_locator, provenance,
         generated_by, candidate_id, status, created_at)
        VALUES (?,?,?,?,?,?,?,?,?,?)""",
        (skill_id, asset_type, json.dumps(body), source_id, locator, provenance,
         generated_by, candidate_id, status, datetime.now().isoformat()))
    conn.commit()
    _audit(conn, "asset_registered", f"{skill_id}:{asset_type} status={status}")
    return cur.lastrowid

def approve_asset(conn, asset_id, notes=""):
    init_asset_schema(conn)
    conn.execute("""UPDATE content_assets SET status='active', review_status='approved',
                    reviewer_notes=?, approved_at=? WHERE asset_id=?""",
                 (notes[:300], datetime.now().isoformat(), asset_id))
    conn.commit()
    try:
        invalidate_dependents(conn, "skill", None, f"asset {asset_id} approved")
    except Exception:
        pass
    return True

def retire_asset(conn, asset_id, notes=""):
    init_asset_schema(conn)
    conn.execute("""UPDATE content_assets SET status='retired', reviewer_notes=?,
                    retired_at=? WHERE asset_id=?""",
                 (notes[:300], datetime.now().isoformat(), asset_id))
    conn.commit()
    return True

def active_assets(conn, skill_id):
    """Approved assets for one skill, by type. This is what the
    completeness audit reads to give credit for generated content."""
    init_asset_schema(conn)
    rows = _safe_query(conn, """SELECT asset_type, COUNT(*) n FROM content_assets
                                 WHERE skill_id=? AND status='active'
                              GROUP BY asset_type""", (skill_id,))
    return {r["asset_type"]: r["n"] for r in rows}

def promote_candidate_as_asset(conn, candidate_id, plan_asset_name=None, notes=""):
    """A human approves a candidate: it becomes a live item AND is
    registered as the asset it was authored to be, so the gap it was
    generated for actually closes."""
    rows = _safe_query(conn, "SELECT * FROM candidate_items WHERE candidate_id=?",
                       (candidate_id,))
    if not rows:
        return None
    r = rows[0]
    # The approver cannot do the verifier's job: only a candidate the gates
    # have passed (verified) or a reviewer has already approved may be
    # served. A rejected or still-draft row stays where it is.
    if r["state"] not in ("verified", "approved"):
        _audit(conn, "candidate_promote_refused",
               f"id={candidate_id} state={r['state']}")
        return None
    needed = ([("verified", "approved"), ("approved", "promoted")] if r["state"] == "verified"
              else [("approved", "promoted")])
    for a, b in needed:
        if b not in CANDIDATE_TRANSITIONS.get(a, set()):
            _audit(conn, "candidate_promote_refused", f"id={candidate_id} {a} -> {b} not legal")
            return None
    r, err = approve_and_promote_candidate(conn, candidate_id, notes or "approved as asset")
    if r is None:
        _audit(conn, "candidate_promote_refused", f"id={candidate_id}: {err}")
        return None
    skills = json.loads(r["skills"] or "[]")
    fam = r["family"] or "structural_variant"
    atype = (_PLAN_TO_ASSET.get(plan_asset_name) if plan_asset_name else None) \
            or (fam if fam in ASSET_TYPES else "structural_variant")
    body = {"q": r["stem"], "opts": json.loads(r["options"]), "a": r["answer"],
            "exp": r["explanation"]}
    try:
        # register_asset commits, which commits the two transitions with it:
        # state and asset land together or not at all.
        aid = register_asset(conn, skills[0] if skills else "", atype, body,
                             source_id=r["source"] or "", provenance=r["provenance"] or "",
                             generated_by=r["generator"] or "", candidate_id=candidate_id,
                             status="active")
    except Exception as e:
        conn.rollback()
        _audit(conn, "candidate_promote_failed", f"id={candidate_id} {type(e).__name__}: {e}")
        return None
    if not aid:
        conn.rollback()
        return None
    _audit(conn, "candidate_state", f"id={candidate_id} {rows[0]['state']} -> approved -> promoted (human)")
    if aid:
        conn.execute("""UPDATE content_assets SET review_status='approved', approved_at=?
                        WHERE asset_id=?""", (datetime.now().isoformat(), aid))
        conn.commit()
    return aid

# ===========================================================================
# PASS 4: STRUCTURED BLIND SOLVE
# ===========================================================================
# An index is a weak check. A solver that must also name the decisive fact
# and say whether more than one option is defensible is a much stronger
# one: an item can be solved correctly by luck, but it cannot have its
# decisive fact named correctly by luck.

def structured_blind_solve(conn, cand, solver_chat=None):
    """Returns {selected_index, confidence, decisive_fact, ambiguities,
    abstain, status}. `solver_chat(system, user) -> text` is a chat call on
    the SOLVER model; when None the check reports unavailable rather than
    passing."""
    opts = cand.get("opts") or []
    if len(opts) < 2:
        return {"status": "invalid", "reason": "fewer than two options"}
    if solver_chat is None:
        return {"status": "unavailable",
                "reason": "no independent solver; cannot verify by solving"}
    listed = "\n".join(f"{i}: {o}" for i, o in enumerate(opts))
    sys_p = ("You answer New Jersey real-estate licensing questions. Reply with "
             "JSON only: {\"selected_index\": int, \"confidence\": 0-1, "
             "\"decisive_fact\": str, \"ambiguities\": [str], \"abstain\": bool}. "
             "Set abstain=true and list the ambiguities if more than one option "
             "is defensible. Never guess.")
    user = (f"Question: {cand.get('q','')}\nOptions:\n{listed}\n"
            + (f"Governing authority: {cand.get('source')}\n" if cand.get("source") else ""))
    try:
        raw = solver_chat(sys_p, user)
        txt = str(raw).strip()
        txt = txt[txt.index("{"):txt.rindex("}") + 1]
        data = json.loads(txt)
    except Exception as e:
        return {"status": "error", "reason": f"solver output unparseable: {e}"}
    if data.get("abstain") or (data.get("ambiguities") and len(data["ambiguities"]) > 0):
        return {"status": "abstained", "ambiguities": data.get("ambiguities", []),
                "reason": "the solver found more than one defensible answer"}
    sel = data.get("selected_index")
    if not isinstance(sel, int) or not (0 <= sel < len(opts)):
        return {"status": "error", "reason": "solver returned no valid index"}
    fact = (data.get("decisive_fact") or "").strip()
    if len(fact.split()) < 3:
        return {"status": "weak", "picked": sel, "agrees": sel == cand.get("a"),
                "reason": "solver could not name the decisive fact; a correct "
                          "index without a reason is not verification"}
    return {"status": "solved", "picked": sel, "agrees": sel == cand.get("a"),
            "confidence": float(data.get("confidence", 0.5)),
            "decisive_fact": fact,
            "reason": ("independent solve matched the key and named the decisive "
                       "fact" if sel == cand.get("a") else
                       "independent solve chose a DIFFERENT option")}

def candidate_bank_status(conn):
    init_candidate_schema(conn)
    rows = _safe_query(conn, """SELECT state, COUNT(*) c FROM candidate_items
                                 GROUP BY state""")
    counts = {r["state"]: r["c"] for r in rows}
    return {"counts": counts,
            "total": sum(counts.values()),
            "awaiting_review": counts.get("verified", 0),
            "live": counts.get("promoted", 0)}


# ===========================================================================
# COMPOSED SKILL NOTES  --  the graph as a writing surface
# ===========================================================================
# The app ships 18 topic notes. It also knows 172 SKILLS, 296 item
# explanations, 35 confusion pairs, 32 misconceptions and ~1,000 graph edges
# -- and none of that reaches the reading surface. A learner who is at 4% on
# "Life estates, pur autre vie, remainder vs. reversion" gets pointed at the
# whole Rights & Interests note, most of which they already know.
#
# THE KEY DISTINCTION: this ASSEMBLES, it does not generate. Every sentence
# in a composed note is lifted verbatim from something already authored and
# reviewed -- an item explanation, a misconception diagnosis, a confusion
# rationale, a topic paragraph. Nothing is invented, so nothing needs
# verifying, and the safety property is the same one that makes the maths
# templates trustworthy: correct by construction rather than correct
# because a model said so.
#
# That is what makes this scale where cloze mining did not. Cloze was capped
# by note length (measured: ~73 items from 2,787 words). Composition is
# capped by the SKILL COUNT and the edges between skills, which is an order
# of magnitude larger and grows every time an item is authored or tagged.

def _sentences_mentioning(text, needles, limit=3):
    """Paragraph sentences that actually mention one of these terms."""
    if not text:
        return []
    out = []
    for raw in re.split(r"(?<=[.!?])\s+", text):
        s_ = raw.strip()
        if len(s_) < 25:
            continue
        low = s_.lower()
        if any(n.lower() in low for n in needles if len(n) > 4):
            out.append(s_)
        if len(out) >= limit:
            break
    return out

def compose_skill_note(conn, skill_id):
    """Build a focused note for ONE skill from verified fragments.

    Returns a section list; each section carries its own provenance so the
    reader can see that this is assembled source material rather than
    something written for them on the spot."""
    meta = SKILLS.get(skill_id)
    if not meta:
        return None
    tid = meta.get("topic")
    topic = TOPICS.get(tid, {})
    label = meta.get("label", skill_id)

    items = [q for q in QUIZ_LIST if skill_id in Q_MATRIX.get(q["id"], [])]
    sections = []

    # 1. The rule itself, taken from the topic note where it is discussed.
    needles = [w for w in re.split(r"[^A-Za-z]+", label) if len(w) > 4] + [label]
    para = _sentences_mentioning(topic.get("notes", ""), needles, limit=3)
    if para:
        sections.append({"heading": "The rule",
                         "lines": para,
                         "source": f"{topic.get('short', tid)} study note"})

    # 2. What the exam actually asks. Item explanations are the densest
    #    authored prose in the app and are never shown outside feedback.
    exps = []
    for q in items[:6]:
        e = (q.get("exp") or "").strip()
        if e and e not in exps:
            exps.append(e)
    if exps:
        sections.append({"heading": "How it gets tested",
                         "lines": exps[:4],
                         "source": f"{len(items)} item explanation(s)"})

    # 3. The specific ways people get it wrong.
    miscs = []
    for q in items:
        m = enriched_misconception(q["id"])
        if m and m.get("diagnosis") and m["diagnosis"] not in miscs:
            miscs.append(m["diagnosis"])
    if miscs:
        sections.append({"heading": "Where it goes wrong",
                         "lines": miscs[:4],
                         "source": "authored misconception tags"})

    # 4. What it is confusable with -- straight off the graph.
    conf = []
    seen_pairs = set()
    for q in items:
        try:
            for e in neighbours(conn, "item", q["id"],
                                edge_type="confusable_with", limit=3):
                w = (e["evidence"] or "").strip()
                if w and w not in seen_pairs:
                    seen_pairs.add(w)
                    conf.append(w)
        except Exception:
            break
    if conf:
        sections.append({"heading": "Do not confuse it with",
                         "lines": conf[:4],
                         "source": "confusion graph (authored edges)"})

    # 5. What it rests on. Inferred, and labelled as such.
    try:
        bott = upstream_bottleneck(conn, skill_id)
    except Exception:
        bott = None
    if bott:
        sections.append({
            "heading": "This rests on",
            "lines": [f"{bott['label']} \u2014 currently "
                      f"{(bott['mastery'] or 0)*100:.0f}%. Shore that up first; "
                      "drilling this skill on its own will not fix it."],
            "source": "prerequisite graph (inferred, not authored)"})

    return {"skill": skill_id, "label": label, "topic": tid,
            "topic_name": topic.get("name", tid),
            "n_items": len(items), "sections": sections,
            "item_ids": [q["id"] for q in items]}

def composed_note_coverage():
    """How many skills can actually produce a usable composed note.

    Reported honestly: a skill with one item and no misconception tag makes
    a thin note, and claiming 172 notes when many are one line would be the
    same overstatement as counting cloze items that do not exist."""
    rich = thin = 0
    for sid in SKILLS:
        items = [q for q in QUIZ_LIST if sid in Q_MATRIX.get(q["id"], [])]
        exps = sum(1 for q in items if (q.get("exp") or "").strip())
        if exps >= 2:
            rich += 1
        elif items:
            thin += 1
    return {"skills": len(SKILLS), "rich": rich, "thin": thin,
            "topic_notes": len(TOPICS)}


# ===========================================================================
# THE ADAPTIVE SKILL DOSSIER
# ===========================================================================
# compose_skill_note() assembles the same fragments for everyone. That is a
# leaflet. This is the thing a book cannot be: a study guide that is
# different for you than for anyone else, because it is built from what YOU
# specifically got wrong, in what order YOUR prerequisites are broken, and
# how close YOU are to forgetting it.
#
# Every signal the app already computes is used here, and each is used for
# the one job it is actually good for:
#
#   DINA posterior      -> how much of this skill is real, per sub-fact
#   chosen-option data  -> WHICH wrong idea you hold, not just that you erred
#   misconception tags  -> the authored diagnosis for that specific wrong idea
#   prerequisite graph  -> whether the fix is here or upstream
#   confusion graph     -> the one fact that separates a lookalike pair
#   FSRS card state     -> knew-and-forgetting vs never-knew (different fixes)
#   calibration split   -> whether it collapses only under a clock
#   item difficulty     -> orders explanations from core rule to edge case
#   generalization gap  -> whether you know the rule or just these items
#
# THE ORDERING ADAPTS. A learner with a broken prerequisite gets that first
# and is told not to drill here yet. A learner who is strong but confusable
# skips the basics entirely and opens on contrasts. A learner who is
# forgetting gets retrieval, not re-reading. Serving the same section order
# to all three is what makes a textbook a textbook.

DOSSIER_STRONG = 0.75
DOSSIER_WEAK = 0.35
DOSSIER_MIN_SEEN = 4   # answers before a strong stance ("solid"/"refining") may be declared

def _skill_state(conn, skill_id):
    """Everything known about this learner on this one skill."""
    meta = SKILLS.get(skill_id) or {}
    tid = meta.get("topic")
    items = [q for q in QUIZ_LIST if skill_id in Q_MATRIX.get(q["id"], [])]
    ids = [q["id"] for q in items]

    mastery, n_obs = None, 0
    try:
        if len(topic_skill_ids(tid)) >= 2:
            post = dina_topic_posterior(conn, tid)
            if post:
                mastery = post["skill_mastery"].get(skill_id)
                n_obs = post.get("n", 0)
    except Exception:
        pass
    if mastery is None:
        mastery = get_mastery(conn, tid) if tid else 0.5

    rows = []
    if ids:
        # A pretest guess is not a held belief and a heavily-hinted answer
        # is not retrieval: neither belongs in "what you actually believe".
        rows = measurement_rows(conn, "question_id IN ({})".format(",".join("?" * len(ids))),
                                tuple(ids),
                                columns="question_id, correct, chosen, mode, "
                                        "confidence, time_taken, timestamp",
                                order="id DESC", limit=40)
    seen = len(rows)
    right = sum(1 for r in rows if r["correct"])

    # Knew-it-and-losing-it is a different problem from never-had-it, and
    # the remedies are opposite: retrieval practice vs. first instruction.
    early = [r["correct"] for r in rows[len(rows) // 2:]] if len(rows) >= 6 else []
    late = [r["correct"] for r in rows[:len(rows) // 2]] if len(rows) >= 6 else []
    trend = None
    if early and late:
        trend = (sum(late) / len(late)) - (sum(early) / len(early))

    # Timed-only collapse
    calm, timed = split_calm_timed(rows)
    pressure_gap = None
    if len(calm) >= 3 and len(timed) >= 3:
        pressure_gap = (sum(calm) / len(calm)) - (sum(timed) / len(timed))

    # High confidence + wrong is the most dangerous single signal there is
    # -- but only while it is still HAPPENING. Counting across the whole
    # 40-row window made a learner who had since fixed the misconception
    # keep reading "you are confidently wrong": mastery 1.00 and the stance
    # still accusing them of a belief they no longer hold. Scoped to the
    # recent window so it decays as the behaviour does.
    recent = rows[:12]
    confident_wrong = sum(1 for r in recent
                          if not r["correct"] and (r["confidence"] or 0) >= 3)

    return {"meta": meta, "topic": tid, "items": items, "mastery": mastery,
            "n_obs": n_obs, "seen": seen, "right": right, "rows": rows,
            "trend": trend, "pressure_gap": pressure_gap,
            "confident_wrong": confident_wrong,
            "accuracy": (right / seen) if seen else None}

def _your_wrong_ideas(conn, st):
    """The specific wrong answers YOU chose, paired with the authored
    diagnosis for that exact distractor.

    This is the difference between "you are weak on easements" and "you
    believe an easement in gross runs with the land, and here is why it does
    not." The app has stored `chosen` all along and never used it for
    instruction."""
    out = []
    counted = {}
    for r in st["rows"]:
        if r["correct"] or r["chosen"] is None:
            continue
        q = QUIZ_BANK.get(r["question_id"])
        if not q:
            continue
        # A row marked wrong whose chosen option IS the key is inconsistent
        # data -- a legacy row, an import, or a mode that recorded `chosen`
        # without meaning it. Printing it produces "You chose X. The keyed
        # answer is X", which reads as a broken app and destroys confidence
        # in every other line on the page.
        if r["chosen"] == q.get("a"):
            continue
        key = (q["id"], r["chosen"])
        counted[key] = counted.get(key, 0) + 1
    for (qid, chosen), times in sorted(counted.items(), key=lambda kv: -kv[1])[:4]:
        q = QUIZ_BANK[qid]
        opts = q.get("opts") or []
        if chosen >= len(opts):
            continue
        m = enriched_misconception(qid, chosen)
        out.append({
            "question": q["q"], "your_answer": opts[chosen],
            "correct_answer": opts[q["a"]] if q["a"] < len(opts) else "",
            "times": times,
            "why_wrong": (m or {}).get("diagnosis"),
            "explanation": q.get("exp", ""),
            "qid": qid})
    return out

def _prereq_chain(conn, skill_id, depth=3):
    """Walk upstream until a mastered prerequisite is found.

    Returns the broken links in the order they must be fixed. If the chain
    is broken two levels up, drilling here is wasted effort and the dossier
    says so instead of quietly serving more items."""
    chain, cur, guard = [], skill_id, set()
    for _ in range(depth):
        if cur in guard:
            break
        guard.add(cur)
        try:
            b = upstream_bottleneck(conn, cur)
        except Exception:
            b = None
        if not b:
            break
        chain.append(b)
        cur = b["skill"]
    return chain

def _discriminators(conn, st):
    """For each lookalike, the single fact that separates them."""
    out, seen = [], set()
    for q in st["items"]:
        try:
            nb = neighbours(conn, "item", q["id"], edge_type="confusable_with",
                            limit=3)
        except Exception:
            break
        for e in nb:
            why = (e["evidence"] or "").strip()
            partner = QUIZ_BANK.get(e["dst_id"])
            if not why or why in seen or not partner:
                continue
            seen.add(why)
            out.append({"distinction": why,
                        "this_side": q.get("exp", "")[:220],
                        "other_side": partner.get("exp", "")[:220],
                        "pair": [q["id"], partner["id"]]})
        if len(out) >= 3:
            break
    return out

def _layered_explanations(st):
    """Item explanations ordered easiest-first, so the dossier reads as
    core rule → qualifier → edge case rather than as an unsorted pile."""
    tiers = {"core": [], "qualifier": [], "edge": []}
    for q in sorted(st["items"], key=lambda x: x.get("b_irt", 0.0)):
        e = (q.get("exp") or "").strip()
        if not e:
            continue
        b = q.get("b_irt", 0.0)
        tier = "core" if b < -0.3 else ("qualifier" if b < 0.6 else "edge")
        if e not in tiers[tier]:
            tiers[tier].append(e)
    return tiers

def build_skill_dossier(conn, skill_id):
    """An adaptive study guide for one skill.

    Sections are SELECTED and ORDERED by the learner's state, and each
    carries its own provenance. Returns None for an unknown skill."""
    if skill_id not in SKILLS:
        return None
    st = _skill_state(conn, skill_id)
    m = st["mastery"] or 0.0
    label = st["meta"].get("label", skill_id)
    topic = TOPICS.get(st["topic"], {})

    wrong = _your_wrong_ideas(conn, st)
    chain = _prereq_chain(conn, skill_id)
    discs = _discriminators(conn, st)
    tiers = _layered_explanations(st)

    # ---- the opening verdict, which drives everything below ----
    if st["seen"] == 0:
        stance = "unseen"
        headline = "You have not answered anything on this yet."
        strategy = ("Read the rule, then answer a few items. Nothing below is "
                    "personalised yet because there is no evidence to "
                    "personalise from.")
    elif chain and m < DOSSIER_STRONG:
        stance = "blocked"
        headline = f"The problem is upstream, not here."
        strategy = (f"{chain[0]['label']} sits underneath this and is at "
                    f"{(chain[0]['mastery'] or 0)*100:.0f}%. Drilling this skill "
                    "now mostly produces guessing noise \u2014 fix the dependency "
                    "first.")
    elif st["confident_wrong"] >= 2 and m < DOSSIER_STRONG:
        stance = "misconception"
        headline = "You are confidently wrong here, which is the expensive kind."
        strategy = ("You are not missing information, you are holding a specific "
                    "wrong rule. Read 'What you actually believe' first; the "
                    "general explanation will not dislodge it.")
    elif st["trend"] is not None and st["trend"] < -0.2:
        stance = "forgetting"
        headline = "You knew this and are losing it."
        strategy = ("Recent answers are worse than earlier ones. This is a "
                    "retention problem, not a comprehension one \u2014 retrieval "
                    "practice will fix it faster than re-reading.")
    elif st["pressure_gap"] is not None and st["pressure_gap"] > 0.25:
        stance = "pressure"
        headline = "You know this untimed and lose it against a clock."
        strategy = ("Accuracy is fine with time and collapses without it. The "
                    "content is in place; what is missing is retrieval speed.")
    elif m >= DOSSIER_STRONG and st["seen"] < DOSSIER_MIN_SEEN:
        # The mastery figure is prior-dominated at one or two answers. A
        # "Solid" verdict here would tell the learner to stop working on
        # something the app has barely looked at.
        stance = "early"
        headline = (f"Looks fine so far, but that is only {st['seen']} "
                    f"answer{'s' if st['seen'] != 1 else ''}.")
        strategy = ("Too little evidence to call it solid. Answer a few more "
                    "items on this before spending the time elsewhere.")
    elif m >= DOSSIER_STRONG and discs:
        stance = "refining"
        headline = "Solid \u2014 what is left is the lookalikes."
        strategy = ("The core rule is not the problem. Go straight to the "
                    "distinctions; that is where the remaining marks are.")
    elif m >= DOSSIER_STRONG:
        stance = "solid"
        headline = "Solid. Keep it warm rather than re-teaching it."
        strategy = "Spaced retrieval is enough here. Spend the time elsewhere."
    else:
        stance = "learning"
        headline = "Still building this one."
        strategy = ("Work down from the core rule; the qualifiers and edge "
                    "cases only make sense once that is fixed.")

    sections = []

    def add(key, heading, lines, source, kind="text"):
        if lines:
            sections.append({"key": key, "heading": heading, "lines": lines,
                             "source": source, "kind": kind})

    # ---- ORDER ADAPTS TO STANCE ----
    if stance == "blocked":
        add("prereq", "Fix this first",
            [f"{c['label']} \u2014 {(c['mastery'] or 0)*100:.0f}% "
             f"({c['provenance']} link)" for c in chain],
            "prerequisite graph")

    if stance == "misconception" or wrong:
        add("wrong", "What you actually believe",
            [(f"You chose “{w['your_answer'][:90]}” "
              f"{w['times']}\u00d7. "
              + (w["why_wrong"] or "The keyed answer is "
                 f"“{w['correct_answer'][:70]}”."))
             for w in wrong],
            "your own answers + authored misconception tags")

    if stance in ("refining", "misconception") and discs:
        add("disc", "The distinction that decides it",
            [d["distinction"] for d in discs],
            "confusion graph (authored)")

    if tiers["core"] and stance not in ("solid", "refining"):
        add("core", "The rule itself", tiers["core"][:3],
            "item explanations, easiest first")

    if tiers["qualifier"]:
        add("qual", "Qualifiers that trip people", tiers["qualifier"][:3],
            "item explanations, mid difficulty")

    if tiers["edge"] and stance in ("solid", "refining", "learning"):
        add("edge", "Edge cases", tiers["edge"][:3],
            "item explanations, hardest")

    if stance != "refining" and discs:
        add("disc2", "Do not confuse it with",
            [d["distinction"] for d in discs],
            "confusion graph (authored)")

    if stance == "pressure":
        add("speed", "Why this collapses under a clock",
            [f"Untimed vs timed accuracy differs by "
             f"{st['pressure_gap']*100:.0f} points on these items. "
             "Practise the recognition, not the reasoning."],
            "your calm/pressure split")

    # ---- what to actually do, ranked ----
    # ACTIONS MUST NOT BE RECOGNITION.
    #
    # "Re-answer the ones you got wrong" re-serves the exact items whose
    # explanation the learner has just read on this very page. They will get
    # them right, the app will record improvement, and nothing will have
    # been learned -- the answer was on screen thirty seconds ago. That is
    # the single most self-deceiving action this app could offer, because
    # it manufactures the evidence that the intervention worked.
    #
    # Every action below therefore uses items the learner has NOT just been
    # shown, or a different mode of retrieval entirely.
    treated = {w["qid"] for w in wrong}
    untreated = [q["id"] for q in st["items"] if q["id"] not in treated]

    todo = []
    if stance == "blocked":
        todo.append(("Fix the prerequisite first", "prereq", chain[0]["skill"]))
    if untreated:
        todo.append((f"Apply it to {len(untreated)} item(s) you were not just "
                     "shown", "drill_untreated", untreated))
    if discs:
        todo.append(("Separate the confusable pair", "pair", discs[0]["pair"]))
    if wrong and not untreated:
        # Only when there is genuinely nothing else on this skill, and
        # labelled honestly so the weakness of the evidence is visible.
        todo.append(("Re-answer the missed items (weak evidence: you have just "
                     "seen these)", "drill_wrong", [w["qid"] for w in wrong]))
    if st["items"]:
        todo.append(("State the rule from memory instead", "recall",
                     [q["id"] for q in st["items"]]))

    return {
        "skill": skill_id, "label": label,
        "topic": st["topic"], "topic_name": topic.get("name", st["topic"]),
        "stance": stance, "headline": headline, "strategy": strategy,
        "mastery": m, "seen": st["seen"], "accuracy": st["accuracy"],
        "n_items": len(st["items"]),
        "confident_wrong": st["confident_wrong"],
        "trend": st["trend"], "pressure_gap": st["pressure_gap"],
        "sections": sections, "todo": todo,
        "evidence": ("no evidence" if st["seen"] == 0 else
                     "thin" if st["seen"] < 4 else
                     "moderate" if st["seen"] < 12 else "solid"),
    }

# ===========================================================================
# RULE CARDS AND CONTENT COMPLETENESS
# ===========================================================================
# Every previous answer to "why is this brief thin" has been a sentence: the
# corpus is small, the notes are short, the bank has three items. True, and
# useless -- it tells nobody which skill to fix or what to write.
#
# This makes the gap MEASURABLE. Ten assets are required for a skill to
# teach itself properly; the app can check which are present for each of the
# 172 skills and report a completeness fraction with the missing assets
# named. "Lesser interests is at 60%, missing a decision question and a
# counterexample" is a work order. "The corpus is small" is an excuse.
#
# The RULE_CARD is the authored layer that fills those gaps. Nothing
# generates one -- a canonical statement of a legal rule is exactly the
# thing this app must not invent -- but the schema means an authored card
# slots in and immediately raises the completeness score, and the compiler
# prefers it over inferred material wherever it exists.

RULE_CARD_FIELDS = (
    "canonical_rule",       # the reviewed statement of the rule
    "decision_question",    # what to ask FIRST on a new fact pattern
    "required_facts",       # facts that decide the outcome
    "non_decisive_facts",   # facts that look decisive and are not
    "ordinary_case",        # the default application
    "exceptions",
    "boundary_conditions",
    "common_misconceptions",
    "confusable_skills",
    "counterexamples",
    "worked_examples",
    "free_recall_prompt",
    "source_authority",     # statute / regulation / course text
    "source_locator",       # citation
    "effective_date",
    "review_status",
)

# Authored cards live here. Empty by design: the schema and the scoring
# exist first so that authoring has a target and a measurable effect.
RULE_CARDS = {}

def rule_card(skill_id):
    return RULE_CARDS.get(skill_id)

# The ten assets a skill needs before it can teach itself. Each entry is
# (label, how to detect it, why it matters).
def _asset_checks(conn, skill_id):
    meta = SKILLS.get(skill_id) or {}
    items = [q for q in QUIZ_LIST if skill_id in Q_MATRIX.get(q["id"], [])]
    raw = enrichment().get("misconceptions") or {}
    card = rule_card(skill_id) or {}

    # decisive/non-decisive facts and an explicit decision question can only
    # come from an authored card or from a confusion edge that names the
    # deciding fact -- neither is inferable from an item alone.
    deciders = 0
    for q in items:
        try:
            for e in neighbours(conn, "item", q["id"],
                                edge_type="confusable_with", limit=3):
                if " \u2014 " in (e["evidence"] or ""):
                    deciders += 1
        except Exception:
            break

    note = TOPICS.get(meta.get("topic"), {}).get("notes", "") or ""
    terms = [w for w in re.split(r"[^A-Za-z]+", meta.get("label", "")) if len(w) > 4]
    in_note = any(t.lower() in note.lower() for t in terms)

    traps = sum(1 for q in items if raw.get(q["id"]))
    worked = sum(1 for q in items if (q.get("exp") or "").strip())
    sourced = sum(1 for q in items if (q.get("source") or "").strip())
    # Approved generated/authored assets count. This is the write-back that
    # makes the completeness score MOVE when a gap is filled.
    try:
        assets = active_assets(conn, skill_id)
    except Exception:
        assets = {}
    def has(t):
        return assets.get(t, 0) > 0

    return [
        ("canonical rule",
         bool(card.get("canonical_rule")) or in_note or has("canonical_rule"),
         "a reviewed statement of the rule itself"),
        ("decision question",
         bool(card.get("decision_question")) or deciders >= 1
         or has("decision_question") or has("minimal_pair"),
         "an explicit 'ask this first' prompt"),
        ("decisive facts",
         len(card.get("required_facts") or []) >= 2 or deciders >= 2,
         "at least two facts that decide the outcome"),
        ("non-decisive facts",
         len(card.get("non_decisive_facts") or []) >= 1
         or has("nondecisive_fact") or has("surface_adversarial"),
         "at least one fact that looks decisive and is not"),
        ("common trap",
         bool(card.get("common_misconceptions")) or traps >= 1
         or has("misconception"),
         "at least one authored misconception"),
        ("contrast pair",
         bool(card.get("confusable_skills")) or deciders >= 1
         or has("contrast_pair") or has("minimal_pair"),
         "at least one named lookalike"),
        ("worked example",
         bool(card.get("worked_examples")) or worked >= 1
         or has("worked_example"),
         "at least one item explained end to end"),
        ("transfer item",
         len(items) >= 2 or has("structural_variant"),
         "a second item so transfer can be tested at all"),
        ("free-recall prompt",
         bool(card.get("free_recall_prompt"))
         or any(c["topic"] == meta.get("topic") for c in FLASHCARDS),
         "something to answer without options in front of you"),
        ("source",
         bool(card.get("source_authority")) or sourced >= 1,
         "a current authority the rule can be checked against"),
    ]

def skill_completeness(conn, skill_id):
    """How much of what a skill needs actually exists.

    Returns the fraction plus the NAMED missing assets, because a number on
    its own cannot be acted on."""
    checks = _asset_checks(conn, skill_id)
    have = [c for c in checks if c[1]]
    missing = [{"asset": c[0], "why": c[2]} for c in checks if not c[1]]
    return {"skill": skill_id,
            "label": SKILLS.get(skill_id, {}).get("label", skill_id),
            "score": len(have) / max(1, len(checks)),
            "have": [c[0] for c in have],
            "missing": missing,
            "authored_card": bool(rule_card(skill_id))}

# ---------------------------------------------------------------------------
# CONTENT MATURITY
# ---------------------------------------------------------------------------
# A learner cannot tell a thin page from a complete one by looking at it --
# both are formatted the same and both sound confident. That is how a 30%
# skill gets read as a finished chapter. The label makes the difference
# visible before the material is trusted, and it is derived from the
# completeness score rather than asserted.

MATURITY_LEVELS = {
    "gold":   ("Gold", "Reviewed rule, sourced, with examples, contrasts and "
                       "transfer assets."),
    "silver": ("Silver", "Reliable rule and examples; some advanced assets "
                         "missing."),
    "bronze": ("Bronze", "Usable explanation, but contrast, source or transfer "
                         "coverage is incomplete."),
    "draft":  ("Draft", "Generated or candidate material. Not authoritative."),
    "gap":    ("Gap", "Too little verified content here to teach from. Read it "
                      "as notes, not as a chapter."),
}

def content_maturity(conn, skill_id):
    """Gold / Silver / Bronze / Draft / Gap for one skill."""
    c = skill_completeness(conn, skill_id)
    score = c["score"]
    have = set(c["have"])
    # Generated material is served from the candidate bank, not QUIZ_LIST,
    # so "is a promoted candidate live on this skill" has to be asked of the
    # bank; QUIZ_LIST is kept in the test for any authored row flagged the
    # same way.
    promoted_here = any(skill_id in (p.get("skills") or [])
                        for p in promoted_candidates(conn))
    if promoted_here or any((q.get("generated") for q in QUIZ_LIST
                             if skill_id in Q_MATRIX.get(q["id"], []))):
        key = "draft"
    elif score >= 0.95 and c["authored_card"]:
        key = "gold"
    elif score >= 0.75 and {"worked example", "canonical rule"} <= have:
        key = "silver"
    elif score >= 0.5 and "worked example" in have:
        key = "bronze"
    else:
        key = "gap"
    label, meaning = MATURITY_LEVELS[key]
    return {"key": key, "label": label, "meaning": meaning,
            "score": score, "missing": c["missing"]}

def maturity_mix(conn):
    """Distribution across the bank, so the overall state is one number."""
    out = {k: 0 for k in MATURITY_LEVELS}
    for sid in SKILLS:
        try:
            out[content_maturity(conn, sid)["key"]] += 1
        except Exception:
            continue
    return out

# ---------------------------------------------------------------------------
# ONE ENTRY POINT FOR STUDY MATERIAL
# ---------------------------------------------------------------------------
# Material was reachable through four different calls with four different
# shapes -- dense_skill_content, build_skill_dossier, mission_brief,
# compile_focus_guide -- and callers had to know which. This is the single
# door, with the mode chosen by what the learner is doing rather than by
# which function the developer remembered.
#
# It NEVER blocks on generation or a network call. Everything returned is
# already on disk; anything that would need a model is reported as absent,
# not waited for.

def get_study_material(conn, skill_id, mode="adaptive"):
    """Study material for one skill. mode: deep | adaptive | reference."""
    if skill_id not in SKILLS:
        return None
    base = {"skill": skill_id,
            "label": SKILLS[skill_id].get("label", skill_id),
            "maturity": content_maturity(conn, skill_id)}

    if mode == "reference":
        base["content"] = dense_skill_content(conn, skill_id)
        base["card"] = rule_card(skill_id)
        return base

    if mode == "deep":
        base["content"] = dense_skill_content(conn, skill_id)
        base["dossier"] = build_skill_dossier(conn, skill_id)
        base["completeness"] = skill_completeness(conn, skill_id)
        return base

    # adaptive: whatever the learner should do next on this skill
    base["dossier"] = build_skill_dossier(conn, skill_id)
    try:
        spec = compile_learning_mission(conn, skill_id)
        base["mission"] = (mission_state(conn, open_mission(conn, spec))
                           if spec else None)
    except Exception:
        base["mission"] = None
    base["content"] = dense_skill_content(conn, skill_id)
    return base

def completeness_report(conn, limit=None):
    """Completeness across every skill, worst first.

    This is the authoring work order: it says which skills cannot currently
    teach themselves and exactly which asset each one is missing."""
    rows = []
    for sid in SKILLS:
        try:
            rows.append(skill_completeness(conn, sid))
        except Exception:
            continue
    rows.sort(key=lambda r: r["score"])
    total = sum(r["score"] for r in rows) / max(1, len(rows))

    # Which asset is missing most often across the whole bank -- the single
    # highest-leverage thing to author next.
    tally = {}
    for r in rows:
        for m in r["missing"]:
            tally[m["asset"]] = tally.get(m["asset"], 0) + 1
    ranked = sorted(tally.items(), key=lambda kv: -kv[1])

    return {"mean": total, "skills": len(rows),
            "complete": sum(1 for r in rows if r["score"] >= 0.999),
            "weak": sum(1 for r in rows if r["score"] < 0.6),
            "worst": rows[:limit] if limit else rows,
            "most_missing": ranked}

def completeness_line(c):
    """One honest sentence for the brief."""
    pct = c["score"] * 100
    if c["score"] >= 0.999:
        return "This skill has every asset it needs to teach itself."
    miss = ", ".join(m["asset"] for m in c["missing"][:3])
    more = (f" and {len(c['missing']) - 3} more"
            if len(c["missing"]) > 3 else "")
    return (f"{pct:.0f}% of the material this skill needs exists. "
            f"Missing: {miss}{more}. That is a content gap, not a gap in you.")


def dense_skill_content(conn, skill_id):
    """EVERYTHING authored about this skill, organised for reading.

    Written after measuring a real brief: 166 words of authored material
    existed for the skill on screen and 14 were shown, while ~120 words of
    commentary explained why the brief was short. The app was talking about
    itself more than about the subject. Nothing here is capped at three
    bullets and nothing is dropped because a stance says the learner
    "doesn't need" it -- a person who opened a page about easements wants
    the material on easements.

    Worked examples are the densest asset and were never shown at all: the
    stem, the keyed answer and the reasoning together are how a rule is
    actually taught, and all three were sitting in QUIZ_BANK unused."""
    meta = SKILLS.get(skill_id) or {}
    items = [q for q in QUIZ_LIST if skill_id in Q_MATRIX.get(q["id"], [])]
    raw = enrichment().get("misconceptions") or {}
    out = {"label": meta.get("label", skill_id), "blocks": []}

    def add(kind, heading, rows, source):
        if rows:
            out["blocks"].append({"kind": kind, "heading": heading,
                                  "rows": rows, "source": source})

    # 1. The distinctions, with BOTH sides spelled out rather than a label.
    discs, seen = [], set()
    for q in items:
        try:
            nb = neighbours(conn, "item", q["id"], edge_type="confusable_with",
                            limit=3)
        except Exception:
            break
        for e in nb:
            why = (e["evidence"] or "").strip()
            partner = QUIZ_BANK.get(e["dst_id"])
            if not why or why in seen:
                continue
            seen.add(why)
            if " — " in why:
                pair, decider = why.split(" \u2014 ", 1)
            else:
                pair, decider = why, ""
            discs.append({"pair": pair.strip(), "decider": decider.strip(),
                          "this": (q.get("exp") or "").strip(),
                          "other": (partner.get("exp") or "").strip() if partner else ""})
    add("distinction", "What decides it", discs, "confusion graph (authored)")

    # 2. Worked examples: stem, answer, reasoning. The densest asset there
    #    is, and previously unused outside question feedback.
    worked = []
    for q in sorted(items, key=lambda x: x.get("b_irt", 0.0)):
        opts = q.get("opts") or []
        key = opts[q["a"]] if q.get("a", 0) < len(opts) else ""
        worked.append({"stem": q.get("q", ""), "answer": key,
                       "why": (q.get("exp") or "").strip(),
                       "level": ("core" if q.get("b_irt", 0) < -0.3 else
                                 "qualifier" if q.get("b_irt", 0) < 0.6 else "edge"),
                       "id": q["id"]})
    add("worked", "Worked through", worked, f"{len(items)} authored item(s)")

    # 3. Why the wrong options look right.
    traps = []
    for q in items:
        rec = raw.get(q["id"]) or {}
        c_ = (rec.get("concept") or "").strip()
        if c_ and c_ not in traps:
            traps.append(c_)
        for _k, v in (rec.get("distractors") or {}).items():
            v = str(v).strip()
            if v and v not in traps:
                traps.append(v)
    add("trap", "Why the wrong answers look right", traps,
        "authored misconception tags")

    # 4. DEFINITIONS. Flashcard term/definition pairs for the terms in this
    #    skill's name -- authored, canonical, and never surfaced outside the
    #    flashcard deck.
    # Words like "estate", "rights" and "property" appear across half the
    # bank, so matching on them pulled RESPA and the Real Estate Commission
    # into a brief about leasehold estates. Only distinctive terms are used.
    _STOP = {"estate", "estates", "rights", "property", "interest", "interests",
             "types", "years", "value", "agent", "agreement", "license",
             "licence", "broker", "seller", "buyer", "requirements", "general",
             "under", "which", "other", "their"}
    terms = [w for w in re.split(r"[^A-Za-z]+", meta.get("label", ""))
             if len(w) > 5 and w.lower() not in _STOP]
    if not terms:
        terms = [w for w in re.split(r"[^A-Za-z]+", meta.get("label", ""))
                 if len(w) > 4 and w.lower() not in _STOP]
    defs = []
    for card in FLASHCARDS:
        blob = (card.get("term", "") + " " + card.get("def", "")).lower()
        if any(t.lower() in blob for t in terms):
            # No markdown: these strings go into Tk labels, which render
            # asterisks literally rather than bolding. The guide compiler
            # adds its own emphasis when it writes Markdown.
            defs.append(f"{card['term']} \u2014 {card['def']}")
    add("definition", "Definitions", defs[:6], "flashcard deck (authored)")

    # 5. THE REST OF THE BANK. The Q-matrix tags 3 items to this skill while
    #    10 mention its terms; restricting to the tagged set threw away 60%
    #    of the relevant material. These are marked as related rather than
    #    tagged, because the distinction is real: a tagged item is an
    #    authored claim that the item tests this skill, a term match is not.
    tagged = {q["id"] for q in items}
    related = []
    for q in QUIZ_LIST:
        if q["id"] in tagged:
            continue
        blob = (q.get("q", "") + " " + (q.get("exp") or "") + " "
                + " ".join(q.get("opts") or [])).lower()
        if any(t.lower() in blob for t in terms):
            e = (q.get("exp") or "").strip()
            if e:
                related.append({"stem": q.get("q", ""), "why": e, "id": q["id"]})
    add("related", "Elsewhere in the bank", related[:8],
        "items mentioning these terms (not Q-matrix tagged)")

    # 6. Where the rule is stated in prose.
    note = TOPICS.get(meta.get("topic"), {}).get("notes", "")
    sents = []
    for raw_s in re.split(r"(?<=[.!?])\s+", note or ""):
        s_ = raw_s.strip()
        if len(s_) > 30 and any(t.lower() in s_.lower() for t in terms):
            sents.append(s_)
    add("note", "In the source note", sents[:4],
        f"{TOPICS.get(meta.get('topic'), {}).get('short', '')} study note")

    # 7. Siblings, so the brief is a place in a map rather than an island.
    sibs = []
    for s_id in topic_skill_ids(meta.get("topic") or ""):
        if s_id == skill_id:
            continue
        sibs.append({"skill": s_id,
                     "label": SKILLS.get(s_id, {}).get("label", s_id)})
    add("sibling", "Next to this in the same topic", sibs[:8],
        "Q-matrix (authored)")

    # 8. What this rests on.
    try:
        b = upstream_bottleneck(conn, skill_id)
    except Exception:
        b = None
    if b:
        add("prereq", "This rests on",
            [f"{b['label']} \u2014 currently {(b['mastery'] or 0)*100:.0f}%. "
             "Shore that up first; drilling this on its own will not fix it."],
            "prerequisite graph (inferred)")

    return out

def dossier_related_skills(conn, skill_id, limit=5):
    """Neighbouring skills worth reading next, by graph adjacency rather
    than by alphabetical accident."""
    meta = SKILLS.get(skill_id)
    if not meta:
        return []
    out = []
    for sid, sm in SKILLS.items():
        if sid == skill_id or sm.get("topic") != meta.get("topic"):
            continue
        out.append(sid)
    return out[:limit]


# ===========================================================================
# LEARNING MISSIONS  --  the dossier as a causal intervention, not a document
# ===========================================================================
# The dossier diagnoses and then trusts the learner to act. A mission has
# STATE: it opens against a specific target result, names the smallest thing
# blocking it, and stays open until the learner has demonstrated the
# reasoning generalises. Rereading does not close it.
#
# Four gates, and the last two are the ones that make this more than a quiz:
#
#   DISCRIMINATION  can you separate the lookalikes right now
#   OWN WORDS       can you state the rule without the options in front of
#                   you (free recall, not recognition)
#   DELAYED         can you still do it after a spacing interval -- the
#                   single best predictor of exam-day retention, and the one
#                   thing an immediate quiz cannot test
#   TRANSFER        does it survive changed wording or facts
#
# TWO EPISTEMIC COMMITMENTS, both taken from the review and both load-bearing:
#
# 1. A diagnosed misconception is a HYPOTHESIS, not a finding. "You selected
#    this distractor three times, which is consistent with using X as the
#    deciding fact" is defensible. "You believe X" is not -- the same
#    answers are consistent with guessing, misreading, or time pressure.
#    Stating it as fact and being wrong makes the learner distrust the whole
#    system.
#
# 2. The brief must not hand over an answer the learner is currently
#    supposed to produce. Commit-then-check, never check-then-commit.

MISSION_KINDS = ("prerequisite_repair", "misconception_repair",
                 "confusable_contrast", "transfer_verification")

MISSION_GATES = ("discrimination", "own_words", "delayed", "transfer")

# A delayed check earlier than this is testing working memory, not retention.
MISSION_DELAY_HOURS = 20

# A gate the bank cannot offer (transfer on a single-item skill) is recorded
# as passed with this prefix in `detail`, so the pass is visible as a waiver
# in the evidence trail rather than indistinguishable from a demonstration.
WAIVED_PREFIX = "waived: "

def _skill_item_count(skill_id):
    return sum(1 for q in QUIZ_LIST if skill_id in Q_MATRIX.get(q["id"], []))

def init_mission_schema(conn):
    conn.executescript("""
    CREATE TABLE IF NOT EXISTS missions (
        mission_id   INTEGER PRIMARY KEY AUTOINCREMENT,
        kind         TEXT NOT NULL,
        skill_id     TEXT,
        partner_id   TEXT,
        target       TEXT,
        hypothesis   TEXT,
        status       TEXT NOT NULL DEFAULT 'open',
        opened_at    TEXT NOT NULL,
        closed_at    TEXT,
        priority     REAL DEFAULT 0
    );
    CREATE TABLE IF NOT EXISTS mission_evidence (
        id           INTEGER PRIMARY KEY AUTOINCREMENT,
        mission_id   INTEGER NOT NULL,
        gate         TEXT NOT NULL,
        passed       INTEGER NOT NULL,
        detail       TEXT,
        occurred_at  TEXT NOT NULL
    );
    """)
    conn.commit()

def _target_statement(kind, skill_label, partner_label=None):
    """A performance objective, not a subject label.

    "Topic: Easements" tells the learner nothing about what success looks
    like. The difference matters because the objective is what the gates are
    then checked against."""
    return {
        "prerequisite_repair":
            f"Use {skill_label} correctly in a new scenario, having first made "
            "the skill it depends on reliable.",
        "misconception_repair":
            f"Given an unfamiliar fact pattern, apply {skill_label} by "
            "identifying the decisive fact rather than a surface cue.",
        "confusable_contrast":
            f"Separate {skill_label} from {partner_label or 'its lookalike'} "
            "in a new scenario, and say which fact decided it.",
        "transfer_verification":
            f"Apply {skill_label} to changed wording and changed numbers, not "
            "only to the items you have already seen.",
    }.get(kind, f"Apply {skill_label} correctly.")

def _partner_label(partner, skill_id):
    """The lookalike named in a mission target. `partner` is whatever the
    confusion graph handed over -- an item id (the common case) or a skill
    id -- and the sentence needs the SKILL it stands for, not a truncated
    question stem. None when nothing resolves, so the target falls back to
    'its lookalike'."""
    if not partner:
        return None
    if partner in SKILLS and partner != skill_id:
        return SKILLS[partner].get("label")
    for s in Q_MATRIX.get(partner, []):
        if s != skill_id and s in SKILLS:
            return SKILLS[s].get("label")
    return None

# ===========================================================================
# SKILL-LEVEL FORGETTING  --  FSRS stability applied to sub-skills
# ===========================================================================
# FSRS-6 schedules 75 flashcards. The 172 sub-skills -- the units the whole
# diagnostic layer reasons about -- had no forgetting curve at all: a skill
# mastered in June read as mastered in December. The research note's
# second-ranked recommendation is exactly this gap, and the fix reuses two
# things already built rather than adding a model:
#
#   * the DSR (difficulty / stability / retrievability) form FSRS already
#     uses, so a skill's stability is computed the same way a card's is;
#   * observation_weight(), so the "grade" a skill receives from an answer
#     is the evidence-weighted one -- a 4-second guess that happened to be
#     right does not extend a skill's stability the way a confident,
#     normally-paced answer does.
#
# This is a deliberately simple half-life model (Settles & Meeder 2016 HLR
# form) rather than the full FSRS parameter set, because the full set was
# fitted on card reviews across many learners and there is no basis for
# assuming it transfers to sub-skill mastery at n=1. The constants are
# conservative and stated.

SKILL_HL_INITIAL_DAYS = 3.0      # first successful evidence buys ~3 days
SKILL_HL_GROWTH = 1.9            # each weighted success multiplies stability
SKILL_HL_LAPSE = 0.45            # a weighted miss shrinks it
SKILL_HL_MAX_DAYS = 120.0

def skill_retention_state(conn, skill_id):
    """Stability (days), last evidence time, and current retrievability.

    Walks the learner's attempts on this skill oldest-first, updating a
    half-life the way HLR/FSRS update stability, with each step scaled by
    the observation weight of that answer."""
    items = [q["id"] for q in QUIZ_LIST if skill_id in Q_MATRIX.get(q["id"], [])]
    if not items:
        return None
    # Same evidence rule as record_attempt's own skill-FSRS path: a
    # sanctioned pretest miss is not a lapse and a heavily-hinted answer is
    # not a retrieval, so neither may move a forgetting curve.
    rows = measurement_rows(conn, "question_id IN ({})".format(",".join("?" * len(items))),
                            tuple(items),
                            columns="correct, time_taken, confidence, timestamp")
    never = {"skill": skill_id, "stability_days": 0.0, "retrievability": None,
             "last": None, "n": len(rows), "state": "never"}
    if not rows:
        return never

    times = [r["time_taken"] for r in rows if r["time_taken"]]
    rt_model = personal_rt_model(times)
    stability = 0.0
    last = None
    learned = False
    for r in rows:
        try:
            ts = datetime.fromisoformat(r["timestamp"])
        except Exception:
            continue
        w = observation_weight(bool(r["correct"]), r["time_taken"], r["confidence"],
                               None, median_secs=None, rt_model=rt_model)
        if r["correct"]:
            learned = True
            if stability <= 0:
                stability = SKILL_HL_INITIAL_DAYS * w
            else:
                # THE SPACING EFFECT, applied literally. Stability grows in
                # proportion to how much of the current half-life had
                # elapsed before the successful recall: answering the same
                # skill eight times in one sitting is massed practice and
                # barely moves it, while one success after a real gap is
                # the evidence that the memory actually held. The first
                # version multiplied on every success regardless and hit
                # the 120-day cap from eight same-second answers.
                gap = ((ts - last).total_seconds() / 86400.0) if last else 0.0
                spaced = min(1.0, gap / max(0.5, stability))   # 0 massed .. 1 fully spaced
                growth = 1.0 + (SKILL_HL_GROWTH - 1.0) * w * (0.08 + 0.92 * spaced)
                stability *= growth
        else:
            stability *= (1.0 - (1.0 - SKILL_HL_LAPSE) * w)
        stability = min(SKILL_HL_MAX_DAYS, max(0.0, stability))
        last = ts

    # Nothing can be forgotten that was never known: until the first
    # success there is no memory to decay, and "never learned" must not
    # read as "lost" (the remedies are opposite -- first instruction vs.
    # retrieval practice). Retrievability is None, not 0, so callers
    # cannot mistake it for a measured collapse.
    if not learned or not last:
        return never

    elapsed = ((datetime.now() - last).total_seconds() / 86400.0) if last else 0.0
    r_now = (0.5 ** (elapsed / stability)) if stability > 0 else 0.0
    state = ("never" if not last else
             "fresh" if r_now >= 0.9 else
             "fading" if r_now >= 0.6 else
             "due" if r_now >= 0.3 else "lost")
    return {"skill": skill_id, "stability_days": round(stability, 2),
            "retrievability": round(r_now, 3), "elapsed_days": round(elapsed, 1),
            "last": last.isoformat() if last else None, "n": len(rows),
            "state": state}

def decayed_skill_mastery(conn, skill_id, mastery):
    """DINA mastery discounted by what has been forgotten since.

    Mastery is what the evidence supported at the time; retrievability is
    how much of it is still there. Reporting the product is the honest
    figure, and it is what makes a June mastery stop reading as a December
    one."""
    st = skill_retention_state(conn, skill_id)
    if not st or st["n"] == 0 or st["state"] == "never" or st["retrievability"] is None:
        return mastery
    r = st["retrievability"]
    # never let decay push below the prior floor -- the evidence existed
    return max(0.15 * mastery, mastery * (0.35 + 0.65 * r))

def skills_due_for_review(conn, limit=12):
    """Sub-skills whose retention has decayed enough to warrant a probe --
    the skill-level analogue of a flashcard being due."""
    out = []
    for sid in SKILLS:
        st = skill_retention_state(conn, sid)
        if st and st["n"] and st["state"] in ("due", "fading", "lost"):
            out.append(st)
    out.sort(key=lambda x: x["retrievability"])
    return out[:limit]

def compile_learning_mission(conn, skill_id=None):
    """Choose the single highest-value mission for this learner right now.

    Ordered by consequence, not convenience: a broken prerequisite outranks
    a misconception, which outranks a lookalike, which outranks a transfer
    check. Fixing a downstream symptom while the dependency is broken is
    wasted effort, so the ordering is the intervention."""
    init_mission_schema(conn)

    candidates = []
    skills = [skill_id] if skill_id else list(SKILLS)

    for sid in skills:
        try:
            d = build_skill_dossier(conn, sid)
        except Exception:
            continue
        if not d or d["seen"] == 0:
            continue
        label = d["label"]
        m = d["mastery"] or 0.0

        if d["stance"] == "blocked":
            chain = _prereq_chain(conn, sid, depth=1)
            if chain:
                candidates.append({
                    "kind": "prerequisite_repair", "skill": chain[0]["skill"],
                    "blocked_skill": sid, "partner": None,
                    "priority": 100 - m * 10,
                    "hypothesis": (
                        f"{label} keeps failing, and {chain[0]['label']} sits "
                        f"underneath it at {(chain[0]['mastery'] or 0)*100:.0f}%. "
                        "The dependency is the likelier cause. This is an "
                        "inferred link, not an authored one."),
                    "label": chain[0]["label"]})
                continue

        if d["stance"] == "misconception" or d["confident_wrong"] >= 2:
            wrong = _your_wrong_ideas(conn, _skill_state(conn, sid))
            if wrong:
                w = wrong[0]
                candidates.append({
                    "kind": "misconception_repair", "skill": sid,
                    "partner": None, "priority": 90 - m * 10,
                    "hypothesis": (
                        f"You selected “{w['your_answer'][:80]}” "
                        f"{w['times']}\u00d7. "
                        + (f"That is consistent with {w['why_wrong'][:150]}"
                           if w.get("why_wrong")
                           else "That pattern is consistent with a specific wrong "
                                "rule rather than random error.")
                        + " Treat this as a hypothesis to test, not a "
                          "conclusion about what you believe."),
                    "label": label})
                continue

        discs = _discriminators(conn, _skill_state(conn, sid))
        if discs and m < DOSSIER_STRONG + 0.1:
            candidates.append({
                "kind": "confusable_contrast", "skill": sid,
                "partner": discs[0]["pair"][1], "priority": 70 - m * 10,
                "hypothesis": discs[0]["distinction"],
                "label": label})
            continue

        if m >= DOSSIER_STRONG:
            gg = generalization_gap(conn)
            if gg.get("status") == "ok" and gg.get("gap", 0) > 0.2:
                candidates.append({
                    "kind": "transfer_verification", "skill": sid,
                    "partner": None, "priority": 50,
                    "hypothesis": (
                        f"Seed items {gg['seed_accuracy']*100:.0f}% vs variants "
                        f"{gg['variant_accuracy']*100:.0f}%. Strong scores here "
                        "may reflect familiarity with these specific items."),
                    "label": label})

    if not candidates:
        return None
    candidates.sort(key=lambda c: -c["priority"])
    return candidates[0]

def open_mission(conn, spec):
    """Persist a mission. Reuses an existing open one for the same target so
    revisiting a skill continues the work rather than resetting it."""
    init_mission_schema(conn)
    existing = _safe_query(conn, """SELECT * FROM missions
                                     WHERE kind=? AND skill_id=? AND status IN
                                           ('open','in_progress')
                                  ORDER BY mission_id DESC LIMIT 1""",
                           (spec["kind"], spec["skill"]))
    if existing:
        return existing[0]["mission_id"]
    cur = conn.execute("""INSERT INTO missions
        (kind, skill_id, partner_id, target, hypothesis, status, opened_at, priority)
        VALUES (?,?,?,?,?,?,?,?)""",
        (spec["kind"], spec["skill"], spec.get("partner"),
         _target_statement(spec["kind"], spec.get("label", spec["skill"]),
                           _partner_label(spec.get("partner"), spec["skill"])),
         spec.get("hypothesis", ""), "open", datetime.now().isoformat(),
         spec.get("priority", 0)))
    conn.commit()
    _audit(conn, "mission_opened", f"{spec['kind']} on {spec['skill']}")
    return cur.lastrowid

def record_gate(conn, mission_id, gate, passed, detail=""):
    if gate not in MISSION_GATES:
        return False
    init_mission_schema(conn)
    conn.execute("""INSERT INTO mission_evidence
        (mission_id, gate, passed, detail, occurred_at) VALUES (?,?,?,?,?)""",
        (mission_id, gate, 1 if passed else 0, detail[:240],
         datetime.now().isoformat()))
    conn.execute("UPDATE missions SET status='in_progress' "
                 "WHERE mission_id=? AND status='open'", (mission_id,))
    conn.commit()
    # Keep the belief graph in step with the mission. Doing it here rather
    # than at the call sites means no gate can be recorded without the
    # belief lifecycle seeing it.
    try:
        sync_belief_from_mission(conn, mission_id)
    except Exception:
        pass
    return True

def mission_state(conn, mission_id):
    """Which gates are passed, and whether the delayed one is even eligible.

    The delayed gate deliberately cannot be satisfied in the same sitting.
    A learner who could close a mission in one session by answering four
    things in a row has demonstrated working memory, not retention, and the
    whole point of the gate is that it takes time to earn."""
    init_mission_schema(conn)
    rows = _safe_query(conn, "SELECT * FROM missions WHERE mission_id=?",
                       (mission_id,))
    if not rows:
        return None
    m = rows[0]
    ev = _safe_query(conn, """SELECT gate, passed, detail, occurred_at FROM mission_evidence
                               WHERE mission_id=? ORDER BY id""", (mission_id,))
    passed = {}
    waived = set()
    for r in ev:
        if r["passed"]:
            passed[r["gate"]] = r["occurred_at"]
            if (r["detail"] or "").startswith(WAIVED_PREFIX):
                waived.add(r["gate"])

    # Transfer needs a second item on the skill. Where the bank has only
    # one (nearly half the skills), the gate can never be earned and the
    # mission would sit in the repair pile forever with the learner told a
    # repair is still due. The waiver is written as evidence with a stated
    # reason rather than skipped in the arithmetic, so the audit trail shows
    # WHY the mission closed on three gates.
    if ("transfer" not in passed and m["status"] in ("open", "in_progress")
            and m["skill_id"] and _skill_item_count(m["skill_id"]) < 2):
        now_iso = datetime.now().isoformat()
        conn.execute("""INSERT INTO mission_evidence
            (mission_id, gate, passed, detail, occurred_at) VALUES (?,?,?,?,?)""",
            (mission_id, "transfer", 1, WAIVED_PREFIX + "single-item skill", now_iso))
        conn.commit()
        _audit(conn, "mission_gate_waived", f"mission={mission_id} transfer: single-item skill")
        passed["transfer"] = now_iso
        waived.add("transfer")

    # The delayed check is measured from the REPAIR, not from when the
    # mission was opened. Missions are opened by the loop and by merely
    # viewing a skill, often a day or more before the learner runs the
    # repair; anchoring on opened_at let the "delayed" check be taken in the
    # same sitting as the immediate gates, which is exactly the working-
    # memory pass the gate exists to exclude. A waived gate is not a repair
    # event, so it cannot anchor the clock either.
    opened = m["opened_at"]
    anchor = max((passed[g] for g in ("discrimination", "own_words", "transfer")
                  if g in passed and g not in waived), default=None) or opened
    eligible_delayed = False
    try:
        age_h = (datetime.now() - datetime.fromisoformat(anchor)).total_seconds() / 3600.0
        eligible_delayed = age_h >= MISSION_DELAY_HOURS
    except (TypeError, ValueError):
        age_h = 0.0

    complete = all(g in passed for g in MISSION_GATES)
    return {"mission_id": mission_id, "kind": m["kind"], "skill": m["skill_id"],
            "target": m["target"], "hypothesis": m["hypothesis"],
            "status": m["status"], "passed": passed, "waived": sorted(waived),
            "outstanding": [g for g in MISSION_GATES if g not in passed],
            "age_hours": round(age_h, 1), "anchor": anchor,
            "delayed_eligible": eligible_delayed,
            "complete": complete,
            "blocked_note": (None if eligible_delayed or "delayed" in passed else
                             f"The delayed check unlocks in "
                             f"{max(0, MISSION_DELAY_HOURS - age_h):.0f}h. It "
                             "cannot be rushed \u2014 that is what makes it "
                             "evidence of retention rather than of a good five "
                             "minutes.")}

def close_mission_if_proven(conn, mission_id):
    st = mission_state(conn, mission_id)
    if not st or not st["complete"]:
        return False
    conn.execute("UPDATE missions SET status='repaired', closed_at=? "
                 "WHERE mission_id=?", (datetime.now().isoformat(), mission_id))
    conn.commit()
    _audit(conn, "mission_repaired", f"mission={mission_id} {st['kind']}")
    return True

def missions_due_now(conn):
    """Missions with something the learner can actually do RIGHT NOW.

    Splits into two piles because they need different screens: a mission
    still missing its immediate gates runs the repair sequence, whereas one
    waiting only on the delayed check needs a single retrieval attempt and
    nothing else. Without this split the delayed gate was unreachable --
    it unlocked at 20h and then nothing ever presented it, so no mission
    could ever reach 'repaired' and the whole gate structure was
    decorative."""
    init_mission_schema(conn)
    repair, delayed = [], []
    for m in _safe_query(conn, """SELECT mission_id FROM missions
                                   WHERE status IN ('open','in_progress')
                                ORDER BY priority DESC LIMIT 12"""):
        st = mission_state(conn, m["mission_id"])
        if not st:
            continue
        outstanding = set(st["outstanding"])
        if outstanding == {"delayed"} and st["delayed_eligible"]:
            delayed.append(st)
        elif outstanding - {"delayed"}:
            repair.append(st)
    return {"repair": repair, "delayed": delayed,
            "waiting": sum(1 for m in _safe_query(
                conn, "SELECT mission_id FROM missions WHERE status='in_progress'")
                if (mission_state(conn, m["mission_id"]) or {}).get("outstanding")
                == ["delayed"])}

def grade_own_words(conn, mission_id, text, reference=""):
    """Grade a restatement on substance rather than length.

    A word count let eight words of anything clear the gate. This uses the
    same coverage measure the Free Recall view already trusts, and abstains
    upward rather than downward: if nothing can judge it, a plausible-length
    answer passes, because failing a learner on a check the app cannot
    actually perform would be worse than a false pass."""
    txt = (text or "").strip()
    if len(txt.split()) < 8:
        return False, "too short to be a statement of the rule"
    if not reference:
        return True, "recorded (no reference text available to score against)"
    try:
        score, _covered, missed = keyword_coverage(txt, reference)
    except Exception:
        return True, "recorded (scorer unavailable)"
    if score >= 0.45:
        return True, f"covers the key terms ({score*100:.0f}%)"
    return False, ("misses the deciding terms"
                   + (f": {', '.join(list(missed)[:3])}" if missed else ""))

def active_missions(conn, limit=6):
    init_mission_schema(conn)
    return _safe_query(conn, """SELECT * FROM missions
                                 WHERE status IN ('open','in_progress')
                              ORDER BY priority DESC, mission_id DESC LIMIT ?""",
                       (limit,))

def mission_brief(conn, spec_or_id):
    """The learner-facing brief: target, hypothesis, decisive question,
    contrast, and the gates still outstanding."""
    if isinstance(spec_or_id, int):
        st = mission_state(conn, spec_or_id)
        if not st:
            return None
        sid = st["skill"]
        kind, hypothesis, target = st["kind"], st["hypothesis"], st["target"]
        gates = st
    else:
        sid = spec_or_id["skill"]
        kind = spec_or_id["kind"]
        hypothesis = spec_or_id.get("hypothesis", "")
        target = _target_statement(kind, spec_or_id.get("label", sid))
        gates = None

    d = build_skill_dossier(conn, sid)
    if not d:
        return None
    stt = _skill_state(conn, sid)
    discs = _discriminators(conn, stt)

    # The decisive question -- a procedure, not a definition. This is what
    # the learner is meant to run on a new fact pattern.
    decisive = None
    if discs:
        decisive = discs[0]["distinction"]

    return {"skill": sid, "label": d["label"], "kind": kind,
            "target": target, "hypothesis": hypothesis,
            "decisive": decisive,
            "contrast": discs[:2],
            "sections": d["sections"],
            "gates": gates,
            "items": [q["id"] for q in stt["items"]]}


# ===========================================================================
# THE LEARNER BELIEF GRAPH
# ===========================================================================
# The app tracks whether a skill is mastered. It does not track WHAT THE
# LEARNER APPEARS TO BELIEVE -- and those are different objects with
# different lifecycles. Mastery is a number that drifts; a belief is a
# specific proposition that is either held or not, accumulates evidence for
# and against, and can come back after appearing to be fixed.
#
# The state that forced this to be its own structure is REOPENED. A mission
# that passes its immediate gates and then fails the delayed check is not
# "still in progress" -- it is a belief that looked repaired and was not.
# Recording that as the same open mission loses the most diagnostically
# useful fact available: that the repair did not survive a night. A learner
# whose misconception has reopened twice needs a different intervention
# from one meeting it for the first time, and nothing in the app could tell
# them apart.
#
# Evidence is APPEND-ONLY and two-sided. A belief is never edited, only
# added to, so the history of what supported and weakened it stays
# reconstructable -- the same discipline the governance plane applies to
# policies, applied to claims about a person.

BELIEF_STATES = ("active", "under_repair", "provisionally_repaired",
                 "repaired", "reopened")

def init_belief_schema(conn):
    conn.executescript("""
    CREATE TABLE IF NOT EXISTS beliefs (
        belief_id    INTEGER PRIMARY KEY AUTOINCREMENT,
        skill_id     TEXT,
        topic_id     TEXT,
        hypothesis   TEXT NOT NULL,
        state        TEXT NOT NULL DEFAULT 'active',
        created_at   TEXT NOT NULL,
        updated_at   TEXT,
        reopen_count INTEGER DEFAULT 0
    );
    CREATE TABLE IF NOT EXISTS belief_evidence (
        id          INTEGER PRIMARY KEY AUTOINCREMENT,
        belief_id   INTEGER NOT NULL,
        direction   TEXT NOT NULL,
        kind        TEXT NOT NULL,
        detail      TEXT,
        weight      REAL DEFAULT 1.0,
        occurred_at TEXT NOT NULL
    );
    CREATE INDEX IF NOT EXISTS ix_belief_ev ON belief_evidence(belief_id);
    """)
    # Evidence is keyed back to the mission that produced it so a second
    # mission on the same skill can be synced without re-copying (or, as
    # before, silently skipping) the first mission's rows.
    cols = {r[1] for r in conn.execute("PRAGMA table_info(belief_evidence)")}
    if "mission_id" not in cols:
        try:
            conn.execute("ALTER TABLE belief_evidence ADD COLUMN mission_id INTEGER")
        except sqlite3.OperationalError:
            pass
    conn.commit()

def register_belief(conn, skill_id, hypothesis, topic_id=None):
    """Open a belief hypothesis, or return the live one for this skill.

    Deliberately one active belief per skill: two competing hypotheses about
    the same skill would both accumulate the same evidence and neither would
    ever resolve."""
    init_belief_schema(conn)
    # Match the most recent belief for this skill REGARDLESS of state.
    # Excluding repaired ones looked right and was not: syncing again after
    # a belief closed found nothing live and started a fresh row, so the
    # reopen history -- the single most useful thing this table stores --
    # was silently reset to zero on the very event that proved it mattered.
    # Reopening is a state transition on the existing belief, never a new
    # belief.
    rows = _safe_query(conn, """SELECT * FROM beliefs
                                 WHERE skill_id=?
                              ORDER BY belief_id DESC LIMIT 1""", (skill_id,))
    hypothesis = (hypothesis or "")[:400]
    if rows:
        # A later mission may name a different wrong rule for the same
        # skill. The belief stays the same row (its reopen history is the
        # point), but the proposition it states follows the newest
        # hypothesis; an empty hypothesis means "no opinion", not "erase".
        if hypothesis and hypothesis != (rows[0]["hypothesis"] or ""):
            conn.execute("UPDATE beliefs SET hypothesis=?, updated_at=? WHERE belief_id=?",
                         (hypothesis, datetime.now().isoformat(), rows[0]["belief_id"]))
            conn.commit()
            _audit(conn, "belief_rehypothesised",
                   f"belief={rows[0]['belief_id']} {skill_id}: {hypothesis[:80]}")
        return rows[0]["belief_id"]
    cur = conn.execute("""INSERT INTO beliefs
        (skill_id, topic_id, hypothesis, state, created_at, updated_at)
        VALUES (?,?,?,?,?,?)""",
        (skill_id, topic_id or SKILLS.get(skill_id, {}).get("topic"),
         hypothesis or f"Unresolved rule on {skill_id}", "active",
         datetime.now().isoformat(), datetime.now().isoformat()))
    conn.commit()
    _audit(conn, "belief_registered", f"{skill_id}: {hypothesis[:80]}")
    return cur.lastrowid

def add_belief_evidence(conn, belief_id, direction, kind, detail="", weight=1.0,
                        mission_id=None, occurred_at=None):
    """Append evidence. `direction` is 'supports' or 'weakens'. Evidence
    copied from a mission gate carries the mission id and the gate's own
    timestamp so the copy is identifiable and never made twice."""
    if direction not in ("supports", "weakens"):
        return False
    init_belief_schema(conn)
    conn.execute("""INSERT INTO belief_evidence
        (belief_id, direction, kind, detail, weight, occurred_at, mission_id)
        VALUES (?,?,?,?,?,?,?)""",
        (belief_id, direction, kind, detail[:300], float(weight),
         occurred_at or datetime.now().isoformat(), mission_id))
    conn.commit()
    return True

# Ordering of belief states for "did this move down?" A demotion from a
# repaired state on failed evidence is a REOPEN, not a quiet slide back.
_BELIEF_RANK = {"active": 0, "under_repair": 1, "reopened": 1,
                "provisionally_repaired": 2, "repaired": 3}

def set_belief_state(conn, belief_id, state, note=""):
    if state not in BELIEF_STATES:
        return False
    init_belief_schema(conn)
    prev = _safe_query(conn, "SELECT state, reopen_count FROM beliefs "
                             "WHERE belief_id=?", (belief_id,))
    bump = 0
    if prev and state == "reopened":
        bump = 1
    conn.execute("""UPDATE beliefs SET state=?, updated_at=?,
                    reopen_count=reopen_count+? WHERE belief_id=?""",
                 (state, datetime.now().isoformat(), bump, belief_id))
    conn.commit()
    _audit(conn, "belief_state", f"belief={belief_id} -> {state} {note}"[:200])
    return True

def belief_view(conn, belief_id):
    """A belief with its two-sided evidence, for display."""
    init_belief_schema(conn)
    rows = _safe_query(conn, "SELECT * FROM beliefs WHERE belief_id=?",
                       (belief_id,))
    if not rows:
        return None
    b = rows[0]
    ev = _safe_query(conn, """SELECT * FROM belief_evidence WHERE belief_id=?
                            ORDER BY id DESC LIMIT 20""", (belief_id,))
    supports = [e for e in ev if e["direction"] == "supports"]
    weakens = [e for e in ev if e["direction"] == "weakens"]
    return {"belief_id": belief_id, "skill": b["skill_id"],
            "topic": b["topic_id"], "hypothesis": b["hypothesis"],
            "state": b["state"], "reopen_count": b["reopen_count"] or 0,
            "supports": [dict(e) for e in supports],
            "weakens": [dict(e) for e in weakens],
            "net": sum(e["weight"] for e in supports)
                   - sum(e["weight"] for e in weakens)}

def active_beliefs(conn, limit=10):
    init_belief_schema(conn)
    return _safe_query(conn, """SELECT * FROM beliefs WHERE state != 'repaired'
                              ORDER BY reopen_count DESC, belief_id DESC
                                 LIMIT ?""", (limit,))

def sync_belief_from_mission(conn, mission_id):
    """Translate mission progress into belief-state changes.

    This is where REOPENED gets produced. A mission whose immediate gates
    passed moves the belief to provisionally_repaired; only the delayed
    check promotes it to repaired. A failed delayed check after that
    reopens it and records the failure as weakening evidence -- which is
    the fact a learner most needs and previously had no way to see."""
    st = mission_state(conn, mission_id)
    if not st or not st.get("skill"):
        return None
    bid = register_belief(conn, st["skill"], st.get("hypothesis") or "")

    ev = _safe_query(conn, """SELECT gate, passed, detail, occurred_at
                                FROM mission_evidence WHERE mission_id=?
                            ORDER BY id""", (mission_id,))
    # Copy each gate result across exactly once, keyed by the mission and
    # the gate's own timestamp. Counting rows belief-wide (the old rule)
    # meant a second mission on the same skill found the count already
    # "used up" by the first and recorded nothing. Rows written before the
    # mission_id column existed match on (gate, time) alone.
    have = set()
    for e in _safe_query(conn, "SELECT mission_id, kind, occurred_at FROM belief_evidence "
                               "WHERE belief_id=?", (bid,)) or []:
        have.add((e["mission_id"], e["kind"], e["occurred_at"]))
    waived = set(st.get("waived") or ())
    for r in ev:
        kind = f"gate:{r['gate']}"
        # A waiver is a statement about the bank, not evidence about the
        # learner; it counts toward closing the mission and nothing else.
        if r["gate"] in waived and (r["detail"] or "").startswith(WAIVED_PREFIX):
            continue
        if (mission_id, kind, r["occurred_at"]) in have or (None, kind, r["occurred_at"]) in have:
            continue
        add_belief_evidence(
            conn, bid,
            "weakens" if r["passed"] else "supports",
            kind, r["detail"] or "",
            weight=(1.5 if r["gate"] == "delayed" else 1.0),
            mission_id=mission_id, occurred_at=r["occurred_at"])

    passed = st["passed"]
    immediate = {"discrimination", "own_words", "transfer"}
    # A failed delayed check stands until the repair sequence is re-run:
    # once an immediate gate passes AFTER it, the belief is back in the
    # provisional stage waiting on the next delayed check.
    last_fail = max((i for i, r in enumerate(ev)
                     if r["gate"] == "delayed" and not r["passed"]), default=None)
    delayed_failed = (last_fail is not None and "delayed" not in passed and
                      not any(r["passed"] and r["gate"] in immediate
                              and not (r["detail"] or "").startswith(WAIVED_PREFIX)
                              for r in ev[last_fail + 1:]))

    cur = _safe_query(conn, "SELECT state FROM beliefs WHERE belief_id=?", (bid,))
    prev = cur[0]["state"] if cur else "active"
    if st["complete"]:
        new = "repaired"
    elif delayed_failed:
        # REOPENED means it looked fixed and did not survive -- so it needs
        # a repaired state to fall from. A delayed check failed before any
        # repair was demonstrated is just more evidence the belief is held.
        new = ("reopened" if prev in ("provisionally_repaired", "repaired", "reopened")
               else "under_repair")
    elif immediate <= set(passed):
        new = "provisionally_repaired"
    elif set(passed) - waived:
        new = "under_repair"
    else:
        new = "active"

    failed_here = any(not r["passed"] for r in ev)
    if prev == "reopened" and new in ("active", "under_repair"):
        # A reopened belief stays reopened until it is repaired again;
        # partial progress does not erase the fact that it came back.
        new = prev
    elif _BELIEF_RANK.get(new, 0) < _BELIEF_RANK.get(prev, 0):
        if prev in ("provisionally_repaired", "repaired") and failed_here:
            # Any demotion from a repaired state on failed evidence is the
            # belief coming back, whichever gate exposed it.
            new = "reopened"
        elif not failed_here:
            # A newly opened mission with no failures yet says nothing
            # against the earlier repair.
            new = prev
    if prev != new:
        set_belief_state(conn, bid, new, f"from mission {mission_id}")
    return belief_view(conn, bid)

def belief_summary_line(bv):
    """One honest sentence about where a belief stands."""
    if not bv:
        return ""
    if bv["state"] == "repaired":
        return "Repaired, and it survived a delayed check."
    if bv["state"] == "reopened":
        n = bv["reopen_count"]
        return (f"This came back after appearing fixed"
                + (f" ({n}\u00d7)" if n > 1 else "")
                + ". A second pass of the same explanation is unlikely to be "
                  "what closes it.")
    if bv["state"] == "provisionally_repaired":
        return ("Provisionally repaired \u2014 the immediate checks passed. It "
                "is not settled until it survives a spacing interval.")
    if bv["state"] == "under_repair":
        return "Under repair; some evidence in, not enough to call it."
    return "Active hypothesis, not yet tested."


# ===========================================================================
# THE FULL STUDY GUIDE COMPILER
# ===========================================================================
# Everything up to now has produced one fragment at a time: a dossier for a
# skill you clicked, a mission for a gap you happened to open. This compiles
# the WHOLE THING -- every topic, every skill, ordered for this learner,
# with their own errors written into it -- as a single document they can
# read away from the app.
#
# Three properties that make it a guide rather than a dump:
#
#   ORDERED BY CONSEQUENCE, NOT BY TOPIC NUMBER. Prerequisites come before
#   the skills that depend on them, and within that, weakest first. Reading
#   a guide front to back should mean fixing things in the order that makes
#   the next thing learnable. A textbook cannot do this because it does not
#   know which of its chapters you are failing.
#
#   PERSONALISED WHERE THERE IS EVIDENCE, GENERIC WHERE THERE IS NOT. A
#   skill with 20 answers gets the learner's actual wrong options and a
#   diagnosis; one with none gets the authored rule and says plainly that
#   nothing is personalised yet. Pretending to personalise from no data is
#   how these systems lose trust.
#
#   ASSEMBLED, NEVER INVENTED. Same rule as everywhere else: every sentence
#   traces to an authored item explanation, misconception tag, confusion
#   rationale or topic note. The guide is large because the corpus is
#   recombined many ways, not because anything was generated.

def _guide_ordering(conn):
    """Topics and skills in the order they should be READ.

    Weakest-first within a topic, but a prerequisite always precedes what
    depends on it -- a topological nudge rather than a full sort, since the
    prerequisite edges are inferred and a cycle must not be able to hang the
    compiler."""
    order = []
    frag = all_topic_fragility(conn)
    topics = sorted(TOPICS.items(),
                    key=lambda kv: -(frag.get(kv[0], {}).get("score", 0)))

    for tid, t in topics:
        sids = topic_skill_ids(tid)
        mast = {}
        try:
            if len(sids) >= 2:
                post = dina_topic_posterior(conn, tid)
                if post:
                    mast = post["skill_mastery"]
        except Exception:
            pass
        ranked = sorted(sids, key=lambda s: mast.get(s, 0.5))

        # Pull any prerequisite ahead of its dependent.
        placed, guard = [], set()
        for s in ranked:
            if s in guard:
                continue
            try:
                b = upstream_bottleneck(conn, s)
            except Exception:
                b = None
            if b and b["skill"] in ranked and b["skill"] not in guard:
                placed.append(b["skill"])
                guard.add(b["skill"])
            placed.append(s)
            guard.add(s)
        order.append((tid, t, placed, mast))
    return order

def _decision_rule(conn, sid, items):
    """The procedure to RUN on a new fact pattern, not a definition to read.

    A study guide organised around definitions teaches recognition. One
    organised around the question you ask first teaches the thing the exam
    actually measures: applying a rule to facts you have not seen. This is
    built from the confusion graph, which is where the deciding fact for
    each pair is already written down."""
    steps, seen = [], set()
    for q in items:
        try:
            nb = neighbours(conn, "item", q["id"], edge_type="confusable_with",
                            limit=2)
        except Exception:
            break
        for e in nb:
            why = (e["evidence"] or "").strip()
            if not why or why in seen:
                continue
            seen.add(why)
            # Authored pairs are written as "A vs. B -- the deciding fact",
            # which is already the shape of a decision step.
            if " — " in why:
                pair, decider = why.split(" \u2014 ", 1)
                steps.append((pair.strip(), decider.strip()))
            else:
                steps.append((why, ""))
        if len(steps) >= 3:
            break
    return steps

def _skill_guide_section(conn, sid, mastery):
    """One skill's chapter, built around the DECISION RULE.

    Restructured deliberately. The previous version led with paragraphs
    lifted from the topic note, which is the weakest asset in the corpus:
    2,787 words across 18 generic documents, against 7,020 words of item
    explanations that are specific, tied to real test items, and map to 172
    skills through the Q-matrix. Leading with the note meant every chapter
    opened with the most general text available and buried the most
    specific. The order below is now: what to ask, how it is reasoned, what
    the wrong answers are actually doing, then your own errors."""
    meta = SKILLS.get(sid, {})
    label = meta.get("label", sid)
    items = [q for q in QUIZ_LIST if sid in Q_MATRIX.get(q["id"], [])]
    lines = [f"### {label}", ""]

    try:
        d = build_skill_dossier(conn, sid)
    except Exception:
        d = None

    if d and d["seen"]:
        pct = (d["mastery"] or 0) * 100
        lines.append(f"*{pct:.0f}% mastery from {d['seen']} answer(s) "
                     f"\u2014 evidence {d['evidence']}.*  **{d['headline']}**")
        lines.append("")

    # ---- 1. THE DECISION RULE ----
    steps = _decision_rule(conn, sid, items)
    if steps:
        lines.append("**Ask this first**")
        lines.append("")
        for pair, decider in steps:
            lines.append(f"- **{pair}** \u2192 {decider}" if decider
                         else f"- {pair}")
        lines.append("")

    # ---- 2. WORKED REASONING, easiest rule to hardest edge case ----
    tiers = {"core": [], "qualifier": [], "edge": []}
    for q in sorted(items, key=lambda x: x.get("b_irt", 0.0)):
        e = (q.get("exp") or "").strip()
        if not e:
            continue
        b = q.get("b_irt", 0.0)
        t = "core" if b < -0.3 else ("qualifier" if b < 0.6 else "edge")
        if e not in tiers[t]:
            tiers[t].append(e)
    for key, heading in (("core", "The rule, worked"),
                         ("qualifier", "Where it gets qualified"),
                         ("edge", "Edge cases the exam likes")):
        if tiers[key]:
            lines.append(f"**{heading}**")
            lines.append("")
            for e in tiers[key][:4]:
                lines.append(f"- {e}")
            lines.append("")

    # ---- 3. WHY THE WRONG ANSWERS LOOK RIGHT ----
    # 625 words of per-option rationale that the old structure never used.
    # Read the RAW enrichment record. enriched_misconception() flattens to
    # {concept, diagnosis} and drops the distractors dict entirely, so the
    # obvious call silently yielded nothing and this whole section rendered
    # zero times across all 172 skills.
    traps = []
    _raw = enrichment().get("misconceptions") or {}
    for q in items:
        rec = _raw.get(q["id"]) or {}
        concept = (rec.get("concept") or "").strip()
        if concept and concept not in traps:
            traps.append(concept)
        for _k, v in (rec.get("distractors") or {}).items():
            v = str(v).strip()
            if v and v not in traps:
                traps.append(v)
    if traps:
        lines.append("**Why the wrong answers look right**")
        lines.append("")
        for t in traps[:4]:
            lines.append(f"- {t}")
        lines.append("")

    # ---- 4. YOUR OWN ERRORS ----
    if d and d["seen"]:
        for sec in d["sections"]:
            if sec["key"] != "wrong":
                continue
            lines.append("**What you specifically got wrong**")
            lines.append("")
            for l in sec["lines"]:
                lines.append(f"- {l}")
            lines.append("")
    elif not steps and not any(tiers.values()):
        lines.append("*Thin coverage: this skill has little authored material "
                     "behind it. That is a content gap, not a gap in you.*")
        lines.append("")

    # ---- 5. RETRIEVAL CHECKPOINT ----
    if items:
        lines.append("**Check yourself**")
        lines.append("")
        for q in items[:3]:
            lines.append(f"- {q['q']}")
        lines.append("")
        lines.append(f"<sub>{len(items)} item(s) test this skill. Answers are "
                     "deliberately omitted \u2014 looking them up is recognition, "
                     "not retrieval.</sub>")
        lines.append("")
    return lines

def compile_study_guide(conn, include_solid=True, max_skills=None):
    """The whole guide, as Markdown.

    `include_solid=False` produces a revision guide: only what is weak or
    unproven, which is the version worth printing the week before an exam."""
    theta, se, n = ability_with_se(conn)
    _t, mean_score, p_pass = predict_pass_probability(conn)
    days = days_to_exam(conn)

    L = ["# NJ Real Estate Salesperson \u2014 Personal Study Guide", ""]
    L.append(f"*Compiled {datetime.now().strftime('%Y-%m-%d %H:%M')} from your own "
             f"answers. Not a generic study guide: the order, the emphasis and "
             f"the worked errors are all yours.*")
    L.append("")

    # ---- where you stand ----
    L.append("## Where you stand")
    L.append("")
    L.append(f"- Ability estimate: **{theta:+.2f}** (standard error {se:.2f})")
    L.append(f"- Simulated 110-question exam: **{mean_score:.1f}%**")
    L.append(f"- Estimated probability of passing: **{p_pass*100:.0f}%**")
    L.append(f"- Answers on record: **{n}**")
    if days is not None:
        L.append(f"- Days to your target exam date: **{days}**")
    L.append("")
    if n < 40:
        L.append("> These figures rest on limited evidence. Treat the ordering "
                 "below as provisional until you have answered more.")
        L.append("")

    # ---- how to use it ----
    L.append("## How to use this")
    L.append("")
    L.append("Chapters are ordered by what is costing you most, not by exam "
             "blueprint order, and a skill that another skill depends on is "
             "placed before it. Reading front to back therefore fixes things "
             "in the order that makes the next thing learnable.")
    L.append("")
    L.append("Everything here is assembled from material already written and "
             "reviewed \u2014 item explanations, misconception tags, confusion "
             "rationales and topic notes. Nothing was generated.")
    L.append("")

    # ---- open repairs ----
    try:
        beliefs = active_beliefs(conn, limit=8)
    except Exception:
        beliefs = []
    if beliefs:
        L.append("## Open repairs")
        L.append("")
        L.append("Specific rules the system thinks you may be holding wrongly. "
                 "These are hypotheses drawn from your answer patterns, not "
                 "conclusions.")
        L.append("")
        for b in beliefs:
            bv = belief_view(conn, b["belief_id"])
            if not bv:
                continue
            lab = SKILLS.get(bv["skill"], {}).get("label", bv["skill"])
            L.append(f"- **{lab}** \u2014 {belief_summary_line(bv)}")
            if bv["hypothesis"]:
                L.append(f"  <br><sub>{bv['hypothesis'][:300]}</sub>")
        L.append("")

    # ---- the chapters ----
    written = 0
    for tid, t, sids, mast in _guide_ordering(conn):
        # The cap is on skill sections; once it is reached no further
        # chapter header should be emitted either, or a capped guide ends
        # in a run of empty chapters.
        if max_skills and written >= max_skills:
            break
        f = (all_topic_fragility(conn) or {}).get(tid, {})
        L.append(f"## {t['name']}")
        L.append("")
        bits = [t.get("group", "")]
        if f.get("n"):
            bits.append(f"{f.get('label','')} \u00b7 {f.get('accuracy',0):.0f}% accuracy "
                        f"over {f['n']} answer(s)")
        else:
            bits.append("not yet practised")
        L.append(f"*{'  \u00b7  '.join(b for b in bits if b)}*")
        L.append("")

        # The topic note is deliberately NOT the chapter opener any more. It
        # is the most general text in the corpus and led every chapter with
        # the least specific thing available. One paragraph as orientation,
        # then straight into the skills.
        if t.get("notes"):
            first = str(t["notes"]).split("\n\n")[0].strip()
            if first:
                L.append(f"<sub>{first[:400]}</sub>")
                L.append("")

        for sid in sids:
            m = mast.get(sid, 0.5)
            if not include_solid and m >= 0.75:
                continue
            if max_skills and written >= max_skills:
                break
            L.extend(_skill_guide_section(conn, sid, m))
            written += 1
        L.append("")

    # ---- appendices ----
    pairs = (enrichment().get("confusion_pairs") or [])
    if pairs:
        L.append("## Appendix A \u2014 Everything that looks like something else")
        L.append("")
        L.append("| Distinction | Deciding fact |")
        L.append("|---|---|")
        for pr in pairs[:40]:
            why = (pr.get("why") or "").replace("|", "/")
            if " — " in why:
                left, right = why.split(" \u2014 ", 1)
            else:
                left, right = why, ""
            L.append(f"| {left} | {right} |")
        L.append("")

    miscs = (enrichment().get("misconceptions") or {})
    if miscs:
        L.append("## Appendix B \u2014 Known traps")
        L.append("")
        seen = set()
        for qid, m in miscs.items():
            d_ = (m or {}).get("diagnosis")
            if d_ and d_ not in seen:
                seen.add(d_)
                L.append(f"- {d_}")
        L.append("")

    L.append("---")
    L.append("")
    L.append("*Estimates come from one learner's own answers against authored "
             "item parameters rather than population-calibrated ones. They "
             "describe this practice history, not a certified exam prediction.*")

    return "\n".join(L)

# ===========================================================================
# THE FOCUS GUIDE  --  depth where it is failing, not breadth everywhere
# ===========================================================================
# compile_study_guide() covers all 172 skills evenly. That is a reference
# work: correct, complete, and the wrong shape for someone with an exam and
# 85 skills below 50%. Reading it front to back spends as many words on a
# skill at 96% as on one at 4%.
#
# This allocates a PAGE BUDGET BY WEAKNESS. A skill at 4% earns a full
# treatment; a skill at 96% earns a line in a list at the back. Twenty pages
# of the material that is actually failing beats fifty-eight pages of
# everything.
#
# THE MATERIAL THAT MAKES DEPTH POSSIBLE was sitting unused: 888 wrong
# options, 4,289 words of them. Every wrong option is a worked
# counterexample -- a specific thing that looks right and is not -- and the
# app has never shown a single one outside the moment a learner picks it.
# Walking all four options of an item, saying what each one would mean and
# why three of them fail, is how a rule gets taught. Showing only the key
# teaches which letter to circle.

FOCUS_WORDS_PER_PAGE = 450

def _exam_weight(tid):
    """Roughly how much of the exam this topic is worth, for prioritising."""
    grp = TOPICS.get(tid, {}).get("group", "National")
    n_topics = sum(1 for t in TOPICS.values() if t.get("group") == grp)
    return (80 if grp == "National" else 30) / max(1, n_topics)

def focus_targets(conn, pages=20):
    """Which skills earn deep treatment, and in what order.

    Ranked by (weakness x exam weight x how much material exists). A skill
    that is failing but has one item and no explanation cannot be taught in
    depth no matter how weak it is, so material availability is part of the
    ranking rather than a disappointment discovered later."""
    rows = []
    for tid in TOPICS:
        sids = topic_skill_ids(tid)
        mast = {}
        if len(sids) >= 2:
            try:
                post = dina_topic_posterior(conn, tid)
                if post:
                    mast = post["skill_mastery"]
            except Exception:
                pass
        base = None
        for sid in sids:
            m = mast.get(sid)
            if m is None:
                if base is None:
                    base = get_mastery(conn, tid)
                m = base
            items = [q for q in QUIZ_LIST if sid in Q_MATRIX.get(q["id"], [])]
            material = sum(len((q.get("exp") or "").split())
                           + sum(len(o.split()) for o in (q.get("opts") or []))
                           for q in items)
            if material < 20:
                continue
            score = (1.0 - m) * _exam_weight(tid) * min(1.0, material / 120.0)
            rows.append({"skill": sid, "topic": tid, "mastery": m,
                         "items": items, "material": material,
                         "priority": score})
    rows.sort(key=lambda r: -r["priority"])

    budget = pages * FOCUS_WORDS_PER_PAGE
    chosen, used = [], 0
    for r in rows:
        if used >= budget:
            break
        chosen.append(r)
        # Measured, not guessed: a 20-page request produced 41 pages at 2.2x,
        # because option analysis, terms, contrasts and related cases all
        # stack on top of the raw item words.
        used += r["material"] * 4.6
    return chosen, rows

def _option_analysis(q):
    """Every option, with a verdict. The wrong ones are the counterexamples.

    Deliberately walks ALL options rather than the key alone: a learner who
    only ever sees the right answer learns which answer is right, not why
    the others are wrong, and the exam is built out of the others."""
    out = []
    opts = q.get("opts") or []
    key = q.get("a", 0)
    rec = (enrichment().get("misconceptions") or {}).get(q["id"]) or {}
    generic = ""
    for _k, v in (rec.get("distractors") or {}).items():
        generic = str(v).strip()
        break
    for i, o in enumerate(opts):
        if i == key:
            out.append({"letter": "ABCD"[i], "text": o, "correct": True,
                        "why": (q.get("exp") or "").strip()})
            continue

        # A wrong option marked only with a cross teaches nothing. Where no
        # misconception is authored, a rationale is DERIVED, and the source
        # is stated so a derived line is never mistaken for a reviewed one.
        why, src = generic, "authored misconception"
        if not why:
            # (a) the option names a term that has a definition -- saying
            #     what it actually is explains why it is not the answer.
            for card in FLASHCARDS:
                t = card.get("term", "")
                if len(t) > 4 and t.lower() in o.lower():
                    why = f"{t} is {card['def'][0].lower()}{card['def'][1:]}"
                    src = "definition"
                    break
        if not why:
            # (b) this option is the KEY somewhere else in the bank, so the
            #     counterexample is the case where it would be right.
            for other in QUIZ_LIST:
                if other["id"] == q["id"]:
                    continue
                oo = other.get("opts") or []
                a_ = other.get("a", 0)
                if a_ < len(oo) and oo[a_].strip().lower() == o.strip().lower():
                    why = (f"That is the answer when the facts are different: "
                           f"“{other['q'][:120]}”")
                    src = "another item in the bank"
                    break
        out.append({"letter": "ABCD"[i], "text": o, "correct": False,
                    "why": why, "src": src})
    return out

def comparison_table(conn, topic_id):
    """A cross-skill contrast table for one topic.

    Prose treats each concept separately and leaves the reader to hold four
    definitions in their head and diff them. A table does the diffing on the
    page. Rows are the concepts, columns are the dimensions the authored
    confusion pairs already say are decisive -- so the columns are not
    invented, they are read off the edges the bank already asserts.

    This is the densest format available from existing material, and the
    only one the app was not already producing."""
    pairs = []
    for pr in (enrichment().get("confusion_pairs") or []):
        a, b = pr.get("a"), pr.get("b")
        if a in QUIZ_BANK and QUIZ_BANK[a]["topic"] == topic_id and pr.get("why"):
            pairs.append(pr)
    if len(pairs) < 2:
        return None

    # Concepts = the keyed answers of the items in those pairs. The right
    # answer names the concept; the explanation describes it.
    concepts, dims = {}, []
    for pr in pairs:
        why = pr["why"]
        dim = why.split(" — ", 1)[1].strip() if " — " in why else "difference"
        if dim not in dims:
            dims.append(dim)
        for qid in (pr.get("a"), pr.get("b")):
            q = QUIZ_BANK.get(qid)
            if not q:
                continue
            opts = q.get("opts") or []
            name = opts[q["a"]] if q.get("a", 0) < len(opts) else q["id"]
            if name not in concepts:
                concepts[name] = {"desc": (q.get("exp") or "").strip(),
                                  "qid": q["id"], "dims": {}}
            concepts[name]["dims"][dim] = (q.get("exp") or "").strip()

    if len(concepts) < 2:
        return None
    return {"topic": topic_id,
            "name": TOPICS.get(topic_id, {}).get("name", topic_id),
            "dimensions": dims[:4],
            "concepts": [{"name": k, **v} for k, v in list(concepts.items())[:8]]}

def mixed_practice_set(conn, topic_id, n=8):
    """A cross-skill set from one topic, weakest sub-skills first.

    Every practice surface in the app serves items for ONE skill. That is
    not how an exam presents them: a real section mixes sub-skills, and
    interleaving is the condition under which discrimination actually gets
    trained. Blocked practice on a single skill produces confidence that
    collapses the moment the neighbouring concept appears."""
    sids = topic_skill_ids(topic_id)
    mast = {}
    try:
        post = dina_topic_posterior(conn, topic_id)
        if post:
            mast = post["skill_mastery"]
    except Exception:
        pass
    scored = []
    for q in QUIZ_LIST:
        if q["topic"] != topic_id:
            continue
        skills = Q_MATRIX.get(q["id"], [])
        weak = min((mast.get(s, 0.5) for s in skills), default=0.5)
        scored.append((weak, q))
    scored.sort(key=lambda x: x[0])
    picked, seen_skills = [], set()
    # Prefer breadth first: one item per weak skill before doubling up, so
    # the set interleaves rather than drilling one thing eight times.
    for weak, q in scored:
        sk = tuple(Q_MATRIX.get(q["id"], []))
        if sk and sk in seen_skills:
            continue
        seen_skills.add(sk)
        picked.append(q)
        if len(picked) >= n:
            break
    for weak, q in scored:
        if len(picked) >= n:
            break
        if q not in picked:
            picked.append(q)
    return picked

def compile_focus_guide(conn, pages=20):
    """A deep guide over the weakest material, as Markdown."""
    chosen, allrows = focus_targets(conn, pages)
    theta, se, n = ability_with_se(conn)
    _t, mean_score, p_pass = predict_pass_probability(conn)

    L = ["# Focus Guide — what is actually failing", ""]
    L.append(f"*Compiled {datetime.now().strftime('%Y-%m-%d')}. "
             f"Ability {theta:+.2f} · simulated exam {mean_score:.0f}% · "
             f"{n} answers on record.*")
    L.append("")
    L.append(f"This is not a reference work. It is roughly {pages} pages spent "
             f"on the {len(chosen)} sub-skills where weakness and exam weight "
             "overlap most, worked in full. Everything you already know is "
             "listed at the back in one line each.")
    L.append("")
    L.append("Each wrong answer is walked through, not just the right one. "
             "Exams are built out of the wrong answers.")
    L.append("")

    L.append("## What this covers, and why these")
    L.append("")
    L.append("| Sub-skill | Your mastery | Why it made the list |")
    L.append("|---|---|---|")
    for r in chosen:
        L.append(f"| {SKILLS.get(r['skill'], {}).get('label', r['skill'])} "
                 f"| {r['mastery']*100:.0f}% "
                 f"| {TOPICS[r['topic']]['short']}, "
                 f"~{_exam_weight(r['topic']):.0f} exam questions |")
    L.append("")

    for idx, r in enumerate(chosen, 1):
        sid = r["skill"]
        label = SKILLS.get(sid, {}).get("label", sid)
        L.append(f"## {idx}. {label}")
        L.append("")
        L.append(f"*You are at {r['mastery']*100:.0f}% here. "
                 f"{TOPICS[r['topic']]['name']}.*")
        L.append("")

        # the rule
        try:
            dense = dense_skill_content(conn, sid)
        except Exception:
            dense = {"blocks": []}
        for blk in dense["blocks"]:
            if blk["kind"] == "distinction" and blk["rows"]:
                L.append("**Ask this first**")
                L.append("")
                for d_ in blk["rows"]:
                    L.append(f"- **{d_['pair']}** — decided by "
                             f"{d_['decider'] or 'the fact below'}")
                    for side in (d_["this"], d_["other"]):
                        if side:
                            L.append(f"    - {side}")
                L.append("")
            if blk["kind"] == "definition" and blk["rows"]:
                L.append("**Terms**")
                L.append("")
                for d_ in blk["rows"]:
                    L.append(f"- {d_}")
                L.append("")

        # worked cases with FULL option analysis
        L.append("**Worked cases**")
        L.append("")
        for q in r["items"]:
            L.append(f"> {q['q']}")
            L.append("")
            for o in _option_analysis(q):
                mark = "**✓**" if o["correct"] else "✗"
                L.append(f"- {mark} **{o['letter']}.** {o['text']}")
                if o["why"]:
                    tag = ("Why this is right" if o["correct"]
                           else "Why this is wrong")
                    note = ("" if o["correct"] or o.get("src") == "authored misconception"
                            else f"  <sub>[{o.get('src', '')}]</sub>")
                    L.append(f"    - {tag}: {o['why']}{note}")
            L.append("")

        # related cases from elsewhere in the bank
        for blk in dense["blocks"]:
            if blk["kind"] == "related" and blk["rows"]:
                L.append("**The same rule, different facts**")
                L.append("")
                for r_ in blk["rows"][:4]:
                    L.append(f"- {r_['stem']}")
                    L.append(f"    - {r_['why']}")
                L.append("")
            if blk["kind"] == "trap" and blk["rows"]:
                L.append("**Traps**")
                L.append("")
                for t_ in blk["rows"][:4]:
                    L.append(f"- {t_}")
                L.append("")
            if blk["kind"] == "prereq" and blk["rows"]:
                L.append("**Fix this first**")
                L.append("")
                for t_ in blk["rows"]:
                    L.append(f"- {t_}")
                L.append("")

        try:
            cc = skill_completeness(conn, sid)
            if cc["score"] < 0.999:
                L.append(f"<sub>{completeness_line(cc)}</sub>")
                L.append("")
        except Exception:
            pass

    # everything else, one line each
    covered = {r["skill"] for r in chosen}
    rest = [r for r in allrows if r["skill"] not in covered]
    if rest:
        L.append("## Not covered here")
        L.append("")
        L.append("Solid enough, or too little material to teach in depth. "
                 "One line each so nothing is silently dropped.")
        L.append("")
        for r in sorted(rest, key=lambda x: -x["mastery"])[:60]:
            L.append(f"- {SKILLS.get(r['skill'], {}).get('label', r['skill'])} "
                     f"— {r['mastery']*100:.0f}%")
        L.append("")

    L.append("---")
    L.append("*Assembled from authored items, explanations and misconception "
             "tags. Nothing generated.*")
    return "\n".join(L)

def focus_guide_stats(conn, text=None, pages=20):
    txt = text if text is not None else compile_focus_guide(conn, pages)
    words = len(txt.split())
    return {"words": words, "approx_pages": round(words / FOCUS_WORDS_PER_PAGE, 1),
            "skills_deep": txt.count("\n## ") - 2,
            "counterexamples": txt.count("Why this is wrong")}

def export_focus_guide(conn, path, pages=20):
    txt = compile_focus_guide(conn, pages)
    with open(path, "w", encoding="utf-8") as fh:
        fh.write(txt)
    return focus_guide_stats(conn, txt, pages)


def study_guide_stats(conn, text=None):
    """Honest size reporting, so the guide is not oversold."""
    txt = text if text is not None else compile_study_guide(conn)
    words = len(txt.split())
    return {"words": words,
            "chapters": txt.count("\n## "),
            "skill_sections": txt.count("\n### "),
            "approx_pages": round(words / 450.0, 1)}

def export_study_guide(conn, path, include_solid=True):
    txt = compile_study_guide(conn, include_solid=include_solid)
    with open(path, "w", encoding="utf-8") as fh:
        fh.write(txt)
    return study_guide_stats(conn, txt)


def distinguishability_summary(conn):
    """Bank-wide roll-up for the Content QA view."""
    option_flags, insufficient = [], 0
    for q in QUIZ_LIST:
        res = separability_options(conn, q["id"])
        if not res:
            continue
        if res.get("status") == "insufficient":
            insufficient += 1
            continue
        for fp in res.get("flagged_pairs", []):
            option_flags.append({"question_id": q["id"], **fp})

    item_res = separability_items(conn)

    profile_topics, unident_total = [], 0
    for tid in TOPICS:
        res = separability_profiles(conn, tid)
        if res.get("status") != "ok":
            continue
        n_un = len(res["unidentified"])
        unident_total += n_un
        if n_un or res["orphan_skills"]:
            profile_topics.append(res)

    rel = unreliable_items(conn)
    person = session_person_fit(conn)

    return {
        "unreliable_items": rel["items"],
        "reliability_insufficient": rel["insufficient"],
        "person_fit": person,
        "option_flags": option_flags,
        "options_insufficient": insufficient,
        "item_pairs": item_res.get("pairs", []),
        "item_status": item_res.get("status"),
        "profile_topics": profile_topics,
        "unidentified_total": unident_total,
    }


def hint_effectiveness(conn):
    """How well does each hint level actually work, measured directly from
    outcomes rather than assumed. Reports, per level: how many times it was
    used and the accuracy of attempts made at that level, compared against
    your unhinted (level 0) baseline -- so a level whose accuracy barely
    beats your baseline is visibly not helping much, distinct from one that
    reliably rescues an answer. This is a genuinely different question from
    what effective_credit() answers: that asks "how much should a correct
    answer at this level count as evidence you knew it" (discounted,
    because it took scaffolding); this asks "does reaching for this level
    actually correlate with getting the question right"."""
    rows = conn.execute("""SELECT hint_level, correct FROM attempts
                            WHERE hint_level IS NOT NULL""").fetchall()
    if not rows:
        return None
    by = {}
    for r in rows:
        lvl = r["hint_level"] or 0
        d = by.setdefault(lvl, {"n": 0, "correct": 0})
        d["n"] += 1
        d["correct"] += 1 if r["correct"] else 0
    baseline = by.get(0, {"n": 0, "correct": 0})
    baseline_acc = (baseline["correct"] / baseline["n"]) if baseline["n"] else None
    out = []
    for lvl in sorted(by):
        d = by[lvl]
        acc = d["correct"] / d["n"]
        out.append({
            "level": lvl, "n": d["n"], "accuracy": acc,
            "vs_baseline": (acc - baseline_acc) if (lvl > 0 and baseline_acc is not None) else None,
        })
    return out

# ============================================================================
# METACOGNITIVE CALIBRATION -- Expected Calibration Error and Brier score,
# formalizing the predict-vs-actual comparison this app already collects
# confidence data for, rather than leaving it as an informal impression.
# ============================================================================
# The app's confidence rating is a 3-point ordinal scale (Guessing / Somewhat
# sure / Confident), not a continuous 0-100 probability, so it needs a
# representative-probability mapping before ECE/Brier (both defined for
# probabilistic predictions) apply. These are defensible representative
# midpoints for a 3-point scale, not a precise elicitation -- documented as
# an approximation rather than false precision.
CONFIDENCE_TO_PROB = {1: 0.30, 2: 0.65, 3: 0.90}  # Guessing / Somewhat sure / Confident

def calibration_metrics(conn, topic_id=None, modes=None):
    """Expected Calibration Error (bucketed by the 3 confidence levels
    themselves -- natural bins, since only 3 discrete ratings exist) and
    Brier score, from data the app already collects.

    Also reports a SEPARATE sensitivity signal per Fleming & Lau's
    metacognition framework: calibration (does average confidence track
    average accuracy) and sensitivity (does confidence discriminate a
    specific right answer from a specific wrong one) are two different
    skills. A learner can look well-calibrated on average (ECE near 0)
    while being unable to tell their own right answers from their wrong
    ones on a per-item basis -- sensitivity catches that, ECE alone does
    not."""
    where = "confidence IS NOT NULL"
    params = []
    if topic_id:
        where += " AND topic_id=?"
        params.append(topic_id)
    # Regime restriction, mirroring ability_with_se(modes=...). Calm and
    # pressured calibration are different constructs for exactly the reason
    # calm and pressured ABILITY are: a learner who reads their own
    # uncertainty well with no clock may lose that discrimination entirely
    # under time pressure. Pooling them reports an average of two different
    # skills and hides the gap.
    if modes:
        where += " AND mode IN (%s)" % ",".join("?" * len(modes))
        params.extend(modes)
    rows = _safe_query(conn, f"SELECT confidence, correct FROM attempts WHERE {where}", params)
    rows = [r for r in rows if r["confidence"] in CONFIDENCE_TO_PROB]
    if len(rows) < 5:
        return None

    by_level = {1: [], 2: [], 3: []}
    for r in rows:
        by_level[r["confidence"]].append(1 if r["correct"] else 0)
    n_total = len(rows)

    ece = 0.0
    per_level = {}
    for lvl, outcomes in by_level.items():
        if not outcomes:
            continue
        acc = sum(outcomes) / len(outcomes)
        conf = CONFIDENCE_TO_PROB[lvl]
        ece += (len(outcomes) / n_total) * abs(acc - conf)
        per_level[lvl] = {"n": len(outcomes), "accuracy": acc, "stated_confidence": conf}

    brier = sum((CONFIDENCE_TO_PROB[r["confidence"]] - (1 if r["correct"] else 0)) ** 2
                for r in rows) / n_total

    conf_correct = [CONFIDENCE_TO_PROB[r["confidence"]] for r in rows if r["correct"]]
    conf_incorrect = [CONFIDENCE_TO_PROB[r["confidence"]] for r in rows if not r["correct"]]
    sensitivity = None
    if conf_correct and conf_incorrect:
        sensitivity = (sum(conf_correct) / len(conf_correct)) - (sum(conf_incorrect) / len(conf_incorrect))

    mean_conf = sum(CONFIDENCE_TO_PROB[r["confidence"]] for r in rows) / n_total
    mean_acc = sum(1 for r in rows if r["correct"]) / n_total
    bias = mean_conf - mean_acc  # positive = overconfident, negative = underconfident

    # Murphy (1973) decomposition over the three confidence bins:
    #   Brier = uncertainty - resolution + reliability
    # exactly, because the stated probability is constant within a bin.
    # Reliability is how far each bin's stated confidence sits from its
    # hit rate (the squared-ECE analogue); resolution is how far the bins'
    # hit rates spread from the overall hit rate -- whether the rating
    # carries information at all. `reliability_over` keeps only the bins
    # rated ABOVE their hit rate: the part of miscalibration that makes a
    # learner skip reviewing what they do not know.
    uncertainty = mean_acc * (1.0 - mean_acc)
    resolution = reliability = reliability_over = 0.0
    for lvl, d in per_level.items():
        w = d["n"] / n_total
        resolution += w * (d["accuracy"] - mean_acc) ** 2
        gap = d["stated_confidence"] - d["accuracy"]
        reliability += w * gap ** 2
        if gap > 0:
            reliability_over += w * gap ** 2

    # Rank-based sensitivity: P(a right answer was rated more confidently
    # than a wrong one), ties counting half -- the Mann-Whitney AUC, the
    # non-parametric analogue of meta-d' (Fleming & Lau 2014). 0.5 means
    # the rating carries no information about which answers are right;
    # unlike the mean difference above it does not depend on the
    # probability mapping. Needs a few of each outcome to mean anything.
    sensitivity_auc = None
    n_right = len(conf_correct)
    n_wrong = len(conf_incorrect)
    if n_right >= 5 and n_wrong >= 5:
        right_by = {lvl: sum(by_level[lvl]) for lvl in (1, 2, 3)}
        wrong_by = {lvl: len(by_level[lvl]) - right_by[lvl] for lvl in (1, 2, 3)}
        wins = 0.0
        for lr in (1, 2, 3):
            for lw in (1, 2, 3):
                if lr > lw:
                    wins += right_by[lr] * wrong_by[lw]
                elif lr == lw:
                    wins += 0.5 * right_by[lr] * wrong_by[lw]
        sensitivity_auc = wins / (n_right * n_wrong)

    return {"n": n_total, "ece": ece, "brier": brier, "per_level": per_level,
            "sensitivity": sensitivity, "bias": bias,
            "uncertainty": uncertainty, "resolution": resolution,
            "reliability": reliability, "reliability_over": reliability_over,
            "sensitivity_auc": sensitivity_auc, "n_right": n_right, "n_wrong": n_wrong}

# Below this AUC a learner's ratings do not separate their right answers
# from their wrong ones; the remedy is different from overconfidence.
CALIBRATION_AUC_UNINFORMATIVE = 0.58

# Named cuts for the calibration reading. Calibration error is inferred
# state, so it decides WHICH sentence the learner reads and never appears in
# one: "about 12 points" is a model quantity, and a learner cannot act on the
# difference between 12 and 14 points anyway. The bands below are what the
# advice actually turns on.
CALIBRATION_MIN_RATINGS = 12
CALIBRATION_OVER_MIN = 0.08       # reliability, over-confident direction
CALIBRATION_OVER_WIDE = 0.15
CALIBRATION_BIAS_OVER = 0.04
CALIBRATION_BIAS_UNDER = -0.08
CALIBRATION_BIAS_UNDER_WIDE = -0.15


def calibration_reading(cal):
    """One plain-words reading of a calibration dict, shared by every
    learner-facing surface so they never disagree. Returns (kind, text):
    'uninformative' -- the ratings carry no information (AUC near 0.5),
    which self-testing fixes; 'overconfident' -- the ratings do track the
    answers but sit above the hit rate, which retrieving before judging
    fixes; 'underconfident'; 'tracking'; or None when there is too little."""
    if not cal or cal.get("n", 0) < CALIBRATION_MIN_RATINGS:
        return None, "Rate confidence on a few more items (J/K/L before answering) and this fills in."
    auc = cal.get("sensitivity_auc")
    bias = cal.get("bias", 0.0)
    over = math.sqrt(cal.get("reliability_over", 0.0))
    if auc is not None and auc < CALIBRATION_AUC_UNINFORMATIVE:
        return "uninformative", (
            "Your confidence ratings do not yet tell your right answers from your wrong "
            "ones — you feel about as sure either way. Test yourself before you rate: "
            "cover the options, say the answer from memory, then decide how sure you are.")
    if over >= CALIBRATION_OVER_MIN and bias > CALIBRATION_BIAS_OVER:
        margin = ("by a wide margin" if over >= CALIBRATION_OVER_WIDE
                  else "by a small but consistent margin")
        return "overconfident", (
            f"You are sure more often than you are right, {margin} where it matters. "
            "Retrieve before you judge: say the answer to yourself "
            "first, and rate 'Somewhat sure' unless you could explain why.")
    if bias < CALIBRATION_BIAS_UNDER:
        margin = ("well below" if bias < CALIBRATION_BIAS_UNDER_WIDE else "below")
        return "underconfident", (
            f"You rate yourself {margin} what the results show. "
            "You know more than you are giving yourself credit for.")
    return "tracking", "Your confidence and your accuracy are tracking each other well."

# ===========================================================================
# PASS 3 -- CALIBRATION ACTS ON SELECTION AND SCHEDULING
# ===========================================================================
# Calibration was display-only: a learner shown to be 47 points
# overconfident under pressure had that fact influence nothing. But
# overconfidence is precisely the condition under which a learner stops
# reviewing material they have not actually mastered -- it is the mechanism
# by which they walk into an exam feeling ready and are not.
#
# So per-topic calibration now does two things:
#   1. SELECTION -- topics where the learner is overconfident get a lift,
#      because that is where the gap between felt and actual mastery is
#      widest, and it is invisible to accuracy alone.
#   2. SCHEDULING -- overconfidence raises FSRS desired retention, which
#      tightens intervals. If you cannot tell whether you know something,
#      the safe response is to test it sooner.
#
# Underconfidence is deliberately NOT penalised. A learner who
# underestimates themselves is not at risk of skipping review; they are at
# risk of over-reviewing, and the app should not amplify that.

CALIBRATION_MIN_N = 8            # per-topic answers before this applies
CALIBRATION_MAX_BOOST = 0.45     # cap on the selection lift

_CALIB_TOPIC_CACHE = {"key": None, "bias": {}}

def topic_calibration_bias(conn):
    """Per-topic overconfidence in [0,1]-ish terms. Positive = overconfident.
    Topics without enough confidence-tagged answers are simply absent."""
    try:
        row = conn.execute("SELECT COUNT(*) c FROM attempts "
                           "WHERE confidence IS NOT NULL").fetchone()
        key = row["c"]
    except Exception:
        return {}
    if _CALIB_TOPIC_CACHE["key"] == key:
        return _CALIB_TOPIC_CACHE["bias"]
    out = {}
    prof = {}
    for tid in TOPICS:
        try:
            cal = calibration_metrics(conn, topic_id=tid)
        except Exception:
            cal = None
        if cal and cal.get("n", 0) >= CALIBRATION_MIN_N:
            out[tid] = cal["bias"]
            prof[tid] = {"bias": cal["bias"], "reliability_over": cal["reliability_over"],
                         "resolution": cal["resolution"],
                         "sensitivity_auc": cal["sensitivity_auc"], "n": cal["n"]}
    _CALIB_TOPIC_CACHE["key"] = key
    _CALIB_TOPIC_CACHE["bias"] = out
    _CALIB_TOPIC_CACHE["profile"] = prof
    return out

def topic_calibration_profile(conn):
    """Per-topic {bias, reliability_over, resolution, sensitivity_auc, n}
    for the topics with enough confidence-tagged answers -- what the
    selection boost reads. Shares topic_calibration_bias's cache."""
    topic_calibration_bias(conn)
    return _CALIB_TOPIC_CACHE.get("profile") or {}

def calibration_selection_boost(bias, cap=None, reliability_over=None):
    """Overconfidence -> selection lift. Underconfidence -> no penalty.

    The lift is driven by the OVERCONFIDENT part of Murphy's reliability
    term (its square root is the RMS gap between stated confidence and hit
    rate in the bins rated above their hit rate), not by the raw bias: a
    learner who rates 'Confident' and is wrong a third of the time while
    calling easy items guesses has a bias near zero and exactly the risk
    this lift exists for -- they will not review what they feel sure of.
    `bias` alone is still accepted for callers without the profile.
    `cap` is the governed ceiling (active_threshold "calibration_max_boost");
    the shipped constant applies when the caller has no connection."""
    if reliability_over is not None:
        over = math.sqrt(max(0.0, reliability_over))
    else:
        over = bias if bias is not None else 0.0
    if over <= 0.08:
        return 1.0
    cap = CALIBRATION_MAX_BOOST if cap is None else float(cap)
    return 1.0 + min(cap, (over - 0.08) * 1.2)

def calibration_by_regime(conn):
    """Calm vs. pressured calibration, split by the same MODE_TAXONOMY that
    already segments timing baselines and ability. Returns a dict with
    'calm' and 'pressure' entries (either may be None when that regime has
    too little confidence-tagged data yet) plus the pooled figure."""
    calm_modes = [m for m, (pace, regime) in MODE_TAXONOMY.items() if regime == "calm"]
    pressure_modes = [m for m, (pace, regime) in MODE_TAXONOMY.items() if regime == "pressure"]
    return {
        "calm": calibration_metrics(conn, modes=calm_modes) if calm_modes else None,
        "pressure": calibration_metrics(conn, modes=pressure_modes) if pressure_modes else None,
        "pooled": calibration_metrics(conn),
    }


# ============================================================================
# ADAPTIVE ENGINE v2
# ============================================================================
# The first version had four specific weaknesses, all of which matter:
#
#   1. It used a 2PL model on four-option multiple choice. 2PL says a
#      candidate of very low ability approaches 0% correct, but on 4-option
#      items they approach 25% by guessing alone. That biases ability
#      downward for weak candidates and mis-scores easy items.
#   2. It always selected the single maximum-information item, which in a
#      fixed bank means the same handful of items appear every session at a
#      given ability -- textbook over-exposure.
#   3. Selection ignored the exam blueprint, so an adaptive run could drift
#      to 90% national content when the real exam is 73/27.
#   4. Ability was a point estimate with no uncertainty, so "theta 0.38"
#      read identically whether it came from 6 answers or 600.
#
# This replaces all four with standard psychometric machinery.

GUESS_C = 0.25          # four options
THETA_GRID = [(-4.0 + 0.08 * i) for i in range(101)]

# ---------------------------------------------------------------------------
# POPULATION-ANCHORED PRIOR  (Bock & Mislevy 1982, EAP with an informative prior)
# ---------------------------------------------------------------------------
# The ability posterior was previously computed against a hardcoded N(0,1)
# prior -- a generic standard normal with no connection to this exam. That
# is the conventional default, and it is defensible, but it quietly asserts
# something false: that a learner with no history is an average member of an
# abstract population centred on theta=0, rather than an average member of
# the population that actually sits the NJ salesperson exam.
#
# WHY THIS IS THE RIGHT FORM OF ANCHORING, AND NAIVE BLENDING IS NOT.
# A tempting but wrong approach is to average the app's P(pass) with the
# published pass rate. That corrupts a conditional estimate with a marginal
# one: the published rate is a base rate over ALL candidates, while the
# app's number is conditional on THIS learner's demonstrated ability, and
# mixing them makes the result worse-calibrated while looking more
# authoritative.
#
# Anchoring the PRIOR is different and principled. It says only: "before I
# have evidence about you, my best guess is that you resemble a typical
# candidate." Bayes then does the rest -- EAP shrinks toward the prior mean
# exactly when data are sparse, and the evidence progressively overwhelms it
# as answers accumulate. The anchor decays automatically; nothing is blended
# after the fact.
#
# CALIBRATION OF THE ANCHOR. mu is chosen so the IRT-implied expected score
# at theta=mu lands near the exam's pass mark region, and sigma is kept wide
# (1.0) so the prior is genuinely weak -- an informative prior that is too
# tight would suppress real signal from a learner who is far from typical.
POPULATION_PRIOR_MU = 0.15    # slightly above the 70% cut, matching a majority-pass exam
POPULATION_PRIOR_SD = 1.0     # deliberately wide: anchor the centre, not the spread

def population_prior_weights():
    """Prior density over THETA_GRID. Kept as a function rather than a
    constant so the anchor can later be tuned (or disabled) without
    touching the estimator."""
    mu, sd = POPULATION_PRIOR_MU, POPULATION_PRIOR_SD
    return [math.exp(-0.5 * ((t - mu) / sd) ** 2) for t in THETA_GRID]
SE_TARGET = 0.30        # stop when the posterior is this precise
BLUEPRINT = {"National": 80 / 110, "NJ-Specific": 30 / 110}

# ============================================================================
# PSI CONTENT-AREA BLUEPRINT (per-topic, not just per-group)
# ============================================================================
# The group-level 73/27 split above is a coarse proxy: PSI's actual outline
# weights CONTENT AREAS unevenly within each portion (Contracts is ~19% of
# the national exam, Property Management only ~3%), and the bank's own
# 18 topics were near-uniformly sized (14-20 items each) rather than matched
# to that. Content-balanced selection was therefore hitting the right
# national/state ratio while still over-serving small content areas and
# under-serving large ones relative to what the real exam actually tests.
#
# National weights are PSI's own published percentages (2/1/2026 Candidate
# Information Bulletin) and map 1:1 onto this app's 11 national topics.
#
# NJ state weights are NOT this precise: PSI publishes item counts for four
# broad categories (2/3/22/3 of 30), but does NOT publish a further split of
# the 22-item "Statutes and Rules Governing Licensee Activities" bucket
# across its listed sub-areas (advertising, trust funds, agency/disclosure,
# contracts, etc.). Rather than inventing sub-percentages PSI never
# published, the five app topics that fall inside that 22-item bucket split
# it evenly; License Law and Commission Conduct are pinned to their own
# distinct published counts (Licensing Requirements = 3, Duties/Powers of
# the Commission = 2), and Fair Housing draws from the 3-item "Additional
# Requirements" bucket (shared on the real exam with the Guaranty Fund,
# Full Disclosure Act, and Timeshare Act, which this bank does not test
# separately, so the full 3 is allocated here rather than split further).
CONTENT_AREA_WEIGHTS = {
    # -- National (PSI %, /80 of the national portion) --
    "t1":  10 / 100,   # Rights & Interests    -> Property Ownership
    "t2":   6 / 100,   # Deeds & Title          -> Transfer of Title
    "t3":   5 / 100,   # Land Use & Zoning      -> Land Use Controls
    "t4":   8 / 100,   # Valuation              -> Valuation
    "t5":  10 / 100,   # Financing              -> Financing
    "t6":  13 / 100,   # Agency                 -> Agency
    "t7":  19 / 100,   # Contracts              -> Contracts
    "t8":   7 / 100,   # Disclosures            -> Property Disclosures
    "t9":   3 / 100,   # Leases                 -> Property Management
    "t10":  7 / 100,   # Calculations           -> Real Estate Calculations
    "t11": 12 / 100,   # Practice               -> Practice of Real Estate
    # -- NJ state (PSI item counts, /30 of the state portion) --
    "t12":  3 / 30,    # NJ License Law         -> Licensing Requirements
    "t18":  2 / 30,    # Commission Conduct     -> Duties/Powers of the Commission
    "t16":  3 / 30,    # NJ Fair Housing        -> Additional Requirements
    "t13": 22 / 30 / 4,  # NJ Agency Disclosure  -+
    "t14": 22 / 30 / 4,  # Attorney Review        |-- even split of the
    "t15": 22 / 30 / 4,  # Realty Transfer Fee    |   unpublished 22-item
    "t17": 22 / 30 / 4,  # Escrow & Trust         |   "Statutes and Rules"
    # (t13/t14/t15/t17 each get 22/30/4, one quarter of that bucket)
}
_CA_SUM = {"National": sum(v for k, v in CONTENT_AREA_WEIGHTS.items() if TOPICS[k]["group"] == "National"),
          "NJ-Specific": sum(v for k, v in CONTENT_AREA_WEIGHTS.items() if TOPICS[k]["group"] == "NJ-Specific")}


def topic_blueprint_priority(target_length=None, served_topics=None):
    """MPI-style continuous priority per TOPIC rather than per group (see
    select_next_item). Each topic's target item count is its
    CONTENT_AREA_WEIGHTS share of the appropriate portion of target_length
    (national share of the 80-question portion, state share of the 30), and
    priority is proportional to remaining need -- same design as the
    group-level version, just at finer granularity."""
    served_topics = served_topics or {}
    if not target_length:
        # No known session length: fall back to a flat proportional need
        # using each topic's overall exam-share directly.
        return {tid: max(0.05, w) for tid, w in CONTENT_AREA_WEIGHTS.items()}
    national_len = target_length * BLUEPRINT["National"]
    state_len = target_length * BLUEPRINT["NJ-Specific"]
    need = {}
    for tid, w in CONTENT_AREA_WEIGHTS.items():
        portion_len = national_len if TOPICS[tid]["group"] == "National" else state_len
        portion_sum = _CA_SUM[TOPICS[tid]["group"]]
        target_n = (w / portion_sum) * portion_len if portion_sum else 0
        need[tid] = max(0.0, target_n - served_topics.get(tid, 0))
    total_need = sum(need.values())
    if total_need <= 0:
        return {tid: 1.0 for tid in CONTENT_AREA_WEIGHTS}
    return {tid: v / total_need for tid, v in need.items()}



def irt_p3(theta, a, b, c=GUESS_C):
    """3PL: lower asymptote c accounts for guessing on multiple choice."""
    z = a * (theta - b)
    z = max(-30.0, min(30.0, z))
    return c + (1.0 - c) / (1.0 + math.exp(-z))


def _prior():
    # N(0, 1) over the grid
    w = population_prior_weights()
    s = sum(w)
    return [x / s for x in w]


def eap_theta(responses, c=GUESS_C):
    """Expected a posteriori ability plus posterior SD.

    A full posterior rather than a point MLE, because the standard error is
    what tells you whether an estimate is worth acting on. Returns
    (theta, se, posterior)."""
    post = _prior()
    for a, b, y in responses:
        # Reject non-finite item parameters BEFORE they reach the
        # likelihood. A single corrupt row -- inf or NaN in a_irt/b_irt,
        # which a partially-written or externally-edited database really can
        # contain -- propagated through the posterior and produced se=nan.
        # That is the worst failure class: a displayed number that is
        # silently meaningless rather than visibly broken. Skipping the row
        # loses one observation; keeping it poisons the whole estimate.
        a_v = a if (a is not None and math.isfinite(a) and a > 0) else 1.0
        b_v = b if (b is not None and math.isfinite(b)) else 0.0
        if abs(b_v) > 20 or a_v > 20:
            continue          # beyond any plausible calibrated range
        a, b = a_v, b_v
        new = []
        for i, t in enumerate(THETA_GRID):
            p = irt_p3(t, a if a else 1.0, b if b is not None else 0.0, c)
            like = p if y else (1.0 - p)
            new.append(post[i] * max(like, 1e-12))
        s = sum(new)
        if s <= 0:
            continue
        post = [x / s for x in new]
    mean = sum(t * w for t, w in zip(THETA_GRID, post))
    var = sum(w * (t - mean) ** 2 for t, w in zip(THETA_GRID, post))
    if not math.isfinite(mean):
        mean = POPULATION_PRIOR_MU
    if not math.isfinite(var) or var < 0:
        var = POPULATION_PRIOR_SD ** 2
    return round(mean, 4), round(math.sqrt(max(var, 1e-9)), 4), post


def fisher_info_3pl(theta, a, b, c=GUESS_C):
    """Information under 3PL. Note it is lower than 2PL near the guessing
    floor -- an easy item tells you almost nothing about a strong candidate,
    and a very hard item tells you little about a weak one who may have
    guessed."""
    p = irt_p3(theta, a, b, c)
    if p <= c + 1e-9 or p >= 1 - 1e-9:
        return 0.0
    q = 1.0 - p
    return (a ** 2) * (q / p) * (((p - c) / (1.0 - c)) ** 2)


CALIB_B_SD = 0.35   # assumed logit-scale uncertainty in an authored difficulty prior

def calibration_inflation(n_items, avg_a=1.0):
    """Approximate extra ability-estimate variance from AUTHORED (not
    empirically calibrated) item parameters. Patton, Diao & Boughton (2013)
    and a 2025 Behavior Research Methods study both find that calibration
    error deflates the posterior SE and can cause CAT to stop prematurely
    with unwarranted confidence -- exactly the situation here, since every
    a/b/c in this bank came from authoring, not a real calibration sample.

    This is a lightweight stand-in for the full Bayesian item-parameter-
    uncertainty model those papers use (which needs MCMC over an actual
    calibration sample we don't have), not a claim of matching it exactly:
    it treats each authored item as carrying a fixed parameter uncertainty
    that averages down across independently-authored items, so the reported
    SE is never smaller than what item uncertainty alone would imply."""
    if n_items <= 0:
        return 1.0
    per_item_var = (CALIB_B_SD / max(avg_a, 0.3)) ** 2
    return per_item_var / n_items

def ability_with_se(conn, topic_id=None, limit=600, modes=None, return_posterior=False):
    """Ability estimate with posterior SE.

    `modes` restricts the estimate to a set of session modes. This matters
    because pressure_profile() treats calm and pressured ability as
    genuinely different constructs -- that separation is the core of this
    app's thesis about test-taking dynamics -- yet the unrestricted estimate
    pools both into one average. Callers that drive adaptive item selection
    should pass the regime they are actually operating in, so the engine
    picking your next question isn't averaging away the very distinction the
    dashboard is telling you matters.

    `return_posterior=True` appends the full grid posterior over THETA_GRID
    as a fourth element, fitted to exactly the rows the point estimate
    used, so posterior-weighted item selection and the theta it accompanies
    never disagree about which answers count."""
    where = ["a_irt IS NOT NULL"]
    params = []
    if topic_id:
        where.append("topic_id=?")
        params.append(topic_id)
    if modes:
        where.append("mode IN (%s)" % ",".join("?" * len(modes)))
        params.extend(modes)
    # Exclude heavily-hinted attempts (two options eliminated + citation
    # shown) from ability estimation. A correct answer reached that way is
    # only weakly evidence of unaided knowledge -- treating it identically
    # to an unhinted correct would inflate theta. This mirrors the same
    # discount effective_credit() already applies inside BKT, extended to
    # IRT so all three estimators agree on what heavy scaffolding is worth.
    where.append("(hint_level IS NULL OR hint_level < ?)")
    params.append(HEAVY_HINT_THRESHOLD)
    params.append(limit)
    # timestamp is selected for the ladder gate below, which drops a
    # candidate's pre-calibration answers by time.
    rows = _safe_query(conn,
        f"""SELECT question_id, a_irt, b_irt, correct, timestamp FROM attempts
             WHERE {' AND '.join(where)} ORDER BY id DESC LIMIT ?""", params)
    # THE LADDER GATE: template items and uncalibrated candidates are
    # practice, not measurement. They do not move theta.
    rows = model_feed_filter(conn, rows)
    resp = [(r["a_irt"], r["b_irt"], r["correct"]) for r in rows]
    if not resp:
        # With no evidence the honest answer IS the prior, not zero.
        # Returning 0.0 here silently contradicted the anchored prior below
        # and made a brand-new learner look like a theta=0 population
        # average that this exam's candidates do not actually centre on.
        if return_posterior:
            return POPULATION_PRIOR_MU, POPULATION_PRIOR_SD, 0, _prior()
        return POPULATION_PRIOR_MU, POPULATION_PRIOR_SD, 0
    th, se, post = eap_theta(resp)
    # avg_a must be computed from SANITISED discriminations. eap_theta
    # already rejects non-finite item parameters internally, but this
    # average was still taken over the raw rows -- so a single inf a_irt
    # produced se=nan here even though the posterior itself was clean.
    # A NaN standard error is worse than a wrong one: it renders as a
    # number and silently invalidates every downstream confidence claim.
    good_a = [r[0] for r in resp
              if r[0] is not None and math.isfinite(r[0]) and 0 < r[0] <= 20]
    avg_a = (sum(good_a) / len(good_a)) if good_a else 1.0
    se_total = math.sqrt(max(0.0, se ** 2 + calibration_inflation(len(resp), avg_a)))
    if not math.isfinite(se_total):
        se_total = POPULATION_PRIOR_SD
    if not math.isfinite(th):
        th = POPULATION_PRIOR_MU
    if return_posterior:
        return th, round(se_total, 4), len(resp), post
    return th, round(se_total, 4), len(resp)


HIER_MIN_N = 5          # responses a topic needs before it informs tau^2
HIER_TAU2_FLOOR = 0.09  # (0.3 logits)^2: topics on this exam genuinely differ

def hierarchical_topic_ability(conn):
    """Per-topic ability with partial pooling toward the global estimate.

    A topic with three responses should not get its own wild estimate; it
    should be shrunk toward what we know about the learner overall. This is
    the standard empirical-Bayes fix for small per-group samples, and it is
    what makes per-topic numbers safe to display at all.

    The prior variance is the BETWEEN-TOPIC spread tau^2 (Efron & Morris
    1975; Gelman et al.), estimated by method of moments over topics with
    at least HIER_MIN_N responses: var(topic thetas) minus the mean of
    their squared SEs, floored at HIER_TAU2_FLOOR. The shrinkage weight is
    therefore tau^2 / (tau^2 + se_topic^2). Using the SE of the global mean
    as the prior variance -- the previous version -- collapsed every topic
    onto the global estimate, harder the more the learner practised, which
    is the opposite of what pooling is for. The pooling target for each
    topic is the mean of the OTHER topics' estimates, so a topic's own
    responses are not counted twice."""
    g_theta, g_se, g_n = ability_with_se(conn)
    per = {tid: ability_with_se(conn, tid) for tid in TOPICS}
    informative = [(t, se) for (t, se, n) in per.values() if n >= HIER_MIN_N]
    tau2 = HIER_TAU2_FLOOR
    if len(informative) >= 3:
        k = len(informative)
        mean_t = sum(t for t, _ in informative) / k
        var_t = sum((t - mean_t) ** 2 for t, _ in informative) / (k - 1)
        mean_se2 = sum(se ** 2 for _, se in informative) / k
        tau2 = max(HIER_TAU2_FLOOR, var_t - mean_se2)
    w_global = 1.0 / tau2
    out = {}
    for tid in TOPICS:
        t_theta, t_se, n = per[tid]
        if n == 0:
            out[tid] = {"theta": g_theta, "se": max(g_se, 1.0), "n": 0, "shrunk": 1.0}
            continue
        # leave-one-topic-out pooling target (falls back to the global
        # estimate when this is the only informative topic)
        others = [(t, se) for (t, se, m), k_ in zip(per.values(), per.keys())
                  if k_ != tid and m >= HIER_MIN_N]
        if others:
            wsum = sum(1.0 / max(se ** 2, 1e-6) for _, se in others)
            target = sum(t / max(se ** 2, 1e-6) for t, se in others) / wsum
        else:
            target = g_theta
        w_topic = 1.0 / max(t_se ** 2, 1e-6)
        blended = (t_theta * w_topic + target * w_global) / (w_topic + w_global)
        se_blend = math.sqrt(1.0 / (w_topic + w_global))
        out[tid] = {"theta": round(blended, 3), "se": round(se_blend, 3), "n": n,
                    "shrunk": round(w_global / (w_topic + w_global), 3)}
    return out


# ---- exposure control + content balancing -------------------------------

def exposure_counts(conn, limit=4000):
    rows = conn.execute("""SELECT question_id, COUNT(*) c FROM attempts
                            GROUP BY question_id LIMIT ?""", (limit,)).fetchall()
    return {r["question_id"]: r["c"] for r in rows}


def theta_posterior_now(conn, limit=600, modes=None):
    """The full EAP posterior over theta (not just its mean/SD), used only
    for KL/posterior-weighted item selection in the first few items of a
    session, where the point estimate is least trustworthy.

    Delegates to ability_with_se so the posterior is fitted to the same
    rows as the point theta the session carries: same regime (`modes`),
    same heavy-hint exclusion, same ladder gate. A posterior pooled over
    calm and timed answers can sit a full logit away from the regime-
    restricted theta the p-filter is using."""
    return ability_with_se(conn, limit=limit, modes=modes, return_posterior=True)[3]


def posterior_weighted_info(posterior, a, b):
    """Expected Fisher information under the full posterior rather than at
    a single point estimate -- the practical form of the KL/global-
    information family (Chang & Ying 1996; the ALICAT study found a
    posterior-weighted criterion beat plain Fisher information specifically
    while theta is still uncertain). Point-Fisher information can badly
    misjudge which item is informative when the true ability could
    plausibly be anywhere across a wide posterior; integrating over that
    posterior is the direct fix."""
    return sum(w * fisher_info_3pl(t, a, b) for t, w in zip(THETA_GRID, posterior))


EARLY_ITEM_COUNT = 5   # use posterior-weighted info for roughly this many items

KT_TOPIC_WEIGHT = 0.5   # 0 = ignore topic-level Thompson sampling, 1 = fully dominant

def thompson_topic_scores(conn):
    """Contextual-bandit-style topic prioritization (Lan & Baraniuk 2016;
    De Kerpel, Thuy & Benoit 2025/26 -- contextual Thompson sampling for
    learner skill-gain). Each topic's evidence is treated as a Beta
    posterior over 'is this topic weak', where a FAILURE is a success for
    the purpose of prioritization (we want to draw more from topics that
    keep going wrong). Sampling from the posterior -- rather than just
    ranking by observed failure rate -- naturally balances exploring
    under-seen topics (wide, uncertain Beta) against exploiting topics
    already known to be weak (narrow, high-mean Beta)."""
    scores = {}
    for tid in TOPICS:
        rows = measurement_rows(conn, "topic_id=?", (tid,), columns="correct", order=None)
        succ = sum(1 for r in rows if r["correct"])
        fail = len(rows) - succ
        alpha = 1 + fail    # "reward" = weakness
        beta_ = 1 + succ
        scores[tid] = random.betavariate(alpha, beta_)
    return scores


# ---------------------------------------------------------------------------
# MEASUREMENT-OPTIMAL vs LEARNING-OPTIMAL
# ---------------------------------------------------------------------------
# Max-information selection puts every item at p(correct) ~ 0.5. That is
# the right objective for MEASURING ability -- a diagnostic wants to
# resolve theta as fast as possible -- and the wrong one for LEARNING.
# Wilson, Shenhav, Straccia & Cohen (2019, Nature Communications) show the
# error rate that maximises learning is ~15.9%; Bjork's "desirable
# difficulty" work puts the productive band at roughly 70-85% success. At
# 50% success a learner is demoralised and half their answers are guesses
# that teach nothing. The app conflated the two objectives and served
# max-info everywhere, including in a mode called "Adaptive Drill" whose
# purpose is learning.

LEARNING_TARGET_P = 0.78      # the desirable-difficulty target
LEARNING_BAND = 0.14          # tolerance either side before the score decays

def learning_utility(theta, a, b, c=GUESS_C, target=None):
    """How well an item sits in the learning zone for this theta.

    Peaks at p(correct) = target (default LEARNING_TARGET_P; the session
    passes learning_target_p() per spec 7.3) and falls away either side.
    An item at p = 0.5 scores far lower than under max-info, which is the
    point: it is not what a person trying to LEARN should be served."""
    p = irt_p3(theta, a, b, c)
    t = target if target is not None else LEARNING_TARGET_P
    d = abs(p - t)
    if d <= LEARNING_BAND:
        return 1.0 - 0.3 * (d / LEARNING_BAND)
    # Strictly monotone outside the band. The earlier max(0.05, ...) floor
    # meant that at a high target (0.95 after two misses) every item more
    # than ~0.3 below target scored an identical 0.05, so content priority
    # and DINA information decided among them and the streak-breaker had no
    # effect on what was served -- measured as a NEGATIVE change in
    # predicted success after two consecutive misses. Items below target
    # decay more slowly than items above it: an easy item is a mild waste,
    # a hard one is the quitting inflection.
    width = 0.30 if p < t else 0.12
    return 1e-4 + 0.7 * math.exp(-((d - LEARNING_BAND) / width) ** 2)

def select_next_item(conn, theta, seen_ids, served_groups, exposure=None,
                     randomesque_k=6, blueprint=None, target_length=None,
                     posterior=None, topic_scores=None, cluster_ids=None,
                     served_topics=None, objective="measure", target_p=None,
                     rng=random):
    """Content-balanced (MPI), exposure-controlled, uncertainty-aware item
    selection.

    `rng` is the generator for the randomesque draw; the shadow trial
    passes a seeded one so two replays differ only by policy.

    Six departures from naive max-info, each tied to a specific finding
    from the adaptive-testing literature:
      * Maximum Priority Index (Cheng & Chang 2009) content balancing, at
        TOPIC granularity when served_topics is supplied (via
        topic_blueprint_priority, matched to PSI's actual per-content-area
        weights -- Contracts ~19% of the national portion, Property
        Management ~3%, etc.), falling back to the coarser National/NJ
        group-level priority otherwise. The group-level version alone kept
        the right 73/27 overall ratio while still over-serving small content
        areas and under-serving large ones relative to the real exam.
      * posterior-weighted ("KL-family") information for the first few
        items of a session, when the point theta estimate is least
        trustworthy, per Chang & Ying (1996) and the ALICAT (2020) finding.
      * exposure penalty: items already seen many times are down-weighted
        so the bank rotates instead of recycling.
      * randomesque top-k: pick at random among the best few candidates
        rather than always the single best, the standard cheap exposure
        control.
      * cluster boost: items belonging to a semantic failure cluster the
        user is currently concentrated in get a modest lift, so the
        Failure Point Explorer's clustering has an actual effect on what
        gets served next instead of being a purely descriptive display.
    """
    blueprint = blueprint or BLUEPRINT
    exposure = exposure if exposure is not None else exposure_counts(conn)
    topic_priority = (topic_blueprint_priority(target_length, served_topics)
                      if served_topics is not None else None)

    if target_length:
        # MPI: priority is proportional to REMAINING NEED for each group,
        # continuous rather than a hard single-group focus.
        need = {}
        for grp, share in blueprint.items():
            target_n = share * target_length
            need[grp] = max(0.0, target_n - served_groups.get(grp, 0))
        total_need = sum(need.values())
        if total_need > 0:
            priority = {g: (v / total_need) for g, v in need.items()}
        else:
            priority = {g: 1.0 for g in blueprint}
    else:
        # No known target length (open-ended session): fall back to
        # deficit-from-current-share, still continuous rather than a hard cut.
        total_served = sum(served_groups.values()) or 0
        priority = {}
        for grp, target in blueprint.items():
            have = served_groups.get(grp, 0)
            share = (have / total_served) if total_served else 0.0
            priority[grp] = max(0.05, target - share + target)  # keep positive, target-weighted

    pool = [q for q in QUIZ_LIST if q["id"] not in seen_ids]
    # Promoted candidates join the live pool. Without this the whole
    # generate -> verify -> approve pipeline ended at "approved" and the
    # item was never actually served -- a content factory whose output
    # nobody sees. They are subject to the same seen_ids exclusion as the
    # bank (a candidate served once in this session is not served again),
    # and they are merged BEFORE the empty-pool check so an exhausted bank
    # still serves them.
    try:
        _promoted = promoted_candidates(conn)
    except (sqlite3.Error, ValueError, TypeError, KeyError) as e:
        _audit(conn, "promoted_candidates_error", f"{type(e).__name__}: {e}")
        _promoted = []
    if _promoted:
        known = {q["id"] for q in pool} | set(seen_ids)
        pool = pool + [q for q in _promoted if q["id"] not in known]
    if not pool:
        return None

    use_posterior = posterior is not None and len(seen_ids) < EARLY_ITEM_COUNT

    # CD-CAT diagnostic boost: for topics with a genuine multi-skill Q-matrix
    # (see DINA above), items that would most narrow down WHICH specific
    # skills are unmastered get a lift, closing the loop between the
    # per-skill diagnosis and what actually gets served next -- otherwise
    # DINA only ever informs a report, the same gap the semantic-cluster
    # boost was built to close for the Failure Explorer. The class posterior
    # is computed ONCE per topic here and reused across every candidate
    # item in that topic, not recomputed per item.
    _unreliable_now = unreliable_item_ids(conn)
    _calib_prof = topic_calibration_profile(conn)
    # COMPETENCE GATE. Items withheld by an unresolved distinguishability
    # finding are removed from the pool entirely rather than merely
    # down-weighted. A hard identifiability failure cannot be drilled away,
    # and a confusable item served to a learner who is not yet strong on the
    # topic produces guessing noise that then feeds back into the very
    # posterior the audit was trying to validate.
    _unrel_w = active_threshold(conn, "unreliable_selection_weight",
                                UNRELIABLE_SELECTION_WEIGHT)
    _boost_cap = active_threshold(conn, "calibration_max_boost", CALIBRATION_MAX_BOOST)
    _gated = gated_item_ids(conn)
    # A repair must change BEHAVIOUR, not just be recorded. Items marked
    # merged or retired leave the pool entirely.
    try:
        _gated = set(_gated) | retired_item_ids(conn)
    except Exception:
        pass
    dina_raw_by_topic = {}
    pool_topics_with_skills = {q["topic"] for q in pool if len(topic_skill_ids(q["topic"])) >= 2}
    for tid in pool_topics_with_skills:
        dina_raw_by_topic[tid] = _dina_class_posterior(conn, tid)

    # Effective difficulties, computed once per candidate rather than per
    # scoring call. Uses the learner's own response history to shrink each
    # authored b toward the observed difficulty (see empirical_item_
    # difficulty), so selection targets what is actually hard for THIS
    # learner rather than what was estimated to be hard in the abstract.
    if _gated:
        remaining = [q for q in pool if q["id"] not in _gated]
        # Never gate the pool down to nothing: if every candidate is
        # withheld, serving a flagged item beats serving no item at all.
        if remaining:
            pool = remaining

    # BATCHED DIFFICULTY. empirical_item_difficulty() runs one query per
    # item; calling it across a 296-item pool is a 296-query N+1 that
    # dominated the first selection of a session (measured 3.8 s cold).
    # One grouped query fetches every item's response counts at once and the
    # per-item blend is done in Python -- identical arithmetic, one round
    # trip. Warm calls were already fast; this is about the first one, which
    # is the one the learner actually waits for.
    _resp = {}
    try:
        for r in _safe_query(conn, """SELECT question_id,
                                             COUNT(*) n, SUM(correct) c
                                      FROM attempts
                                      WHERE (hint_level IS NULL OR hint_level < ?)
                                        AND (mode IS NULL OR mode != 'pretest')
                                      GROUP BY question_id""",
                             (HEAVY_HINT_THRESHOLD,)):
            _resp[r["question_id"]] = (r["c"] or 0, r["n"] or 0)
    except Exception:
        _resp = {}

    def _fast_b(qid, authored):
        authored, governed = governed_difficulty_prior(conn, qid, authored,
                                                       return_source=True)
        # A PROMOTED prior is already the blend of authored and observed
        # difficulty (propose_policies computes exactly this shrinkage), and
        # it is the number the sealed gate judged. Blending it a second
        # time against the same attempts served a difficulty the gate never
        # scored and let items drift twice the sanctioned shift.
        if governed:
            return authored
        c_n = _resp.get(qid)
        if not c_n or c_n[1] == 0:
            return authored
        correct, n = c_n
        p = (correct + 1.0) / (n + 2.0)
        implied = theta - math.log(p / (1.0 - p))
        w = n / (n + ITEM_DIFFICULTY_PRIOR_WEIGHT)
        blended = (1.0 - w) * authored + w * implied
        return max(authored - ITEM_DIFFICULTY_MAX_SHIFT,
                   min(authored + ITEM_DIFFICULTY_MAX_SHIFT, blended))

    eff_b = {}
    for q in pool:
        # Start from the precomputed per-item prior where the offline
        # pipeline authored one, falling back to the item's own b_irt. This
        # matters most at low n, where the prior still dominates the
        # shrinkage below.
        eff_b[q["id"]] = _fast_b(q["id"], q.get("b_irt", 0.0))

    # Spec 7.3: in LEARN sessions the success target is a CEILING the
    # randomesque draw cannot breach, not a soft down-weight. Hard-filter
    # the pool to items with p >= target - 0.06 using the learner-specific
    # difficulty; fall back to the unfiltered pool only if that empties it.
    if objective == "learn" and target_p is not None:
        # POOL FLOOR (spec 7.3): a ceiling with no floor is overlearning --
        # at a high phase-A target and a low theta the filter can leave a
        # handful of easy items and serve them until the exposure penalty
        # gives out. Widen the filter by 0.04 per step until at least
        # `pool_floor` candidates survive or the unfiltered pool is reached.
        _pool_floor = int(active_threshold(conn, "pool_floor", 12))
        _p_of = {q["id"]: irt_p3(theta, q.get("a_irt", 1.0),
                                 eff_b.get(q["id"], q.get("b_irt", 0.0)),
                                 q.get("c_irt", GUESS_C)) for q in pool}
        _cut = target_p - 0.06
        _kept = [q for q in pool if _p_of[q["id"]] >= _cut]
        while len(_kept) < _pool_floor and _cut > 0.0:
            _cut -= 0.04
            _kept = [q for q in pool if _p_of[q["id"]] >= _cut]
        # PER-GROUP MINIMUM. The ceiling is applied to the whole bank at
        # once, and for a learner whose state-law items are all below the
        # cut it left a pool with no NJ item in it at all -- the blueprint
        # then had nothing to balance. Each group keeps at least its
        # blueprint share of the floor, filled with its easiest remaining
        # items, so content balancing always has something to choose from.
        _kept_ids = {q["id"] for q in _kept}

        def _add_easiest(cands, k):
            _extra = sorted((q for q in cands if q["id"] not in _kept_ids),
                            key=lambda q: _p_of[q["id"]], reverse=True)[:k]
            _kept.extend(_extra)
            _kept_ids.update(q["id"] for q in _extra)

        for _grp, _share in blueprint.items():
            _min_n = math.ceil(_share * _pool_floor)
            _have = sum(1 for q in _kept if TOPICS[q["topic"]]["group"] == _grp)
            if _have < _min_n:
                _add_easiest([q for q in pool if TOPICS[q["topic"]]["group"] == _grp],
                             _min_n - _have)
        # The same at topic granularity when the blueprint is per topic: a
        # content area with remaining need keeps its single easiest item in
        # the pool, otherwise the few areas that happen to be easy for this
        # learner absorb the whole session while Contracts never appears.
        if topic_priority is not None:
            _topics_kept = {q["topic"] for q in _kept}
            for _tid, _pri in topic_priority.items():
                if _pri > 0 and _tid not in _topics_kept:
                    _add_easiest([q for q in pool if q["topic"] == _tid], 1)
        if _kept:
            pool = _kept

    _priority_max = max((topic_priority or priority).values()) or 1.0

    def score(q):
        a = q.get("a_irt", 1.0)
        b = eff_b.get(q["id"], q.get("b_irt", 0.0))
        if objective == "learn":
            info = learning_utility(theta, a, b, q.get("c_irt", GUESS_C), target=target_p)
        else:
            info = posterior_weighted_info(posterior, a, b) if use_posterior \
                else fisher_info_3pl(theta, a, b)
        if topic_priority is not None:
            content_priority = topic_priority.get(q["topic"], 1.0)
        else:
            grp = TOPICS[q["topic"]]["group"]
            content_priority = priority.get(grp, 1.0)
        # MPI priority is SOFT (Cheng & Chang 2009): a topic whose quota is
        # met is de-prioritised, never zeroed. A zero here multiplied every
        # other factor -- exposure, DINA, Thompson -- into 0 and left the
        # sort to fall back on bank order. The floor is relative to the
        # most-needed topic because priorities are normalised to sum to 1
        # across 18 topics (a needed topic sits at ~0.05-0.15), so an
        # absolute floor would make "quota met" indistinguishable from
        # "needed".
        content_priority = max(0.05 * _priority_max, content_priority)
        seen = exposure.get(q["id"], 0)
        s = info * content_priority / (1.0 + 0.35 * seen)
        if topic_scores:
            tb = topic_scores.get(q["topic"], 0.5)
            s *= (1.0 - KT_TOPIC_WEIGHT) + KT_TOPIC_WEIGHT * (0.4 + 1.2 * tb)
        if cluster_ids and q["id"] in cluster_ids:
            s *= 1.6  # modest lift toward the concept currently confused
        cb = _calib_prof.get(q["topic"])
        if cb is not None:
            s *= calibration_selection_boost(cb["bias"], cap=_boost_cap,
                                             reliability_over=cb["reliability_over"])
        # Locus D: stop spending attention on items whose answers are
        # partly noise (see unreliable_item_ids).
        if q["id"] in _unreliable_now:
            s *= _unrel_w
        raw = dina_raw_by_topic.get(q["topic"])
        if raw is not None:
            dina_info = dina_item_information(conn, q["topic"], q["id"], raw=raw)
            # Bernoulli-KL magnitudes are typically small fractions; scale
            # modestly rather than let this dominate the existing IRT/
            # content/exposure factors above -- it is a refinement to
            # selection within an already-reasonable candidate set, not the
            # primary selection signal.
            s *= (1.0 + min(1.0, dina_info))
        return s

    # Ties (exact score equality does happen: same topic, same authored
    # parameters, same exposure) are broken by point information rather
    # than by position in QUIZ_LIST, so the top-k is a property of the
    # items and not of the order the bank was typed in.
    def _rank_key(q):
        return (score(q), fisher_info_3pl(theta, q.get("a_irt", 1.0),
                                          eff_b.get(q["id"], q.get("b_irt", 0.0))))
    ranked = sorted(pool, key=_rank_key, reverse=True)
    top = ranked[:max(1, randomesque_k)]
    return rng.choice(top)


_PASS_CUTOFF_CACHE = {}

def theta_at_pass_cutoff(target_pct=70.0):
    """The ability level at which expected score on the FULL item bank
    equals the pass threshold, found once by bisection and cached. Used as
    the reference point for a classification-confidence stopping rule: for a
    licensing exam what the learner actually needs to know is pass/fail
    readiness, not a maximally precise theta -- CAT can stop as soon as the
    confidence interval no longer straddles this cutoff, even if the plain
    SE threshold hasn't been reached yet."""
    key = round(target_pct, 1)
    if key in _PASS_CUTOFF_CACHE:
        return _PASS_CUTOFF_CACHE[key]
    items = QUIZ_LIST

    def expected_pct(theta):
        ps = [irt_p3(theta, q.get("a_irt", 1.0), q.get("b_irt", 0.0)) for q in items]
        return 100.0 * sum(ps) / len(ps)

    lo, hi = -4.0, 4.0
    for _ in range(40):
        mid = (lo + hi) / 2
        if expected_pct(mid) < target_pct:
            lo = mid
        else:
            hi = mid
    theta_cut = (lo + hi) / 2
    _PASS_CUTOFF_CACHE[key] = theta_cut
    return theta_cut


def classification_confident(theta, se, target_pct=70.0, z=1.645):
    """Is the pass/fail call already settled, independent of how precise
    theta itself is? Returns (confident, verdict) where verdict is
    'pass'/'fail' only when confident. z=1.645 is a one-sided ~90% interval,
    appropriate for a stop/continue decision rather than a published result."""
    cut = theta_at_pass_cutoff(target_pct)
    lo, hi = theta - z * se, theta + z * se
    if lo > cut:
        return True, "pass"
    if hi < cut:
        return True, "fail"
    return False, None


def stopping_se(prior_se, session_info):
    """The SE the stop rule is allowed to act on.

    A stopping rule is defined on the information collected by the test
    being administered (Kingsbury & Weiss 1983; Eggen & Straetmans 2000).
    The cumulative posterior SE from the learner's whole history is already
    below threshold before a returning learner answers a single item, so
    using it directly ended every session at min_items. Here the history
    enters only as a prior whose information is capped at half of what the
    target precision needs; the other half must come from this session's
    own Fisher information, Σ I(θ̂, a_j, b_j) over the items answered."""
    info_needed = 1.0 / (SE_TARGET ** 2)
    prior_info = 1.0 / max(prior_se, 1e-6) ** 2 if prior_se else 0.0
    prior_info = min(prior_info, 0.5 * info_needed)
    return 1.0 / math.sqrt(max(prior_info + max(session_info, 0.0), 1e-9))


def cat_should_stop(se, n_items, max_items, min_items=8, theta=None, target_pct=70.0,
                    session_info=None):
    """Stop when the estimate is precise enough OR the pass/fail
    classification is already confident, not merely when a fixed count is
    reached. Returns (stop, reason).

    `session_info` is the Fisher information accumulated over THIS session's
    items. When given, both early-stop tests use stopping_se() and require
    the session to have contributed at least half of the information the
    target precision needs, so a settled historical estimate cannot end a
    session on its own. When omitted, `se` is taken at face value (the
    behaviour offline callers with no session context expect)."""
    if n_items >= max_items:
        return True, "reached the item limit"
    if n_items < min_items:
        return False, None
    if session_info is not None:
        if session_info < 0.5 / (SE_TARGET ** 2):
            return False, None
        se = stopping_se(se, session_info)
    if theta is not None:
        confident, verdict = classification_confident(theta, se, target_pct)
        if confident:
            return True, (f"classification confident ({verdict}) — the confidence interval "
                          f"no longer crosses the {target_pct:.0f}% pass cutoff")
    if se <= SE_TARGET:
        return True, f"ability estimated precisely enough (SE {se:.2f})"
    return False, None


# ---- exam-date-aware review scheduling ----------------------------------

def schedule_for_exam(conn, half_life, days_to_exam, default_target=TARGET_RECALL):
    """Choose the next review gap to maximize recall ON EXAM DAY.

    The stock scheduler targets a fixed 85% recall at review time, which is
    right when the horizon is open-ended but wrong near a deadline: with nine
    days left, spacing a card 30 days out guarantees it is cold on exam day.
    When the exam is close, intervals are capped so every card gets at least
    one more retrieval before it counts."""
    if days_to_exam is None or days_to_exam <= 0:
        gap = half_life * math.log(1 / default_target, 2)
        return max(1, round(gap)), "standard spacing"
    natural = half_life * math.log(1 / default_target, 2)
    if natural <= days_to_exam * 0.6:
        return max(1, round(natural)), "standard spacing"
    # compress so the card is reviewed again before the exam
    capped = max(1, math.floor(days_to_exam * 0.6))
    return capped, f"compressed to fit {days_to_exam} days before the exam"


def days_to_exam(conn):
    s = get_setting(conn, "target_exam_date")
    if not s:
        return None
    try:
        return (date.fromisoformat(s) - date.today()).days
    except ValueError:
        return None
# ===========================================================================
# V2  --  THE LEARNING LOOP
# ===========================================================================
# V1 has every component a closed learning loop needs, and no loop. The
# evidence graph, DINA, beliefs, missions, the focus guide, the error log --
# each is reachable from its own tab, each computes its own view of the
# learner, and nothing composes them into a cycle with a defined order,
# typed hand-offs, or a record of what one turn did.
#
# V2 makes the loop a first-class object:
#
#     OBSERVE    every signal from recent answers, evidence-weighted
#        |
#     DIAGNOSE   per-skill state + root causes, ranked by consequence
#        |
#     PRESCRIBE  ordered interventions, each with its reason
#        |
#     INSTRUCT   the study packet, BUILT FROM THE FAILED ITEMS
#        |
#     VERIFY     what must be demonstrated, and when
#        |
#     UPDATE     write-back to beliefs, missions, retention  -->  OBSERVE
#
# Each stage is a function with one input type and one output type. Each
# turn of the loop is recorded, with what it saw and what it prescribed, so
# the loop can be audited and its prescriptions can be judged against what
# happened next. That record is what turns "an app with many features" into
# a system that can be shown to learn from its own decisions.

LOOP_STAGES = ("observe", "diagnose", "prescribe", "instruct", "verify", "update")

def init_loop_schema(conn):
    conn.executescript("""
    CREATE TABLE IF NOT EXISTS loop_cycles (
        cycle_id     INTEGER PRIMARY KEY AUTOINCREMENT,
        started_at   TEXT NOT NULL,
        n_evidence   INTEGER,
        top_skill    TEXT,
        top_stance   TEXT,
        root_cause   TEXT,
        prescription TEXT,
        packet_words INTEGER,
        outcome      TEXT,
        closed_at    TEXT
    );
    """)
    # top_mastery: the figure the cycle judged its top skill at, so a later
    # cycle can be judged against it. cycle_json: the whole rendered turn,
    # so the loop page can show the last prescription and packet on
    # re-entry instead of "no cycle has run yet".
    cols = {r[1] for r in conn.execute("PRAGMA table_info(loop_cycles)")}
    for col, coltype in (("top_mastery", "REAL"), ("cycle_json", "TEXT")):
        if col not in cols:
            try:
                conn.execute(f"ALTER TABLE loop_cycles ADD COLUMN {col} {coltype}")
            except sqlite3.OperationalError:
                pass
    conn.commit()

# ---------------------------------------------------------------------------
# STAGE 1: OBSERVE
# ---------------------------------------------------------------------------
def loop_observe(conn, window=120):
    """Everything the last `window` answers say, with each answer weighted
    by how much it should be believed.

    Output: Evidence = list of dicts, one per answer, carrying the skill it
    tests, the option chosen, the weight, and the derived flags. This is
    the single input to diagnosis; nothing downstream reads attempts
    directly, so the weighting is applied exactly once and consistently."""
    # Measurement rows only: a pretest guess and a heavily-hinted answer
    # are not evidence of what the learner holds (see MEASUREMENT_ROW_SQL).
    rows = measurement_rows(conn, "question_id NOT LIKE 'gen-%'",
                            columns="id, question_id, topic_id, correct, chosen, "
                                    "confidence, time_taken, timestamp, mode",
                            order="id DESC", limit=window)
    times = [r["time_taken"] for r in rows if r["time_taken"]]
    rt_model = personal_rt_model(times)
    now = datetime.now()
    out = []
    for r in rows:
        q = QUIZ_BANK.get(r["question_id"])
        if not q:
            continue
        try:
            age = (now - datetime.fromisoformat(r["timestamp"])).total_seconds() / 86400.0
        except Exception:
            age = None
        w = observation_weight(bool(r["correct"]), r["time_taken"], r["confidence"],
                               age, rt_model=rt_model)
        z = rt_zscore(r["time_taken"], rt_model) if rt_model else 0.0
        out.append({
            "attempt_id": r["id"], "qid": q["id"], "topic": q["topic"],
            "skills": Q_MATRIX.get(q["id"], []),
            "correct": bool(r["correct"]), "chosen": r["chosen"],
            "confidence": r["confidence"], "weight": w, "rt_z": z,
            "age_days": age, "timed": pressure_class(r["mode"]) == "pressure",
            "pressure_class": pressure_class(r["mode"]),
            "flags": [f for f, ok in (
                ("guess", not r["correct"] and z < -1.5),
                ("confident_wrong", not r["correct"] and (r["confidence"] or 0) >= 3),
                ("lucky", r["correct"] and (r["confidence"] or 0) <= 1),
                ("effortful", r["correct"] and z > 1.5),
            ) if ok],
        })
    return {"evidence": out, "n": len(out), "rt_model": rt_model,
            "observed_at": now.isoformat()}

def certificate_for_skill(conn, skill_id):
    """The worst distinguishability certificate among this skill's items.

    A HARD certificate means the bank cannot tell this skill apart from
    another with the items it has -- drilling it produces confidence
    without validity. The loop must know that before it prescribes."""
    worst = None
    order = {"hard": 3, "quasi-hard": 2, "soft": 1}
    for q in QUIZ_LIST:
        if skill_id not in Q_MATRIX.get(q["id"], []):
            continue
        try:
            ok, why, cert = competence_gate(conn, q["id"])
        except Exception:
            continue
        if cert and order.get(str(cert).lower().replace("_", "-"), 0) > order.get(str(worst).lower().replace("_", "-"), 0):
            worst = cert
    return worst

# ---------------------------------------------------------------------------
# EVIDENCE STATEMENTS  --  every claim says what it rests on
# ---------------------------------------------------------------------------
# A mastery percentage with no evidence statement reads as a measurement.
# "3%" and "3% from one answer on a skill the bank cannot separate from its
# lookalike" are different claims, and the loop was making the first while
# only entitled to the second. Every finding now carries a confidence level
# and its reason, and CONTENT MATURITY is a hard input: a Gap skill is not
# "3% mastered", it is "cannot be assessed with the material that exists",
# and it is routed to authoring rather than to the learner.

def evidence_statement(n_evidence, evidence_weight, n_items, maturity_key,
                       confident_wrong=0, has_transfer=False):
    """(level, statement). Level in: high, moderate, low, cannot_assess."""
    if maturity_key in ("gap", "draft"):
        return ("cannot_assess",
                "The bank does not hold enough verified material on this skill "
                "to measure it. A number here would be a guess dressed as a "
                "diagnosis. Routed to content authoring, not to you.")
    if n_items < 2:
        return ("low", "Only one item tests this skill, so nothing can "
                       "distinguish knowing it from remembering that question.")
    if n_evidence < 2:
        return ("low", "One answer on record. Everything below is provisional "
                       "until there are more.")
    if evidence_weight >= 4.0 and (has_transfer or n_items >= 3):
        return ("high",
                f"{n_evidence} evidence-weighted answers across {n_items} items"
                + (f"; {confident_wrong} were confident and wrong" if confident_wrong else "")
                + ".")
    if evidence_weight >= 1.5:
        return ("moderate",
                f"{n_evidence} answers on {n_items} items \u2014 enough to see a "
                "pattern, not enough to be sure of it"
                + (f"; {confident_wrong} confident-wrong" if confident_wrong else "")
                + ".")
    return ("low", f"{n_evidence} answers, but the weighted evidence is thin "
                   "\u2014 several were guesses or very old.")

# ---------------------------------------------------------------------------
# STAGE 2: DIAGNOSE
# ---------------------------------------------------------------------------
def loop_diagnose(conn, observed):
    """From evidence to a ranked statement of what is wrong and why.

    Output: Diagnosis = per-skill records with mastery, retention, belief
    state, stance, and the failed items that support the finding; plus the
    root causes the prerequisite graph identifies across skills. Ranked by
    consequence = weakness x exam weight x how much evidence there is."""
    ev = observed["evidence"]
    by_skill = {}
    for e in ev:
        for sid in e["skills"]:
            by_skill.setdefault(sid, []).append(e)

    findings = []
    for sid, es in by_skill.items():
        meta = SKILLS.get(sid) or {}
        tid = meta.get("topic")
        try:
            d = build_skill_dossier(conn, sid)
        except Exception:
            d = None
        if not d:
            continue
        try:
            ret = skill_retention_state(conn, sid)
        except Exception:
            ret = None
        mastery = d["mastery"] or 0.0
        decayed = decayed_skill_mastery(conn, sid, mastery)
        wsum = sum(e["weight"] for e in es)
        wrong = [e for e in es if not e["correct"]]
        failed_items = []
        for e in sorted(wrong, key=lambda x: -x["weight"])[:4]:
            q = QUIZ_BANK.get(e["qid"])
            opts = q.get("opts") or []
            ch = e["chosen"]
            failed_items.append({
                "qid": e["qid"], "stem": q["q"],
                "chosen": opts[ch] if ch is not None and ch < len(opts) else None,
                "chosen_idx": ch, "key": opts[q["a"]] if q["a"] < len(opts) else "",
                "flags": e["flags"], "weight": e["weight"],
            })
        try:
            bl = [b for b in active_beliefs(conn, 40) if b["skill_id"] == sid]
            belief = belief_view(conn, bl[0]["belief_id"]) if bl else None
        except Exception:
            belief = None
        try:
            bott = upstream_bottleneck(conn, sid)
        except Exception:
            bott = None
        consequence = ((1.0 - decayed) * _exam_weight(tid) *
                       min(1.0, wsum / 4.0))

        # ---- signals the engine already computes and the loop ignored ----
        # timed collapse: right untimed, wrong against the clock
        calm = [e for e in es if e.get("pressure_class") == "calm"]
        timed = [e for e in es if e["timed"]]
        pgap = None
        if len(calm) >= 3 and len(timed) >= 3:
            pgap = (sum(e["correct"] for e in calm) / len(calm)
                    - sum(e["correct"] for e in timed) / len(timed))
        # content maturity: is the material behind this skill even adequate?
        try:
            mat = content_maturity(conn, sid)
        except Exception:
            mat = None
        # certificate: can the bank even distinguish this skill?
        try:
            cert = certificate_for_skill(conn, sid)
        except Exception:
            cert = None

        n_items = len([q for q in QUIZ_LIST if sid in Q_MATRIX.get(q["id"], [])])
        ev_level, ev_text = evidence_statement(
            len(es), wsum, n_items, (mat or {}).get("key", "bronze"),
            confident_wrong=sum(1 for e in es if "confident_wrong" in e["flags"]))
        # MATURITY GOVERNS: an unassessable skill contributes no consequence
        # to the learner's ranking. It goes to the authoring queue instead.
        assessable = ev_level != "cannot_assess"
        if not assessable:
            consequence = 0.0

        findings.append({
            "evidence_level": ev_level, "evidence_text": ev_text,
            "assessable": assessable,
            "pressure_gap": pgap,
            "maturity": mat["key"] if mat else None,
            "maturity_missing": [m["asset"] for m in (mat or {}).get("missing", [])][:3],
            "certificate": cert,
            "skill": sid, "label": meta.get("label", sid), "topic": tid,
            "mastery": mastery, "decayed_mastery": decayed,
            "retention": ret, "stance": d["stance"], "headline": d["headline"],
            "n_evidence": len(es), "evidence_weight": round(wsum, 2),
            "n_wrong": len(wrong),
            "confident_wrong": sum(1 for e in es if "confident_wrong" in e["flags"]),
            "guesses": sum(1 for e in es if "guess" in e["flags"]),
            "failed_items": failed_items,
            "belief": belief, "rests_on": bott,
            "consequence": consequence,
        })
    findings.sort(key=lambda f: -f["consequence"])

    # Root causes across the whole picture.
    from collections import Counter
    roots = Counter()
    for f in findings:
        if f["rests_on"] and f["decayed_mastery"] < DOSSIER_STRONG:
            roots[f["rests_on"]["skill"]] += f["consequence"]
    root_list = [{"skill": s, "label": SKILLS.get(s, {}).get("label", s),
                  "weight": round(w, 3)} for s, w in roots.most_common(3)]

    unassessable = [f for f in findings if not f["assessable"]]
    return {"findings": [f for f in findings if f["assessable"]],
            "unassessable": unassessable,
            "root_causes": root_list,
            "n_skills": len(findings),
            "summary": {
                "weak": sum(1 for f in findings if f["decayed_mastery"] < DOSSIER_WEAK),
                "fading": sum(1 for f in findings if f["retention"]
                              and f["retention"]["state"] in ("fading", "due", "lost")),
                "misconceptions": sum(1 for f in findings if f["stance"] == "misconception"),
                "blocked": sum(1 for f in findings if f["stance"] == "blocked"),
                "pressure": sum(1 for f in findings
                                if f["pressure_gap"] is not None and f["pressure_gap"] > 0.25),
                "content_gap": sum(1 for f in findings if f["maturity"] == "gap"),
                "unmeasurable": sum(1 for f in findings
                                    if str(f["certificate"] or "").lower().startswith("hard")),
            },
            # memorization: familiar items right, variants wrong
            "generalization": (generalization_gap(conn)
                               if callable(globals().get("generalization_gap")) else None)}

# ---------------------------------------------------------------------------
# STAGE 3: PRESCRIBE
# ---------------------------------------------------------------------------
def loop_prescribe(conn, diagnosis, budget=5):
    """From diagnosis to an ORDERED list of interventions, each with the
    reason it was chosen and the one before it.

    The order is the intervention. Root causes go first because repairing
    a symptom while its prerequisite is broken is wasted effort; then
    misconceptions, because a held wrong rule is expensive; then fading
    skills, because retrieval is cheap and the window is closing; then
    the remainder by consequence."""
    rx = []
    used = set()

    # CONTENT REPAIR comes before everything. If the bank cannot distinguish
    # a skill (hard certificate), or has too little material to teach it
    # (Gap maturity), then no amount of drilling helps and the honest
    # prescription is "this is a content problem, not you" -- routed to
    # authoring or generation, not to the learner. This is the branch of
    # next_uncertainty_cut() the loop had been skipping.
    for f in diagnosis["findings"]:
        if len(rx) >= budget:
            break
        hard = str(f["certificate"] or "").lower().startswith("hard")
        if hard and f["skill"] not in used:
            rx.append({"kind": "content_repair", "skill": f["skill"], "label": f["label"],
                       "why": ("The bank cannot currently tell this skill apart from a "
                               "neighbour with the items it has. Drilling it raises "
                               "confidence without raising validity. Needs authoring.")})
            used.add(f["skill"])

    for rc in diagnosis["root_causes"]:
        if len(rx) >= budget:
            break
        if rc["skill"] in used:
            continue
        rx.append({"kind": "prerequisite_repair", "skill": rc["skill"],
                   "label": rc["label"],
                   "why": f"Several weak skills rest on this one. Fix it first or "
                          "the others will not hold."})
        used.add(rc["skill"])

    for f in diagnosis["findings"]:
        if len(rx) >= budget:
            break
        if f["skill"] in used:
            continue
        if f["stance"] == "misconception" or f["confident_wrong"] >= 2:
            # Two routes in: the dossier's stance, or the raw count. Say
            # which, so "0 confident wrong answers: a held wrong rule" can
            # never be printed.
            why = (f"{f['confident_wrong']} confident wrong answer(s): a held "
                   "wrong rule, not a gap."
                   if f["confident_wrong"] >= 2 else
                   f"{f['n_wrong']} miss(es) clustering on the same option: "
                   "consistent with a held wrong rule.")
            rx.append({"kind": "misconception_repair", "skill": f["skill"],
                       "label": f["label"], "why": why})
            used.add(f["skill"])

    # TIMED COLLAPSE is its own intervention: the content is in place, the
    # retrieval speed is not, and re-teaching the rule is the wrong fix.
    for f in diagnosis["findings"]:
        if len(rx) >= budget:
            break
        if f["skill"] in used:
            continue
        if f["pressure_gap"] is not None and f["pressure_gap"] > 0.25:
            rx.append({"kind": "speed", "skill": f["skill"], "label": f["label"],
                       "why": (f"Untimed accuracy is {f['pressure_gap']*100:.0f} points "
                               "above timed. You know this; you lose it against a "
                               "clock. Speeded recognition, not re-reading.")})
            used.add(f["skill"])

    for f in diagnosis["findings"]:
        if len(rx) >= budget:
            break
        if f["skill"] in used:
            continue
        if f["retention"] and f["retention"]["state"] in ("due", "lost"):
            rx.append({"kind": "retrieval", "skill": f["skill"], "label": f["label"],
                       "why": (f"Known once, now at {f['retention']['retrievability']*100:.0f}% "
                               "retrievability. Retrieval practice, not re-reading.")})
            used.add(f["skill"])

    for f in diagnosis["findings"]:
        if len(rx) >= budget:
            break
        if f["skill"] in used:
            continue
        if f["decayed_mastery"] < DOSSIER_STRONG:
            rx.append({"kind": "instruction", "skill": f["skill"], "label": f["label"],
                       "why": (f"{f['decayed_mastery']*100:.0f}% mastery on a topic worth "
                               f"~{_exam_weight(f['topic']):.0f} exam questions.")})
            used.add(f["skill"])

    # Where the app has MEASURED which intervention type actually lifts
    # this learner (select_intervention / intervention_lift), say so. A
    # prescription backed by the learner's own outcome data beats one
    # backed by a structural default, and the loop should prefer it.
    for r in rx:
        try:
            diag = {"skill": r["skill"], "kind": r["kind"]}
            best = select_intervention(conn, diag)
            # select_intervention names the chosen action under "type"; reading
            # any other key here silently skipped the measured branch entirely.
            if best and best.get("type"):
                lift, n = intervention_lift(conn, best["type"])
                if n >= 3:
                    r["measured"] = {"intervention": best["type"],
                                     "lift": round(lift, 3), "n": n}
                    r["why"] += (f" Your own history: {best['type']} has "
                                 f"lifted you {lift*100:+.0f} pts over {n} use(s).")
        except Exception:
            pass
    fmap = {f["skill"]: f for f in diagnosis["findings"]}
    for r in rx:
        f = fmap.get(r["skill"])
        if f:
            r["evidence_level"] = f["evidence_level"]
            r["evidence_text"] = f["evidence_text"]
        else:
            # A root cause comes from the prerequisite graph and need not
            # have any answers of its own in the window. Say so, rather
            # than dressing an inference up as a measurement.
            r["evidence_level"] = "low"
            r["evidence_text"] = ("Inferred from the prerequisite graph, not from "
                                  "your answers on this skill.")
    # What could NOT be assessed is a work order for content, reported as
    # such rather than silently dropped.
    authoring = [{"skill": u["skill"], "label": u["label"],
                  "maturity": u["maturity"], "why": u["evidence_text"]}
                 for u in diagnosis.get("unassessable", [])[:8]]
    return {"interventions": rx, "budget": budget, "authoring_queue": authoring}

# ---------------------------------------------------------------------------
# STAGE 4: INSTRUCT  --  the study packet, built from the failures
# ---------------------------------------------------------------------------
def loop_instruct(conn, diagnosis, prescription):
    """The on-the-fly study guide, generated FROM the failed items.

    Every prescribed skill gets a chapter whose spine is the learner's own
    misses: the item, the option they chose, why that option looked right
    and is wrong, the option that is right and why, then the rule stated,
    then the lookalikes, then an UNTREATED item on the same skill so the
    chapter ends in retrieval rather than reading. A chapter with no misses
    to build on falls back to the worked-case treatment.

    Output: Packet = ordered chapters, each with typed sections, plus the
    Markdown rendering."""
    fmap = {f["skill"]: f for f in diagnosis["findings"]}
    chapters = []
    L = ["# Study packet \u2014 built from what you got wrong", ""]
    L.append(f"*{datetime.now().strftime('%Y-%m-%d %H:%M')} \u00b7 "
             f"{len(prescription['interventions'])} intervention(s) prescribed from "
             f"{diagnosis['n_skills']} diagnosed skill(s).*")
    L.append("")

    for i, rx in enumerate(prescription["interventions"], 1):
        sid = rx["skill"]
        f = fmap.get(sid)
        chapter = {"skill": sid, "label": rx["label"], "kind": rx["kind"],
                   "why": rx["why"], "sections": []}
        L.append(f"## {i}. {rx['label']}")
        L.append("")
        L.append(f"**Why this, now:** {rx['why']}")
        L.append("")
        # Maturity label, so a thin chapter is never mistaken for a full one.
        if f and f.get("maturity"):
            mk = f["maturity"]
            mlabel = MATURITY_LEVELS.get(mk, (mk, ""))[0]
            L.append(f"<sub>Content maturity: **{mlabel}**"
                     + (f" \u2014 missing {', '.join(f['maturity_missing'])}"
                        if f.get("maturity_missing") else "")
                     + "</sub>")
            L.append("")
        if rx["kind"] == "content_repair":
            L.append("> **This chapter is about the bank, not about you.** The items "
                     "cannot separate this skill from its neighbour. What follows is "
                     "the best available material; the real fix is authoring.")
            L.append("")
            # Never generate from here. This runs on the UI thread inside
            # "Run one turn of the loop", and loading a local model is a
            # multi-minute freeze the learner did not ask for. The packet
            # names the authoring target; the Candidate bank's "Generate a
            # candidate" button is the consented, threaded way to act on it.
            target = {"kind": "hard", "skill": sid,
                      "topic": rx.get("topic") or SKILLS.get(sid, {}).get("topic"),
                      "certificate": "hard", "why": "loop content_repair"}
            chapter["generate_target"] = target
            chapter["action"] = {"label": "Generate a differentiating item",
                                 "view": "improvement", "section": "Candidate bank",
                                 "target": target}
            L.append("<sub>Action: generate a differentiating item for this skill "
                     "from Self-Improvement → Candidate bank (“Generate a "
                     "candidate”). Generation is never started from the loop "
                     "itself.</sub>")
            L.append("")

        # --- A. the failures themselves, each as a worked counterexample ---
        failed = (f or {}).get("failed_items") or []
        if failed:
            L.append("### What you got wrong, and why it looked right")
            L.append("")
            sec = []
            for fi in failed:
                q = QUIZ_BANK.get(fi["qid"])
                if not q:
                    continue
                L.append(f"> {fi['stem']}")
                L.append("")
                for o in _option_analysis(q):
                    mine = (fi["chosen_idx"] is not None
                            and o["letter"] == "ABCD"[fi["chosen_idx"]])
                    mark = "\u2713" if o["correct"] else "\u2717"
                    tag = "  **\u2190 you chose this**" if mine and not o["correct"] else ""
                    L.append(f"- {mark} **{o['letter']}.** {o['text']}{tag}")
                    if o["why"]:
                        L.append(f"    - {'Right because' if o['correct'] else 'Wrong because'}: {o['why']}")
                if fi["flags"]:
                    L.append(f"    - <sub>signals: {', '.join(fi['flags'])}</sub>")
                L.append("")
                sec.append(fi)
            chapter["sections"].append({"kind": "failures", "items": sec})

        # --- B. the rule and the lookalikes ---
        try:
            dense = dense_skill_content(conn, sid)
        except Exception:
            dense = {"blocks": []}
        # The cross-skill contrast table: the densest format the engine
        # produces, and the loop was not using it.
        try:
            tbl = comparison_table(conn, SKILLS.get(sid, {}).get("topic"))
        except Exception:
            tbl = None
        if tbl and len(tbl["concepts"]) >= 2:
            L.append("### Side by side")
            L.append("")
            L.append("| Concept | " + " | ".join(tbl["dimensions"][:3]) + " |")
            L.append("|---|" + "---|" * min(3, len(tbl["dimensions"])))
            for con in tbl["concepts"][:6]:
                cells = [con["dims"].get(dm, "")[:70].replace("|", "/")
                         for dm in tbl["dimensions"][:3]]
                L.append(f"| **{con['name'][:40]}** | " + " | ".join(cells) + " |")
            L.append("")
            chapter["sections"].append({"kind": "comparison", "concepts": len(tbl["concepts"])})
        for blk in dense["blocks"]:
            if blk["kind"] == "distinction" and blk["rows"]:
                L.append("### The distinction that decides it")
                L.append("")
                for d_ in blk["rows"]:
                    L.append(f"- **{d_['pair']}** \u2014 {d_['decider'] or ''}")
                L.append("")
                chapter["sections"].append({"kind": "distinctions", "rows": blk["rows"]})
            if blk["kind"] == "definition" and blk["rows"]:
                L.append("### Terms")
                L.append("")
                for d_ in blk["rows"]:
                    L.append(f"- {d_}")
                L.append("")
            if blk["kind"] == "trap" and blk["rows"]:
                L.append("### Known traps")
                L.append("")
                for t_ in blk["rows"][:4]:
                    L.append(f"- {t_}")
                L.append("")

        # --- C. worked cases if there were no failures to build on ---
        if not failed:
            items = [q for q in QUIZ_LIST if sid in Q_MATRIX.get(q["id"], [])]
            if items:
                L.append("### Worked cases")
                L.append("")
                for q in items[:3]:
                    L.append(f"> {q['q']}")
                    L.append("")
                    for o in _option_analysis(q):
                        mark = "\u2713" if o["correct"] else "\u2717"
                        L.append(f"- {mark} **{o['letter']}.** {o['text']}")
                        if o["why"]:
                            L.append(f"    - {o['why']}")
                    L.append("")

        # --- D. end in RETRIEVAL: an untreated item ---
        seen_q = {fi["qid"] for fi in failed}
        untreated = [q for q in QUIZ_LIST if sid in Q_MATRIX.get(q["id"], [])
                     and q["id"] not in seen_q]
        if untreated:
            L.append("### Now apply it \u2014 without looking up")
            L.append("")
            for q in untreated[:2]:
                L.append(f"- {q['q']}")
            L.append("")
            L.append("<sub>Answers deliberately omitted. These are the items you have "
                     "not just been shown; getting them right is the evidence that "
                     "counts.</sub>")
            L.append("")
            chapter["sections"].append({"kind": "retrieval",
                                        "items": [q["id"] for q in untreated[:2]]})
        else:
            L.append("<sub>No untreated item exists on this skill \u2014 a content gap, "
                     "not a gap in you.</sub>")
            L.append("")

        # --- E. what proves it ---
        if f and f["belief"]:
            L.append(f"<sub>Belief state: {belief_summary_line(f['belief'])}</sub>")
            L.append("")
        chapters.append(chapter)

    text = "\n".join(L)
    return {"chapters": chapters, "markdown": text, "words": len(text.split())}

# ---------------------------------------------------------------------------
# STAGE 5: VERIFY
# ---------------------------------------------------------------------------
def loop_verify(conn, prescription):
    """What must be demonstrated for each prescribed intervention, opened
    as missions so the gates are tracked rather than hoped for.

    Also surfaces the delayed checks from EARLIER turns that are now ripe:
    a verification stage that only looked forward would let a repair from
    yesterday sit unproven forever."""
    try:
        due = missions_due_now(conn)
    except Exception:
        due = {"repair": [], "delayed": [], "waiting": 0}
    ripe = [{"mission_id": st["mission_id"], "skill": st["skill"],
             "label": SKILLS.get(st["skill"], {}).get("label", st["skill"]),
             "age_hours": st["age_hours"]} for st in due["delayed"]]
    plan = []
    for rx in prescription["interventions"]:
        try:
            spec = compile_learning_mission(conn, rx["skill"])
            mid = open_mission(conn, spec) if spec else None
            st = mission_state(conn, mid) if mid else None
        except Exception:
            st = None
        plan.append({"skill": rx["skill"], "label": rx["label"], "kind": rx["kind"],
                     "mission_id": st["mission_id"] if st else None,
                     "outstanding": st["outstanding"] if st else list(MISSION_GATES),
                     "delayed_at_hours": MISSION_DELAY_HOURS,
                     # proof should be INTERLEAVED across the topic, not blocked
                     # on one skill -- an exam section mixes them
                     "proof_set": [q["id"] for q in mixed_practice_set(
                         conn, SKILLS.get(rx["skill"], {}).get("topic", ""), 6)]})
    return {"plan": plan, "ripe_delayed": ripe, "waiting": due.get("waiting", 0)}

# ---------------------------------------------------------------------------
# STAGE 6: UPDATE, and the cycle itself
# ---------------------------------------------------------------------------
def run_learning_cycle(conn, budget=5):
    """One full turn of the loop, recorded.

    Returns every stage's output so the UI can show the whole cycle and
    the learner can see what the system saw, what it concluded, what it
    prescribed and why, and what it will take as proof."""
    init_loop_schema(conn)
    observed = loop_observe(conn)
    diagnosis = loop_diagnose(conn, observed)
    prescription = loop_prescribe(conn, diagnosis, budget)
    packet = loop_instruct(conn, diagnosis, prescription)
    verification = loop_verify(conn, prescription)

    # UPDATE: sync every touched belief; missions were opened in verify
    for v in verification["plan"]:
        if v["mission_id"]:
            try:
                sync_belief_from_mission(conn, v["mission_id"])
            except Exception:
                pass

    # A new turn closes the previous open one, scoring it against what
    # happened to the skill it targeted. Until this, outcome/closed_at were
    # never written and the loop had nothing to judge itself by.
    for prev in _safe_query(conn, "SELECT cycle_id, top_skill, top_mastery FROM loop_cycles "
                                  "WHERE closed_at IS NULL") or []:
        conn.execute("UPDATE loop_cycles SET closed_at=?, outcome=? WHERE cycle_id=?",
                     (observed["observed_at"],
                      _cycle_outcome(conn, prev["top_skill"], prev["top_mastery"]),
                      prev["cycle_id"]))

    top = diagnosis["findings"][0] if diagnosis["findings"] else None
    cycle = {"observed": observed, "diagnosis": diagnosis,
             "prescription": prescription, "packet": packet,
             "verification": verification}
    cur = conn.execute("""INSERT INTO loop_cycles
        (started_at, n_evidence, top_skill, top_stance, top_mastery, root_cause,
         prescription, packet_words, cycle_json) VALUES (?,?,?,?,?,?,?,?,?)""",
        (observed["observed_at"], observed["n"],
         top["skill"] if top else None, top["stance"] if top else None,
         top["decayed_mastery"] if top else None,
         (diagnosis["root_causes"][0]["skill"] if diagnosis["root_causes"] else None),
         json.dumps([(r["kind"], r["skill"]) for r in prescription["interventions"]]),
         packet["words"], json.dumps(cycle, default=str)))
    conn.commit()
    cycle_id = cur.lastrowid
    cycle["cycle_id"] = cycle_id
    return cycle

def _cycle_outcome(conn, skill, mastery_then):
    """One line on whether a cycle's top skill moved since the cycle ran."""
    if not skill:
        return "no top skill"
    now = _mastery_now(conn, skill)
    if now is None or mastery_then is None:
        return "unknown"
    delta = now - mastery_then
    word = "improved" if delta > 0.05 else "worse" if delta < -0.05 else "unchanged"
    return f"{word}: {mastery_then*100:.0f}% -> {now*100:.0f}%"

def _mastery_now(conn, skill):
    """Decayed mastery, the same figure loop_diagnose stores as top_mastery,
    so then-vs-now compares like with like."""
    try:
        d = build_skill_dossier(conn, skill)
    except Exception:
        return None
    if not d:
        return None
    return decayed_skill_mastery(conn, skill, d["mastery"] or 0.0)

def loop_history(conn, limit=10):
    init_loop_schema(conn)
    return _safe_query(conn, """SELECT * FROM loop_cycles
                              ORDER BY cycle_id DESC LIMIT ?""", (limit,))

def loop_effectiveness(conn):
    """Did earlier prescriptions work? For each closed cycle, compare the
    top skill's mastery then vs now. This is the loop judging itself."""
    rows = loop_history(conn, 20)
    out = []
    for r in rows:
        if not r["top_skill"]:
            continue
        then = r["top_mastery"] if "top_mastery" in r.keys() else None
        now = _mastery_now(conn, r["top_skill"])
        out.append({"cycle_id": r["cycle_id"], "skill": r["top_skill"],
                    "stance_then": r["top_stance"],
                    "mastery_then": then, "mastery_now": now,
                    "delta": (now - then) if now is not None and then is not None else None,
                    "outcome": r["outcome"], "closed_at": r["closed_at"],
                    "started_at": r["started_at"]})
    return out

def loop_last_cycle(conn):
    """The most recent turn as run_learning_cycle returned it, or None for
    a row written before the turn was persisted."""
    hist = loop_history(conn, 1)
    if not hist:
        return None
    r = hist[0]
    raw = r["cycle_json"] if "cycle_json" in r.keys() else None
    if not raw:
        return None
    try:
        cyc = json.loads(raw)
    except ValueError:
        return None
    cyc["cycle_id"] = r["cycle_id"]
    return cyc

# ============================================================================
# SMALL REUSABLE WIDGETS
# ============================================================================

def stat_chip(parent, label, value, value_color=None, on_click=None, hint=None):
    """A headline figure, optionally a navigation target.

    Most of these numbers ARE a destination -- "Cards due 75" and
    "Checklist 0/18" name a screen the learner then has to go find in the
    sidebar. Rendering them as inert decoration makes the reader do the
    lookup manually. When on_click is supplied the chip lifts on hover and
    carries a caption saying where it goes, so the affordance is visible
    rather than something to be discovered by clicking things."""
    box = ctk.CTkFrame(parent, fg_color=C.NAVY_2, corner_radius=10)
    lab = ctk.CTkLabel(box, text=label, font=(FONT_BODY, 10, "bold"),
                       text_color=C.GOLD_SOFT)
    lab.pack(padx=14, pady=(8, 0), anchor="w")
    val = ctk.CTkLabel(box, text=value, font=(FONT_DISPLAY, 20, "bold"),
                       text_color=(value_color or C.CREAM))
    val.pack(padx=14, pady=(0, 2 if on_click else 8), anchor="w")

    if on_click is None:
        return box

    # NAVY_3 on NAVY_2 rendered as an unreadable smudge -- the affordance
    # was there and invisible, which is worse than absent because it looks
    # like a rendering fault. GOLD_SOFT reads at 9pt on this background.
    cap = ctk.CTkLabel(box, text=(hint or "open"), font=(FONT_BODY, 9),
                       text_color=C.GOLD_SOFT)
    cap.pack(padx=14, pady=(0, 7), anchor="w")

    targets = (box, lab, val, cap)

    def enter(_e=None):
        box.configure(fg_color=C.NAVY_3)
        cap.configure(text_color=C.CREAM)

    def leave(_e=None):
        box.configure(fg_color=C.NAVY_2)
        cap.configure(text_color=C.GOLD_SOFT)

    def click(_e=None):
        on_click()

    # Binding the CustomTkinter wrapper is not enough: each CTk widget draws
    # into an inner tk Label/Canvas, and THAT is what actually receives the
    # pointer events. Binding only the wrapper produced a chip that
    # highlighted on hover and did nothing on click.
    def bind_deep(w):
        for target in (w, getattr(w, "_label", None), getattr(w, "_canvas", None),
                       getattr(w, "_text_label", None)):
            if target is None:
                continue
            try:
                target.bind("<Enter>", enter, add="+")
                target.bind("<Leave>", leave, add="+")
                target.bind("<Button-1>", click, add="+")
                target.configure(cursor="hand2")
            except Exception:
                pass

    for w in targets:
        bind_deep(w)
    return box

def card(parent, **kwargs):
    fg = kwargs.pop("fg_color", C.PAPER_DIM)
    f = ctk.CTkFrame(parent, fg_color=fg, corner_radius=12, border_width=1,
                      border_color=C.PAPER_LINE, **kwargs)
    return f

def bind_autowrap(label, container, padding=48):
    """Keep a label's wraplength matched to the width actually available to it.

    Two things make this harder than it looks:
      1. A CTkScrollableFrame's inner frame sizes to its *content*, not the
         viewport, so measuring the container overshoots and text runs off
         the right edge.
      2. At first render nothing has been laid out yet -- widths report as 1 --
         so a single measurement taken up front is simply wrong, and the text
         stays clipped until something happens to trigger a resize.

    So: measure the label's own immediate parent (which is laid out by the
    same geometry manager that bounds the text), keep retrying until that
    parent reports a real width, and re-apply on every window resize."""
    master = label.master
    root = label.winfo_toplevel()

    def apply_now():
        try:
            if not label.winfo_exists():
                return True  # stop retrying; widget is gone
            w = master.winfo_width()
            if w <= 40:
                return False  # not laid out yet
            # CTkLabel.configure(wraplength=X) internally multiplies X by the
            # display scaling factor before handing it to Tk. winfo_width()
            # already returns REAL pixels, so passing it straight through gets
            # it inflated by 1.25x / 1.5x on a high-DPI Windows display and the
            # text overflows -- invisible on a 1.0-scaling machine. Divide it
            # back out so the final value lands at the true available width.
            try:
                scale = label._get_widget_scaling() or 1.0
            except Exception:
                scale = 1.0
            avail = (w - padding) / scale
            label.configure(wraplength=max(200, int(avail)))
            return True
        except tk.TclError:
            return True

    def retry(attempt=0):
        if apply_now():
            return
        if attempt < 40:  # ~2s of polling, then give up gracefully
            root.after(50, lambda: retry(attempt + 1))

    def on_master_configure(event=None):
        apply_now()

    try:
        master.bind("<Configure>", on_master_configure, add="+")
    except Exception:
        pass

    # Registry lets a window resize re-apply every wrapping label at once,
    # which also covers labels whose parent never fires its own Configure.
    if not hasattr(root, "_autowrap_registry"):
        root._autowrap_registry = []

        def apply_all(event=None):
            alive = []
            for lbl, fn in root._autowrap_registry:
                try:
                    if not lbl.winfo_exists():
                        continue
                    fn()
                    alive.append((lbl, fn))
                except tk.TclError:
                    continue
            root._autowrap_registry = alive

        def on_resize(event=None):
            pending = getattr(root, "_autowrap_after_id", None)
            if pending:
                try:
                    root.after_cancel(pending)
                except Exception:
                    pass
            root._autowrap_after_id = root.after(60, apply_all)

        root._autowrap_apply_all = apply_all
        root.bind("<Configure>", on_resize, add="+")

    root._autowrap_registry.append((label, apply_now))
    root.after_idle(retry)

def section_title(parent, text, subtitle=None):
    wrap = ctk.CTkFrame(parent, fg_color="transparent")
    ctk.CTkLabel(wrap, text=text, font=(FONT_DISPLAY, 25, "bold"), text_color=C.INK,
                 anchor="w").pack(anchor="w")
    rule = ctk.CTkFrame(wrap, height=2, width=54, fg_color=C.BRASS, corner_radius=2)
    rule.pack(anchor="w", pady=(6, 0))
    if subtitle:
        lbl = ctk.CTkLabel(wrap, text=subtitle, font=(FONT_BODY, 12), text_color=C.INK_DIM,
                           anchor="w", justify="left")
        lbl.pack(anchor="w", pady=(7, 0), fill="x")
        bind_autowrap(lbl, parent, padding=70)
    return wrap

def frag_color(label):
    return {"Fragile": C.STAMP, "Developing": C.BRASS_DARK, "Solid": C.FOREST, "Unstudied": C.INK_DIM}.get(label, C.INK)

# ============================================================================
# MODE EXPLANATIONS -- click-to-expand "What is this, and why does it help?"
# shown on each Practice/Timed mode's setup screen. Condensed from a fuller
# guide, kept to what earns a person's attention on a screen they're about to
# click past, not the full essay.
# ============================================================================
MODE_HELP = {
    "quiz": (
        "Untimed multiple choice with hints and an explanation after every answer. Rate "
        "how sure you are before you answer (J/K/L) -- a confident miss is the one worth "
        "seeing again, and it comes back later in the session. Take your time here: this "
        "is where the material gets learned, and nothing is scored against the clock."
    ),
    "adaptive": (
        "Picks each next question at the difficulty you learn fastest from -- hard enough "
        "to make you think, not so hard that you are guessing -- with the topic mix "
        "matched to the real PSI exam rather than spread evenly. You choose how many; "
        "a confident miss comes back before the end."
    ),
    "freerecall": (
        "No options to recognize -- you type the answer from memory, scored by a blend of "
        "keyword coverage, semantic similarity, and (when loaded) entailment scoring, which "
        "catches a fluent-but-wrong answer that cosine similarity alone would miss. "
        "Producing an answer is a harder, more realistic test than recognizing one among "
        "four choices, and your score here genuinely moves your tracked topic mastery, not "
        "just a display number."
    ),
    "errorlog": (
        "Every miss, tagged by cause, resurfacing on a schedule until you've answered it "
        "correctly twice in a row -- one correct answer could be a lucky guess, two in a "
        "row much less likely to be. A miss you never see again isn't fixed, it's just "
        "forgotten that you got it wrong."
    ),
    "blindspots": (
        "Every answer plotted by confidence versus correctness. The dangerous quadrant is "
        "confident-and-wrong, not unsure-and-wrong -- if you're unsure and miss it you "
        "already know to review it, but a confident miss is a real misconception hiding "
        "where instinct won't warn you. Worth a periodic gut-check, especially close to "
        "exam day."
    ),
    "explorer": (
        "Groups your misses by conceptual similarity using semantic embeddings, not by "
        "their fixed topic label -- so it can catch that you're specifically confusing "
        "designated agency with dual agency, even though both questions just say 'Agency.' "
        "A cluster you're concentrated in also gets a real, capped boost in what Adaptive "
        "Drill serves you next, so finding it here actually changes your practice."
    ),
    "diagnostic": (
        "A short timed set, then an untimed retry of anything you missed. Getting an item "
        "right on the retry means you knew it and the clock got in the way; missing it "
        "twice means it still needs learning. Telling those two apart is what decides "
        "what the app has you do next -- so answer the retry honestly, not from memory of "
        "the first pass."
    ),
    "progressive": (
        "A pacing ladder moving from generous time toward the real exam's per-question "
        "pace in stages, rather than jumping straight into a full timed exam. This is also "
        "where your personal timing baseline gets built -- the data that later lets the app "
        "tell your genuine pace from genuine panic."
    ),
    "exam": (
        "The real thing: full-length, strictly timed, PSI-format (110 questions, 4 hours), "
        "with flagging, a pre-submission review screen, and a live pacing coach. A "
        "behavioral controller watches for genuine rushing or accuracy-sliding against your "
        "own timed-condition baseline and offers a short procedural reset cue if it fires -- "
        "then measures whether that cue actually helped, rather than assuming it did."
    ),
}

def mode_info_disclosure(parent, mode_key, wrap_target=None):
    """A small 'What is this, and why does it help?' toggle. Collapsed by
    default so it doesn't compete with the setup screen for attention, but
    one click away for anyone who wants the reasoning, not just the button."""
    text = MODE_HELP.get(mode_key)
    if not text:
        return None
    holder = ctk.CTkFrame(parent, fg_color="transparent", height=0)
    holder.pack(anchor="w", fill="x", pady=(4, 14))
    state = {"open": False}

    body = ctk.CTkFrame(holder, fg_color=C.PAPER_DIM)
    body_inner = ctk.CTkFrame(body, fg_color="transparent", height=0)
    body_inner.pack(fill="x", padx=14, pady=10)
    body_lbl = ctk.CTkLabel(body_inner, text=text, font=(FONT_BODY, 12), text_color=C.INK,
                            anchor="w", justify="left")
    body_lbl.pack(anchor="w", fill="x")
    bind_autowrap(body_lbl, wrap_target or parent, padding=90)

    toggle = ghost_button(holder, "\u2139  What is this, and why does it help?", None)

    def flip():
        state["open"] = not state["open"]
        if state["open"]:
            toggle.configure(text="\u2139  Hide explanation")
            body.pack(anchor="w", fill="x", pady=(6, 0))
        else:
            toggle.configure(text="\u2139  What is this, and why does it help?")
            body.pack_forget()

    toggle.configure(command=flip)
    toggle.pack(anchor="w")
    return holder

def quick_context_panel(parent, conn, wrap_target=None):
    """A compact 'where you stand' strip for setup screens. These used to
    be a single small card sitting at the top of an otherwise-empty window
    -- this fills that space with something a person would actually want
    to see before starting, built entirely from data the app already
    computes elsewhere (weakest_topics), not new decoration. Silently
    renders nothing if there isn't enough history yet, rather than showing
    a panel full of dashes.

    This sits on the screens a learner sees right before a timed set, so
    it names the topics and nothing else: no fragility label, no accuracy
    percentage, no red (spec 7.12). The ranking still comes from the
    fragility model; the numbers behind it live in the Author views."""
    weak = weakest_topics(conn, n=3)
    if not weak:
        return None
    total_attempts = conn.execute("SELECT COUNT(*) c FROM attempts").fetchone()["c"]
    if total_attempts < 5:
        return None
    holder = ctk.CTkFrame(parent, fg_color="transparent", height=0)
    holder.pack(anchor="w", fill="x", pady=(20, 0))
    c = card(holder, fg_color=C.PAPER_DIM)
    c.pack(fill="x")
    inner = ctk.CTkFrame(c, fg_color="transparent", height=0)
    inner.pack(fill="x", padx=18, pady=14)
    ctk.CTkLabel(inner, text="Topics worth a little extra attention",
                 font=(FONT_BODY, 11, "bold"), text_color=C.INK, anchor="w"
                 ).pack(anchor="w", pady=(0, 6))
    ctk.CTkLabel(inner, text="  \u00b7  ".join(TOPICS[tid]["short"] for tid, _frag in weak),
                 font=(FONT_BODY, 12), text_color=C.INK, anchor="w", justify="left",
                 wraplength=600).pack(anchor="w")
    return holder

def lazy_section(parent, title, subtitle, builder, open_by_default=False):
    """A collapsible panel whose contents are BUILT ON FIRST EXPAND.

    CustomTkinter widgets are expensive -- measured at roughly 2.4 ms per
    CTkLabel and 2.6 ms per bordered card() on a modest machine. Views had
    grown to several hundred widgets and took over a second to open, which
    is felt as lag on every visit even though every underlying computation
    runs in single-digit milliseconds. Deferring the heavy panels means the
    page appears immediately and the cost is paid only by someone who
    actually opens that panel, once.

    `builder(container)` is called at most once."""
    holder = ctk.CTkFrame(parent, fg_color="transparent", height=0)
    holder.pack(fill="x", pady=(0, 10))
    state = {"open": False, "built": False}

    head = ctk.CTkFrame(holder, fg_color="transparent", height=0)
    head.pack(fill="x")
    body = ctk.CTkFrame(holder, fg_color="transparent", height=0)

    def flip():
        state["open"] = not state["open"]
        if state["open"]:
            if not state["built"]:
                builder(body)
                state["built"] = True
            body.pack(fill="x", pady=(6, 0))
            toggle.configure(text="\u25be  " + title)
        else:
            body.pack_forget()
            toggle.configure(text="\u25b8  " + title)

    toggle = ctk.CTkButton(head, text="\u25b8  " + title, anchor="w",
                           fg_color="transparent", hover_color=C.PAPER_DIM,
                           text_color=C.INK, font=(FONT_DISPLAY, 14, "bold"),
                           corner_radius=6, height=30, cursor="hand2",
                           command=flip)
    toggle.pack(anchor="w", fill="x")
    if subtitle:
        ctk.CTkLabel(head, text=subtitle, font=(FONT_BODY, 10),
                     text_color=C.INK_DIM, anchor="w").pack(anchor="w", padx=(10, 0))
    if open_by_default:
        flip()
    return holder

GROUP_ORDER = {"National": 0, "NJ-Specific": 1}

def show_skill_note(conn, skill_id, app=None):
    """A dense study brief for one skill.

    Rewritten after a real screenshot showed five paragraphs of the app
    explaining itself above two lines of subject matter. Provenance and
    caveats now live in one small footer line; everything above it is
    content. Nothing is capped and nothing is withheld on the grounds that
    the learner's mastery says they do not need it -- someone who opened a
    page about easements wants the easements material, not a note saying it
    was omitted for their benefit."""
    d = build_skill_dossier(conn, skill_id)
    dense = dense_skill_content(conn, skill_id)
    if not d and not dense["blocks"]:
        return

    win = ctk.CTkToplevel()
    win.title(dense["label"])
    win.geometry("860x720")
    win.configure(fg_color=C.PAPER)
    try:
        win.attributes("-topmost", True)
        win.after(200, lambda: win.attributes("-topmost", False))
    except Exception:
        pass

    sc = ctk.CTkScrollableFrame(win, fg_color="transparent")
    sc.pack(fill="both", expand=True, padx=26, pady=18)
    W = 780                       # wraplength: the window is 860 wide

    ctk.CTkLabel(sc, text=dense["label"], font=(FONT_DISPLAY, 21, "bold"),
                 text_color=C.INK, anchor="w", justify="left",
                 wraplength=W).pack(anchor="w")

    # One status line, not five paragraphs.
    if d:
        stance_col = {"blocked": C.STAMP, "misconception": C.STAMP,
                      "forgetting": C.BRASS_DARK, "pressure": C.BRASS_DARK,
                      "refining": C.FOREST, "solid": C.FOREST}.get(
                          d["stance"], C.INK_DIM)
        ctk.CTkLabel(sc, text=f'{d["headline"]}  {d["strategy"]}',
                     font=(FONT_BODY, 12), text_color=stance_col, anchor="w",
                     justify="left", wraplength=W).pack(anchor="w", pady=(4, 2))
        ctk.CTkLabel(sc,
                     text=(f'{d["topic_name"]}  \u00b7  {d["n_items"]} item(s)  '
                           f'\u00b7  mastery {d["mastery"]*100:.0f}%  \u00b7  '
                           f'{d["seen"]} answer(s)'),
                     font=(FONT_BODY, 10), text_color=C.INK_DIM,
                     anchor="w").pack(anchor="w", pady=(0, 12))

    # ---- YOUR OWN ERRORS, first, when there are any ----
    if d:
        for sec in d["sections"]:
            if sec["key"] != "wrong":
                continue
            ctk.CTkLabel(sc, text="What you actually got wrong",
                         font=(FONT_BODY, 13, "bold"), text_color=C.STAMP,
                         anchor="w").pack(anchor="w", pady=(6, 4))
            for l in sec["lines"]:
                ctk.CTkLabel(sc, text="\u2022  " + str(l), font=(FONT_BODY, 12),
                             text_color=C.INK, anchor="w", justify="left",
                             wraplength=W - 16).pack(anchor="w", pady=1)

    # ---- THE CONTENT ----
    for blk in dense["blocks"]:
        ctk.CTkLabel(sc, text=blk["heading"], font=(FONT_BODY, 13, "bold"),
                     text_color=C.BRASS_DARK, anchor="w").pack(anchor="w",
                                                               pady=(14, 4))
        if blk["kind"] == "distinction":
            for r in blk["rows"]:
                ctk.CTkLabel(sc, text="\u21c4  " + r["pair"],
                             font=(FONT_BODY, 12, "bold"), text_color=C.INK,
                             anchor="w", justify="left",
                             wraplength=W - 16).pack(anchor="w", pady=(4, 0))
                if r["decider"]:
                    ctk.CTkLabel(sc, text="     decided by: " + r["decider"],
                                 font=(FONT_BODY, 12), text_color=C.FOREST,
                                 anchor="w", justify="left",
                                 wraplength=W - 30).pack(anchor="w")
                for side in (r["this"], r["other"]):
                    if side:
                        ctk.CTkLabel(sc, text="     " + side,
                                     font=(FONT_BODY, 11), text_color=C.INK_DIM,
                                     anchor="w", justify="left",
                                     wraplength=W - 30).pack(anchor="w")
        elif blk["kind"] == "worked":
            for r in blk["rows"]:
                ctk.CTkLabel(sc, text="Q.  " + r["stem"], font=(FONT_BODY, 12),
                             text_color=C.INK, anchor="w", justify="left",
                             wraplength=W - 16).pack(anchor="w", pady=(6, 0))
                if r["answer"]:
                    ctk.CTkLabel(sc, text="A.  " + r["answer"],
                                 font=(FONT_BODY, 12, "bold"),
                                 text_color=C.FOREST, anchor="w",
                                 justify="left",
                                 wraplength=W - 30).pack(anchor="w")
                if r["why"]:
                    ctk.CTkLabel(sc, text="     " + r["why"],
                                 font=(FONT_BODY, 11), text_color=C.INK_DIM,
                                 anchor="w", justify="left",
                                 wraplength=W - 30).pack(anchor="w")
        elif blk["kind"] == "related":
            for r in blk["rows"]:
                ctk.CTkLabel(sc, text="\u2022  " + r["stem"], font=(FONT_BODY, 12),
                             text_color=C.INK, anchor="w", justify="left",
                             wraplength=W - 16).pack(anchor="w", pady=(5, 0))
                ctk.CTkLabel(sc, text="     " + r["why"], font=(FONT_BODY, 11),
                             text_color=C.INK_DIM, anchor="w", justify="left",
                             wraplength=W - 30).pack(anchor="w")
        elif blk["kind"] == "sibling":
            row = ctk.CTkFrame(sc, fg_color="transparent")
            row.pack(anchor="w", fill="x")
            for r in blk["rows"]:
                ghost_button(row, r["label"][:34],
                             lambda s_=r["skill"]: (win.destroy(),
                                                    show_skill_note(conn, s_, app))
                             ).pack(anchor="w", pady=2)
        else:
            for r in blk["rows"]:
                ctk.CTkLabel(sc, text="\u2022  " + str(r), font=(FONT_BODY, 12),
                             text_color=C.INK, anchor="w", justify="left",
                             wraplength=W - 16).pack(anchor="w", pady=1)

    # ---- act on it ----
    if d and d["todo"] and app is not None:
        ctk.CTkLabel(sc, text="Do this next", font=(FONT_BODY, 13, "bold"),
                     text_color=C.INK, anchor="w").pack(anchor="w", pady=(18, 4))

        def _run(payload, title):
            pool = [QUIZ_BANK[i] for i in (payload or []) if i in QUIZ_BANK]
            if not pool:
                app.toast("Nothing available for that step.", kind="warn")
                return
            win.destroy()
            QuestionSession(app, app.content, pool, "quiz", title,
                            f"{len(pool)} item(s) for this skill.",
                            allow_hints=True, collect_diagnostics=True,
                            on_finish=lambda s: render_result_screen(
                                app, app.content, s, lambda: app.show_view("checklist")))

        brow = ctk.CTkFrame(sc, fg_color="transparent", height=0)
        brow.pack(anchor="w")
        for lab, kind, payload in d["todo"][:3]:
            if kind == "prereq":
                ghost_button(brow, lab,
                             lambda s_=payload: (win.destroy(),
                                                 show_skill_note(conn, s_, app))
                             ).pack(side="left", padx=(0, 8))
            elif kind == "recall":
                ghost_button(brow, lab,
                             lambda: (win.destroy(), app.show_view("freerecall"))
                             ).pack(side="left", padx=(0, 8))
            else:
                ghost_button(brow, lab,
                             lambda p=payload, l=lab: _run(p, l)
                             ).pack(side="left", padx=(0, 8))

    # ---- one footer, not five paragraphs ----
    # Say precisely what is missing rather than "this brief is short".
    # A named gap is a work order; a vague apology is noise.
    try:
        cc = skill_completeness(conn, skill_id)
    except Exception:
        cc = None
    if cc and cc["score"] < 0.999:
        ctk.CTkLabel(sc, text="What this skill still lacks",
                     font=(FONT_BODY, 12, "bold"), text_color=C.BRASS_DARK,
                     anchor="w").pack(anchor="w", pady=(18, 3))
        ctk.CTkLabel(sc, text=completeness_line(cc), font=(FONT_BODY, 11),
                     text_color=C.INK_DIM, anchor="w", justify="left",
                     wraplength=W).pack(anchor="w")
        for m in cc["missing"][:4]:
            ctk.CTkLabel(sc, text=f"   \u2022 {m['asset']} \u2014 {m['why']}",
                         font=(FONT_BODY, 10), text_color=C.INK_DIM,
                         anchor="w", justify="left",
                         wraplength=W - 20).pack(anchor="w")

    srcs = ", ".join(sorted({b["source"] for b in dense["blocks"]}))
    ctk.CTkLabel(sc,
                 text=("Assembled from authored material \u2014 nothing generated. "
                       + (f"Sources: {srcs}." if srcs else "")),
                 font=(FONT_BODY, 9), text_color=C.INK_DIM, anchor="w",
                 justify="left", wraplength=W).pack(anchor="w", pady=(14, 2))
    ghost_button(sc, "Close", win.destroy).pack(anchor="w", pady=(8, 0))

    def _fit():
        try:
            if not win.winfo_exists():
                return
            sc.update_idletasks()
            bb = sc._parent_canvas.bbox("all")
            if bb:
                win.geometry(f"860x{max(430, min(920, (bb[3] - bb[1]) + 76))}")
        except Exception:
            pass
    win.after(60, _fit)


def skill_breakdown_panel(parent, conn, topic_id, wrap_target=None,
                          toggle_host=None, app=None):
    """DINA per-skill mastery breakdown for topics with a genuine multi-skill
    Q-matrix. Renders nothing for ordinary single-skill topics -- a joint
    profile adds nothing over the topic-level number when there is one skill.

    Both the widgets AND the posterior are built on first expand. Case File
    shows one of these per topic and 11 topics now have a breakdown; doing
    the DINA update plus row construction for all of them on every render
    cost ~900 ms on a view where the panels are collapsed by default and
    most are never opened."""
    skill_ids = topic_skill_ids(topic_id)
    if len(skill_ids) < 2:
        return None

    holder = ctk.CTkFrame(parent, fg_color="transparent", height=0)
    holder.pack(anchor="w", fill="x", pady=(6, 10))
    state = {"open": False, "built": False}
    body = ctk.CTkFrame(holder, fg_color=C.PAPER_DIM)
    body_inner = ctk.CTkFrame(body, fg_color="transparent", height=0)
    body_inner.pack(fill="x", padx=14, pady=12)

    def _build_body():
        if state["built"]:
            return
        state["built"] = True
        post = dina_topic_posterior(conn, topic_id)
        if not post:
            ctk.CTkLabel(body_inner, text="Not enough answers in this topic yet.",
                         font=(FONT_BODY, 11), text_color=C.INK_DIM,
                         anchor="w").pack(anchor="w")
            return
        note = ctk.CTkLabel(
            body_inner,
            text=("A topic-level score blends this topic's sub-facts into one number. This is a "
                  "per-skill diagnosis (a DINA cognitive-diagnosis model) from your own recent "
                  "answers, showing which of this topic's distinct sub-facts you actually know."),
            font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w", justify="left")
        note.pack(anchor="w", fill="x", pady=(0, 10))
        bind_autowrap(note, wrap_target or parent, padding=100)
        for sid in sorted(skill_ids, key=lambda s: -post["skill_mastery"][s]):
            m = post["skill_mastery"][sid]
            row = ctk.CTkFrame(body_inner, fg_color="transparent", height=0)
            row.pack(fill="x", pady=2)
            # Each skill row opens its own COMPOSED note. A learner sitting
            # at 4% on one sub-skill was previously sent to the whole topic
            # note, most of which they already know; this gives them the
            # fragment that is actually about their gap.
            sl = ctk.CTkLabel(row, text=SKILLS[sid]["label"], font=(FONT_BODY, 12),
                              text_color=C.INK, width=230, anchor="w")
            sl.pack(side="left")

            def _open_skill(s_=sid):
                show_skill_note(conn, s_)

            for tgt in (sl, getattr(sl, "_label", None)):
                if tgt is None:
                    continue
                try:
                    tgt.bind("<Button-1>",
                             lambda _e, s_=sid: show_skill_note(conn, s_, app))
                    tgt.configure(cursor="hand2")
                except Exception:
                    pass
            track = ctk.CTkFrame(row, fg_color=C.PAPER_LINE, height=10, corner_radius=5)
            track.pack(side="left", fill="x", expand=True, padx=8)
            track.pack_propagate(False)
            col = C.FOREST if m >= 0.6 else (C.BRASS if m >= 0.35 else C.STAMP)
            ctk.CTkFrame(track, fg_color=col, height=10, corner_radius=5,
                         width=max(3, int(m * 260))).place(x=0, y=0)
            ctk.CTkLabel(row, text=f"{m*100:.0f}%", font=(FONT_MONO, 11),
                         text_color=C.INK_DIM, width=44, anchor="e").pack(side="left")
        ctk.CTkLabel(body_inner,
                     text=f"Based on your {post['n']} most recent answers in this topic.",
                     font=(FONT_BODY, 9), text_color=C.INK_DIM,
                     anchor="w").pack(anchor="w", pady=(8, 0))

    # The toggle can live on the topic's own title row instead of claiming a
    # second row per topic. With 18 topics that second row was the single
    # biggest contributor to this view's scroll burden -- measured at 2.25
    # screens, the worst in the app -- for a control most topics never open.
    toggle = ghost_button(toggle_host or holder,
                          (f"\u2139  {len(skill_ids)} sub-skills" if toggle_host
                           else f"\u2139  Skill breakdown ({len(skill_ids)} sub-skills)"),
                          None)

    def flip():
        state["open"] = not state["open"]
        if state["open"]:
            _build_body()
            toggle.configure(text="\u2139  Hide skill breakdown")
            body.pack(anchor="w", fill="x", pady=(6, 0))
        else:
            toggle.configure(text=(f"\u2139  {len(skill_ids)} sub-skills" if toggle_host
                                   else f"\u2139  Skill breakdown "
                                        f"({len(skill_ids)} sub-skills)"))
            body.pack_forget()

    toggle.configure(command=flip)
    if toggle_host is not None:
        toggle.pack(side="right", padx=(0, 10))
    else:
        toggle.pack(anchor="w")
    return holder


def primary_button(parent, text, command, width=None, fg=C.BRASS, hover=C.BRASS_DARK, text_color="#221A0C"):
    return ctk.CTkButton(parent, text=text, command=command, fg_color=fg, hover_color=hover,
                          text_color=text_color, font=(FONT_BODY, 13, "bold"), corner_radius=8,
                          height=38, width=width or 0, cursor="hand2")

def ghost_button(parent, text, command, width=None):
    return ctk.CTkButton(parent, text=text, command=command, fg_color="transparent",
                          hover_color=C.PAPER_LINE, text_color=C.INK, font=(FONT_BODY, 13),
                          corner_radius=8, height=36, border_width=1, border_color=C.PAPER_LINE,
                          width=width or 0, cursor="hand2")

def ghost_button_dark(parent, text, command, width=None):
    """Same as ghost_button but for use on a dark (navy) card background --
    ghost_button's dark ink text is illegible there since its 'transparent'
    fill inherits the surrounding dark color."""
    return ctk.CTkButton(parent, text=text, command=command, fg_color="transparent",
                          hover_color=C.NAVY_2, text_color=C.CREAM, font=(FONT_BODY, 13),
                          corner_radius=8, height=36, border_width=1, border_color=C.GOLD_SOFT,
                          width=width or 0, cursor="hand2")

def styled_entry(parent, **kwargs):
    """CTkEntry with all colors pinned explicitly. Without this, CTkEntry
    falls back to CustomTkinter's theme defaults, which follow the OS's
    light/dark setting even though we force light appearance mode elsewhere
    -- pinning every color here is defense in depth against that class of
    bug (text rendering unreadable against our fixed light palette)."""
    width = kwargs.pop("width", 160)
    font = kwargs.pop("font", (FONT_BODY, 13))
    entry = ctk.CTkEntry(parent, width=width, font=font,
                          fg_color="#FFFFFF", text_color=C.INK,
                          placeholder_text_color=C.INK_DIM,
                          border_color=C.PAPER_LINE, border_width=1,
                          **kwargs)
    return entry

