class TrainerApp(ctk.CTk):
    def __init__(self):
        super().__init__()
        self.conn = db_connect()
        init_schema(self.conn)
        resolve_fonts()
        try:
            saved_scale = float(get_setting(self.conn, "ui_scale", "1.0"))
            if abs(saved_scale - 1.0) > 0.01:
                ctk.set_widget_scaling(saved_scale)
        except Exception:
            pass

        self.title("NJ Real Estate Licensing Trainer")
        self.geometry("1280x900")
        self.minsize(1040, 680)
        self.configure(fg_color=C.NAVY)

        self.nav_buttons = {}
        self.toast_label = None
        self.toast_after_id = None
        self.active_session = None
        self.protocol("WM_DELETE_WINDOW", self._on_close)
        self._build_shell()
        self._splash = None
        self._splash_state = None
        self._run_startup_sequence()

    # =======================================================================
    # STARTUP: THE RECURSA LOOP, DRAWN WHILE IT WARMS
    # =======================================================================
    # This is a splash screen that does real work. The measured cost of a
    # cold start is dominated by one thing: computing the DINA class
    # posterior for every decomposed topic (174ms measured across 11 topics,
    # 0ms once cached). The dashboard pays part of it, and the first item
    # selection of the session pays the rest -- as a stall between pressing
    # Start and seeing a question, which is the worst possible moment for it.
    #
    # Rather than hide that behind a spinner, the startup screen draws the
    # architecture the app is actually built on -- the shared learner model
    # at the centre, the subsystems reading from and writing to it -- and
    # lights each subsystem up as its cache genuinely finishes warming. The
    # animation is not a progress bar dressed up; each node turns live only
    # when the work it represents has actually completed.
    #
    # The warming runs on a background thread with its own connection, and
    # the whole screen is skippable and self-dismissing: if warming fails
    # for any reason the app proceeds anyway, because every cache here is an
    # optimisation, never a requirement.

    # =======================================================================
    # STARTUP: THE RECURSA LOOP, DRAWN FROM THIS LEARNER'S OWN STATE
    # =======================================================================
    # A splash that does real work, and shows real data while doing it.
    #
    # WHAT IT WARMS. Cold start is dominated by one measured cost: the DINA
    # class posterior for every decomposed topic (174ms across 11 topics,
    # 1ms once cached). Worse than its size is its timing -- the first item
    # selection of a session paid part of it, as a stall between pressing
    # Start and seeing a question. Paying it here removes it from the moment
    # it hurts most.
    #
    # WHAT MAKES IT ADAPTIVE, in three distinct senses:
    #   1. To the WINDOW -- every coordinate derives from the live canvas
    #      size, so it composes correctly from a small laptop window to a
    #      maximised 4K one instead of assuming a fixed geometry.
    #   2. To the LEARNER -- the outer ring is not decoration. It is one arc
    #      segment per topic, coloured by that topic's real fragility, so a
    #      returning learner sees their own progress the moment the app
    #      opens. A first-run learner sees an unlit ring, which is honest
    #      rather than a fake full circle.
    #   3. To PROGRESS -- each subsystem node fades in on an eased curve
    #      only once its cache genuinely finishes warming. It is not a
    #      progress bar dressed as a diagram.
    #
    # Everything here is optional: warming failures are swallowed per-step,
    # the screen is skippable, and it self-dismisses on a hard ceiling.

    def _run_startup_sequence(self):
        splash = ctk.CTkFrame(self, fg_color=C.NAVY, corner_radius=0)
        splash.place(relx=0, rely=0, relwidth=1, relheight=1)
        self._splash = splash

        canvas = tk.Canvas(splash, bg=C.NAVY, highlightthickness=0, bd=0)
        canvas.pack(fill="both", expand=True)

        nodes = [
            ("knowledge", "Knowledge", "IRT \u00b7 BKT \u00b7 PFA", -90),
            ("diagnosis", "Diagnosis", "per-skill DINA", -30),
            ("selection", "Selection", "CD-CAT \u00b7 blueprint", 30),
            ("memory", "Memory", "FSRS-6 \u00b7 relearning", 90),
            ("behaviour", "Behaviour", "pace \u00b7 calibration", 150),
            ("content", "Content", "search \u00b7 embeddings", 210),
        ]
        # Warming marks one extra key ("capability") that has no ring node
        # of its own -- it is reported in the tier line instead. The live
        # counter must therefore count only keys that ARE nodes, or it
        # reads "7 / 6", which it did.
        node_keys = {k for k, _, _, _ in nodes}

        state = {"t": 0.0, "live": {}, "done": False, "job": None,
                 "ring": [], "stats": None, "returning": False,
                 # `tr` drives the whole settle choreography: 0 = working,
                 # 1 = fully settled and inviting. Every element that moves
                 # during the transition reads from this one number, so the
                 # motion stays coherent instead of six things easing on
                 # their own schedules.
                 "tr": 0.0, "settle_at": None, "audio": False,
                 # Cleared the moment the splash is dismissed, so the warm
                 # thread does not start music under the main app when Skip
                 # lands before synthesis has finished.
                 "audio_wanted": True}
        self._splash_state = state

        # Palette taken from the reference splash design rather than reusing
        # the app's UI colours: a deep-space navy that goes almost black at
        # the edges, and a warmer, lighter gold than the interface brass.
        SPACE_CORE = "#17345c"     # centre of the background wash
        SPACE_MID = "#0b162c"
        SPACE_EDGE = "#060914"     # near-black at the corners
        GOLD = "#d7bc7a"           # the dominant accent
        GOLD_HOT = "#f3e0a8"       # highlight / inner glow
        CREAM_HI = "#f8f1e2"

        def _mix(c1, c2, f):
            """Blend two #rrggbb colours. Tk has no alpha, so every glow and
            fade here is done by mixing toward the background instead."""
            f = max(0.0, min(1.0, f))
            a = [int(c1[i:i + 2], 16) for i in (1, 3, 5)]
            b = [int(c2[i:i + 2], 16) for i in (1, 3, 5)]
            return "#%02x%02x%02x" % tuple(int(a[i] + (b[i] - a[i]) * f) for i in range(3))

        def _ease(x):
            # Cubic ease-out: fast arrival, gentle settle. Linear fades read
            # as mechanical; this reads as deliberate.
            x = max(0.0, min(1.0, x))
            return 1 - (1 - x) ** 3

        # Persistent particle systems, seeded once. Drawing them from a
        # stable seed rather than re-randomising each frame is what makes
        # the motion read as a continuous system rather than static noise
        # flickering in place.
        _rng = random.Random(20260831)
        drift = [{"a": _rng.uniform(0, 360), "r": _rng.uniform(0.35, 1.95),
                  "sp": _rng.uniform(0.05, 0.32), "sz": _rng.uniform(0.7, 2.1),
                  "br": _rng.uniform(0.10, 0.42)} for _ in range(90)]
        # Packets travel the spokes between hub and node -- the literal
        # "reads from and writes to" of the architecture, in both
        # directions, which the earlier version only implied with a label.
        packets = [{"node": _rng.randrange(6), "p": _rng.random(),
                    "sp": _rng.uniform(0.010, 0.024),
                    "out": _rng.random() < 0.5} for _ in range(26)]
        # Occasional node-to-node crosstalk arcs, so the ring isn't the only
        # thing connecting subsystems.
        sparks = []

        def draw():
            if not canvas.winfo_exists():
                return
            w = max(canvas.winfo_width(), 200)
            h = max(canvas.winfo_height(), 200)
            cx, cy = w / 2.0, h * 0.55
            # The ring sits at R*1.30, so usable vertical space below the
            # title block and above the Skip button bounds R -- not
            # min(w,h), which let the ring collide with the subtitle.
            # Reserve the bottom strip for the tier line and Enter control,
            # or the ring overlaps both (it did).
            avail = (h * 0.80 - h * 0.21) / 2.0 / 1.32
            t = state["t"]
            # `tr` must be read BEFORE anything that scales with it -- R
            # below is the first such use.
            tr = state.get("tr", 0.0)
            # Everything below eases with `tr`: the ring draws in slightly,
            # motion slows, glow warms, and the busy working texture
            # (starfield density, packet speed) relaxes into a calm ready
            # state.
            calm = 1.0 - tr
            R = max(110.0, min(min(w * 0.30, avail), 260.0)) * (1.0 - 0.055 * tr)
            canvas.delete("all")

            # ---------- deep-space background wash ----------
            # Tk has no gradients, so a radial falloff is built from
            # concentric filled ovals stepping between three stops. Drawn
            # first, everything else sits on top. This is what makes the
            # frame read as depth rather than a flat navy rectangle.
            cv_w, cv_h = w, h
            steps = 46
            maxr = math.hypot(w, h) * 0.62
            for i in range(steps, 0, -1):
                f = i / steps
                rr = maxr * f
                if f > 0.5:
                    col = _mix(SPACE_MID, SPACE_EDGE, (f - 0.5) / 0.5)
                else:
                    col = _mix(SPACE_CORE, SPACE_MID, f / 0.5)
                canvas.create_oval(cx - rr, cy * 0.92 - rr, cx + rr, cy * 0.92 + rr,
                                   fill=col, outline="")

            # ---------- drifting starfield ----------
            # Slow orbital drift at varied radii and speeds gives real
            # parallax: near particles visibly outrun far ones.
            for d in drift[:int(len(drift) * (1.0 - 0.45 * tr))]:
                a = math.radians(d["a"] + t * d["sp"] * (1.0 - 0.55 * tr))
                rr = R * d["r"]
                px, py = cx + rr * math.cos(a), cy + rr * math.sin(a) * 0.92
                tw = 0.55 + 0.45 * math.sin(math.radians(t * 2.6 + d["a"] * 3))
                sz = d["sz"]
                canvas.create_oval(px - sz, py - sz, px + sz, py + sz,
                                   fill=_mix(C.NAVY, C.GOLD_SOFT, d["br"] * tw),
                                   outline="")


            # ---------- pulse rings emitted from the hub ----------
            for k in range(3):
                ph = ((t * 0.011) + k / 3.0) % 1.0
                pr = R * (0.44 + ph * 0.92)
                canvas.create_oval(cx - pr, cy - pr, cx + pr, cy + pr,
                                   outline=_mix(SPACE_MID, GOLD, 0.22 * (1.0 - ph)),
                                   width=2)

            # ---------- learner's topic ring, shimmering ----------
            ring = state["ring"]
            node_pos = []
            if ring:
                rr = R * 1.30
                seg = 360.0 / len(ring)
                for i, (label, frag_score, studied) in enumerate(ring):
                    start = 90 - (i + 1) * seg + 1.2 - (t * 0.05) % 360
                    if not studied:
                        base = _mix(C.NAVY, C.NAVY_2, 0.55)
                    elif frag_score >= 55:
                        base = C.STAMP
                    elif frag_score >= 30:
                        base = C.BRASS
                    else:
                        base = C.FOREST
                    # A travelling highlight sweeps the ring, so the arc set
                    # reads as one connected instrument rather than 18
                    # separate bars.
                    sweep = ((math.sin(math.radians(t * 2.2 - i * 24)) + 1) / 2) * (1.0 - 0.5 * tr)
                    col = _mix(base, C.CREAM, 0.30 * sweep) if studied else base
                    canvas.create_arc(cx - rr, cy - rr, cx + rr, cy + rr,
                                      start=start, extent=seg - 2.4,
                                      style="arc", outline=col,
                                      width=6 + 2.5 * sweep)

            # ---------- spokes, nodes, and travelling packets ----------
            for idx, (key, title, sub, ang) in enumerate(nodes):
                a = math.radians(ang)
                nx, ny = cx + R * math.cos(a), cy + R * math.sin(a)
                node_pos.append((nx, ny))
                born = state["live"].get(key)
                p = _ease((t - born) / 26.0) if born is not None else 0.0
                canvas.create_line(cx, cy, nx, ny,
                                   fill=_mix(_mix(SPACE_MID, GOLD, 0.22), GOLD, p * 0.85),
                                   width=1 + 1.3 * p)

            # Packets ride the spokes in both directions.
            for pk in packets:
                nx, ny = node_pos[pk["node"] % len(node_pos)]
                pk["p"] += pk["sp"] * (1.0 - 0.72 * tr)
                if pk["p"] > 1.0:
                    pk["p"] = 0.0
                    pk["node"] = _rng.randrange(len(node_pos))
                    pk["out"] = _rng.random() < 0.5
                    pk["sp"] = _rng.uniform(0.010, 0.024)
                f = pk["p"] if pk["out"] else (1.0 - pk["p"])
                # Ease toward the hub so packets decelerate as they arrive,
                # which reads as data settling rather than bouncing.
                fe = f * f * (3 - 2 * f)
                px = cx + (nx - cx) * fe
                py = cy + (ny - cy) * fe
                glow = 0.5 + 0.5 * math.sin(math.radians(t * 8 + pk["p"] * 360))
                sz = 2.6 + 1.5 * glow
                col = C.GOLD_SOFT if pk["out"] else C.CREAM
                canvas.create_oval(px - sz, py - sz, px + sz, py + sz,
                                   fill=_mix(C.NAVY_2, col, (0.55 + 0.45 * glow) * (1.0 - 0.55 * tr)),
                                   outline="")

            # ---------- crosstalk arcs between subsystems ----------
            if len(node_pos) >= 2 and _rng.random() < 0.06 * calm:
                i, j = _rng.sample(range(len(node_pos)), 2)
                sparks.append({"i": i, "j": j, "life": 1.0})
            for sp in list(sparks):
                sp["life"] -= 0.035
                if sp["life"] <= 0:
                    sparks.remove(sp)
                    continue
                x1, y1 = node_pos[sp["i"]]
                x2, y2 = node_pos[sp["j"]]
                # Bow the line through a point pulled toward the hub, so
                # crosstalk visibly passes through the shared model rather
                # than bypassing it.
                mx, my = (x1 + x2) / 2, (y1 + y2) / 2
                bx, by = mx + (cx - mx) * 0.55, my + (cy - my) * 0.55
                canvas.create_line(x1, y1, bx, by, x2, y2, smooth=True,
                                   fill=_mix(C.NAVY, C.BRASS, 0.55 * sp["life"]),
                                   width=1.6)

            # ---------- node bodies, drawn above the packets ----------
            for idx, (key, title, sub, ang) in enumerate(nodes):
                nx, ny = node_pos[idx]
                born = state["live"].get(key)
                p = _ease((t - born) / 26.0) if born is not None else 0.0
                base_r = max(20.0, R * 0.115)
                if p > 0:
                    for gi in range(4, 0, -1):
                        gr = base_r + gi * 5 * p + math.sin(math.radians(t * 2.4 + ang)) * 1.8
                        canvas.create_oval(nx - gr, ny - gr, nx + gr, ny + gr,
                                           outline=_mix(SPACE_MID, GOLD, 0.20 * p / gi),
                                           width=2)
                r = base_r * (0.72 + 0.28 * p)
                # RADIAL-GRADIENT DISC. A flat fill reads as a sticker; the
                # reference design uses a lit sphere. Concentric rings step
                # from a hot highlight offset up-left toward a darker rim,
                # which is what gives each node the sense of being a lit
                # object rather than a coloured dot.
                if p > 0.02:
                    layers = 9
                    for k in range(layers, 0, -1):
                        f = k / layers
                        rr = r * f
                        # highlight sits toward the upper-left, as if lit
                        ox, oy = nx - r * 0.16 * (1 - f), ny - r * 0.18 * (1 - f)
                        inner = _mix(GOLD_HOT, GOLD, 1.0 - f)
                        col = _mix(C.NAVY_2, inner, p * (0.35 + 0.65 * (1.0 - f)))
                        canvas.create_oval(ox - rr, oy - rr, ox + rr, oy + rr,
                                           fill=col, outline="")
                canvas.create_oval(nx - r, ny - r, nx + r, ny + r,
                                   fill="" if p > 0.02 else _mix(SPACE_MID, C.NAVY_2, 0.6),
                                   outline=_mix(_mix(SPACE_MID, GOLD, 0.30), GOLD, p),
                                   width=1.4 + 0.8 * p)
                if p > 0.25:
                    canvas.create_text(nx, ny, text="\u2713",
                                       fill=_mix(GOLD, CREAM_HI, p),
                                       font=(FONT_BODY, int(11 + 3 * p), "bold"))
                canvas.create_text(nx, ny + r + 16, text=title,
                                   fill=_mix(C.NAVY_3, C.CREAM, max(p, 0.35)),
                                   font=(FONT_BODY, 10, "bold"))
                canvas.create_text(nx, ny + r + 30, text=sub,
                                   fill=_mix(C.NAVY_3, C.GOLD_SOFT, max(p, 0.25)),
                                   font=(FONT_BODY, 8))

            # ---------- hub ----------
            hr = max(78.0, R * 0.44) + math.sin(math.radians(t * 1.8)) * 2.5
            for gi in range(5, 0, -1):
                gr = hr + gi * 4
                canvas.create_oval(cx - gr, cy - gr, cx + gr, cy + gr,
                                   outline=_mix(SPACE_MID, GOLD, (0.30 + 0.45 * tr) / gi), width=2)
            canvas.create_oval(cx - hr, cy - hr, cx + hr, cy + hr,
                               fill=_mix(SPACE_MID, SPACE_CORE, 0.35),
                               outline=GOLD_HOT, width=2)

            # Live waveform across the hub -- a running trace, not a loop,
            # so the centre never looks frozen even once warming completes.
            pts = []
            for i in range(-30, 31):
                x = cx + i * (hr * 0.028)
                amp = hr * 0.10
                y = (cy + hr * 0.60
                     + math.sin(math.radians(i * 11 + t * 7)) * amp * 0.6
                     + math.sin(math.radians(i * 27 - t * 4)) * amp * 0.4)
                pts += [x, y]
            canvas.create_line(*pts, smooth=True,
                               fill=_mix(C.NAVY_2, C.BRASS, 0.75), width=1.6)

            canvas.create_text(cx, cy - 34, text="LEARNER MODEL",
                               fill=C.GOLD_SOFT, font=(FONT_BODY, 9, "bold"))
            st_ = state["stats"]
            if st_:
                canvas.create_text(cx, cy - 6, text=st_["headline"],
                                   fill=C.CREAM, font=(FONT_DISPLAY, 20, "bold"))
                canvas.create_text(cx, cy + 18, text=st_["sub"],
                                   fill=C.GOLD_SOFT, font=(FONT_BODY, 9))
            canvas.create_text(cx, cy + 38,
                               text=f"{len([k for k in state['live'] if k in node_keys])}"
                                    f" / {len(nodes)} subsystems live",
                               fill=_mix(C.NAVY_2, C.GOLD_SOFT, 0.8),
                               font=(FONT_BODY, 8, "bold"))

            # ---------- titles ----------
            canvas.create_text(cx, h * 0.085, text="R E C U R S A",
                               fill=C.CREAM, font=(FONT_DISPLAY, 30, "bold"))
            canvas.create_line(cx - 90, h * 0.125, cx + 90, h * 0.125,
                               fill=C.BRASS, width=2)
            canvas.create_text(
                cx, h * 0.163,
                text="every answer changes what the system believes,\n"
                     "and what it believes chooses the next question",
                fill=_mix(C.NAVY, C.GOLD_SOFT, 1.0 - 0.45 * tr),
                font=(FONT_BODY, 11), justify="center")

            # ---------- live step / capability status ----------
            step = state.get("step")
            if step:
                # A moving ellipsis, so a long model download visibly
                # progresses instead of looking hung.
                dots = "." * (1 + int(t / 12) % 3)
                canvas.create_text(cx, h * 0.870, text=step.rstrip(".\u2026") + dots,
                                   fill=C.GOLD_SOFT, font=(FONT_BODY, 10))
            elif state.get("tier") is not None:
                tier = state["tier"]
                name = SEMANTIC_TIERS.get(tier, {}).get("name", "Precomputed vectors")
                hw = state.get("hw") or {}
                bits = [f"{hw.get('cores', '?')} cores", f"{hw.get('ram_gb', 0):.0f} GB"]
                if hw.get("gpu"):
                    bits.append(f"GPU {hw.get('vram_gb', 0):.0f} GB")
                canvas.create_text(
                    cx, h * 0.870,
                    text=f"Semantic tier {tier} \u00b7 {name}   \u2014   " + " \u00b7 ".join(bits),
                    fill=_mix(C.NAVY_2, C.GOLD_SOFT, 0.85), font=(FONT_BODY, 9))

            # ---------- ENTER control ----------
            eb = state.get("enter_born")
            if eb is not None:
                ep = _ease((t - eb) / 22.0)
                ex, ey, hw2, hh2 = cx, h * 0.930, 138.0, 22.0
                hot = state.get("enter_hot")
                breathe = (math.sin(math.radians(t * 3.2)) + 1) / 2
                # Outer glow, stronger on hover
                layers = 6 if hot else 4
                for gi in range(layers, 0, -1):
                    pad = gi * (3.4 if hot else 2.4) + breathe * 2.0
                    canvas.create_oval(ex - hw2 - pad, ey - hh2 - pad,
                                       ex + hw2 + pad, ey + hh2 + pad,
                                       outline=_mix(SPACE_MID, GOLD,
                                                    (0.34 if hot else 0.18) * ep / gi),
                                       width=2)
                fill = _mix(SPACE_MID, GOLD, (0.22 if hot else 0.06) * ep)
                canvas.create_oval(ex - hw2, ey - hh2, ex + hw2, ey + hh2,
                                   fill=fill,
                                   outline=_mix(SPACE_MID, GOLD_HOT if hot else GOLD, ep),
                                   width=1.6)
                canvas.create_text(ex, ey, text="E N T E R   R E C U R S A",
                                   fill=_mix(SPACE_MID, CREAM_HI if hot else GOLD_HOT, ep),
                                   font=(FONT_BODY, 11, "bold"))
                # A light sweep travelling across the control, so it reads
                # as charged rather than merely coloured.
                sw = ((t * 0.02) % 1.6) - 0.3
                if 0.0 <= sw <= 1.0 and ep > 0.6:
                    sx = ex - hw2 + sw * hw2 * 2
                    canvas.create_line(sx, ey - hh2 + 4, sx, ey + hh2 - 4,
                                       fill=_mix(fill, C.CREAM, 0.45), width=3)

            state["t"] += 1.0
            state["job"] = self.after(33, draw)

        def warm():
            """Warms caches AND loads the strongest semantic backend this
            machine can sustain.

            The model load is the reason this screen earns its existence.
            Loading a sentence encoder takes seconds -- long enough that
            doing it lazily means the first Failure Explorer or Free Recall
            visit of a session stalls with no explanation. Startup is the
            only moment where spending that time is honest, because the
            learner has not yet asked for anything.

            Everything here is best-effort. Every step is individually
            wrapped, and a failure at any tier demotes to the tier below
            rather than blocking: Tier 0 (precomputed vectors) ships with
            the app and cannot fail, so there is always a working floor."""
            wconn = None
            try:
                wconn = db_connect()

                # Ambience is synthesised (~0.8s) and started here, on the
                # warm thread, so it never delays the first frame.
                # Respects a remembered mute preference.
                try:
                    if (state["audio_wanted"]
                            and get_setting(wconn, "splash_audio", "on") != "off"):
                        state["audio"] = ambience_start()
                except Exception:
                    pass

                # --- learner state, so the ring and hub show real data ---
                try:
                    frag = all_topic_fragility(wconn)
                    ring = []
                    for tid in sorted(TOPICS):
                        f = frag.get(tid, {})
                        ring.append((TOPICS[tid]["short"], f.get("score", 50.0),
                                     bool(f.get("n"))))
                    state["ring"] = ring
                    n_att = wconn.execute(
                        "SELECT COUNT(*) c FROM attempts").fetchone()["c"]
                    studied = sum(1 for _, _, s in ring if s)
                    state["returning"] = n_att > 0
                    state["stats"] = ({"headline": f"{n_att:,} answers",
                                       "sub": f"{studied} of {len(ring)} topics under way"}
                                      if n_att else
                                      {"headline": "Ready",
                                       "sub": "no history yet \u2014 start with the diagnostic"})
                except Exception:
                    pass
                state["live"]["knowledge"] = state["t"]
                try:
                    ability_with_se(wconn)
                except Exception:
                    pass

                # --- precomputed content layer (always available) ---
                state["step"] = "Loading precomputed vectors\u2026"
                try:
                    enrichment()
                    _load_embeddings()
                except Exception:
                    pass
                state["live"]["content"] = state["t"]

                # --- the expensive psychometric warm: 174ms cold, 1ms warm ---
                # Build the evidence graph if it has not been built. One-off
                # (~1.6 s) and idempotent -- build_graph returns early when
                # edges already exist -- so this costs nothing on later runs.
                state["step"] = "Building the evidence graph\u2026"
                try:
                    build_graph(wconn)
                    # Prerequisite edges are what upstream_bottleneck reads.
                    # Without this call the prerequisite_drill branch of
                    # next_uncertainty_cut could never fire -- the graph had
                    # the machinery and none of the edges.
                    infer_prerequisites(wconn)
                except Exception:
                    pass

                state["step"] = "Computing per-skill diagnosis\u2026"
                try:
                    for tid in TOPICS:
                        if len(topic_skill_ids(tid)) >= 2:
                            _dina_class_posterior(wconn, tid)
                except Exception:
                    pass
                state["live"]["diagnosis"] = state["t"]

                try:
                    readiness_forecast(wconn)
                except Exception:
                    pass
                state["live"]["selection"] = state["t"]

                try:
                    fsrs_desired_retention(wconn)
                    personal_review_median(wconn)
                except Exception:
                    pass
                state["live"]["memory"] = state["t"]

                try:
                    calibration_by_regime(wconn)
                except Exception:
                    pass
                state["live"]["behaviour"] = state["t"]

                # --- CAPABILITY TIER: load the strongest backend available ---
                # This is the part that genuinely needs a splash. It walks
                # the ladder downward from the highest feasible tier, and
                # the first one that actually loads wins.
                try:
                    cap = probe_machine()
                    state["hw"] = cap
                    target = selected_semantic_tier(wconn)
                    state["tier_target"] = target
                    achieved = 0
                    if target in (1, 2, 3):
                        state["step"] = (f"Loading {SEMANTIC_TIERS[target]['name'].lower()}"
                                         f" \u2014 this is a one-time download\u2026")

                        def cb(msg):
                            state["step"] = msg

                        try:
                            model = _get_embed_model(status_cb=cb)
                            if model is not None:
                                achieved = target
                                # Pre-encode the corpus once, here, so the
                                # first Explorer visit does not pay it.
                                state["step"] = "Indexing the question bank\u2026"
                                try:
                                    get_question_embeddings(model)
                                except Exception:
                                    pass
                            else:
                                demote_tier(target, "model unavailable at startup")
                        except Exception as e:
                            demote_tier(target, f"load failed: {e}")
                    state["tier"] = achieved
                    state["step"] = None
                except Exception:
                    state["tier"] = 0
                    state["step"] = None
                state["live"]["capability"] = state["t"]
            except Exception:
                pass
            finally:
                if wconn is not None:
                    try:
                        wconn.close()
                    except Exception:
                        pass
                state["done"] = True
                # If the splash was dismissed while this thread was still
                # working, anything audio managed to start since must go too.
                if not state["audio_wanted"]:
                    try:
                        ambience_stop()
                    except Exception:
                        pass

        # Skip stays available throughout: nobody should be held hostage
        # to a loading animation, however pretty.
        skip = ctk.CTkButton(splash, text="Skip \u2192", width=86, height=26,
                             fg_color=C.NAVY, hover_color=C.NAVY_2,
                             text_color=C.NAVY_3, border_color=C.NAVY_2, border_width=1,
                             corner_radius=13, font=(FONT_BODY, 10),
                             command=lambda: self._finish_startup(force=True))
        skip.place(relx=0.94, rely=0.955, anchor="center")

        # Audio mute, ON THE SPLASH rather than buried in Settings. Someone
        # opening this in an office needs silence in one click, not a
        # menu dive -- and the choice is remembered, so they are never
        # surprised twice.
        def toggle_audio():
            on = get_setting(self.conn, "splash_audio", "on") != "off"
            if on:
                ambience_stop()
                set_setting(self.conn, "splash_audio", "off")
                state["audio"] = False
                audio_btn.configure(text="\u266a off")
            else:
                set_setting(self.conn, "splash_audio", "on")
                state["audio"] = ambience_start()
                audio_btn.configure(text="\u266a on")

        _audio_on = get_setting(self.conn, "splash_audio", "on") != "off"
        audio_btn = ctk.CTkButton(splash, text=("\u266a on" if _audio_on else "\u266a off"),
                                  width=62, height=26,
                                  fg_color=C.NAVY, hover_color=C.NAVY_2,
                                  text_color=C.NAVY_3, border_color=C.NAVY_2,
                                  border_width=1, corner_radius=13,
                                  font=(FONT_BODY, 10), command=toggle_audio)
        audio_btn.place(relx=0.06, rely=0.955, anchor="center")

        # The ENTER control is drawn on the canvas rather than placed as a
        # widget, so it can share the scene's lighting: it fades in on the
        # same eased curve as the subsystem nodes, carries the same brass
        # glow, and breathes with the hub. A flat rectangular button dropped
        # on top would read as a different piece of software.
        state["enter_born"] = None
        state["enter_hot"] = False

        def enter_geom():
            w = max(canvas.winfo_width(), 200)
            h = max(canvas.winfo_height(), 200)
            return w / 2.0, h * 0.930, 138.0, 22.0   # cx, cy, half-width, half-height

        def on_move(ev):
            ex, ey, hw, hh = enter_geom()
            state["enter_hot"] = (state["enter_born"] is not None
                                  and abs(ev.x - ex) <= hw and abs(ev.y - ey) <= hh)
            canvas.configure(cursor="hand2" if state["enter_hot"] else "")

        def on_click(ev):
            ex, ey, hw, hh = enter_geom()
            if state["enter_born"] is not None and abs(ev.x - ex) <= hw and abs(ev.y - ey) <= hh:
                self._finish_startup()

        canvas.bind("<Motion>", on_move)
        canvas.bind("<Button-1>", on_click)

        import threading
        threading.Thread(target=warm, daemon=True).start()
        draw()

        def poll(elapsed=0):
            if not splash.winfo_exists():
                return
            # Players that cannot loop on their own are restarted from here,
            # so the drone lasts exactly as long as the splash and no longer.
            if state["audio"]:
                ambience_tick()
            # Once warming finishes the screen HOLDS, and hands control to
            # the learner via the Enter control, rather than yanking a
            # finished animation away mid-stride. The long ceiling only
            # exists so a pathological model load cannot strand anyone.
            if state["done"] and state["settle_at"] is None:
                state["settle_at"] = state["t"]
            if state["settle_at"] is not None:
                # ~1.6s settle. The Enter control is only born partway
                # through, so the scene visibly calms BEFORE the invitation
                # appears -- the transition leads, the button follows.
                state["tr"] = _ease(min(1.0, (state["t"] - state["settle_at"]) / 48.0))
                if state["tr"] > 0.45 and state["enter_born"] is None:
                    state["enter_born"] = state["t"]
            if elapsed >= 120000:
                self._finish_startup()
                return
            self.after(80, lambda: poll(elapsed + 80))

        self.after(60, lambda: poll(60))

    def _finish_startup(self, force=False):
        # Music must never outlive its screen. The flag goes first so a warm
        # thread still mid-synthesis sees it before it can start a player;
        # the stop covers one that is already running.
        st = getattr(self, "_splash_state", None)
        if st is not None:
            st["audio_wanted"] = False
        try:
            ambience_stop()
        except Exception:
            pass
        if st is not None:
            if st.get("job"):
                try:
                    self.after_cancel(st["job"])
                except Exception:
                    pass
            st["job"] = None
        sp = getattr(self, "_splash", None)
        if sp is not None and sp.winfo_exists():
            sp.destroy()
        self._splash = None
        # V2 lands on the loop. The dashboard is one tab over; the loop is
        # the thing the app is for.
        self.show_view("today")

    def report_callback_exception(self, exc, val, tb):
        """Overrides Tkinter's default behavior of silently printing a
        traceback to a console the user may not even see. Keeps the app
        alive (a bug in one view shouldn't take down the whole window) and
        tells the user plainly that their saved progress isn't at risk --
        every answer is committed to disk the moment it's given, independent
        of whatever screen is currently rendering."""
        import traceback
        traceback.print_exception(exc, val, tb)
        try:
            from tkinter import messagebox
            messagebox.showerror(
                "Something went wrong",
                f"An unexpected error occurred:\n\n{val}\n\n"
                "The app will keep running. Your saved progress is safe -- every "
                "answer is written to disk immediately, not just at the end of a "
                "session. If this keeps happening, restart the app.",
                parent=self)
        except Exception:
            pass

    def _on_close(self):
        # Quitting from the splash itself must not leave a detached audio
        # process playing after the window is gone.
        try:
            ambience_stop()
        except Exception:
            pass
        if self.active_session is not None and not self.active_session.destroyed:
            from tkinter import messagebox
            if not messagebox.askyesno(
                "Quit?",
                "You're in the middle of a session. Quit anyway?\n\n"
                "(Answers you've already submitted are saved -- only the current, "
                "unfinished question and the session summary will be lost.)",
                parent=self):
                return
            # Closing the window is the most common way to abandon a
            # session; it must count as one (session event, unresolved
            # intervention closed) exactly like navigating away does.
            try:
                self.active_session.abandon()
            except Exception:
                pass
        self.destroy()

    def _build_shell(self):
        self.sidebar = ctk.CTkFrame(self, width=232, fg_color=C.NAVY, corner_radius=0)
        self.sidebar.pack(side="left", fill="y")
        self.sidebar.pack_propagate(False)

        head = ctk.CTkFrame(self.sidebar, fg_color="transparent")
        head.pack(fill="x", padx=20, pady=(24, 4))
        ctk.CTkLabel(head, text="LICENSING FILE", font=(FONT_DISPLAY, 19, "bold"),
                     text_color=C.CREAM, anchor="w").pack(anchor="w")
        ctk.CTkLabel(head, text="NJ Salesperson \u00b7 PSI format", font=(FONT_BODY, 11),
                     text_color=C.GOLD_SOFT, anchor="w").pack(anchor="w", pady=(2, 0))

        sep = ctk.CTkFrame(self.sidebar, height=1, fg_color=C.NAVY_2)
        sep.pack(fill="x", padx=20, pady=(14, 6))

        nav_scroll = ctk.CTkScrollableFrame(self.sidebar, fg_color="transparent",
                                             scrollbar_button_color=C.NAVY_2,
                                             scrollbar_button_hover_color=C.BRASS_DARK)
        nav_scroll.pack(fill="both", expand=True, padx=6)
        self._nav_scroll = nav_scroll

        # With 4 groups and 19 items, the nav list previously needed roughly
        # 1000px of vertical space against a 780px default window -- the
        # bottom items (Item Analysis, Content QA, Settings) were reachable
        # by scrolling, but with NO visible cue that scrolling was possible,
        # so the list just looked like it ended after "Timing." Tightened
        # spacing here narrows that gap; the "more below" indicator further
        # down closes it completely by making the remaining overflow visible
        # rather than silent, at any window size.
        for group_label, items in NAV_GROUPS:
            if group_label:
                ctk.CTkLabel(nav_scroll, text=group_label, font=(FONT_BODY, 10, "bold"),
                             text_color=C.BRASS, anchor="w").pack(anchor="w", padx=14, pady=(12, 3))
            for key, label in items:
                btn = ctk.CTkButton(nav_scroll, text="   " + label, anchor="w", fg_color="transparent",
                                     hover_color=C.NAVY_2, text_color=C.CREAM,
                                     font=(FONT_BODY, 13), corner_radius=6, height=30,
                                     cursor="hand2",
                                     command=lambda k=key: self.show_view(k))
                btn.pack(fill="x", padx=8, pady=1)
                self.nav_buttons[key] = btn
        # Author group: collapsed toggle, off the default path (P8).
        hdr = ctk.CTkLabel(nav_scroll, text="\u25b8 Author", font=(FONT_BODY, 10, "bold"),
                           text_color=C.BRASS, anchor="w", cursor="hand2")
        hdr.pack(anchor="w", padx=14, pady=(18, 3))
        holder = ctk.CTkFrame(nav_scroll, fg_color="transparent")
        for key, label in AUTHOR_NAV:
            btn = ctk.CTkButton(holder, text="   " + label, anchor="w", fg_color="transparent",
                                 hover_color=C.NAVY_2, text_color=C.CREAM,
                                 font=(FONT_BODY, 12), corner_radius=6, height=28,
                                 cursor="hand2", command=lambda k=key: self.show_view(k))
            btn.pack(fill="x", padx=8, pady=1)
            self.nav_buttons[key] = btn
        state = {"open": False}
        def _toggle(_e=None):
            state["open"] = not state["open"]
            if state["open"]:
                holder.pack(fill="x", after=hdr)
                hdr.configure(text="\u25be Author")
            else:
                holder.pack_forget()
                hdr.configure(text="\u25b8 Author")
        hdr.bind("<Button-1>", _toggle)

        # "More below" indicator: pinned between the scrollable nav and the
        # footer, shown only when the nav list genuinely has content below
        # the visible viewport. This is the real fix -- tighter spacing and
        # a taller default window both help, but this is what makes the
        # overflow visible instead of silent at ANY window size.
        self._nav_more_indicator = ctk.CTkLabel(
            self.sidebar, text="\u25be  more", font=(FONT_BODY, 10), text_color=C.GOLD_SOFT)

        def _update_nav_more_indicator(*_a):
            try:
                canvas = nav_scroll._parent_canvas
                top, bottom = canvas.yview()
                needs_indicator = bottom < 0.995
            except Exception:
                needs_indicator = False
            if needs_indicator:
                if not self._nav_more_indicator.winfo_ismapped():
                    self._nav_more_indicator.pack(pady=(0, 2))
            else:
                if self._nav_more_indicator.winfo_ismapped():
                    self._nav_more_indicator.pack_forget()

        self._update_nav_more_indicator = _update_nav_more_indicator
        nav_scroll._parent_canvas.bind("<Configure>", _update_nav_more_indicator, add="+")
        nav_scroll.bind("<Configure>", _update_nav_more_indicator, add="+")
        # CTkScrollableFrame doesn't expose a scroll-position callback, so
        # poll cheaply -- this is just a label visibility check, not
        # meaningful work, and only runs while the sidebar exists.
        def _poll_nav_indicator():
            if not self.sidebar.winfo_exists():
                return
            _update_nav_more_indicator()
            self.after(400, _poll_nav_indicator)
        self.after(200, _poll_nav_indicator)

        foot_wrap = ctk.CTkFrame(self.sidebar, fg_color="transparent")
        foot_wrap.pack(fill="x", pady=(6, 12), padx=16)
        ctk.CTkFrame(foot_wrap, height=1, fg_color=C.NAVY_2).pack(fill="x", pady=(0, 8))
        self.sidebar_status = ctk.CTkLabel(foot_wrap, text="", font=(FONT_BODY, 10),
                                            text_color=C.GOLD_SOFT, anchor="w", justify="left")
        self.sidebar_status.pack(anchor="w")
        # The one sentence that tells a nervous learner nothing will be lost
        # has to be readable: GOLD_SOFT on NAVY is ~9.5:1, NAVY_3 was 1.3:1.
        ctk.CTkLabel(foot_wrap, text="Progress saves automatically", font=(FONT_BODY, 10),
                     text_color=C.GOLD_SOFT, anchor="w").pack(anchor="w", pady=(4, 0))

        self.content = ctk.CTkFrame(self, fg_color=C.PAPER, corner_radius=0)
        self.content.pack(side="left", fill="both", expand=True)

        # Global key handling: answering with A-D / 1-4 and advancing with
        # Enter is far faster than reaching for the mouse on every question,
        # and it mirrors how people actually take computer-based exams.
        self.bind_all("<Key>", self._on_global_key)

        self.refresh_sidebar_status()
        self.after(250, _update_nav_more_indicator)


    def refresh_sidebar_status(self):
        """Live counters in the sidebar so the work waiting for you is always
        visible without navigating anywhere."""
        try:
            due = sum(1 for c in FLASHCARDS
                      if card_due_today(get_card_state(self.conn, c["id"])))
            errs = self.conn.execute(
                "SELECT COUNT(*) c FROM error_log WHERE active=1").fetchone()["c"]
            # Spec 7.12: "41 skills solid \u00b7 next session ~14 min". No
            # deficit counters on every screen.
            n_solid, est = session_summary_cached(self.conn)
            bits = [f"{n_solid} skills solid"]
            if est:
                bits.append(f"next session ~{est} min")
            elif self.conn.execute(
                    "SELECT 1 FROM diagnostic_results LIMIT 1").fetchone() is None:
                # Today's only action before a diagnostic exists is the
                # diagnostic itself; name that, not a session nobody is offered.
                bits.append(f"next: diagnostic ~{round(20 * PACE_TARGET_SECONDS / 60)} min")
            self.sidebar_status.configure(text="\n".join(bits))
        except Exception:
            pass

    def _on_global_key(self, event):
        sess = getattr(self, "active_session", None)
        if sess is None or getattr(sess, "destroyed", True):
            return
        try:
            widget = self.focus_get()
        except (tk.TclError, KeyError):
            # focus_get raises when focus sits in a widget Tk knows but
            # Tkinter no longer wraps (a Toplevel mid-teardown); treat that
            # as "not ours" rather than answering a question with it.
            return
        # never hijack typing in a text field: the elaboration box, the
        # tutor follow-up entry, a settings field. CTkTextbox / CTkEntry
        # hand focus to their inner tk.Text / tk.Entry, so the class check
        # catches them; the isinstance walk covers any subclass.
        if widget is not None:
            try:
                if widget.winfo_class() in ("Entry", "Text", "TEntry", "TCombobox", "Spinbox") \
                        or isinstance(widget, (tk.Entry, tk.Text, tk.Spinbox,
                                               ctk.CTkTextbox, ctk.CTkEntry)):
                    return
            except tk.TclError:
                return
        try:
            sess.handle_key(event)
        except Exception:
            pass

    def toast(self, message, kind="info"):
        """Brief, non-blocking confirmation. Saves and background actions
        should acknowledge themselves; silently changing nothing on screen
        leaves the user unsure whether the click registered."""
        colors = {"info": C.NAVY_2, "good": C.FOREST, "warn": C.STAMP}
        if self.toast_after_id:
            try:
                self.after_cancel(self.toast_after_id)
            except Exception:
                pass
            self.toast_after_id = None
        if self.toast_label is not None:
            try:
                self.toast_label.destroy()
            except Exception:
                pass
        lbl = ctk.CTkLabel(self, text=f"  {message}  ", font=(FONT_BODY, 12, "bold"),
                           text_color=C.CREAM, fg_color=colors.get(kind, C.NAVY_2),
                           corner_radius=9, height=40)
        lbl.place(relx=0.5, rely=0.95, anchor="center")
        lbl.lift()
        self.toast_label = lbl

        def clear():
            if lbl.winfo_exists():
                lbl.destroy()
            self.toast_label = None
            self.toast_after_id = None

        self.toast_after_id = self.after(2400, clear)

    def show_view(self, key):
        if self.active_session is not None and not self.active_session.destroyed:
            from tkinter import messagebox
            if not messagebox.askyesno(
                "Leave this session?",
                "You're in the middle of a session. Leaving now will end it early.\n\n"
                "(Answers you've already submitted are saved -- only the current, "
                "unfinished question and the session summary will be lost.)",
                parent=self):
                return
            self.active_session.abandon()

        # "You are here": a Workshop tool keeps Workshop lit, a ladder rung
        # keeps the Ladder lit, and the learner's Settings subset belongs to
        # Today -- otherwise every drill-down cleared the sidebar highlight.
        lit = NAV_HIGHLIGHT.get(key, key)
        for k, btn in self.nav_buttons.items():
            active = (k == lit)
            btn.configure(fg_color=(C.BRASS if active else "transparent"),
                         text_color=(C.INK if active else C.CREAM),
                         hover_color=(C.BRASS_DARK if active else C.NAVY_2))
        for w in self.content.winfo_children():
            w.destroy()
        self.current_view = key
        if hasattr(self, "sidebar_status"):
            self.refresh_sidebar_status()
        fn = VIEW_MAP.get(key)
        if fn:
            fn(self, self.content)

# ============================================================================
# DASHBOARD VIEW
# ============================================================================

def view_dashboard(app, parent):
    conn = app.conn
    scroll = ctk.CTkScrollableFrame(parent, fg_color="transparent")
    scroll.pack(fill="both", expand=True, padx=32, pady=28)

    section_title(scroll, "Dashboard", "Where things stand right now.").pack(anchor="w", pady=(0, 18))

    total_attempts = conn.execute("SELECT COUNT(*) c FROM attempts").fetchone()["c"]
    due_today = sum(1 for c in FLASHCARDS if card_due_today(get_card_state(conn, c["id"])))
    checklist = {r["topic_id"]: bool(r["done"]) for r in conn.execute("SELECT topic_id, done FROM checklist").fetchall()}
    done_ct = sum(1 for v in checklist.values() if v)

    chips = ctk.CTkFrame(scroll, fg_color="transparent")
    chips.pack(fill="x", pady=(0, 20))
    if total_attempts > 0:
        theta, mean_score, p_pass = predict_pass_probability(conn)
        pass_color = C.FOREST if p_pass >= 0.7 else (C.BRASS_DARK if p_pass < 0.4 else C.BRASS)
        stat_chip(chips, "Ability (theta)", f"{theta:+.2f}",
                  on_click=lambda: app.show_view("learnermodel"),
                  hint="see the evidence").pack(side="left", padx=(0, 10))
        stat_chip(chips, "Est. exam score", f"{mean_score:.0f}%",
                  on_click=lambda: app.show_view("analytics"),
                  hint="how this is derived").pack(side="left", padx=10)
        stat_chip(chips, "P(pass)", f"{p_pass*100:.0f}%", value_color=pass_color,
                  on_click=lambda: app.show_view("analytics"),
                  hint="readiness detail").pack(side="left", padx=10)
    else:
        stat_chip(chips, "Ability (theta)", "\u2014").pack(side="left", padx=(0, 10))
        stat_chip(chips, "Est. exam score", "\u2014").pack(side="left", padx=10)
        stat_chip(chips, "P(pass)", "\u2014").pack(side="left", padx=10)
    stat_chip(chips, "Cards due", str(due_today),
              on_click=lambda: app.show_view("flashcards"),
              hint="review them").pack(side="left", padx=10)
    stat_chip(chips, "Checklist", f"{done_ct}/{len(TOPICS)}",
              on_click=lambda: app.show_view("checklist"),
              hint="open case file").pack(side="left", padx=(10, 0))

    # ---- Today's plan (session orchestrator) ----
    plan = plan_today(conn)
    plan_card = card(scroll, fg_color=C.NAVY)
    plan_card.pack(fill="x", pady=(0, 20))
    pinner = ctk.CTkFrame(plan_card, fg_color="transparent")
    pinner.pack(fill="x", padx=24, pady=20)
    header_row = ctk.CTkFrame(pinner, fg_color="transparent")
    header_row.pack(fill="x")
    ctk.CTkLabel(header_row, text="Today's plan", font=(FONT_BODY, 10, "bold"),
                 text_color=C.BRASS, anchor="w").pack(side="left")
    if plan["days_left"] is not None:
        dl = plan["days_left"]
        dl_txt = f"{dl} days to exam" if dl >= 0 else "exam date passed"
        ctk.CTkLabel(header_row, text=dl_txt, font=(FONT_BODY, 10, "bold"),
                     text_color=C.GOLD_SOFT, anchor="e").pack(side="right")
    ctk.CTkLabel(pinner, text=plan["headline"], font=(FONT_DISPLAY, 19, "bold"),
                 text_color=C.CREAM, anchor="w", justify="left", wraplength=620).pack(anchor="w", pady=(3, 12))

    # ---- open repair missions ----
    # Both reviews asked for the main study surface to launch the
    # highest-priority mission. Until now a mission could only be found by
    # opening a topic, expanding its skill breakdown, and clicking the right
    # sub-skill -- so most would never be seen, and the delayed gate in
    # particular had no route back to the learner at all.
    try:
        mdue = missions_due_now(conn)
    except Exception:
        mdue = {"repair": [], "delayed": []}

    if mdue["delayed"] or mdue["repair"]:
        mbox = ctk.CTkFrame(pinner, fg_color=C.NAVY_2, corner_radius=8)
        mbox.pack(fill="x", pady=(0, 14))
        mb = ctk.CTkFrame(mbox, fg_color="transparent")
        mb.pack(fill="x", padx=16, pady=12)

        if mdue["delayed"]:
            st0 = mdue["delayed"][0]
            ctk.CTkLabel(mb, text="A repair is ready to be checked",
                         font=(FONT_BODY, 10, "bold"), text_color=C.GOLD_SOFT,
                         anchor="w").pack(anchor="w")
            lab = SKILLS.get(st0["skill"], {}).get("label", st0["skill"])
            dl = ctk.CTkLabel(
                mb,
                text=(f"{lab} \u2014 you repaired this {st0['age_hours']:.0f} "
                      "hours ago. One item decides whether it held."),
                font=(FONT_BODY, 12), text_color=C.CREAM, anchor="w",
                justify="left")
            dl.pack(anchor="w", fill="x", pady=(3, 0))
            bind_autowrap(dl, scroll, padding=110)

            def _delayed(mid=st0["mission_id"]):
                run_delayed_check(app, parent, conn, mid,
                                  on_done=lambda: app.show_view("dashboard"))
            ghost_button(mb, "Take the delayed check", _delayed).pack(
                anchor="w", pady=(8, 0))

        elif mdue["repair"]:
            st0 = mdue["repair"][0]
            ctk.CTkLabel(mb, text="Open repair", font=(FONT_BODY, 10, "bold"),
                         text_color=C.GOLD_SOFT, anchor="w").pack(anchor="w")
            rl = ctk.CTkLabel(mb, text=st0["target"], font=(FONT_BODY, 12),
                              text_color=C.CREAM, anchor="w", justify="left")
            rl.pack(anchor="w", fill="x", pady=(3, 0))
            bind_autowrap(rl, scroll, padding=110)
            # The five things a learner needs before committing to a task:
            # why this one, how long, what counts as done, and what is
            # deliberately not available yet. Without the last, a gate that
            # cannot be earned today reads as a broken button.
            reason = {"prerequisite_repair":
                      "chosen because the skill underneath this one is failing",
                      "misconception_repair":
                      "chosen because your wrong answers cluster on one option",
                      "confusable_contrast":
                      "chosen because two items here are marked confusable",
                      "transfer_verification":
                      "chosen because your variant scores lag your seed scores",
                      }.get(st0["kind"], "chosen by the mission compiler")
            immediate = [x for x in st0["outstanding"] if x != "delayed"]
            mins = max(3, 2 * len(immediate) + 2)
            # NAVY_3 on NAVY_2 is unreadable -- the same contrast mistake
            # already fixed once on the stat chips. Anything meant to be read
            # on this panel needs GOLD_SOFT or brighter.
            for line, col in (
                    (f"Why this one: {reason}.", C.GOLD_SOFT),
                    (f"About {mins} minutes now.", C.GOLD_SOFT),
                    ("Proof required: " + (", ".join(immediate) or "none left"),
                     C.CREAM),
                    ("Later: the delayed check, which cannot be taken today "
                     "\u2014 that is what makes it evidence of retention."
                     if "delayed" in st0["outstanding"] else
                     "The delayed check is already passed.", C.GOLD_SOFT)):
                ll = ctk.CTkLabel(mb, text=line, font=(FONT_BODY, 10),
                                  text_color=col, anchor="w", justify="left")
                ll.pack(anchor="w", pady=(3, 0))
                bind_autowrap(ll, scroll, padding=110)

            def _repair(mid=st0["mission_id"]):
                run_mission(app, parent, conn, mid,
                            on_done=lambda: app.show_view("dashboard"))
            brow2 = ctk.CTkFrame(mb, fg_color="transparent", height=0)
            brow2.pack(anchor="w", pady=(10, 0))
            primary_button(brow2, "Continue the repair", _repair).pack(side="left",
                                                                       padx=(0, 8))
            ghost_button(brow2, "Open the Learning Lab",
                         lambda: app.show_view("learninglab")).pack(side="left")

    # ---- the uncertainty cut ----
    # The graph's answer to "what would actually RESOLVE the current
    # uncertainty" -- which is not always another question. Shown only when
    # it disagrees with ordinary practice, because a banner that says
    # "carry on as normal" every day is noise.
    try:
        cut = next_uncertainty_cut(conn)
    except Exception:
        cut = None
    if cut and cut.get("unit") != "item":
        cut_col = {"content_repair": C.STAMP,
                   "prerequisite_drill": C.GOLD_SOFT,
                   "contrast_pair": C.GOLD_SOFT,
                   "transfer_variant": C.GOLD_SOFT}.get(cut["unit"], C.GOLD_SOFT)
        cutbox = ctk.CTkFrame(pinner, fg_color=C.NAVY_2, corner_radius=8)
        cutbox.pack(fill="x", pady=(0, 14))
        cb = ctk.CTkFrame(cutbox, fg_color="transparent")
        cb.pack(fill="x", padx=16, pady=12)
        label = {"content_repair": "The bank cannot answer this one",
                 "prerequisite_drill": "Fix the upstream cause first",
                 "contrast_pair": "Two items you are confusing",
                 "transfer_variant": "Check this is learned, not memorised"}.get(
                     cut["unit"], "Suggested next step")
        ctk.CTkLabel(cb, text=label, font=(FONT_BODY, 10, "bold"),
                     text_color=cut_col, anchor="w").pack(anchor="w")
        wl = ctk.CTkLabel(cb, text=cut["why"], font=(FONT_BODY, 12),
                          text_color=C.CREAM, anchor="w", justify="left")
        wl.pack(anchor="w", fill="x", pady=(3, 0))
        bind_autowrap(wl, scroll, padding=110)
        if cut.get("provenance") == "inferred":
            # pady bottom was 0, so this caption sat flush against the box
            # edge and rendered clipped.
            ctk.CTkLabel(cb, text="Inferred from your own results, not authored "
                                  "\u2014 treat it as a hint.",
                         font=(FONT_BODY, 9), text_color=C.GOLD_SOFT,
                         anchor="w").pack(anchor="w", pady=(6, 4))
        if cut["unit"] == "contrast_pair" and cut.get("items"):
            def drill_pair(items=cut["items"]):
                qs = [QUIZ_BANK[i] for i in items if i in QUIZ_BANK]
                if qs:
                    QuestionSession(app, parent, qs, "quiz",
                                    "Contrast pair",
                                    "Two items the bank marks as confusable, "
                                    "served back to back.",
                                    allow_hints=True, collect_diagnostics=True,
                                    on_finish=lambda s: app.show_view("dashboard"))
            ghost_button(cb, "Drill this pair", drill_pair).pack(anchor="w", pady=(8, 0))
        elif cut["unit"] == "content_repair":
            ghost_button(cb, "See what needs authoring",
                         lambda: app.show_view("contentqa")).pack(anchor="w", pady=(8, 0))

    total_min = sum(b["minutes"] for b in plan["blocks"])
    for b in plan["blocks"]:
        brow = ctk.CTkFrame(pinner, fg_color=C.NAVY_2, corner_radius=8)
        brow.pack(fill="x", pady=3)
        bi = ctk.CTkFrame(brow, fg_color="transparent")
        bi.pack(fill="x", padx=14, pady=10)
        left = ctk.CTkFrame(bi, fg_color="transparent")
        left.pack(side="left", fill="x", expand=True)
        ctk.CTkLabel(left, text=b["title"], font=(FONT_BODY, 13, "bold"), text_color=C.CREAM,
                     anchor="w").pack(anchor="w")
        ctk.CTkLabel(left, text=b["detail"], font=(FONT_BODY, 11), text_color=C.GOLD_SOFT,
                     anchor="w", justify="left", wraplength=440).pack(anchor="w", pady=(1, 0))
        ctk.CTkLabel(bi, text=f"~{b['minutes']}m", font=(FONT_MONO, 11), text_color=C.GOLD_SOFT,
                     width=48).pack(side="left", padx=(8, 6))
        ghost_button_dark(bi, "Start", lambda v=b["view"]: app.show_view(v), width=68).pack(side="left")

    ctk.CTkLabel(pinner, text=f"Total: about {total_min} minutes", font=(FONT_BODY, 11),
                 text_color=C.GOLD_SOFT, anchor="w").pack(anchor="w", pady=(10, 0))

    # Recommended focus card
    frag = all_topic_fragility(conn)
    ranked = sorted(frag.items(), key=lambda kv: kv[1]["score"], reverse=True)
    studied_ranked = [x for x in ranked if x[1]["n"] > 0]


    # Fragility mini list
    if studied_ranked:
        ctk.CTkLabel(scroll, text="Topic fragility", font=(FONT_DISPLAY, 15, "bold"),
                     text_color=C.INK, anchor="w").pack(anchor="w", pady=(4, 8))
        flist = card(scroll)
        flist.pack(fill="x")
        inner = ctk.CTkFrame(flist, fg_color="transparent")
        inner.pack(fill="x", padx=18, pady=14)
        for tid, f in studied_ranked[:6]:
            t = TOPICS[tid]
            row = ctk.CTkFrame(inner, fg_color="transparent")
            row.pack(fill="x", pady=4)
            ctk.CTkLabel(row, text=t["short"], font=(FONT_BODY, 12), text_color=C.INK,
                         width=170, anchor="w").pack(side="left")
            bar_bg = ctk.CTkFrame(row, fg_color=C.PAPER_LINE, height=10, corner_radius=5)
            bar_bg.pack(side="left", fill="x", expand=True, padx=10)
            bar_bg.pack_propagate(False)
            bar_fill = ctk.CTkFrame(bar_bg, fg_color=frag_color(f["label"]), height=10, corner_radius=5,
                                     width=max(4, int(f["score"] * 2.4)))
            bar_fill.place(x=0, y=0)
            ctk.CTkLabel(row, text=f["label"], font=(FONT_BODY, 11, "bold"),
                         text_color=frag_color(f["label"]), width=80, anchor="e").pack(side="left")

