def view_checklist(app, parent):
    conn = app.conn
    scroll = ctk.CTkScrollableFrame(parent, fg_color="transparent")
    scroll.pack(fill="both", expand=True, padx=32, pady=28)
    section_title(scroll, "Case File", "Topic checklist with live fragility.").pack(anchor="w", pady=(0, 18))

    checklist = {r["topic_id"]: bool(r["done"]) for r in conn.execute("SELECT topic_id, done FROM checklist").fetchall()}
    frag = all_topic_fragility(conn)
    ordered = sorted(TOPICS.values(), key=lambda t: (GROUP_ORDER.get(t["group"], 9), t["id"]))

    def toggle(tid, var):
        new_val = var.get()
        conn.execute("""INSERT INTO checklist (topic_id, done) VALUES (?,?)
                         ON CONFLICT(topic_id) DO UPDATE SET done=excluded.done""", (tid, 1 if new_val else 0))
        conn.commit()

    current_group = None
    for t in ordered:
        if t["group"] != current_group:
            current_group = t["group"]
            label = "National Portion (80 questions on real exam)" if current_group == "National" \
                else "New Jersey Portion (30 questions on real exam)"
            ctk.CTkLabel(scroll, text=label, font=(FONT_BODY, 11, "bold"), text_color=C.BRASS_DARK,
                         anchor="w").pack(anchor="w", pady=(16, 6))
        row = card(scroll)
        row.pack(fill="x", pady=3)
        inner = ctk.CTkFrame(row, fg_color="transparent")
        inner.pack(fill="x", padx=14, pady=6)
        var = tk.BooleanVar(value=checklist.get(t["id"], False))
        cb = ctk.CTkCheckBox(inner, text=t["name"], variable=var, font=(FONT_BODY, 13),
                              text_color=C.INK, fg_color=C.BRASS, hover_color=C.BRASS_DARK,
                              checkmark_color=C.PAPER, border_color=C.INK_DIM,
                              command=lambda tid=t["id"], v=var: toggle(tid, v))
        cb.pack(side="left")
        f = frag[t["id"]]
        tag_text = f["label"] if f["n"] else "Unstudied"
        ctk.CTkLabel(inner, text=tag_text, font=(FONT_BODY, 11, "bold"),
                     text_color=frag_color(tag_text)).pack(side="right")
        skill_breakdown_panel(row, conn, t["id"], wrap_target=scroll,
                              toggle_host=inner, app=app)

# ============================================================================
# STUDY NOTES VIEW
# ============================================================================

def _split_note_paragraphs(text, max_sentences=3):
    """The notes are authored as one dense block per topic. Reading a
    1,000-character wall is miserable, so break it into short paragraphs at
    sentence boundaries -- without inventing or reordering any content."""
    parts = re.split(r"(?<=[.!?])\s+", text.strip())
    paras, buf = [], []
    for s in parts:
        buf.append(s)
        if len(buf) >= max_sentences:
            paras.append(" ".join(buf))
            buf = []
    if buf:
        paras.append(" ".join(buf))
    return paras


# ============================================================================
# STUDY-NOTES DIAGRAMS -- dual coding for the topics whose content is
# structural rather than propositional
# ============================================================================
# Paivio (1986) dual coding; Mayer (2009) multimedia principles: a picture
# beside prose earns its place only when it carries the STRUCTURE the prose
# describes -- what contains what, what comes before what, which way a duty
# points. Every diagram below is drawn from this bank's own note text and
# item explanations, never from outside recall: a decorative picture is
# merely wasted, but a picture that asserts something the bank does not
# teaches the wrong fact, which is worse than no picture at all.
#
# Layout is measured, never fixed. Each helper draws its text first, asks
# the canvas where that text actually landed, and only then places the box
# around it, so no label can overlap another or run off the edge at any
# window width. Nothing here uses hard-coded pixel coordinates: everything
# is a fraction of the width the canvas really got.

# The reader's UI scale ("Larger" in Settings) applies to CTk widgets, not
# to a plain tk.Canvas, so a diagram would stay small next to note text that
# had grown. The renderer publishes the live scale here rather than
# threading it through every draw signature; layout is measured, so a bigger
# font simply makes a box taller, never makes it overflow.
_DG_SCALE = 1.0

def _dg_u(width):
    """Scale factor from the canvas's real width. The diagrams are laid out
    against a 700-px reference and clamped, so text stays legible at the
    app's 1040-px minimum window without ballooning on a wide one."""
    return max(0.82, min(1.20, width / 700.0)) * _DG_SCALE

def _dg_font(u, size, bold=False):
    px = max(8, int(round(size * u)))
    return (FONT_BODY, px, "bold") if bold else (FONT_BODY, px)

def _dg_text(cv, x, y, s, u, size=10, color=None, bold=False, wrap=None,
             anchor="nw", justify="left"):
    """One text item, anchored north-west so a measured flow layout can
    stack items by their real bottoms. Returns the item id."""
    return cv.create_text(x, y, text=s, anchor=anchor, justify=justify,
                          font=_dg_font(u, size, bold), fill=color or C.INK,
                          width=int(max(24, wrap)) if wrap else 0)

def _dg_round(cv, x0, y0, x1, y1, r=6, **kw):
    """A rounded rectangle; tk.Canvas has no such primitive, and square
    corners read as a table rather than as the app's cards."""
    r = max(1.0, min(r, (x1 - x0) / 2.0, (y1 - y0) / 2.0))
    pts = [x0 + r, y0, x1 - r, y0, x1, y0, x1, y0 + r,
           x1, y1 - r, x1, y1, x1 - r, y1, x0 + r, y1,
           x0, y1, x0, y1 - r, x0, y0 + r, x0, y0]
    return cv.create_polygon(pts, smooth=True, **kw)

def _dg_panel(cv, x, y, w, u, title=None, lines=(), fill=C.PAPER_DIM,
              border=C.PAPER_LINE, title_color=C.NAVY, body_color=C.INK,
              size=9.5, title_size=None, pad=None, gap=3.0):
    """A titled box whose height is whatever its wrapped text needs.
    Returns the bottom y."""
    pad = 9 * u if pad is None else pad
    inner = w - 2 * pad
    ty = y + pad
    if title:
        i = _dg_text(cv, x + pad, ty, title, u, size=title_size or (size + 0.5),
                     bold=True, color=title_color, wrap=inner)
        ty = cv.bbox(i)[3] + 4 * u
    for ln in lines:
        i = _dg_text(cv, x + pad, ty, ln, u, size=size, color=body_color, wrap=inner)
        ty = cv.bbox(i)[3] + gap * u
    bottom = ty - (gap * u if lines else 0) + pad
    rect = _dg_round(cv, x, y, x + w, bottom, r=6 * u, fill=fill,
                     outline=border, width=1)
    cv.tag_lower(rect)
    return bottom

def _dg_chips(cv, x, y, w, u, labels, size=8.5, fill=C.PAPER,
              border=C.BRASS, color=C.INK):
    """A wrapping row of small labelled chips. A chip that would cross the
    right edge is moved down a row after it has been measured."""
    gap = 5 * u
    cx, cy, row_h = x, y, 0.0
    for lb in labels:
        i = _dg_text(cv, cx + 7 * u, cy + 3.5 * u, lb, u, size=size, color=color)
        b = cv.bbox(i)
        cw = (b[2] - cx) + 7 * u
        if cx > x and cx + cw > x + w:
            cv.move(i, x - cx, row_h + gap)
            cy += row_h + gap
            cx = x
            row_h = 0.0
            b = cv.bbox(i)
            cw = (b[2] - cx) + 7 * u
        ch = (b[3] - cy) + 3.5 * u
        r = _dg_round(cv, cx, cy, cx + cw, cy + ch, r=5 * u, fill=fill,
                      outline=border, width=1)
        cv.tag_lower(r, i)
        row_h = max(row_h, ch)
        cx += cw + gap
    return cy + row_h

def _dg_arrow(cv, x0, y0, x1, y1, u, color=C.BRASS_DARK, dash=None, width=1.6):
    return cv.create_line(x0, y0, x1, y1, fill=color, width=max(1, width * u),
                          arrow="last", arrowshape=(9 * u, 11 * u, 3.6 * u),
                          dash=dash)


def _diagram_t1(cv, W):
    """The bundle of rights, and what each lesser estate gives up.
    Content source: the t1 note text (the five rights; fee simple absolute
    as 'complete, indefinite ownership'; life estates measured by a lifetime
    with a remainder or reversion behind them; the four leasehold estates)
    plus the t1 item explanations for remainder vs reversion."""
    u = _dg_u(W)
    pad = 10 * u
    top = 6 * u
    left_w = max(140 * u, (W - 3 * pad) * 0.32)
    rx = pad + left_w + 26 * u
    rw = W - rx - pad

    # --- left: the bundle itself ---
    i = _dg_text(cv, pad + 9 * u, top + 9 * u, "THE BUNDLE OF RIGHTS", u,
                 size=9, bold=True, color=C.BRASS_DARK, wrap=left_w - 18 * u)
    ty = cv.bbox(i)[3] + 6 * u
    for name in ("Possession", "Control", "Exclusion", "Enjoyment", "Disposition"):
        i = _dg_text(cv, pad + 18 * u, ty, name, u, size=9.5, color=C.INK,
                     wrap=left_w - 30 * u)
        b = cv.bbox(i)
        cv.create_line(pad + 11 * u, ty + 2 * u, pad + 11 * u, b[3] - 1 * u,
                       fill=C.BRASS, width=max(2, 2.4 * u))
        ty = b[3] + 5 * u
    left_bottom = ty + 4 * u
    r = _dg_round(cv, pad, top, pad + left_w, left_bottom, r=6 * u,
                  fill=C.PAPER_DIM, outline=C.PAPER_LINE, width=1)
    cv.tag_lower(r)

    # --- right: the estates, widest first ---
    y = top
    y = _dg_panel(cv, rx, y, rw, u, title="Fee simple absolute",
                  lines=["Holds the whole bundle. Complete, indefinite ownership — "
                         "the highest estate."],
                  fill=C.NAVY, border=C.NAVY, title_color=C.GOLD_SOFT,
                  body_color=C.CREAM)
    # the whole bundle IS what the highest estate holds: say it with the line
    _dg_arrow(cv, pad + left_w + 3 * u, (top + y) / 2.0, rx - 3 * u, (top + y) / 2.0, u)
    _dg_arrow(cv, rx + 16 * u, y + 4 * u, rx + 16 * u, y + 20 * u, u)
    i = _dg_text(cv, rx + 28 * u, y + 5 * u, "lesser estates", u, size=8,
                 color=C.INK_DIM)
    y = max(cv.bbox(i)[3], y + 20 * u) + 4 * u

    ind = 14 * u
    y2 = _dg_panel(cv, rx + ind, y, rw - ind, u, title="Life estate",
                   lines=["The bundle, but measured by a lifetime.",
                          "Waiting behind it: a remainder (to a named third party) "
                          "or a reversion (back to the grantor)."],
                   fill=C.PAPER, border=C.BRASS)
    y = y2 + 8 * u

    ind2 = 28 * u
    px, pw = rx + ind2, rw - ind2
    ipad = 9 * u
    i = _dg_text(cv, px + ipad, y + ipad, "Leasehold estates", u, size=10,
                 bold=True, color=C.NAVY, wrap=pw - 2 * ipad)
    ty = cv.bbox(i)[3] + 4 * u
    i = _dg_text(cv, px + ipad, ty,
                 "Possession for a term only — the owner keeps the rest of the bundle.",
                 u, size=9.5, color=C.INK, wrap=pw - 2 * ipad)
    ty = cv.bbox(i)[3] + 5 * u
    ty = _dg_chips(cv, px + ipad, ty, pw - 2 * ipad, u,
                   ["estate for years", "periodic tenancy", "tenancy at will",
                    "tenancy at sufferance"])
    bottom = ty + ipad
    r = _dg_round(cv, px, y, px + pw, bottom, r=6 * u, fill=C.PAPER,
                  outline=C.BRASS, width=1)
    cv.tag_lower(r)
    return max(bottom, left_bottom) + 6 * u


def _diagram_t2(cv, W):
    """How far back each deed's warranty reaches, and where title actually
    passes. Content source: the t2 note text (the four deed types and what
    each warrants; title passes at delivery and acceptance; recording gives
    constructive notice and priority; NJ race-notice, N.J.S.A. 46:26A-12)
    and the t2 item explanations for special warranty and race-notice."""
    u = _dg_u(W)
    pad = 10 * u
    y = 6 * u
    i = _dg_text(cv, pad, y, "How far back the warranty reaches", u, size=10.5,
                 bold=True, color=C.NAVY, wrap=W - 2 * pad)
    y = cv.bbox(i)[3] + 7 * u

    lab_w = max(118 * u, W * 0.27)
    ax0 = pad + lab_w + 10 * u
    ax1 = W - pad
    gx = ax0 + (ax1 - ax0) * 0.60          # where the grantor's own ownership starts

    i = _dg_text(cv, ax0, y, "earlier owners in the chain of title", u, size=8,
                 color=C.INK_DIM, wrap=(gx - ax0) - 8 * u)
    i2 = _dg_text(cv, gx, y, "the grantor's own ownership", u, size=8,
                  color=C.INK_DIM, wrap=(ax1 - gx))
    y = max(cv.bbox(i)[3], cv.bbox(i2)[3]) + 4 * u
    cv.create_line(ax0, y, ax1, y, fill=C.BRASS, width=1)
    for tx in (ax0, gx, ax1):
        cv.create_line(tx, y - 5 * u, tx, y + 5 * u, fill=C.BRASS, width=1)
    y += 10 * u

    bar_h = 15 * u
    rows = [
        ("General warranty", "against defects from all prior owners", "full",
         C.FOREST, C.FOREST),
        ("Special warranty", "only for the grantor's own period of ownership",
         "grantor", C.BRASS, C.BRASS_DARK),
        ("Bargain and sale", "implies title, but warrants nothing", "implied",
         "", C.BRASS_DARK),
        ("Quitclaim", "whatever interest exists, if any — zero warranties",
         "none", "", C.INK_DIM),
    ]
    for name, gloss, kind, fill, edge in rows:
        i = _dg_text(cv, pad, y, name, u, size=9.5, bold=True, color=C.INK,
                     wrap=lab_w)
        b = cv.bbox(i)
        i2 = _dg_text(cv, pad, b[3] + 1 * u, gloss, u, size=8.5, color=C.INK_DIM,
                      wrap=lab_w)
        text_bottom = cv.bbox(i2)[3]
        if kind == "full":
            _dg_round(cv, ax0, y, ax1, y + bar_h, r=4 * u, fill=fill,
                      outline=edge, width=1)
        elif kind == "grantor":
            _dg_round(cv, gx, y, ax1, y + bar_h, r=4 * u, fill=fill,
                      outline=edge, width=1)
        elif kind == "implied":
            _dg_round(cv, gx, y, ax1, y + bar_h, r=4 * u, fill=C.PAPER,
                      outline=edge, width=1)
            cv.create_line(gx + 4 * u, y + bar_h / 2, ax1 - 4 * u, y + bar_h / 2,
                           fill=edge, dash=(3, 3), width=1)
        else:
            cv.create_line(ax0, y + bar_h / 2, ax1, y + bar_h / 2,
                           fill=C.PAPER_LINE, dash=(2, 4), width=1)
            i3 = _dg_text(cv, (ax0 + ax1) / 2, y + bar_h / 2, "nothing warranted", u,
                          size=8.5, color=C.INK_DIM, anchor="center")
            # the dashed rule would otherwise strike through the words
            bb = cv.bbox(i3)
            cv.tag_lower(cv.create_rectangle(bb[0] - 5 * u, bb[1], bb[2] + 5 * u, bb[3],
                                             fill=C.PAPER, outline=""), i3)
        y = max(text_bottom, y + bar_h) + 7 * u

    y += 2 * u
    y = _dg_panel(cv, pad, y, W - 2 * pad, u,
                  title="Recording is not what moves title",
                  lines=["Delivery and acceptance of the deed — title passes here.",
                         "Recording in the county clerk's office — constructive notice "
                         "to the world, and priority.",
                         "NJ is race-notice (N.J.S.A. 46:26A-12): a later purchaser prevails "
                         "only if they took without notice of the earlier conveyance AND "
                         "recorded first."],
                  fill=C.PAPER_DIM, border=C.PAPER_LINE)
    return y + 6 * u


def _diagram_t3(cv, W):
    """The three legal-description systems, side by side.
    Content source: the t3 note text (metes and bounds by courses and
    distances from a point of beginning; the rectangular/government survey
    system of townships, ranges and sections; lot-and-block referencing a
    recorded plat; NJ most often uses lot-and-block or metes and bounds)."""
    u = _dg_u(W)
    pad = 10 * u
    gap = 8 * u
    cw = (W - 2 * pad - 2 * gap) / 3.0
    top = 6 * u
    ipad = 8 * u
    # The columns are laid out in passes -- titles, then shapes, then
    # captions -- so the three panels line up even when a narrow window
    # wraps one column's annotation onto two lines. A shape drawn into a
    # band of assumed height is exactly how labels end up on top of it.
    sh = 66 * u

    def note(x, y, w, s, color=C.INK_DIM, anchor="n"):
        return _dg_text(cv, x + w / 2.0, y, s, u, size=7.5, color=color,
                        anchor=anchor, justify="center", wrap=w)

    def fig_metes(x, y, w):
        sy = cv.bbox(note(x, y, w, "the boundary, course by course"))[3] + 3 * u
        pts = [(0.14, 0.80), (0.08, 0.26), (0.54, 0.05), (0.94, 0.36), (0.64, 0.95)]
        poly = []
        for fx, fy in pts:
            poly += [x + fx * w, sy + fy * sh]
        cv.create_polygon(poly, fill=C.PAPER, outline=C.NAVY, width=max(1, 1.4 * u))
        px, py = x + pts[0][0] * w, sy + pts[0][1] * sh
        d = 3.2 * u
        cv.create_oval(px - d, py - d, px + d, py + d, fill=C.BRASS, outline=C.BRASS_DARK)
        cv.create_line(px, py + d, px, sy + sh + 3 * u, fill=C.BRASS_DARK, width=1)
        # one course drawn with its direction: the boundary is run, not just bounded
        _dg_arrow(cv, x + pts[1][0] * w, sy + pts[1][1] * sh,
                  x + pts[2][0] * w, sy + pts[2][1] * sh, u, width=1.2)
        i = note(x, sy + sh + 4 * u, w, "point of beginning", color=C.BRASS_DARK)
        return cv.bbox(i)[3]

    def fig_survey(x, y, w):
        sy = cv.bbox(note(x, y, w, "one township · 36 sections"))[3] + 3 * u
        side = min(w, sh) * 0.98
        gx0 = x + (w - side) / 2.0
        gy0 = sy + (sh - side) / 2.0
        step = side / 6.0
        cv.create_rectangle(gx0, gy0, gx0 + side, gy0 + side, fill=C.PAPER,
                            outline=C.NAVY, width=max(1, 1.4 * u))
        for k in range(1, 6):
            cv.create_line(gx0 + k * step, gy0, gx0 + k * step, gy0 + side,
                           fill=C.PAPER_LINE)
            cv.create_line(gx0, gy0 + k * step, gx0 + side, gy0 + k * step,
                           fill=C.PAPER_LINE)
        cv.create_rectangle(gx0 + 3 * step, gy0 + 2 * step,
                            gx0 + 4 * step, gy0 + 3 * step,
                            fill=C.BRASS, outline=C.BRASS_DARK)
        cv.create_line(gx0 + 3.5 * step, gy0 + side,
                       gx0 + 3.5 * step, sy + sh + 3 * u,
                       fill=C.BRASS_DARK, width=1)
        i = note(x, sy + sh + 4 * u, w, "one section", color=C.BRASS_DARK)
        return cv.bbox(i)[3]

    def fig_lotblock(x, y, w):
        sy = cv.bbox(note(x, y, w, "one block on the recorded plat"))[3] + 3 * u
        bw = w * 0.96
        bh = min(sh * 0.62, 42 * u)
        bx = x + (w - bw) / 2.0
        by = sy + (sh - bh) / 2.0
        cv.create_rectangle(bx, by, bx + bw, by + bh, fill=C.PAPER,
                            outline=C.NAVY, width=max(1, 1.4 * u))
        for k in range(1, 4):
            cv.create_line(bx + k * bw / 4.0, by, bx + k * bw / 4.0, by + bh,
                           fill=C.PAPER_LINE)
        cv.create_rectangle(bx + 2 * bw / 4.0, by, bx + 3 * bw / 4.0, by + bh,
                            fill=C.BRASS, outline=C.BRASS_DARK)
        for k in range(4):
            _dg_text(cv, bx + (k + 0.5) * bw / 4.0, by + bh / 2.0, str(k + 1), u,
                     size=8, color=(C.INK if k != 2 else C.NAVY), anchor="center")
        cv.create_line(bx + 2.5 * bw / 4.0, by + bh,
                       bx + 2.5 * bw / 4.0, sy + sh + 3 * u,
                       fill=C.BRASS_DARK, width=1)
        i = note(x, sy + sh + 4 * u, w, "lot 3 of that block", color=C.BRASS_DARK)
        return cv.bbox(i)[3]

    cols = [
        ("Metes and bounds",
         "Courses and distances run from a point of beginning, back to where they started.",
         fig_metes),
        ("Government survey",
         "The rectangular system: townships and ranges, divided into sections.",
         fig_survey),
        ("Lot and block",
         "A lot and block number, as shown on a recorded subdivision plat.",
         fig_lotblock),
    ]
    xs = [pad + k * (cw + gap) for k in range(3)]
    title_bottoms = [cv.bbox(_dg_text(cv, xs[k] + ipad, top + ipad, cols[k][0], u,
                                      size=9.5, bold=True, color=C.NAVY,
                                      wrap=cw - 2 * ipad))[3] for k in range(3)]
    fy = max(title_bottoms) + 5 * u
    fig_bottom = max(cols[k][2](xs[k] + ipad, fy, cw - 2 * ipad) for k in range(3))
    cap_y = fig_bottom + 5 * u
    cap_bottom = max(cv.bbox(_dg_text(cv, xs[k] + ipad, cap_y, cols[k][1], u,
                                      size=8.5, color=C.INK_DIM,
                                      wrap=cw - 2 * ipad))[3] for k in range(3))
    panel_bottom = cap_bottom + ipad
    for k in range(3):
        cv.tag_lower(_dg_round(cv, xs[k], top, xs[k] + cw, panel_bottom, r=6 * u,
                               fill=C.PAPER_DIM, outline=C.PAPER_LINE, width=1))

    y = panel_bottom + 8 * u
    y = _dg_panel(cv, pad, y, W - 2 * pad, u, title=None,
                  lines=["In New Jersey a residential deed most often uses lot-and-block "
                         "or metes and bounds — not the government survey system."],
                  fill=C.PAPER, border=C.BRASS, body_color=C.INK)
    return y + 6 * u


def _diagram_t6(cv, W):
    """Which way the fiduciary duty points.
    Content source: the t6 note text (OLDCAR; a subagent owes those same
    duties to the original principal, not to the party they work with
    directly; dual agency legal in NJ only with informed written consent
    from both parties; a designated/transaction broker relationship
    provides limited representation without full fiduciary duties)."""
    u = _dg_u(W)
    pad = 10 * u
    top = 6 * u
    # The gaps between the three boxes are where the relationship labels
    # live, so they are sized for the label rather than left over.
    gapx = max(104 * u, W * 0.15)
    cw = (W - 2 * pad - 2 * gapx) / 3.0
    x_sel, x_brk, x_buy = pad, pad + cw + gapx, pad + 2 * (cw + gapx)

    b1 = _dg_panel(cv, x_sel, top, cw, u, title="Seller",
                   lines=["the client (principal)"], fill=C.NAVY, border=C.NAVY,
                   title_color=C.GOLD_SOFT, body_color=C.CREAM)
    b2 = _dg_panel(cv, x_brk, top, cw, u, title="Listing broker",
                   lines=["the agent"], fill=C.PAPER, border=C.BRASS)
    b3 = _dg_panel(cv, x_buy, top, cw, u, title="Buyer",
                   lines=["a customer here"], fill=C.PAPER_DIM,
                   border=C.PAPER_LINE, title_color=C.INK)
    row_bottom = max(b1, b2, b3)
    mid = top + (row_bottom - top) * 0.55

    _dg_arrow(cv, x_brk - 6 * u, mid, x_sel + cw + 6 * u, mid, u)
    i = _dg_text(cv, x_sel + cw + gapx / 2.0, mid - 6 * u,
                 "fiduciary duties\nOLDCAR", u, size=8, color=C.BRASS_DARK,
                 anchor="s", justify="center", wrap=gapx - 6 * u)
    cv.itemconfigure(i, justify="center")
    cv.create_line(x_brk + cw + 6 * u, mid, x_buy - 6 * u, mid,
                   fill=C.INK_DIM, dash=(3, 3), width=1)
    i = _dg_text(cv, x_brk + cw + gapx / 2.0, mid - 6 * u,
                 "works with —\nno fiduciary duty", u, size=8, color=C.INK_DIM,
                 anchor="s", justify="center", wrap=gapx - 6 * u)
    cv.itemconfigure(i, justify="center")

    # The subagent hangs off the listing broker, and its duty runs the same
    # way: the elbow carries no label of its own, because the claim belongs
    # inside the box where it cannot collide with anything.
    y = row_bottom + 22 * u
    sub_w = W - pad - x_brk
    sub_bottom = _dg_panel(cv, x_brk, y, sub_w, u, title="Subagent",
                           lines=["extends the listing broker's agency",
                                  "— and owes those same duties to the original "
                                  "principal, not to the party they work with"],
                           fill=C.PAPER, border=C.BRASS)
    cv.create_line(x_brk + cw / 2.0, row_bottom, x_brk + cw / 2.0, y,
                   fill=C.PAPER_LINE, width=1)
    _dg_text(cv, x_brk + cw / 2.0 + 6 * u, row_bottom + 3 * u, "under the broker", u,
             size=8, color=C.INK_DIM)
    sub_mid = y + (sub_bottom - y) * 0.5
    elbow_x = x_sel + cw / 2.0
    cv.create_line(x_brk - 4 * u, sub_mid, elbow_x, sub_mid,
                   fill=C.BRASS_DARK, width=max(1, 1.6 * u))
    _dg_arrow(cv, elbow_x, sub_mid, elbow_x, row_bottom + 3 * u, u)
    y = sub_bottom + 10 * u

    half = (W - 2 * pad - 8 * u) / 2.0
    a = _dg_panel(cv, pad, y, half, u, title="Dual agency",
                  lines=["One licensee, both sides. Lawful in NJ only with informed "
                         "written consent from both parties, because it inherently "
                         "limits loyalty and disclosure to either side."],
                  fill=C.PAPER_DIM, border=C.PAPER_LINE)
    b = _dg_panel(cv, pad + half + 8 * u, y, half, u,
                  title="Designated / transaction broker",
                  lines=["A facilitator: limited representation, without the full "
                         "fiduciary duties owed to a client."],
                  fill=C.PAPER_DIM, border=C.PAPER_LINE)
    return max(a, b) + 6 * u


def _diagram_t7(cv, W):
    """Where an offer dies, where the contract begins, and what a
    contingency lets a party out of. Content source: the t7 note text (the
    six requirements including the Statute of Frauds; a counteroffer voids
    the original offer and creates a new offer that must itself be accepted;
    contingencies are conditions precedent that typically give a party an
    exit if unmet)."""
    u = _dg_u(W)
    pad = 10 * u
    top = 6 * u
    gapx = 10 * u
    spine_w = (W - 2 * pad) * 0.56
    side_x = pad + spine_w + gapx
    side_w = W - side_x - pad

    y = top
    offer_bottom = _dg_panel(cv, pad, y, spine_w, u, title="Offer",
                             lines=["made on stated terms"], fill=C.PAPER,
                             border=C.BRASS)
    side_bottom = _dg_panel(cv, side_x, y, side_w, u, title="Counteroffer",
                            lines=["Any change to the terms. The original offer is "
                                   "void, and the counteroffer must itself be accepted."],
                            fill=C.PAPER_DIM, border=C.PAPER_LINE)
    mid = y + (offer_bottom - y) * 0.6
    _dg_arrow(cv, pad + spine_w + 2 * u, mid, side_x - 2 * u, mid, u)
    y = max(offer_bottom, side_bottom) + 4 * u

    i = _dg_text(cv, pad + 28 * u, y + 3 * u, "accepted as made", u, size=8,
                 color=C.INK_DIM)
    _dg_arrow(cv, pad + 16 * u, y + 2 * u, pad + 16 * u, y + 22 * u, u)
    y = max(cv.bbox(i)[3], y + 22 * u) + 4 * u

    y = _dg_panel(cv, pad, y, W - 2 * pad, u, title="Binding contract",
                  lines=["Needs offer, acceptance, consideration, competent parties, "
                         "legal purpose — and, for real estate, writing, to satisfy "
                         "the Statute of Frauds."],
                  fill=C.NAVY, border=C.NAVY, title_color=C.GOLD_SOFT,
                  body_color=C.CREAM)
    y += 3 * u
    _dg_arrow(cv, pad + 16 * u, y, pad + 16 * u, y + 18 * u, u)
    y += 22 * u

    y = _dg_panel(cv, pad, y, W - 2 * pad, u,
                  title="Contingencies — conditions precedent",
                  lines=["financing  ·  inspection  ·  appraisal"],
                  fill=C.PAPER, border=C.BRASS)
    y += 3 * u
    half = (W - 2 * pad - 8 * u) / 2.0
    lx = pad + half * 0.5
    rx = pad + half + 8 * u + half * 0.5
    _dg_arrow(cv, lx, y, lx, y + 20 * u, u, color=C.FOREST)
    _dg_arrow(cv, rx, y, rx, y + 20 * u, u)
    i = _dg_text(cv, lx + 7 * u, y + 4 * u, "met", u, size=8, color=C.FOREST)
    i2 = _dg_text(cv, rx + 7 * u, y + 4 * u, "not met", u, size=8, color=C.BRASS_DARK)
    y = max(cv.bbox(i)[3], cv.bbox(i2)[3], y + 20 * u) + 4 * u

    a = _dg_panel(cv, pad, y, half, u, title=None,
                  lines=["Performance continues toward closing."],
                  fill=C.FOREST_DIM, border=C.FOREST, body_color=C.INK)
    b = _dg_panel(cv, pad + half + 8 * u, y, half, u, title=None,
                  lines=["The protected party typically has an exit, on the terms "
                         "the contract sets."],
                  fill=C.PAPER_DIM, border=C.PAPER_LINE)
    return max(a, b) + 6 * u


def _diagram_t14(cv, W):
    """The attorney-review window: when the clock starts, who can stop the
    contract, and what ends it. Content source: the t14 note text (a
    practice custom from the 1983 consent judgment, not a statute; the
    three-business-day period begins once the contract is fully signed and
    delivered to both parties; either party's attorney may disapprove or
    propose changes with no reason stated; Conley v. Guerrero on notice
    methods; only a licensed NJ attorney may exercise the right)."""
    u = _dg_u(W)
    pad = 10 * u
    top = 6 * u
    start_w = (W - 2 * pad) * 0.34
    arrow_gap = 16 * u
    bar_x = pad + start_w + arrow_gap
    bar_w = W - bar_x - pad

    start_bottom = _dg_panel(cv, pad, top, start_w, u,
                             title="Signed AND delivered",
                             lines=["to both parties — the clock starts here"],
                             fill=C.NAVY, border=C.NAVY, title_color=C.GOLD_SOFT,
                             body_color=C.CREAM)
    i = _dg_text(cv, bar_x, top, "three business days", u, size=8.5,
                 color=C.BRASS_DARK, bold=True)
    bar_top = cv.bbox(i)[3] + 4 * u
    bar_h = 26 * u
    seg = bar_w / 3.0
    for k in range(3):
        _dg_round(cv, bar_x + k * seg + (1.5 * u if k else 0), bar_top,
                  bar_x + (k + 1) * seg - 1.5 * u, bar_top + bar_h, r=4 * u,
                  fill=C.PAPER, outline=C.BRASS, width=1)
        _dg_text(cv, bar_x + (k + 0.5) * seg, bar_top + bar_h / 2.0,
                 f"day {k + 1}", u, size=8.5, color=C.INK, anchor="center")
    mid = bar_top + bar_h / 2.0
    _dg_arrow(cv, pad + start_w + 3 * u, mid, bar_x - 3 * u, mid, u)

    # Both outcomes branch from the END of the window, so the arrows leave
    # the day bar rather than dropping out of the box that starts the clock.
    y = max(start_bottom, bar_top + bar_h) + 8 * u
    half = (W - 2 * pad - 8 * u) / 2.0
    lx = pad + half * 0.5
    rx = pad + half + 8 * u + half * 0.5
    _dg_arrow(cv, bar_x + bar_w * 0.30, bar_top + bar_h + 2 * u, lx, y + 20 * u, u)
    _dg_arrow(cv, bar_x + bar_w * 0.92, bar_top + bar_h + 2 * u, rx, y + 20 * u, u,
              color=C.FOREST)
    y += 24 * u

    a = _dg_panel(cv, pad, y, half, u, title="Disapproved inside the window",
                  lines=["Either party's NJ-licensed attorney may disapprove "
                         "outright or propose changes. No reason need be stated, "
                         "and the contract does not stand as written."],
                  fill=C.PAPER_DIM, border=C.PAPER_LINE)
    b = _dg_panel(cv, pad + half + 8 * u, y, half, u,
                  title="The window closes quietly",
                  lines=["No attorney disapproves within the three business days — "
                         "the contract becomes binding as written."],
                  fill=C.FOREST_DIM, border=C.FOREST, title_color=C.NAVY)
    y = max(a, b) + 8 * u

    y = _dg_panel(cv, pad, y, W - 2 * pad, u, title=None,
                  lines=["Notice may be sent by fax, email, personal delivery, or "
                         "overnight mail with proof of delivery (Conley v. Guerrero, "
                         "2017). Only a licensed New Jersey attorney can exercise the "
                         "right — an unrepresented party must retain counsel to use it."],
                  fill=C.PAPER, border=C.BRASS)
    return y + 6 * u


# topic_id -> (draw function, the one line saying what the picture is FOR).
# A topic that is not in this table is simply text, exactly as before.
TOPIC_DIAGRAMS = {
    "t1":  (_diagram_t1,
            "What the full bundle contains, and what each lesser estate gives up."),
    "t2":  (_diagram_t2,
            "Which promises come with each deed — and why recording is not where "
            "title changes hands."),
    "t3":  (_diagram_t3,
            "What each of the three description systems actually looks like on the ground."),
    "t6":  (_diagram_t6,
            "Which way the fiduciary duty points — what the scenario questions turn on."),
    "t7":  (_diagram_t7,
            "Where an offer dies, where the contract begins, and what a contingency "
            "lets a party out of."),
    "t14": (_diagram_t14,
            "When the three-business-day clock starts, who can stop the contract, "
            "and what ends the window."),
}

TOPIC_DIAGRAM_WINDOW = 4     # measurement rows that make up an occasion's outcome

def score_topic_diagram_occasions(conn):
    """Attach an outcome to each finished topic-diagram occasion: accuracy on
    the next items actually served for that topic after the occasion was
    assigned, counted only from MEASUREMENT rows (a pretest guess or a
    heavily-hinted answer is not evidence either way). The window closes at
    TOPIC_DIAGRAM_WINDOW items or at the topic's next occasion, whichever
    comes first, so the same items can never score two occasions and an
    occasion can never be scored twice -- record_behaviour_outcome keeps the
    first value, and the window here is fixed rather than growing with every
    later render."""
    rows = _safe_query(conn, "SELECT key, assigned_at FROM behaviour_occasions "
                             "WHERE name='topic_diagram' AND outcome IS NULL "
                             "AND assigned_at IS NOT NULL ORDER BY assigned_at ASC", ())
    if not rows:
        return 0
    later = {}
    for r in _safe_query(conn, "SELECT key, assigned_at FROM behaviour_occasions "
                               "WHERE name='topic_diagram' AND assigned_at IS NOT NULL "
                               "ORDER BY assigned_at ASC", ()):
        later.setdefault(str(r["key"]).split(":", 1)[0], []).append(r["assigned_at"])
    scored = 0
    for r in rows:
        key = str(r["key"])
        tid = key.split(":", 1)[0]
        start = r["assigned_at"]
        nxt = next((t for t in later.get(tid, []) if t > start), None)
        where, params = "topic_id=? AND timestamp>?", [tid, start]
        if nxt:
            where += " AND timestamp<?"
            params.append(nxt)
        att = measurement_rows(conn, where, tuple(params), columns="correct",
                               order="id ASC", limit=TOPIC_DIAGRAM_WINDOW)
        if not att:
            continue
        # An open window waits for its full complement; a window the next
        # occasion has already closed is scored on whatever it got.
        if len(att) < TOPIC_DIAGRAM_WINDOW and not nxt:
            continue
        record_behaviour_outcome(conn, "topic_diagram", key,
                                 sum(1 for a in att if a["correct"]) / float(len(att)))
        scored += 1
    return scored


def view_notes(app, parent):
    conn = app.conn
    # Close out any topic-diagram occasions whose items have since been
    # served. Scoring here rather than in the answer path keeps the trial's
    # bookkeeping off the hot loop, and the window it reads is fixed, so a
    # later visit cannot re-score an occasion or move its outcome.
    try:
        score_topic_diagram_occasions(conn)
    except sqlite3.Error as e:
        _audit(conn, "topic_diagram_score_failed", f"{type(e).__name__}: {e}")
    parent.grid_columnconfigure(0, weight=0, minsize=286)
    parent.grid_columnconfigure(1, weight=1)
    parent.grid_rowconfigure(0, weight=1)

    frag = all_topic_fragility(conn)
    checklist = {r["topic_id"]: bool(r["done"])
                 for r in conn.execute("SELECT topic_id, done FROM checklist").fetchall()}
    ordered = sorted(TOPICS.values(), key=lambda t: (GROUP_ORDER.get(t["group"], 9), t["id"]))

    # ---------------- left column: search + filtered topic list ----------------
    left = ctk.CTkFrame(parent, fg_color=C.PAPER_DIM, corner_radius=0)
    left.grid(row=0, column=0, sticky="nsew")
    left.grid_rowconfigure(2, weight=1)

    ctk.CTkLabel(left, text="STUDY NOTES", font=(FONT_BODY, 11, "bold"),
                 text_color=C.BRASS_DARK, anchor="w").grid(row=0, column=0, sticky="w",
                                                            padx=18, pady=(20, 8))
    search_var = tk.StringVar()
    search_entry = styled_entry(left, width=240, font=(FONT_BODY, 12),
                                placeholder_text="Search notes\u2026", textvariable=search_var)
    search_entry.grid(row=1, column=0, padx=16, pady=(0, 10), sticky="ew")

    list_frame = ctk.CTkScrollableFrame(left, fg_color="transparent", width=250,
                                        scrollbar_button_color=C.PAPER_LINE,
                                        scrollbar_button_hover_color=C.BRASS)
    list_frame.grid(row=2, column=0, sticky="nsew", padx=(6, 4), pady=(0, 12))

    state = {"selected": ordered[0]["id"], "buttons": {}}
    # One-shot jump target set by Search's "Open topic notes" button. Read
    # once and cleared immediately so it doesn't override a normal later
    # visit to Notes.
    _focus = get_setting(conn, "notes_focus_topic", "")
    if _focus and _focus in TOPICS:
        state["selected"] = _focus
        set_setting(conn, "notes_focus_topic", "")

    # ---------------- right column ----------------
    right = ctk.CTkFrame(parent, fg_color="transparent")
    right.grid(row=0, column=1, sticky="nsew")
    right.grid_rowconfigure(1, weight=1)
    right.grid_columnconfigure(0, weight=1)

    head = ctk.CTkFrame(right, fg_color="transparent")
    head.grid(row=0, column=0, sticky="ew", padx=32, pady=(26, 0))

    title_lbl = ctk.CTkLabel(head, text="", font=(FONT_DISPLAY, 25, "bold"),
                             text_color=C.INK, anchor="w", justify="left")
    title_lbl.pack(anchor="w", fill="x")
    bind_autowrap(title_lbl, head, padding=8)
    ctk.CTkFrame(head, height=2, width=54, fg_color=C.BRASS, corner_radius=2).pack(anchor="w", pady=(6, 10))

    # Empty CTkFrames default to 200px tall; this one is populated later by
    # render_topic, so it must be pinned or it reserves a blank block.
    meta_row = ctk.CTkFrame(head, fg_color="transparent", height=0)
    meta_row.pack(anchor="w", fill="x", pady=(0, 12))

    focus_row = ctk.CTkFrame(head, fg_color="transparent")
    focus_row.pack(anchor="w", fill="x", pady=(0, 4))

    body_wrap = ctk.CTkFrame(right, fg_color="transparent")
    body_wrap.grid(row=1, column=0, sticky="nsew", padx=32, pady=(0, 24))
    body_wrap.grid_rowconfigure(0, weight=1)
    body_wrap.grid_columnconfigure(0, weight=1)

    # A real Text widget rather than a stack of labels: it gives proper line
    # spacing, paragraph spacing, and inline bolding of key terms, which a
    # CTkLabel simply cannot do.
    # width is in CHARACTERS and defaults to 80: at the "Larger" scale that
    # asks the grid for more than the column can give, and the whole right
    # column then runs off the window edge. It is sized by sticky="nsew".
    text = tk.Text(body_wrap, wrap="word", bg=C.PAPER, fg=C.INK, relief="flat",
                   highlightthickness=0, borderwidth=0, padx=4, pady=4, width=20,
                   spacing1=2, spacing2=5, spacing3=13, cursor="arrow")
    text.grid(row=0, column=0, sticky="nsew")
    tscroll = ctk.CTkScrollbar(body_wrap, command=text.yview,
                               button_color=C.PAPER_LINE, button_hover_color=C.BRASS)
    tscroll.grid(row=0, column=1, sticky="ns", padx=(8, 0))
    text.configure(yscrollcommand=tscroll.set)

    text.tag_configure("body", font=(FONT_BODY, 13), foreground=C.INK, lmargin1=0, lmargin2=0)
    text.tag_configure("term", font=(FONT_BODY, 13, "bold"), foreground=C.BRASS_DARK)
    text.tag_configure("h", font=(FONT_DISPLAY, 14, "bold"), foreground=C.NAVY,
                       spacing1=12, spacing3=6)
    text.tag_configure("kv", font=(FONT_BODY, 12), foreground=C.INK_DIM)

    # ---- the dual-coding diagram, embedded in the note itself ----
    # It lives INSIDE the Text rather than above it so it scrolls with the
    # prose it illustrates and cannot squeeze the note down to a few lines
    # at the app's minimum window height. Its width comes from the Text's
    # real width, and it is redrawn on a debounced <Configure> exactly as
    # the analytics charts are; the binding is made once here, not once per
    # topic, so switching topics cannot pile up handlers.
    diag = {"holder": None, "draw": None, "canvas": None, "caption": None,
            "pending": None}

    def _diag_render():
        cvs, holder = diag["canvas"], diag["holder"]
        if cvs is None or holder is None or not holder.winfo_exists():
            return
        w = max(300, text.winfo_width() - 26)
        cvs.configure(width=w)
        diag["caption"].configure(wraplength=w)
        cvs.delete("all")
        global _DG_SCALE
        try:
            _DG_SCALE = float(get_setting(conn, "ui_scale", "1.0"))
        except (TypeError, ValueError):
            _DG_SCALE = 1.0
        h = int(math.ceil(diag["draw"](cvs, float(w))))
        if int(cvs.cget("height")) != h:
            cvs.configure(height=h)

    def _diag_redraw():
        diag["pending"] = None
        try:
            _diag_render()
        except tk.TclError:
            pass    # the view was torn down mid-debounce

    def _diag_configure(_e=None):
        if diag["pending"] is not None:
            try:
                text.after_cancel(diag["pending"])
            except tk.TclError:
                pass
        diag["pending"] = text.after(60, _diag_redraw)

    text.bind("<Configure>", _diag_configure, add="+")

    def _mount_diagram(spec):
        """Put the canvas and its one-line caption at the top of the note."""
        draw_fn, caption = spec
        holder = tk.Frame(text, bg=C.PAPER, highlightthickness=0, bd=0)
        cvs = tk.Canvas(holder, bg=C.PAPER, highlightthickness=0, bd=0, height=120)
        cvs.pack(fill="x")
        cap = tk.Label(holder, text=caption, bg=C.PAPER, fg=C.INK_DIM,
                       font=(FONT_BODY, 10), anchor="w", justify="left",
                       wraplength=400)
        cap.pack(fill="x", pady=(3, 0))
        diag.update({"holder": holder, "canvas": cvs, "caption": cap,
                     "draw": draw_fn})
        text.window_create("end", window=holder, padx=0, pady=4)
        text.insert("end", "\n", "body")
        text.update_idletasks()
        _diag_render()

    # Learner-facing wording for the topic fragility label. "Solid" is
    # reserved for the skill-level successive-relearning state shown on
    # Today/Progress, and this page carries no red (spec 7.12).
    NOTES_FRAG = {"Solid": ("Steady", C.FOREST), "Developing": ("Building", C.BRASS_DARK),
                  "Fragile": ("Needs work", C.BRASS_DARK)}

    def notes_frag(label):
        return NOTES_FRAG.get(label, (label, C.INK_DIM))

    def _flow_row(parent_):
        """A plain Tk frame for flowing widgets: `place` needs an unscaled
        container whose height this code sets itself."""
        return tk.Frame(parent_, bg=C.PAPER, highlightthickness=0, bd=0)

    def _flow(container, widgets, gap=8):
        """Left-to-right, wrapping to a new row when the container is
        narrower than its widgets -- a packed row just clips at the app's
        minimum width, and grid cannot do it because its columns share
        widths across rows."""
        def relayout(_e=None):
            avail = max(container.winfo_width(), 200)
            x = y = row_h = 0
            for wd in widgets:
                if not wd.winfo_exists():
                    continue
                rw, rh = wd.winfo_reqwidth(), wd.winfo_reqheight()
                if x and x + rw > avail:
                    x = 0
                    y += row_h + 6
                    row_h = 0
                # CTk widgets scale place() coordinates by the UI scale;
                # winfo_* values are real pixels, so undo it here.
                sc = wd._get_widget_scaling() if hasattr(wd, "_get_widget_scaling") else 1.0
                wd.place(x=x / sc, y=y / sc)
                x += rw + gap
                row_h = max(row_h, rh)
            total = y + row_h
            if container.winfo_reqheight() != total:
                container.configure(height=total)
        container.bind("<Configure>", relayout)
        container.after_idle(relayout)

    def _wrap_to_head(label, extra):
        """Wrap a focus-card label to the RIGHT COLUMN's width (head is
        grid-stretched to it) minus the card/inner padding `extra`. The
        generic bind_autowrap measures the label's own parent, which here
        is still shrinking to the column when first measured, and its
        200-logical floor is wider than this column at the minimum window
        on the "Larger" scale."""
        wrap_labels.append((label, extra))
        label.after_idle(_apply_head_wraps)

    wrap_labels = []

    def _apply_head_wraps(_e=None):
        if not head.winfo_exists():
            return          # the view was torn down before a deferred call
        w = head.winfo_width()
        if w <= 40:
            head.after(50, _apply_head_wraps)
            return
        wrap_labels[:] = [(lb, ex) for lb, ex in wrap_labels if lb.winfo_exists()]
        for lb, ex in wrap_labels:
            try:
                scale = lb._get_widget_scaling() or 1.0
            except Exception:
                scale = 1.0
            lb.configure(wraplength=max(80, int((w - ex) / scale)))

    head.bind("<Configure>", _apply_head_wraps, add="+")

    def _declined_pretests():
        try:
            return set(json.loads(get_setting(conn, "notes_pretest_declined", "[]") or "[]"))
        except (TypeError, ValueError):
            return set()

    def _pretest_candidates(tid):
        """Up to two items on this topic's not-started skills, one per
        skill: retrieval attempted before reading is what makes the note
        stick (Richland, Kornell & Kao 2009)."""
        try:
            not_started = set(skill_status(conn)["not_started"])
        except Exception:
            return []
        picks, used = [], set()
        for sid in topic_skill_ids(tid):
            if sid not in not_started:
                continue
            cands = [q for q in items_for_skill(sid) if q["id"] not in used]
            if not cands:
                continue
            q = random.choice(cands)
            used.add(q["id"])
            picks.append({"q": q, "movement": "work", "pretest": True, "retest": False, "skill": sid})
            if len(picks) >= 2:
                break
        return picks

    def render_topic(tid):
        state["selected"] = tid
        t = TOPICS[tid]
        f = frag[tid]

        title_lbl.configure(text=t["name"])
        for w in meta_row.winfo_children():
            w.destroy()

        def pill(parent_, label, color, bg):
            p = ctk.CTkFrame(parent_, fg_color=bg, corner_radius=11, border_width=1,
                             border_color=color)
            ctk.CTkLabel(p, text=label, font=(FONT_BODY, 10, "bold"), text_color=color
                         ).pack(padx=10, pady=3)
            return p

        # Pills flow on their own row and the two actions sit on a second
        # one, so neither the title nor "Mark reviewed" can be pushed off
        # the right edge once a topic has practice data.
        pill_row = _flow_row(meta_row)
        pill_row.pack(anchor="w", fill="x")
        pills = [pill(pill_row, t["group"], C.BRASS_DARK, C.PAPER_DIM)]
        if f["n"]:
            f_txt, f_col = notes_frag(f["label"])
            pills.append(pill(pill_row, f'{f_txt}  \u00b7  {f["accuracy"]}% acc', f_col, C.PAPER_DIM))
            pills.append(pill(pill_row, f'MASTERY {f["mastery"]:.0f}%', C.NAVY, C.PAPER_DIM))
        else:
            pills.append(pill(pill_row, "NOT YET PRACTICED", C.INK_DIM, C.PAPER_DIM))
        _flow(pill_row, pills)
        btn_row = _flow_row(meta_row)
        btn_row.pack(anchor="w", fill="x", pady=(2, 0))

        n_q = sum(1 for q in QUIZ_LIST if q["topic"] == tid)
        cards = [c for c in FLASHCARDS if c["topic"] == tid]

        def drill_topic():
            pool = [q for q in QUIZ_LIST if q["topic"] == tid]
            random.shuffle(pool)
            pool = pool[:12]

            def on_finish(summary):
                render_result_screen(app, parent, summary, lambda: app.show_view("notes"))

            QuestionSession(app, parent, pool, "quiz", f"Drill: {t['short']}",
                            f"{len(pool)} questions from this topic",
                            allow_hints=True, collect_diagnostics=True, on_finish=on_finish)

        def toggle_reviewed():
            newv = not checklist.get(tid, False)
            checklist[tid] = newv
            conn.execute("""INSERT INTO checklist (topic_id, done) VALUES (?,?)
                             ON CONFLICT(topic_id) DO UPDATE SET done=excluded.done""",
                         (tid, 1 if newv else 0))
            conn.commit()
            app.toast("Marked reviewed" if newv else "Marked unreviewed", kind="good")
            rebuild_list()
            render_topic(tid)

        _flow(btn_row, [primary_button(btn_row, f"Drill this topic ({n_q})", drill_topic),
                        ghost_button(btn_row,
                                     "\u2713 Reviewed" if checklist.get(tid) else "Mark reviewed",
                                     toggle_reviewed)])

        for w in focus_row.winfo_children():
            w.destroy()

        # ---- pretest before reading ----
        # A failed retrieval attempt before the note beats reading first
        # (Richland, Kornell & Kao 2009; Kornell, Hays & Bjork 2009). Two
        # items on skills this learner has not started yet, recorded as
        # sanctioned pretest guesses through the composed-plan slot; the
        # retest the session appends is what starts the skills.
        just_tried = None
        raw_jt = get_setting(conn, "notes_just_tried", "")
        if raw_jt:
            try:
                jt = json.loads(raw_jt)
                if jt.get("topic") == tid:
                    just_tried = jt.get("items") or []
            except (TypeError, ValueError):
                pass
            set_setting(conn, "notes_just_tried", "")
        offer = [] if (just_tried is not None or tid in _declined_pretests()
                       or tid in state.setdefault("pretest_seen", set())) \
            else _pretest_candidates(tid)
        if offer:
            pc = card(focus_row, fg_color=C.NAVY)
            pc.pack(fill="x", pady=(0, 10))
            pi = ctk.CTkFrame(pc, fg_color="transparent")
            pi.pack(fill="x", padx=16, pady=12)
            n_off = len(offer)
            pl = ctk.CTkLabel(pi, text=(f"Before you read: try {n_off} quick question{'s' if n_off != 1 else ''} "
                                        "on this topic. Missing them now is fine \u2014 a guess first "
                                        "makes the note stick better than reading first."),
                              font=(FONT_BODY, 12), text_color=C.CREAM, anchor="w", justify="left")
            pl.pack(anchor="w", fill="x")
            _wrap_to_head(pl, 48)
            prow_ = _flow_row(pi)
            prow_.configure(bg=C.NAVY)
            prow_.pack(anchor="w", fill="x", pady=(8, 0))

            def _pretest(items=list(offer)):
                state["pretest_seen"].add(tid)
                plan = {"items": items, "n_items": len(items), "est_minutes": 2,
                        "retest_max": len(items), "focus_topic": tid, "phase": None,
                        "planned_mean_p": None}

                def on_finish(_summary):
                    set_setting(conn, "notes_just_tried",
                                json.dumps({"topic": tid,
                                            "items": [it["q"]["q"] for it in items]}))
                    set_setting(conn, "notes_focus_topic", tid)
                    app.show_view("notes")

                QuestionSession(app, parent, None, "quiz", f"Before you read: {t['short']}",
                                f"{len(items)} quick question{'s' if len(items) != 1 else ''} "
                                "\u2014 a first guess is fine.",
                                allow_hints=False, collect_diagnostics=False,
                                composed_plan=plan, on_finish=on_finish)

            def _read_first():
                state["pretest_seen"].add(tid)
                declined = _declined_pretests()
                declined.add(tid)
                set_setting(conn, "notes_pretest_declined", json.dumps(sorted(declined)))
                render_topic(tid)

            _flow(prow_, [primary_button(prow_, f"Try {n_off} question{'s' if n_off != 1 else ''}", _pretest),
                          ghost_button_dark(prow_, "Read first", _read_first)])

        # ---- what YOU specifically struggle with in this topic ----
        # Reading a note is undirected: you re-read the whole thing because
        # nothing says which part you are actually weak on. The engine
        # already knows -- per-skill DINA mastery, authored confusion pairs,
        # and misconceptions tied to specific items -- and none of it was
        # reaching the one screen where a person is trying to learn the
        # material. This turns the note from a document into a briefing.
        try:
            weak = []
            if len(topic_skill_ids(tid)) >= 2:
                post = dina_topic_posterior(conn, tid)
                if post:
                    weak = sorted(
                        ((s_, m_) for s_, m_ in post["skill_mastery"].items()
                         if m_ < 0.6),
                        key=lambda kv: kv[1])[:3]

            pairs = []
            for pr in (enrichment().get("confusion_pairs") or []):
                a, b = pr.get("a"), pr.get("b")
                if a in QUIZ_BANK and b in QUIZ_BANK \
                        and QUIZ_BANK[a]["topic"] == tid and pr.get("why"):
                    pairs.append(pr["why"])
                if len(pairs) >= 2:
                    break

            missed = _safe_query(conn, """SELECT question_id, COUNT(*) n
                                           FROM attempts
                                          WHERE topic_id=? AND correct=0
                                       GROUP BY question_id
                                       ORDER BY n DESC LIMIT 2""", (tid,))

            if weak or pairs or missed or just_tried:
                fc = card(focus_row, fg_color=C.PAPER_DIM)
                fc.pack(fill="x", pady=(0, 10))
                fi = ctk.CTkFrame(fc, fg_color="transparent")
                fi.pack(fill="x", padx=16, pady=12)
                hl = ctk.CTkLabel(fi, text="Read this with your own gaps in mind",
                                  font=(FONT_BODY, 11, "bold"), text_color=C.BRASS_DARK,
                                  anchor="w", justify="left")
                hl.pack(anchor="w", fill="x")
                _wrap_to_head(hl, 48)

                if just_tried:
                    jl = ctk.CTkLabel(fi, text="   You just tried: " + "  \u00b7  ".join(
                                          s[:90] for s in just_tried),
                                      font=(FONT_BODY, 11), text_color=C.NAVY,
                                      anchor="w", justify="left")
                    jl.pack(anchor="w", fill="x", pady=(2, 2))
                    _wrap_to_head(jl, 48)

                for sid_, m_ in weak:
                    r_ = ctk.CTkFrame(fi, fg_color="transparent", height=0)
                    r_.pack(fill="x", pady=1)
                    # Percentage first, on the right; the skill name takes
                    # what is left and wraps instead of clipping.
                    ctk.CTkLabel(r_, text=f"{m_*100:.0f}%", font=(FONT_MONO, 10),
                                 text_color=C.BRASS_DARK, width=44,
                                 anchor="e").pack(side="right")
                    sl = ctk.CTkLabel(r_, text=f"   {SKILLS.get(sid_, {}).get('label', sid_)}",
                                      font=(FONT_BODY, 11), text_color=C.INK,
                                      anchor="w", justify="left")
                    sl.pack(side="left", fill="x", expand=True)
                    _wrap_to_head(sl, 100)

                for why_ in pairs:
                    wl = ctk.CTkLabel(fi, text="   \u21c4  " + why_,
                                      font=(FONT_BODY, 10), text_color=C.INK_DIM,
                                      anchor="w", justify="left")
                    wl.pack(anchor="w", fill="x")
                    _wrap_to_head(wl, 48)

                for mrow in missed:
                    qq = QUIZ_BANK.get(mrow["question_id"])
                    if not qq:
                        continue
                    # Wrapped to the column it lives in, and no red: a
                    # learner reading up on a weak topic is not helped by
                    # a warning colour on the thing they came to fix.
                    ml_ = ctk.CTkLabel(
                        fi, text=f'   \u2717 missed {mrow["n"]}\u00d7: {qq["q"][:78]}',
                        font=(FONT_BODY, 10), text_color=C.BRASS_DARK,
                        anchor="w", justify="left")
                    ml_.pack(anchor="w", fill="x")
                    _wrap_to_head(ml_, 48)
        except Exception as e:
            _audit(conn, "notes_focus_failed", f"{type(e).__name__}: {e}")

        # ---- body ----
        text.configure(state="normal")
        text.delete("1.0", "end")

        # The diagram is a TRIAL, not a feature: this topic-day occasion is
        # assigned on or off by behaviour_arm, and its outcome is this
        # topic's accuracy on the next items served for it (scored lazily by
        # score_topic_diagram_occasions on a later visit here). Deleting the
        # Text's contents unmaps the embedded window but does not destroy
        # the widget, so the old one goes explicitly.
        old_holder = diag.get("holder")
        if old_holder is not None and old_holder.winfo_exists():
            old_holder.destroy()
        diag.update({"holder": None, "canvas": None, "caption": None, "draw": None})
        spec = TOPIC_DIAGRAMS.get(tid)
        if spec:
            try:
                if behaviour_arm(conn, "topic_diagram",
                                 f"{tid}:{date.today().isoformat()}"):
                    _mount_diagram(spec)
            except (tk.TclError, sqlite3.Error) as e:
                _audit(conn, "topic_diagram_failed", f"{tid} {type(e).__name__}: {e}")

        query = search_var.get().strip().lower()
        terms = sorted({c["term"] for c in cards}, key=len, reverse=True)

        for para in _split_note_paragraphs(t["notes"]):
            start_idx = text.index("end-1c")
            text.insert("end", para + "\n", "body")
            end_idx = text.index("end-1c")
            # bold every key term where it appears, so the vocabulary you are
            # actually tested on stands out from the surrounding prose
            for term in terms:
                pos = start_idx
                while True:
                    pos = text.search(term, pos, stopindex=end_idx, nocase=True)
                    if not pos:
                        break
                    epos = f"{pos}+{len(term)}c"
                    text.tag_add("term", pos, epos)
                    pos = epos

        if t.get("source"):
            text.insert("end", "\nSource\n", "h")
            text.insert("end", t["source"] + "\n", "kv")

        if cards:
            text.insert("end", "\nKey terms in this topic\n", "h")
            for c in cards:
                text.insert("end", f"\u2022 {c['term']} \u2014 ", "term")
                text.insert("end", c["def"] + "\n", "kv")

        # highlight search matches
        if query:
            text.tag_configure("hit", background=C.GOLD_SOFT, foreground=C.INK)
            pos = "1.0"
            while True:
                pos = text.search(query, pos, stopindex="end", nocase=True)
                if not pos:
                    break
                epos = f"{pos}+{len(query)}c"
                text.tag_add("hit", pos, epos)
                pos = epos

        text.configure(state="disabled")
        text.yview_moveto(0)

        for k, b in state["buttons"].items():
            active = (k == tid)
            b.configure(fg_color=(C.PAPER if active else "transparent"),
                        text_color=(C.INK if active else C.INK_DIM))

        # The focus card's labels take their wrap width from a parent that
        # is still shrinking to the column while they are first measured;
        # re-apply once the grid has settled (no window resize fires here).
        def _rewrap():
            if not head.winfo_exists():
                return      # navigated away (parent is app.content and survives)
            fn = getattr(parent.winfo_toplevel(), "_autowrap_apply_all", None)
            if fn:
                fn()
            _apply_head_wraps()
        parent.after(150, _rewrap)

    def rebuild_list():
        for w in list_frame.winfo_children():
            w.destroy()
        state["buttons"] = {}
        query = search_var.get().strip().lower()
        current_group = None
        shown = 0
        for t in ordered:
            if query and query not in t["name"].lower() and query not in t["notes"].lower() \
                    and query not in t["short"].lower():
                continue
            shown += 1
            if t["group"] != current_group:
                current_group = t["group"]
                ctk.CTkLabel(list_frame, text=current_group, font=(FONT_BODY, 10, "bold"),
                             text_color=C.BRASS_DARK, anchor="w").pack(anchor="w", padx=14,
                                                                        pady=(12, 3))
            f = frag[t["id"]]
            row = ctk.CTkFrame(list_frame, fg_color="transparent")
            row.pack(fill="x", padx=6, pady=1)
            dot_color = notes_frag(f["label"])[1] if f["n"] else C.PAPER_LINE
            ctk.CTkFrame(row, width=7, height=7, corner_radius=4,
                         fg_color=dot_color).pack(side="left", padx=(6, 0))
            mark = "\u2713 " if checklist.get(t["id"]) else ""
            b = ctk.CTkButton(row, text=f"  {mark}{t['short']}", anchor="w",
                              fg_color="transparent", hover_color=C.PAPER_LINE,
                              text_color=C.INK_DIM, font=(FONT_BODY, 12),
                              corner_radius=6, height=30, cursor="hand2",
                              command=lambda tid=t["id"]: render_topic(tid))
            b.pack(side="left", fill="x", expand=True)
            state["buttons"][t["id"]] = b
        if shown == 0:
            ctk.CTkLabel(list_frame, text="No topics match that search.",
                         font=(FONT_BODY, 11), text_color=C.INK_DIM,
                         wraplength=200, justify="left").pack(anchor="w", padx=14, pady=14)

    def on_search(*_):
        rebuild_list()
        if state["selected"] in state["buttons"]:
            render_topic(state["selected"])
        elif state["buttons"]:
            render_topic(next(iter(state["buttons"])))

    search_var.trace_add("write", on_search)

    rebuild_list()
    render_topic(state["selected"])


# ============================================================================
# SETTINGS VIEW
