def _settings_exam_date_card(app, wrap, blurb):
    """The exam-date card, shared by Author Settings and the learner's
    'Exam date & display' page so both write the same setting."""
    conn = app.conn
    c1 = card(wrap)
    c1.pack(fill="x", pady=(0, 16))
    inner = ctk.CTkFrame(c1, fg_color="transparent")
    inner.pack(fill="x", padx=20, pady=18)
    ctk.CTkLabel(inner, text="Target exam date", font=(FONT_DISPLAY, 15, "bold"),
                 text_color=C.INK, anchor="w").pack(anchor="w")
    bl = ctk.CTkLabel(inner, text=blurb, font=(FONT_BODY, 11), text_color=C.INK_DIM,
                      anchor="w", justify="left")
    bl.pack(anchor="w", fill="x", pady=(2, 10))
    bind_autowrap(bl, inner, padding=8)
    row = ctk.CTkFrame(inner, fg_color="transparent")
    row.pack(anchor="w")
    current = get_setting(conn, "target_exam_date", "")
    entry = styled_entry(row, placeholder_text="YYYY-MM-DD", width=160, font=(FONT_MONO, 13))
    if current:
        entry.insert(0, current)
    entry.pack(side="left", padx=(0, 10))
    status = ctk.CTkLabel(row, text="", font=(FONT_BODY, 11), text_color=C.FOREST)
    status.pack(side="left")

    def save_date():
        val = entry.get().strip()
        try:
            date.fromisoformat(val)
            set_setting(conn, "target_exam_date", val)
            status.configure(text="Saved.", text_color=C.FOREST)
            app.toast("Exam date saved", kind="good")
        except ValueError:
            status.configure(text="Invalid date format.", text_color=C.STAMP)

    primary_button(row, "Save", save_date).pack(side="left")
    return c1


def _settings_text_size_card(app, wrap):
    conn = app.conn
    c_txt = card(wrap)
    c_txt.pack(fill="x", pady=(0, 16))
    ti = ctk.CTkFrame(c_txt, fg_color="transparent", height=0)
    ti.pack(fill="x", padx=20, pady=18)
    ctk.CTkLabel(ti, text="Text size", font=(FONT_DISPLAY, 15, "bold"),
                 text_color=C.INK, anchor="w").pack(anchor="w")
    ctk.CTkLabel(ti, text="Applies immediately and is remembered. Useful for long timed sessions.",
                 font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w").pack(anchor="w", pady=(2, 10))
    trow = ctk.CTkFrame(ti, fg_color="transparent", height=0)
    trow.pack(anchor="w")
    motion_var = ctk.BooleanVar(value=get_setting(conn, "reduce_motion", "0") == "1")
    ctk.CTkCheckBox(ti, text="Reduce motion (transitions draw their end state at once)",
                    variable=motion_var,
                    command=lambda: set_setting(conn, "reduce_motion", "1" if motion_var.get() else "0")
                    ).pack(anchor="w", pady=(12, 0))
    access_var = ctk.BooleanVar(value=get_setting(conn, "accessible_map", "0") == "1")
    ctk.CTkCheckBox(ti, text="Open the map as a list by default (Alt+L switches any time)",
                    variable=access_var,
                    command=lambda: set_setting(conn, "accessible_map", "1" if access_var.get() else "0")
                    ).pack(anchor="w", pady=(8, 0))
    speak_var = ctk.BooleanVar(value=get_setting(conn, "speak_announcements", "0") == "1")
    ghost_button(ti, "Open the course map for screen readers",
                 lambda: vis_open_web_map(app)).pack(anchor="w", pady=(8, 0))
    ctk.CTkCheckBox(ti, text="Speak map announcements aloud",
                    variable=speak_var,
                    command=lambda: set_setting(conn, "speak_announcements", "1" if speak_var.get() else "0")
                    ).pack(anchor="w", pady=(8, 0))
    cur_scale = get_setting(conn, "ui_scale", "1.0")

    def set_scale(v):
        set_setting(conn, "ui_scale", str(v))
        try:
            ctk.set_widget_scaling(float(v))
            app.toast(f"Text size {int(float(v)*100)}%", kind="good")
        except Exception:
            pass

    for label, val in [("Small", 0.9), ("Normal", 1.0), ("Large", 1.15), ("Larger", 1.3)]:
        b = ghost_button(trow, label, lambda v=val: set_scale(v), width=90)
        if abs(float(cur_scale) - val) < 0.01:
            b.configure(fg_color=C.BRASS, text_color=C.INK)
        b.pack(side="left", padx=(0, 8))
    return c_txt


def view_exam_settings(app, parent):
    """The learner-facing subset of Settings: the one setting the app needs
    from the learner (the exam date) and the one that affects every screen
    (text size). Reached from Today; the Author group keeps the rest."""
    wrap = ctk.CTkFrame(parent, fg_color="transparent")
    wrap.pack(fill="both", expand=True, padx=32, pady=28)
    section_title(wrap, "Exam date & display",
                  "Two settings, both optional. Everything else stays as it is.").pack(anchor="w", fill="x", pady=(0, 20))
    _settings_exam_date_card(
        app, wrap,
        "Lets the app pace your review toward the day, and opens the full 110-question "
        "simulation inside the last 21 days. Leave it blank if you haven't booked yet.")
    _settings_text_size_card(app, wrap)
    ghost_button(wrap, "Back to Today", lambda: app.show_view("today")).pack(anchor="w", pady=(4, 0))


def _settings_gpu_card(app, wrap):
    """Compute fabric: nodes (local server, Vast.ai instances), their models,
    sleep/wake, cost, and the fabric grader's promotion state."""
    conn = app.conn
    c_gpu = card(wrap)
    c_gpu.pack(fill="x", pady=(0, 16))
    gi = ctk.CTkFrame(c_gpu, fg_color="transparent")
    gi.pack(fill="x", padx=20, pady=18)
    ctk.CTkLabel(gi, text="Compute fabric (optional)", font=(FONT_DISPLAY, 15, "bold"),
                 text_color=C.INK, anchor="w").pack(anchor="w")
    ctk.CTkLabel(gi, text=("Connects to GPUs you control: a local server, Vast.ai instances, or "
                 "both. Models of any size, from two different families, strengthen grading, "
                 "tutoring and question review. Idle models sleep and idle Vast instances stop "
                 "themselves. Only the item and your typed answer are sent; your progress never "
                 "leaves this machine."),
                 font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w", justify="left",
                 wraplength=620).pack(anchor="w", pady=(2, 10))

    status = ctk.CTkLabel(gi, text="", font=(FONT_BODY, 11), text_color=C.INK_DIM,
                          anchor="w", justify="left", wraplength=620)
    nodes_box = ctk.CTkFrame(gi, fg_color="transparent")

    def _nodes():
        return _fabric_nodes_from_settings(conn)

    def _save_nodes(nodes):
        set_setting(conn, FABRIC_SETTING_NODES, json.dumps(nodes))

    def _health():
        try:
            return json.loads(get_setting(conn, FABRIC_SETTING_HEALTH, "") or "{}")
        except Exception:
            return {}

    def _describe():
        on = get_setting(conn, GPU_SETTING_ENABLED, "0") == "1"
        cfg = gpu_config(conn)
        if not on:
            return "Off."
        if not cfg:
            return "On, but no node has passed a connection test."
        ok, why = fabric_pair_available(cfg)
        return "On." + ("" if ok else f" Grading and review unavailable: {why}.")

    # --- form -------------------------------------------------------------
    form = ctk.CTkFrame(gi, fg_color="transparent")
    form.pack(anchor="w", fill="x", pady=(0, 6))
    e_name = styled_entry(form, width=110, font=(FONT_MONO, 12), placeholder_text="name")
    e_name.pack(side="left", padx=(0, 6))
    kind_var = ctk.StringVar(value="local")
    ctk.CTkSegmentedButton(form, values=["local", "vast"], variable=kind_var).pack(
        side="left", padx=(0, 6))
    e_ep = styled_entry(form, width=230, font=(FONT_MONO, 12),
                        placeholder_text="http://127.0.0.1:8900")
    e_ep.pack(side="left", padx=(0, 6))
    e_tok = styled_entry(form, width=150, font=(FONT_MONO, 12),
                         placeholder_text="access token", show="\u2022")
    e_tok.pack(side="left")
    form2 = ctk.CTkFrame(gi, fg_color="transparent")
    form2.pack(anchor="w", fill="x", pady=(0, 6))
    e_pri = styled_entry(form2, width=70, font=(FONT_MONO, 12), placeholder_text="priority")
    e_pri.pack(side="left", padx=(0, 6))
    e_cost = styled_entry(form2, width=90, font=(FONT_MONO, 12), placeholder_text="$ / hour")
    e_cost.pack(side="left", padx=(0, 6))
    e_vid = styled_entry(form2, width=130, font=(FONT_MONO, 12),
                         placeholder_text="Vast instance id")
    e_vid.pack(side="left", padx=(0, 6))
    wake_var = ctk.BooleanVar(value=True)
    ctk.CTkCheckBox(form2, text="wake for learner requests", variable=wake_var).pack(
        side="left", padx=(6, 0))

    def save_node():
        name = e_name.get().strip()
        ep = e_ep.get().strip()
        if not name or not ep:
            status.configure(text="A node needs a name and an endpoint.")
            return
        try:
            pri = int(e_pri.get().strip() or (0 if kind_var.get() == "local" else 1))
            cost = float(e_cost.get().strip() or 0.0)
        except ValueError:
            status.configure(text="Priority must be a whole number and cost a number.")
            return
        nodes = [n for n in _nodes() if n["name"] != name]
        nodes.append({"name": name, "kind": kind_var.get(), "endpoint": ep, "priority": pri,
                      "cost_per_hour": cost, "vast_instance_id": e_vid.get().strip(),
                      "wake_on_interactive": bool(wake_var.get())})
        _save_nodes(nodes)
        if e_tok.get().strip():
            secret_set(conn, fabric_token_setting(name), e_tok.get().strip())
        render_nodes()
        status.configure(text=f"Saved {name}. Test it to bring it into the fabric.")

    btns = ctk.CTkFrame(gi, fg_color="transparent")
    btns.pack(anchor="w", fill="x", pady=(0, 8))
    primary_button(btns, "Save node", save_node).pack(side="left", padx=(0, 8))

    # --- Vast key -----------------------------------------------------------
    vrow = ctk.CTkFrame(gi, fg_color="transparent")
    vrow.pack(anchor="w", fill="x", pady=(0, 8))
    e_vkey = styled_entry(vrow, width=300, font=(FONT_MONO, 12),
                          placeholder_text="Vast.ai API key (to start and stop instances)",
                          show="\u2022")
    if secret_get(conn, FABRIC_SETTING_VAST_KEY):
        e_vkey.insert(0, secret_get(conn, FABRIC_SETTING_VAST_KEY))
    e_vkey.pack(side="left", padx=(0, 8))

    def save_vkey():
        secret_set(conn, FABRIC_SETTING_VAST_KEY, e_vkey.get().strip())
        app.toast("Vast key saved" if e_vkey.get().strip() else "Vast key cleared", kind="good")
    ghost_button(vrow, "Save key", save_vkey).pack(side="left")

    # --- worker helper --------------------------------------------------------
    def run_bg(fn, done):
        holder = {}
        import threading
        t = threading.Thread(target=lambda: holder.update(result=fn()), daemon=True)
        t.start()

        def poll():
            if t.is_alive():
                gi.after(250, poll)
                return
            if gi.winfo_exists():
                done(holder.get("result"))
        gi.after(250, poll)

    def test_nodes(names=None):
        nodes = [n for n in _nodes() if names is None or n["name"] in names]
        toks = {n["name"]: (secret_get(conn, fabric_token_setting(n["name"]))
                            or secret_get(conn, GPU_SETTING_TOKEN)) for n in nodes}
        status.configure(text="Testing\u2026")

        def work():
            return {n["name"]: fabric_node_health(n["endpoint"], toks[n["name"]])
                    for n in nodes}

        def done(res):
            health = _health()
            bad = []
            for name, (h, raw, err) in (res or {}).items():
                if raw is not None:
                    health[name] = raw
                else:
                    health.pop(name, None)
                    bad.append(f"{name}: {err}")
            set_setting(conn, FABRIC_SETTING_HEALTH, json.dumps(health))
            if health:
                set_setting(conn, GPU_SETTING_ENABLED, "1")
                reset_tier_failures()
            render_nodes()
            status.configure(text=_describe() + (" Not connected \u2014 " + "; ".join(bad)
                                                 if bad else ""))
        run_bg(work, done)

    def node_action(node, action):
        cfg = gpu_config(conn) or {"nodes": [], "vast_key": ""}
        live = next((n for n in cfg["nodes"] if n["name"] == node["name"]), None)
        if live is None:
            tok = (secret_get(conn, fabric_token_setting(node["name"]))
                   or secret_get(conn, GPU_SETTING_TOKEN))
            live = {**node, "token": tok}
            cfg["vast_key"] = secret_get(conn, FABRIC_SETTING_VAST_KEY)
        status.configure(text=f"{action.capitalize()} {node['name']}\u2026")
        fn = {"wake": lambda: fabric_wake(cfg, live, wait_s=0),
              "sleep": lambda: fabric_sleep(cfg, live),
              "stop": lambda: fabric_sleep(cfg, live, stop_instance=True)}[action]
        run_bg(fn, lambda r: (status.configure(
            text=f"{node['name']}: {action} " + ("sent." if r and r[0] else f"failed: {r and r[1]}")),
            gi.after(1500, lambda: test_nodes([node["name"]]))))

    def remove_node(node):
        _save_nodes([n for n in _nodes() if n["name"] != node["name"]])
        health = _health()
        health.pop(node["name"], None)
        set_setting(conn, FABRIC_SETTING_HEALTH, json.dumps(health))
        render_nodes()

    def render_nodes():
        for w in nodes_box.winfo_children():
            w.destroy()
        health = _health()
        for n in sorted(_nodes(), key=lambda x: int(x.get("priority", 1))):
            row = ctk.CTkFrame(nodes_box, fg_color="transparent")
            row.pack(anchor="w", fill="x", pady=(4, 0))
            h = _normalise_health(health.get(n["name"])) if n["name"] in health else None
            if h:
                models = ", ".join(
                    f"{m.get('model')} ({m.get('family')}"
                    + (f", {m['params_b']}B" if m.get("params_b") else "")
                    + (", asleep" if m.get("asleep") else "") + ")"
                    for m in h["models"] if m.get("model"))
                up_h = (h["node"].get("uptime_s") or 0) / 3600.0
                cost = f" \u00b7 ~${up_h * float(n.get('cost_per_hour') or 0):.2f} since start" \
                    if n.get("cost_per_hour") else ""
                line = f"{n['name']} [{n['kind']}, priority {n.get('priority')}] \u2014 {models}{cost}"
            else:
                line = f"{n['name']} [{n['kind']}] \u2014 not tested"
            ctk.CTkLabel(row, text=line, font=(FONT_BODY, 11), text_color=C.INK,
                         anchor="w", justify="left", wraplength=620).pack(anchor="w")
            br = ctk.CTkFrame(row, fg_color="transparent")
            br.pack(anchor="w")
            ghost_button(br, "Test", lambda x=n: test_nodes([x["name"]])).pack(side="left", padx=(0, 6))
            ghost_button(br, "Wake", lambda x=n: node_action(x, "wake")).pack(side="left", padx=(0, 6))
            ghost_button(br, "Sleep", lambda x=n: node_action(x, "sleep")).pack(side="left", padx=(0, 6))
            if n["kind"] == "vast":
                ghost_button(br, "Stop instance", lambda x=n: node_action(x, "stop")).pack(
                    side="left", padx=(0, 6))
            ghost_button(br, "Remove", lambda x=n: remove_node(x)).pack(side="left")

    ctrl = ctk.CTkFrame(gi, fg_color="transparent")
    ctrl.pack(anchor="w", fill="x", pady=(4, 0))
    primary_button(ctrl, "Test all and turn on", lambda: test_nodes()).pack(side="left", padx=(0, 8))

    def turn_off():
        set_setting(conn, GPU_SETTING_ENABLED, "0")
        status.configure(text=_describe())
    ghost_button(ctrl, "Turn off", turn_off).pack(side="left")
    nodes_box.pack(anchor="w", fill="x", pady=(8, 0))
    status.pack(anchor="w", pady=(8, 0))

    # --- grader promotion ------------------------------------------------------
    grow = ctk.CTkFrame(gi, fg_color="transparent")
    grow.pack(anchor="w", fill="x", pady=(12, 0))
    glabel = ctk.CTkLabel(grow, text="", font=(FONT_BODY, 11), text_color=C.INK_DIM,
                          anchor="w", justify="left", wraplength=620)
    glabel.pack(anchor="w")
    gbtns = ctk.CTkFrame(grow, fg_color="transparent")
    gbtns.pack(anchor="w", pady=(4, 0))

    adj_box = ctk.CTkFrame(grow, fg_color="transparent")

    def _current_pair():
        init_grader_governance_schema(conn)
        row = conn.execute("SELECT judges FROM grader_shadow WHERE gpu_score IS NOT NULL "
                           "ORDER BY id DESC LIMIT 1").fetchone()
        try:
            return tuple(json.loads(row[0])) if row and row[0] else None
        except (TypeError, ValueError):
            return None

    def render_grader():
        for w in gbtns.winfo_children():
            w.destroy()
        init_grader_governance_schema(conn)
        rung = get_setting(conn, GRADER_SETTING_RUNG, "canary") or "canary"
        pair = _current_pair()
        st = grader_promotion_status(conn, pair)
        rep = grader_shadow_report(conn)
        lines = [f"Fabric grader: {rung}"
                 + (f" (judges: {' + '.join(pair)})" if pair else "") + "."]
        lines.append(f"Shadow grades {st['n_shadow']}, abstentions {rep.get('abstained', 0)}.")
        if st["battery"]:
            lines.append("Known-answer battery: " + ", ".join(
                f"{k} {v:.0%}" for k, v in st["battery"].items()) + ".")
        lines.append(f"Human adjudications {st['n_adjudicated']}"
                     + (f", mean error {st['mae_vs_human']:.1f}, bias {st['bias_vs_human']:+.1f}"
                        if st["mae_vs_human"] is not None else "") + ".")
        if rep.get("mean_abs_diff") is not None:
            lines.append(f"Agreement with the local scorer (reported, not decisive): mean "
                         f"difference {rep['mean_abs_diff']:.1f}"
                         + (f", correlation {rep['r']:.2f}" if rep.get("r") is not None else "") + ".")
        if st["reasons"]:
            lines.append("Not yet eligible: " + "; ".join(st["reasons"]) + ".")
        glabel.configure(text=" ".join(lines))

        def run_battery():
            cfg = gpu_config(conn)
            if not cfg:
                status.configure(text="The fabric is not connected.")
                return
            status.configure(text="Running the known-answer battery\u2026")
            run_bg(lambda: run_grader_battery(cfg),
                   lambda res: (store_grader_battery(conn, res or []), render_grader(),
                                status.configure(text=f"Battery finished: {len(res or [])} cases.")))
        ghost_button(gbtns, "Run known-answer battery", run_battery).pack(side="left", padx=(0, 8))
        ghost_button(gbtns, "Adjudicate answers", render_adjudication).pack(side="left", padx=(0, 8))
        if rung == "active":
            ghost_button(gbtns, "Return grader to canary",
                         lambda: (set_setting(conn, GRADER_SETTING_RUNG, "canary"),
                                  _audit(conn, "grader_rung", "active -> canary"),
                                  render_grader())).pack(side="left")
        elif st["eligible"] and pair:
            primary_button(gbtns, "Promote grader to active",
                           lambda: (set_setting(conn, GRADER_SETTING_RUNG, "active"),
                                    set_setting(conn, "grader_active_pair", json.dumps(list(pair))),
                                    _audit(conn, "grader_rung", f"canary -> active {pair}"),
                                    render_grader())).pack(side="left")

    def render_adjudication():
        for w in adj_box.winfo_children():
            w.destroy()
        item = next_unadjudicated_shadow(conn)
        if not adj_box.winfo_ismapped():
            adj_box.pack(anchor="w", fill="x", pady=(8, 0))
        if not item:
            ctk.CTkLabel(adj_box, text="Nothing waiting for adjudication.", font=(FONT_BODY, 11),
                         text_color=C.INK_DIM, anchor="w").pack(anchor="w")
            return
        # Blind: the scores are not shown, so the human grade is independent.
        ctk.CTkLabel(adj_box, text=(f"Term: {item['term']}\nReference: {item['reference']}\n"
                                    f"Answer: {item['learner_text']}"),
                     font=(FONT_BODY, 11), text_color=C.INK, anchor="w", justify="left",
                     wraplength=620).pack(anchor="w")
        row = ctk.CTkFrame(adj_box, fg_color="transparent")
        row.pack(anchor="w", pady=(4, 0))
        e = styled_entry(row, width=90, font=(FONT_MONO, 12), placeholder_text="0-100")
        e.pack(side="left", padx=(0, 8))

        def save():
            try:
                v = float(e.get().strip())
            except ValueError:
                status.configure(text="Enter a score from 0 to 100.")
                return
            record_adjudication(conn, item["id"], v)
            render_grader()
            render_adjudication()
        primary_button(row, "Save and next", save).pack(side="left")

    render_nodes()
    render_grader()
    status.configure(text=_describe())


def view_settings(app, parent):
    conn = app.conn
    wrap = ctk.CTkFrame(parent, fg_color="transparent")
    wrap.pack(fill="both", expand=True, padx=32, pady=28)
    section_title(wrap, "Settings").pack(anchor="w", pady=(0, 12))
    _ai_row = ctk.CTkFrame(wrap, fg_color="transparent")
    _ai_row.pack(anchor="w", pady=(0, 14))
    primary_button(_ai_row, "AI and server", lambda: app.show_view("aisettings")).pack(side="left")
    ghost_button(_ai_row, "Set up AI", lambda: app.show_view("aisetup")).pack(side="left", padx=(8, 0))
    ghost_button(_ai_row, "AI usage", lambda: app.show_view("aiusage")).pack(side="left", padx=(8, 0))
    ghost_button(_ai_row, "Law library", lambda: app.show_view("lawlibrary")).pack(side="left", padx=(8, 0))

    _settings_exam_date_card(app, wrap, "Used for the readiness forecast on the Analytics screen.")

    c1b = card(wrap)
    c1b.pack(fill="x", pady=(0, 16))
    inner1b = ctk.CTkFrame(c1b, fg_color="transparent")
    inner1b.pack(fill="x", padx=20, pady=18)
    ctk.CTkLabel(inner1b, text="Backup", font=(FONT_DISPLAY, 15, "bold"),
                 text_color=C.INK, anchor="w").pack(anchor="w")
    ctk.CTkLabel(inner1b, text="Saves a timestamped copy of your entire progress database -- "
                 "cheap insurance against a corrupted file or an accidental reset.",
                 font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w", justify="left",
                 wraplength=560).pack(anchor="w", pady=(2, 10))
    backup_row = ctk.CTkFrame(inner1b, fg_color="transparent")
    backup_row.pack(anchor="w")
    backup_status = ctk.CTkLabel(backup_row, text="", font=(FONT_BODY, 11), text_color=C.FOREST)

    def do_backup():
        import shutil
        conn.commit()
        stamp = datetime.now().strftime("%Y-%m-%d_%H%M%S")
        backup_path = os.path.join(APP_DIR, f"progress_backup_{stamp}.db")
        try:
            shutil.copy2(DB_PATH, backup_path)
            backup_status.configure(text=f"Saved: {backup_path}", text_color=C.FOREST)
        except Exception as e:
            backup_status.configure(text=f"Backup failed: {e}", text_color=C.STAMP)

    primary_button(backup_row, "Backup Now", do_backup).pack(side="left", padx=(0, 10))
    backup_status.pack(side="left")

    c_api = card(wrap)
    c_api.pack(fill="x", pady=(0, 16))
    ai = ctk.CTkFrame(c_api, fg_color="transparent")
    ai.pack(fill="x", padx=20, pady=18)
    ctk.CTkLabel(ai, text="Claude tutor (optional)", font=(FONT_DISPLAY, 15, "bold"),
                 text_color=C.INK, anchor="w").pack(anchor="w")
    ctk.CTkLabel(ai, text="Adds an \u201cAsk the tutor\u201d button after you answer a question, for a "
                 "Socratic follow-up on what you missed. Requires your own Anthropic API key, stored "
                 "locally on this machine. Calls are made only when you click the button, never "
                 "automatically. Leave blank to keep the app fully offline.",
                 font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w", justify="left",
                 wraplength=620).pack(anchor="w", pady=(2, 10))
    arow = ctk.CTkFrame(ai, fg_color="transparent")
    arow.pack(anchor="w", fill="x")
    existing_key = get_setting(conn, "anthropic_api_key", "")
    key_entry = styled_entry(arow, width=340, font=(FONT_MONO, 12),
                             placeholder_text="sk-ant-...", show="\u2022")
    if existing_key:
        key_entry.insert(0, existing_key)
    key_entry.pack(side="left", padx=(0, 10))
    key_status = ctk.CTkLabel(arow, text=("key saved" if existing_key else ""),
                              font=(FONT_BODY, 11), text_color=C.FOREST)
    key_status.pack(side="left", padx=(8, 0))

    def save_key():
        set_setting(conn, "anthropic_api_key", key_entry.get().strip())
        key_status.configure(text="Saved." if key_entry.get().strip() else "Cleared.",
                             text_color=C.FOREST)
        app.toast("Tutor key saved" if key_entry.get().strip() else "Tutor key cleared",
                  kind="good")

    primary_button(arow, "Save", save_key).pack(side="left")

    _settings_gpu_card(app, wrap)

    _settings_text_size_card(app, wrap)

    c_bak = card(wrap)
    c_bak.pack(fill="x", pady=(0, 16))
    bi = ctk.CTkFrame(c_bak, fg_color="transparent", height=0)
    bi.pack(fill="x", padx=20, pady=18)
    ctk.CTkLabel(bi, text="Backup and restore", font=(FONT_DISPLAY, 15, "bold"),
                 text_color=C.INK, anchor="w").pack(anchor="w")
    bl = ctk.CTkLabel(bi, text=("All your progress lives in a single file on this machine. Export a "
                                "backup before switching computers or if you want a safety copy of "
                                "your review schedule, error log, and calibration history."),
                      font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w", justify="left")
    bl.pack(anchor="w", fill="x", pady=(2, 10))
    bind_autowrap(bl, wrap, padding=70)
    brow = ctk.CTkFrame(bi, fg_color="transparent", height=0)
    brow.pack(anchor="w")
    bstatus = ctk.CTkLabel(bi, text="", font=(FONT_BODY, 11), text_color=C.FOREST,
                           anchor="w", justify="left")

    def do_export():
        try:
            from tkinter import filedialog
            path = filedialog.asksaveasfilename(
                defaultextension=".json", initialfile="nj_trainer_backup.json",
                filetypes=[("Trainer backup", "*.json")])
            if not path:
                return
            n = export_backup(conn, path)
            bstatus.configure(text=f"Exported {n} records to {path}", text_color=C.FOREST)
            app.toast("Backup exported", kind="good")
        except Exception as e:
            bstatus.configure(text=f"Export failed: {e}", text_color=C.STAMP)

    def do_export_csv():
        """Take your own data elsewhere. A JSON backup only restores INTO
        this app; CSV is what lets you analyse it anywhere."""
        try:
            from tkinter import filedialog
            path = filedialog.asksaveasfilename(
                defaultextension=".csv", initialfile="nj_trainer_attempts.csv",
                filetypes=[("CSV", "*.csv")])
            if not path:
                return
            n = export_attempts_csv(conn, path)
            bstatus.configure(text=f"Exported {n} answers to {path}",
                              text_color=C.FOREST)
            app.toast(f"{n} answers exported as CSV", kind="good")
        except Exception as e:
            bstatus.configure(text=f"CSV export failed: {e}", text_color=C.STAMP)

    def do_export_report():
        try:
            from tkinter import filedialog
            path = filedialog.asksaveasfilename(
                defaultextension=".md", initialfile="readiness_report.md",
                filetypes=[("Markdown", "*.md")])
            if not path:
                return
            export_readiness_report(conn, path)
            bstatus.configure(text=f"Readiness report written to {path}",
                              text_color=C.FOREST)
            app.toast("Readiness report exported", kind="good")
        except Exception as e:
            bstatus.configure(text=f"Report export failed: {e}", text_color=C.STAMP)

    def do_export_guide(revision_only=False):
        """Write the full compiled guide. Two flavours: everything, or only
        what is weak -- the second is the version worth printing the week
        before the exam."""
        try:
            from tkinter import filedialog
            name = ("revision_guide.md" if revision_only
                    else "personal_study_guide.md")
            path = filedialog.asksaveasfilename(
                defaultextension=".md", initialfile=name,
                filetypes=[("Markdown", "*.md")])
            if not path:
                return
            bstatus.configure(text="Compiling\u2026", text_color=C.INK_DIM)
            app.update_idletasks()
            st = export_study_guide(conn, path, include_solid=not revision_only)
            bstatus.configure(
                text=(f"{st['words']:,} words \u00b7 {st['skill_sections']} skill "
                      f"sections \u00b7 ~{st['approx_pages']:.0f} pages \u2192 {path}"),
                text_color=C.FOREST)
            app.toast("Study guide compiled.", kind="good")
        except Exception as e:
            bstatus.configure(text=f"Guide export failed: {e}", text_color=C.STAMP)

    def do_import():
        try:
            from tkinter import filedialog
            path = filedialog.askopenfilename(filetypes=[("Trainer backup", "*.json")])
            if not path:
                return
            # import_backup raises (and leaves the DB untouched) if any row
            # fails; what comes back here are only the soft losses.
            n, skipped, problems = import_backup(conn, path, replace=True)
            if skipped or problems:
                detail = problems[0] if problems else ""
                bstatus.configure(
                    text=(f"Restored {n} records, but {skipped} could not be restored. "
                          f"{detail}"),
                    text_color=C.STAMP)
                app.toast("Restore incomplete \u2014 see details", kind="warn")
            else:
                bstatus.configure(text=f"Restored {n} records cleanly. Reopen a view to see it.",
                                  text_color=C.FOREST)
                app.toast("Backup restored", kind="good")
            app.refresh_sidebar_status()
        except ValueError as e:
            # The restore refused the file and rolled back: say so plainly,
            # because the old message ("Restored 0 records") read as success.
            bstatus.configure(
                text=f"Restore failed \u2014 your existing data is untouched. {e}",
                text_color=C.STAMP)
            app.toast("Restore failed \u2014 nothing changed", kind="warn")
        except Exception as e:
            bstatus.configure(text=f"Restore failed: {e}", text_color=C.STAMP)
            app.toast("Restore failed", kind="warn")

    primary_button(brow, "Export backup", do_export).pack(side="left", padx=(0, 8))
    ghost_button(brow, "Answers (CSV)", do_export_csv).pack(side="left", padx=(0, 8))
    ghost_button(brow, "Readiness report", do_export_report).pack(side="left", padx=(0, 8))
    # The guide exports used to live here, which put them a long way from
    # the screen where a person is actually reading a guide, and gave two
    # near-identical names ("Study Guide" the view, "Compile study guide"
    # the button) to different things. They now sit in the Study Guide view
    # beside the page-count controls.
    ghost_button(brow, "Restore from backup", do_import).pack(side="left")
    bstatus.pack(anchor="w", fill="x", pady=(8, 0))

    # ---- Semantic analysis capability ladder ----
    cap = probe_machine()
    cs = card(wrap)
    cs.pack(fill="x", pady=(0, 16))
    ci2 = ctk.CTkFrame(cs, fg_color="transparent")
    ci2.pack(fill="x", padx=20, pady=18)
    ctk.CTkLabel(ci2, text="Semantic analysis quality", font=(FONT_DISPLAY, 15, "bold"),
                text_color=C.INK, anchor="w").pack(anchor="w")
    hw = (f"This machine: {cap['cores']} core(s) \u00b7 {cap['ram_gb']:.1f} GB RAM"
          + (f" \u00b7 GPU {cap['vram_gb']:.0f} GB" if cap["gpu"] else " \u00b7 no GPU detected"))
    ctk.CTkLabel(ci2, text=hw, font=(FONT_MONO, 10), text_color=C.INK_DIM,
                anchor="w").pack(anchor="w", pady=(2, 2))
    cdesc = ctk.CTkLabel(
        ci2,
        text=("Clustering your misses and finding related items can run at several levels. "
              "The app picks the strongest one this machine can sustain and falls back "
              "automatically if one fails, so the feature always works \u2014 stronger tiers "
              "only make it better. You can pin a specific tier if the automatic choice "
              "isn't what you want."),
        font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w", justify="left")
    cdesc.pack(anchor="w", fill="x", pady=(2, 10))
    bind_autowrap(cdesc, wrap, padding=70)

    tier_var = tk.StringVar(value=get_setting(conn, "semantic_tier_pin", "auto") or "auto")

    def save_tier():
        set_setting(conn, "semantic_tier_pin", tier_var.get())
        app.toast("Semantic tier preference saved", kind="good")

    ctk.CTkRadioButton(ci2, text="Automatic \u2014 use the best this machine supports",
                       variable=tier_var, value="auto", font=(FONT_BODY, 12),
                       text_color=C.INK, fg_color=C.BRASS, border_color=C.INK_DIM,
                       command=save_tier).pack(anchor="w", pady=3)
    _tier_rows = tier_report(conn)
    for row in _tier_rows:
        mark = "\u2713 " if row["active"] else ("" if row["feasible"] else "\u2717 ")
        state_txt = "in use now" if row["active"] else (
            "available" if row["feasible"] else row["reason"])
        rb = ctk.CTkRadioButton(
            ci2, text=f"{mark}Tier {row['tier']} \u2014 {row['name']}  ({state_txt})",
            variable=tier_var, value=str(row["tier"]), font=(FONT_BODY, 12),
            text_color=(C.INK if row["feasible"] else C.INK_DIM),
            fg_color=C.BRASS, border_color=C.INK_DIM, command=save_tier)
        rb.pack(anchor="w", pady=3)
        if not row["feasible"]:
            rb.configure(state="disabled")
        det = ctk.CTkLabel(ci2, text="      " + row["quality"], font=(FONT_BODY, 10),
                          text_color=C.INK_DIM, anchor="w", justify="left")
        det.pack(anchor="w", fill="x")
        bind_autowrap(det, wrap, padding=90)
    if any(r.get("demoted") for r in _tier_rows):
        # A tier dropped after a runtime failure this session (a dropped
        # connection, a model that errored). Let the learner try it again
        # without restarting the app.
        def retry_tiers():
            reset_tier_failures()
            app.toast("Tiers reset \u2014 they will be tried again on the next analysis.",
                      kind="good")
            app.show_view("settings")
        ghost_button(ci2, "Retry tiers", retry_tiers).pack(anchor="w", pady=(6, 0))

    c1b = card(wrap)
    c1b.pack(fill="x", pady=(0, 16))
    fi = ctk.CTkFrame(c1b, fg_color="transparent")
    fi.pack(fill="x", padx=20, pady=18)
    ctk.CTkLabel(fi, text="Personalize your spaced-repetition schedule", font=(FONT_DISPLAY, 15, "bold"),
                text_color=C.INK, anchor="w").pack(anchor="w")
    n_reviews = conn.execute("SELECT COUNT(*) c FROM review_log").fetchone()["c"]
    reopt_at = get_setting(conn, "fsrs_reoptimized_at", "")
    reopt_n = get_setting(conn, "fsrs_reoptimized_n", "")
    fdesc = ctk.CTkLabel(
        fi,
        text=(f"FSRS-6 ships with defaults trained on ~700 million reviews from ~10,000 users, "
              f"already accurate for the large majority of learners. Refitting its 21 parameters "
              f"against your own {n_reviews} logged review(s) can sharpen it further -- optional, "
              f"and your schedule works fine on the defaults either way. Needs "
              f"{MIN_REVIEWS_FOR_REOPTIMIZATION}+ logged reviews, and an extra package "
              f"(pip install \"fsrs[optimizer]\") the first time it's used."),
        font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w", justify="left")
    fdesc.pack(anchor="w", fill="x", pady=(2, 10))
    bind_autowrap(fdesc, wrap, padding=70)
    if reopt_at:
        ctk.CTkLabel(fi, text=f"Last personalized {reopt_at[:10]} from {reopt_n} reviews.",
                    font=(FONT_BODY, 10), text_color=C.FOREST, anchor="w").pack(anchor="w", pady=(0, 8))

    fstatus = ctk.CTkLabel(fi, text="", font=(FONT_BODY, 11), text_color=C.INK_DIM,
                           anchor="w", justify="left")

    def run_reoptimize():
        fbtn.configure(state="disabled", text="Re-optimizing\u2026 (may take a few seconds the first time)")
        fstatus.configure(text="")
        result = {}

        def worker():
            # A sqlite3 connection belongs to the thread that created it --
            # `conn` (=app.conn) was created on the main thread and cannot
            # be used here. This exact mistake has been made and fixed
            # before in this app (the Explorer's clustering worker); caught
            # here the same way, by actually running the button through the
            # real UI rather than trusting the code on sight. The worker
            # opens its own short-lived connection instead.
            wconn = None
            try:
                wconn = db_connect()
                params, msg = reoptimize_fsrs_parameters(wconn)
                result["params"], result["msg"] = params, msg
            except Exception as e:
                result["params"], result["msg"] = None, f"Unexpected error: {e}"
            finally:
                if wconn is not None:
                    try:
                        wconn.close()
                    except Exception:
                        pass

        import threading
        threading.Thread(target=worker, daemon=True).start()

        def poll():
            if "msg" not in result:
                app.after(150, poll)
                return
            fbtn.configure(state="normal", text="Re-optimize now")
            color = C.FOREST if result["params"] else C.INK_DIM
            fstatus.configure(text=result["msg"], text_color=color)
            fstatus.pack(anchor="w", fill="x", pady=(4, 0))
            bind_autowrap(fstatus, wrap, padding=70)

        app.after(150, poll)

    fbtn = primary_button(fi, "Re-optimize now", run_reoptimize)
    fbtn.pack(anchor="w")
    if n_reviews < MIN_REVIEWS_FOR_REOPTIMIZATION:
        fbtn.configure(state="disabled")
        fstatus.configure(text=f"Needs {MIN_REVIEWS_FOR_REOPTIMIZATION - n_reviews} more logged "
                               "review(s) first -- keep using Flashcards or Free Recall.")
        fstatus.pack(anchor="w", fill="x", pady=(6, 0))

    c2 = card(wrap, fg_color=C.STAMP_DIM)
    c2.pack(fill="x")
    inner2 = ctk.CTkFrame(c2, fg_color="transparent")
    inner2.pack(fill="x", padx=20, pady=18)
    ctk.CTkLabel(inner2, text="Fresh reinstall", font=(FONT_DISPLAY, 15, "bold"),
                 text_color=C.STAMP, anchor="w").pack(anchor="w")
    reset_desc = ctk.CTkLabel(
        inner2,
        text=("Wipes all progress, mastery, schedules, and settings, then relaunches the "
              "app as if it were freshly installed. A timestamped backup is saved "
              "automatically first, so this is recoverable via Restore above if you change "
              "your mind. Your citation corpus (citations.db, if you built one) is NOT "
              "touched -- that is a separate tool's data."),
        font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w", justify="left")
    reset_desc.pack(anchor="w", fill="x", pady=(2, 10))
    bind_autowrap(reset_desc, wrap, padding=70)

    reset_status = ctk.CTkLabel(inner2, text="", font=(FONT_BODY, 11), text_color=C.INK,
                                anchor="w", justify="left")

    confirm_state = {"armed": False}
    reset_btn = primary_button(inner2, "Fresh Reinstall\u2026", None,
                               fg=C.STAMP, hover="#7f2f2f", text_color="#fff")

    def do_reset():
        if not confirm_state["armed"]:
            confirm_state["armed"] = True
            reset_btn.configure(text="Really wipe everything? Click again to confirm")
            reset_status.configure(
                text="This is your last chance to back out \u2014 nothing has happened yet.",
                text_color=C.STAMP)
            reset_status.pack(anchor="w", fill="x", pady=(6, 0))
            # auto-disarm if they click away/wait, so a stray later click can't
            # trigger the wipe without a fresh, deliberate confirmation
            def disarm():
                confirm_state["armed"] = False
                # The timer outlives the Settings view; the button may not.
                if reset_btn.winfo_exists():
                    reset_btn.configure(text="Fresh Reinstall\u2026")
            app.after(8000, disarm)
            return

        # 1) Safety net: export a timestamped backup before touching anything.
        backup_path = None
        try:
            backup_dir = os.path.join(os.path.expanduser("~"), "Desktop")
            if not os.path.isdir(backup_dir):
                backup_dir = APP_DIR
            stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            backup_path = os.path.join(backup_dir, f"nj_trainer_backup_before_reinstall_{stamp}.json")
            export_backup(conn, backup_path)
        except Exception as e:
            reset_status.configure(text=f"Backup failed ({e}) \u2014 reinstall cancelled, "
                                        "nothing was touched.", text_color=C.STAMP)
            confirm_state["armed"] = False
            reset_btn.configure(text="Fresh Reinstall\u2026")
            return

        # 2) Wipe: close the connection, delete the progress DB and the
        # semantic embedding cache (safe -- it regenerates on next use).
        # The citation corpus is deliberately left alone; it is a separate
        # tool's data that took real bandwidth to build.
        try:
            conn.close()
        except Exception:
            pass
        for fname in ("progress.db", "embeddings_cache.json"):
            fpath = os.path.join(APP_DIR, fname)
            if os.path.exists(fpath):
                try:
                    os.remove(fpath)
                except Exception:
                    pass

        # 3) Relaunch as a brand-new process. An in-place DB swap would still
        # leave stale in-memory state around (cached theta, controller
        # window, loaded models); re-executing the interpreter is what
        # actually gives a truly fresh install rather than a fresh database
        # under an old process.
        try:
            app.destroy()
        except Exception:
            pass
        os.execv(sys.executable, [sys.executable] + sys.argv)

    reset_btn.configure(command=do_reset)
    reset_btn.pack(anchor="w")


# ============================================================================
# QUESTION SESSION -- the shared engine behind Quiz / Adaptive / Diagnostic /
# Progressive / Exam / Error Log drill / Explorer drill. One state machine,
# configured differently per mode, instead of duplicating the flow six times.
# ============================================================================

# Shown only after the reveal, and never in a timed set; a "Hard" stamp in
# red before the learner has answered is a warning label, not information.
DIFF_COLOR = {"easy": C.INK_DIM, "medium": C.INK_DIM, "hard": C.BRASS_DARK}

class QuestionSession:
    def __init__(self, app, parent, questions, record_mode, title, subtitle,
                 allow_hints=False, collect_diagnostics=False, timed=False,
                 total_seconds=None, allow_back=False, dynamic_picker=None,
                 diagnostic_redo=False, elaborate=False, pressure_confidence=False,
                 pre_performance=False, on_finish=None, composed_plan=None,
                 record_fn=None):
        self.app = app
        # `record_fn(q, correct, elapsed, chosen_idx)` replaces the plain
        # record_attempt call for fixed-list sessions whose items are not
        # bank items -- the transfer check's template variants, which must
        # be written the way generalization_gap expects to read them.
        self.record_fn = record_fn
        # Spec 7.4/7.5/7.6: a composed session carries per-item movement and
        # pretest flags; the phase governs ritual depth; the retest queue
        # feeds Movement 3.
        self.composed_plan = composed_plan
        session_context_begin(self)
        if composed_plan:
            questions = [it["q"] for it in composed_plan["items"]]
        self.plan_meta = list(composed_plan["items"]) if composed_plan else []
        try:
            self.phase = learner_phase(app.conn)
        except Exception:
            self.phase = "A"
        self.ctrl_consecutive_wrong = 0
        self.ctrl_action = None
        try:
            self._solid_at_start = skills_solid_count(app.conn)
        except Exception:
            self._solid_at_start = 0
        # Spec 7.6 / P5: EVERY learn-objective session treats the first
        # encounter with a skill as a sanctioned pretest, not only the
        # composed session. Skills are "seen" once any attempt on an item
        # loading them exists (a pretest counts -- the retest is what scores).
        self._seen_skills = set()
        try:
            for r in app.conn.execute("SELECT DISTINCT question_id FROM attempts").fetchall():
                for sid in Q_MATRIX.get(r["question_id"], []):
                    if sid in SKILLS:
                        self._seen_skills.add(sid)
        except Exception:
            pass
        self._dynamic_retest = False
        self._dynamic_retests_served = 0
        self._dynamic_retests_missed = []
        self._retests_added = 0
        self._retests_held = 0
        self._retest_qids = set()
        self._closed_early = False
        self.conn = app.conn
        # Every attempt row this session writes has an id above this mark;
        # the debrief reads them back rather than re-deriving outcomes from
        # the several answer paths (confidence prompt, error tag, redo tag).
        try:
            self._attempt_id_at_start = int(
                self.conn.execute("SELECT COALESCE(MAX(id), 0) m FROM attempts").fetchone()["m"])
        except sqlite3.Error:
            self._attempt_id_at_start = 0
        self.parent = parent
        self.questions = questions or []
        self.record_mode = record_mode
        try:
            _fcfg = gpu_config(self.conn)
            if _fcfg:
                import threading
                threading.Thread(target=fabric_prewarm, args=(_fcfg,), daemon=True).start()
        except Exception as e:
            _audit(self.conn, "fabric_prewarm_failed", f"{type(e).__name__}: {e}")
        self.title = title
        self.subtitle = subtitle
        self.allow_hints = allow_hints
        self.collect_diagnostics = collect_diagnostics
        self.timed = timed
        self.total_seconds = total_seconds
        self.allow_back = allow_back
        self.dynamic_picker = dynamic_picker
        self.diagnostic_redo = diagnostic_redo
        self.elaborate = elaborate
        # Confidence capture under PRESSURE. The click-based post-answer
        # prompt used in untimed modes is unusable mid-exam: it interrupts
        # the flow and, worse, would itself alter the pacing behaviour the
        # timing baselines are measuring. This instead offers a persistent,
        # keystroke-only selector (1/2/3) the learner sets BEFORE choosing an
        # answer, defaulting to unrecorded if they ignore it entirely --
        # so the exam still runs exactly as before for anyone who doesn't
        # engage with it. Without this, every calibration figure in the app
        # described calm conditions only, while the app's central thesis is
        # that calm and pressured are different constructs.
        # Spec 7.5 Beat 2: confidence is captured BEFORE the reveal in every
        # mode, via the J/K/L strip. The post-reveal button prompt survives
        # only as a fallback for diagnostic sessions when no keystroke came.
        self.pressure_confidence = True
        self.pending_confidence = None
        # Per-ITEM pre-performance routine. The July 2026 choking meta-
        # analysis (21 studies) found pre-performance routines and quiet-eye
        # training among the most effective interventions, with the largest
        # and most consistent effects in CLOSED-SKILL, fine-precision tasks
        # -- which is exactly what a single timed exam item is. The app's
        # existing pre-session routine (expressive writing + arousal
        # reappraisal + breathing) draws on the weaker half of that same
        # evidence base: mixed replication, and a small pooled effect with
        # documented publication bias. This adds the better-evidenced form
        # WITHOUT removing the old one, since they address different moments.
        self.pre_performance = pre_performance
        self.on_finish = on_finish

        self.dynamic_target = len(self.questions) if dynamic_picker else None
        self.dynamic_seen = []
        self.served_groups = {"National": 0, "NJ-Specific": 0}
        self.served_topics = {}
        self.exposure = exposure_counts(self.conn) if dynamic_picker else {}
        self.theta_se = None
        self.stop_reason = None
        self._session_info = 0.0     # Fisher information gathered by THIS session
        if dynamic_picker:
            # Estimate ability within the pacing regime this session actually
            # runs under, rather than pooling calm and pressured performance
            # into one average that the pressure model then insists are
            # different constructs.
            self._ability_modes = tuple(
                BASELINE_REGIMES[baseline_regime_for_mode(record_mode)])
            self.theta, self.theta_se, _n = ability_with_se(
                self.conn, modes=self._ability_modes)
        else:
            self._ability_modes = None
            self.theta = None
        # A ladder set (the diagnostic's timed portion, a progressive set)
        # is a random draw from the bank with no composed plan, but the
        # phase gate's relative criterion needs what the set asked of the
        # learner: the mean success probability of the served items at the
        # ability the learner brought to it. Scored against the absolute
        # 0.75 bar instead, a ladder-only learner could never leave phase A.
        self._planned_mean_p = None
        if (not dynamic_picker and not diagnostic_redo
                and (str(record_mode).startswith("progressive") or record_mode == "diagnostic_timed")
                and any(self.questions)):
            th0 = current_theta(self.conn)
            served = [q for q in self.questions if q]
            self._planned_mean_p = round(sum(
                irt_p3(th0, q.get("a_irt", 1.0), q.get("b_irt", 0.0), q.get("c_irt", 0.2))
                for q in served) / len(served), 3)

        self.index = 0
        self.answers = [None] * max(1, len(self.questions))
        self.initial_answers = [None] * max(1, len(self.questions))
        self.attempt_row_ids = [None] * max(1, len(self.questions))
        self.hint_level = 0
        self._eliminated = set()
        self.pending_confidence = None
        self.revealed = False
        self.selected_idx = None
        self.session_start = time.monotonic()
        self.q_start = time.monotonic()
        self.timer_after_id = None
        self._advance_after_id = None
        self.destroyed = False
        self.missed_for_redo = []
        self.flagged = set()
        # live controller state
        self.ctrl_window = []          # rolling {correct, z}
        self.ctrl_last_cue_at = -99
        self.ctrl_active_id = None
        self.ctrl_acc_at_cue = None
        self.ctrl_answers_since_cue = 0
        self.ctrl_correct_since_cue = 0
        self.ctrl_paused_escalation = False
        self.ctrl_baselines = None
        self.ctrl_regime = "calm"
        self.ctrl_basis = "default"
        self._gen_state = None         # the generation occasion, per item
        self.exam_mode = allow_back and timed  # full exam-day rehearsal
        self.calc_window = None
        self._continue_btn = None

        self.app.active_session = self
        log_session_event(self.conn, "start", self.record_mode,
                          n_items=(self.dynamic_target or len(self.questions)))
        self._build_chrome()
        self._bind_keys()
        self._load_current_question()
        self.render_question()
        if self.timed:
            self._tick()

    # ---- lifecycle -------------------------------------------------------

    def _clear(self):
        for w in self.parent.winfo_children():
            w.destroy()

    def _bind_keys(self):
        # ONE key path only. TrainerApp binds <Key> once at the "all" level
        # and routes it to the active session's handle_key (with the
        # text-field focus guard). A per-session bind_all here would REPLACE
        # that binding -- Tk's bind_all without add="+" overwrites -- and
        # the matching unbind_all would then remove the app-level handler
        # for good, so nothing is bound or unbound per session.
        pass

    def _unbind_keys(self):
        # See _bind_keys: the app-level binding outlives every session and
        # already checks `active_session`, so there is nothing to release.
        pass

    def _build_chrome(self):
        self._clear()
        header = ctk.CTkFrame(self.parent, fg_color="transparent")
        header.pack(fill="x", padx=32, pady=(28, 0))
        ctk.CTkLabel(header, text=self.title, font=(FONT_DISPLAY, 22, "bold"),
                     text_color=C.INK, anchor="w").pack(anchor="w")
        ctk.CTkLabel(header, text=self.subtitle, font=(FONT_BODY, 12), text_color=C.INK_DIM,
                     anchor="w").pack(anchor="w", pady=(2, 12))

        top_row = ctk.CTkFrame(self.parent, fg_color="transparent")
        top_row.pack(fill="x", padx=32)
        self.progress_lbl = ctk.CTkLabel(top_row, text="", font=(FONT_MONO, 12), text_color=C.INK_DIM)
        self.progress_lbl.pack(side="left")
        timer_box = ctk.CTkFrame(top_row, fg_color="transparent")
        timer_box.pack(side="right")
        self.timer_lbl = ctk.CTkLabel(timer_box, text="", font=(FONT_MONO, 14, "bold"), text_color=C.NAVY)
        self.timer_lbl.pack(anchor="e")
        self.pace_lbl = ctk.CTkLabel(timer_box, text="", font=(FONT_BODY, 10), text_color=C.INK_DIM)
        self.pace_lbl.pack(anchor="e")

        bar_holder = ctk.CTkFrame(self.parent, fg_color="transparent", height=6)
        bar_holder.pack(fill="x", padx=32, pady=(10, 0))
        self.progress_track = ctk.CTkFrame(bar_holder, fg_color=C.PAPER_LINE, height=6,
                                            corner_radius=3)
        self.progress_track.pack(fill="x")
        self.progress_track.pack_propagate(False)
        self.progress_fill = ctk.CTkFrame(self.progress_track, fg_color=C.BRASS, height=6,
                                           corner_radius=3, width=0)
        self.progress_fill.place(x=0, y=0)

        self.body = ctk.CTkScrollableFrame(self.parent, fg_color="transparent")
        self.body.pack(fill="both", expand=True, padx=32, pady=(12, 16))

    def _current_question(self):
        if self.dynamic_picker:
            return self._current_dynamic_q
        return self.questions[self.index]

    def _plan_meta_now(self):
        if self.dynamic_picker or not self.plan_meta:
            return None
        if 0 <= self.index < len(self.plan_meta):
            return self.plan_meta[self.index]
        return None

    def _is_learn_objective(self):
        return not (self.timed or self.exam_mode or str(self.record_mode).startswith("diagnostic")
                    or self.diagnostic_redo or self.record_mode == "challenge")

    def _retest_cap(self):
        """Governed per-session ceiling on same-session retests, shared by
        the dynamic and the fixed-list paths."""
        return int(active_threshold(self.conn, "retest_max_per_session", 3))

    def _pretest_allowed(self):
        """A sanctioned pretest is only honest where THIS session will serve
        the retest that scores it (spec 7.6). Composed plans decide that
        themselves through their per-item pretest flags; dynamic drills
        detect first encounters live; a fixed-list session (Practice Quiz,
        topic drill, error-log drill) has no pretest slot, so every answer
        there is ordinary evidence and no "take a swing" banner is shown."""
        if not self._is_learn_objective() or self.composed_plan or not self.dynamic_picker:
            return False
        return not getattr(self, "_dynamic_retest", False)

    def _is_first_encounter(self, q):
        if q is None or not self._pretest_allowed():
            return False
        skills = [sid for sid in Q_MATRIX.get(q["id"], []) if sid in SKILLS]
        if not skills or any(sid in self._seen_skills for sid in skills):
            return False
        # A pretest with no retest slot left would be evidence thrown away,
        # so first encounters past the cap record as ordinary answers. An
        # item already queued keeps its pretest status across the several
        # calls one answer can make.
        return (q["id"] in self._retest_qids
                or len(self.missed_for_redo) + self._retests_added < self._retest_cap())

    def _mark_seen(self, q):
        for sid in Q_MATRIX.get(q["id"], []):
            if sid in SKILLS:
                self._seen_skills.add(sid)

    def _effective_mode(self):
        """Pretest items record under mode='pretest' (excluded from every
        estimator); everything else under the session's record_mode."""
        meta = self._plan_meta_now()
        if meta and meta.get("pretest"):
            return "pretest"
        if self._is_first_encounter(self._current_question()):
            return "pretest"
        return self.record_mode

    def _queue_retest(self, q):
        """Spec 7.6: confident-wrong (and every pretest) goes to
        missed_for_redo for a Movement-3 retest -- the interpolated test
        that blocks the return of high-confidence errors."""
        if q["id"] in self._retest_qids or str(q["id"]).startswith("gen-"):
            return
        self._retest_qids.add(q["id"])
        self.missed_for_redo.append(q)

    def _append_retests(self, max_n=None):
        """At the end of a fixed-list plan, append retests from
        missed_for_redo -- by default as many as the governed per-session
        cap still allows, counting the ones already appended, so reaching
        the end of the queue a second time cannot restart the tail.
        Returns how many were added."""
        if max_n is None:
            max_n = max(0, self._retest_cap() - self._retests_added)
        added = 0
        if self.missed_for_redo and added < max_n and len(self.plan_meta) < len(self.questions):
            # A plain fixed list (Practice Quiz, topic drill) starts with no
            # plan_meta at all; the retest flag must land at the retest's
            # own index, so the planned items get neutral metadata first.
            self.plan_meta.extend(
                {"q": qq, "movement": "work", "pretest": False, "retest": False, "skill": None}
                for qq in self.questions[len(self.plan_meta):])
        while self.missed_for_redo and added < max_n:
            q = self.missed_for_redo.pop(0)
            self.questions.append(q)
            self.plan_meta.append({"q": q, "movement": "close", "pretest": False,
                                   "retest": True, "skill": None})
            self.answers.append(None)
            self.initial_answers.append(None)
            self.attempt_row_ids.append(None)
            added += 1
        self._retests_added += added
        return added

    def _load_current_question(self):
        if self.dynamic_picker:
            candidates = [q for q in QUIZ_LIST if q["id"] not in self.dynamic_seen]
            if not candidates:
                self._current_dynamic_q = None
                return
            if False:
                # The theta-0.35 post-cue hold is retired (spec 7.3): the
                # same intent -- don't escalate into a rough patch -- is now
                # expressed in p-space by learning_target_p(), which lifts
                # the target after a cue or two consecutive misses. One
                # policy, one space.
                pass
            else:
                posterior = None
                if len(self.dynamic_seen) < EARLY_ITEM_COUNT:
                    posterior = theta_posterior_now(
                        self.conn, modes=getattr(self, "_ability_modes", None))
                # Recomputed each item (cheap -- a Beta draw per topic) so
                # topic priorities stay current as mastery evidence accrues
                # during the session, not frozen at whatever it was at start.
                topic_scores = thompson_topic_scores(self.conn)
                # Only does real work if the embedding model was already
                # warmed up elsewhere (Free Recall / Explorer); otherwise
                # this is an instant no-op rather than a fresh model load.
                cluster_ids = get_cluster_boost_ids(self.conn)
                # A session's OBJECTIVE decides the selection rule. Timed and
                # diagnostic modes exist to measure, so they use max-info;
                # everything else exists to teach, so it targets the
                # desirable-difficulty band instead. Serving p=0.5 items in a
                # drill was the single largest mismatch between what the
                # engine optimised and what the learner was there for.
                objective = ("measure" if (self.timed or self.exam_mode or
                                           str(self.record_mode).startswith("diagnostic"))
                             else "learn")
                target_p = None
                if objective == "learn":
                    try:
                        target_p = learning_target_p(
                            self.conn, learner_phase(self.conn), len(self.dynamic_seen),
                            self.dynamic_target,
                            {"consecutive_wrong": self.ctrl_consecutive_wrong,
                             "paused_escalation": self.ctrl_paused_escalation},
                            theta=self.theta)
                    except Exception:
                        target_p = None
                best = select_next_item(self.conn, self.theta, set(self.dynamic_seen),
                                        self.served_groups, exposure=self.exposure,
                                        target_length=self.dynamic_target,
                                        posterior=posterior, topic_scores=topic_scores,
                                        cluster_ids=cluster_ids,
                                        served_topics=self.served_topics,
                                        objective=objective, target_p=target_p)
                if best is None:
                    best = max(candidates,
                               key=lambda q: fisher_info_3pl(self.theta, q.get("a_irt", 1.0),
                                                             q.get("b_irt", 0.0)))
            self._current_dynamic_q = best

    # ---- rendering ---------------------------------------------------

    def _scroll_to_top(self):
        """Return the question body to the top after a re-render.

        update_idletasks() first is the load-bearing part: it forces the new
        children to be mapped and the scrollregion recomputed, so the
        moveto that follows applies to the FINAL geometry rather than being
        overwritten by it."""
        try:
            if not self.body.winfo_exists():
                return
            cv = self.body._parent_canvas
            self.body.update_idletasks()
            # ORDER IS THE WHOLE FIX. CTkScrollableFrame binds <Configure> to
            # reset scrollregion from bbox("all"), and that fires AFTER a
            # plain yview_moveto -- at which point Tk preserves the ABSOLUTE
            # scroll offset across the new region, silently restoring the old
            # position. Measured 0.20 before advancing and 0.19 after, three
            # different ways. Setting the scrollregion first and moving
            # second means there is no later recompute to undo it.
            cv.configure(scrollregion=cv.bbox("all"))
            cv.yview_moveto(0.0)
        except Exception:
            pass

    def _scroll_to_feedback(self):
        """After an answer, bring the verdict / explanation / Next into view.

        At the default and minimum window sizes the option rows alone fill
        the viewport, so the feedback lands below the fold and the only
        hint that anything happened is a scrollbar. Same canvas mechanics
        as _scroll_to_top (scrollregion first, then moveto). The target
        keeps as much of the coloured option rows visible as still fits:
        scroll just far enough that the END of the feedback area is on
        screen, but never past the verdict at its top."""
        if self.destroyed:
            return
        try:
            fa = getattr(self, "feedback_area", None)
            if fa is None or not self.body.winfo_exists() or not fa.winfo_exists():
                return
            cv = self.body._parent_canvas
            self.body.update_idletasks()
            cv.configure(scrollregion=cv.bbox("all"))
            bbox = cv.bbox("all")
            if not bbox:
                return
            total = float(bbox[3] - bbox[1])
            view_h = float(cv.winfo_height())
            if total <= 0 or view_h <= 1 or total <= view_h:
                return
            top = fa.winfo_y()
            bottom = top + fa.winfo_height()
            want_bottom = max(0.0, (bottom - view_h) / total)
            want_top = max(0.0, top / total)
            cv.yview_moveto(min(want_top, want_bottom))
        except tk.TclError:
            pass

    def _retest_header_text(self, q):
        """Header for a retest item. The retest queue holds only pretests
        and confident misses, so the newest attempt on the item is the one
        that queued it: mode 'pretest' means the learner was told to guess,
        anything else was a confident miss."""
        mode = None
        try:
            row = self.conn.execute(
                "SELECT mode FROM attempts WHERE question_id=? ORDER BY id DESC LIMIT 1",
                (q["id"],)).fetchone()
            mode = row["mode"] if row else None
        except sqlite3.Error:
            mode = None
        if mode == "pretest":
            return "Back again — the one you guessed on."
        return "Back again — the one you were sure about earlier."

    def _days_since_last_exposure(self, q):
        """Days since the newest attempt on this item that predates this
        session, or None when the session is its first exposure. A same-
        session retest is minutes old and so returns None too."""
        start_id = getattr(self, "_attempt_id_at_start", 0)
        try:
            if self.conn.execute(
                    "SELECT 1 FROM attempts WHERE question_id=? AND id > ? LIMIT 1",
                    (q["id"], start_id)).fetchone():
                return None
            row = self.conn.execute(
                "SELECT timestamp FROM attempts WHERE question_id=? AND id <= ? "
                "ORDER BY id DESC LIMIT 1",
                (q["id"], start_id)).fetchone()
            if not row or not row["timestamp"]:
                return None
            then = datetime.fromisoformat(str(row["timestamp"]))
            return max(0, (datetime.now() - then).days)
        except (sqlite3.Error, ValueError, TypeError):
            return None

    # ---- generation before recognition (directive V) ---------------------

    def _generation_position(self):
        """A counter that advances once per item served, in both the fixed
        list and the engine-picked path, so one occasion is one item."""
        return len(self.dynamic_seen) if self.dynamic_picker else self.index

    def _generation_state(self, q, meta):
        """The generation occasion for the item on screen, or None.

        Recomputed only when the item changes, so the re-render that follows
        the learner's own answer does not re-open the prompt."""
        pos = self._generation_position()
        st = getattr(self, "_gen_state", None)
        if st is not None and st["pos"] == pos and st["qid"] == q["id"]:
            return st
        self._gen_state = None
        if not self._is_learn_objective():
            return None
        is_retest = bool((meta and meta.get("retest"))
                         or getattr(self, "_dynamic_retest", False))
        mission_id = meta.get("mission_id") if meta else None
        try:
            applies, why = generation_applies(self.conn, q, is_retest=is_retest,
                                              mission_id=mission_id)
        except sqlite3.Error:
            applies, why = False, "eligibility could not be read"
        if not applies:
            return None
        key = f"{q['id']}@{getattr(self, '_attempt_id_at_start', 0)}:{pos}"
        try:
            # `why` -- the state that made this a treatment occasion -- is
            # RECORDED, never consulted: the arm is a hash of the occasion
            # key and nothing else.
            arm = intervention_arm(self.conn, GENERATION_TRIAL, key,
                                   state_tag=why, subject=str(q["id"]))
        except sqlite3.Error:
            arm = None
        self._gen_state = {"pos": pos, "qid": q["id"], "key": key, "arm": arm,
                           "why": why, "result": None, "scored": False,
                           "stage": ("prompt" if arm == "generation_first"
                                     else "off")}
        return self._gen_state

    def _render_generation_prompt(self, q, gen):
        """Write the answer before the options appear.

        Keyboard-first, for the same reason the confidence strip is: a
        mouse-driven extra step alters the pacing the timing baselines
        measure. The box takes focus, Enter submits, Shift+Enter is a new
        line, Escape skips. Skipping is always offered -- this measures
        whether a prompt helps, not whether the learner complies."""
        box = card(self.body, fg_color=C.PAPER_DIM)
        box.pack(fill="x", pady=(14, 0))
        inner = ctk.CTkFrame(box, fg_color="transparent", height=0)
        inner.pack(fill="x", padx=16, pady=13)
        ctk.CTkLabel(inner,
                     text="Before the options — write the answer from memory",
                     font=(FONT_BODY, 12, "bold"), text_color=C.INK,
                     anchor="w").pack(anchor="w")
        lead = ctk.CTkLabel(
            inner,
            text=(("You were sure about this one and missed it, so it is worth "
                   "producing rather than picking."
                   if gen["why"] == "confident-miss retest" else
                   "This item belongs to an open repair, so it is worth "
                   "producing rather than picking.")
                  + " A phrase is enough, and the options come next either way."),
            font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w",
            justify="left")
        lead.pack(anchor="w", fill="x", pady=(3, 8))
        bind_autowrap(lead, self.body, padding=90)
        self._gen_box = ctk.CTkTextbox(inner, height=70, font=(FONT_BODY, 12),
                                       fg_color="#FFFFFF", text_color=C.INK,
                                       corner_radius=8, border_width=1,
                                       border_color=C.PAPER_LINE)
        self._gen_box.pack(fill="x")

        def submit(event=None):
            try:
                text = self._gen_box.get("1.0", "end").strip()
            except tk.TclError:
                text = ""
            self._submit_generation(text)
            return "break"

        def skip(event=None):
            self._submit_generation(None)
            return "break"

        self._gen_box.bind("<Return>", submit)
        # Shift+Return must reach the widget's own newline handler, so it is
        # deliberately not bound here.
        self._gen_box.bind("<Escape>", skip)
        row = ctk.CTkFrame(inner, fg_color="transparent")
        row.pack(anchor="w", fill="x", pady=(9, 0))
        primary_button(row, "Check, then show the options", submit).pack(side="left")
        ghost_button(row, "Skip", skip).pack(side="left", padx=(8, 0))
        ctk.CTkLabel(row, text="Enter to submit · Shift+Enter for a new line "
                               "· Esc to skip",
                     font=(FONT_BODY, 10), text_color=C.INK_DIM
                     ).pack(side="left", padx=(10, 0))
        try:
            self._gen_box.focus_set()
        except tk.TclError:
            pass
        # The chrome the rest of the class expects to exist, empty while the
        # prompt is up: no options have been built, which is the point.
        self.option_buttons = []
        self.hint_area = ctk.CTkFrame(self.body, fg_color="transparent", height=0)
        self.hint_area.pack(fill="x")
        self.action_row = ctk.CTkFrame(self.body, fg_color="transparent", height=0)
        self.action_row.pack(fill="x")
        self.feedback_area = ctk.CTkFrame(self.body, fg_color="transparent", height=0)
        self.feedback_area.pack(fill="x")

    def _submit_generation(self, text):
        """Score the produced answer (or record that it was skipped) and
        re-render with the options.

        The re-render restarts the item clock, so the response time still
        measures time-to-choose from the moment the options appeared, which
        is the quantity the timing baselines compare against."""
        gen = getattr(self, "_gen_state", None)
        if gen is None or gen.get("stage") != "prompt":
            return
        if text:
            gen["result"] = record_generation_attempt(
                self.conn, gen["key"], self._current_question(), text)
        if not gen.get("result"):
            gen["result"] = {"skipped": True}
        gen["stage"] = "answered"
        self.render_question()

    def _render_generation_result(self, result):
        """What the produced answer covered.

        Packed into the body ABOVE the options, not into feedback_area --
        the reveal empties feedback_area, and this feedback has to survive
        the prompt that follows it. Word counts and the terms themselves,
        never a percentage and never the mastery credit: the learner is
        being told about their own sentence, not shown an internal
        estimate."""
        box = card(self.body, fg_color=C.PAPER_DIM)
        box.pack(fill="x", pady=(12, 0))
        inner = ctk.CTkFrame(box, fg_color="transparent", height=0)
        inner.pack(fill="x", padx=16, pady=12)
        if result.get("skipped"):
            ctk.CTkLabel(inner,
                         text="You skipped writing it first — the options are below.",
                         font=(FONT_BODY, 11, "italic"), text_color=C.INK_DIM,
                         anchor="w").pack(anchor="w")
            return
        ctk.CTkLabel(inner, text="WHAT YOU WROTE", font=(FONT_BODY, 10, "bold"),
                     text_color=C.BRASS_DARK, anchor="w").pack(anchor="w")
        yl = ctk.CTkLabel(inner, text=result.get("text") or "", font=(FONT_BODY, 12),
                          text_color=C.INK, anchor="w", justify="left")
        yl.pack(anchor="w", fill="x", pady=(3, 7))
        bind_autowrap(yl, self.body, padding=90)
        covered, missed = result.get("covered") or [], result.get("missed") or []
        total = len(covered) + len(missed)
        if total:
            ctk.CTkLabel(inner,
                         text=(f"{len(covered)} of the {total} key words in the "
                               "answer are in what you wrote."),
                         font=(FONT_BODY, 12), text_color=C.INK,
                         anchor="w").pack(anchor="w")
        if missed:
            ml = ctk.CTkLabel(inner, text="Not there yet: " + ", ".join(missed),
                              font=(FONT_BODY, 12), text_color=C.INK,
                              anchor="w", justify="left")
            ml.pack(anchor="w", fill="x", pady=(3, 0))
            bind_autowrap(ml, self.body, padding=90)
        nl = ctk.CTkLabel(
            inner,
            text=("This is a word-overlap check against the authored answer, "
                  "not a grade — the same wording in different words "
                  "counts as missed. The options are below."),
            font=(FONT_BODY, 10), text_color=C.INK_DIM, anchor="w",
            justify="left")
        nl.pack(anchor="w", fill="x", pady=(6, 0))
        bind_autowrap(nl, self.body, padding=90)

    def _record_generation_outcome(self, correct):
        """One occasion, one outcome, recorded once. The observable is the
        accuracy of the very item the prompt was shown on -- a thing this
        app already scores, so no proxy had to be invented to make the
        trial look measured."""
        gen = getattr(self, "_gen_state", None)
        if not gen or gen.get("scored") or not gen.get("arm"):
            return
        gen["scored"] = True
        try:
            record_intervention_outcome(self.conn, GENERATION_TRIAL,
                                        gen["key"], 1.0 if correct else 0.0)
        except sqlite3.Error as e:
            _audit(self.conn, "generation_outcome_failed",
                   f"{gen['key']} {type(e).__name__}: {e}")

    def render_question(self):
        # The review screen (and any other full-pane takeover) destroys the
        # question chrome, but a queued auto-advance may still fire afterwards.
        # Rebuild the chrome rather than crashing on a stale widget path.
        try:
            self.body.winfo_exists()
            _ = self.body.winfo_children()
        except (tk.TclError, AttributeError):
            self._build_chrome()
        for w in self.body.winfo_children():
            w.destroy()

        # SCROLL RESET. The body is a CTkScrollableFrame, and its scroll
        # position survives having its children replaced. A question whose
        # feedback grew tall -- an expanded explanation, or a Socratic hint
        # appended after the fact -- leaves the view scrolled down; the next
        # question then renders correctly at the top while the viewport is
        # still parked below it, so the screen looks blank apart from a
        # sliver of the first widget. Nothing has crashed, which is why it
        # produces no error and is easy to misread as a render failure.
        # Defensive scroll reset. NOT a fix for anything currently known to
        # be broken: with this disabled the view still returns to 0.00 on
        # every advance, because CustomTkinter already rebuilds the
        # scrollregion when render_question replaces the body. It is kept
        # only as a cheap guarantee for paths that bypass that rebuild.
        #
        # Recorded because it cost a long investigation: the earlier
        # measurements that appeared to show a stuck scroll (0.25 -> 0.23)
        # were taken on a flow that never advanced at all. Clicking an
        # error-tag button records the tag; the session advances only via
        # the continue button, whose label is "Next \u2192" or "Finish".
        # Measuring an advance that never happened produced four rounds of
        # fixes for a bug that was not there.
        try:
            self.parent.after(60, self._scroll_to_top)
        except Exception:
            pass

        self.revealed = False
        self.hint_level = 0
        self._eliminated = set()
        self.pending_confidence = None
        self.selected_idx = None
        self.q_start = time.monotonic()
        self._continue_btn = None

        q = self._current_question()
        if q is None:
            self.finish()
            return
        topic = TOPICS[q["topic"]]
        meta = self._plan_meta_now()

        # Spec 7.6: first-encounter header. The sanction is what makes an
        # errorful-generation event deliverable to an avoidant learner.
        if (meta and meta.get("pretest")) or self._is_first_encounter(q):
            hb = card(self.body, fg_color=C.PAPER_DIM)
            hb.pack(fill="x", pady=(0, 10))
            ctk.CTkLabel(hb, text="New topic \u2014 a first guess is fine; missing it now "
                         "is part of how it sticks.", font=(FONT_BODY, 12, "italic"),
                         text_color=C.INK, anchor="w", justify="left", wraplength=640
                         ).pack(anchor="w", padx=14, pady=10)
        elif (meta and meta.get("retest")) or getattr(self, "_dynamic_retest", False):
            # The queue holds two kinds of item -- a sanctioned pretest the
            # learner was told to guess on, and a confident miss -- and the
            # header must not tell a guesser they were "sure".
            ctk.CTkLabel(self.body, text=self._retest_header_text(q),
                         font=(FONT_BODY, 11, "italic"), text_color=C.INK_DIM,
                         anchor="w").pack(anchor="w", pady=(0, 6))

        total_n = self.dynamic_target if self.dynamic_picker else len(self.questions)
        idx_n = len(self.dynamic_seen) + 1 if self.dynamic_picker else self.index + 1
        self._update_progress_bar(idx_n, total_n)
        # The ability estimate and its standard error stay in the Author
        # views; on the learner's counter they read as a live score.
        self.progress_lbl.configure(text=f"Question {idx_n} of {total_n}")

        if self.pre_performance:
            # Quiet-eye-style fixed routine, shown on every item so it
            # becomes automatic rather than novel by exam day -- the whole
            # point of a pre-performance routine is that it is rehearsed.
            # It precedes the stem because it is a PRE-performance routine;
            # after the first few items it collapses to a one-line reminder
            # so the rehearsed form stays present without being re-read.
            pp = card(self.body, fg_color=C.PAPER_DIM)
            pp.pack(fill="x", pady=(0, 10))
            ppi = ctk.CTkFrame(pp, fg_color="transparent", height=0)
            if idx_n > PRE_PERFORMANCE_FULL_ITEMS:
                ppi.pack(fill="x", padx=14, pady=6)
                ctk.CTkLabel(ppi, text="Before you answer:  " + PROCEDURAL_CUE_SHORT,
                             font=(FONT_BODY, 11, "bold"), text_color=C.INK,
                             anchor="w").pack(anchor="w")
            else:
                ppi.pack(fill="x", padx=14, pady=9)
                ctk.CTkLabel(ppi, text="Before you answer", font=(FONT_BODY, 11, "bold"),
                             text_color=C.INK, anchor="w").pack(anchor="w")
                for step in procedural_cue_steps(self.exam_mode):
                    ctk.CTkLabel(ppi, text="\u2022  " + step, font=(FONT_BODY, 11),
                                 text_color=C.INK, anchor="w").pack(anchor="w", pady=(2, 0))

        meta_row = ctk.CTkFrame(self.body, fg_color="transparent", height=0)
        meta_row.pack(fill="x", pady=(0, 6))
        ctk.CTkLabel(meta_row, text=f"{topic['short']} \u00b7 {topic['group']}", font=(FONT_BODY, 11, "bold"),
                     text_color=C.BRASS_DARK).pack(side="left")
        # The difficulty tag is created here but packed only on the reveal
        # of an untimed item (on_option_click); a timed set never shows it,
        # as the real exam never would.
        diff = q.get("difficulty", "medium")
        self._diff_lbl = ctk.CTkLabel(meta_row, text=diff.title(), font=(FONT_BODY, 11, "bold"),
                                      text_color=DIFF_COLOR.get(diff, C.INK_DIM))
        if self.allow_back and self.answers[self.index] is not None:
            ctk.CTkLabel(meta_row, text=f"current answer: {'ABCD'[self.answers[self.index]]}",
                         font=(FONT_BODY, 11), text_color=C.INK_DIM).pack(side="right")

        qcard = card(self.body)
        qcard.pack(fill="x")
        qinner = ctk.CTkFrame(qcard, fg_color="transparent")
        qinner.pack(fill="x", padx=22, pady=20)
        qlabel = ctk.CTkLabel(qinner, text=q["q"], font=(FONT_DISPLAY, 16), text_color=C.INK,
                               anchor="w", justify="left")
        qlabel.pack(anchor="w", fill="x")
        bind_autowrap(qlabel, self.body, padding=48)

        # Generation before recognition (directive V), on the narrow set of
        # items where hypercorrection is the mechanism. While the prompt is
        # up the options are not BUILT at all -- "before the options appear"
        # is the whole of the manipulation, and hiding built widgets would
        # leave them one keystroke away.
        gen = self._generation_state(q, meta)
        if gen is not None and gen.get("stage") == "prompt":
            self._render_generation_prompt(q, gen)
            return
        if gen is not None and gen.get("result"):
            self._render_generation_result(gen["result"])

        self.option_buttons = []
        opts_wrap = ctk.CTkFrame(self.body, fg_color="transparent")
        opts_wrap.pack(fill="x", pady=(14, 0))
        for i, opt in enumerate(q["opts"]):
            row = ctk.CTkFrame(opts_wrap, fg_color=C.PAPER_DIM, corner_radius=8,
                                border_width=1, border_color=C.PAPER_LINE)
            row.pack(fill="x", pady=4)
            row_inner = ctk.CTkFrame(row, fg_color="transparent")
            row_inner.pack(fill="x", padx=14, pady=10)
            letter_lbl = ctk.CTkLabel(row_inner, text="ABCD"[i], font=(FONT_BODY, 13, "bold"),
                                      text_color=C.BRASS_DARK, width=18, anchor="nw")
            letter_lbl.pack(side="left", anchor="n")
            text_lbl = ctk.CTkLabel(row_inner, text=opt, font=(FONT_BODY, 13), text_color=C.INK,
                                    anchor="w", justify="left")
            text_lbl.pack(side="left", fill="x", expand=True, anchor="w")
            bind_autowrap(text_lbl, self.body, padding=100)

            widgets = [row, row_inner, letter_lbl, text_lbl]

            def make_handler(idx=i):
                return lambda e=None: self.on_option_click(idx)

            def make_hover(enter):
                def handler(e=None):
                    if row.cget("fg_color") in (C.PAPER_DIM,) or not enter:
                        pass
                return handler

            handler = make_handler(i)
            for w in widgets:
                w.bind("<Button-1>", handler)
                w.configure(cursor="hand2") if hasattr(w, "configure") else None

            def on_enter(e=None, row=row):
                if not getattr(row, "_disabled", False):
                    row.configure(fg_color=C.PAPER_LINE)

            def on_leave(e=None, row=row):
                if not getattr(row, "_disabled", False):
                    row.configure(fg_color=C.PAPER_DIM)

            for w in widgets:
                w.bind("<Enter>", on_enter)
                w.bind("<Leave>", on_leave)

            row._letter_lbl = letter_lbl
            row._text_lbl = text_lbl
            row._disabled = False
            self.option_buttons.append(row)

        hint_bits = ["A\u2013D or 1\u20134 to answer"]
        if self.allow_hints:
            hint_bits.append("H for a hint")
        if self.exam_mode:
            hint_bits += ["F to flag", "C for calculator"]
        if self.pressure_confidence:
            hint_bits.append("J/K/L to rate confidence")
        ctk.CTkLabel(self.body, text="   \u00b7   ".join(hint_bits), font=(FONT_BODY, 11),
                     text_color=C.INK_DIM, anchor="w").pack(anchor="w", pady=(8, 0))

        if self.pressure_confidence:
            self._build_confidence_strip()

        if self.elaborate:
            # Elaborative interrogation: committing to a REASON before seeing
            # the answer is the mechanism -- reading someone else's rationale
            # afterwards is not the same thing.
            el = card(self.body, fg_color=C.PAPER_DIM)
            el.pack(fill="x", pady=(8, 0))
            eli = ctk.CTkFrame(el, fg_color="transparent", height=0)
            eli.pack(fill="x", padx=14, pady=10)
            ctk.CTkLabel(eli, text="Before you answer \u2014 why is your choice true?",
                         font=(FONT_BODY, 11, "bold"), text_color=C.INK,
                         anchor="w").pack(anchor="w")
            self.elab_box = ctk.CTkTextbox(eli, height=58, font=(FONT_BODY, 12),
                                            fg_color="#FFFFFF", text_color=C.INK,
                                            corner_radius=8, border_width=1,
                                            border_color=C.PAPER_LINE)
            self.elab_box.pack(fill="x", pady=(5, 0))

        self.hint_area = ctk.CTkFrame(self.body, fg_color="transparent", height=0)
        self.hint_area.pack(fill="x")

        self.action_row = ctk.CTkFrame(self.body, fg_color="transparent", height=0)
        self.action_row.pack(fill="x", pady=(12, 0))
        if self.allow_hints:
            self.hint_btn = ghost_button(self.action_row, "Hint", self.on_hint_click)
            self.hint_btn.pack(side="left")
        _cq = self._current_question()
        if (not self.timed and not self.exam_mode and self._effective_mode() != "pretest"
                and not str(_cq.get("id", "")).startswith("gen-")):
            self.tutor_btn = ghost_button(self.action_row, "Talk it through first",
                                          lambda qq=_cq: (None if self.revealed else
                                                          render_tutor_panel(self, self.feedback_area, qq, True)))
            self.tutor_btn.pack(side="left", padx=(8, 0))
        if self.allow_back and self.index > 0:
            ghost_button(self.action_row, "\u2190 Previous", self.go_back).pack(side="left", padx=(8, 0))
        if self.exam_mode:
            flagged_now = self.index in self.flagged
            self.flag_btn = ghost_button(
                self.action_row,
                "\u2691 Unflag" if flagged_now else "\u2691 Flag for review",
                self.toggle_flag)
            self.flag_btn.pack(side="left", padx=(8, 0))
            ghost_button(self.action_row, "Calculator", self.open_calculator).pack(side="left", padx=(8, 0))
        if self.timed:
            ghost_button(self.action_row, "Review & submit" if self.exam_mode else "Submit now",
                         self.submit_now).pack(side="right")

        self.feedback_area = ctk.CTkFrame(self.body, fg_color="transparent", height=0)
        self.feedback_area.pack(fill="x", pady=(8, 0))

    # ---- interaction -------------------------------------------------

    def on_hint_click(self):
        q = self._current_question()
        topic = TOPICS[q["topic"]]
        if self.hint_level >= 3:
            return
        self.hint_level += 1
        for w in self.hint_area.winfo_children():
            w.destroy()
        box = card(self.hint_area, fg_color=C.PAPER_LINE)
        box.pack(fill="x", pady=(6 if self.hint_level > 1 else 0, 0))
        inner = ctk.CTkFrame(box, fg_color="transparent", height=0)
        inner.pack(fill="x", padx=14, pady=10)

        if self.hint_level == 1:
            # Search using only the question's most DISTINCTIVE terms, not
            # the full sentence. search_content ANDs every token together --
            # passing a full 12-word question (including "which", "the",
            # "and", "of") builds a query almost nothing can match, and
            # tested at only 1/40 real hits before this fix. The same IDF
            # salience ranking Free Recall scoring already uses picks out
            # the handful of words that actually carry the question's
            # meaning, which searches far better.
            snippet = None
            try:
                idf = _build_idf()
                q_tokens = _tokenize(q["q"])
                salient = sorted(set(q_tokens), key=lambda w: -idf.get(w, 0.0))[:4]
                if salient:
                    hits = search_content_any(self.conn, salient, limit=8)
                    note_hit = next((h for h in hits if h["kind"] == "note" and h["topic_id"] == q["topic"]), None)
                    if note_hit:
                        snippet = re.sub(r"\s+", " ", note_hit["snippet"]).strip()
            except Exception:
                snippet = None
            if not snippet:
                snippet = topic["notes"][:240].rsplit(" ", 1)[0] + "..."
            lbl = ctk.CTkLabel(inner, text=f"Hint 1 of 3 \u2014 context from {topic['name']}:\n\u201c{snippet}\u201d",
                               font=(FONT_BODY, 12), text_color=C.INK, anchor="w", justify="left")
            lbl.pack(anchor="w", fill="x")
            bind_autowrap(lbl, self.body, padding=48)

        elif self.hint_level == 2:
            # Eliminate ONE wrong option -- down to three remaining. Weaker
            # than the old single-shot 50/50, now that there's a stronger
            # level 3 to reserve real narrowing for.
            wrong_idxs = [i for i in range(len(q["opts"])) if i != q["a"]]
            random.shuffle(wrong_idxs)
            eliminated = wrong_idxs[:1]
            self._eliminated = set(eliminated)
            for i in eliminated:
                row = self.option_buttons[i]
                row._disabled = True
                row.configure(fg_color=C.PAPER_LINE)
                row._letter_lbl.configure(text_color=C.INK_DIM)
                row._text_lbl.configure(text_color=C.INK_DIM)
            ctk.CTkLabel(inner, text=f"Hint 2 of 3 \u2014 ruled out {', '.join('ABCD'[i] for i in eliminated)}. "
                        "Three options left.",
                        font=(FONT_BODY, 12), text_color=C.INK, anchor="w").pack(anchor="w")

        elif self.hint_level == 3:
            # Eliminate a SECOND wrong option (classic 50/50) and surface
            # the item's own governing citation -- a real, specific pointer
            # rather than the answer itself. Every question in the bank now
            # carries a source, so this is available for every item.
            already = getattr(self, "_eliminated", set())
            wrong_idxs = [i for i in range(len(q["opts"])) if i != q["a"] and i not in already]
            random.shuffle(wrong_idxs)
            eliminated = wrong_idxs[:1]
            for i in eliminated:
                row = self.option_buttons[i]
                row._disabled = True
                row.configure(fg_color=C.PAPER_LINE)
                row._letter_lbl.configure(text_color=C.INK_DIM)
                row._text_lbl.configure(text_color=C.INK_DIM)
            text3 = f"Hint 3 of 3 \u2014 ruled out {', '.join('ABCD'[i] for i in eliminated)}. Down to two options."
            if q.get("source"):
                text3 += f"\nGoverning source: {q['source']}"
            lbl3 = ctk.CTkLabel(inner, text=text3, font=(FONT_BODY, 12), text_color=C.INK,
                               anchor="w", justify="left")
            lbl3.pack(anchor="w", fill="x")
            bind_autowrap(lbl3, self.body, padding=48)

    def on_option_click(self, idx):
        if self.revealed:
            return
        self.selected_idx = idx
        q = self._current_question()
        elapsed = time.monotonic() - self.q_start
        correct = (idx == q["a"])
        # V9.5: explain before the reveal. The latency is captured at the click,
        # before the prompt, and handed back on resume so typing time never
        # enters the timing baselines.
        if getattr(self, "_explain_resume", None) is not None:
            elapsed, self._explain_resume = self._explain_resume, None
        elif explain_wanted(self, q):
            ExplainPrompt.render(self, q, idx, correct, elapsed)
            return
        # The generation trial's observable, recorded on every answer path
        # from one place so an occasion cannot be scored twice or missed.
        self._record_generation_outcome(correct)

        if self.index < len(self.initial_answers) and self.initial_answers[self.index] is None and not self.dynamic_picker:
            self.initial_answers[self.index] = idx
        if not self.dynamic_picker and self.index < len(self.answers):
            self.answers[self.index] = idx

        if self.timed:
            # Real exam/timed-practice conditions: no immediate feedback --
            # matching an actual timed exam, we mark the selection, record
            # (or, on a back-navigated re-answer, update) it silently, and
            # advance -- no verdict, no explanation, no confidence/tagging.
            self.revealed = True
            for i, row in enumerate(self.option_buttons):
                row._disabled = True
                if i == idx:
                    row.configure(fg_color=C.PAPER_LINE, border_color=C.BRASS)
            fresh = self._record_or_update_attempt(q, correct, elapsed)
            self._mark_seen(q)
            # The behavioural controller was built for exactly this regime;
            # it sees each FIRST response only -- a back-navigated change of
            # answer is not a paced response and would corrupt the window.
            if fresh:
                self._update_controller(q, correct, elapsed)
            # A pacing cue is the one thing worth pausing the silent advance
            # for: leave it on screen with a Next button (the clock keeps
            # running, as on the real exam) instead of wiping it 120 ms later.
            cue_shown = False
            try:
                cue_shown = bool(self.feedback_area.winfo_exists()
                                 and self.feedback_area.winfo_children())
            except tk.TclError:
                cue_shown = False
            if cue_shown:
                self._render_continue()
            else:
                self._advance_after_id = self.parent.after(120, self.go_next)
            return

        if hasattr(self, "hint_btn"):
            self.hint_btn.configure(state="disabled")

        for i, row in enumerate(self.option_buttons):
            row._disabled = True
            if i == q["a"]:
                row.configure(fg_color=C.FOREST_DIM, border_color=C.FOREST)
            elif i == idx:
                # The one red element of a miss: the row that was chosen.
                row.configure(fg_color=C.STAMP_DIM, border_color=C.STAMP)
        self.revealed = True
        # The difficulty tag becomes information once the answer is known.
        diff_lbl = getattr(self, "_diff_lbl", None)
        if diff_lbl is not None:
            try:
                diff_lbl.pack(side="left", padx=(10, 0))
            except tk.TclError:
                pass

        for w in self.feedback_area.winfo_children():
            w.destroy()
        verdict = "\u2713 Correct." if correct else "\u2717 Not quite."
        verdict_color = C.FOREST if correct else C.INK
        # A correct answer that cost far more than its time share is a hidden
        # problem: it scores as a success while consuming the budget that
        # causes a miss later in the section.
        if correct and elapsed > PACE_TARGET_SECONDS * SLOW_FACTOR:
            verdict = f"\u2713 Correct \u2014 but that took {fmt_secs(elapsed)}"
            verdict_color = C.BRASS_DARK
        ctk.CTkLabel(self.feedback_area, text=verdict, font=(FONT_BODY, 13, "bold"),
                     text_color=verdict_color, anchor="w").pack(anchor="w")
        if correct:
            self._spaced_recall_line(q, meta=self._plan_meta_now())
        # Interleaved lookalikes are only worth the slot if the learner
        # knows the two are a pair: name the original on the partner item,
        # and on a missed original say that its lookalike is next.
        meta = self._plan_meta_now()
        pair_line = None
        if meta and meta.get("partner_of"):
            pair_line = ("This is the one people mix up with "
                         f"{SKILLS.get(meta['partner_of'], {}).get('label', meta['partner_of'])}.")
        elif meta and not correct and any(
                m.get("partner_of") == meta.get("skill")
                for m in self.plan_meta[self.index + 1:self.index + 4]):
            pair_line = "Its lookalike is coming up."
        if pair_line:
            ctk.CTkLabel(self.feedback_area, text=pair_line, font=(FONT_BODY, 12, "italic"),
                         text_color=C.INK, anchor="w", justify="left", wraplength=620
                         ).pack(anchor="w", pady=(4, 0))

        # Why the option YOU picked is wrong. Knowing the right answer does not
        # dislodge the specific wrong belief that produced the miss, so where a
        # per-distractor rationale exists, lead with it. Rendered in the
        # paper/brass tints: the chosen row already carries the red.
        if not correct:
            chosen_text = q["opts"][idx]
            why = (q.get("why_wrong") or {}).get(chosen_text)
            box = card(self.feedback_area, fg_color=C.PAPER_DIM)
            box.pack(fill="x", pady=(6, 6))
            inner = ctk.CTkFrame(box, fg_color="transparent", height=0)
            inner.pack(fill="x", padx=14, pady=10)
            ctk.CTkLabel(inner, text=f"Why \u201c{chosen_text[:70]}\u201d is wrong",
                         font=(FONT_BODY, 11, "bold"), text_color=C.BRASS_DARK,
                         anchor="w").pack(anchor="w")
            if why:
                wl = ctk.CTkLabel(inner, text=why, font=(FONT_BODY, 12), text_color=C.INK,
                                  anchor="w", justify="left")
            else:
                wl = ctk.CTkLabel(
                    inner,
                    text=("No specific write-up for this distractor yet \u2014 compare it against "
                          "the correct answer and the explanation below, and check the Study "
                          "Notes for this topic."),
                    font=(FONT_BODY, 12, "italic"), text_color=C.INK_DIM,
                    anchor="w", justify="left")
            wl.pack(anchor="w", fill="x", pady=(3, 0))
            bind_autowrap(wl, self.body, padding=90)
            try:
                render_lookalike_note(self, q)      # V8.5 trial: after misses only
            except Exception as e:
                _audit(self.conn, "lookalike_note_failed", f"{type(e).__name__}: {e}")
        if self.elaborate and hasattr(self, "elab_box"):
            try:
                mine = self.elab_box.get("1.0", "end").strip()
            except Exception:
                mine = ""
            if mine:
                mb = card(self.feedback_area, fg_color=C.PAPER_DIM)
                mb.pack(fill="x", pady=(4, 6))
                mi = ctk.CTkFrame(mb, fg_color="transparent", height=0)
                mi.pack(fill="x", padx=14, pady=9)
                ctk.CTkLabel(mi, text="Your reasoning", font=(FONT_BODY, 11, "bold"),
                             text_color=C.BRASS_DARK, anchor="w").pack(anchor="w")
                ml = ctk.CTkLabel(mi, text=mine, font=(FONT_BODY, 12), text_color=C.INK,
                                  anchor="w", justify="left")
                ml.pack(anchor="w", fill="x", pady=(2, 0))
                bind_autowrap(ml, self.body, padding=90)

        exp_lbl = ctk.CTkLabel(self.feedback_area, text=q["exp"], font=(FONT_BODY, 12),
                               text_color=C.INK_DIM, anchor="w", justify="left")
        exp_lbl.pack(anchor="w", fill="x", pady=(2, 4))
        bind_autowrap(exp_lbl, self.body, padding=48)

        # Citations make each claim checkable instead of asking the user to
        # take an authored answer on faith -- the single most important
        # property for a licensing study tool.
        if q.get("source"):
            src_lbl = ctk.CTkLabel(self.feedback_area,
                                   text="Source: " + q["source"],
                                   font=(FONT_BODY, 10), text_color=C.BRASS_DARK,
                                   anchor="w", justify="left")
            src_lbl.pack(anchor="w", fill="x", pady=(0, 8))
            bind_autowrap(src_lbl, self.body, padding=48)

        # Everything below packs more into feedback_area (confidence / tag
        # prompts, Next). Scrolling is deferred to idle so it measures the
        # FINAL geometry, whichever branch runs.
        try:
            self.parent.after_idle(self._scroll_to_feedback)
        except tk.TclError:
            pass

        if self.dynamic_picker:
            a_irt, b_irt = q.get("a_irt", 1.0), q.get("b_irt", 0.0)
            mode_now = self._effective_mode()
            record_attempt(self.conn, mode_now, q["id"], q["topic"], correct, self.hint_level,
                           a_irt, b_irt, elapsed, chosen=idx, confidence=self.pending_confidence,
                           rushing=self.ctrl_paused_escalation, question=q)
            if mode_now == "pretest" or (not correct and self.pending_confidence == 3):
                self._queue_retest(q)
            if not correct and self.pending_confidence == 3:
                self._confident_miss_line()
            if self._dynamic_retest and correct:
                self._retests_held += 1
            elif self._dynamic_retest:
                # Missed again: owed to a later session (persisted at finish).
                self._dynamic_retests_missed.append(q["id"])
            self._mark_seen(q)
            self._update_controller(q, correct, elapsed)
            self.dynamic_seen.append(q["id"])
            self.served_groups[TOPICS[q["topic"]]["group"]] = \
                self.served_groups.get(TOPICS[q["topic"]]["group"], 0) + 1
            self.served_topics[q["topic"]] = self.served_topics.get(q["topic"], 0) + 1
            self.exposure[q["id"]] = self.exposure.get(q["id"], 0) + 1
            self.theta, self.theta_se, _n = ability_with_se(
                self.conn, modes=getattr(self, "_ability_modes", None))
            # Information THIS session has gathered, evaluated at the
            # current estimate. Only items the model learns from count --
            # a shadow candidate or a template item tells the stop rule
            # nothing, just as it tells theta nothing.
            _qid = str(q["id"])
            if not _qid.startswith("gen-") and (not _qid.startswith("cand-")
                                               or q.get("ladder") == "calibrated"):
                self._session_info = getattr(self, "_session_info", 0.0) + \
                    fisher_info_3pl(self.theta, a_irt, b_irt)
            # The CAT stop rule is a MEASUREMENT rule. Timed, exam and
            # diagnostic sessions exist to measure and may end early once
            # this session's own evidence settles the estimate; a learning
            # session selects for desirable difficulty, not information, and
            # runs to the count the learner asked for.
            if not self._is_learn_objective():
                stop, reason = cat_should_stop(self.theta_se, len(self.dynamic_seen),
                                               self.dynamic_target, theta=self.theta,
                                               session_info=self._session_info)
            else:
                stop, reason = False, None
            # Surface early termination (precision reached or the pass/fail
            # call is already confident) but not the ordinary "hit the item
            # limit" case, which isn't early stopping at all.
            if stop and reason and "item limit" not in reason:
                self.stop_reason = reason
                ctk.CTkLabel(self.feedback_area,
                             text="Stopping early — " + reason + ".",
                             font=(FONT_BODY, 11, "italic"), text_color=C.INK_DIM,
                             anchor="w", justify="left", wraplength=620
                             ).pack(anchor="w", fill="x", pady=(4, 0))
            self._render_continue(is_last=(len(self.dynamic_seen) >= self.dynamic_target
                                           or bool(self.stop_reason)))
            return

        if self.diagnostic_redo:
            # Special flow: on correct, ask Timing/Strategy; on incorrect, auto-tag Content.
            if correct:
                self._prompt_redo_tag(q, elapsed)
            else:
                a_irt, b_irt = q.get("a_irt", 1.0), q.get("b_irt", 0.0)
                record_attempt(self.conn, self.record_mode, q["id"], q["topic"], False, 0,
                               a_irt, b_irt, elapsed, error_type="Content", rushing=self.ctrl_paused_escalation,
                               question=q)
                self._update_controller(q, correct, elapsed)
                self._render_continue()
            return

        if self.collect_diagnostics:
            if self.pending_confidence is not None:
                # Pre-reveal keystroke already captured; no contaminated
                # post-reveal prompt needed.
                self._confidence_chosen(q, idx, correct, elapsed, self.pending_confidence)
            else:
                self._prompt_confidence(q, idx, correct, elapsed)
            return

        a_irt, b_irt = q.get("a_irt", 1.0), q.get("b_irt", 0.0)
        conf = self.pending_confidence
        mode_now = self._effective_mode()
        if self.record_fn is not None:
            self.record_fn(q, correct, elapsed, idx)
        else:
            record_attempt(self.conn, mode_now, q["id"], q["topic"], correct, self.hint_level,
                           a_irt, b_irt, elapsed, chosen=idx, confidence=conf,
                           rushing=self.ctrl_paused_escalation, question=q)
        if mode_now == "pretest" or (not correct and conf == 3):
            self._queue_retest(q)
        if not correct and conf == 3:
            self._confident_miss_line()
        self._mark_seen(q)
        self._update_controller(q, correct, elapsed)
        self._render_continue()

    def _record_or_update_attempt(self, q, correct, elapsed):
        """Insert a fresh attempts row the first time this question (by
        index within the session) is answered, or update that same row in
        place if the user revisits and changes the answer (exam back-
        navigation). Prevents the same question from being counted twice
        toward ability estimation / topic mastery.

        The first answer goes through record_attempt so a timed item feeds
        everything an untimed one does -- BKT, the error log, the flashcard
        pull-forward on a miss and skill-level FSRS -- and stores the chosen
        option for the distractor analysis. Returns True when a fresh row
        was written, False for an in-place revisit."""
        a_irt, b_irt = q.get("a_irt", 1.0), q.get("b_irt", 0.0)
        initial = self.initial_answers[self.index] if self.index < len(self.initial_answers) else None
        existing_id = self.attempt_row_ids[self.index] if self.index < len(self.attempt_row_ids) else None
        if existing_id is None:
            row_id = record_attempt(self.conn, self.record_mode, q["id"], q["topic"], correct, 0,
                                    a_irt, b_irt, elapsed, confidence=self.pending_confidence,
                                    initial_answer=initial, chosen=self.selected_idx,
                                    rushing=self.ctrl_paused_escalation, question=q)
            if self.index < len(self.attempt_row_ids):
                self.attempt_row_ids[self.index] = row_id
            return True
        # Revisit: the row keeps its original response time (the revisit's
        # few seconds are not a paced read of the item) and BKT is left
        # alone -- it was already updated once for this exposure and is
        # recomputable from the attempts table; a second update would count
        # the same item twice toward topic mastery.
        prev = self.conn.execute("SELECT correct FROM attempts WHERE id=?", (existing_id,)).fetchone()
        self.conn.execute("UPDATE attempts SET correct=?, chosen=? WHERE id=?",
                          (1 if correct else 0, self.selected_idx, existing_id))
        self.conn.commit()
        if prev and bool(prev["correct"]) != correct:
            if not str(q["id"]).startswith("gen-"):
                update_error_log(self.conn, q["id"], q["topic"], correct, None)
        return False

    def _prompt_confidence(self, q, idx, correct, elapsed):
        wrap = ctk.CTkFrame(self.feedback_area, fg_color="transparent")
        wrap.pack(anchor="w", pady=(4, 0))
        # Kept as a handle so the follow-up prompt can remove exactly this
        # widget and nothing else in the feedback area (the explanation and
        # why-wrong card packed before it must survive).
        self._conf_prompt = wrap
        ctk.CTkLabel(wrap, text="How confident were you?", font=(FONT_BODY, 12, "bold"),
                     text_color=C.INK).pack(anchor="w")
        btnrow = ctk.CTkFrame(wrap, fg_color="transparent")
        btnrow.pack(anchor="w", pady=(6, 0))
        labels = [("Guessing", 1), ("Somewhat sure", 2), ("Confident", 3)]
        picked = {"done": False}

        def pick(level):
            # First click wins. The buttons go away before anything is
            # recorded, so a double-click (or a second click while the
            # handler runs) cannot insert a second attempts row.
            if picked["done"]:
                return
            picked["done"] = True
            self._conf_prompt = None
            try:
                wrap.destroy()
            except tk.TclError:
                pass
            self._confidence_chosen(q, idx, correct, elapsed, level)

        for lbl, lvl in labels:
            ghost_button(btnrow, lbl, lambda l=lvl: pick(l)).pack(side="left", padx=(0, 8))

    def _confidence_chosen(self, q, idx, correct, elapsed, level):
        a_irt, b_irt = q.get("a_irt", 1.0), q.get("b_irt", 0.0)
        if correct:
            mode_now = self._effective_mode()
            record_attempt(self.conn, mode_now, q["id"], q["topic"], True, self.hint_level,
                           a_irt, b_irt, elapsed, confidence=level, chosen=idx, rushing=self.ctrl_paused_escalation,
                           question=q)
            if mode_now == "pretest":
                self._queue_retest(q)
            self._mark_seen(q)
            self._update_controller(q, correct, elapsed)
            self._render_continue()
        else:
            if level == 3 or self._effective_mode() == "pretest":
                self._queue_retest(q)
            self._prompt_error_tag(q, elapsed, level)

    def _confident_miss_line(self):
        """Spec 7.5 / P6: the hypercorrection sanction and effort-reframe."""
        if not hasattr(self, "feedback_area") or not self.feedback_area.winfo_exists():
            return
        # Only promise a return that this session will actually serve: the
        # item must be in the queue (a retest missed again is not re-queued)
        # and within the per-session cap. Otherwise the sanction stands on
        # its own and the item is owed to a later session.
        q = self._current_question()
        queued = q is not None and any(m["id"] == q["id"] for m in self.missed_for_redo)
        try:
            room = (len(self.missed_for_redo) + self._retests_added) <= self._retest_cap()
        except Exception:
            room = True
        if queued and room and (self._is_learn_objective() or self.dynamic_picker):
            text = "That was a confident miss \u2014 it comes back later this session."
        else:
            text = "That was a confident miss \u2014 it comes back in a later session."
        ctk.CTkLabel(self.feedback_area, text=text,
                     font=(FONT_BODY, 12, "italic"), text_color=C.INK, anchor="w",
                     justify="left", wraplength=620).pack(anchor="w", pady=(6, 0))
        # Calibration feedback works when confidence-versus-outcome is seen
        # immediately and repeatedly, so the session's running tally goes
        # under every sanction. Counted here, where the sanction is shown,
        # because the answer paths that reach it are several.
        self._confident_misses = getattr(self, "_confident_misses", 0) + 1
        ctk.CTkLabel(self.feedback_area,
                     text=f"Confident \u00b7 missed: {self._confident_misses} this session",
                     font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w"
                     ).pack(anchor="w", pady=(2, 0))

    def _spaced_recall_line(self, q, meta=None):
        """A correct answer on an item coming back after a gap is the
        success that spacing produces and that learners under-credit
        (Soderstrom & Bjork 2015): say so, with the gap, when the item is
        a retest or a relearning item last seen two or more days ago."""
        if not hasattr(self, "feedback_area") or not self.feedback_area.winfo_exists():
            return
        if self.timed or self.exam_mode:
            return
        # A composed-plan item that is not a pretest is either a retest owed
        # from an earlier session or a skill being relearned on schedule;
        # a dynamic retest is the same thing in an engine-picked drill.
        is_return = bool((meta and not meta.get("pretest"))
                         or getattr(self, "_dynamic_retest", False))
        if not is_return:
            return
        days = self._days_since_last_exposure(q)
        if days is None or days < 2:
            return
        ctk.CTkLabel(self.feedback_area,
                     text=(f"Right \u2014 {days} days after last time; that's the kind of "
                           "recall that lasts."),
                     font=(FONT_BODY, 12, "italic"), text_color=C.INK, anchor="w",
                     justify="left", wraplength=620).pack(anchor="w", pady=(4, 0))

    def _prompt_error_tag(self, q, elapsed, confidence):
        # Remove only the confidence prompt, if one was shown. The verdict,
        # the why-wrong card, the explanation and the source were packed
        # into feedback_area just before this and are the whole point of a
        # miss -- correct-answer feedback after an error is the mechanism
        # the hypercorrection ritual relies on.
        prompt = getattr(self, "_conf_prompt", None)
        if prompt is not None:
            self._conf_prompt = None
            try:
                if prompt.winfo_exists():
                    prompt.destroy()
            except tk.TclError:
                pass
        # height=0: in phase A this frame gets no children, and an empty
        # CTkFrame otherwise keeps its 200 px default -- a blank band
        # between the explanation and the Next button.
        wrap = ctk.CTkFrame(self.feedback_area, fg_color="transparent", height=0)
        wrap.pack(anchor="w", fill="x")

        # Precomputed misconception diagnosis, if the offline enrichment
        # pipeline authored one for this item. Naming the specific error is
        # what the tutoring research finds effective -- "you inverted gross
        # and net" teaches something "incorrect" does not. This is authored
        # analysis, shown as such, and it costs one dict lookup: no model,
        # no API call, no wait.
        # Spec 7.5 adaptive ritual depth: phase A gets rationale + (for a
        # confident miss) the one-line sanction, then continues; B adds the
        # misconception card; C adds the confusion partner and the optional
        # error-type tag. Every element below is individually justified;
        # collectively, for a phase-A learner, it was dwelling on failure.
        depth = getattr(self, "phase", "C")
        if depth == "A":
            a_irt, b_irt = q.get("a_irt", 1.0), q.get("b_irt", 0.0)
            record_attempt(self.conn, self._effective_mode(), q["id"], q["topic"], False,
                           self.hint_level, a_irt, b_irt, elapsed, confidence=confidence,
                           chosen=self.selected_idx, rushing=self.ctrl_paused_escalation,
                           question=q)
            if confidence == 3:
                self._confident_miss_line()
            self._mark_seen(q)
            self._update_controller(q, False, elapsed)
            self._render_continue()
            return
        misc = enriched_misconception(q["id"], self.selected_idx)
        if misc and misc.get("diagnosis"):
            mc = card(wrap, fg_color=C.PAPER_DIM)
            mc.pack(fill="x", pady=(0, 10))
            mi = ctk.CTkFrame(mc, fg_color="transparent", height=0)
            mi.pack(fill="x", padx=14, pady=10)
            ctk.CTkLabel(mi, text="Likely misconception", font=(FONT_BODY, 10, "bold"),
                        text_color=C.BRASS_DARK, anchor="w").pack(anchor="w")
            dl = ctk.CTkLabel(mi, text=misc["diagnosis"], font=(FONT_BODY, 12),
                              text_color=C.INK, anchor="w", justify="left")
            dl.pack(anchor="w", fill="x", pady=(3, 0))
            bind_autowrap(dl, self.body, padding=60)
            if misc.get("concept"):
                ctk.CTkLabel(mi, text="Key idea: " + misc["concept"], font=(FONT_BODY, 11),
                            text_color=C.INK_DIM, anchor="w").pack(anchor="w", pady=(4, 0))

        # Confusion partner, shown INDEPENDENTLY of whether this item has an
        # authored misconception. Nesting it inside the misconception card
        # (as it was first written) meant 11 of the 16 items that HAVE a
        # confusion pair could never display it -- the data shipped but was
        # unreachable. Contrast is useful on its own: seeing the item you
        # confused this one with is often the whole correction.
        partner, why = enriched_confusion_partner(q["id"])
        if depth == "C" and partner and partner in QUIZ_BANK:
            pc = card(wrap, fg_color=C.PAPER_DIM)
            pc.pack(fill="x", pady=(0, 10))
            pi = ctk.CTkFrame(pc, fg_color="transparent", height=0)
            pi.pack(fill="x", padx=14, pady=10)
            ctk.CTkLabel(pi, text="Commonly confused with", font=(FONT_BODY, 10, "bold"),
                        text_color=C.BRASS_DARK, anchor="w").pack(anchor="w")
            wl = ctk.CTkLabel(pi, text=why, font=(FONT_BODY, 12), text_color=C.INK,
                              anchor="w", justify="left")
            wl.pack(anchor="w", fill="x", pady=(3, 0))
            bind_autowrap(wl, self.body, padding=60)
            pl = ctk.CTkLabel(pi, text="\u2192 " + QUIZ_BANK[partner]["q"][:110],
                              font=(FONT_BODY, 11), text_color=C.INK_DIM,
                              anchor="w", justify="left")
            pl.pack(anchor="w", fill="x", pady=(4, 0))
            bind_autowrap(pl, self.body, padding=60)

        # Optional Socratic follow-up. Fires only on an explicit click, and
        # only if the learner has configured their own key -- the button is
        # simply absent otherwise, so the offline path is unchanged.
        # The Socratic button no longer requires a key. The expert pool has
        # tier-0 producers that work fully offline; a key only adds the
        # frontier expert to the ranking.
        _api = get_setting(self.conn, "anthropic_api_key", "")
        if True:
            sq_holder = ctk.CTkFrame(wrap, fg_color="transparent", height=0)
            sq_holder.pack(anchor="w", fill="x", pady=(0, 8))

            def ask_socratic():
                sq_btn.configure(state="disabled", text="Thinking\u2026")
                res = {}

                def worker():
                    # ROUTED THROUGH THE EXPERT POOL rather than calling the
                    # API directly. This is what gives the routing policy
                    # real production outcomes to learn from -- previously
                    # run_with_pool() existed but was never invoked, so the
                    # router had no data and could never improve.
                    wconn = None
                    try:
                        wconn = db_connect()
                        m = enriched_misconception(q["id"], self.selected_idx)
                        diag = (m or {}).get("diagnosis")

                        def _precomputed():
                            # Tier-0: turn the authored misconception into a
                            # question. Always available, never wrong in a
                            # new way.
                            if not diag:
                                return None
                            return ("Before checking \u2014 " + diag.rstrip(".") +
                                    ". Does that match your reasoning here?")

                        def _heuristic():
                            # The floor. Generic but always present.
                            return ("Walk through why you ruled out the option "
                                    "you didn't choose \u2014 what would have "
                                    "had to be true for yours to be right?")

                        def _frontier():
                            out, err = socratic_hint(_api, q, self.selected_idx, diag)
                            return out

                        # run_plan, NOT run_with_pool. The plan layer is what
                        # applies the bounded evidence packet, the injection
                        # framing, the critic, and the abstention rule for
                        # high-risk legal items. Calling the pool directly
                        # bypassed all four -- they existed but never ran.
                        result = run_plan(
                            wconn, "hint",
                            {"precomputed": _precomputed,
                             "heuristic": _heuristic,
                             "frontier_api": _frontier},
                            question=q, allow_paid=bool(_api),
                            critic_fns={"heuristic": lambda t, pk: {"accept": True}})
                        res["out"] = result.get("output")
                        res["expert"] = result.get("label") or result.get("expert")
                        res["plan"] = result.get("plan")
                        if result.get("abstained"):
                            res["err"] = result.get("reason")
                        elif result.get("refused"):
                            res["err"] = result.get("reason")
                        elif not res["out"]:
                            res["err"] = result.get("reason") or "No expert produced a usable hint."
                        else:
                            res["err"] = None
                    except Exception as e:
                        res["out"], res["err"] = None, f"{type(e).__name__}: {e}"
                    finally:
                        if wconn is not None:
                            try:
                                wconn.close()
                            except Exception:
                                pass

                import threading
                threading.Thread(target=worker, daemon=True).start()

                def poll():
                    if "out" not in res and "err" not in res:
                        self.parent.after(120, poll)
                        return
                    if not sq_holder.winfo_exists():
                        return
                    sq_btn.configure(state="normal", text="Ask a Socratic question")
                    txt = res.get("out") or res.get("err") or "No response."
                    if res.get("out") and res.get("expert"):
                        txt = txt + f"\n\u2014 {res['expert']}"
                    lb = ctk.CTkLabel(sq_holder, text="\u201c" + txt + "\u201d",
                                      font=(FONT_BODY, 12, "italic"),
                                      text_color=(C.INK if res.get("out") else C.INK_DIM),
                                      anchor="w", justify="left")
                    lb.pack(anchor="w", fill="x", pady=(6, 0))
                    bind_autowrap(lb, self.body, padding=60)

                self.parent.after(120, poll)

            sq_btn = ghost_button(sq_holder, "Ask a Socratic question", ask_socratic)
            sq_btn.pack(anchor="w")

        if depth != "C":
            # Phase B: the tag is valuable to the author and attribute_error,
            # not to the learner yet. Record and move on.
            a_irt, b_irt = q.get("a_irt", 1.0), q.get("b_irt", 0.0)
            record_attempt(self.conn, self._effective_mode(), q["id"], q["topic"], False,
                           self.hint_level, a_irt, b_irt, elapsed, confidence=confidence,
                           chosen=self.selected_idx, rushing=self.ctrl_paused_escalation,
                           question=q)
            if confidence == 3:
                self._confident_miss_line()
            self._mark_seen(q)
            self._update_controller(q, False, elapsed)
            self._render_continue()
            return
        # Phase C: the miss is recorded NOW, exactly as phases A/B do, and
        # the continue button is rendered alongside the tags. The tag is
        # genuinely optional -- a side effect that annotates the row just
        # written -- so navigating away or closing the app can no longer
        # lose the attempt, and the learner is not held hostage to a
        # self-attribution the label says they may skip.
        a_irt, b_irt = q.get("a_irt", 1.0), q.get("b_irt", 0.0)
        mode_now = self._effective_mode()
        # record_attempt returns the new row's id, so the tag prompt can
        # amend exactly that row without re-querying by question id.
        attempt_id = record_attempt(self.conn, mode_now, q["id"], q["topic"], False,
                                    self.hint_level, a_irt, b_irt, elapsed,
                                    confidence=confidence, chosen=self.selected_idx,
                                    rushing=self.ctrl_paused_escalation, question=q)
        if confidence == 3:
            self._confident_miss_line()
        self._mark_seen(q)
        self._update_controller(q, False, elapsed)

        tag_box = ctk.CTkFrame(wrap, fg_color="transparent")
        tag_box.pack(anchor="w", fill="x")
        ctk.CTkLabel(tag_box, text="Why did you miss it? (optional \u2014 drives the error log)",
                     font=(FONT_BODY, 12, "bold"), text_color=C.INK).pack(anchor="w")
        btnrow = ctk.CTkFrame(tag_box, fg_color="transparent")
        btnrow.pack(anchor="w", pady=(6, 0))
        tags = [("Content \u2014 didn't know it", "Content"),
                ("Strategy \u2014 wrong approach / trap", "Strategy"),
                ("Timing \u2014 rushed / ran out of time", "Timing")]
        chosen = {"done": False}

        def choose(tag):
            # First click wins; the buttons are gone before the write so a
            # double-click cannot tag twice or stack anything.
            if chosen["done"]:
                return
            chosen["done"] = True
            try:
                tag_box.destroy()
            except tk.TclError:
                pass
            # Hybrid attribution: cross-check the self-tag against behavioural
            # evidence (response-time z, confidence, hint use). Previously
            # attribute_error() existed but had ZERO call sites -- the app
            # recorded only the raw self-report, which the research
            # specifically warns is unreliable right after a miss. The
            # self-tag is still what gets STORED (it is the user's call);
            # the behavioural read is surfaced when it disagrees, so the
            # user can reconsider rather than being silently overridden.
            final_tag = tag
            try:
                cause, conf, why = attribute_error(
                    self.conn, q, False, elapsed, confidence, tag,
                    hint_level=self.hint_level,
                    baselines=self.ctrl_baselines,
                    regime=getattr(self, "ctrl_regime", "calm"))
            except Exception:
                cause, conf, why = None, 0.0, []
            # Annotate the row already written -- never a second INSERT.
            # The error log took the "Content" default when the miss was
            # recorded; bring it in line with the learner's own call.
            try:
                if attempt_id is not None:
                    self.conn.execute("UPDATE attempts SET error_type=? WHERE id=?",
                                      (final_tag, attempt_id))
                if mode_now != "pretest" and not str(q["id"]).startswith("gen-"):
                    self.conn.execute(
                        "UPDATE error_log SET error_type=? WHERE question_id=? AND active=1",
                        (final_tag, q["id"]))
                self.conn.commit()
            except sqlite3.Error as e:
                _audit(self.conn, "error_tag_update_failed",
                       f"question_id={q['id']} {type(e).__name__}: {e}")
            ctk.CTkLabel(wrap, text=f"Tagged: {final_tag}", font=(FONT_BODY, 11),
                         text_color=C.INK_DIM, anchor="w").pack(anchor="w", pady=(2, 0))
            if cause and cause != "Uncertain" and cause != tag and conf >= 0.5:
                self._show_attribution_note(cause, conf, why, tag)

        for lbl, tag in tags:
            ghost_button(btnrow, lbl, lambda t=tag: choose(t)).pack(side="left", padx=(0, 8))
        self._render_continue()

    def _show_attribution_note(self, cause, conf, why, self_tag):
        """Surface a behavioural second opinion when it disagrees with the
        self-tag. Advisory only -- never overrides the user's own call."""
        if not hasattr(self, "feedback_area") or not self.feedback_area.winfo_exists():
            return
        box = card(self.feedback_area, fg_color=C.PAPER_DIM)
        box.pack(fill="x", pady=(8, 0))
        inner = ctk.CTkFrame(box, fg_color="transparent", height=0)
        inner.pack(fill="x", padx=16, pady=11)
        ctk.CTkLabel(inner, text="SECOND OPINION", font=(FONT_BODY, 10, "bold"),
                     text_color=C.BRASS_DARK, anchor="w").pack(anchor="w")
        msg = (f"You tagged this {self_tag}, but your answering behaviour looks more like "
               f"{cause}.")
        ml = ctk.CTkLabel(inner, text=msg, font=(FONT_BODY, 12), text_color=C.INK,
                          anchor="w", justify="left")
        ml.pack(anchor="w", fill="x", pady=(3, 3))
        bind_autowrap(ml, self.body, padding=100)
        for reason in (why or [])[:2]:
            ctk.CTkLabel(inner, text="  \u00b7  " + reason, font=(FONT_BODY, 11),
                         text_color=C.INK_DIM, anchor="w", justify="left").pack(anchor="w")

    def _prompt_redo_tag(self, q, elapsed):
        # The verdict and explanation packed just before this stay; only the
        # prompt is added beneath them.
        wrap = ctk.CTkFrame(self.feedback_area, fg_color="transparent")
        wrap.pack(anchor="w", fill="x")
        ctk.CTkLabel(wrap, text="You knew it untimed \u2014 was that rushing, or a wrong initial approach?",
                     font=(FONT_BODY, 12, "bold"), text_color=C.INK, wraplength=600, justify="left").pack(anchor="w")
        btnrow = ctk.CTkFrame(wrap, fg_color="transparent")
        btnrow.pack(anchor="w", pady=(6, 0))
        chosen = {"done": False}

        def choose(tag):
            # First click wins; the buttons are gone before the write so a
            # double-click cannot insert a second attempts row or a second
            # Next button.
            if chosen["done"]:
                return
            chosen["done"] = True
            try:
                wrap.destroy()
            except tk.TclError:
                pass
            a_irt, b_irt = q.get("a_irt", 1.0), q.get("b_irt", 0.0)
            record_attempt(self.conn, self.record_mode, q["id"], q["topic"], True, 0,
                           a_irt, b_irt, elapsed, error_type=tag,
                           chosen=self.selected_idx, rushing=self.ctrl_paused_escalation,
                           question=q)
            self._update_controller(q, True, elapsed)
            self._render_continue()

        ghost_button(btnrow, "Timing (rushed)", lambda: choose("Timing")).pack(side="left", padx=(0, 8))
        ghost_button(btnrow, "Strategy (wrong approach)", lambda: choose("Strategy")).pack(side="left", padx=(0, 8))
        # A neutral exit: a learner who guessed right, or simply does not
        # know, must not be forced to invent a cause -- a made-up tag is
        # worse for the error log than none at all.
        ghost_button(btnrow, "Not sure / guessed", lambda: choose(None)).pack(side="left")

    def _update_controller(self, q, correct, elapsed):
        """Update the rolling behavioural window and decide whether a cue is
        warranted. Never blocks; never diagnoses."""
        # Refresh baselines periodically rather than caching once at session
        # start. Two reasons: (a) a first-ever timed exam begins with NO timed
        # history, so a once-only read leaves the controller permanently blind
        # during the very session where panic is likeliest; (b) evidence
        # accumulated earlier in this same session should count.
        need_refresh = (
            self.ctrl_baselines is None
            or (len(self.ctrl_window) and len(self.ctrl_window) % 5 == 0)
        )
        if need_refresh:
            try:
                self.ctrl_regime = baseline_regime_for_mode(self.record_mode)
                self.ctrl_baselines = personal_baselines(self.conn, regime=self.ctrl_regime)
            except Exception:
                self.ctrl_regime = "calm"
                self.ctrl_baselines = {}
        z = None
        try:
            # Always compute z. When no personal baseline exists yet,
            # timing_z falls back to the generic exam-pace reference and
            # reports basis='default' -- previously an empty baseline dict
            # was falsy here, so z stayed None and the detector was mute.
            z, basis = timing_z(self.conn, q, elapsed, self.ctrl_baselines or None,
                                regime=getattr(self, "ctrl_regime", "calm"))
            self.ctrl_basis = basis
        except Exception:
            z = None
        # The raw seconds ride along beside z: rt_variability is about the
        # SPREAD of the times themselves, which a per-item z (each divided by
        # its own difficulty's spread) has already normalised away.
        try:
            _rt = float(elapsed) if elapsed and float(elapsed) > 0 else None
        except (TypeError, ValueError):
            _rt = None
        self.ctrl_window.append({"correct": bool(correct), "z": z, "rt": _rt})
        self.ctrl_window = self.ctrl_window[-CONTROLLER_WINDOW:]
        self.ctrl_consecutive_wrong = 0 if correct else self.ctrl_consecutive_wrong + 1

        # measure recovery after a previous cue
        if self.ctrl_active_id is not None:
            self.ctrl_answers_since_cue += 1
            self.ctrl_correct_since_cue += 1 if correct else 0
            if self.ctrl_answers_since_cue >= 3:
                try:
                    close_intervention(self.conn, self.ctrl_active_id,
                                       self.ctrl_correct_since_cue / self.ctrl_answers_since_cue)
                except Exception:
                    pass
                self.ctrl_active_id = None
                self.ctrl_paused_escalation = False

        idx_now = len(self.ctrl_window) + self.index
        try:
            _sliding_acc = active_threshold(self.conn, "sliding_acc", 0.50)
        except Exception:
            _sliding_acc = 0.50
        signal, message = compute_session_signal(self.ctrl_window, bool(self.ctrl_baselines),
                                                 basis=getattr(self, "ctrl_basis", "personal"),
                                                 sliding_acc=_sliding_acc,
                                                 expected_p=(self.composed_plan or {}).get("planned_mean_p"))
        if not signal:
            # Nothing has gone wrong yet -- which is exactly when drifting
            # attention is worth naming, since the dispersion leads the error
            # by several items. Checked only here, so it can never pre-empt a
            # signal driven by something that has already happened.
            try:
                _rt_cv = active_threshold(self.conn, "rt_variability_cv", 0.75)
            except Exception:
                _rt_cv = 0.75
            signal, message = rt_variability_signal(self.ctrl_window, _rt_cv)
        if not signal:
            return
        measuring = (self.timed or self.exam_mode
                     or str(self.record_mode).startswith("diagnostic"))
        # two_wrong is a quiet target lift, not a cue: it has no UI, so it
        # neither waits for nor consumes the cue cooldown. A dynamic
        # session expresses it through learning_target_p() reading
        # ctrl_consecutive_wrong on the next pick; a composed plan is a
        # fixed list, so the lift has to re-pick the next work item (see
        # _apply_controller_action) -- and be logged, or it can never be
        # canaried. One lift per rough patch: while a previous one is
        # still being measured, nothing more fires.
        if signal == "two_wrong":
            if not self.composed_plan or measuring or self.ctrl_active_id is not None:
                return
        else:
            if idx_now - self.ctrl_last_cue_at < CONTROLLER_COOLDOWN:
                return
            # Ask what this signal has actually done for this learner before
            # firing it again. Cues measured as unhelpful (or as preceding
            # abandonment) fire far less often; see cue_policy().
            fire, _w = should_fire_cue(self.conn, signal)
            if not fire:
                self.ctrl_last_cue_at = idx_now   # respect cooldown even when suppressed
                return
        # Spec 7.10: signal -> ACTION, governed per (signal, action).
        # Timed/measurement sessions keep cue-only: the ladder exists to
        # measure, and adapting difficulty mid-simulation would corrupt it.
        if measuring:
            action = "cue"
        else:
            try:
                action = controller_action_for(self.conn, signal, getattr(self, "phase", "A"))
            except Exception:
                action = "cue"
        if signal == "two_wrong" and action != "lift_target":
            return                       # harm-learned fallback: there is no cue text to degrade to
        # A quiet lift does not hold the cue cooldown, so a cue can follow
        # it within its recovery window; close the lift on what was
        # answered so far rather than orphaning its row unresolved.
        if self.ctrl_active_id is not None:
            self._resolve_pending_intervention("superseded")
        acc_before = sum(1 for w in self.ctrl_window if w["correct"]) / len(self.ctrl_window)
        if signal != "two_wrong":
            self.ctrl_last_cue_at = idx_now
        self.ctrl_paused_escalation = True
        self.ctrl_answers_since_cue = 0
        self.ctrl_correct_since_cue = 0
        self.ctrl_action = action
        try:
            self.ctrl_active_id = log_intervention(self.conn, self.record_mode, signal,
                                                    self.index, acc_before, action=action)
        except Exception:
            self.ctrl_active_id = None
        self._apply_controller_action(action, signal, message, q)

    def _apply_controller_action(self, action, signal, message, q):
        """One action per item boundary. Every branch degrades to the cue
        if its precondition is missing (no authored view, not a composed
        session, etc.) rather than doing nothing."""
        theta = self.theta
        if theta is None:
            try:
                theta = current_theta(self.conn)
            except Exception:
                theta = 0.0

        def p_of(x):
            return irt_p3(theta, x.get("a_irt", 1.0), x.get("b_irt", 0.0), x.get("c_irt", 0.2))

        if action == "lift_target":
            # A dynamic session lifts through learning_target_p on its next
            # pick. A composed plan is fixed, so the next unplayed work item
            # is re-picked at the lifted target: the closest unseen item of
            # the same skill that is at least as likely to land as the one
            # planned. Nothing is swapped when the planned item already is
            # the best the bank offers -- and then the debrief says nothing.
            swapped = False
            if self.composed_plan:
                try:
                    t = learning_target_p(self.conn, getattr(self, "phase", "A"),
                                          self.index + 1, len(self.questions),
                                          {"consecutive_wrong": 2}, theta=theta)
                    used = {qq["id"] for qq in self.questions if qq}
                    for j in range(self.index + 1, len(self.questions)):
                        meta = self.plan_meta[j] if j < len(self.plan_meta) else None
                        if (meta is None or meta.get("movement") != "work"
                                or meta.get("pretest") or meta.get("retest")
                                or self.answers[j] is not None):
                            continue
                        sid = meta.get("skill")
                        cur = self.questions[j]
                        cands = [x for x in items_for_skill(sid) if sid and x["id"] not in used
                                 and p_of(x) >= p_of(cur) and p_of(x) >= t - 0.06]
                        if cands:
                            pick = min(cands, key=lambda x: abs(p_of(x) - t))
                            self.questions[j] = pick
                            self.plan_meta[j] = dict(meta, q=pick)
                            swapped = True
                        break
                except Exception as e:
                    _audit(self.conn, "lift_target_repick_failed", f"{type(e).__name__}: {e}")
            if not swapped:
                self.ctrl_action = "cue"
            return
        if action == "cue":
            self._show_cue(signal, message)
            return
        if action == "cue_then_solid_item":
            self._show_cue(signal, message)
            # The next composed item is swapped for one from a solid skill
            # at a high success target, if one is available. When nothing
            # was swapped the learner only saw the cue, and the debrief
            # must say so rather than describe an intervention that did
            # not happen.
            swapped = False
            try:
                st = skill_status(self.conn)
                for sid in st["solid"]:
                    cands = [x for x in items_for_skill(sid)
                             if x["id"] not in {qq["id"] for qq in self.questions if qq}]
                    if cands and self.composed_plan and self.index + 1 < len(self.questions):
                        pick = max(cands, key=p_of)   # the steadiest item, not the first listed
                        self.questions[self.index + 1] = pick
                        self.plan_meta[self.index + 1] = {"q": pick, "movement": "work",
                                                          "pretest": False, "skill": sid}
                        swapped = True
                        break
            except Exception:
                pass
            if not swapped:
                self.ctrl_action = "cue"
            return
        if action == "offer_pause":
            if hasattr(self, "feedback_area") and self.feedback_area.winfo_exists():
                box = card(self.feedback_area, fg_color=C.PAPER_DIM)
                box.pack(fill="x", pady=(8, 0))
                inner = ctk.CTkFrame(box, fg_color="transparent", height=0)
                inner.pack(fill="x", padx=16, pady=12)
                # What rt_variability is reporting is attention going in and
                # out, not this item being hard, so what it offers is a short
                # break -- the end of the session stays available underneath,
                # but it is not what is being suggested. Nothing here blocks
                # the next question either way.
                drift = (signal == "rt_variability")
                lead = ctk.CTkLabel(
                    inner,
                    text=(RT_VARIABILITY_CUE if drift
                          else "You can pause here \u2014 what you've done is saved."),
                    font=(FONT_BODY, 12), text_color=C.INK, anchor="w", justify="left")
                lead.pack(anchor="w", fill="x")
                if drift:
                    bind_autowrap(lead, self.body, padding=100)
                    left = ctk.CTkLabel(inner, text="", font=(FONT_BODY, 11),
                                        text_color=C.INK_DIM, anchor="w")
                    left.pack(anchor="w", pady=(4, 0))
                    remaining = {"s": 0}

                    def tick():
                        # Purely a countdown to look away from: the widget may
                        # be gone the moment the learner presses Next, so every
                        # tick re-checks rather than assuming it survives.
                        if not left.winfo_exists():
                            return
                        if remaining["s"] <= 0:
                            left.configure(text="Ready when you are.")
                            return
                        left.configure(text=f"{remaining['s']}s")
                        remaining["s"] -= 1
                        left.after(1000, tick)

                    def take_thirty():
                        remaining["s"] = 30
                        tick()
                    ghost_button(inner, "Take 30 seconds",
                                 take_thirty).pack(anchor="w", pady=(6, 0))
                # finish() logs the session under kind "pause" (not
                # "complete"), so a session cut short here neither counts
                # as dwell nor feeds its partial accuracy to the phase gate.
                def pause():
                    self._pause_requested = True
                    self.finish()
                ghost_button(inner, "Pause the session", pause).pack(anchor="w", pady=(6, 0))
            return
        if action == "close_early":
            if self.composed_plan:
                self._closed_early = True
                # go_next jumps to the plan's Close item. When the plan has
                # none left, the promise below is kept by truncating the
                # list instead: the current item plus two more, then done
                # (retests owed are still appended by go_next afterwards).
                has_close = any(
                    j < len(self.plan_meta) and self.plan_meta[j].get("movement") == "close"
                    for j in range(self.index + 1, len(self.questions)))
                if not has_close and len(self.questions) > self.index + 3:
                    keep = self.index + 3
                    self.questions = self.questions[:keep]
                    self.plan_meta = self.plan_meta[:keep]
                n_more = 1 if has_close else max(0, len(self.questions) - self.index - 1)
                more = {0: "this is the last one", 1: "one more, then done"}.get(
                    n_more, "two more, then done")
                if hasattr(self, "feedback_area") and self.feedback_area.winfo_exists():
                    ctk.CTkLabel(self.feedback_area,
                                 text=f"Wrapping this one up a little early \u2014 {more}.",
                                 font=(FONT_BODY, 12, "italic"), text_color=C.INK_DIM,
                                 anchor="w").pack(anchor="w", pady=(6, 0))
            else:
                self.ctrl_action = "cue"
                self._show_cue(signal, message)
            return
        if action == "scaffold":
            body = None
            try:
                for sid in Q_MATRIX.get(q["id"], []):
                    body = skill_view(self.conn, sid, "rule")
                    if body:
                        break
            except Exception:
                body = None
            if body and hasattr(self, "feedback_area") and self.feedback_area.winfo_exists():
                box = card(self.feedback_area, fg_color=C.PAPER_DIM)
                box.pack(fill="x", pady=(8, 0))
                inner = ctk.CTkFrame(box, fg_color="transparent", height=0)
                inner.pack(fill="x", padx=16, pady=12)
                ctk.CTkLabel(inner, text="THE RULE", font=(FONT_BODY, 11, "bold"),
                             text_color=C.INK, anchor="w").pack(anchor="w")
                bl = ctk.CTkLabel(inner, text=body, font=(FONT_BODY, 12), text_color=C.INK,
                                  anchor="w", justify="left")
                bl.pack(anchor="w", fill="x", pady=(3, 0))
                bind_autowrap(bl, self.body, padding=100)
            else:
                self.ctrl_action = "cue"
                self._show_cue(signal, message)   # no authored view yet: cue-only
            return
        self._show_cue(signal, message)

    def _show_cue(self, signal, message):
        """One short, dismissible, operational cue. No labels about the
        learner, no motivational language, no blocking."""
        if not hasattr(self, "feedback_area") or not self.feedback_area.winfo_exists():
            return
        box = card(self.feedback_area, fg_color=C.PAPER_DIM)
        box.pack(fill="x", pady=(8, 0))
        inner = ctk.CTkFrame(box, fg_color="transparent", height=0)
        inner.pack(fill="x", padx=16, pady=12)
        head = ctk.CTkFrame(inner, fg_color="transparent", height=0)
        head.pack(fill="x")
        # 11 px in INK: BRASS_DARK on PAPER_DIM is 3.9:1, under AA for text
        # this small, and this header is the one thing a cue must make legible.
        ctk.CTkLabel(head, text="RESET", font=(FONT_BODY, 11, "bold"),
                     text_color=C.INK, anchor="w").pack(side="left")
        ctk.CTkButton(head, text="\u2715", width=24, height=22, corner_radius=6,
                      fg_color="transparent", hover_color=C.PAPER_LINE,
                      text_color=C.INK_DIM, font=(FONT_BODY, 11),
                      command=box.destroy).pack(side="right")
        ml = ctk.CTkLabel(inner, text=message, font=(FONT_BODY, 12), text_color=C.INK,
                          anchor="w", justify="left")
        ml.pack(anchor="w", fill="x", pady=(3, 6))
        bind_autowrap(ml, self.body, padding=100)
        for step in procedural_cue_steps(self.exam_mode):
            ctk.CTkLabel(inner, text="  \u00b7  " + step, font=(FONT_BODY, 11),
                         text_color=C.INK, anchor="w").pack(anchor="w")

    def _render_continue(self, is_last=False):
        q = self._current_question()
        if (not self.timed) and self.selected_idx is not None and not str(q["id"]).startswith("gen-"):
            _tarea = ctk.CTkFrame(self.feedback_area, fg_color="transparent", height=0)
            _tarea.pack(anchor="w", fill="x", pady=(6, 0))
            ghost_button(_tarea, "Talk it through",
                         lambda a=_tarea, qq=q: render_tutor_panel(self, a, qq, before_answer=False)).pack(anchor="w")
        row = ctk.CTkFrame(self.feedback_area, fg_color="transparent")
        row.pack(anchor="w", pady=(6, 0))
        is_final = is_last or (not self.dynamic_picker and self.index >= len(self.questions) - 1)
        label = "Finish" if is_final else "Next \u2192"
        self._continue_btn = primary_button(row, label, self.go_next)
        self._continue_btn.pack(side="left")
        hint_lbl = ctk.CTkLabel(row, text="press Enter", font=(FONT_BODY, 10), text_color=C.INK_DIM)
        hint_lbl.pack(side="left", padx=(10, 0))

    def _render_tutor_button(self, q):
        """Opt-in Claude tutor. Runs on a worker thread so the UI never
        blocks on the network, and only ever fires on an explicit click."""
        tutor_area = ctk.CTkFrame(self.feedback_area, fg_color="transparent", height=0)
        tutor_area.pack(anchor="w", fill="x", pady=(6, 0))
        convo = {"history": None}

        def ask(followup=None, container=tutor_area):
            for w in container.winfo_children():
                w.destroy()
            status = ctk.CTkLabel(container, text="Asking the tutor...", font=(FONT_BODY, 12),
                                  text_color=C.INK_DIM, anchor="w")
            status.pack(anchor="w")
            holder = {}

            # Resolve the key on the UI thread, then hand only the string to
            # the worker -- never the connection.
            api_key = get_setting(self.conn, "anthropic_api_key", "")
            gpu = gpu_config(self.conn)

            def worker():
                reply, err, sent = ask_tutor(api_key, q, self.selected_idx,
                                             followup=followup, history=convo["history"],
                                             return_messages=True, transport=gpu)
                holder["reply"], holder["err"] = reply, err
                if reply and not err:
                    # Keep the whole exchange so the next follow-up is a real
                    # continuation rather than a stateless re-ask.
                    convo["history"] = list(sent) + [{"role": "assistant", "content": reply}]

            import threading
            t = threading.Thread(target=worker, daemon=True)
            t.start()

            def poll():
                if t.is_alive():
                    container.after(200, poll)
                    return
                if not container.winfo_exists():
                    return
                for w in container.winfo_children():
                    w.destroy()
                if holder.get("err"):
                    ctk.CTkLabel(container, text=holder["err"], font=(FONT_BODY, 12),
                                 text_color=C.STAMP, anchor="w", justify="left",
                                 wraplength=620).pack(anchor="w")
                    return
                reply = holder.get("reply") or "(no response)"
                box = card(container, fg_color=C.PAPER_DIM)
                box.pack(fill="x", pady=(4, 6))
                lbl = ctk.CTkLabel(box, text=reply, font=(FONT_BODY, 12), text_color=C.INK,
                                   anchor="w", justify="left")
                lbl.pack(anchor="w", padx=14, pady=12, fill="x")
                bind_autowrap(lbl, self.body, padding=90)
                ctk.CTkLabel(container, text="Tutor responses are AI-generated. The authored "
                             "explanation above is the authoritative source.",
                             font=(FONT_BODY, 10), text_color=C.INK_DIM, anchor="w").pack(anchor="w")
                frow = ctk.CTkFrame(container, fg_color="transparent")
                frow.pack(anchor="w", fill="x", pady=(6, 0))
                fentry = styled_entry(frow, width=380, font=(FONT_BODY, 12),
                                      placeholder_text="Ask a follow-up...")
                fentry.pack(side="left", padx=(0, 8))
                ghost_button(frow, "Send",
                             lambda: ask(fentry.get().strip() or None)).pack(side="left")

            poll()

        ghost_button(tutor_area, "Ask the tutor why", lambda: ask()).pack(anchor="w")

    def go_next(self):
        if self.destroyed:
            return
        if self.dynamic_picker:
            # Terminate once the target item count is reached OR the CAT
            # stopping rule (precision / confident pass-fail classification)
            # has already fired -- without this check the session never ends
            # itself: it just keeps serving items from the remaining pool
            # forever, and the "Finish"-labeled button on the last item was
            # cosmetic only.
            if len(self.dynamic_seen) >= self.dynamic_target or self.stop_reason:
                # Spec 7.6: same-session hypercorrection retest before the
                # session ends -- the interpolated test that blocks the
                # return of confident errors; also where a pretest scores.
                cap = int(active_threshold(self.conn, "retest_max_per_session", 3))
                if self.missed_for_redo and self._dynamic_retests_served < cap:
                    q = self.missed_for_redo.pop(0)
                    self._dynamic_retest = True
                    self._dynamic_retests_served += 1
                    self._retests_added += 1
                    self.dynamic_target += 1
                    # let it be served again: remove from dynamic_seen so
                    # the selector isn't consulted, we set it directly
                    self._current_dynamic_q = q
                    if q["id"] in self.dynamic_seen:
                        self.dynamic_seen.remove(q["id"])
                    self.render_question()
                    return
                self.finish()
                return
            self._dynamic_retest = False
            self._load_current_question()
            self.render_question()
            return
        if self.index >= len(self.questions) - 1:
            # Spec 7.6: the same-session retest is owed by EVERY learn
            # session that promised it on a confident miss -- Practice
            # Quiz and topic drills as much as the composed plan. Timed and
            # diagnostic sessions measure, so they never append.
            if self._is_learn_objective() and self._append_retests():
                self.index += 1
                self.render_question()
                return
            self.finish()
        else:
            if self._closed_early:
                # Controller "close_early" (phase A sliding): skip the rest of
                # Movement 2 and proceed straight to Close.
                for j in range(self.index + 1, len(self.questions)):
                    m = self.plan_meta[j] if j < len(self.plan_meta) else None
                    if m and m.get("movement") == "close":
                        self.index = j
                        self._closed_early = False
                        self.render_question()
                        return
                self._closed_early = False
            self.index += 1
            self.render_question()

    def go_back(self):
        if self.index > 0:
            self.index -= 1
            self.render_question()

    def _unanswered_indices(self):
        if self.dynamic_picker:
            return []
        return [i for i in range(len(self.questions))
                if i < len(self.answers) and self.answers[i] is None]

    def _confirm_submit(self):
        """One stray click on "Submit now" must not end a 43-minute timed
        test with items still blank. Ask only when something IS blank; a
        complete set submits without ceremony."""
        n = len(self._unanswered_indices())
        if n == 0:
            return True
        from tkinter import messagebox
        return bool(messagebox.askyesno(
            "Submit with unanswered items?",
            f"{n} question{'s' if n != 1 else ''} still unanswered "
            f"— {'they' if n != 1 else 'it'} will count as wrong.\n\nSubmit anyway?",
            parent=self.app))

    def submit_now(self):
        if self.exam_mode:
            self.show_review_screen()
        elif self._confirm_submit():
            self.finish()

    def _update_progress_bar(self, idx_n, total_n):
        try:
            if not self.progress_track.winfo_exists():
                return
            self.progress_track.update_idletasks()
            w = self.progress_track.winfo_width()
            if w <= 1:
                self.progress_track.after(60, lambda: self._update_progress_bar(idx_n, total_n))
                return
            frac = max(0.0, min(1.0, (idx_n - 1) / max(1, total_n)))
            self.progress_fill.configure(width=max(2, int(w * frac)))
        except Exception:
            pass

    def _build_confidence_strip(self):
        """A single quiet row offering optional confidence capture during a
        timed session. Deliberately non-blocking and unobtrusive: it never
        gates the answer, carries no default selection, and leaving it alone
        simply records nothing. Anything more intrusive would change the
        pacing behaviour the timing baselines exist to measure, which would
        corrupt the very signal it is meant to complement."""
        self._conf_strip = ctk.CTkFrame(self.body, fg_color="transparent", height=0)
        self._conf_strip.pack(anchor="w", fill="x", pady=(8, 0))
        ctk.CTkLabel(self._conf_strip, text="Confidence (optional):", font=(FONT_BODY, 11),
                    text_color=C.INK_DIM, anchor="w").pack(side="left", padx=(0, 8))
        self._conf_chips = {}
        # 11 px INK on PAPER_LINE: INK_DIM on that ground is 3.9:1, under AA
        # for chips this small, and the strip is only worth using if it can
        # be read at a glance.
        for lvl, label, key in [(1, "Guessing", "J"), (2, "Somewhat sure", "K"), (3, "Confident", "L")]:
            chip = ctk.CTkButton(self._conf_strip, text=f"{label}  ({key})",
                                 font=(FONT_BODY, 11), height=26, width=124,
                                 corner_radius=13, fg_color=C.PAPER_LINE,
                                 hover_color=C.BRASS, text_color=C.INK,
                                 command=lambda l=lvl: self._set_confidence(l))
            chip.pack(side="left", padx=(0, 6))
            self._conf_chips[lvl] = chip
        self._refresh_confidence_strip()

    def _set_confidence(self, level):
        if self.revealed:
            return
        self.pending_confidence = level
        self._refresh_confidence_strip()

    def _refresh_confidence_strip(self):
        chips = getattr(self, "_conf_chips", None)
        if not chips:
            return
        for lvl, chip in chips.items():
            try:
                if not chip.winfo_exists():
                    continue
                if self.pending_confidence == lvl:
                    chip.configure(fg_color=C.BRASS, text_color="#221A0C")
                else:
                    chip.configure(fg_color=C.PAPER_LINE, text_color=C.INK)
            except Exception:
                pass

    def handle_key(self, event):
        """A-D / 1-4 select an answer, Enter advances, F flags, C opens the
        calculator. Keyboard-first is how people actually work through a
        long question set. This is the ONLY key handler for a session; it
        is reached through TrainerApp._on_global_key, which has already
        refused keys typed into a text field."""
        if self.destroyed:
            return
        ch = (event.char or "").lower()
        key = (event.keysym or "").lower()
        # Modifier, arrow, function and dead keys arrive with an EMPTY char,
        # and `"" in "abcd"` is True with index 0 -- every such key would
        # otherwise answer "A". Only a single printable character counts.
        if len(ch) != 1:
            ch = ""
        # Keys typed with the calculator in front belong to the calculator,
        # not the exam behind it.
        calc = getattr(self, "calc_window", None)
        if calc is not None:
            try:
                if calc.winfo_exists() and str(getattr(event, "widget", "")).startswith(str(calc)):
                    return
            except tk.TclError:
                pass

        if key in ("return", "kp_enter"):
            if self.revealed:
                nxt = getattr(self, "_continue_btn", None)
                if nxt is not None and nxt.winfo_exists():
                    nxt.invoke()
                    return
                if self.timed:
                    # A timed reveal has its own auto-advance queued; a
                    # second go_next here would skip an item.
                    return
                self.go_next()
            return

        # Confidence under pressure: J/K/L rather than 1/2/3, because 1-4
        # are already bound to answer selection -- reusing them would make
        # every confidence keypress also submit an answer. J/K/L sit under
        # the right hand on the home row and are otherwise unbound.
        if self.pressure_confidence and not self.revealed and ch in ("j", "k", "l"):
            self.pending_confidence = {"j": 1, "k": 2, "l": 3}[ch]
            self._refresh_confidence_strip()
            return

        if self.exam_mode and ch == "f":
            self.toggle_flag()
            return
        if self.exam_mode and ch == "c":
            self.open_calculator()
            return

        if self.revealed:
            return
        if self.allow_hints and ch == "h":
            self.on_hint_click()
            return
        idx = None
        if ch and ch in "abcd":
            idx = "abcd".index(ch)
        elif ch and ch in "1234":
            idx = int(ch) - 1
        if idx is not None and idx < len(getattr(self, "option_buttons", ())):
            row = self.option_buttons[idx]
            try:
                alive = row.winfo_exists()
            except tk.TclError:
                alive = False
            # The review screen tears the option rows down while the session
            # (and this handler) stay alive; there is nothing to answer there.
            if alive and not getattr(row, "_disabled", False):
                self.on_option_click(idx)

    def _cancel_pending_advance(self):
        aid = getattr(self, "_advance_after_id", None)
        if aid:
            try:
                self.parent.after_cancel(aid)
            except Exception:
                pass
            self._advance_after_id = None

    def show_review_screen(self):
        """Mirrors the real exam's review step: see everything unanswered or
        flagged before committing, and jump straight back to any of it."""
        self._cancel_pending_advance()
        for w in self.parent.winfo_children():
            w.destroy()
        # The clock keeps running through review, exactly as on exam day,
        # so it has to stay VISIBLE here: _tick updates whatever
        # self.timer_lbl points at, and the old label died with the chrome.
        top_row = ctk.CTkFrame(self.parent, fg_color="transparent")
        top_row.pack(fill="x", padx=32, pady=(28, 0))
        timer_box = ctk.CTkFrame(top_row, fg_color="transparent")
        timer_box.pack(side="right")
        self.timer_lbl = ctk.CTkLabel(timer_box, text="", font=(FONT_MONO, 14, "bold"),
                                      text_color=C.NAVY)
        self.timer_lbl.pack(anchor="e")
        self.pace_lbl = ctk.CTkLabel(timer_box, text="", font=(FONT_BODY, 10),
                                     text_color=C.INK_DIM)
        self.pace_lbl.pack(anchor="e")
        if self.timed and self.total_seconds:
            remaining = max(0, self.total_seconds - (time.monotonic() - self.session_start))
            mins, secs = int(remaining // 60), int(remaining % 60)
            self.timer_lbl.configure(text=f"⏱ {mins}:{secs:02d}",
                                     text_color=(C.STAMP if remaining < 60 else C.NAVY))
        wrap = ctk.CTkScrollableFrame(self.parent, fg_color="transparent")
        wrap.pack(fill="both", expand=True, padx=32, pady=(4, 28))
        section_title(wrap, "Review before submitting",
                      "Anything unanswered or flagged is listed here.").pack(anchor="w", pady=(0, 16))

        unanswered = [i for i in range(len(self.questions)) if self.answers[i] is None]
        flagged = sorted(self.flagged)

        chips = ctk.CTkFrame(wrap, fg_color="transparent")
        chips.pack(fill="x", pady=(0, 16))
        stat_chip(chips, "Answered", f"{len(self.questions) - len(unanswered)}/{len(self.questions)}").pack(side="left", padx=(0, 10))
        stat_chip(chips, "Unanswered", str(len(unanswered)),
                  value_color=(C.STAMP if unanswered else C.CREAM)).pack(side="left", padx=10)
        stat_chip(chips, "Flagged", str(len(flagged))).pack(side="left", padx=10)

        def jump(i):
            self.index = i
            self._build_chrome()
            self.render_question()

        def section(title, idxs, color):
            if not idxs:
                return
            ctk.CTkLabel(wrap, text=title, font=(FONT_DISPLAY, 14, "bold"), text_color=color,
                         anchor="w").pack(anchor="w", pady=(10, 6))
            for i in idxs:
                q = self.questions[i]
                row = card(wrap)
                row.pack(fill="x", pady=3)
                inner = ctk.CTkFrame(row, fg_color="transparent")
                inner.pack(fill="x", padx=14, pady=8)
                txt = f"Q{i+1}. {q['q'][:90]}"
                ctk.CTkLabel(inner, text=txt, font=(FONT_BODY, 12), text_color=C.INK,
                             anchor="w").pack(side="left")
                ghost_button(inner, "Go", lambda i=i: jump(i), width=60).pack(side="right")

        section(f"Unanswered ({len(unanswered)})", unanswered, C.STAMP)
        section(f"Flagged ({len(flagged)})", flagged, C.BRASS_DARK)

        if not unanswered and not flagged:
            ctk.CTkLabel(wrap, text="Everything is answered and nothing is flagged.",
                         font=(FONT_BODY, 13), text_color=C.FOREST, anchor="w").pack(anchor="w", pady=(6, 0))

        btnrow = ctk.CTkFrame(wrap, fg_color="transparent")
        btnrow.pack(anchor="w", pady=(20, 0))
        def submit_exam():
            if self._confirm_submit():
                self.finish()

        primary_button(btnrow, "Submit exam", submit_exam).pack(side="left", padx=(0, 8))
        ghost_button(btnrow, "Keep working", self.resume_from_review).pack(side="left")

    def resume_from_review(self):
        """The review screen replaced the entire question chrome, so returning
        to the exam has to rebuild it before rendering a question again --
        self.body and the timer labels from before no longer exist."""
        self._build_chrome()
        self.render_question()

    def _resolve_pending_intervention(self, outcome):
        """Close any intervention still open when a session ends.

        Without this, an intervention logged just before the user quits (or
        finishes) stays resolved=0 forever, and intervention_effectiveness()
        -- which only counts resolved rows -- silently drops it. Those
        dropped cases are exactly the ones where the learner was struggling
        hardest, so the effectiveness figure was biased optimistic by
        survivorship. Partial recovery windows are still recorded, using
        whatever answers actually followed the cue; `outcome` distinguishes
        a normal finish from an abandon so the two can be told apart later."""
        if getattr(self, "ctrl_active_id", None) is None:
            return
        try:
            n = getattr(self, "ctrl_answers_since_cue", 0) or 0
            if n > 0:
                acc_after = (getattr(self, "ctrl_correct_since_cue", 0) or 0) / n
            else:
                # Cue fired but the learner answered nothing afterwards --
                # the most negative outcome possible, and the one previously
                # discarded entirely.
                acc_after = 0.0
            close_intervention(self.conn, self.ctrl_active_id, acc_after,
                               outcome=outcome, answers_after=n)
        except Exception:
            pass
        self.ctrl_active_id = None

    def abandon(self):
        """Called when the user navigates away or closes the window mid-
        session, after confirming. Stops the timer and releases the keyboard
        bindings without writing a session summary -- every answer already
        given was already committed to disk as it happened, so nothing is
        lost except the current in-progress question and the aggregate
        summary row."""
        if self.destroyed:
            return
        self.destroyed = True
        self._resolve_pending_intervention("abandoned")
        self._cancel_pending_callbacks()
        self._unbind_keys()
        if self.app.active_session is self:
            self.app.active_session = None
        if self.timed:
            # A score prediction belongs to the attempt it was made for; an
            # abandoned timed set must not leave it to be scored against
            # the next one as a calibration point.
            try:
                set_setting(self.conn, "pending_prediction", "")
            except sqlite3.Error as e:
                _audit(self.conn, "prediction_clear_failed", str(e))
        try:
            n_done = (len(self.dynamic_seen) if self.dynamic_picker
                      else sum(1 for a in self.answers if a is not None))
            log_session_event(self.conn, "abandon", self.record_mode, n_items=n_done)
            update_learner_phase(self.conn, completed=False)
        except Exception:
            pass
        session_context_end(self)
        if getattr(self, "_calm_key", None) is not None:
            try:
                record_behaviour_outcome(self.conn, "calm_timer", self._calm_key, 0.0)   # abandoned
            except Exception:
                pass
        try:
            record_session_affect(self.conn, abandoned=True, session_key=getattr(self, "session_uuid", None))
        except Exception as e:
            _audit(self.conn, "session_affect_failed", f"{type(e).__name__}: {e}")
        self._persist_retests()

    def _persist_retests(self):
        """Spec 7.6 across sessions: retests this session owed but did not
        serve (the per-session cap, a pause, an abandon) are queued for the
        next composed session, and pending retests it did serve are
        stamped so they are not queued again. Nothing is queued for
        measurement sessions, which never promised a retest."""
        try:
            served = []
            for i, m in enumerate(self.plan_meta):
                if (m.get("pending_id") and i < len(self.answers)
                        and self.answers[i] is not None):
                    served.append(m["pending_id"])
            for pid in served:
                mark_pending_retest_served(self.conn, pid)
            if not self._is_learn_objective():
                return
            # An owed item answered in any slot of a learning session (the
            # warm-up or the due fill can pick it before the retest loop
            # does) is served: stamped by question id, so it neither stays
            # among the oldest rows nor blocks a later confident miss on the
            # same item from being queued.
            answered = [qq["id"] for i, qq in enumerate(self.questions)
                        if qq and i < len(self.answers) and self.answers[i] is not None]
            mark_pending_retests_served_for(self.conn, answered)
            leftovers = []
            for q in self.missed_for_redo:
                reason = "pretest" if any(
                    m.get("pretest") and m.get("q", {}).get("id") == q["id"]
                    for m in self.plan_meta) else "confident_miss"
                leftovers.append((q["id"], reason))
            # retests already appended to the list but never reached, and
            # retests MISSED AGAIN: those are not re-queued within the
            # session (see _queue_retest), and the feedback line and the
            # debrief both promise they "come back in a later session".
            for i, m in enumerate(self.plan_meta):
                if not m.get("retest") or i >= len(self.answers):
                    continue
                ans = self.answers[i]
                if ans is None or ans != m["q"]["a"]:
                    leftovers.append((m["q"]["id"], "confident_miss"))
            for qid in getattr(self, "_dynamic_retests_missed", []):
                leftovers.append((qid, "confident_miss"))
            if leftovers:
                add_pending_retests(self.conn, leftovers)
        except sqlite3.Error as e:
            _audit(self.conn, "persist_retests_failed", str(e))

    def _cancel_pending_callbacks(self):
        for attr in ("timer_after_id", "_advance_after_id"):
            after_id = getattr(self, attr, None)
            if after_id:
                try:
                    self.parent.after_cancel(after_id)
                except Exception:
                    pass
                setattr(self, attr, None)
        # The calculator is a topmost Toplevel owned by the session; left
        # alone it floats over every other view after the exam ends.
        calc = getattr(self, "calc_window", None)
        if calc is not None:
            try:
                if calc.winfo_exists():
                    calc.destroy()
            except tk.TclError:
                pass
            self.calc_window = None

    # ---- timer ---------------------------------------------------------

    def _tick(self):
        if self.destroyed:
            return
        self.timer_after_id = None
        elapsed = time.monotonic() - self.session_start
        remaining = self.total_seconds - elapsed
        # The review screen tears down the question chrome (including the
        # timer label) while the exam is still running, so the tick must
        # tolerate its own widgets having been destroyed: keep counting,
        # and above all still END the exam when time runs out -- the label
        # is cosmetic, the deadline is not.
        try:
            lbl_alive = self.timer_lbl.winfo_exists()
        except (tk.TclError, AttributeError):
            lbl_alive = False
        if remaining <= 0:
            if lbl_alive:
                try:
                    self.timer_lbl.configure(text="Time's up", text_color=C.STAMP)
                except tk.TclError:
                    pass
            self.finish()
            return
        if not hasattr(self, "_calm"):
            self._calm = calm_timer_arm(self)       # V8.5 trial, assigned once per session
        if lbl_alive:
            text, color = timer_display(remaining, self._calm, exam=bool(getattr(self, "exam_mode", False)))
            try:
                self.timer_lbl.configure(text=text, text_color=color)
                self._update_pacing(elapsed)
            except tk.TclError:
                pass
        self.timer_after_id = self.parent.after(1000, self._tick)

    def _update_pacing(self, elapsed):
        """Live pacing coach: compares where you actually are against where
        an even pace would put you, and says so in plain language. This is
        the guess-and-move-on discipline the research calls for -- it only
        helps if you know you're behind while there's still time to act."""
        if not hasattr(self, "pace_lbl"):
            return
        try:
            if not self.pace_lbl.winfo_exists():
                return
        except tk.TclError:
            return
        total_q = len(self.questions) if not self.dynamic_picker else (self.dynamic_target or 1)
        if not total_q:
            return
        answered = sum(1 for a in self.answers[:len(self.questions)] if a is not None)
        per_q = self.total_seconds / total_q
        expected_answered = elapsed / per_q
        delta_q = answered - expected_answered
        delta_secs = delta_q * per_q
        if abs(delta_secs) < 45:
            self.pace_lbl.configure(text="on pace", text_color=C.INK_DIM)
        elif delta_secs > 0:
            self.pace_lbl.configure(text=f"{int(delta_secs // 60)}m {int(delta_secs % 60)}s ahead",
                                    text_color=C.FOREST)
        else:
            behind = abs(delta_secs)
            msg = f"{int(behind // 60)}m {int(behind % 60)}s behind"
            if behind > 180:
                msg += " \u2014 consider guessing and moving on"
            self.pace_lbl.configure(text=msg, text_color=(C.STAMP if getattr(self, "exam_mode", False) else C.INK))

    def toggle_flag(self):
        if self.index in self.flagged:
            self.flagged.discard(self.index)
        else:
            self.flagged.add(self.index)
        if hasattr(self, "flag_btn") and self.flag_btn.winfo_exists():
            self.flag_btn.configure(text="\u2691 Unflag" if self.index in self.flagged
                                    else "\u2691 Flag for review")

    def open_calculator(self):
        """Basic four-function calculator -- PSI permits a non-scientific
        calculator on the real exam, so practicing without one trains the
        wrong habit."""
        if self.calc_window is not None and self.calc_window.winfo_exists():
            self.calc_window.lift()
            return
        win = ctk.CTkToplevel(self.parent)
        win.title("Calculator")
        win.geometry("260x330")
        win.configure(fg_color=C.PAPER)
        win.attributes("-topmost", True)
        self.calc_window = win

        display_var = tk.StringVar(value="0")
        disp = ctk.CTkLabel(win, textvariable=display_var, font=(FONT_MONO, 22, "bold"),
                            text_color=C.INK, anchor="e", fg_color=C.PAPER_DIM, corner_radius=8,
                            height=52)
        disp.pack(fill="x", padx=12, pady=(12, 8))

        buf = {"expr": ""}

        def press(ch):
            if ch == "C":
                buf["expr"] = ""
                display_var.set("0")
                return
            if ch == "=":
                try:
                    expr = buf["expr"].replace("\u00d7", "*").replace("\u00f7", "/")
                    if not all(c in "0123456789.+-*/() " for c in expr):
                        raise ValueError
                    result = eval(expr, {"__builtins__": {}}, {})
                    display_var.set(f"{result:,.4f}".rstrip("0").rstrip("."))
                    buf["expr"] = str(result)
                except Exception:
                    display_var.set("error")
                    buf["expr"] = ""
                return
            buf["expr"] += ch
            display_var.set(buf["expr"])

        grid = ctk.CTkFrame(win, fg_color="transparent")
        grid.pack(fill="both", expand=True, padx=12, pady=(0, 12))
        keys = [["7","8","9","\u00f7"],["4","5","6","\u00d7"],["1","2","3","-"],["0",".","=","+"],["C"]]
        for r, rowk in enumerate(keys):
            for c, k in enumerate(rowk):
                b = ctk.CTkButton(grid, text=k, width=52, height=44, corner_radius=8,
                                  fg_color=(C.BRASS if k in "=" else C.PAPER_DIM),
                                  hover_color=C.PAPER_LINE,
                                  text_color=C.INK, font=(FONT_BODY, 15, "bold"),
                                  command=lambda k=k: press(k))
                b.grid(row=r, column=c, padx=3, pady=3, sticky="nsew")
        for c in range(4):
            grid.grid_columnconfigure(c, weight=1)

    # ---- finish ---------------------------------------------------------

    def finish(self):
        if self.destroyed:
            return
        self.destroyed = True
        self._resolve_pending_intervention("session_ended")
        session_context_end(self)
        self._unbind_keys()
        # Generated items climb the calibration ladder on their own evidence.
        # Checked at session end so a candidate cannot start updating the
        # model mid-session, and so the decision is auditable per session.
        try:
            advance_ladder(self.conn)
        except Exception:
            pass
        if self.app.active_session is self:
            self.app.active_session = None
        self._cancel_pending_callbacks()
        time_used = time.monotonic() - self.session_start

        if self.dynamic_picker:
            correct_ct = sum(1 for qid in self.dynamic_seen
                              for r in [self.conn.execute(
                                  "SELECT correct FROM attempts WHERE question_id=? ORDER BY id DESC LIMIT 1",
                                  (qid,)).fetchone()] if r and r["correct"])
            total = len(self.dynamic_seen)
            answered = total
        else:
            answered = sum(1 for a in self.answers[:len(self.questions)] if a is not None)
            correct_ct = sum(1 for i, a in enumerate(self.answers[:len(self.questions)])
                              if a is not None and a == self.questions[i]["a"])
            # Under a clock the served set is the denominator: a blank is
            # scored as wrong, as on the real PSI exam, so running out of
            # time cannot inflate the score. Untimed sessions may end early
            # (pause) and are scored on what was actually answered.
            total = len(self.questions) if (self.timed or self.exam_mode) else answered

        objective = ("simulation" if (self.timed or self.exam_mode)
                     else "diagnostic" if str(self.record_mode).startswith("diagnostic")
                     else "learn")
        # Retests appended to a fixed list carry a plan_meta flag; dynamic
        # retests are counted live as they are answered. A session is one
        # or the other, so the two never double-count.
        retest_held = self._retests_held + sum(
            1 for i, qq in enumerate(self.questions)
            if qq and i < len(self.plan_meta) and self.plan_meta[i].get("retest")
            and i < len(self.answers) and self.answers[i] == qq["a"])
        # Retests owed from an earlier session arrive pre-planned (composed
        # plan, pending_id) rather than appended, so they are counted from
        # the plan flags alongside the appended ones.
        retests_served = self._retests_added + sum(
            1 for i, m in enumerate(self.plan_meta)
            if m.get("pending_id") and i < len(self.answers) and self.answers[i] is not None)
        # Skills "moved forward" are the ones with at least one correct,
        # unaided, non-pretest answer this session -- read back from the
        # rows the session wrote, whichever answer path wrote them.
        advanced_skills = set()
        try:
            rows = self.conn.execute(
                "SELECT question_id FROM attempts WHERE id > ? AND correct = 1 "
                "AND mode != 'pretest' AND COALESCE(hint_level, 0) < ?",
                (getattr(self, "_attempt_id_at_start", 0), HEAVY_HINT_THRESHOLD)).fetchall()
            for r in rows:
                advanced_skills.update(sid for sid in Q_MATRIX.get(r["question_id"], []) if sid in SKILLS)
        except sqlite3.Error as e:
            _audit(self.conn, "advanced_skills_query_failed", str(e))
        summary = {"total": total, "correct": correct_ct, "answered": answered,
                   "pct": round(100 * correct_ct / total, 1) if total else 0.0,
                   "time_used": time_used, "answers": self.answers,
                   "initial_answers": self.initial_answers, "questions": self.questions,
                   "mode": self.record_mode, "objective": objective,
                   "phase": getattr(self, "phase", "A"),
                   "retests": retests_served,
                   "retest_held": retest_held,
                   "solid_before": getattr(self, "_solid_at_start", 0),
                   "controller_action": self.ctrl_action,
                   "served_skills": sorted({sid for qq in self.questions if qq
                                            for sid in Q_MATRIX.get(qq["id"], [])}),
                   "advanced_skills": sorted(advanced_skills),
                   # The debrief reads this session's own rows (calibration
                   # grid) from the id mark rather than re-deriving them.
                   "attempt_id_start": getattr(self, "_attempt_id_at_start", 0),
                   "session_uuid": getattr(self, "session_uuid", None),
                   "completed_at": datetime.now().isoformat(timespec="seconds")}
        try:
            settle_question_screen_trials(self, summary)
        except Exception as e:
            _audit(self.conn, "question_trials_settle_failed", f"{type(e).__name__}: {e}")
        try:
            _aff = dict(summary)
            _aff["planned_mean_p"] = (self.composed_plan or {}).get("planned_mean_p")
            record_session_affect(self.conn, _aff, abandoned=False, session_key=summary.get("session_uuid"))
        except Exception as e:
            _audit(self.conn, "session_affect_failed", f"{type(e).__name__}: {e}")
        try:
            model_drift_check(self.conn)
        except Exception as e:
            _audit(self.conn, "model_drift_check_failed", f"{type(e).__name__}: {e}")
        mark_session_today(self.conn)
        # A pause ends the session but is not a completion: it is logged
        # under its own kind so the phase gate neither counts it as dwell
        # nor reads its partial accuracy.
        paused = bool(getattr(self, "_pause_requested", False))
        planned_mean_p = (self.composed_plan or {}).get("planned_mean_p")
        if planned_mean_p is None:
            planned_mean_p = getattr(self, "_planned_mean_p", None)
        if self.diagnostic_redo:
            # The untimed redo is the second half of the diagnostic the
            # learner just completed, not a session of its own: its items
            # are the ones just missed, so its accuracy is regression to the
            # mean, and the timed half already counted toward dwell and
            # evaluated the phase. Logged under its own kind so the phase
            # machine sees one completed session per diagnostic.
            log_session_event(self.conn, "complete_part", self.record_mode,
                              n_items=total, n_correct=correct_ct)
        else:
            log_session_event(self.conn, "pause" if paused else "complete", self.record_mode,
                              n_items=total, n_correct=correct_ct,
                              planned_mean_p=planned_mean_p)
            try:
                update_learner_phase(self.conn, completed=not paused)
            except Exception:
                pass
        self._persist_retests()
        if self.on_finish:
            self.on_finish(summary)

# ---- shared "results" screen ------------------------------------------

def render_result_screen(app, parent, summary, on_done, extra_rows=None):
    """Spec 7.7: three renderers dispatched on the session's objective.
    The 70% verdict survives only where the exam cutoff is the honest
    reference -- the simulation debrief. Learn sessions never see a
    percentage; a learner doing exactly what a p=0.78 selector intends
    was previously shown, in red, that they failed."""
    objective = summary.get("objective")
    if objective == "learn":
        return render_learn_result(app, parent, summary, on_done)
    if objective == "simulation":
        return render_simulation_debrief(app, parent, summary, on_done, extra_rows=extra_rows)
    # Diagnostic: the third renderer. It measures, so its numbers are
    # shown, but as a comparison (timed against untimed on the same items)
    # rather than a pass/fail stamp -- the 70% verdict belongs to the
    # simulation debrief alone, and nothing here is red.
    for w in parent.winfo_children():
        w.destroy()
    wrap = ctk.CTkFrame(parent, fg_color="transparent")
    wrap.pack(fill="both", expand=True, padx=32, pady=40)

    section_title(wrap, summary.get("title") or "Diagnostic Results").pack(anchor="w", pady=(0, 20))
    if not extra_rows:
        extra_rows = [("Correct", f"{summary.get('correct', 0)}/{summary.get('total', 0)}")]
    c = card(wrap)
    c.pack(fill="x", pady=(0, 20))
    inner = ctk.CTkFrame(c, fg_color="transparent")
    inner.pack(fill="x", padx=18, pady=14)
    for label, value in extra_rows:
        row = ctk.CTkFrame(inner, fg_color="transparent")
        row.pack(fill="x", pady=2)
        ctk.CTkLabel(row, text=label, font=(FONT_BODY, 12), text_color=C.INK_DIM,
                     anchor="w", width=220).pack(side="left")
        ctk.CTkLabel(row, text=value, font=(FONT_BODY, 12, "bold"), text_color=C.INK,
                     anchor="w").pack(side="left")
    verdict = summary.get("verdict")
    if verdict:
        result_card = card(wrap, fg_color=C.NAVY)
        result_card.pack(fill="x", pady=(0, 8))
        ctk.CTkLabel(result_card, text=verdict, font=(FONT_DISPLAY, 14, "bold"),
                     text_color=C.CREAM, anchor="w", justify="left", wraplength=600
                     ).pack(padx=20, pady=16, anchor="w")
    next_step = summary.get("next_step")
    if next_step:
        ctk.CTkLabel(wrap, text=next_step, font=(FONT_BODY, 13), text_color=C.INK,
                     anchor="w", justify="left", wraplength=640).pack(anchor="w", pady=(6, 12))

    primary_button(wrap, summary.get("done_label") or "Continue", on_done).pack(anchor="w")


def render_learn_result(app, parent, summary, on_done):
    """No percentage. Competence first, then what moved, then one neutral
    line if the controller acted."""
    for w in parent.winfo_children():
        w.destroy()
    wrap = ctk.CTkFrame(parent, fg_color="transparent")
    wrap.pack(fill="both", expand=True, padx=32, pady=40)
    try:
        solid_after = skills_solid_count(app.conn)
    except Exception:
        solid_after = None
    solid_before = summary.get("solid_before")
    n_skills = len(summary.get("served_skills") or [])
    # "Moved forward" is earned by a correct unaided answer; a served skill
    # that was only missed was practised, not advanced.
    n_advanced = len(summary.get("advanced_skills") or [])
    ctk.CTkLabel(wrap, text="Session done.", font=(FONT_DISPLAY, 30, "bold"),
                 text_color=C.INK).pack(anchor="w")
    lines = []
    if n_skills and n_advanced:
        lines.append(f"Skills practised: {n_skills} \u00b7 {n_advanced} moved forward.")
    elif n_skills:
        lines.append(f"Skills practised: {n_skills}.")
    if solid_after is not None and solid_before is not None:
        if solid_after > solid_before:
            lines.append(f"Solid: {solid_before} \u2192 {solid_after}.")
        elif solid_after:
            lines.append(f"Solid: {solid_after}.")
    if summary.get("retests"):
        held = summary.get("retest_held", 0)
        if held == summary["retests"]:
            lines.append(f"{'One' if held == 1 else held} confident miss retested and held.")
        else:
            lines.append(f"{summary['retests']} retested; {held} held \u2014 the rest come back next time.")
    act = summary.get("controller_action")
    if act and act != "cue":
        lines.append({"lift_target": "The last stretch was made a little easier after two misses in a row.",
                      "close_early": "This one was closed a little early after a rough patch.",
                      "scaffold": "A rule reminder was shown mid-session.",
                      "offer_pause": "A pause was offered mid-session.",
                      "cue_then_solid_item": "A steadier item was slotted in after a fast stretch."
                      }.get(act, ""))
    for ln in [x for x in lines if x]:
        ctk.CTkLabel(wrap, text=ln, font=(FONT_BODY, 14), text_color=C.INK,
                     anchor="w", justify="left", wraplength=640).pack(anchor="w", pady=(6, 0))
    # What moved: Learning Events between the learner-facing state before the
    # session and now -- tier changes, spaced days held within a tier,
    # confident misses revisited, repairs opened or closed, and practice that
    # added evidence without a change.
    if summary.get("vis_before") is None and summary.get("tiers_before") is not None:
        summary["vis_before"] = {"tiers": summary["tiers_before"]}
    try:
        vis_render_session_events(app, wrap, summary)
    except Exception as e:
        _audit(app.conn, "debrief_events_failed", f"{type(e).__name__}: {e}")
    _render_calibration_grid(app.conn, wrap, summary.get("attempt_id_start"), app=app)
    primary_button(wrap, "Back to Today", on_done).pack(anchor="w", pady=(24, 0))


def _session_calibration_counts(conn, attempt_id_start):
    """Confidence x outcome counts for the rows one session wrote:
    {1|2|3: {"right": n, "wrong": n}}. Empty when nothing was rated."""
    counts = {lvl: {"right": 0, "wrong": 0} for lvl in (1, 2, 3)}
    if attempt_id_start is None:
        return {}
    rated = 0
    for r in _safe_query(conn, "SELECT confidence, correct FROM attempts WHERE id > ? "
                               "AND confidence IS NOT NULL", (attempt_id_start,)):
        try:
            lvl = int(r["confidence"])
        except (TypeError, ValueError):
            continue
        if lvl not in counts:
            continue
        counts[lvl]["right" if r["correct"] else "wrong"] += 1
        rated += 1
    return counts if rated else {}


def _render_calibration_grid(conn, parent, attempt_id_start, app=None):
    """Science upgrade U#4: calibration feedback at session level. Seeing
    confidence against outcome repeatedly is what improves calibration
    (Nietfeld et al. 2006), so the learn debrief shows the 3x2 grid for
    the items the learner rated, with one plain sentence. Nothing is drawn
    when no item was rated."""
    counts = _session_calibration_counts(conn, attempt_id_start)
    if not counts:
        return
    c = card(parent, fg_color=C.PAPER_DIM)
    c.pack(fill="x", pady=(16, 0))
    inner = ctk.CTkFrame(c, fg_color="transparent", height=0)
    inner.pack(fill="x", padx=18, pady=12)
    ctk.CTkLabel(inner, text="How sure you were, and how it went", font=(FONT_BODY, 11, "bold"),
                 text_color=C.INK, anchor="w").pack(anchor="w", pady=(0, 6))
    grid = ctk.CTkFrame(inner, fg_color="transparent", height=0)
    grid.pack(anchor="w")
    names = {1: "Guessing", 2: "Somewhat sure", 3: "Confident"}
    ctk.CTkLabel(grid, text="", width=120).grid(row=0, column=0)
    for j, head in enumerate(("right", "wrong"), start=1):
        ctk.CTkLabel(grid, text=head, font=(FONT_BODY, 11), text_color=C.INK_DIM,
                     width=60).grid(row=0, column=j, padx=4)
    detail = ctk.CTkFrame(inner, fg_color="transparent")

    def open_cell(lvl, outcome):
        # Every non-empty cell is a door to the questions behind it.
        for w_ in detail.winfo_children():
            w_.destroy()
        cell = present_calibration_cell(conn, attempt_id_start, lvl, outcome)
        detail.pack(fill="x", pady=(10, 0), after=grid)
        ctk.CTkLabel(detail, text=f"{names[lvl]} and {outcome}", font=(FONT_BODY, 12, "bold"),
                     text_color=C.INK, anchor="w").pack(anchor="w")
        for it in cell["items"]:
            ctk.CTkLabel(detail, text=("\u21ba " if it["coming_back"] else "\u2022 ") + it["stem"]
                         + (f"  ({', '.join(it['skills'])})" if it["skills"] else ""),
                         font=(FONT_BODY, 11), text_color=C.INK, anchor="w", justify="left",
                         wraplength=600).pack(anchor="w", pady=1)
        if cell["shared_confusion"]:
            ctk.CTkLabel(detail, text="These share a known mix-up: " + cell["shared_confusion"],
                         font=(FONT_BODY, 11, "italic"), text_color=C.INK_DIM, anchor="w",
                         justify="left", wraplength=600).pack(anchor="w", pady=(4, 0))
        if any(it["coming_back"] for it in cell["items"]):
            ctk.CTkLabel(detail, text="\u21ba marks a question already scheduled to come back.",
                         font=(FONT_BODY, 10), text_color=C.INK_DIM, anchor="w").pack(anchor="w")
        sids = []
        for it in cell["items"]:
            for s in Q_MATRIX.get(it["qid"], []):
                if s not in sids:
                    sids.append(s)
        if app is not None and sids and outcome == "wrong":
            primary_button(detail, "Practise these", lambda: vis_start_practice(
                app, app.content, sids[:6], "Worth a second look"), width=140).pack(anchor="w", pady=(8, 0))

    for i, lvl in enumerate((1, 2, 3), start=1):
        ctk.CTkLabel(grid, text=names[lvl], font=(FONT_BODY, 12), text_color=C.INK,
                     width=120, anchor="w").grid(row=i, column=0, sticky="w", pady=1)
        for j, key in enumerate(("right", "wrong"), start=1):
            n_ = counts[lvl][key]
            if n_:
                ctk.CTkButton(grid, text=str(n_), width=60, height=26, fg_color="transparent",
                              border_width=1, border_color=C.PAPER_LINE, hover_color=C.PAPER_LINE,
                              text_color=C.INK, font=(FONT_MONO, 12, "bold"), cursor="hand2",
                              command=lambda l=lvl, k=key: open_cell(l, k)).grid(row=i, column=j, padx=4, pady=1)
            else:
                ctk.CTkLabel(grid, text="0", font=(FONT_MONO, 12), text_color=C.INK_DIM,
                             width=60).grid(row=i, column=j, padx=4, pady=1)
    conf_wrong = counts[3]["wrong"]
    conf_total = counts[3]["right"] + conf_wrong
    guess_right = counts[1]["right"]
    guess_total = guess_right + counts[1]["wrong"]
    if conf_wrong:
        sentence = (f"{'One' if conf_wrong == 1 else conf_wrong} of the {conf_total} you were "
                    f"confident about went wrong — those are the ones that came back, "
                    "and the ones worth a second look.")
    elif conf_total:
        sentence = ("Everything you were confident about was right — your sense of "
                    "what you know is tracking well.")
    elif guess_total and guess_right > guess_total / 2:
        sentence = ("You called most of these guesses and got them anyway — you know "
                    "more than you are giving yourself credit for.")
    else:
        sentence = "Rating a few more items builds the picture."
    ctk.CTkLabel(inner, text=sentence, font=(FONT_BODY, 12), text_color=C.INK,
                 anchor="w", justify="left", wraplength=600).pack(anchor="w", pady=(8, 0))
    # Across all rated answers, not just this session: the distinction that
    # decides the advice (ratings that carry no information vs. ratings
    # that are sound but too high) needs more than one session's counts.
    try:
        kind, reading = calibration_reading(calibration_metrics(conn))
    except sqlite3.Error:
        kind, reading = None, ""
    if kind in ("uninformative", "overconfident"):
        ctk.CTkLabel(inner, text="Over all your rated answers: " + reading,
                     font=(FONT_BODY, 11), text_color=C.INK_DIM,
                     anchor="w", justify="left", wraplength=600).pack(anchor="w", pady=(6, 0))


def render_simulation_debrief(app, parent, summary, on_done, extra_rows=None):
    """Spec 7.8: pressure_profile gets a screen. Score against 70 (the one
    place it belongs), calm vs clock on the SAME skills, verdict routing,
    first-instinct advice positively framed."""
    for w in parent.winfo_children():
        w.destroy()
    wrap = ctk.CTkScrollableFrame(parent, fg_color="transparent")
    wrap.pack(fill="both", expand=True, padx=32, pady=32)
    conn = app.conn
    pct = summary["pct"]
    passed = pct >= 70
    ctk.CTkLabel(wrap, text=f"{pct:.1f}%", font=(FONT_DISPLAY, 48, "bold"),
                 text_color=(C.FOREST if passed else C.INK)).pack(anchor="w")
    answered = summary.get("answered")
    blanks = (summary["total"] - answered) if answered is not None else 0
    ctk.CTkLabel(wrap, text=(f"{summary['correct']}/{summary['total']} correct \u2014 "
                             + ("clears the 70% mark" if passed else "under the 70% mark this time")),
                 font=(FONT_BODY, 13), text_color=C.INK_DIM).pack(anchor="w", pady=(2, 14 if blanks <= 0 else 2))
    if blanks > 0:
        # A pacing failure is shown, not hidden: the blanks are in the
        # denominator above, and this says so.
        ctk.CTkLabel(wrap, text=(f"Answered {answered} of {summary['total']} \u2014 the "
                                 f"{blanks} left blank count as wrong, as on the real exam."),
                     font=(FONT_BODY, 12, "italic"), text_color=C.INK_DIM, anchor="w",
                     justify="left", wraplength=620).pack(anchor="w", pady=(0, 14))

    # Calm versus clock, restricted to the skills this session served.
    served = set(summary.get("served_skills") or [])
    served_qids = {q["id"] for q in QUIZ_LIST if served & set(Q_MATRIX.get(q["id"], []))}
    calm_acc = None
    try:
        if served_qids:
            marks = ",".join("?" * len(served_qids))
            calm_modes = tuple(CALM_MODES)
            cm = ",".join("?" * len(calm_modes))
            rows = conn.execute(
                f"""SELECT correct FROM attempts WHERE mode IN ({cm})
                     AND question_id IN ({marks}) ORDER BY id DESC LIMIT 400""",
                (*calm_modes, *served_qids)).fetchall()
            if len(rows) >= 8:
                calm_acc = sum(1 for r in rows if r["correct"]) / len(rows)
    except Exception:
        calm_acc = None
    try:
        prof = pressure_profile(conn)
    except Exception:
        prof = {}
    # The card compares calm and clock on the SAME skills. When those rows
    # are too few, the global profile stands in -- labelled as such, in its
    # own words rather than the profile's prescriptive verdict -- and when
    # even that has fewer than eight rows a side, the card is not drawn:
    # a comparison built on four answers would be noise presented as
    # insight.
    global_acc_calm = prof.get("acc_calm")
    global_acc_press = prof.get("acc_pressure")
    global_ok = (calm_acc is None and global_acc_calm is not None and global_acc_press is not None
                 and (prof.get("n_calm") or 0) >= 8 and (prof.get("n_pressure") or 0) >= 8)
    if calm_acc is not None or global_ok:
        c = card(wrap)
        c.pack(fill="x", pady=(0, 14))
        inner = ctk.CTkFrame(c, fg_color="transparent")
        inner.pack(fill="x", padx=18, pady=14)
        ctk.CTkLabel(inner, text="CALM VERSUS CLOCK", font=(FONT_BODY, 11, "bold"),
                     text_color=C.INK, anchor="w").pack(anchor="w")
        if calm_acc is not None:
            msg = (f"On these same skills you answer {calm_acc*100:.0f}% untimed and "
                   f"{pct:.0f}% under a clock.")
            gap = calm_acc * 100 - pct
            # The same-skill gap is description; the claim about the clock
            # belongs to the tested profile verdict, not to a threshold on
            # a handful of answers.
            # The profile verdict is only quoted when this session's own
            # numbers point the same way; a verdict that contradicts the
            # figures printed beside it reads as nonsense.
            blanks = max(0, int(summary.get("total") or 0) - int(summary.get("answered") or 0))
            if prof.get("confident") and prof.get("pressure_limited") and gap >= 0:
                msg += " The clock is the constraint, not the content."
            elif (prof.get("confident") and prof.get("verdict_kind") == "timing_helps"
                  and gap <= 0 and blanks == 0):
                msg += " The clock is keeping you decisive."
            elif blanks > 0 and gap >= 15:
                msg += (f" The {blanks} left blank are in that figure — "
                        "pace, more than knowledge, is what to work on.")
            elif gap >= 15:
                msg += " A gap that size on this many answers is suggestive, not settled."
            elif gap <= -8:
                msg += " Timed came out ahead here \u2014 too few answers to call it a pattern."
            else:
                msg += " Calm and timed are close."
        else:
            msg = (f"Across all your timed work so far: {global_acc_calm*100:.0f}% untimed "
                   f"and {global_acc_press*100:.0f}% under a clock. This set alone: "
                   f"{pct:.0f}%.")
        ml = ctk.CTkLabel(inner, text=msg, font=(FONT_BODY, 13), text_color=C.INK,
                          anchor="w", justify="left", wraplength=620)
        ml.pack(anchor="w", pady=(4, 0))

        # Verdict routing -- pointed at a door that is open. Generous-pace
        # practice is a ladder rung with an unlock rule; while it is locked
        # the honest next step is the work that opens it.
        if prof.get("confident"):
            if prof.get("pressure_limited"):
                route = _rung2_locked_hint(conn) or (
                    "Next session leans to timed sets at a generous pace, with the "
                    "pre-answer routine.")
            else:
                route = "Next session leans to relearning the skills that were shaky here."
            ctk.CTkLabel(inner, text=route, font=(FONT_BODY, 12, "italic"), text_color=C.INK_DIM,
                         anchor="w", justify="left", wraplength=620).pack(anchor="w", pady=(8, 0))

    # First-instinct advice, positively framed.
    try:
        w2r = r2w = 0
        qs = summary.get("questions") or []
        for i, q in enumerate(qs):
            init = summary["initial_answers"][i] if i < len(summary["initial_answers"]) else None
            fin = summary["answers"][i] if i < len(summary["answers"]) else None
            if init is None or fin is None or init == fin:
                continue
            if fin == q["a"]:
                w2r += 1
            elif init == q["a"]:
                r2w += 1
        if w2r + r2w > 0:
            fi = card(wrap)
            fi.pack(fill="x", pady=(0, 14))
            fin_ = ctk.CTkFrame(fi, fg_color="transparent")
            fin_.pack(fill="x", padx=18, pady=14)
            ctk.CTkLabel(fin_, text="CHANGED ANSWERS", font=(FONT_BODY, 11, "bold"),
                         text_color=C.INK, anchor="w").pack(anchor="w")
            adv = (f"You changed {w2r + r2w} answers: {w2r} to the right one, {r2w} away from it. "
                   + ("When you change an answer, you're usually right to." if w2r >= r2w
                      else "Your first instinct was doing well \u2014 change only on a real second reading."))
            ctk.CTkLabel(fin_, text=adv, font=(FONT_BODY, 13), text_color=C.INK, anchor="w",
                         justify="left", wraplength=620).pack(anchor="w", pady=(4, 0))
    except Exception:
        pass

    if extra_rows:
        c2 = card(wrap)
        c2.pack(fill="x", pady=(0, 14))
        in2 = ctk.CTkFrame(c2, fg_color="transparent")
        in2.pack(fill="x", padx=18, pady=14)
        for label, value in extra_rows:
            row = ctk.CTkFrame(in2, fg_color="transparent")
            row.pack(fill="x", pady=2)
            ctk.CTkLabel(row, text=label, font=(FONT_BODY, 12), text_color=C.INK_DIM,
                         anchor="w", width=220).pack(side="left")
            ctk.CTkLabel(row, text=value, font=(FONT_BODY, 12, "bold"), text_color=C.INK,
                         anchor="w").pack(side="left")
    primary_button(wrap, "Continue", on_done).pack(anchor="w")

# ============================================================================
# ANXIETY ROUTINE (optional pre-timed-session sequence)
# ============================================================================

def run_anxiety_routine(app, parent, on_done):
    steps = {"i": 0}

    def step_braindump():
        for w in parent.winfo_children():
            w.destroy()
        wrap = ctk.CTkFrame(parent, fg_color="transparent")
        wrap.pack(fill="both", expand=True, padx=40, pady=40)
        section_title(wrap, "Pre-Exam Routine", "Step 1 of 3 \u2014 Brain dump").pack(anchor="w", pady=(0, 16))
        ctk.CTkLabel(wrap, text="Type out whatever's on your mind about this test \u2014 worries, pressure, "
                     "distractions. Nothing here is saved or read.", font=(FONT_BODY, 13), text_color=C.INK,
                     anchor="w", justify="left", wraplength=560).pack(anchor="w", pady=(0, 12))
        box = ctk.CTkTextbox(wrap, width=560, height=160, font=(FONT_BODY, 13), fg_color=C.PAPER_DIM,
                              text_color=C.INK, corner_radius=10, border_width=1, border_color=C.PAPER_LINE)
        box.pack(anchor="w")
        box.focus_set()
        btnrow = ctk.CTkFrame(wrap, fg_color="transparent")
        btnrow.pack(anchor="w", pady=(16, 0))
        primary_button(btnrow, "Continue", step_reappraisal).pack(side="left", padx=(0, 8))
        ghost_button(btnrow, "Skip routine", on_done).pack(side="left")

    def step_reappraisal():
        for w in parent.winfo_children():
            w.destroy()
        wrap = ctk.CTkFrame(parent, fg_color="transparent")
        wrap.pack(fill="both", expand=True, padx=40, pady=40)
        section_title(wrap, "Pre-Exam Routine", "Step 2 of 3 \u2014 Reappraisal").pack(anchor="w", pady=(0, 20))
        quote_card = card(wrap, fg_color=C.NAVY)
        quote_card.pack(fill="x")
        # Reappraisal, not reassurance: the line must be true on day one,
        # before any work has been done, or it reads as pressure.
        lbl = ctk.CTkLabel(quote_card,
                            text="\u201cThis jitteriness is my body getting ready to perform \u2014 not a sign "
                                 "something is wrong. Arousal sharpens focus. All I need to do is "
                                 "read each question and answer it.\u201d",
                            font=(FONT_DISPLAY, 16, "italic"), text_color=C.CREAM, anchor="w",
                            justify="left", wraplength=520)
        lbl.pack(padx=24, pady=24, anchor="w")
        btnrow = ctk.CTkFrame(wrap, fg_color="transparent")
        btnrow.pack(anchor="w", pady=(20, 0))
        primary_button(btnrow, "Continue", step_breathing).pack(side="left", padx=(0, 8))
        ghost_button(btnrow, "Skip the rest", on_done).pack(side="left")

    def step_breathing():
        for w in parent.winfo_children():
            w.destroy()
        wrap = ctk.CTkFrame(parent, fg_color="transparent")
        wrap.pack(fill="both", expand=True, padx=40, pady=40)
        section_title(wrap, "Pre-Exam Routine", "Step 3 of 3 \u2014 Paced breathing (4 in \u00b7 7 hold \u00b7 8 out)").pack(anchor="w", pady=(0, 20))
        canvas = tk.Canvas(wrap, width=240, height=240, bg=C.PAPER, highlightthickness=0)
        canvas.pack()
        phase_lbl = ctk.CTkLabel(wrap, text="", font=(FONT_DISPLAY, 16, "bold"), text_color=C.NAVY)
        phase_lbl.pack(pady=(14, 0))
        round_lbl = ctk.CTkLabel(wrap, text="", font=(FONT_BODY, 11), text_color=C.INK_DIM)
        round_lbl.pack()

        state = {"round": 1, "phase": 0, "job": None, "cancelled": False}
        phases = [("Breathe in...", 4, 60, 100), ("Hold...", 7, 100, 100), ("Breathe out...", 8, 100, 60)]

        def animate(phase_idx, frame, total_frames):
            if state["cancelled"]:
                return
            label, dur, r_start, r_end = phases[phase_idx]
            t = frame / max(1, total_frames)
            r = r_start + (r_end - r_start) * t
            canvas.delete("all")
            canvas.create_oval(120 - r, 120 - r, 120 + r, 120 + r, fill=C.BRASS, outline=C.BRASS_DARK, width=2)
            phase_lbl.configure(text=label)
            round_lbl.configure(text=f"Round {state['round']} of 3")
            if frame < total_frames:
                state["job"] = wrap.after(int(dur * 1000 / total_frames), lambda: animate(phase_idx, frame + 1, total_frames))
            else:
                next_phase(phase_idx)

        def next_phase(phase_idx):
            if phase_idx + 1 < len(phases):
                animate(phase_idx + 1, 0, 30)
            else:
                if state["round"] < 3:
                    state["round"] += 1
                    # One full round is the routine; the other two are
                    # there for whoever wants them. Nobody is held for a
                    # minute behind a disabled button.
                    finish_btn.configure(state="normal", text="Ready — begin")
                    animate(0, 0, 30)
                else:
                    finish_btn.configure(state="normal", text="Ready. Good luck.")

        def leave():
            # Stop the animation before the widgets go, so a queued frame
            # cannot draw on a destroyed canvas.
            state["cancelled"] = True
            job = state.get("job")
            if job is not None:
                try:
                    wrap.after_cancel(job)
                except (tk.TclError, ValueError):
                    pass
            on_done()

        btnrow = ctk.CTkFrame(wrap, fg_color="transparent")
        btnrow.pack(pady=(20, 0), anchor="w")
        finish_btn = primary_button(btnrow, "One round, then you can begin…", leave)
        finish_btn.configure(state="disabled")
        finish_btn.pack(side="left", padx=(0, 8))
        ghost_button(btnrow, "Skip the rest", leave).pack(side="left")
        animate(0, 0, 30)

    step_braindump()

def maybe_offer_anxiety_routine(app, parent, context_label, on_continue):
    for w in parent.winfo_children():
        w.destroy()
    wrap = ctk.CTkFrame(parent, fg_color="transparent")
    wrap.pack(fill="both", expand=True, padx=40, pady=40)
    section_title(wrap, "Before you start", f"Run the ~3-minute pre-exam routine before {context_label}?").pack(anchor="w", pady=(0, 4))
    ctk.CTkLabel(wrap, text="Brief expressive writing + stress reappraisal + paced breathing \u2014 evidence-based.",
                 font=(FONT_BODY, 12), text_color=C.INK_DIM, anchor="w").pack(anchor="w", pady=(0, 20))
    row = ctk.CTkFrame(wrap, fg_color="transparent")
    row.pack(anchor="w")
    primary_button(row, "Run the routine", lambda: run_anxiety_routine(app, parent, on_continue)).pack(side="left", padx=(0, 10))
    ghost_button(row, "Skip \u2014 start now", on_continue).pack(side="left")

# The in-set reframe. Deliberately NOT the routine's step 2: that one is a
# first-person line the learner reads to themselves inside an opt-in routine,
# and it is about what to do next. This one is shown to people who did not
# opt into anything, so it states the finding in the third person and stops.
# It says nothing about how prepared the reader is, and it does not claim
# anxiety is good -- the finding is about what the arousal is taken to mean.
AROUSAL_REFRAME = (
    "A fast heart and shallow breathing before a timed test are the body moving "
    "blood and oxygen to the brain — the same response it uses for anything "
    "demanding. In a study by Jamieson and colleagues (2010), people who were "
    "told that this response aids performance scored higher on a timed test than "
    "people who were not told. The arousal itself did not drop. What changed was "
    "what it was read as."
)

def maybe_show_arousal_reframe(app, parent, key, on_continue):
    """Shown at the start of a strict-tier set and the timed exam, when the
    trial arms it on for this occasion. `key` identifies the occasion: it is
    the same key the set's accuracy is later recorded against, so one sitting
    is one measured occasion regardless of how the screen is reached."""
    try:
        armed = behaviour_arm(app.conn, "reappraisal", key)
    except sqlite3.Error as e:
        _audit(app.conn, "reappraisal_arm_failed", str(e))
        on_continue()
        return
    if not armed:
        on_continue()
        return
    for w in parent.winfo_children():
        w.destroy()
    wrap = ctk.CTkFrame(parent, fg_color="transparent")
    wrap.pack(fill="both", expand=True, padx=40, pady=40)
    section_title(wrap, "Before the clock starts",
                  "About the physical side of nerves.").pack(anchor="w", fill="x", pady=(0, 16))
    c = card(wrap)
    c.pack(fill="x")
    inner = ctk.CTkFrame(c, fg_color="transparent")
    inner.pack(fill="x", padx=22, pady=18)
    lbl = ctk.CTkLabel(inner, text=AROUSAL_REFRAME, font=(FONT_BODY, 13), text_color=C.INK,
                       anchor="w", justify="left")
    lbl.pack(anchor="w", fill="x")
    bind_autowrap(lbl, inner, padding=24)
    primary_button(wrap, "Begin", on_continue).pack(anchor="w", pady=(20, 0))

def reappraisal_occasion_key(scope):
    """One key per sitting. The clock reading is taken when the set is
    started, not when it ends, so an occasion cannot be assigned twice."""
    return f"{scope}:{datetime.now().isoformat(timespec='seconds')}"

def record_reappraisal_outcome(conn, key, summary):
    """The occasion's outcome is that set's accuracy on a 0-1 scale, taken
    from the same summary the result screen shows (blanks already count as
    wrong there). Only the first value is kept, by record_behaviour_outcome."""
    total = summary.get("total") or 0
    if not key or not total:
        return
    record_behaviour_outcome(conn, "reappraisal", key, summary.get("correct", 0) / total)

# ============================================================================
# FLASHCARDS VIEW
# ============================================================================

def view_flashcards(app, parent):
    conn = app.conn
    # DECK ORDER. Shuffling the due pile treats 75 cards as interchangeable
    # when they are not: some are weak topics the learner keeps missing and
    # some are near-mature cards being kept warm. With a large due pile the
    # session usually ends before the important ones come up, purely by
    # where the shuffle put them. `deck` lets that be chosen instead of
    # left to chance, and defaults to weakest-first because that is the
    # ordering the rest of the app already argues for.
    all_due = [c for c in FLASHCARDS if card_due_today(get_card_state(conn, c["id"]))]
    deck_pref = get_setting(conn, "flashcard_deck", "weakest")

    def _order(cards, pref):
        if pref == "random":
            out = list(cards)
            random.shuffle(out)
            return out
        if pref == "topic":
            return sorted(cards, key=lambda c: (TOPICS.get(c["topic"], {}).get("name", ""),
                                                c["term"]))
        # weakest-first: lowest topic mastery leads, ties broken by how
        # overdue the card is.
        mast = {}

        def _m(tid):
            if tid not in mast:
                try:
                    mast[tid] = get_mastery(conn, tid)
                except Exception:
                    mast[tid] = 0.5
            return mast[tid]

        return sorted(cards, key=lambda c: (_m(c["topic"]),
                                            due_local_date(get_card_state(conn, c["id"]))))

    due = _order(all_due, deck_pref)
    mode = "due"
    if not due:
        due = _order(list(FLASHCARDS), deck_pref)
        mode = "all"

    # A deck nobody has reviewed yet is not a debt: on day one every card
    # is "due" only because it is new, and a deficit counter is the wrong
    # first thing to show.
    fresh_deck = (mode == "due" and not any(
        get_card_state(conn, c["id"])["last_reviewed"] for c in due))
    n_due_at_start = len(due)

    # `shown_at` starts the clock when a card face is rendered, so the
    # measured duration is time-to-grade: how long retrieval actually
    # took, which is the signal fluency_adjusted_grade needs. `last_msg`
    # is the one line of feedback about the card just graded.
    state = {"i": 0, "showing_def": False, "reviewed": 0, "shown_at": None,
             "last_msg": ""}

    # KEYBOARD. Space flips, 1-4 grade, Enter flips or (at the end) leaves.
    # Bound on the app window while this build of the view is current and
    # released the moment a key arrives for a different view, so a stale
    # handler can never grade a card behind another screen.
    view_token = object()
    app._flashcards_view = view_token
    bound = {"id": None}

    def _release():
        # Only the binding this build installed, and only while it is still
        # the live one -- a later build of the view replaces it, and
        # unbinding then would take the newer handler down with it.
        if bound["id"] is not None and getattr(app, "_flashcards_keybind", None) == bound["id"]:
            try:
                app.unbind("<Key>", bound["id"])
            except tk.TclError:
                pass
            app._flashcards_keybind = None
        bound["id"] = None

    def _on_key(event):
        if app.current_view != "flashcards" or getattr(app, "_flashcards_view", None) is not view_token:
            _release()
            return
        try:
            w = app.focus_get()
            if w is not None and w.winfo_class() in ("Entry", "Text", "TEntry", "TCombobox", "Spinbox"):
                return
        except (tk.TclError, KeyError):
            return
        ks = event.keysym
        if state["i"] >= len(due):
            if ks in ("Return", "KP_Enter"):
                app.show_view("dashboard")
            return
        if ks == "space" or (ks in ("Return", "KP_Enter") and not state["showing_def"]):
            flip_current()
        elif state["showing_def"] and event.char in ("1", "2", "3", "4"):
            grade_current(int(event.char) - 1)

    bound["id"] = app.bind("<Key>", _on_key)     # replaces any earlier build's handler
    app._flashcards_keybind = bound["id"]

    # Set by render(): the flip/grade actions for the card on screen.
    actions = {"flip": None, "grade": None}

    def flip_current():
        if actions["flip"]:
            actions["flip"]()

    def grade_current(g):
        if actions["grade"]:
            actions["grade"](g)

    def _days_phrase(new_state):
        """'Next review: in N days' from the schedule, in learner words."""
        try:
            nxt = _dt_from_iso(new_state.get("due_date"))
        except (TypeError, ValueError):
            return ""
        if nxt is None:
            return ""
        days = (nxt.astimezone().date() - date.today()).days
        if days <= 0:
            return "Next review: later today"
        if days == 1:
            return "Next review: tomorrow"
        return f"Next review: in {days} days"

    def render():
        for w in parent.winfo_children():
            w.destroy()
        actions["flip"] = actions["grade"] = None
        wrap = ctk.CTkFrame(parent, fg_color="transparent")
        wrap.pack(fill="both", expand=True, padx=32, pady=28)
        section_title(wrap, "Flashcards", "Each card comes back just before you'd forget it.").pack(anchor="w", pady=(0, 14))

        if state["i"] >= len(due):
            ctk.CTkLabel(wrap, text=f"Reviewed {state['reviewed']} card{'s' if state['reviewed']!=1 else ''} this session.",
                         font=(FONT_BODY, 14), text_color=C.INK).pack(anchor="w", pady=(20, 14))
            primary_button(wrap, "Back to Today", lambda: app.show_view("dashboard")).pack(anchor="w")
            return

        remaining = len(due) - state["i"]
        if mode != "due":
            banner_text = f"Nothing due \u2014 browsing full deck ({len(due)} card{'s' if len(due)!=1 else ''})."
        elif fresh_deck:
            banner_text = f"Up to {n_due_at_start} cards available \u2014 stop whenever you like."
        else:
            banner_text = f"{remaining} card{'s' if remaining!=1 else ''} due today."
        banner = card(wrap, fg_color=C.NAVY)
        banner.pack(fill="x", pady=(0, 16))
        brow = ctk.CTkFrame(banner, fg_color="transparent")
        brow.pack(fill="x", padx=16, pady=10)
        ctk.CTkLabel(brow, text=banner_text, font=(FONT_BODY, 12, "bold"),
                     text_color=C.CREAM).pack(side="left")

        # Deck order, chosen rather than shuffled. Persisted, because a
        # preference the learner has to re-pick every session is one they
        # will stop using.
        def _set_deck(pref):
            set_setting(conn, "flashcard_deck", pref)
            app.show_view("flashcards")

        ctk.CTkLabel(brow, text="order:", font=(FONT_BODY, 10),
                     text_color=C.GOLD_SOFT).pack(side="left", padx=(18, 6))
        for pref, lab in (("weakest", "weakest first"), ("topic", "by topic"),
                          ("random", "shuffled")):
            live = (deck_pref == pref)
            b = ctk.CTkButton(
                brow, text=lab, height=24, corner_radius=6,
                font=(FONT_BODY, 10, "bold"),
                fg_color=(C.BRASS if live else C.NAVY_2),
                hover_color=C.BRASS_DARK,
                text_color=("#221A0C" if live else C.GOLD_SOFT),
                command=(lambda p_=pref: _set_deck(p_)))
            b.pack(side="left", padx=3)

        c = due[state["i"]]
        st = get_card_state(conn, c["id"])
        topic = TOPICS[c["topic"]]
        # Scheduler internals (stability, reps, predicted recall) belong in
        # Author; the learner gets the topic and, once a card is graded,
        # when it will come back.
        meta_txt = topic["short"]
        if state["last_msg"]:
            meta_txt += f"   \u00b7   {state['last_msg']}"
        ctk.CTkLabel(wrap, text=meta_txt, font=(FONT_MONO, 11), text_color=C.INK_DIM, anchor="w").pack(anchor="w", pady=(0, 4))

        # Successive-relearning stage, distinct from FSRS's own interval --
        # a long FSRS interval means the schedule THINKS you'll remember it;
        # this shows whether you've actually cleared the stricter evidence-
        # based mastery criterion (Rawson & Dunlosky), not just gotten a
        # lucky good streak.
        if st["successive_relearning_complete"]:
            sr_txt, sr_color = "\u2713 Mastered (cleared 3 initial + 3 spaced correct recalls)", C.FOREST
        elif st["initial_criterion_met"]:
            sr_txt = (f"Relearning {st['relearn_sessions_completed']}/{RELEARN_SESSIONS_REQUIRED} "
                      "spaced sessions toward mastery")
            sr_color = C.BRASS_DARK
        elif st["initial_streak"] > 0:
            sr_txt = f"Learning: {st['initial_streak']}/{INITIAL_CRITERION_STREAK} correct in a row"
            sr_color = C.INK_DIM
        else:
            sr_txt, sr_color = "Not yet started", C.INK_DIM
        ctk.CTkLabel(wrap, text=sr_txt, font=(FONT_BODY, 10, "bold"), text_color=sr_color,
                    anchor="w").pack(anchor="w", pady=(0, 8))

        # The flashcard used to be a thin, full-width strip sitting in a
        # mostly-empty window -- for what is the single most repeated
        # interaction in the whole app, it read more like a text box that
        # happened to flip than an actual card. This gives it real
        # presence: a fixed, generous size, vertically centered in the
        # remaining space, with a brass border for depth (a real drop
        # shadow isn't available in Tk, and a first attempt at simulating
        # one with a place()-based offset backing frame rendered as
        # completely invisible when actually tested -- a plain colored
        # border is simpler and reliably visible).
        # LAYOUT ORDER MATTERS HERE. The grade buttons are packed to the
        # BOTTOM of `wrap` *before* the card claims the remaining space, so
        # they can never be pushed off-screen. Previously the card was a
        # fixed 620x300 packed into an expanding frame with the buttons
        # after it -- on a shorter window the card ate the height and the
        # Again/Hard/Good/Easy row was clipped out of view entirely, which
        # left the card flipping back and forth with no way to grade it.
        # height=0: an empty CTkFrame otherwise asks for 200 px, which on
        # the front face (no buttons yet) squeezed the card stage to nothing
        # at the "Larger" scale.
        grade_row = ctk.CTkFrame(wrap, fg_color="transparent", height=0)
        grade_row.pack(side="bottom", pady=(10, 4))
        hint = ctk.CTkLabel(wrap, text=("\u21bb  click the card or press Space to flip"
                                        if not state["showing_def"]
                                        else "1 Again \u00b7 2 Hard \u00b7 3 Good \u00b7 4 Easy"),
                            font=(FONT_BODY, 11), text_color=C.INK_DIM)
        hint.pack(side="bottom", pady=(6, 2))

        stage = ctk.CTkFrame(wrap, fg_color="transparent")
        stage.pack(fill="both", expand=True)
        stage.update_idletasks()

        # Card size ADAPTS to what is actually left over, rather than
        # asserting a fixed size the window may not have.
        avail_h = max(stage.winfo_height(), 160)
        avail_w = max(stage.winfo_width(), 320)
        # The floor must NEVER exceed what is actually available. A fixed
        # 150 px minimum overflowed the stage on a short window (900x560),
        # which pushed the grade row off screen and made the card
        # un-gradeable -- the same class of bug as the original fixed-size
        # card, reintroduced by an over-eager minimum.
        # winfo_* values are real pixels; CTk multiplies width/height/
        # wraplength by the UI scale, so hand it logical units or the card
        # outgrows the stage at the "Larger" setting.
        try:
            ui_sc = ctk.ScalingTracker.get_widget_scaling(stage) or 1.0
        except Exception:
            ui_sc = 1.0
        card_h = int(min(300, max(90, avail_h / ui_sc - 24)))
        card_w = int(min(620, max(260, avail_w / ui_sc - 60)))

        center = ctk.CTkFrame(stage, fg_color="transparent")
        center.place(relx=0.5, rely=0.5, anchor="center")

        face = ctk.CTkFrame(center, fg_color=C.PAPER_DIM, corner_radius=12,
                            width=card_w, height=card_h,
                            border_width=2, border_color=C.BRASS)
        face.pack()
        face.pack_propagate(False)

        if not state["showing_def"] and state["shown_at"] is None:
            state["shown_at"] = time.monotonic()
        term_size = (30 if card_h >= 240 else
                     24 if card_h >= 190 else
                     19 if card_h >= 140 else 16)
        if state["showing_def"]:
            # The back keeps the term above its definition: the learner is
            # grading recall of a pairing, and a definition on its own is
            # not gradeable once the prompt has vanished.
            inner = ctk.CTkFrame(face, fg_color="transparent")
            inner.place(relx=0.5, rely=0.5, anchor="center")
            term_lbl = ctk.CTkLabel(inner, text=c["term"], font=(FONT_DISPLAY, 15, "bold"),
                                    text_color=C.BRASS_DARK, wraplength=card_w - 70, justify="center")
            term_lbl.pack(pady=(0, 6))
            lbl = ctk.CTkLabel(inner, text=c["def"], font=(FONT_DISPLAY, 17),
                               text_color=C.INK, wraplength=card_w - 70, justify="center")
            lbl.pack()
            clickable = (face, inner, term_lbl, lbl)
        else:
            lbl = ctk.CTkLabel(face, text=c["term"], font=(FONT_DISPLAY, term_size, "bold"),
                               text_color=C.INK, wraplength=card_w - 70, justify="center")
            lbl.place(relx=0.5, rely=0.5, anchor="center")
            clickable = (face, lbl)

        def flip(_=None):
            state["showing_def"] = not state["showing_def"]
            render()
        for w in clickable:
            w.bind("<Button-1>", flip)
        actions["flip"] = flip

        if state["showing_def"]:
            row = grade_row
            grades = [("Again", 0, C.STAMP), ("Hard", 1, C.BRASS_DARK), ("Good", 2, C.BRASS), ("Easy", 3, C.FOREST)]

            def grade(g):
                # Deadline-awareness is now handled INSIDE hlr_update via
                # FSRS's desired_retention (see fsrs_desired_retention), so
                # no separate post-hoc due-date override is needed here.
                dur_ms = None
                if state["shown_at"] is not None:
                    dur_ms = int((time.monotonic() - state["shown_at"]) * 1000)
                # Schedule against the FLUENCY-ADJUSTED grade, but log the
                # learner's ORIGINAL grade -- the raw self-report is never
                # overwritten, so the adjustment stays auditable.
                eff_g, adjusted, reason = fluency_adjusted_grade(conn, g, dur_ms)
                new_state = hlr_update(st, eff_g, conn=conn)
                # Successive-relearning criterion is a layer ON TOP of FSRS's
                # own interval scheduling, not a replacement for it -- see
                # apply_successive_relearning_criterion. "Again" (g=0) is the
                # only grade that represents a failed recall; Hard/Good/Easy
                # all count as a successful one for this criterion, same as
                # they do for FSRS itself.
                apply_successive_relearning_criterion(new_state, correct=(g > 0))
                save_card_state(conn, c["id"], new_state)
                log_review(conn, c["id"], g, duration_ms=dur_ms)
                state["reviewed"] += 1
                state["i"] += 1
                state["showing_def"] = False
                state["shown_at"] = None
                # A card still in a learning/relearning step (FSRS state 1
                # or 3: its next step is minutes away) goes to the back of
                # this sitting's pile so the step is actually completed
                # here, the way Anki does it, instead of surfacing as
                # "still due" the moment the view is reopened.
                if new_state.get("state") in (1, 3):
                    due.append(c)
                    state["last_msg"] = "Last card: back again shortly"
                else:
                    state["last_msg"] = ("Last card: " + _days_phrase(new_state).lower()
                                         if _days_phrase(new_state) else "")
                if adjusted and reason:
                    app.toast("Hesitation noted \u2014 " + reason, kind="info")
                render()

            actions["grade"] = grade
            for lbl_txt, g, color in grades:
                ctk.CTkButton(row, text=lbl_txt, command=lambda g=g: grade(g), fg_color=color,
                             hover_color=C.INK, text_color="#fff", font=(FONT_BODY, 12, "bold"),
                             corner_radius=8, width=100, height=36).pack(side="left", padx=(0, 8))

    render()

# ============================================================================
# PRACTICE QUIZ
# ============================================================================

def select_quiz_pool(conn, scope, count):
    if scope == "weak":
        weak_ids = [tid for tid, _ in weakest_topics(conn, n=6)]
        pool = [q for q in QUIZ_LIST if q["topic"] in weak_ids] if weak_ids else list(QUIZ_LIST)
    elif scope == "national":
        pool = [q for q in QUIZ_LIST if TOPICS[q["topic"]]["group"] == "National"]
    elif scope == "nj":
        pool = [q for q in QUIZ_LIST if TOPICS[q["topic"]]["group"] == "NJ-Specific"]
    else:
        pool = list(QUIZ_LIST)
    random.shuffle(pool)
    return pool[:min(count, len(pool))]

def view_quiz(app, parent):
    wrap = ctk.CTkFrame(parent, fg_color="transparent")
    wrap.pack(fill="both", expand=True, padx=32, pady=28)
    section_title(wrap, "Practice Quiz", f"Bank of {len(QUIZ_LIST)} authored items. Untimed, with hints available.").pack(anchor="w", pady=(0, 20))
    mode_info_disclosure(wrap, "quiz")

    c = card(wrap)
    c.pack(fill="x", pady=(0, 16))
    inner = ctk.CTkFrame(c, fg_color="transparent")
    inner.pack(fill="x", padx=20, pady=18)

    ctk.CTkLabel(inner, text="Focus", font=(FONT_BODY, 12, "bold"), text_color=C.INK, anchor="w").pack(anchor="w")
    scope_var = tk.StringVar(value="all")
    scope_options = [("All topics", "all"), ("National only", "national"), ("NJ only", "nj"),
                      ("My weak topics", "weak"), ("Math drill (generative)", "math")]
    for lbl, val in scope_options:
        ctk.CTkRadioButton(inner, text=lbl, variable=scope_var, value=val, font=(FONT_BODY, 12),
                           text_color=C.INK, fg_color=C.BRASS, hover_color=C.BRASS_DARK, border_color=C.INK_DIM).pack(anchor="w", pady=2)

    ctk.CTkLabel(inner, text="Question count", font=(FONT_BODY, 12, "bold"), text_color=C.INK,
                 anchor="w").pack(anchor="w", pady=(14, 4))
    count_entry = styled_entry(inner, width=100, font=(FONT_BODY, 12))
    count_entry.insert(0, "15")
    count_entry.pack(anchor="w")

    elab_var = tk.BooleanVar(value=False)
    ctk.CTkCheckBox(inner, text="Explain-first mode (write why before answering)",
                    variable=elab_var, font=(FONT_BODY, 12), text_color=C.INK,
                    fg_color=C.BRASS, hover_color=C.BRASS_DARK,
                    checkmark_color=C.PAPER).pack(anchor="w", pady=(12, 0))

    def start():
        try:
            count = max(1, int(count_entry.get().strip()))
        except ValueError:
            count = 15
        scope = scope_var.get()
        if scope == "math":
            pool = [generate_math_item() for _ in range(count)]
        else:
            pool = select_quiz_pool(app.conn, scope, count)
        if not pool:
            return

        def on_finish(summary):
            app.conn.execute("INSERT INTO quiz_results (timestamp, total, correct, pct, scope) VALUES (?,?,?,?,?)",
                             (datetime.now().isoformat(), summary["total"], summary["correct"], summary["pct"], scope))
            app.conn.commit()
            render_result_screen(app, parent, summary, lambda: app.show_view("today"))

        QuestionSession(app, parent, pool, "quiz", "Practice Quiz", f"{len(pool)} questions \u00b7 {scope}",
                       allow_hints=True, collect_diagnostics=(scope != "math"),
                       elaborate=elab_var.get(), on_finish=on_finish)

    primary_button(inner, "Start Quiz", start).pack(anchor="w", pady=(18, 0))

    # ---- ENGINE-TARGETED STARTS ----
    # The launcher offered a random draw and a topic filter. The engine
    # knows which sub-skills are failing, which items are confusable, and
    # which the learner has never been served -- and none of it reached the
    # place a session actually begins. These start from what the engine
    # would pick, not from a shuffle.
    tcard = card(wrap)
    tcard.pack(fill="x", pady=(16, 0))
    ti = ctk.CTkFrame(tcard, fg_color="transparent")
    ti.pack(fill="x", padx=18, pady=14)
    ctk.CTkLabel(ti, text="Or start from what is failing",
                 font=(FONT_DISPLAY, 14, "bold"), text_color=C.INK,
                 anchor="w").pack(anchor="w")
    tl = ctk.CTkLabel(
        ti,
        text=("The engine ranks your sub-skills by weakness and exam weight, and "
              "knows which items you have never been shown. A random draw "
              "spends most of its questions on things you already know."),
        font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w", justify="left")
    tl.pack(anchor="w", fill="x", pady=(3, 10))
    bind_autowrap(tl, wrap, padding=90)

    def _launch(pool, title, sub):
        if not pool:
            app.toast("Nothing matched that target yet.", kind="warn")
            return
        QuestionSession(app, parent, pool, "quiz", title, sub,
                        allow_hints=True, collect_diagnostics=True,
                        on_finish=lambda summary: render_result_screen(
                            app, parent, summary, lambda: app.show_view("quiz")))

    def weakest():
        try:
            chosen, _ = focus_targets(app.conn, pages=12)
        except Exception:
            chosen = []
        pool, seen = [], set()
        for r in chosen:
            for q in r["items"]:
                if q["id"] not in seen:
                    seen.add(q["id"]); pool.append(q)
        _launch(pool[:20], "Weakest skills",
                f"{len(pool[:20])} items across your weakest sub-skills, in order.")

    def unseen():
        try:
            done = {r["question_id"] for r in _safe_query(
                app.conn, "SELECT DISTINCT question_id FROM attempts")}
        except Exception:
            done = set()
        pool = [q for q in QUIZ_LIST if q["id"] not in done]
        random.shuffle(pool)
        _launch(pool[:20], "Never seen",
                f"{len(pool)} items you have never been served; 20 of them here.")

    def confusable():
        try:
            targets = factory_targets(app.conn, limit=8)
        except Exception:
            targets = []
        pool, seen = [], set()
        for t in targets:
            for q in QUIZ_LIST:
                if t.get("skill") in Q_MATRIX.get(q["id"], []) and q["id"] not in seen:
                    seen.add(q["id"]); pool.append(q)
        _launch(pool[:16], "Lookalikes",
                "Items the bank marks as confusable with each other.")

    brow = ctk.CTkFrame(ti, fg_color="transparent", height=0)
    brow.pack(anchor="w")
    ghost_button(brow, "Weakest skills first", weakest).pack(side="left", padx=(0, 8))
    ghost_button(brow, "Items I have never seen", unseen).pack(side="left", padx=(0, 8))
    ghost_button(brow, "Confusable pairs", confusable).pack(side="left")

    quick_context_panel(wrap, app.conn)

