def view_diagnostic(app, parent):
    def show_setup():
        for w in parent.winfo_children():
            w.destroy()
        wrap = ctk.CTkFrame(parent, fg_color="transparent")
        wrap.pack(fill="both", expand=True, padx=32, pady=28)
        section_title(wrap, "Diagnostic Test", "Separates genuine content gaps from performance/timing issues.").pack(anchor="w", pady=(0, 20))
        mode_info_disclosure(wrap, "diagnostic")
        c = card(wrap)
        c.pack(fill="x", pady=(0, 16))
        inner = ctk.CTkFrame(c, fg_color="transparent")
        inner.pack(fill="x", padx=20, pady=18)
        ctk.CTkLabel(inner, text="You'll take a short timed set, then immediately retry anything you missed "
                     "with no clock.", font=(FONT_BODY, 12), text_color=C.INK_DIM, anchor="w",
                     wraplength=560, justify="left").pack(anchor="w", pady=(0, 14))
        ctk.CTkLabel(inner, text="Question count", font=(FONT_BODY, 12, "bold"), text_color=C.INK,
                     anchor="w").pack(anchor="w", pady=(0, 4))
        count_entry = styled_entry(inner, width=100, font=(FONT_BODY, 12))
        count_entry.insert(0, "20")
        count_entry.pack(anchor="w")

        def go():
            try:
                count = max(2, int(count_entry.get().strip()))
            except ValueError:
                count = 20
            maybe_offer_anxiety_routine(app, parent, "this diagnostic", lambda: start_timed(count))

        primary_button(inner, "Continue", go).pack(anchor="w", pady=(18, 0))
        quick_context_panel(wrap, app.conn)

    def start_timed(count):
        pool = list(QUIZ_LIST)
        random.shuffle(pool)
        pool = pool[:min(count, len(pool))]
        total_seconds = round(len(pool) * (240 * 60 / 110))

        def on_timed_finish(summary):
            missed = [q for i, q in enumerate(summary["questions"])
                      if summary["answers"][i] != q["a"]]
            timed_correct = summary["correct"]
            if not missed:
                finalize(len(pool), timed_correct, 0, 0)
                return
            start_redo(pool, timed_correct, missed)

        QuestionSession(app, parent, pool, "diagnostic_timed", "Diagnostic \u2014 Timed Portion",
                       f"{len(pool)} questions \u00b7 {total_seconds//60} min budget \u00b7 hints disabled",
                       timed=True, total_seconds=total_seconds, pressure_confidence=True,
                       on_finish=on_timed_finish)

    def start_redo(pool, timed_correct, missed):
        def on_redo_finish(summary):
            finalize(len(pool), timed_correct, summary["correct"], len(missed))

        QuestionSession(app, parent, missed, "diagnostic_untimed", "Diagnostic \u2014 Untimed Redo",
                       f"Retrying {len(missed)} missed question(s), no clock.",
                       diagnostic_redo=True, on_finish=on_redo_finish)

    def finalize(total_n, timed_correct, redo_correct, missed_count):
        timed_pct = round(100 * timed_correct / total_n, 1) if total_n else 0.0
        untimed_equiv_correct = timed_correct + redo_correct
        untimed_equiv_pct = round(100 * untimed_equiv_correct / total_n, 1) if total_n else 0.0
        gap_pct = round(untimed_equiv_pct - timed_pct, 1)

        if untimed_equiv_pct < 70:
            classification = "Content gap dominant \u2014 prioritize spaced retrieval review (Practice Quiz) before adding time pressure."
        elif untimed_equiv_pct >= 85 and gap_pct >= 15:
            classification = "Performance/pacing gap dominant \u2014 you know the material; the clock is the issue. Prioritize Progressive Timed Practice and full exams."
        else:
            classification = "Mixed picture \u2014 balance content review with progressive timed practice."

        app.conn.execute("""INSERT INTO diagnostic_results
            (timestamp, n, timed_correct, missed_count, untimed_redo_correct, timed_pct, untimed_equiv_pct, gap_pct, classification)
            VALUES (?,?,?,?,?,?,?,?,?)""",
            (datetime.now().isoformat(), total_n, timed_correct, missed_count, redo_correct,
             timed_pct, untimed_equiv_pct, gap_pct, classification))
        app.conn.commit()
        mark_session_today(app.conn)

        # The stored classification keeps its short engine prefix (Today's
        # headline keys on it); what the learner reads is written in terms
        # of what they did and what to do next, and the "next" points only
        # at a door that is open: generous-pace practice is a ladder rung
        # with an unlock rule, so while it is locked the honest step is the
        # work that opens it.
        if untimed_equiv_pct < 70:
            verdict = ("Some of this is still new. Untimed practice with the explanations "
                       "is what moves it \u2014 the clock can wait until the material is there.")
            next_step = "Today's session picks up the skills this diagnostic found; start there."
        elif untimed_equiv_pct >= 85 and gap_pct >= 15:
            verdict = ("You know this material \u2014 most of what the clock cost you, you got "
                       "right as soon as it was gone.")
            next_step = _rung2_locked_hint(app.conn) or (
                "Generous-pace timed sets are open on the Ladder; that is where this gap closes.")
        else:
            verdict = ("A mix: some items still need learning, and a few you knew but lost "
                       "under the clock.")
            next_step = ("Today's sessions cover both \u2014 relearning what was missed twice, "
                         "with timed practice folded in as skills settle.")
        summary = {"objective": "diagnostic", "title": "Diagnostic Results",
                   "total": total_n, "correct": timed_correct, "pct": timed_pct,
                   "verdict": verdict, "next_step": next_step, "done_label": "Back to Today"}
        rows = [("Timed", f"{timed_pct:.0f}%  ({timed_correct} of {total_n})"),
                ("Untimed retry", f"{redo_correct} of {missed_count} recovered"),
                ("Knew it, given time", f"{untimed_equiv_pct:.0f}%")]
        render_result_screen(app, parent, summary, lambda: app.show_view("today"),
                             extra_rows=rows)

    show_setup()

