def view_progressive(app, parent):
    def show_setup():
        for w in parent.winfo_children():
            w.destroy()
        wrap = ctk.CTkFrame(parent, fg_color="transparent")
        wrap.pack(fill="both", expand=True, padx=32, pady=28)
        section_title(wrap, "Progressive Timed Practice", "Interleaved, mixed-topic sets at increasing pace.").pack(anchor="w", pady=(0, 20))
        mode_info_disclosure(wrap, "progressive")
        c = card(wrap)
        c.pack(fill="x", pady=(0, 16))
        inner = ctk.CTkFrame(c, fg_color="transparent")
        inner.pack(fill="x", padx=20, pady=18)

        ctk.CTkLabel(inner, text="Pace", font=(FONT_BODY, 12, "bold"), text_color=C.INK, anchor="w").pack(anchor="w")
        tier_var = tk.StringVar(value=(getattr(app, "_ladder_tier", None) or "generous"))
        # A locked pace states its own condition here, before Continue is
        # pressed -- a rung the learner cannot open should never be a surprise
        # discovered by pressing a button.
        try:
            by_tier = {r.get("tier"): r for r in ladder_rungs(app.conn) if r.get("tier")}
        except Exception:
            by_tier = {}
        for _tier, _label in (("generous", "Generous (2x real exam pace)"),
                              ("strict", "Strict (real exam pace)")):
            ctk.CTkRadioButton(inner, text=_label, variable=tier_var, value=_tier,
                               font=(FONT_BODY, 12), text_color=C.INK, fg_color=C.BRASS,
                               border_color=C.INK_DIM).pack(anchor="w", pady=2)
            _r = by_tier.get(_tier)
            if _r is not None and not _r["open"] and _r.get("unlock"):
                _ul = ctk.CTkLabel(inner, text="Locked — " + _r["unlock"],
                                   font=(FONT_BODY, 10), text_color=C.INK_DIM,
                                   anchor="w", justify="left")
                _ul.pack(anchor="w", fill="x", padx=(24, 0))
                bind_autowrap(_ul, inner, padding=40)

        ctk.CTkLabel(inner, text="Question count", font=(FONT_BODY, 12, "bold"), text_color=C.INK,
                     anchor="w").pack(anchor="w", pady=(14, 4))
        count_entry = styled_entry(inner, width=100, font=(FONT_BODY, 12))
        count_entry.insert(0, "15")
        count_entry.pack(anchor="w")

        def go():
            try:
                count = max(1, int(count_entry.get().strip()))
            except ValueError:
                count = 15
            tier = tier_var.get()
            if not rung_open(app.conn, "progressive", tier):
                # The refusal carries its own condition and distance: being
                # told to go and look somewhere else is the failure mode
                # directive IV names.
                _r = next((r for r in ladder_rungs(app.conn) if r.get("tier") == tier), None)
                app.toast("That pace isn't open yet. "
                          + ((_r or {}).get("unlock") or "See the Ladder for what unlocks it."),
                          kind="info")
                return
            if tier == "strict":
                maybe_offer_anxiety_routine(app, parent, "this strict-paced set", lambda: start(count, tier))
            else:
                start(count, tier)

        primary_button(inner, "Continue", go).pack(anchor="w", pady=(18, 0))
        quick_context_panel(wrap, app.conn)

    def start(count, tier):
        pool = list(QUIZ_LIST)
        random.shuffle(pool)
        pool = pool[:min(count, len(pool))]
        per_q = (240 * 60 / 110) * (2 if tier == "generous" else 1)
        total_seconds = round(per_q * len(pool))
        # Only the strict tier runs at the pace the reframe is about; the
        # generous tier is not an occasion and is not assigned an arm.
        rkey = reappraisal_occasion_key("progressive_strict") if tier == "strict" else None

        def on_finish(summary):
            app.conn.execute("INSERT INTO quiz_results (timestamp, total, correct, pct, scope) VALUES (?,?,?,?,?)",
                             (datetime.now().isoformat(), summary["total"], summary["correct"], summary["pct"],
                              "progressive_" + tier))
            app.conn.commit()
            if rkey:
                record_reappraisal_outcome(app.conn, rkey, summary)
            render_result_screen(app, parent, summary, lambda: app.show_view("today"))

        def begin():
            QuestionSession(app, parent, pool, "progressive_" + tier, "Progressive Practice",
                           f"{len(pool)} interleaved questions \u00b7 {tier} pace \u00b7 hints disabled",
                           timed=True, total_seconds=total_seconds, pressure_confidence=True,
                           on_finish=on_finish)

        if rkey:
            maybe_show_arousal_reframe(app, parent, rkey, begin)
        else:
            begin()

    show_setup()

