def build_exam(count):
    national = [q for q in QUIZ_LIST if TOPICS[q["topic"]]["group"] == "National"]
    nj = [q for q in QUIZ_LIST if TOPICS[q["topic"]]["group"] == "NJ-Specific"]
    nat_target = round(count * 80 / 110)
    nj_target = count - nat_target
    random.shuffle(national)
    random.shuffle(nj)
    picked = [national[i % len(national)] for i in range(nat_target)]
    picked += [nj[i % len(nj)] for i in range(nj_target)]
    random.shuffle(picked)
    return picked

def _exam_seconds(count):
    """Time budget for a count-item exam at the real PSI pace."""
    return round(count * PACE_TARGET_SECONDS)

def _exam_minutes(count):
    """The minute figure the setup labels and the running session share, so
    the number the learner picked is the number the session shows."""
    return round(_exam_seconds(count) / 60)

def view_exam(app, parent):
    def show_setup():
        for w in parent.winfo_children():
            w.destroy()
        wrap = ctk.CTkFrame(parent, fg_color="transparent")
        wrap.pack(fill="both", expand=True, padx=32, pady=28)
        section_title(wrap, "Timed Practice Exam", "80/30 national/NJ ratio, paced like the real 110Q / 240-min PSI exam.").pack(anchor="w", pady=(0, 20))
        mode_info_disclosure(wrap, "exam")
        c = card(wrap)
        c.pack(fill="x", pady=(0, 16))
        inner = ctk.CTkFrame(c, fg_color="transparent")
        inner.pack(fill="x", padx=20, pady=18)
        ctk.CTkLabel(inner, text="Length", font=(FONT_BODY, 12, "bold"), text_color=C.INK, anchor="w").pack(anchor="w")
        len_var = tk.StringVar(value="30")
        _days = days_to_exam(app.conn)
        _lengths = [(f"30 questions (~{_exam_minutes(30)} min)", "30"),
                    (f"60 questions (~{_exam_minutes(60)} min)", "60")]
        if _days is not None and _days <= 21:
            _lengths.append((f"110 questions ({_exam_minutes(110)} min \u2014 full simulation)", "110"))
        for lbl, val in _lengths:
            ctk.CTkRadioButton(inner, text=lbl, variable=len_var, value=val, font=(FONT_BODY, 12),
                               text_color=C.INK, fg_color=C.BRASS, border_color=C.INK_DIM).pack(anchor="w", pady=2)
        if _days is None:
            ctk.CTkLabel(inner, text="The full 110-question simulation opens inside 21 days of your exam "
                         "date \u2014 set the date in Settings to unlock it.",
                         font=(FONT_BODY, 10), text_color=C.INK_DIM, anchor="w",
                         wraplength=520, justify="left").pack(anchor="w", pady=(2, 0))
        elif _days > 21:
            ctk.CTkLabel(inner, text=f"The full 110-question simulation opens inside 21 days of your exam "
                         f"({_days} days away).", font=(FONT_BODY, 10), text_color=C.INK_DIM,
                         anchor="w", wraplength=520, justify="left").pack(anchor="w", pady=(2, 0))

        pp_var = tk.BooleanVar(value=True)   # spec 7.9: default on rung 4
        ctk.CTkCheckBox(inner, text="Show the pre-answer routine on every question",
                        variable=pp_var, font=(FONT_BODY, 12), text_color=C.INK,
                        fg_color=C.BRASS, hover_color=C.BRASS_DARK,
                        checkmark_color=C.PAPER, border_color=C.INK_DIM).pack(anchor="w", pady=(12, 0))
        ctk.CTkLabel(inner, text="A short fixed routine practiced on each item. Strongest evidence in "
                     "the 2026 choking meta-analysis for precise, self-paced tasks like exam questions.",
                     font=(FONT_BODY, 10), text_color=C.INK_DIM, anchor="w",
                     wraplength=520, justify="left").pack(anchor="w", pady=(2, 0))

        _rung_ok = rung_open(app.conn, "exam")
        if not _rung_ok:
            _why = next((r["why"] for r in ladder_rungs(app.conn) if r["key"] == "exam"), "")
            ctk.CTkLabel(inner, text="This rung isn't open yet. " + _why, font=(FONT_BODY, 11, "italic"),
                         text_color=C.INK_DIM, anchor="w", wraplength=520, justify="left").pack(anchor="w", pady=(10, 0))

        def go():
            count = int(len_var.get())
            if not rung_open(app.conn, "exam"):
                app.toast("The exam rung isn't open yet \u2014 see the Ladder for what unlocks it.", kind="info")
                return
            maybe_offer_anxiety_routine(
                app, parent, "this exam simulation",
                lambda: ask_prediction(app, parent, "exam",
                                       lambda: start(count, pp_var.get())))

        _go_btn = primary_button(inner, "Continue", go)
        _go_btn.pack(anchor="w", pady=(18, 0))
        if not _rung_ok:
            try:
                _go_btn.configure(state="disabled")
            except Exception:
                pass
        quick_context_panel(wrap, app.conn)

    def start(count, pre_performance=False):
        questions = build_exam(count)
        total_seconds = _exam_seconds(count)
        rkey = reappraisal_occasion_key("exam")

        def on_finish(summary):
            # Each answer was already recorded (or updated, if changed via
            # back-navigation) live during the session by QuestionSession --
            # do not re-record here, or every question would be double-
            # counted toward ability estimation and topic mastery.
            # A blank counts as wrong in its section, as in the overall
            # score, so the two portions add up to the headline figure.
            nat_total = nat_correct = nj_total = nj_correct = 0
            for i, q in enumerate(summary["questions"]):
                a = summary["answers"][i] if i < len(summary["answers"]) else None
                is_correct = (a is not None and a == q["a"])
                if TOPICS[q["topic"]]["group"] == "National":
                    nat_total += 1
                    nat_correct += 1 if is_correct else 0
                else:
                    nj_total += 1
                    nj_correct += 1 if is_correct else 0
            nat_pct = round(100 * nat_correct / nat_total, 1) if nat_total else None
            nj_pct = round(100 * nj_correct / nj_total, 1) if nj_total else None
            app.conn.execute("""INSERT INTO exam_results
                (timestamp, total, correct, pct, time_used, national_pct, nj_pct)
                VALUES (?,?,?,?,?,?,?)""",
                (datetime.now().isoformat(), summary["total"], summary["correct"], summary["pct"],
                 summary["time_used"], nat_pct, nj_pct))
            app.conn.commit()

            extra = []
            if nat_pct is not None:
                extra.append(("National portion", f"{nat_correct}/{nat_total} ({nat_pct}%)"))
            if nj_pct is not None:
                extra.append(("NJ portion", f"{nj_correct}/{nj_total} ({nj_pct}%)"))
            extra.append(("Time used", f"{int(summary['time_used']//60)} min"))
            pred = take_prediction(app.conn)
            if pred:
                record_calibration(app.conn, pred["predicted"], summary["pct"])
                diff = pred["predicted"] - summary["pct"]
                extra.append(("You predicted",
                              f'{pred["predicted"]}%  ({diff:+.0f} vs actual)'))
            record_reappraisal_outcome(app.conn, rkey, summary)
            render_result_screen(app, parent, summary, lambda: app.show_view("today"), extra_rows=extra)

        def begin():
            QuestionSession(app, parent, questions, "exam", "Timed Practice Exam",
                           f"{len(questions)} questions \u00b7 {_exam_minutes(count)} min \u00b7 hints disabled",
                           timed=True, total_seconds=total_seconds, allow_back=True,
                           pressure_confidence=True, pre_performance=pre_performance,
                           on_finish=on_finish)

        maybe_show_arousal_reframe(app, parent, rkey, begin)

    show_setup()

