# ERROR LOG
# ============================================================================

def view_error_log(app, parent):
    """THE ERROR LOG, rebuilt as a diagnosis surface.

    The old version listed tagged misses with a topic and a count. It used
    none of the engine: no misconception tag, no belief state, no skill
    mastery, no repair action, no grouping by what the misses have in
    common. For the one screen that exists to look at what went wrong,
    that was the most underpowered view in the app relative to its job.

    Misses are now grouped by the SKILL they share rather than listed by
    date -- five misses on one sub-skill are one problem, not five -- and
    each carries the authored diagnosis of the option actually chosen.
    """
    conn = app.conn
    scroll = ctk.CTkScrollableFrame(parent, fg_color="transparent")
    scroll.pack(fill="both", expand=True, padx=30, pady=(20, 10))
    section_title(scroll, "Error Log",
                  "What went wrong, what it points to, and what to do about it."
                  ).pack(anchor="w", pady=(0, 12))

    rows = conn.execute("SELECT * FROM error_log WHERE active=1 "
                        "ORDER BY tagged_at DESC").fetchall()
    # Misses on promoted candidate items (`cand-<id>`) are logged like any
    # other, so they are resolved through the same bank the picker serves
    # from; a miss the page can neither show nor drill must not be counted.
    bank = dict(QUIZ_BANK)
    try:
        bank.update({c["id"]: c for c in promoted_candidates(conn)})
    except sqlite3.Error as e:
        _audit(conn, "errorlog_candidates_failed", str(e))
    rows = [r for r in rows if r["question_id"] in bank]
    if not rows:
        ctk.CTkLabel(scroll,
                     text="Nothing active \u2014 either you haven't tagged a miss "
                          "yet, or everything has graduated. Misses get tagged "
                          "automatically in Practice Quiz and the Diagnostic Test.",
                     font=(FONT_BODY, 13), text_color=C.INK_DIM, wraplength=620,
                     justify="left", anchor="w").pack(anchor="w")
        return

    from collections import Counter, defaultdict
    # error_type is stored with mixed case by different code paths, so
    # "content" and "Content" rendered as two chips for one category.
    counts = Counter(str(r["error_type"] or "untagged").lower() for r in rows)
    chips = ctk.CTkFrame(scroll, fg_color="transparent")
    chips.pack(fill="x", pady=(0, 14))
    stat_chip(chips, "Active misses", str(len(rows))).pack(side="left", padx=(0, 10))
    for k, v in counts.most_common(3):
        stat_chip(chips, str(k).title(), str(v)).pack(side="left", padx=(0, 10))

    by_skill = defaultdict(list)
    orphan = []
    for r in rows:
        q = bank.get(r["question_id"])
        if not q:
            continue
        sk = Q_MATRIX.get(q["id"]) or [s for s in q.get("skills", []) if s in SKILLS]
        if sk:
            by_skill[sk[0]].append((r, q))
        else:
            orphan.append((r, q))

    mast_cache = {}

    def _mastery(sid):
        if sid in mast_cache:
            return mast_cache[sid]
        tid = SKILLS.get(sid, {}).get("topic")
        m = 0.5
        try:
            if tid and len(topic_skill_ids(tid)) >= 2:
                post = dina_topic_posterior(conn, tid)
                if post:
                    m = post["skill_mastery"].get(sid, 0.5)
            elif tid:
                m = get_mastery(conn, tid)
        except Exception:
            pass
        mast_cache[sid] = m
        return m

    groups = sorted(by_skill.items(), key=lambda kv: (_mastery(kv[0]), -len(kv[1])))

    # One thing underneath several misses? The prerequisite graph can say.
    root_causes = Counter()
    for sid, _ in groups:
        try:
            b = upstream_bottleneck(conn, sid)
            if b:
                root_causes[b["skill"]] += len(by_skill[sid])
        except Exception:
            pass
    if root_causes:
        rc, n = root_causes.most_common(1)[0]
        if n >= 2:
            rcard = card(scroll, fg_color=C.NAVY)
            rcard.pack(fill="x", pady=(0, 14))
            ri = ctk.CTkFrame(rcard, fg_color="transparent")
            ri.pack(fill="x", padx=18, pady=12)
            ctk.CTkLabel(ri, text="One thing underneath several of these",
                         font=(FONT_BODY, 10, "bold"), text_color=C.BRASS,
                         anchor="w").pack(anchor="w")
            rl = ctk.CTkLabel(
                ri,
                text=(f"{n} of your misses sit on skills that rest on "
                      f"{SKILLS.get(rc, {}).get('label', rc)} "
                      f"({_mastery(rc)*100:.0f}%). Drilling the misses one by one "
                      "will not hold until that is fixed."),
                font=(FONT_BODY, 12), text_color=C.CREAM, anchor="w", justify="left")
            rl.pack(anchor="w", fill="x", pady=(3, 0))
            bind_autowrap(rl, scroll, padding=110)
            ctk.CTkLabel(ri, text="inferred from your own results, not authored",
                         font=(FONT_BODY, 9), text_color=C.GOLD_SOFT,
                         anchor="w").pack(anchor="w", pady=(2, 0))
            primary_button(ri, "Open that skill",
                           lambda s_=rc: show_skill_note(conn, s_, app)).pack(
                               anchor="w", pady=(8, 0))

    def render_group(sid, pairs):
        m = _mastery(sid)
        label = SKILLS.get(sid, {}).get("label", sid)
        gc = card(scroll)
        gc.pack(fill="x", pady=4)
        gi = ctk.CTkFrame(gc, fg_color="transparent")
        gi.pack(fill="x", padx=16, pady=12)
        hdr = ctk.CTkFrame(gi, fg_color="transparent", height=0)
        hdr.pack(fill="x")
        ctk.CTkLabel(hdr, text=label, font=(FONT_BODY, 13, "bold"),
                     text_color=C.INK, anchor="w").pack(side="left")
        mcol = C.STAMP if m < 0.35 else (C.BRASS_DARK if m < 0.7 else C.FOREST)
        ctk.CTkLabel(hdr, text=f"{m*100:.0f}%  \u00b7  {len(pairs)} miss(es)",
                     font=(FONT_BODY, 11, "bold"), text_color=mcol,
                     anchor="e").pack(side="right")
        try:
            bl = [b for b in active_beliefs(conn, limit=30) if b["skill_id"] == sid]
        except Exception:
            bl = []
        if bl:
            bv = belief_view(conn, bl[0]["belief_id"])
            if bv:
                ctk.CTkLabel(gi, text=belief_summary_line(bv), font=(FONT_BODY, 11),
                             text_color=(C.STAMP if bv["state"] == "reopened"
                                         else C.INK_DIM),
                             anchor="w", justify="left",
                             wraplength=700).pack(anchor="w", pady=(4, 0))
        for r, q in pairs[:4]:
            ctk.CTkLabel(gi, text="\u2022  " + q["q"][:110], font=(FONT_BODY, 11),
                         text_color=C.INK, anchor="w", justify="left",
                         wraplength=700).pack(anchor="w", pady=(6, 0))
            chosen = None
            try:
                last = conn.execute(
                    "SELECT chosen FROM attempts WHERE question_id=? AND correct=0 "
                    "ORDER BY id DESC LIMIT 1", (q["id"],)).fetchone()
                chosen = last["chosen"] if last else None
            except Exception:
                pass
            opts = q.get("opts") or []
            if chosen is not None and chosen < len(opts) and chosen != q.get("a"):
                mm = enriched_misconception(q["id"], chosen)
                diag = (mm or {}).get("diagnosis") or ""
                ctk.CTkLabel(gi,
                             text=(f'     you chose \u201c{opts[chosen][:60]}\u201d'
                                   + (f" \u2014 {diag[:150]}" if diag else "")),
                             font=(FONT_BODY, 10),
                             text_color=(C.STAMP if diag else C.INK_DIM),
                             anchor="w", justify="left",
                             wraplength=690).pack(anchor="w")
            ctk.CTkLabel(gi, text=f"     {r['error_type']}  \u00b7  "
                                  f"{r['consecutive_correct']}/2 to graduate",
                         font=(FONT_BODY, 9), text_color=C.INK_DIM,
                         anchor="w").pack(anchor="w")
        if len(pairs) > 4:
            ctk.CTkLabel(gi, text=f"     + {len(pairs) - 4} more on this skill",
                         font=(FONT_BODY, 9), text_color=C.INK_DIM,
                         anchor="w").pack(anchor="w")
        brow = ctk.CTkFrame(gi, fg_color="transparent", height=0)
        brow.pack(anchor="w", pady=(10, 0))
        seen_ids = {q["id"] for _, q in pairs}
        untreated = [x for x in QUIZ_LIST if sid in Q_MATRIX.get(x["id"], [])
                     and x["id"] not in seen_ids]
        if untreated:
            ghost_button(brow, f"Apply it to {len(untreated)} unseen item(s)",
                         lambda pool=untreated, l=label: QuestionSession(
                             app, parent, pool, "quiz", l,
                             "Items on this skill you have not missed yet.",
                             allow_hints=True, collect_diagnostics=True,
                             on_finish=lambda _s: app.show_view("errorlog"))
                         ).pack(side="left", padx=(0, 8))
        ghost_button(brow, "Open the brief",
                     lambda s_=sid: show_skill_note(conn, s_, app)).pack(side="left")

    for sid, pairs in groups[:12]:
        render_group(sid, pairs)
    if len(groups) > 12:
        ctk.CTkLabel(scroll, text=f"{len(groups) - 12} more skill(s) with misses.",
                     font=(FONT_BODY, 11), text_color=C.INK_DIM,
                     anchor="w").pack(anchor="w", pady=(6, 0))

    def drill():
        ordered = [q for sid, pairs in groups for _, q in pairs]
        ordered += [q for _, q in orphan]

        def on_finish(summary):
            render_result_screen(app, parent, summary,
                                 lambda: app.show_view("errorlog"))

        QuestionSession(app, parent, ordered, "quiz", "Error Log Drill",
                        f"{len(ordered)} tagged misses, weakest skill first",
                        allow_hints=True, collect_diagnostics=True,
                        on_finish=on_finish)

    primary_button(scroll, "Drill all, weakest skill first", drill).pack(
        anchor="w", pady=(16, 0))

# ============================================================================
# FREE-RECALL DRILL
# ============================================================================

def recall_band(score):
    if score >= 60:
        return "Strong recall", C.FOREST
    if score >= 30:
        return "Partial recall", C.BRASS_DARK
    return "Weak recall", C.STAMP

def view_freerecall(app, parent):
    conn = app.conn
    state = {"model": None, "nli_model": None, "model_tried": False, "loaded": False}

    due = [c for c in FLASHCARDS if card_due_today(get_card_state(conn, c["id"]))]
    if not due:
        due = list(FLASHCARDS)
    random.shuffle(due)
    session = {"i": 0, "scores": [], "started_at": None}
    # Identity of THIS build of the view. `parent` is app.content, which
    # survives navigation, so a background scorer that finishes after the
    # learner has moved on must be able to tell it is stale.
    view_token = object()
    app._freerecall_view = view_token

    def view_is_current():
        return (app.current_view == "freerecall"
                and getattr(app, "_freerecall_view", None) is view_token)

    def get_model():
        """Return whichever scoring models are already loaded; never block
        the UI waiting on either."""
        return state["model"], state["nli_model"]

    def begin_background_load():
        if state["model_tried"]:
            return
        state["model_tried"] = True

        def worker():
            # semantic_available() performs the actual `import
            # sentence_transformers`, which pulls in transformers/torch and
            # can block for many seconds on first call. Probing it out here
            # (rather than before starting the thread) is what keeps the
            # "background" load genuinely off the UI thread -- checking it
            # first froze the whole window on the very first visit.
            if not semantic_available():
                state["loaded"] = True
                return
            try:
                state["model"] = _get_embed_model()
            except Exception:
                state["model"] = None
            try:
                state["nli_model"] = _get_nli_model()
            except Exception:
                state["nli_model"] = None
            state["loaded"] = True

        import threading
        threading.Thread(target=worker, daemon=True).start()

    def render_prompt():
        begin_background_load()
        for w in parent.winfo_children():
            w.destroy()
        wrap = ctk.CTkScrollableFrame(parent, fg_color="transparent")
        wrap.pack(fill="both", expand=True, padx=32, pady=28)
        section_title(wrap, "Free-Recall Drill",
                      "Type the definition from memory. Harder than multiple choice \u2014 and a much "
                      "better test of what you actually know.").pack(anchor="w", pady=(0, 16))
        mode_info_disclosure(wrap, "freerecall")

        if session["i"] >= len(due):
            avg = sum(session["scores"]) / len(session["scores"]) if session["scores"] else 0
            ctk.CTkLabel(wrap, text=f"Session complete \u2014 {len(session['scores'])} terms, "
                         f"average {avg:.0f}%", font=(FONT_BODY, 14), text_color=C.INK).pack(anchor="w", pady=(10, 14))
            primary_button(wrap, "Back to Today", lambda: app.show_view("dashboard")).pack(anchor="w")
            return

        c = due[session["i"]]
        # Clock starts when the term is presented, so the measured
        # duration covers the actual retrieval attempt.
        session["started_at"] = time.monotonic()
        topic = TOPICS[c["topic"]]
        ctk.CTkLabel(wrap, text=f"Term {session['i']+1} of {len(due)}  \u00b7  {topic['short']}",
                     font=(FONT_MONO, 11), text_color=C.INK_DIM, anchor="w").pack(anchor="w", pady=(0, 8))

        face = card(wrap, fg_color=C.PAPER_DIM)
        face.pack(fill="x")
        ctk.CTkLabel(face, text=c["term"], font=(FONT_DISPLAY, 22, "bold"), text_color=C.INK,
                     wraplength=640, justify="center").pack(padx=30, pady=22)

        if semantic_available_cached() is not False and not (state["model"] and state["nli_model"]):
            ctk.CTkLabel(wrap,
                         text=("Semantic/entailment scorers loading in the background \u2014 answers "
                               "are scored by key-term coverage until ready. You can keep going."),
                         font=(FONT_BODY, 10), text_color=C.INK_DIM, anchor="w",
                         justify="left").pack(anchor="w", pady=(10, 0))
        ctk.CTkLabel(wrap, text="Write what it means, in your own words:", font=(FONT_BODY, 12, "bold"),
                     text_color=C.INK, anchor="w").pack(anchor="w", pady=(16, 6))
        box = ctk.CTkTextbox(wrap, height=130, font=(FONT_BODY, 13), fg_color="#FFFFFF",
                              text_color=C.INK, corner_radius=10, border_width=1, border_color=C.PAPER_LINE)
        box.pack(fill="x")
        box.focus_set()

        btnrow = ctk.CTkFrame(wrap, fg_color="transparent")
        btnrow.pack(anchor="w", pady=(14, 0))
        primary_button(btnrow, "Check my answer",
                       lambda: render_result(c, box.get("1.0", "end").strip())).pack(side="left", padx=(0, 8))
        ghost_button(btnrow, "Skip", advance).pack(side="left")

    def render_result(c, user_text):
        gpu = gpu_config(conn)
        if gpu:
            render_result_gpu(c, user_text, gpu)
            return
        model, nli_model = get_model()
        if model or nli_model:
            # Local embedding/NLI models are already loaded in memory --
            # this is fast and safe to run directly in the click handler.
            score, covered, missed, method, sig = score_free_recall(
                user_text, c["def"], model=model, nli_model=nli_model, return_signals=True)
            render_result_screen(c, user_text, score, covered, missed, method, signals=sig)
            return

        api_key = get_setting(conn, "anthropic_api_key", "")
        if not api_key:
            # No local model and no API key configured -- keyword coverage
            # only, which is synchronous and safe to run inline.
            score, covered, missed, method, sig = score_free_recall(
                user_text, c["def"], return_signals=True)
            render_result_screen(c, user_text, score, covered, missed, method, signals=sig)
            return

        # API-based scoring is a real network call and must NOT run on the
        # UI thread -- doing that would freeze the whole window for the
        # duration of the request, the same class of bug fixed earlier for
        # the tutor and the Explorer's clustering worker. Show a brief
        # loading state and hand the request to a background thread instead.
        for w in parent.winfo_children():
            w.destroy()
        loading_wrap = ctk.CTkFrame(parent, fg_color="transparent")
        loading_wrap.pack(fill="both", expand=True, padx=32, pady=28)
        section_title(loading_wrap, "Free-Recall Drill", c["term"]).pack(anchor="w", pady=(0, 14))
        ctk.CTkLabel(loading_wrap, text="Scoring your answer via the API\u2026",
                    font=(FONT_BODY, 13), text_color=C.INK_DIM).pack(anchor="w")

        holder = {}

        def worker():
            # Try the PER-CRITERION rubric grader first. It evaluates core
            # concept, qualifiers and factual accuracy separately, because a
            # single holistic score lets one strong phrase halo the whole
            # answer -- and it can return "uncertain" instead of inventing a
            # number. rubric_grade_free_recall existed for several passes
            # and was never called; the flat API scorer below was doing all
            # the work.
            try:
                res, rerr = rubric_grade_free_recall(api_key, c["term"],
                                                     c["def"], user_text)
            except Exception:
                res, rerr = None, "rubric grader unavailable"
            if res and not res.get("uncertain"):
                holder["api_score"] = res["score_pct"]
                holder["method_tag"] = "rubric"
                holder["criteria"] = res.get("criteria", [])
                holder["err"] = None
                return
            if res and res.get("uncertain"):
                # An explicit abstention is a valid outcome and must not be
                # silently replaced with a guess from the weaker scorer.
                holder["api_score"] = None
                holder["method_tag"] = "rubric_uncertain"
                holder["err"] = ("The grader could not judge this fairly: "
                                 + (res.get("note") or "answer too short or "
                                    "off-topic") + " \u2014 scored on key terms only.")
                return
            api_score, method_tag, err = score_free_recall_via_api(api_key, user_text, c["def"])
            holder["api_score"] = api_score
            holder["method_tag"] = method_tag
            holder["err"] = err

        import threading
        threading.Thread(target=worker, daemon=True).start()

        def poll():
            # The learner may have navigated away while the request was in
            # flight; the reply must then be dropped, not painted over
            # whatever view now occupies app.content.
            if not view_is_current() or not loading_wrap.winfo_exists():
                return
            if "api_score" not in holder and "err" not in holder:
                app.after(150, poll)
                return
            keyword_score, covered, missed = keyword_coverage(user_text, c["def"])
            if holder.get("api_score") is not None:
                # Blend the same way the local semantic+keyword path does,
                # rather than trusting the API score alone. The API grade
                # stands in for the similarity signal in the classifier.
                blended = round(0.7 * holder["api_score"] + 0.3 * (keyword_score * 100), 1)
                render_result_screen(c, user_text, blended, covered, missed, "api+keyword",
                                     signals={"coverage": keyword_score,
                                              "sim01": holder["api_score"] / 100.0,
                                              "entail": None})
            else:
                # API call failed -- degrade to keyword-only rather than
                # showing an error and losing the attempt entirely.
                render_result_screen(c, user_text, round(keyword_score * 100, 1),
                                     covered, missed, "keyword",
                                     signals={"coverage": keyword_score,
                                              "sim01": None, "entail": None})

        app.after(150, poll)

    def render_result_gpu(c, user_text, gpu):
        for w in parent.winfo_children():
            w.destroy()
        loading_wrap = ctk.CTkFrame(parent, fg_color="transparent")
        loading_wrap.pack(fill="both", expand=True, padx=32, pady=28)
        section_title(loading_wrap, "Free-Recall Drill", c["term"]).pack(anchor="w", pady=(0, 14))
        ctk.CTkLabel(loading_wrap, text="Checking your answer\u2026",
                     font=(FONT_BODY, 13), text_color=C.INK_DIM).pack(anchor="w")
        holder = {}

        def worker():
            try:
                holder["res"], holder["err"] = gpu_grade_free_recall(
                    gpu, c["term"], c["def"], user_text)
            except Exception as e:
                holder["res"], holder["err"] = None, str(e)

        import threading
        threading.Thread(target=worker, daemon=True).start()

        def poll():
            if not view_is_current() or not loading_wrap.winfo_exists():
                return
            if "err" not in holder:
                app.after(150, poll)
                return
            res = holder.get("res")
            rung = get_setting(conn, GRADER_SETTING_RUNG, "canary") or "canary"
            model, nli_model = get_model()
            score, covered, missed, method, sig = score_free_recall(
                user_text, c["def"], model=model, nli_model=nli_model, return_signals=True)
            try:
                _pair = json.loads(get_setting(conn, "grader_active_pair", "") or "null")
            except ValueError:
                _pair = None
            use, suffix, shadow = free_recall_score_decision(res, score, rung, promoted_pair=_pair)
            record_grader_shadow_v81(conn, c["term"], c["def"], user_text, score, res, rung)
            if suffix == "gpu-dual":
                keyword_score, covered, missed = keyword_coverage(user_text, c["def"])
                blended = round(0.7 * use + 0.3 * (keyword_score * 100), 1)
                render_result_screen(c, user_text, blended, covered, missed,
                                     "gpu-dual+keyword",
                                     signals={"coverage": keyword_score,
                                              "sim01": use / 100.0, "entail": None})
                return
            # Canary, abstention or failure: the incumbent local score enters
            # the record exactly as it would have without the fabric.
            render_result_screen(c, user_text, score, covered, missed, method + suffix,
                                 signals=sig)

        app.after(150, poll)

    def render_result_screen(c, user_text, score, covered, missed, method, signals=None):
        # TYPED OUTCOME, not just a score. A paraphrase and a contradiction
        # can land on similar numbers and demand opposite responses, so the
        # classification drives the grade rather than the raw percentage.
        # The classifier gets the RAW signals -- coverage and similarity
        # separately -- because the blended score fed in as both makes the
        # paraphrase branch (close meaning, different words) unreachable.
        sig = signals or {}
        coverage = sig.get("coverage")
        if coverage is None:
            coverage = keyword_coverage(user_text, c.get("def", ""))[0]
        recall_class = classify_recall(user_text, c.get("def", ""), coverage,
                                       semantic=sig.get("sim01"),
                                       entailment=sig.get("entail"))
        recall_rule = recall_consequence(recall_class["outcome"])
        outcome_note = (f"{recall_class['outcome'].replace('_',' ').title()} \u2014 "
                        + recall_rule.get("note", ""))
        session["scores"].append(score)

        for w in parent.winfo_children():
            w.destroy()
        wrap = ctk.CTkScrollableFrame(parent, fg_color="transparent")
        wrap.pack(fill="both", expand=True, padx=32, pady=28)
        section_title(wrap, "Free-Recall Drill", c["term"]).pack(anchor="w", pady=(0, 14))

        band, color = recall_band(score)
        ctk.CTkLabel(wrap, text=f"{band} \u00b7 {score:.0f}%", font=(FONT_DISPLAY, 26, "bold"),
                     text_color=color, anchor="w").pack(anchor="w")
        method_notes = {
            "semantic+entailment+keyword": "scored by semantic similarity + entailment + key-term coverage",
            "semantic+keyword": "scored by semantic similarity + key-term coverage",
            "entailment+keyword": "scored by entailment + key-term coverage",
            "api+keyword": "scored via the API (Claude-graded similarity + key-term coverage) "
                          "\u2014 an alternative to the local sentence-transformers model",
            "keyword": "scored by key-term coverage only \u2014 install sentence-transformers, or add "
                      "an API key in Settings, for richer scoring that credits paraphrasing",
        }
        method_note = method_notes.get(method, method)
        ctk.CTkLabel(wrap, text=method_note, font=(FONT_BODY, 10), text_color=C.INK_DIM,
                     anchor="w", wraplength=620, justify="left").pack(anchor="w", pady=(2, 14))

        if covered:
            ctk.CTkLabel(wrap, text="You captured: " + ", ".join(covered), font=(FONT_BODY, 12),
                         text_color=C.FOREST, anchor="w", wraplength=620, justify="left").pack(anchor="w", pady=(0, 4))
        if missed:
            ctk.CTkLabel(wrap, text="You didn't mention: " + ", ".join(missed), font=(FONT_BODY, 12),
                         text_color=C.STAMP, anchor="w", wraplength=620, justify="left").pack(anchor="w", pady=(0, 12))

        ctk.CTkLabel(wrap, text="Your answer", font=(FONT_BODY, 11, "bold"), text_color=C.INK_DIM,
                     anchor="w").pack(anchor="w", pady=(6, 2))
        ua = card(wrap)
        ua.pack(fill="x")
        ua_lbl = ctk.CTkLabel(ua, text=user_text or "(blank)", font=(FONT_BODY, 12), text_color=C.INK,
                              anchor="w", justify="left")
        ua_lbl.pack(padx=14, pady=10, anchor="w", fill="x")
        bind_autowrap(ua_lbl, wrap, padding=80)

        ctk.CTkLabel(wrap, text="Reference definition", font=(FONT_BODY, 11, "bold"), text_color=C.INK_DIM,
                     anchor="w").pack(anchor="w", pady=(12, 2))
        rf = card(wrap, fg_color=C.PAPER_DIM)
        rf.pack(fill="x")
        rf_lbl = ctk.CTkLabel(rf, text=c["def"], font=(FONT_BODY, 12), text_color=C.INK,
                              anchor="w", justify="left")
        rf_lbl.pack(padx=14, pady=10, anchor="w", fill="x")
        bind_autowrap(rf_lbl, wrap, padding=80)

        ctk.CTkLabel(wrap, text="How well did you actually know it?", font=(FONT_BODY, 12, "bold"),
                     text_color=C.INK, anchor="w").pack(anchor="w", pady=(16, 6))
        # The classifier can only pull the schedule DOWN, so when it will,
        # say so next to the buttons rather than silently ignoring a press.
        grade_cap = recall_rule.get("fsrs_grade")
        cap_note = outcome_note
        if grade_cap is not None:
            cap_note += (f" Scheduled no higher than "
                         f"{['Again', 'Hard', 'Good', 'Easy'][grade_cap]}.")
        ctk.CTkLabel(wrap, text=cap_note, font=(FONT_BODY, 10), text_color=C.INK_DIM,
                     anchor="w", wraplength=620, justify="left").pack(anchor="w", pady=(0, 6))
        grow = ctk.CTkFrame(wrap, fg_color="transparent")
        grow.pack(anchor="w")

        def grade(g):
            st = get_card_state(conn, c["id"])
            # Deadline-awareness now lives inside hlr_update via FSRS's
            # desired_retention, so no separate post-hoc override is needed.
            # Free Recall shares the FSRS path, so it gets the same
            # fluency adjustment. Here the elapsed time is the whole
            # typing-and-submitting episode rather than a flip-to-grade
            # gap, which is a coarser but still meaningful measure of how
            # hard the retrieval was.
            # The typed outcome is a ceiling on the button grade, the same
            # one-directional rule fluency_adjusted_grade follows: an
            # incomplete or reversed answer cannot be scheduled as Good or
            # Easy, but a complete one the learner found easy stays Easy.
            g_pressed = g
            if grade_cap is not None:
                g = min(g, grade_cap)
            dur_ms = None
            started = session.get("started_at")
            if started:
                dur_ms = int((time.monotonic() - started) * 1000)
            eff_g, adjusted, reason = fluency_adjusted_grade(conn, g, dur_ms)
            new_state = hlr_update(st, eff_g, conn=conn)
            apply_successive_relearning_criterion(new_state, correct=(g > 0))
            save_card_state(conn, c["id"], new_state)
            # The learner's own press is what the log keeps: it is the raw
            # self-report the parameter fit and the audit trail need.
            log_review(conn, c["id"], g_pressed, duration_ms=dur_ms)
            # Previously the entailment/similarity score was purely
            # descriptive -- shown as a percentage and then discarded. It
            # now feeds BKT through the same fractional-credit slot already
            # used for hint-discounted quiz credit, so a strong (or weak)
            # free-recall answer moves this topic's mastery estimate the
            # way a partial-credit quiz answer already does, instead of
            # vanishing the moment the screen changes.
            # Record a real attempt row as well as the BKT update. Without
            # this, free-recall evidence was structurally invisible to PFA
            # (which reads the attempts table), so as quiz attempts
            # accumulated and the blend shifted toward PFA, free-recall
            # signal was progressively erased from the mastery number the
            # app displays -- measured at ~75% of the signal discarded once
            # n passed the crossover. Logged under its own mode so it stays
            # separable from multiple-choice evidence.
            passed = score >= 50
            record_attempt(conn, "freerecall", c["id"], c["topic"], passed, 0,
                           None, None, None, update_bkt=False, log_error=False)
            # `correct` is unused here since fractional_credit overrides the
            # credit calculation entirely; passed as a fixed placeholder so
            # that isn't ambiguous to a future reader. The outcome's
            # mastery_credit scales the score: a contradiction with rich
            # keyword overlap must not earn the topic 60% of a correct
            # answer.
            bkt_update(conn, c["topic"], True, 0,
                      fractional_credit=max(0.0, min(1.0, (score / 100.0)
                                                     * recall_rule.get("mastery_credit", 1.0))))
            mark_session_today(conn)
            advance()

        for lbl_txt, gval, col in [("Again", 0, C.STAMP), ("Hard", 1, C.BRASS_DARK),
                                    ("Good", 2, C.BRASS), ("Easy", 3, C.FOREST)]:
            ctk.CTkButton(grow, text=lbl_txt, command=lambda g=gval: grade(g), fg_color=col,
                          hover_color=C.INK, text_color="#fff", font=(FONT_BODY, 12, "bold"),
                          corner_radius=8, width=96, height=36).pack(side="left", padx=(0, 8))

    def advance():
        session["i"] += 1
        render_prompt()

    render_prompt()

# ============================================================================
# BLIND SPOTS (confidence x correctness)
# ============================================================================

def view_blindspots(app, parent):
    conn = app.conn
    scroll = ctk.CTkScrollableFrame(parent, fg_color="transparent")
    scroll.pack(fill="both", expand=True, padx=32, pady=28)
    section_title(scroll, "Blind Spots",
                  "Where your confidence and your accuracy disagree.").pack(anchor="w", pady=(0, 18))
    mode_info_disclosure(scroll, "blindspots")

    quad = confidence_quadrants(conn)
    total = sum(len(v) for v in quad.values())
    if total == 0:
        ctk.CTkLabel(scroll, text="No confidence data yet. Confidence is recorded during Practice Quiz "
                     "and the Error Log drill \u2014 do one of those first.",
                     font=(FONT_BODY, 13), text_color=C.INK_DIM, wraplength=560, justify="left",
                     anchor="w").pack(anchor="w")
        return

    grid = ctk.CTkFrame(scroll, fg_color="transparent")
    grid.pack(fill="x", pady=(0, 18))
    cells = [
        ("Confident & wrong", quad["confident_wrong"], C.STAMP,
         "The dangerous cell \u2014 you won't think to check these."),
        ("Confident & right", quad["confident_right"], C.FOREST, "Genuine mastery."),
        ("Unsure & wrong", quad["unsure_wrong"], C.BRASS_DARK, "Known gaps \u2014 straightforward to fix."),
        ("Unsure & right", quad["unsure_right"], C.NAVY, "Shaky knowledge, or lucky guesses."),
    ]
    for i, (label, items, color, note) in enumerate(cells):
        cell = card(grid)
        cell.grid(row=i // 2, column=i % 2, sticky="nsew", padx=6, pady=6)
        inner = ctk.CTkFrame(cell, fg_color="transparent")
        inner.pack(fill="both", padx=16, pady=14)
        ctk.CTkLabel(inner, text=label, font=(FONT_BODY, 10, "bold"),
                     text_color=color, anchor="w").pack(anchor="w")
        ctk.CTkLabel(inner, text=str(len(items)), font=(FONT_DISPLAY, 28, "bold"),
                     text_color=color, anchor="w").pack(anchor="w")
        ctk.CTkLabel(inner, text=note, font=(FONT_BODY, 11), text_color=C.INK_DIM,
                     anchor="w", wraplength=240, justify="left").pack(anchor="w")
    grid.grid_columnconfigure(0, weight=1)
    grid.grid_columnconfigure(1, weight=1)
    try:
        _ckind, _creading = calibration_reading(calibration_metrics(conn))
    except sqlite3.Error:
        _ckind = None
    if _ckind is not None:
        ctk.CTkLabel(scroll, text=_creading, font=(FONT_BODY, 12), text_color=C.INK,
                     anchor="w", justify="left", wraplength=620).pack(anchor="w", pady=(0, 14))

    blind = quad["confident_wrong"]
    if blind:
        ctk.CTkLabel(scroll, text="Your blind spots", font=(FONT_DISPLAY, 15, "bold"),
                     text_color=C.INK, anchor="w").pack(anchor="w", pady=(6, 8))
        # Rendered in PAGES. Every entry is a card() plus two labels, and
        # card() alone measures ~2.6 ms, so an unbounded list of 84 blind
        # spots cost ~1.3 s of pure widget construction on every visit.
        # De-duplication now happens up front rather than inside the render
        # loop, so the page count reflects real distinct items.
        seen = []
        for qid in blind:
            if qid not in seen and qid in QUIZ_BANK:
                seen.append(qid)
        BLIND_PAGE = 10
        _bs = {"n": 0, "btn": None}

        def _render_blind():
            if _bs["btn"] is not None and _bs["btn"].winfo_exists():
                _bs["btn"].destroy()
                _bs["btn"] = None
            batch = seen[_bs["n"]:_bs["n"] + BLIND_PAGE]
            for qid in batch:
                _render_one(qid)
            _bs["n"] += len(batch)
            left = len(seen) - _bs["n"]
            if left > 0:
                _bs["btn"] = ghost_button(
                    scroll, f"Show {min(BLIND_PAGE, left)} more  ({left} left)",
                    _render_blind)
                _bs["btn"].pack(anchor="w", pady=(8, 4))

        def _render_one(qid):
            q = QUIZ_BANK.get(qid)
            if not q:
                return
            row = card(scroll)
            row.pack(fill="x", pady=3)
            inner = ctk.CTkFrame(row, fg_color="transparent")
            inner.pack(fill="x", padx=14, pady=9)
            lbl = ctk.CTkLabel(inner, text=q["q"], font=(FONT_BODY, 12), text_color=C.INK,
                               anchor="w", justify="left")
            lbl.pack(anchor="w", fill="x")
            bind_autowrap(lbl, scroll, padding=90)
            ctk.CTkLabel(inner, text=TOPICS[q["topic"]]["short"], font=(FONT_BODY, 10, "bold"),
                         text_color=C.BRASS_DARK, anchor="w").pack(anchor="w", pady=(2, 0))

        _render_blind()

        def drill():
            pool = [QUIZ_BANK[qid] for qid in seen if qid in QUIZ_BANK]
            random.shuffle(pool)

            def on_finish(summary):
                render_result_screen(app, parent, summary, lambda: app.show_view("blindspots"))

            QuestionSession(app, parent, pool, "quiz", "Blind Spot Drill",
                            f"{len(pool)} questions you were confident and wrong about",
                            allow_hints=True, collect_diagnostics=True, on_finish=on_finish)

        primary_button(scroll, "Drill blind spots", drill).pack(anchor="w", pady=(14, 0))
    else:
        ctk.CTkLabel(scroll, text="No blind spots recorded \u2014 when you're confident, you're right. "
                     "That's the calibration you want.", font=(FONT_BODY, 13), text_color=C.FOREST,
                     wraplength=560, justify="left", anchor="w").pack(anchor="w", pady=(8, 0))


# ============================================================================
# TIMING DASHBOARD
# ============================================================================

def view_timing(app, parent):
    conn = app.conn
    scroll = ctk.CTkScrollableFrame(parent, fg_color="transparent")
    scroll.pack(fill="both", expand=True, padx=32, pady=28)
    section_title(scroll, "Timing",
                  "Where the clock is actually costing you \u2014 including correct answers "
                  "that cost too much.").pack(anchor="w", pady=(0, 18))

    s = timing_summary(conn)
    if not s:
        ctk.CTkLabel(scroll, text="No timing data yet. Timing is recorded during Practice Quiz, "
                     "Adaptive Drill, Progressive Practice, and the Diagnostic.",
                     font=(FONT_BODY, 13), text_color=C.INK_DIM, wraplength=560,
                     justify="left", anchor="w").pack(anchor="w")
        return

    chips = ctk.CTkFrame(scroll, fg_color="transparent")
    chips.pack(fill="x", pady=(0, 18))
    stat_chip(chips, "Target pace", fmt_secs(s["target"]),
              on_click=lambda v="exam": app.show_view(v),
              hint="practise timed").pack(side="left", padx=(0, 10))
    avg_color = C.BRASS_DARK if s["avg"] > s["target"] else C.FOREST
    stat_chip(chips, "Your average", fmt_secs(s["avg"]), value_color=avg_color,
              on_click=lambda v="analytics": app.show_view(v),
              hint="pace detail").pack(side="left", padx=10)
    stat_chip(chips, "Median", fmt_secs(s["median"]),
              on_click=lambda v="analytics": app.show_view(v),
              hint="pace detail").pack(side="left", padx=10)
    stat_chip(chips, "Over budget", f'{s["over_budget_pct"]:.0f}%',
              value_color=(C.STAMP if s["over_budget_pct"] > 25 else C.CREAM)).pack(side="left", padx=10)
    stat_chip(chips, "Answered", str(s["n"]),
              on_click=lambda: app.show_view("analytics"),
              hint="full analytics").pack(side="left", padx=(10, 0))

    # ---- the three flagged categories ----
    def flag_card(title, items, color, note):
        c = card(scroll)
        c.pack(fill="x", pady=(0, 10))
        inner = ctk.CTkFrame(c, fg_color="transparent", height=0)
        inner.pack(fill="x", padx=18, pady=14)
        row = ctk.CTkFrame(inner, fg_color="transparent", height=0)
        row.pack(fill="x")
        ctk.CTkLabel(row, text=title, font=(FONT_DISPLAY, 15, "bold"),
                     text_color=color, anchor="w").pack(side="left")
        ctk.CTkLabel(row, text=str(len(items)), font=(FONT_DISPLAY, 20, "bold"),
                     text_color=color, anchor="e").pack(side="right")
        nl = ctk.CTkLabel(inner, text=note, font=(FONT_BODY, 11), text_color=C.INK_DIM,
                          anchor="w", justify="left")
        nl.pack(anchor="w", fill="x", pady=(2, 6))
        bind_autowrap(nl, scroll, padding=90)
        seen = []
        for r in items[:6]:
            q = QUIZ_BANK.get(r["question_id"])
            if not q or q["id"] in seen:
                continue
            seen.append(q["id"])
            lbl = ctk.CTkLabel(inner,
                               text=f'\u2022 [{fmt_secs(r["time_taken"])}] {q["q"][:88]}',
                               font=(FONT_BODY, 11), text_color=C.INK, anchor="w", justify="left")
            lbl.pack(anchor="w", fill="x", pady=1)
            bind_autowrap(lbl, scroll, padding=100)

        # ACTION. This card names an instruction -- "drill them for speed",
        # "these are guesses" -- and until now offered no way to act on it.
        # A diagnosis the reader has to go re-find in the sidebar is a
        # dead end dressed as advice.
        if seen:
            def _drill(ids=list(seen), t=title):
                pool = [QUIZ_BANK[i] for i in ids if i in QUIZ_BANK]
                if not pool:
                    app.toast("Those items are no longer in the bank.", kind="warn")
                    return
                timed = t.startswith("Correct")     # speed work needs a clock
                # A speed drill runs on a real clock at exam pace and is
                # recorded as timed practice, not as an exam: it re-answers
                # items the learner already knows, which must not enter the
                # exam-mode pressure baselines.
                QuestionSession(
                    app, parent, pool, "progressive_strict" if timed else "quiz",
                    f"Timing drill \u2014 {t.lower()}",
                    ("Same items, against the clock. The goal is pace, not "
                     "content \u2014 you already know these."
                     if timed else
                     "Re-answer these deliberately, reading the full stem."),
                    allow_hints=not timed, collect_diagnostics=True,
                    timed=timed,
                    total_seconds=(round(len(pool) * PACE_TARGET_SECONDS) if timed else None),
                    pressure_confidence=timed,
                    on_finish=lambda _s: app.show_view("timing"))
            ghost_button(inner, f"Drill these {len(seen)}", _drill).pack(
                anchor="w", pady=(8, 0))
        return seen

    slow_ids = flag_card("Correct, but too slow", s["slow_correct"], C.BRASS_DARK,
        "The hidden problem: these scored as successes while eating the time budget that causes a "
        "miss later in the section. Drill them for speed, not for content.")
    flag_card("Over target time", s["slow"], C.STAMP,
        f'Answered in more than {SLOW_FACTOR:g}\u00d7 the {fmt_secs(s["target"])} target.')
    flag_card("Suspiciously fast", s["fast"], C.NAVY,
        "Answered almost instantly. Fast and right is fine; fast and wrong usually means guessing "
        "rather than reading the question.")

    if slow_ids:
        def drill_slow():
            pool = [QUIZ_BANK[i] for i in slow_ids if i in QUIZ_BANK]
            random.shuffle(pool)

            def on_finish(summary):
                render_result_screen(app, parent, summary, lambda: app.show_view("timing"))

            QuestionSession(app, parent, pool, "progressive_strict", "Speed Drill",
                            f"{len(pool)} questions you got right but slowly",
                            allow_hints=False, timed=True,
                            total_seconds=round(len(pool) * PACE_TARGET_SECONDS),
                            pressure_confidence=True, on_finish=on_finish)

        primary_button(scroll, "Speed-drill the slow-but-correct", drill_slow).pack(anchor="w", pady=(4, 18))

    # ---- pace by topic ----
    bt = timing_by_topic(conn)
    if bt:
        ctk.CTkLabel(scroll, text="Pace by topic", font=(FONT_DISPLAY, 15, "bold"),
                     text_color=C.INK, anchor="w").pack(anchor="w", pady=(6, 8))
        tc = card(scroll)
        tc.pack(fill="x", pady=(0, 18))
        ti = ctk.CTkFrame(tc, fg_color="transparent", height=0)
        ti.pack(fill="x", padx=16, pady=12)
        for r in bt[:10]:
            t = TOPICS[r["topic_id"]]
            row = ctk.CTkFrame(ti, fg_color="transparent", height=0)
            row.pack(fill="x", pady=3)
            ctk.CTkLabel(row, text=t["short"], font=(FONT_BODY, 12), text_color=C.INK,
                         width=170, anchor="w").pack(side="left")
            frac = min(1.0, r["avg"] / (PACE_TARGET_SECONDS * 2))
            track = ctk.CTkFrame(row, fg_color=C.PAPER_LINE, height=10, corner_radius=5)
            track.pack(side="left", fill="x", expand=True, padx=10)
            track.pack_propagate(False)
            col = C.STAMP if r["avg"] > PACE_TARGET_SECONDS else C.FOREST
            ctk.CTkFrame(track, fg_color=col, height=10, corner_radius=5,
                         width=max(4, int(frac * 420))).place(x=0, y=0)
            ctk.CTkLabel(row, text=f'{fmt_secs(r["avg"])}  \u00b7  {r["acc"]:.0f}% acc',
                         font=(FONT_BODY, 11), text_color=C.INK_DIM,
                         width=150, anchor="e").pack(side="left")

    # ---- where in a session things break down ----
    cl = timing_position_clusters(conn)
    if cl:
        ctk.CTkLabel(scroll, text="Across a timed session", font=(FONT_DISPLAY, 15, "bold"),
                     text_color=C.INK, anchor="w").pack(anchor="w", pady=(6, 8))
        pc = card(scroll)
        pc.pack(fill="x", pady=(0, 12))
        pi = ctk.CTkFrame(pc, fg_color="transparent", height=0)
        pi.pack(fill="x", padx=16, pady=12)
        labels = ["first fifth", "second", "middle", "fourth", "last fifth"]
        for r in cl:
            row = ctk.CTkFrame(pi, fg_color="transparent", height=0)
            row.pack(fill="x", pady=3)
            name = labels[r["bucket"]] if r["bucket"] < len(labels) else str(r["bucket"])
            ctk.CTkLabel(row, text=name, font=(FONT_BODY, 12), text_color=C.INK,
                         width=110, anchor="w").pack(side="left")
            acc = r["acc"] or 0
            track = ctk.CTkFrame(row, fg_color=C.PAPER_LINE, height=10, corner_radius=5)
            track.pack(side="left", fill="x", expand=True, padx=10)
            track.pack_propagate(False)
            col = C.FOREST if acc >= 70 else C.STAMP
            ctk.CTkFrame(track, fg_color=col, height=10, corner_radius=5,
                         width=max(4, int(acc / 100 * 420))).place(x=0, y=0)
            ctk.CTkLabel(row, text=f'{acc:.0f}% acc \u00b7 {fmt_secs(r["avg"])}',
                         font=(FONT_BODY, 11), text_color=C.INK_DIM,
                         width=150, anchor="e").pack(side="left")
        note = ctk.CTkLabel(pi, text="If accuracy falls or pace slows in the later buckets, that is "
                            "a stamina and pacing problem rather than a knowledge problem \u2014 "
                            "the fix is full-length timed exposure, not more content review.",
                            font=(FONT_BODY, 11, "italic"), text_color=C.INK_DIM,
                            anchor="w", justify="left")
        note.pack(anchor="w", fill="x", pady=(8, 0))
        bind_autowrap(note, scroll, padding=90)

    # ---- score-prediction calibration ----
    hist = calibration_history(conn)
    if hist:
        ctk.CTkLabel(scroll, text="Score prediction accuracy", font=(FONT_DISPLAY, 15, "bold"),
                     text_color=C.INK, anchor="w").pack(anchor="w", pady=(6, 8))
        cc = card(scroll)
        cc.pack(fill="x", pady=(0, 12))
        ci = ctk.CTkFrame(cc, fg_color="transparent", height=0)
        ci.pack(fill="x", padx=16, pady=12)
        errs = [h["predicted"] - h["actual"] for h in hist]
        bias = sum(errs) / len(errs)
        mae = sum(abs(e) for e in errs) / len(errs)
        verdict = ("You are well calibrated." if abs(bias) < 5 else
                   ("You consistently OVERestimate your score \u2014 classic overconfidence."
                    if bias > 0 else
                    "You consistently UNDERestimate your score \u2014 you know more than you think."))
        ctk.CTkLabel(ci, text=f"Average miss: {mae:.1f} points   \u00b7   bias {bias:+.1f}",
                     font=(FONT_BODY, 12, "bold"), text_color=C.INK, anchor="w").pack(anchor="w")
        vl = ctk.CTkLabel(ci, text=verdict + "  Calibration usually stabilizes after about four "
                          "prediction cycles.", font=(FONT_BODY, 11), text_color=C.INK_DIM,
                          anchor="w", justify="left")
        vl.pack(anchor="w", fill="x", pady=(2, 8))
        bind_autowrap(vl, scroll, padding=90)
        for h in hist[-6:]:
            ctk.CTkLabel(ci, text=f'{h["date"]}   predicted {h["predicted"]}%   actual {h["actual"]:.0f}%',
                         font=(FONT_MONO, 11), text_color=C.INK, anchor="w").pack(anchor="w")


def ask_prediction(app, parent, kind, on_continue):
    """Metacognitive calibration: commit to a predicted score BEFORE the
    session, then compare. Predicting after the fact teaches nothing."""
    for w in parent.winfo_children():
        w.destroy()
    wrap = ctk.CTkFrame(parent, fg_color="transparent")
    wrap.pack(fill="both", expand=True, padx=40, pady=44)
    section_title(wrap, "Predict your score",
                  "Commit to a number before you start. Comparing predicted vs. actual is what "
                  "trains calibration.").pack(anchor="w", pady=(0, 18))
    row = ctk.CTkFrame(wrap, fg_color="transparent", height=0)
    row.pack(anchor="w")
    ent = styled_entry(row, width=90, font=(FONT_BODY, 13), placeholder_text="e.g. 72")
    ent.pack(side="left", padx=(0, 8))
    ctk.CTkLabel(row, text="%", font=(FONT_BODY, 13), text_color=C.INK).pack(side="left", padx=(0, 14))

    def go():
        try:
            v = max(0, min(100, int(ent.get().strip())))
            save_prediction(app.conn, kind, v)
        except ValueError:
            pass
        on_continue()

    def skip():
        # No prediction for THIS attempt -- and none left over from an
        # earlier, abandoned one to be scored against it.
        set_setting(app.conn, "pending_prediction", "")
        on_continue()

    primary_button(row, "Start", go).pack(side="left", padx=(0, 8))
    ghost_button(row, "Skip", skip).pack(side="left")


# ============================================================================
# ITEM ANALYSIS (question-bank quality control)
# ============================================================================

def view_item_analysis(app, parent):
    conn = app.conn
    scroll = ctk.CTkScrollableFrame(parent, fg_color="transparent")
    scroll.pack(fill="both", expand=True, padx=32, pady=28)
    section_title(scroll, "Question Quality",
                  "Your answering history used as quality control on the question bank itself.").pack(
        anchor="w", pady=(0, 16))

    intro_card = card(scroll, fg_color=C.PAPER_DIM)
    intro_card.pack(fill="x", pady=(0, 16))
    intro_inner = ctk.CTkFrame(intro_card, fg_color="transparent", height=0)
    intro_inner.pack(fill="x", padx=18, pady=14)
    intro = ctk.CTkLabel(intro_inner,
        text=("This bank was authored by one source and most of it is still uncited, so independent "
              "signal about which questions are suspect is worth having. The useful signal for a "
              "single user is an item you keep missing while doing well on the rest of its topic "
              "\u2014 that isolates the question from your knowledge of the subject. Note that true "
              "item discrimination needs many test-takers and cannot be computed from one person's "
              "data, so it is deliberately not reported here."),
        font=(FONT_BODY, 12), text_color=C.INK_DIM, anchor="w", justify="left")
    intro.pack(anchor="w", fill="x")
    bind_autowrap(intro, scroll, padding=90)

    items = item_analysis(conn)
    if not items:
        empty_card = card(scroll, fg_color=C.PAPER_DIM)
        empty_card.pack(fill="x")
        empty_inner = ctk.CTkFrame(empty_card, fg_color="transparent", height=0)
        empty_inner.pack(fill="x", padx=18, pady=16)
        empty_lbl = ctk.CTkLabel(empty_inner,
            text=(f"Not enough data yet. An item needs at least {MIN_RESPONSES_FOR_ANALYSIS} "
                  "responses before its statistics mean anything. Note that distractor-choice "
                  "tracking was added recently, so only answers recorded from now on can support "
                  "the non-functioning-distractor check."),
            font=(FONT_BODY, 13), text_color=C.INK_DIM, wraplength=600,
            justify="left", anchor="w")
        empty_lbl.pack(anchor="w", fill="x", pady=(0, 12))
        primary_button(empty_inner, "Start a Practice Quiz",
                       lambda: app.show_view("quiz")).pack(anchor="w")
        return

    flagged = [i for i in items if i["flags"]]
    chips = ctk.CTkFrame(scroll, fg_color="transparent")
    chips.pack(fill="x", pady=(0, 16))
    stat_chip(chips, "Items analyzed", str(len(items)),
              on_click=lambda: app.show_view("contentqa"),
              hint="content audit").pack(side="left", padx=(0, 10))
    stat_chip(chips, "Flagged", str(len(flagged)),
              value_color=(C.STAMP if flagged else C.FOREST)).pack(side="left", padx=10)
    avg_p = sum(i["p"] for i in items) / len(items)
    stat_chip(chips, "Avg success", f"{avg_p*100:.0f}%").pack(side="left", padx=10)

    # Fetched once for the whole list. Calling retired_item_ids() inside the
    # row loop would be a 20-query N+1 on a view already measured at 1044 ms.
    try:
        retired_ids = retired_item_ids(app.conn)
    except Exception:
        retired_ids = set()

    if flagged:
        ctk.CTkLabel(scroll, text="Suspect items", font=(FONT_DISPLAY, 15, "bold"),
                     text_color=C.STAMP, anchor="w").pack(anchor="w", pady=(6, 8))
        # The engine side is cheap -- item_analysis() measured at 8 ms for
        # 211 items -- so this view's 1044 ms was almost entirely Tk widget
        # construction: 20 suspect cards, each with an autowrapping label and
        # now action buttons on top. Six is enough to act on in one sitting;
        # the rest are still reachable through Content QA's findings queue,
        # which groups them by what they should trigger anyway.
        for it in flagged[:6]:
            q = it["q"]
            c = card(scroll)
            c.pack(fill="x", pady=4)
            inner = ctk.CTkFrame(c, fg_color="transparent", height=0)
            inner.pack(fill="x", padx=16, pady=12)
            ql = ctk.CTkLabel(inner, text=f'[{q["id"]}] {q["q"]}', font=(FONT_BODY, 12),
                              text_color=C.INK, anchor="w", justify="left")
            ql.pack(anchor="w", fill="x")
            bind_autowrap(ql, scroll, padding=90)
            # topic_p is computed from scored multiple-choice rows only
            # (free recall and pretest guesses are excluded upstream); the
            # label says so, since that is what makes the gap meaningful.
            tp = (f'   rest of topic (multiple choice) {it["topic_p"]*100:.0f}%'
                  if it["topic_p"] is not None else "")
            ctk.CTkLabel(inner,
                         text=f'n={it["n"]}   you get it right {it["p"]*100:.0f}%{tp}',
                         font=(FONT_MONO, 11), text_color=C.INK_DIM, anchor="w").pack(anchor="w", pady=(3, 0))
            for f in it["flags"]:
                ctk.CTkLabel(inner, text="\u26a0  " + f, font=(FONT_BODY, 11, "bold"),
                             text_color=C.STAMP, anchor="w").pack(anchor="w")

            # ACT ON THE FLAG. This view identified suspect items and offered
            # nothing to do about them, even though apply_item_repair() and
            # its cross-locus propagation already exist and are wired into
            # Content QA. Flagging without a repair path is a report, not a
            # tool.
            arow = ctk.CTkFrame(inner, fg_color="transparent", height=0)
            arow.pack(anchor="w", pady=(8, 0))
            retired_now = it["q"]["id"] in retired_ids

            def _retire(qid=q["id"]):
                r = apply_item_repair(app.conn, qid, "retire",
                                      "retired from Item Analysis")
                app.toast(r["note"][:120] if r.get("ok") else
                          r.get("reason", "repair failed"),
                          kind="good" if r.get("ok") else "warn")
                app.show_view("items")

            def _reinstate(qid=q["id"]):
                apply_item_repair(app.conn, qid, "reinstate",
                                  "reinstated from Item Analysis")
                app.toast(f"{qid} is back in rotation.", kind="good")
                app.show_view("items")

            def _drill_one(qq=q):
                QuestionSession(app, parent, [qq], "quiz", "Single item",
                                "One suspect item, on its own.",
                                allow_hints=True, collect_diagnostics=True,
                                on_finish=lambda _s: app.show_view("items"))

            if retired_now:
                ctk.CTkLabel(arow, text="retired \u2014 not being served",
                             font=(FONT_BODY, 11, "bold"), text_color=C.INK_DIM,
                             anchor="w").pack(side="left", padx=(0, 8))
                ghost_button(arow, "Reinstate", _reinstate).pack(side="left")
            else:
                ghost_button(arow, "Retire this item", _retire).pack(side="left", padx=(0, 8))
                ghost_button(arow, "Answer it again", _drill_one).pack(side="left")

            if it["answered"] >= MIN_RESPONSES_FOR_ANALYSIS:
                dist = "   ".join(
                    f'{"ABCD"[i]}:{it["counts"][i]}' + ("*" if i == q["a"] else "")
                    for i in range(4))
                ctk.CTkLabel(inner, text="choices  " + dist + "   (* = correct)",
                             font=(FONT_MONO, 10), text_color=C.INK_DIM,
                             anchor="w").pack(anchor="w", pady=(3, 0))

    ctk.CTkLabel(scroll, text="All analyzed items", font=(FONT_DISPLAY, 15, "bold"),
                 text_color=C.INK, anchor="w").pack(anchor="w", pady=(14, 8))
    tbl = card(scroll)
    tbl.pack(fill="x")
    ti = ctk.CTkFrame(tbl, fg_color="transparent", height=0)
    ti.pack(fill="x", padx=16, pady=12)
    for it in items[:40]:
        row = ctk.CTkFrame(ti, fg_color="transparent", height=0)
        row.pack(fill="x", pady=2)
        ctk.CTkLabel(row, text=it["q"]["id"], font=(FONT_MONO, 11), text_color=C.INK_DIM,
                     width=52, anchor="w").pack(side="left")
        ctk.CTkLabel(row, text=TOPICS[it["q"]["topic"]]["short"][:20], font=(FONT_BODY, 11),
                     text_color=C.INK, width=150, anchor="w").pack(side="left")
        track = ctk.CTkFrame(row, fg_color=C.PAPER_LINE, height=9, corner_radius=5)
        track.pack(side="left", fill="x", expand=True, padx=8)
        track.pack_propagate(False)
        col = C.STAMP if it["p"] < 0.35 else (C.FOREST if it["p"] > 0.7 else C.BRASS)
        ctk.CTkFrame(track, fg_color=col, height=9, corner_radius=5,
                     width=max(3, int(it["p"] * 300))).place(x=0, y=0)
        ctk.CTkLabel(row, text=f'{it["p"]*100:3.0f}%  n={it["n"]}',
                     font=(FONT_MONO, 10), text_color=C.INK_DIM,
                     width=170, anchor="e").pack(side="left")


# ============================================================================
# CONTENT QA
# ============================================================================
# The bank carries source, verified, and why_wrong fields, but nothing
# enforced that they were actually populated -- so "we added provenance
# tracking" could quietly mean 12% coverage. This surfaces the real numbers,
# because an uncited claim in a licensing tool is the app's biggest risk.

VERIFIED_STALE_MONTHS = 12

def content_qa(bank=None):
    bank = bank or QUIZ_LIST
    today = date.today()
    report = {"total": len(bank), "cited": 0, "verified": 0, "stale": [],
              "uncited": [], "missing_why": [], "partial_why": [],
              "by_group": {}}
    for q in bank:
        grp = TOPICS[q["topic"]]["group"]
        g = report["by_group"].setdefault(grp, {"n": 0, "cited": 0})
        g["n"] += 1
        if q.get("source"):
            report["cited"] += 1
            g["cited"] += 1
        else:
            report["uncited"].append(q)
        v = q.get("verified")
        if v:
            report["verified"] += 1
            try:
                y, m = int(v[:4]), int(v[5:7])
                months = (today.year - y) * 12 + (today.month - m)
                if months >= VERIFIED_STALE_MONTHS:
                    report["stale"].append((q, months))
            except Exception:
                pass
        ww = q.get("why_wrong") or {}
        distractors = [o for i, o in enumerate(q["opts"]) if i != q["a"]]
        have = sum(1 for dtext in distractors if dtext in ww)
        if have == 0:
            report["missing_why"].append(q)
        elif have < len(distractors):
            report["partial_why"].append((q, have, len(distractors)))
    return report


def view_content_qa(app, parent):
    scroll = ctk.CTkScrollableFrame(parent, fg_color="transparent")
    scroll.pack(fill="both", expand=True, padx=32, pady=28)
    section_title(scroll, "Bank Audit",
                  "How much of this question bank is actually sourced, verified, and "
                  "fully explained.").pack(anchor="w", pady=(0, 16))

    r = content_qa()
    n = r["total"]

    # DIFFICULTY FLOOR. The bank's easiest item is b = -1.30, so a learner
    # at theta = -1.0 cannot be served above p = 0.67 by any selector. This
    # is the binding constraint on the phase-A success target and it is a
    # content problem: author (or generate and verify) easy items per skill.
    try:
        for _th in (-1.0, -0.5):
            fr = bank_difficulty_floor_report(app.conn, theta=_th)
            fc = card(scroll, fg_color=C.PAPER_DIM)
            fc.pack(fill="x", pady=(0, 10))
            fi = ctk.CTkFrame(fc, fg_color="transparent", height=0)
            fi.pack(fill="x", padx=18, pady=12)
            ctk.CTkLabel(fi, text=f"DIFFICULTY FLOOR AT \u03b8 = {_th:+.1f}", font=(FONT_BODY, 10, "bold"),
                         text_color=C.BRASS_DARK, anchor="w").pack(anchor="w")
            ctk.CTkLabel(fi, text=(f"Easiest item offers p = {fr['bank_max_p']:.2f}; phase-A target is "
                                   f"{fr['target'] + 0.06:.2f}. {fr['n_items_at_target']} items reach the target; "
                                   f"{fr['n_starved']} of {fr['n_skills']} skills have fewer than 3 such items. "
                                   f"Remedy is content, not selection: easy variants (b \u2264 \u22122) per starved skill."),
                         font=(FONT_BODY, 12), text_color=C.INK, anchor="w", justify="left",
                         wraplength=680).pack(anchor="w", pady=(3, 0))
    except Exception:
        pass

    # Data-integrity warning: any session mode recorded in attempts but
    # absent from MODE_TAXONOMY silently inherits calm-regime treatment,
    # which is how the freerecall mode went unclassified after it was added.
    # Enrichment coverage. The precomputed artifact is genuinely partial --
    # embeddings cover the whole corpus, but misconceptions, confusion
    # pairs, difficulty priors and skill decompositions were authored for a
    # subset. Reporting that honestly belongs here, in the view whose whole
    # purpose is content quality control, rather than letting a learner
    # assume every item carries authored analysis.
    _e = enrichment()
    if _e:
      def _build_cov(_parent):
        ec = card(_parent)
        ec.pack(fill="x", pady=(0, 14))
        ei = ctk.CTkFrame(ec, fg_color="transparent", height=0)
        ei.pack(fill="x", padx=18, pady=14)
        enote = ctk.CTkLabel(
            ei,
            text=("Built once at packaging time and shipped with the app, so it needs no model "
                  "and no network. It is authored analysis, not measured from your answers, and "
                  "it is deliberately partial \u2014 here is exactly how far it reaches."),
            font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w", justify="left")
        enote.pack(anchor="w", fill="x", pady=(2, 10))
        bind_autowrap(enote, scroll, padding=90)

        n_q = len(QUIZ_LIST)
        emb = _e.get("embeddings") or {}
        pair_items = {x for pr in _e.get("confusion_pairs", []) for x in (pr.get("a"), pr.get("b"))}
        multi_topics = [t for t in TOPICS if len(topic_skill_ids(t)) >= 2]
        cov = [
            ("Corpus embeddings", len(emb.get("ids", [])), n_q + len(FLASHCARDS) + len(TOPICS),
             "powers offline clustering, related-items, and semantic search"),
            ("Skill decompositions", len(multi_topics), len(TOPICS),
             "topics with per-skill diagnosis rather than one score"),
            ("Misconception diagnoses", len(_e.get("misconceptions", {})), n_q,
             "names the specific error behind a wrong answer"),
            ("Confusion pairs", len(pair_items), n_q,
             "items shown alongside what they are mistaken for"),
            ("Difficulty priors", len(_e.get("difficulty_priors", {})), n_q,
             "better starting estimate than the difficulty tier"),
        ]
        for label, have, total, why in cov:
            frac = (have / total) if total else 0.0
            # NOTE: deliberately not named `r` -- that name already holds
            # content_qa()'s result in this function, and shadowing it here
            # broke the citation stats below.
            crow = ctk.CTkFrame(ei, fg_color="transparent", height=0)
            crow.pack(fill="x", pady=3)
            ctk.CTkLabel(crow, text=label, font=(FONT_BODY, 12), text_color=C.INK,
                        width=180, anchor="w").pack(side="left")
            track = ctk.CTkFrame(crow, fg_color=C.PAPER_LINE, height=10, corner_radius=5)
            track.pack(side="left", fill="x", expand=True, padx=8)
            track.pack_propagate(False)
            col = C.FOREST if frac >= 0.85 else (C.BRASS if frac >= 0.25 else C.STAMP)
            ctk.CTkFrame(track, fg_color=col, height=10, corner_radius=5,
                        width=max(3, int(frac * 260))).place(x=0, y=0)
            ctk.CTkLabel(crow, text=f"{have}/{total}", font=(FONT_MONO, 11),
                        text_color=C.INK_DIM, width=72, anchor="e").pack(side="left")
            wl = ctk.CTkLabel(ei, text="      " + why, font=(FONT_BODY, 10),
                              text_color=C.INK_DIM, anchor="w")
            wl.pack(anchor="w", fill="x")


      lazy_section(scroll, "Precomputed analysis coverage",
                   "How far the shipped authored analysis actually reaches.",
                   _build_cov)

    # ---- Distinguishability audit (companion note, Loci A/B/C) ----
    def _build_audit(_parent):
        # Placed in Content QA because it is a property of the BANK, not of the
        # learner: it asks whether the items can separate the states the loop
        # estimates, which is a different question from what the learner got
        # wrong. Computed on demand rather than on view load, because the
        # Locus C sweep enumerates profile pairs across every decomposed topic.
        dq = card(_parent)
        dq.pack(fill="x", pady=(0, 14))
        di = ctk.CTkFrame(dq, fg_color="transparent")
        di.pack(fill="x", padx=18, pady=14)
        dnote = ctk.CTkLabel(
            di,
            text=("Asks whether the bank can tell things apart, rather than what you got wrong. "
                  "Three checks: two answer options nobody can separate, two questions testing the "
                  "same fact in different words, and skill profiles this topic's questions could "
                  "never distinguish no matter how much you practise."),
            font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w", justify="left")
        dnote.pack(anchor="w", fill="x", pady=(2, 10))
        bind_autowrap(dnote, scroll, padding=90)
        dstatus = ctk.CTkLabel(di, text="", font=(FONT_BODY, 11), text_color=C.INK_DIM,
                               anchor="w", justify="left")
        dresults = ctk.CTkFrame(di, fg_color="transparent", height=0)

        def run_audit():
            dbtn.configure(state="disabled", text="Auditing\u2026")
            for w in dresults.winfo_children():
                w.destroy()
            holder = {}

            def worker():
                wconn = None
                try:
                    wconn = db_connect()
                    holder["res"] = distinguishability_summary(wconn)
                except Exception as e:
                    holder["err"] = str(e)
                finally:
                    if wconn is not None:
                        try:
                            wconn.close()
                        except Exception:
                            pass

            import threading
            threading.Thread(target=worker, daemon=True).start()

            def poll():
                # The view may have been torn down while the audit ran;
                # configuring a destroyed button raises inside an after()
                # callback, so stop the poll instead.
                if not dbtn.winfo_exists():
                    return
                if "res" not in holder and "err" not in holder:
                    app.after(150, poll)
                    return
                dbtn.configure(state="normal", text="Run audit")
                if "err" in holder:
                    dstatus.configure(text="Audit failed: " + holder["err"], text_color=C.STAMP)
                    dstatus.pack(anchor="w", fill="x", pady=(6, 0))
                    return
                r = holder["res"]
                dresults.pack(anchor="w", fill="x", pady=(8, 0))

                def line(txt, col=C.INK, bold=False, indent=0):
                    lb = ctk.CTkLabel(dresults, text=(" " * indent) + txt,
                                      font=(FONT_BODY, 11, "bold") if bold else (FONT_BODY, 11),
                                      text_color=col, anchor="w", justify="left")
                    lb.pack(anchor="w", fill="x", pady=1)
                    bind_autowrap(lb, scroll, padding=100)

                n_opt = len(r["option_flags"])
                line(f"Answer options that cannot be told apart: {n_opt}",
                     C.STAMP if n_opt else C.FOREST, bold=True)
                for f in r["option_flags"][:5]:
                    line(f"{f['question_id']}: options {f['labels'][0]}/{f['labels'][1]} "
                         f"chosen at {f['pull'][0]*100:.0f}% and {f['pull'][1]*100:.0f}% "
                         f"\u2014 a coin flip once the key is eliminated", C.INK_DIM, indent=3)
                if r["options_insufficient"]:
                    line(f"({r['options_insufficient']} items lack the "
                         f"{MIN_RESPONSES_FOR_SEPARABILITY}+ answers this check needs)",
                         C.INK_DIM, indent=3)

                n_pair = len(r["item_pairs"])
                line(f"Possible duplicate questions: {n_pair}",
                     C.STAMP if n_pair else C.FOREST, bold=True)
                for pr in r["item_pairs"][:5]:
                    line(f"{pr['a']} / {pr['b']} \u2014 {pr['similarity']:.2f} similar"
                         + (f", both missed {pr['co_miss']}\u00d7" if pr["co_miss"] else "")
                         + f"  [{pr['certificate']}]", C.INK_DIM, indent=3)

                # Locus D -- an item that cannot be told apart from ITSELF.
                ur = r.get("unreliable_items", [])
                line(f"Questions that answer inconsistently: {len(ur)}",
                     C.STAMP if ur else C.FOREST, bold=True)
                for u in ur[:5]:
                    line(f"{u['question_id']}: misfit {u['outfit']:.1f} "
                         f"(1.0 = as expected), flips {u['alternation']*100:.0f}% of the time "
                         f"across {u['n']} exposures \u2014 likely ambiguous wording",
                         C.INK_DIM, indent=3)
                if not ur and r.get("reliability_insufficient"):
                    line(f"({r['reliability_insufficient']} items need "
                         f"{MIN_EXPOSURES_FOR_RELIABILITY}+ exposures before this check applies)",
                         C.INK_DIM, indent=3)

                pf = r.get("person_fit")
                if pf:
                    line("Your own recent answers: "
                         + ("don't match your usual level" if pf["aberrant"] else "consistent with your usual level")
                         + f"  (fit {pf['lz']:+.2f})",
                         C.INK if pf["aberrant"] else C.FOREST, bold=True)
                    line(pf["note"], C.INK_DIM, indent=3)

                n_un = r["unidentified_total"]
                line(f"Skill profiles this bank cannot distinguish: {n_un}",
                     C.STAMP if n_un else C.FOREST, bold=True)
                if not n_un:
                    line("Every decomposed topic's questions can separate every one-skill "
                         "difference \u2014 the per-skill diagnosis is well-founded.",
                         C.INK_DIM, indent=3)
                for t in r["profile_topics"][:4]:
                    if t["orphan_skills"]:
                        line(f"{t['topic']}: skills with no question testing them: "
                             f"{', '.join(t['orphan_skills'])}", C.STAMP, indent=3)
                    if t["unidentified"]:
                        line(f"{t['topic']}: {len(t['unidentified'])} skill(s) "
                             "unidentifiable (only ever tested together with another) "
                             "\u2014 needs a new question, not more practice",
                             C.STAMP, indent=3)

            app.after(150, poll)

        dbtn = primary_button(di, "Run audit", run_audit)
        dbtn.pack(anchor="w")
        dstatus.pack(anchor="w", fill="x", pady=(6, 0))


    lazy_section(scroll, "Distinguishability audit",
                 "Whether the bank can tell things apart \u2014 options, questions, skills, and itself.",
                 _build_audit)

    # ---- certificate dispatcher: findings grouped by ACTION ----
    def _build_queue(_parent):
        qd = certificate_queue(app.conn)
        gated = gated_item_ids(app.conn)
        qc = card(_parent)
        qc.pack(fill="x", pady=(0, 14))
        qi = ctk.CTkFrame(qc, fg_color="transparent")
        qi.pack(fill="x", padx=18, pady=14)
        intro = ctk.CTkLabel(
            qi,
            text=("Every distinguishability finding, grouped by what it should TRIGGER "
                  "rather than by which audit produced it. A weak signal means keep "
                  "measuring; two agreeing signals mean remediate; a structural "
                  "identifiability failure cannot be drilled away at all and needs new "
                  "content."),
            font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w", justify="left")
        intro.pack(anchor="w", fill="x", pady=(0, 10))
        bind_autowrap(intro, scroll, padding=90)

        for act, title, col in (("observe", "Keep measuring", C.INK_DIM),
                                ("remediate", "Targeted remediation", C.BRASS_DARK),
                                ("author", "Needs new content", C.STAMP)):
            rule = CERTIFICATE_ACTIONS[
                {"observe": CERT_SOFT, "remediate": CERT_QUASI_HARD,
                 "author": CERT_HARD}[act]]
            ctk.CTkLabel(qi, text=f"{title}  ({len(qd[act])})",
                         font=(FONT_BODY, 12, "bold"), text_color=col,
                         anchor="w").pack(anchor="w", pady=(8, 2))
            ctk.CTkLabel(qi, text="   " + rule["detail"], font=(FONT_BODY, 10),
                         text_color=C.INK_DIM, anchor="w",
                         justify="left").pack(anchor="w")
            if not qd[act]:
                ctk.CTkLabel(qi, text="   nothing outstanding", font=(FONT_BODY, 10),
                             text_color=C.FOREST, anchor="w").pack(anchor="w")
            for e in qd[act][:6]:
                erow = ctk.CTkFrame(qi, fg_color="transparent", height=0)
                erow.pack(fill="x", pady=1)
                ctk.CTkLabel(erow,
                             text=f"   \u2022 {e['kind']}: {e['ref']} \u2014 {e['why']}"[:96],
                             font=(FONT_BODY, 10), text_color=C.INK,
                             anchor="w").pack(side="left")
                # A finding you cannot act on is still just a report. The
                # repair button is what makes the queue a work queue -- and
                # applying it propagates across every dependent analysis.
                ref = str(e.get("ref", ""))
                if act in ("remediate", "author") and ref in QUIZ_BANK:
                    def _repair(qid=ref):
                        r = apply_item_repair(app.conn, qid, "retire",
                                              "retired from the findings queue")
                        if r.get("ok"):
                            app.toast(r["note"][:120], kind="good")
                        else:
                            app.toast(r.get("reason", "repair failed"), kind="warn")
                        app.show_view("contentqa")
                    ghost_button(erow, "Retire", _repair).pack(side="right")

        ctk.CTkLabel(qi,
                     text=(f"Competence gate: {len(gated)} item(s) currently withheld "
                           "because your mastery on their topic is too low for the "
                           "answer to carry information."),
                     font=(FONT_BODY, 10, "bold"),
                     text_color=(C.BRASS_DARK if gated else C.FOREST),
                     anchor="w").pack(anchor="w", pady=(10, 0))

        gg = generalization_gap(app.conn)
        ctk.CTkLabel(qi, text="Generalization", font=(FONT_BODY, 12, "bold"),
                     text_color=C.INK, anchor="w").pack(anchor="w", pady=(12, 2))
        if gg.get("status") == "ok":
            ctk.CTkLabel(qi,
                         text=(f"   seed {gg['seed_accuracy']*100:.0f}% vs variants "
                               f"{gg['variant_accuracy']*100:.0f}%  \u2014  {gg['verdict']}"),
                         font=(FONT_BODY, 11),
                         text_color=(C.FOREST if gg["gap"] < 0.10 else C.STAMP),
                         anchor="w").pack(anchor="w")
        else:
            ctk.CTkLabel(qi, text="   " + gg.get("note", ""), font=(FONT_BODY, 10),
                         text_color=C.INK_DIM, anchor="w",
                         justify="left").pack(anchor="w")

    def _build_completeness(_parent):
        r = completeness_report(app.conn)
        ci = ctk.CTkFrame(_parent, fg_color="transparent")
        ci.pack(fill="x", padx=4, pady=4)
        note = ctk.CTkLabel(
            ci,
            text=("Ten assets are needed before a skill can teach itself. This "
                  "measures which exist for each of the 172 skills, so a thin "
                  "brief becomes a named work order instead of a complaint "
                  "about the corpus."),
            font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w",
            justify="left")
        note.pack(anchor="w", fill="x", pady=(0, 10))
        bind_autowrap(note, scroll, padding=90)
        ctk.CTkLabel(ci,
                     text=(f"Mean completeness {r['mean']*100:.0f}%  \u00b7  "
                           f"{r['complete']} of {r['skills']} skills complete  "
                           f"\u00b7  {r['weak']} below 60%"),
                     font=(FONT_BODY, 12, "bold"),
                     text_color=(C.FOREST if r["mean"] > 0.8 else C.BRASS_DARK),
                     anchor="w").pack(anchor="w", pady=(0, 10))

        ctk.CTkLabel(ci, text="Author these first \u2014 most-missing across the bank",
                     font=(FONT_BODY, 11, "bold"), text_color=C.BRASS_DARK,
                     anchor="w").pack(anchor="w", pady=(4, 3))
        for asset, n in r["most_missing"][:6]:
            row = ctk.CTkFrame(ci, fg_color="transparent", height=0)
            row.pack(fill="x", pady=1)
            ctk.CTkLabel(row, text=asset, font=(FONT_BODY, 11),
                         text_color=C.INK, width=200, anchor="w").pack(side="left")
            track = ctk.CTkFrame(row, fg_color=C.PAPER_LINE, height=9,
                                 corner_radius=4)
            track.pack(side="left", fill="x", expand=True, padx=8)
            track.pack_propagate(False)
            ctk.CTkFrame(track, fg_color=C.STAMP, height=9, corner_radius=4,
                         width=max(3, int((n / max(1, r["skills"])) * 300))
                         ).place(x=0, y=0)
            ctk.CTkLabel(row, text=f"{n}/{r['skills']}", font=(FONT_MONO, 10),
                         text_color=C.INK_DIM, width=60,
                         anchor="e").pack(side="left")

        ctk.CTkLabel(ci, text="Thinnest skills", font=(FONT_BODY, 11, "bold"),
                     text_color=C.BRASS_DARK, anchor="w").pack(anchor="w",
                                                               pady=(12, 3))
        for x in r["worst"][:8]:
            wl = ctk.CTkLabel(
                ci,
                text=(f"   {x['score']*100:3.0f}%  {x['label'][:44]}  \u2014  "
                      + ", ".join(m["asset"] for m in x["missing"][:3])),
                font=(FONT_BODY, 10),
                text_color=(C.STAMP if x["score"] < 0.5 else C.INK),
                anchor="w", justify="left")
            wl.pack(anchor="w", fill="x")

    lazy_section(scroll, "Content completeness",
                 "Which skills can teach themselves, and what the rest are missing.",
                 _build_completeness)

    lazy_section(scroll, "Findings and what they trigger",
                 "Distinguishability results as a work queue, not a warning list.",
                 _build_queue)
    unclassified = unclassified_modes(app.conn)
    if unclassified:
        warn = card(scroll, fg_color=C.STAMP_DIM)
        warn.pack(fill="x", pady=(0, 14))
        wi = ctk.CTkFrame(warn, fg_color="transparent", height=0)
        wi.pack(fill="x", padx=18, pady=13)
        ctk.CTkLabel(wi, text="UNCLASSIFIED SESSION MODES", font=(FONT_BODY, 10, "bold"),
                     text_color=C.STAMP, anchor="w").pack(anchor="w")
        wl = ctk.CTkLabel(
            wi,
            text=("These modes appear in your history but have no entry in the mode taxonomy, "
                  "so they are being treated as untimed/calm by the timing baselines and are "
                  "invisible to the pressure model: " + ", ".join(unclassified)),
            font=(FONT_BODY, 12), text_color=C.INK, anchor="w", justify="left")
        wl.pack(anchor="w", fill="x", pady=(3, 0))
        bind_autowrap(wl, scroll, padding=90)

    chips = ctk.CTkFrame(scroll, fg_color="transparent")
    chips.pack(fill="x", pady=(0, 8))
    cited_pct = 100 * r["cited"] / n
    stat_chip(chips, "Questions", str(n)).pack(side="left", padx=(0, 10))
    stat_chip(chips, "With a citation", f'{r["cited"]} ({cited_pct:.0f}%)',
              value_color=(C.FOREST if cited_pct > 80 else C.STAMP)).pack(side="left", padx=10)
    wpct = 100 * (n - len(r["missing_why"])) / n
    stat_chip(chips, "With rebuttals", f'{n - len(r["missing_why"])} ({wpct:.0f}%)',
              value_color=(C.FOREST if wpct > 80 else C.BRASS)).pack(side="left", padx=10)
    stat_chip(chips, "Stale (>1yr)", str(len(r["stale"])),
              value_color=(C.STAMP if r["stale"] else C.CREAM)).pack(side="left", padx=(10, 0))

    warn = card(scroll, fg_color=(C.STAMP_DIM if cited_pct < 80 else C.PAPER_DIM))
    warn.pack(fill="x", pady=(12, 18))
    wi = ctk.CTkFrame(warn, fg_color="transparent", height=0)
    wi.pack(fill="x", padx=18, pady=14)
    msg = (f'{n - r["cited"]} of {n} questions carry no citation. Treat those as unverified: '
           "cross-check anything numeric or NJ-specific against your course materials or the "
           "Real Estate Commission before relying on it."
           if cited_pct < 80 else
           "Citation coverage is healthy. Keep an eye on the stale list below.")
    ml = ctk.CTkLabel(wi, text=msg, font=(FONT_BODY, 12),
                      text_color=(C.STAMP if cited_pct < 80 else C.INK),
                      anchor="w", justify="left")
    ml.pack(anchor="w", fill="x")
    bind_autowrap(ml, scroll, padding=90)

    ctk.CTkLabel(scroll, text="Citation coverage by portion", font=(FONT_DISPLAY, 15, "bold"),
                 text_color=C.INK, anchor="w").pack(anchor="w", pady=(4, 8))
    gc = card(scroll)
    gc.pack(fill="x", pady=(0, 16))
    gi = ctk.CTkFrame(gc, fg_color="transparent", height=0)
    gi.pack(fill="x", padx=16, pady=12)
    for grp, d in sorted(r["by_group"].items()):
        pct = 100 * d["cited"] / d["n"] if d["n"] else 0
        row = ctk.CTkFrame(gi, fg_color="transparent", height=0)
        row.pack(fill="x", pady=3)
        ctk.CTkLabel(row, text=grp, font=(FONT_BODY, 12), text_color=C.INK,
                     width=130, anchor="w").pack(side="left")
        track = ctk.CTkFrame(row, fg_color=C.PAPER_LINE, height=10, corner_radius=5)
        track.pack(side="left", fill="x", expand=True, padx=10)
        track.pack_propagate(False)
        col = C.FOREST if pct >= 80 else (C.BRASS if pct >= 40 else C.STAMP)
        ctk.CTkFrame(track, fg_color=col, height=10, corner_radius=5,
                     width=max(3, int(pct * 3.6))).place(x=0, y=0)
        ctk.CTkLabel(row, text=f'{d["cited"]}/{d["n"]}  ({pct:.0f}%)', font=(FONT_MONO, 11),
                     text_color=C.INK_DIM, width=120, anchor="e").pack(side="left")

    def listing(title, items, color, fmt, limit=25):
        if not items:
            return
        ctk.CTkLabel(scroll, text=f"{title} ({len(items)})", font=(FONT_DISPLAY, 15, "bold"),
                     text_color=color, anchor="w").pack(anchor="w", pady=(6, 8))
        c = card(scroll)
        c.pack(fill="x", pady=(0, 14))
        ci = ctk.CTkFrame(c, fg_color="transparent", height=0)
        ci.pack(fill="x", padx=16, pady=12)
        for it in items[:limit]:
            lbl = ctk.CTkLabel(ci, text=fmt(it), font=(FONT_BODY, 11), text_color=C.INK,
                               anchor="w", justify="left")
            lbl.pack(anchor="w", fill="x", pady=1)
            bind_autowrap(lbl, scroll, padding=90)
        if len(items) > limit:
            ctk.CTkLabel(ci, text=f"... and {len(items)-limit} more", font=(FONT_BODY, 11, "italic"),
                         text_color=C.INK_DIM, anchor="w").pack(anchor="w", pady=(4, 0))

    listing("Stale verifications", r["stale"], C.STAMP,
            lambda t: f'[{t[0]["id"]}] verified {t[1]} months ago \u2014 {t[0]["q"][:70]}')
    listing("Partial distractor rebuttals", r["partial_why"], C.BRASS_DARK,
            lambda t: f'[{t[0]["id"]}] {t[1]}/{t[2]} distractors explained \u2014 {t[0]["q"][:66]}')
    listing("No citation", r["uncited"], C.STAMP,
            lambda q: f'[{q["id"]}] {TOPICS[q["topic"]]["short"]} \u2014 {q["q"][:76]}', limit=30)

    # ---- the standing adversarial catalogue (directive XXI) --------------
    # Deliberately behind a button. Running it at startup would charge the
    # learner a second of every launch for a check that exists for whoever
    # is changing the code, and a self-check nobody chose to run is a check
    # nobody reads.
    ctk.CTkLabel(scroll, text="Self-check", font=(FONT_DISPLAY, 15, "bold"),
                 text_color=C.INK, anchor="w").pack(anchor="w", pady=(10, 6))
    sc = card(scroll)
    sc.pack(fill="x", pady=(0, 16))
    si = ctk.CTkFrame(sc, fg_color="transparent", height=0)
    si.pack(fill="x", padx=18, pady=14)
    intro = ctk.CTkLabel(
        si,
        text=(f"{len(ADVERSARIAL_CLASSES)} failure CLASSES, each one found in this "
              "codebase rather than imagined, each with the invariant it violates "
              "and a probe that would catch a recurrence. Every probe is also run "
              "against a deliberately broken stand-in of its own class and must "
              "fail there \u2014 a probe that cannot fail is worse than no probe. "
              "Runs headless against a temporary database; your history is not "
              "touched."),
        font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w", justify="left")
    intro.pack(anchor="w", fill="x", pady=(0, 10))
    bind_autowrap(intro, scroll, padding=90)
    # Created here, packed below the button, so the results land under the
    # control that produced them.
    out = ctk.CTkFrame(si, fg_color="transparent", height=0)

    for name, spec_ac in ADVERSARIAL_CLASSES.items():
        er = ctk.CTkFrame(out, fg_color="transparent", height=0)
        er.pack(fill="x", pady=(0, 7))
        ctk.CTkLabel(er, text="\u25cb  " + spec_ac["title"], font=(FONT_BODY, 12),
                     text_color=C.INK, anchor="w").pack(anchor="w")
        il = ctk.CTkLabel(er, text="Invariant: " + spec_ac["invariant"],
                          font=(FONT_BODY, 10), text_color=C.INK_DIM,
                          anchor="w", justify="left")
        il.pack(anchor="w", fill="x")
        bind_autowrap(il, scroll, padding=110)

    def run_self_check():
        btn.configure(state="disabled", text="Running\u2026")
        for w in out.winfo_children():
            w.destroy()
        res = {}

        def worker():
            try:
                res["r"] = run_adversarial_catalogue()
            except Exception as e:
                res["err"] = f"{type(e).__name__}: {e}"

        import threading
        threading.Thread(target=worker, daemon=True).start()

        def poll():
            if "r" not in res and "err" not in res:
                parent.after(150, poll)
                return
            if not out.winfo_exists():
                return
            btn.configure(state="normal", text="Run the self-check again")
            if res.get("err"):
                ctk.CTkLabel(out, text="The self-check could not run: " + res["err"],
                             font=(FONT_BODY, 12), text_color=C.STAMP,
                             anchor="w").pack(anchor="w")
                return
            r = res["r"]
            head = (f"{r['n'] - r['n_failed']} of {r['n']} classes pass"
                    + (f"; {r['n_unfalsifiable']} probe(s) UNFALSIFIABLE"
                       if r["n_unfalsifiable"] else
                       "; every probe caught an injected instance of its own class"))
            ctk.CTkLabel(out, text=head, font=(FONT_BODY, 12, "bold"),
                         text_color=(C.FOREST if r["ok"] else C.STAMP),
                         anchor="w").pack(anchor="w", pady=(0, 8))
            for e in r["entries"]:
                row = ctk.CTkFrame(out, fg_color="transparent", height=0)
                row.pack(fill="x", pady=(0, 7))
                ok = e["passed"] and e["caught_injection"] is not False
                ctk.CTkLabel(row, text=("\u2713  " if ok else "\u2717  ") + e["title"],
                             font=(FONT_BODY, 12),
                             text_color=(C.INK if ok else C.STAMP),
                             anchor="w").pack(anchor="w")
                dl = ctk.CTkLabel(row, text=e["detail"], font=(FONT_BODY, 10),
                                  text_color=C.INK_DIM, anchor="w", justify="left")
                dl.pack(anchor="w", fill="x")
                bind_autowrap(dl, scroll, padding=110)
                if e["caught_injection"] is False:
                    ul = ctk.CTkLabel(
                        row,
                        text=("This probe also PASSED on a deliberately broken "
                              "instance of its own class, so it is checking "
                              "nothing: " + e["injection_detail"]),
                        font=(FONT_BODY, 10), text_color=C.STAMP,
                        anchor="w", justify="left")
                    ul.pack(anchor="w", fill="x")
                    bind_autowrap(ul, scroll, padding=110)

        parent.after(150, poll)

    btn = primary_button(si, "Run the self-check", run_self_check)
    btn.pack(anchor="w", pady=(4, 0))
    out.pack(fill="x", pady=(12, 0))


# ============================================================================
# GLOBAL SEARCH
# ============================================================================
# Searches questions, flashcards, and topic notes at once -- previously the
# only way to find where a specific fact lived was to remember which of the
# 18 topics it was under and browse there.

def view_search(app, parent):
    conn = app.conn
    wrap = ctk.CTkFrame(parent, fg_color="transparent")
    wrap.pack(fill="both", expand=True, padx=32, pady=28)
    section_title(wrap, "Search",
                  "Find anything across questions, flashcards, and study notes at once.").pack(
        anchor="w", pady=(0, 16))

    row = ctk.CTkFrame(wrap, fg_color="transparent", height=0)
    row.pack(fill="x", pady=(0, 6))
    entry = styled_entry(row, width=420, font=(FONT_BODY, 13),
                         placeholder_text="e.g. trust account, net listing, adverse possession")
    entry.pack(side="left", padx=(0, 8))

    results_area = ctk.CTkScrollableFrame(wrap, fg_color="transparent")
    results_area.pack(fill="both", expand=True, pady=(10, 0))

    KIND_LABEL = {"question": "Question", "flashcard": "Flashcard", "note": "Study note", "skill": "Skill"}
    KIND_COLOR = {"question": C.BRASS_DARK, "flashcard": C.FOREST, "note": C.NAVY, "skill": C.NAVY_3}

    def open_question(qid):
        q = QUIZ_BANK.get(qid)
        if not q:
            return
        for w in app.content.winfo_children():
            w.destroy()
        QuestionSession(app, app.content, [q], "quiz", "Practice Quiz",
                        "from search", allow_hints=True, collect_diagnostics=False,
                        on_finish=lambda s: render_result_screen(
                            app, app.content, s, lambda: app.show_view("search")))

    def open_topic_notes(topic_id):
        set_setting(conn, "notes_focus_topic", topic_id)
        app.show_view("notes")

    def run_search():
        q = entry.get()
        for w in results_area.winfo_children():
            w.destroy()
        if not q.strip():
            return
        results = search_content(conn, q, limit=25)
        if not results:
            ctk.CTkLabel(results_area, text="No matches. Try fewer or different words.",
                        font=(FONT_BODY, 13), text_color=C.INK_DIM).pack(anchor="w", pady=10)
            return
        ctk.CTkLabel(results_area, text=f"{len(results)} result(s)", font=(FONT_BODY, 11),
                    text_color=C.INK_DIM).pack(anchor="w", pady=(0, 8))
        for r in results:
            c = card(results_area)
            c.pack(fill="x", pady=4)
            inner = ctk.CTkFrame(c, fg_color="transparent", height=0)
            inner.pack(fill="x", padx=16, pady=12)
            head = ctk.CTkFrame(inner, fg_color="transparent", height=0)
            head.pack(fill="x")
            ctk.CTkLabel(head, text=KIND_LABEL.get(r["kind"], r["kind"].title()),
                        font=(FONT_BODY, 9, "bold"), text_color=KIND_COLOR.get(r["kind"], C.INK),
                        anchor="w").pack(side="left")
            topic = TOPICS.get(r["topic_id"])
            if topic and r["kind"] != "note":
                ctk.CTkLabel(head, text="  \u00b7  " + topic["short"], font=(FONT_BODY, 9),
                            text_color=C.INK_DIM, anchor="w").pack(side="left")
            title_lbl = ctk.CTkLabel(inner, text=r["title"], font=(FONT_BODY, 13, "bold"),
                                     text_color=C.INK, anchor="w", justify="left")
            title_lbl.pack(anchor="w", fill="x", pady=(4, 2))
            bind_autowrap(title_lbl, wrap, padding=90)
            snip = re.sub(r"\s+", " ", r["snippet"]).strip()
            snip_lbl = ctk.CTkLabel(inner, text=snip, font=(FONT_BODY, 11), text_color=C.INK_DIM,
                                    anchor="w", justify="left")
            snip_lbl.pack(anchor="w", fill="x")
            bind_autowrap(snip_lbl, wrap, padding=90)
            if r["kind"] == "question":
                ghost_button(inner, "Practice this question",
                            lambda qid=r["item_id"]: open_question(qid)).pack(anchor="w", pady=(8, 0))
                # Semantically related items from the precomputed vectors.
                # Keyword search finds what shares words; this finds what
                # shares meaning -- the confusable neighbours a learner
                # most needs to see side by side. Costs one dot product.
                try:
                    nbrs = embedding_neighbors("q:" + r["item_id"], limit=2, kinds=("q",))
                    nbrs = [(sim, k) for sim, k in nbrs if sim > 0.55]
                    if nbrs:
                        rel = ctk.CTkLabel(
                            inner,
                            text="Related: " + "  \u00b7  ".join(
                                QUIZ_BANK[k.split(":", 1)[1]]["q"][:58] + "\u2026"
                                for _, k in nbrs if k.split(":", 1)[1] in QUIZ_BANK),
                            font=(FONT_BODY, 10), text_color=C.INK_DIM,
                            anchor="w", justify="left")
                        rel.pack(anchor="w", fill="x", pady=(5, 0))
                        bind_autowrap(rel, wrap, padding=90)
                except Exception:
                    pass
            elif r["kind"] == "skill":
                ghost_button(inner, "Open on the map",
                             lambda sid=r["item_id"]: vis_go_map(app, sid)).pack(anchor="w", pady=(8, 0))
            elif r["kind"] in ("flashcard", "note"):
                ghost_button(inner, "Open topic notes",
                            lambda tid=r["topic_id"]: open_topic_notes(tid)).pack(anchor="w", pady=(8, 0))

    primary_button(row, "Search", run_search).pack(side="left")
    entry.bind("<Return>", lambda e: run_search())
    entry.focus_set()

    # An empty search box in an otherwise-empty window read as unfinished --
    # personalized example queries (built from your own recent misses, not
    # generic hardcoded examples) give the empty state something to invite,
    # per the same "emptiness is a moment for direction" idea already
    # applied to Item Analysis's empty state below.
    suggestions = []
    try:
        rows = conn.execute("""SELECT DISTINCT question_id FROM attempts
                               WHERE correct=0 ORDER BY id DESC LIMIT 40""").fetchall()
        seen_topics = set()
        for r in rows:
            q = QUIZ_BANK.get(r["question_id"])
            if not q or q["topic"] in seen_topics:
                continue
            seen_topics.add(q["topic"])
            words = [w for w in re.findall(r"[A-Za-z']{4,}", q["q"]) if w.lower() not in
                    {"which", "what", "does", "when", "must", "shall", "under", "with", "that"}][:3]
            if words:
                suggestions.append(" ".join(words))
            if len(suggestions) >= 4:
                break
    except Exception:
        suggestions = []
    if not suggestions:
        suggestions = ["trust account", "net listing", "adverse possession", "designated agency"]

    sug_wrap = ctk.CTkFrame(wrap, fg_color="transparent", height=0)
    sug_wrap.pack(anchor="w", pady=(2, 0))
    ctk.CTkLabel(sug_wrap, text="Try:", font=(FONT_BODY, 11), text_color=C.INK_DIM,
                anchor="w").pack(side="left", padx=(0, 8))
    for s in suggestions:
        def run_suggestion(term=s):
            entry.delete(0, "end")
            entry.insert(0, term)
            run_search()
        ghost_button(sug_wrap, s, run_suggestion).pack(side="left", padx=(0, 6))


def view_learner_model(app, parent):
    """THE OPEN LEARNER MODEL.

    Every other view answers "what should I do next?". This one answers a
    question the app has never let anyone ask: "what does this system
    actually believe about me, why, and can I argue with it?"

    THE VISUAL IDEA. Uncertainty is rendered as SOFTNESS rather than as a
    number beside a number. A well-evidenced belief draws as a tight, bright,
    solid node; a tentative one draws large, dim and diffuse, with a visible
    halo of doubt. This matters because the OLM uncertainty literature finds
    people read a bare percentage as settled fact -- "68% from four answers"
    and "68% from forty" render identically as text, and the whole point is
    that they are different claims. Here they cannot look the same.

    Layout follows the same hub-and-spoke language as the startup screen, so
    the app makes one visual argument about itself throughout: a shared model
    at the centre, evidence orbiting it.
    """
    conn = app.conn

    def _close_abandoned_challenge(cid):
        """A challenge is registered the moment the probe starts, so one
        that is still open when this view is (re)built was walked out of
        mid-probe. It closes as inconclusive with no probe evidence, and
        the model is left exactly where it was."""
        if cid is None:
            return
        try:
            conn.execute("UPDATE model_challenges SET resolved=1, verdict='inconclusive', "
                         "probe_correct=0, probe_total=0 WHERE id=? AND resolved=0", (cid,))
            conn.commit()
            _audit(conn, "challenge_abandoned", f"challenge={cid} probe not completed")
        except sqlite3.Error as e:
            _audit(conn, "challenge_close_failed", f"challenge={cid}: {e}")

    for _stale in (open_challenges(conn) or []):
        _close_abandoned_challenge(_stale["id"])

    wrap = ctk.CTkFrame(parent, fg_color="transparent")
    wrap.pack(fill="both", expand=True, padx=30, pady=(20, 10))

    section_title(wrap, "Your Learner Model",
                  "Everything this system believes about you, how strongly, "
                  "and why \u2014 with the option to disagree.").pack(anchor="w", pady=(0, 12))

    model = open_learner_model(conn)
    # Partial-pooled per-topic ability. A topic with three answers must not
    # get its own wild estimate; empirical-Bayes shrinkage toward the global
    # figure is what makes a per-topic number safe to show at all. This was
    # computed but never displayed anywhere.
    try:
        hier = hierarchical_topic_ability(conn)
    except Exception:
        hier = {}
    total_n = sum(m["n"] for m in model)
    if total_n == 0:
        c = card(wrap)
        c.pack(fill="x")
        inner = ctk.CTkFrame(c, fg_color="transparent")
        inner.pack(fill="x", padx=20, pady=18)
        ctk.CTkLabel(inner, text="Nothing believed yet.", font=(FONT_DISPLAY, 15, "bold"),
                     text_color=C.INK, anchor="w").pack(anchor="w")
        ctk.CTkLabel(inner,
                     text="This screen fills in as you answer questions. It will show what the "
                          "system concludes about each topic, how much evidence sits behind that, "
                          "and let you challenge anything you think is wrong.",
                     font=(FONT_BODY, 12), text_color=C.INK_DIM, anchor="w",
                     justify="left", wraplength=620).pack(anchor="w", pady=(6, 0))
        primary_button(inner, "Start the diagnostic",
                       lambda: app.show_view("diagnostic")).pack(anchor="w", pady=(14, 0))
        return

    # ---- the constellation ------------------------------------------------
    canvas_card = card(wrap)
    canvas_card.pack(fill="x", pady=(0, 14))
    cv = tk.Canvas(canvas_card, height=520, bg=C.PAPER_DIM,
                   highlightthickness=0, bd=0)
    cv.pack(fill="x", padx=14, pady=14)

    state = {"sel": None, "t": 0.0, "job": None}

    def mix(c1, c2, f):
        f = max(0.0, min(1.0, f))
        a = [int(c1[i:i + 2], 16) for i in (1, 3, 5)]
        b = [int(c2[i:i + 2], 16) for i in (1, 3, 5)]
        return "#%02x%02x%02x" % tuple(int(a[i] + (b[i] - a[i]) * f) for i in range(3))

    def node_geom():
        w = max(cv.winfo_width(), 400)
        h = max(cv.winfo_height(), 260)
        cx, cy = w / 2.0, h / 2.0
        # The outermost thing drawn is not the ring: it is a weakly-evidenced
        # node (which sits at R*1.18, further out than a confident one) plus
        # its own radius plus a radially-placed label beyond that. Sizing R
        # from h*0.40 ignored all three, so the bottom node and its caption
        # were drawn past the canvas edge and clipped. Reserve that margin
        # explicitly instead.
        node_r = max(20.0, min(w, h) * 0.035)
        label_margin = node_r + 26          # label sits at node_r + ~14, plus text height
        avail_v = (h / 2.0) - label_margin
        avail_h = (w / 2.0) - label_margin - 70   # side labels run horizontally
        R = max(90.0, min(w * 0.30, avail_v / 1.18, avail_h / 1.18))
        out = []
        n = len(model)
        for i, m in enumerate(model):
            ang = math.radians(-90 + (360.0 / n) * i)
            # Well-supported beliefs sit CLOSER to the centre: distance
            # encodes how much the model actually knows about that topic.
            strength = m["confidence"]["strength"]
            rr = R * (1.18 - 0.42 * strength)
            out.append((cx + rr * math.cos(ang), cy + rr * math.sin(ang), m))
        return cx, cy, R, out

    def draw():
        if not cv.winfo_exists():
            return
        cv.delete("all")
        t = state["t"]
        cx, cy, R, nodes = node_geom()

        for i in range(5, 0, -1):
            rr = R * (0.55 + i * 0.18)
            cv.create_oval(cx - rr, cy - rr, cx + rr, cy + rr,
                           outline=mix(C.PAPER_DIM, C.PAPER_LINE, 0.5), width=1)

        for (nx, ny, m) in nodes:
            strength = m["confidence"]["strength"]
            cv.create_line(cx, cy, nx, ny,
                           fill=mix(C.PAPER_DIM, C.BRASS, 0.15 + 0.5 * strength),
                           width=1 + 1.5 * strength)

        for (nx, ny, m) in nodes:
            mastery = m["mastery"]
            strength = m["confidence"]["strength"]
            col = (C.FOREST if mastery >= 0.6 else
                   C.BRASS if mastery >= 0.35 else C.INK_DIM)
            base = 7 + 9 * mastery
            # UNCERTAINTY AS SOFTNESS: a weakly-evidenced belief gets a wide,
            # faint halo -- literally fuzzy. A well-evidenced one is tight
            # and solid. The halo is the doubt, drawn.
            halo_layers = int(2 + 7 * (1.0 - strength))
            for k in range(halo_layers, 0, -1):
                rr = base + k * (2.0 + 3.0 * (1.0 - strength))
                cv.create_oval(nx - rr, ny - rr, nx + rr, ny + rr,
                               outline=mix(C.PAPER_DIM, col,
                                           0.22 * strength + 0.05), width=1)
            sel = (state["sel"] is not None
                   and state["sel"]["topic_id"] == m["topic_id"])
            if sel:
                pulse = 3 + 2 * math.sin(math.radians(t * 6))
                cv.create_oval(nx - base - pulse, ny - base - pulse,
                               nx + base + pulse, ny + base + pulse,
                               outline=C.INK, width=2)
            cv.create_oval(nx - base, ny - base, nx + base, ny + base,
                           fill=mix(C.PAPER_DIM, col, 0.35 + 0.65 * strength),
                           outline=mix(col, C.INK, 0.3 * strength),
                           width=1 + strength)
            # Labels are placed RADIALLY (pushed further out along the same
            # spoke) rather than directly under each node. Stacking them
            # below made the lower half of the ring collide with itself and
            # pushed several labels over the hub, where they were unreadable.
            dx, dy = nx - cx, ny - cy
            dist = math.hypot(dx, dy) or 1.0
            lx = nx + (dx / dist) * (base + 14)
            ly = ny + (dy / dist) * (base + 12)
            anchor = "w" if dx > 12 else ("e" if dx < -12 else "center")
            cv.create_text(lx, ly, text=TOPICS[m["topic_id"]]["short"][:20],
                           fill=mix(C.INK_DIM, C.INK, strength),
                           font=(FONT_BODY, 8), anchor=anchor)

        cv.create_oval(cx - 46, cy - 46, cx + 46, cy + 46,
                       fill=C.NAVY, outline=C.BRASS, width=2)
        cv.create_text(cx, cy - 10, text="LEARNER", fill=C.GOLD_SOFT,
                       font=(FONT_BODY, 8, "bold"))
        cv.create_text(cx, cy + 6, text="MODEL", fill=C.CREAM,
                       font=(FONT_DISPLAY, 13, "bold"))
        cv.create_text(cx, cy + 24, text=f"{total_n} answers",
                       fill=C.GOLD_SOFT, font=(FONT_BODY, 8))

        state["t"] += 1.0
        state["job"] = app.after(60, draw)

    def on_click(ev):
        _, _, _, nodes = node_geom()
        best, bd = None, 1e9
        for (nx, ny, m) in nodes:
            d = (ev.x - nx) ** 2 + (ev.y - ny) ** 2
            if d < bd:
                best, bd = m, d
        if best is not None and bd < 60 ** 2:
            state["sel"] = best
            render_detail()

    cv.bind("<Button-1>", on_click)
    cv.bind("<Configure>", lambda e: None)

    legend = ctk.CTkLabel(
        wrap,
        text=("Distance from centre and softness both show CONFIDENCE, not skill: a fuzzy, "
              "far-out node means the system has barely any evidence about that topic, "
              "whatever the colour says. Colour shows believed mastery. Click any node."),
        font=(FONT_BODY, 10), text_color=C.INK_DIM, anchor="w", justify="left")
    legend.pack(anchor="w", pady=(0, 10))
    bind_autowrap(legend, wrap, padding=60)

    # ---- detail / negotiation panel --------------------------------------
    detail_holder = ctk.CTkFrame(wrap, fg_color="transparent")
    detail_holder.pack(fill="both", expand=True)

    def render_detail():
        for w in detail_holder.winfo_children():
            w.destroy()
        m = state["sel"]
        if m is None:
            ctk.CTkLabel(detail_holder,
                         text="Select a topic above to inspect what is believed and why.",
                         font=(FONT_BODY, 12), text_color=C.INK_DIM,
                         anchor="w").pack(anchor="w", pady=8)
            return
        tid = m["topic_id"]
        c = card(detail_holder)
        c.pack(fill="x", pady=(0, 10))
        inner = ctk.CTkFrame(c, fg_color="transparent")
        inner.pack(fill="x", padx=18, pady=14)

        ctk.CTkLabel(inner, text=TOPICS[tid]["name"], font=(FONT_DISPLAY, 15, "bold"),
                     text_color=C.INK, anchor="w").pack(anchor="w")

        h = hier.get(tid)
        conf = m["confidence"]
        claim = ctk.CTkLabel(
            inner,
            text=(f"Believed mastery {m['mastery']*100:.0f}%  \u00b7  "
                  f"{conf['label']} ({conf['n']} answers)"),
            font=(FONT_BODY, 12, "bold"),
            # Colour tracks MASTERY, not confidence. Keying it to confidence
            # painted "believed mastery 20% (well supported)" in green,
            # which reads as good news when it is the opposite.
            text_color=(C.FOREST if m["mastery"] >= 0.6 else
                        C.BRASS_DARK if m["mastery"] >= 0.35 else C.INK_DIM),
            anchor="w")
        claim.pack(anchor="w", pady=(4, 2))

        # The claim is stated in words as well as a number, because the
        # number alone is what gets over-read as certainty.
        if h:
            ctk.CTkLabel(
                inner,
                text=(f"Ability on this topic: {h['theta']:+.2f} "
                      f"(\u00b1{h['se']:.2f})"
                      + (f"  \u2014 {h['shrunk']*100:.0f}% of this is borrowed from "
                         "your overall level, because this topic has little data"
                         if h.get("shrunk", 0) > 0.35 else "")),
                font=(FONT_BODY, 11), text_color=C.INK_DIM,
                anchor="w").pack(anchor="w", pady=(2, 4))
        if conf["strength"] < 0.4:
            ctk.CTkLabel(inner,
                         text="This is a weak guess. Treat it as a starting point, not a finding.",
                         font=(FONT_BODY, 11, "italic"), text_color=C.INK_DIM,
                         anchor="w").pack(anchor="w", pady=(0, 6))

        # ---- the evidence, inspectable ----
        # ---- the SUB-SKILL picture, which this view never showed ----
        # A topic-level number blends every sub-fact into one figure. The
        # DINA posterior already separates them, the belief graph already
        # says which are hypothesised wrong, and neither was reaching the
        # one view named for the learner model. That made this the most
        # underpowered view in the app relative to its name.
        # The rows come from open_learner_model's entry for this node, which
        # carries `n` per sub-skill: a skill nobody has been tested on sits
        # at the 0.5 prior in the posterior, and showing that as a measured
        # "50%" in the weakest-first list would contradict the model's own
        # evidence rule. Measured skills rank weakest first; prior-only
        # skills follow, marked as such, with no percentage.
        skills = m.get("skills") or []
        if skills:
            ctk.CTkLabel(inner, text="Inside this topic, sub-skill by sub-skill",
                         font=(FONT_BODY, 11, "bold"), text_color=C.INK,
                         anchor="w").pack(anchor="w", pady=(12, 4))
            measured = sorted((s for s in skills if s.get("n")), key=lambda s: s["mastery"])
            unmeasured = [s for s in skills if not s.get("n")]
            ranked = [(s["skill"], s["mastery"], s["n"]) for s in measured + unmeasured]
            try:
                live_beliefs = {b["skill_id"]: b for b in active_beliefs(conn, 40)}
            except Exception:
                live_beliefs = {}
            shown = ranked[:8]
            for sid_, ms, n_ in shown:
                row = ctk.CTkFrame(inner, fg_color="transparent", height=0)
                row.pack(fill="x", pady=1)
                lab = SKILLS.get(sid_, {}).get("label", sid_)
                sl = ctk.CTkLabel(row, text=lab[:44], font=(FONT_BODY, 11),
                                  text_color=C.INK if n_ else C.INK_DIM, width=300, anchor="w")
                sl.pack(side="left")
                if n_:
                    col = C.INK_DIM if ms < 0.35 else (C.BRASS_DARK if ms < 0.7 else C.FOREST)
                    ctk.CTkLabel(row, text=f"{ms*100:.0f}%", font=(FONT_MONO, 10),
                                 text_color=col, width=44, anchor="e").pack(side="left")
                else:
                    ctk.CTkLabel(row, text="no evidence yet", font=(FONT_BODY, 10, "italic"),
                                 text_color=C.INK_DIM, width=110, anchor="e").pack(side="left")
                tag = ""
                try:
                    b_ = upstream_bottleneck(conn, sid_)
                    if b_:
                        tag = "rests on " + b_["label"][:26]
                except Exception:
                    pass
                if sid_ in live_beliefs:
                    st_ = live_beliefs[sid_]["state"].replace("_", " ")
                    tag = (tag + "  \u00b7  " if tag else "") + f"belief: {st_}"
                if tag:
                    ctk.CTkLabel(row, text=tag, font=(FONT_BODY, 9),
                                 text_color=C.INK_DIM, anchor="w").pack(
                                     side="left", padx=(8, 0))
                for tgt in (sl, getattr(sl, "_label", None)):
                    if tgt is None:
                        continue
                    try:
                        tgt.bind("<Button-1>",
                                 lambda _e, s_=sid_: show_skill_note(conn, s_, app))
                        tgt.configure(cursor="hand2")
                    except Exception:
                        pass
            n_hidden_unmeasured = len(unmeasured) - sum(1 for _s, _m, n_ in shown if not n_)
            if n_hidden_unmeasured > 0:
                ctk.CTkLabel(inner, text=f"{n_hidden_unmeasured} more sub-skill"
                             f"{'s' if n_hidden_unmeasured != 1 else ''} not yet assessed.",
                             font=(FONT_BODY, 10, "italic"), text_color=C.INK_DIM,
                             anchor="w").pack(anchor="w", pady=(2, 0))

            # what the engine would do next about this topic
            try:
                cut = next_uncertainty_cut(conn)
            except Exception:
                cut = None
            if cut and cut.get("topic") == tid:
                ctk.CTkLabel(inner, text="What the engine would do next here",
                             font=(FONT_BODY, 11, "bold"), text_color=C.BRASS_DARK,
                             anchor="w").pack(anchor="w", pady=(10, 2))
                cl = ctk.CTkLabel(inner, text=cut.get("why", ""), font=(FONT_BODY, 11),
                                  text_color=C.INK, anchor="w", justify="left",
                                  wraplength=640)
                cl.pack(anchor="w")

        if m["recent"]:
            ctk.CTkLabel(inner, text="The evidence behind this",
                         font=(FONT_BODY, 11, "bold"), text_color=C.INK,
                         anchor="w").pack(anchor="w", pady=(10, 4))
            for r in m["recent"][:6]:
                row = ctk.CTkFrame(inner, fg_color="transparent", height=0)
                row.pack(fill="x", pady=1)
                ctk.CTkLabel(row, text=("\u2713" if r["correct"] else "\u2717"),
                             font=(FONT_BODY, 12, "bold"), width=18,
                             text_color=(C.FOREST if r["correct"] else C.INK_DIM),
                             anchor="w").pack(side="left")
                lb = ctk.CTkLabel(row, text=r["text"], font=(FONT_BODY, 11),
                                  text_color=C.INK_DIM, anchor="w", justify="left")
                lb.pack(side="left", fill="x", expand=True)
                if r["hinted"]:
                    ctk.CTkLabel(row, text="hinted", font=(FONT_BODY, 9),
                                 text_color=C.BRASS_DARK, anchor="e").pack(side="right")

        # ---- per-skill breakdown where one exists ----
        if m["skills"]:
            ctk.CTkLabel(inner, text="Broken down by sub-skill",
                         font=(FONT_BODY, 11, "bold"), text_color=C.INK,
                         anchor="w").pack(anchor="w", pady=(12, 4))
            for sk in m["skills"][:8]:
                row = ctk.CTkFrame(inner, fg_color="transparent", height=0)
                row.pack(fill="x", pady=2)
                ctk.CTkLabel(row, text=sk["label"][:44], font=(FONT_BODY, 11),
                             text_color=C.INK, width=250, anchor="w").pack(side="left")
                track = ctk.CTkFrame(row, fg_color=C.PAPER_LINE, height=8,
                                     corner_radius=4)
                track.pack(side="left", fill="x", expand=True, padx=8)
                track.pack_propagate(False)
                if sk.get("n", 1) == 0:
                    # A prior is not a measurement: no bar, and say so,
                    # rather than a 50% bar indistinguishable from a skill
                    # actually measured at 50%.
                    ctk.CTkLabel(row, text="no evidence yet",
                                 font=(FONT_BODY, 10, "italic"), text_color=C.INK_DIM,
                                 width=100, anchor="e").pack(side="left")
                    continue
                col = (C.FOREST if sk["mastery"] >= 0.6 else
                       C.BRASS if sk["mastery"] >= 0.35 else C.INK_DIM)
                ctk.CTkFrame(track, fg_color=col, height=8, corner_radius=4,
                             width=max(3, int(sk["mastery"] * 220))).place(x=0, y=0)
                ctk.CTkLabel(row, text=f"{sk['mastery']*100:.0f}%",
                             font=(FONT_MONO, 10), text_color=C.INK_DIM,
                             width=40, anchor="e").pack(side="left")

        # ---- negotiation ----
        ctk.CTkLabel(inner, text="Disagree with this?", font=(FONT_BODY, 11, "bold"),
                     text_color=C.INK, anchor="w").pack(anchor="w", pady=(14, 2))
        note = ctk.CTkLabel(
            inner,
            text=("Challenging a belief does not change it \u2014 it schedules a short, "
                  "targeted test whose questions sit right at the disputed level, and the "
                  "result settles it. Simply asserting mastery would defeat the point: "
                  "self-assessment is exactly the signal this app measures rather than trusts."),
            font=(FONT_BODY, 10), text_color=C.INK_DIM, anchor="w", justify="left")
        note.pack(anchor="w", fill="x", pady=(0, 8))
        bind_autowrap(note, wrap, padding=90)

        btnrow = ctk.CTkFrame(inner, fg_color="transparent", height=0)
        btnrow.pack(anchor="w")

        def challenge(claim_txt):
            register_challenge(conn, tid, claim_txt)
            probe = challenge_probe_items(conn, tid)
            if not probe:
                app.toast("No suitable probe items for this topic.", kind="warn")
                return
            ch = open_challenges(conn)
            cid = ch[0]["id"] if ch else None

            def on_finish(summary):
                if summary is None:
                    # Probe abandoned: no evidence, no verdict, but the
                    # challenge must not stay open forever.
                    _close_abandoned_challenge(cid)
                    return
                correct = summary.get("correct", 0) if isinstance(summary, dict) else 0
                total = summary.get("total", len(probe)) if isinstance(summary, dict) else len(probe)
                verdict = resolve_challenge(conn, cid, correct, total)
                msg = {"learner_right": "You were right \u2014 the model was underrating you.",
                       "model_right": "The probe supported the model's estimate.",
                       "inconclusive": "Too close to call from this many questions."}.get(
                           verdict, "Challenge recorded.")
                app.toast(f"{correct}/{total}. {msg}",
                          kind=("good" if verdict == "learner_right" else "info"))
                app.show_view("learnermodel")

            # Its own record_mode: a probe adjudicates a belief, so every
            # answer must land as ordinary calm evidence -- under "quiz",
            # unseen skills were sanctioned as pretest guesses and most of
            # the probe never reached the model.
            QuestionSession(app, parent, probe, "challenge",
                            f"Challenge \u2014 {TOPICS[tid]['short']}",
                            f"{len(probe)} questions at the disputed level. "
                            "This settles the disagreement with evidence.",
                            allow_hints=False, collect_diagnostics=True,
                            on_finish=on_finish)

        ghost_button(btnrow, "I know this better than shown",
                     lambda: challenge("underrated")).pack(side="left", padx=(0, 8))
        ghost_button(btnrow, "I know this less well than shown",
                     lambda: challenge("overrated")).pack(side="left")

        past = _safe_query(conn, "SELECT * FROM model_challenges WHERE topic_id=? "
                                 "AND resolved=1 ORDER BY id DESC LIMIT 3", (tid,))
        if past:
            ctk.CTkLabel(inner, text="Past challenges", font=(FONT_BODY, 11, "bold"),
                         text_color=C.INK, anchor="w").pack(anchor="w", pady=(14, 2))
            for r in past:
                ctk.CTkLabel(
                    inner,
                    text=(f"  claimed {r['claim']} \u2192 probe {r['probe_correct']}/"
                          f"{r['probe_total']} \u2192 {r['verdict'].replace('_',' ')}"),
                    font=(FONT_BODY, 10), text_color=C.INK_DIM,
                    anchor="w").pack(anchor="w")

    # ---- the opt-in analytical view (directive I's one exception) --------
    # Folded shut by default and opened by an explicit press, so the numbers
    # are available to the learner who wants them without becoming anyone's
    # default experience.
    def open_analytical():
        win = ctk.CTkToplevel()
        win.title("The numbers behind this")
        win.geometry("820x700")
        win.configure(fg_color=C.PAPER)
        try:
            win.attributes("-topmost", True)
            win.after(200, lambda: win.attributes("-topmost", False))
        except Exception:
            pass
        sc = ctk.CTkScrollableFrame(win, fg_color="transparent")
        sc.pack(fill="both", expand=True, padx=26, pady=18)
        ctk.CTkLabel(sc, text="The numbers behind this", font=(FONT_DISPLAY, 19, "bold"),
                     text_color=C.INK, anchor="w").pack(anchor="w")
        ctk.CTkLabel(sc,
                     text=("Internal model quantities, not advice. These are what the app's "
                           "plain-words state is derived FROM — a single number here is "
                           "never a verdict about you, and nothing in the app routes you here."),
                     font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w",
                     justify="left", wraplength=740).pack(anchor="w", pady=(4, 10))
        try:
            sections = learner_state_analytical(conn)
        except Exception as e:
            _audit(conn, "analytical_view_failed", f"{type(e).__name__}: {e}")
            sections = []
        if not sections:
            ctk.CTkLabel(sc, text="Nothing estimated yet — answer some questions first.",
                         font=(FONT_BODY, 12), text_color=C.INK_DIM, anchor="w").pack(anchor="w")
        for title, rows in sections:
            ctk.CTkLabel(sc, text=title, font=(FONT_BODY, 12, "bold"),
                         text_color=C.INK, anchor="w").pack(anchor="w", pady=(12, 3))
            for label, value in rows:
                ctk.CTkLabel(sc, text=f"  {label}: {value}", font=(FONT_MONO, 10),
                             text_color=C.INK_DIM, anchor="w").pack(anchor="w")

    anal = ctk.CTkFrame(wrap, fg_color="transparent")
    anal.pack(fill="x", pady=(14, 0))
    ghost_button(anal, "Show the numbers behind this", open_analytical, width=210).pack(anchor="w")

    render_detail()
    draw()

    def cleanup():
        if state.get("job"):
            try:
                app.after_cancel(state["job"])
            except Exception:
                pass
    wrap.bind("<Destroy>", lambda e: cleanup())


def view_improvement(app, parent):
    """IMPROVEMENT REVIEW.

    The governance plane existed but was engine-only: you could not see what
    was promoted, why, or roll it back without a Python console. A reversible
    system whose reversal control is invisible is not, in practice,
    reversible.

    Four controls, per the blueprint: inspect the diff, run the gate, promote
    what passes, roll back. Promotion is never automatic here -- the cycle
    proposes and the gate judges, but a human presses the button."""
    conn = app.conn
    init_governance_schema(conn)
    init_expert_schema(conn)

    scroll = ctk.CTkScrollableFrame(parent, fg_color="transparent")
    scroll.pack(fill="both", expand=True, padx=30, pady=(20, 10))

    section_title(scroll, "Improvement Review",
                  "What the system has proposed about itself, whether it passed "
                  "the sealed gate, and how to undo it.").pack(anchor="w", pady=(0, 14))

    st = governance_status(conn)

    # ---- what is live right now ----
    c = card(scroll)
    c.pack(fill="x", pady=(0, 12))
    inner = ctk.CTkFrame(c, fg_color="transparent")
    inner.pack(fill="x", padx=18, pady=14)
    ctk.CTkLabel(inner, text="Currently active", font=(FONT_DISPLAY, 14, "bold"),
                 text_color=C.INK, anchor="w").pack(anchor="w")
    if st["active_release"] is None:
        ctk.CTkLabel(inner, text="No release active \u2014 the app is running on its "
                                 "shipped defaults.",
                     font=(FONT_BODY, 12), text_color=C.INK_DIM,
                     anchor="w").pack(anchor="w", pady=(4, 0))
    else:
        ctk.CTkLabel(inner, text=f"Release #{st['active_release']}",
                     font=(FONT_BODY, 12, "bold"), text_color=C.FOREST,
                     anchor="w").pack(anchor="w", pady=(4, 2))
        for kind, rev in st["members"]:
            ctk.CTkLabel(inner, text=f"   {kind}  \u2190  revision {rev}",
                         font=(FONT_MONO, 11), text_color=C.INK_DIM,
                         anchor="w").pack(anchor="w")
    ctk.CTkLabel(inner,
                 text=f"{st['n_sealed']} observations are sealed and never shown to the "
                      "proposer \u2014 they exist only to judge its work.",
                 font=(FONT_BODY, 10), text_color=C.INK_DIM,
                 anchor="w").pack(anchor="w", pady=(8, 0))

    try:
        _stg = release_stage(conn)
        if _stg.get("stage") not in (None, "none"):
            scol = {"full": C.FOREST, "canary": C.BRASS_DARK}.get(_stg["stage"], C.STAMP)
            ctk.CTkLabel(inner,
                         text=(f"Stage: {_stg['stage']} \u2014 governs "
                               f"{_stg.get('share', 0)*100:.0f}% of selections"
                               + (f"  ({_stg.get('label')})" if _stg.get("label") else "")),
                         font=(FONT_BODY, 11, "bold"), text_color=scol,
                         anchor="w").pack(anchor="w", pady=(6, 0))
            if _stg.get("rationale"):
                ctk.CTkLabel(inner, text="   " + _stg["rationale"],
                             font=(FONT_BODY, 10), text_color=C.INK_DIM,
                             anchor="w").pack(anchor="w")
            if _stg["stage"] == "canary":
                # What the canary is being watched WITH: the same running
                # evidence the gate promoted it on, now fed by every sealed
                # answer given while it governs.
                _prog = canary_progress(conn, _stg.get("release_id"))
                _ev = ""
                if _prog.get("log_wealth") is not None:
                    _e = math.exp(min(700, _prog["log_wealth"]))
                    _ev = (f"; evidence for it {_e:.1f}x (needs {1 / SEQ_ALPHA:.0f}x), "
                           f"lower bound on its gain {_prog['lcb']:+.4f}")
                    if _prog.get("seq_verdict") == "worse":
                        _ev += " — predicts worse; rolls back on the next governed read"
                ctk.CTkLabel(inner,
                             text=(f"   Watched: governed {_prog['governed']} of "
                                   f"{CANARY_MIN_DECISIONS} decisions needed" + _ev),
                             font=(FONT_BODY, 10), text_color=C.INK_DIM,
                             anchor="w", justify="left", wraplength=640).pack(anchor="w")
    except Exception:
        pass

    rw_ok, rw_n = routing_weights_active(conn)
    ctk.CTkLabel(inner,
                 text=("Routing: rules-first. Learned weights "
                       + (f"ACTIVE ({rw_n} outcomes)" if rw_ok
                          else f"not yet applied \u2014 {rw_n}/{ROUTING_LEARNED_MIN_OBS} "
                               "outcomes recorded")),
                 font=(FONT_BODY, 10), text_color=(C.FOREST if rw_ok else C.BRASS_DARK),
                 anchor="w").pack(anchor="w", pady=(2, 0))

    # ---- the sample-size ladder ----
    # The author-facing schedule. Not an apology for what is missing: every
    # capability states the quantity that would identify it, where the data
    # stands against that quantity, and what the next rung unlocks. What the
    # rungs have in common above n=1 is visible without anyone saying it.
    lad = card(scroll)
    lad.pack(fill="x", pady=(0, 12))
    ladi = ctk.CTkFrame(lad, fg_color="transparent")
    ladi.pack(fill="x", padx=18, pady=14)
    ctk.CTkLabel(ladi, text="Sample-size ladder", font=(FONT_DISPLAY, 14, "bold"),
                 text_color=C.INK, anchor="w").pack(anchor="w")
    try:
        rep = capability_report(conn)
    except Exception as e:
        rep = None
        ctk.CTkLabel(ladi, text=f"Ladder unavailable: {type(e).__name__}: {e}",
                     font=(FONT_BODY, 11), text_color=C.STAMP,
                     anchor="w").pack(anchor="w", pady=(4, 0))
    if rep is not None:
        cnt, tr = rep["counts"], rep["trajectories"]
        ctk.CTkLabel(ladi,
                     text=(f"{cnt['learners']} learner · "
                           f"{cnt['measurement_rows']} measured responses · "
                           f"{cnt['distinct_items']} distinct items · "
                           f"{cnt['paired_occasions']} paired occasions · "
                           f"{tr['trajectories']} trajector"
                           f"{'y' if tr['trajectories'] == 1 else 'ies'} "
                           f"({tr['occasions']} occasion"
                           f"{'' if tr['occasions'] == 1 else 's'}, "
                           f"{tr['closed']} with an after-state)"),
                     font=(FONT_MONO, 10), text_color=C.INK_DIM,
                     anchor="w").pack(anchor="w", pady=(4, 2))
        gl = ctk.CTkLabel(ladi, text=tr["grain"], font=(FONT_BODY, 10),
                          text_color=C.INK_DIM, anchor="w", justify="left")
        gl.pack(anchor="w", fill="x", pady=(0, 8))
        bind_autowrap(gl, scroll, padding=90)
        shown_rung = None
        for g in rep["capabilities"]:
            if g["rung"] != shown_rung:
                shown_rung = g["rung"]
                ctk.CTkLabel(ladi, text=shown_rung, font=(FONT_BODY, 11, "bold"),
                             text_color=C.BRASS_DARK,
                             anchor="w").pack(anchor="w", pady=(8, 2))
            if g["available"] is None:
                mark, col = "·", C.INK_DIM
                stands = f"per item, {g['needed']} {g['quantity_label']}"
            elif g["available"]:
                mark, col = "✓", C.FOREST
                stands = f"{g['have']}/{g['needed']} {g['quantity_label']}"
            else:
                mark, col = "—", C.INK_DIM
                stands = (f"{g['have']}/{g['needed']} {g['quantity_label']} "
                          f"· {g['distance']} short")
            ctk.CTkLabel(ladi, text=f"{mark}  {g['label']}  —  {stands}",
                         font=(FONT_BODY, 11, "bold"), text_color=col,
                         anchor="w").pack(anchor="w")
            for text in (g["why"], "Unlocks: " + g["unlocks"],
                         ("Satisfied by: " + g["satisfied_by"]
                          if g["available"] is False and g["satisfied_by"] else "")):
                if not text:
                    continue
                sub = ctk.CTkLabel(ladi, text="      " + text, font=(FONT_BODY, 10),
                                   text_color=C.INK_DIM, anchor="w", justify="left")
                sub.pack(anchor="w", fill="x")
                bind_autowrap(sub, scroll, padding=110)

    # ---- run the cycle ----
    runner = card(scroll)
    runner.pack(fill="x", pady=(0, 12))
    ri = ctk.CTkFrame(runner, fg_color="transparent")
    ri.pack(fill="x", padx=18, pady=14)
    ctk.CTkLabel(ri, text="Run an improvement review", font=(FONT_DISPLAY, 14, "bold"),
                 text_color=C.INK, anchor="w").pack(anchor="w")
    note = ctk.CTkLabel(
        ri,
        text=("Proposes policy changes from the visible half of your history, then "
              "scores each candidate against the sealed half it has never seen. "
              "Candidates that do not predict your answers better are rejected. "
              "Nothing is applied until you promote it."),
        font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w", justify="left")
    note.pack(anchor="w", fill="x", pady=(4, 10))
    bind_autowrap(note, scroll, padding=90)

    out_holder = ctk.CTkFrame(ri, fg_color="transparent", height=0)
    out_holder.pack(fill="x")

    def run_review():
        run_btn.configure(state="disabled", text="Reviewing\u2026")
        holder = {}

        def worker():
            wconn = None
            try:
                wconn = db_connect()
                # activate=False: the GATE decides pass/fail, a PERSON decides
                # promotion. Separating those is the whole point.
                # The STAGED cycle, not the flat one. run_improvement_cycle
                # promotes straight to full release; run_full_improvement_cycle
                # assigns an evidence rung, requires the shadow trial, and
                # limits blast radius accordingly. Calling the flat version
                # here meant rungs and canary staging existed but governed
                # nothing.
                holder["res"] = run_full_improvement_cycle(wconn, activate=False)
                holder["routing"] = run_routing_improvement(wconn, activate=False)
            except Exception as e:
                holder["err"] = f"{type(e).__name__}: {e}"
            finally:
                if wconn is not None:
                    try:
                        wconn.close()
                    except Exception:
                        pass

        import threading
        threading.Thread(target=worker, daemon=True).start()

        def poll():
            # Every widget touched here may have been destroyed while the
            # worker ran -- navigating away, or any rebuild of this view,
            # invalidates them. Without these guards the callback raises
            # TclError and the results are computed but never shown, which
            # is exactly what happened: the rungs were being written to the
            # decision log while the panel stayed blank.
            if not out_holder.winfo_exists() or not run_btn.winfo_exists():
                return
            if "res" not in holder and "err" not in holder:
                app.after(150, poll)
                return
            try:
                run_btn.configure(state="normal", text="Run improvement review")
                for w in out_holder.winfo_children():
                    w.destroy()
            except Exception:
                return
            if "err" in holder:
                ctk.CTkLabel(out_holder, text="Review failed: " + holder["err"],
                             font=(FONT_BODY, 11), text_color=C.STAMP,
                             anchor="w").pack(anchor="w")
                return
            res = holder["res"]
            promotable = {}

            def permission_line(kind, rung):
                """What the rung PERMITS, said in the same place the rung is
                named. A strength with no consequence attached is a label,
                and the reader is entitled to see the consequence."""
                perms = (rung or {}).get("permissions") or {}
                if not perms:
                    return
                cls = POLICY_DECISION_CLASS.get(kind, "prediction")
                may = (f"may govern {cls} decisions on up to "
                       f"{perms['max_share'] * 100:.0f}% of reads"
                       if cls in perms.get("governs", ())
                       else f"may NOT govern {cls} decisions at this rung")
                if perms.get("to_rise"):
                    may += f"; to rise: {perms['to_rise']}"
                if len(may) > 118:
                    may = may[:118].rsplit(" ", 1)[0] + " …"
                ctk.CTkLabel(out_holder, text="    " + may,
                             font=(FONT_BODY, 9), text_color=C.INK_DIM,
                             anchor="w").pack(anchor="w")

            ctk.CTkLabel(out_holder,
                         text=f"Proposed from {res.get('n_visible')} visible observations:",
                         font=(FONT_BODY, 11, "bold"), text_color=C.INK,
                         anchor="w").pack(anchor="w", pady=(6, 4))
            for kind, r in res["results"].items():
                verdict = r["verdict"]
                col = {"promote": C.FOREST, "reject": C.STAMP}.get(verdict, C.BRASS_DARK)
                row = ctk.CTkFrame(out_holder, fg_color="transparent", height=0)
                row.pack(fill="x", pady=2)
                ctk.CTkLabel(row, text=f"{kind}", font=(FONT_BODY, 11, "bold"),
                             text_color=C.INK, width=170, anchor="w").pack(side="left")
                ctk.CTkLabel(row, text=verdict.upper(), font=(FONT_BODY, 11, "bold"),
                             text_color=col, width=90, anchor="w").pack(side="left")
                rung = r.get("rung") or {}
                if rung:
                    if verdict == "abstain":
                        rlabel, rcol = "not yet judged", C.INK_DIM
                    else:
                        rlabel = rung.get("label", "")
                        rcol = {0: C.STAMP, 1: C.BRASS_DARK}.get(rung.get("rung"),
                                                                 C.FOREST)
                    ctk.CTkLabel(row, text=rlabel,
                                 font=(FONT_BODY, 10, "bold"), text_color=rcol,
                                 width=130, anchor="w").pack(side="left")
                detail = r.get("reason") or rung.get("why", "")
                ctk.CTkLabel(row, text=detail[:78],
                             font=(FONT_BODY, 10),
                             text_color=C.INK_DIM, anchor="w").pack(side="left")
                if verdict == "promote":
                    permission_line(kind, rung)
                    promotable[kind] = r["revision_id"]
            rt = holder.get("routing") or {}
            if rt:
                ctk.CTkLabel(out_holder,
                             text=f"routing_policy: {rt.get('verdict','?').upper()} "
                                  f"\u2014 {rt.get('reason','')}",
                             font=(FONT_BODY, 10), text_color=C.INK_DIM,
                             anchor="w").pack(anchor="w", pady=(4, 0))
                if rt.get("verdict") == "promote" and rt.get("revision_id"):
                    permission_line("routing_policy", rt.get("rung"))
                    promotable["routing_policy"] = rt["revision_id"]

            if promotable:
                def promote():
                    # create_release carries the live members forward, so
                    # promoting this round's passes keeps every earlier
                    # promotion live instead of silently reverting it.
                    rid = create_release(conn, promotable, note="reviewed and promoted")
                    # Stage by the WEAKEST member's rung: a release is only as
                    # trustworthy as its least-evidenced part. The router's
                    # rung counts too -- a routing-only promotion used to
                    # inherit the "4" default and ship as Replicated/full.
                    worst = 4
                    for _k, _r in res["results"].items():
                        if _r["verdict"] == "promote":
                            worst = min(worst, (_r.get("rung") or {}).get("rung", 0))
                    if "routing_policy" in promotable:
                        worst = min(worst, (rt.get("rung") or {}).get("rung", 1))
                    stg = stage_release(conn, rid, rung_record(
                        worst, why="weakest member's rung governs"))
                    # A shadow-staged release is recorded, never activated.
                    if stg["stage"] != "shadow":
                        activate_release(conn, rid, reason="human promotion after gate")
                    app.toast(f"Release #{rid}: {stg['stage']} "
                              f"({stg['share']*100:.0f}% of selections) \u2014 "
                              f"{stg['label']}.", kind="good")
                    app.show_view("improvement")
                primary_button(out_holder,
                               f"Promote {len(promotable)} passing change(s)",
                               promote).pack(anchor="w", pady=(12, 0))
            else:
                verdicts = {r["verdict"] for r in res["results"].values()}
                if verdicts and verdicts <= {"abstain"}:
                    msg = ("Nothing could be JUDGED yet. The sealed half of your "
                           "history is still too small to tell a real improvement "
                           "from noise, so the gate declined to rule rather than "
                           "guess. Answer more questions and run this again.")
                elif "reject" in verdicts:
                    msg = ("Nothing passed. Some candidates were judged and lost to "
                           "the policy already running, which is a normal outcome "
                           "rather than a failure.")
                else:
                    msg = ("Nothing to promote from this run.")
                ml = ctk.CTkLabel(out_holder, text=msg, font=(FONT_BODY, 11),
                                  text_color=C.INK_DIM, anchor="w", justify="left")
                ml.pack(anchor="w", fill="x", pady=(10, 0))
                bind_autowrap(ml, scroll, padding=100)
            # The review just wrote decisions; the history below the
            # results must show them, not the rows from before the click.
            render_history()

        app.after(150, poll)

    run_btn = primary_button(ri, "Run improvement review", run_review)
    run_btn.pack(anchor="w")

    # ---- decision history ----
    hist_holder = ctk.CTkFrame(scroll, fg_color="transparent", height=0)
    hist_holder.pack(fill="x")

    def render_history():
        if not hist_holder.winfo_exists():
            return
        for w in hist_holder.winfo_children():
            w.destroy()
        decisions = governance_status(conn)["decisions"]
        if not decisions:
            return
        hc = card(hist_holder)
        hc.pack(fill="x", pady=(0, 12))
        hi = ctk.CTkFrame(hc, fg_color="transparent")
        hi.pack(fill="x", padx=18, pady=14)
        ctk.CTkLabel(hi, text="Decision history", font=(FONT_DISPLAY, 14, "bold"),
                     text_color=C.INK, anchor="w").pack(anchor="w", pady=(0, 6))
        for d in decisions:
            col = {"promote": C.FOREST, "reject": C.STAMP}.get(d["verdict"], C.BRASS_DARK)
            ctk.CTkLabel(hi,
                         text=(f"{d['decided_at'][:16]}  {d['kind']}  "
                               f"rev{d['revision_id']}  \u2192  {d['verdict']}  "
                               f"({d['detail'] or ''})")[:118],
                         font=(FONT_MONO, 10), text_color=col,
                         anchor="w").pack(anchor="w")
    render_history()

    # ---- rollback ----
    rc = card(scroll)
    rc.pack(fill="x", pady=(0, 12))
    rci = ctk.CTkFrame(rc, fg_color="transparent")
    rci.pack(fill="x", padx=18, pady=14)
    ctk.CTkLabel(rci, text="Rollback", font=(FONT_DISPLAY, 14, "bold"),
                 text_color=C.INK, anchor="w").pack(anchor="w")
    ctk.CTkLabel(rci,
                 text="Reverting is a single pointer change. Nothing is deleted, so any "
                      "earlier release can be restored at any time.",
                 font=(FONT_BODY, 11), text_color=C.INK_DIM,
                 anchor="w").pack(anchor="w", pady=(4, 8))
    if st["active_release"] is not None:
        def _quick_rollback():
            prev = rollback_to_previous(conn)
            if prev:
                app.toast(f"Rolled back to release #{prev}.", kind="good")
            elif prev == 0:
                app.toast("Rolled back to shipped defaults.", kind="good")
            else:
                app.toast("No earlier release to roll back to.", kind="info")
            app.show_view("improvement")
        ghost_button(rci, "Roll back one release",
                     _quick_rollback).pack(anchor="w", pady=(0, 8))

        def _deactivate():
            was = deactivate_release(conn, reason="manual return to shipped defaults")
            app.toast(f"Release #{was} deactivated \u2014 running on shipped defaults.",
                      kind="good")
            app.show_view("improvement")
        ghost_button(rci, "Deactivate (shipped defaults)",
                     _deactivate).pack(anchor="w", pady=(0, 8))
    if st["releases"]:
        for r in st["releases"][:5]:
            row = ctk.CTkFrame(rci, fg_color="transparent", height=0)
            row.pack(fill="x", pady=2)
            live = (r["release_id"] == st["active_release"])
            ctk.CTkLabel(row,
                         text=f"Release #{r['release_id']}  \u00b7  {r['created_at'][:16]}"
                              f"  \u00b7  {r['n_members']} policies"
                              + ("   \u2190 live" if live else ""),
                         font=(FONT_BODY, 11),
                         text_color=(C.FOREST if live else C.INK),
                         anchor="w").pack(side="left")
            if not live:
                ghost_button(row, "Restore",
                             lambda rid=r["release_id"]: (
                                 activate_release(conn, rid, reason="manual restore"),
                                 app.toast(f"Restored release #{rid}.", kind="good"),
                                 app.show_view("improvement"))).pack(side="right")
    else:
        ctk.CTkLabel(rci, text="No releases yet.", font=(FONT_BODY, 11),
                     text_color=C.INK_DIM, anchor="w").pack(anchor="w")

    # ---- evaluation lab: behaviour, not just a scalar ----
    lc = card(scroll)
    lc.pack(fill="x", pady=(0, 12))
    li = ctk.CTkFrame(lc, fg_color="transparent")
    li.pack(fill="x", padx=18, pady=14)
    ctk.CTkLabel(li, text="Evaluation Lab", font=(FONT_DISPLAY, 14, "bold"),
                 text_color=C.INK, anchor="w").pack(anchor="w")
    lnote = ctk.CTkLabel(
        li,
        text=("A shadow trial replays a candidate against your real history and reports "
              "what it WOULD have served \u2014 without applying it. Two policies can "
              "score identically on prediction and still behave completely differently, "
              "which a single number hides."),
        font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w", justify="left")
    lnote.pack(anchor="w", fill="x", pady=(4, 8))
    bind_autowrap(lnote, scroll, padding=90)
    lab_out = ctk.CTkFrame(li, fg_color="transparent", height=0)
    lab_out.pack(fill="x")

    def run_lab():
        lab_btn.configure(state="disabled", text="Replaying\u2026")
        h = {}

        def w():
            wc = None
            try:
                wc = db_connect()
                h["r"] = evaluation_lab(wc, "difficulty_priors")
            except Exception as e:
                h["e"] = f"{type(e).__name__}: {e}"
            finally:
                if wc is not None:
                    try:
                        wc.close()
                    except Exception:
                        pass

        import threading
        threading.Thread(target=w, daemon=True).start()

        def poll():
            if not lab_out.winfo_exists() or not lab_btn.winfo_exists():
                return
            if "r" not in h and "e" not in h:
                app.after(150, poll); return
            lab_btn.configure(state="normal", text="Run shadow trial")
            for x in lab_out.winfo_children():
                x.destroy()
            if "e" in h:
                ctk.CTkLabel(lab_out, text="Trial failed: " + h["e"],
                             font=(FONT_BODY, 11), text_color=C.STAMP,
                             anchor="w").pack(anchor="w"); return
            r = h["r"]; sh = r["shadow"]; gate = r["gate"]
            ctk.CTkLabel(lab_out,
                         text=f"Gate (prediction): {gate['verdict'].upper()} \u2014 "
                              f"{gate.get('reason','')}",
                         font=(FONT_BODY, 11), text_color=C.INK,
                         anchor="w").pack(anchor="w", pady=(4, 2))
            if "error" in sh:
                ctk.CTkLabel(lab_out, text="Shadow trial: " + sh["error"],
                             font=(FONT_BODY, 11), text_color=C.INK_DIM,
                             anchor="w").pack(anchor="w"); return
            col = (C.FOREST if sh["overlap"] > 0.85 else
                   C.BRASS_DARK if sh["overlap"] > 0.6 else C.STAMP)
            ctk.CTkLabel(lab_out, text=f"Shadow (behaviour): {sh['verdict']}",
                         font=(FONT_BODY, 11, "bold"), text_color=col,
                         anchor="w").pack(anchor="w")
            ctk.CTkLabel(lab_out,
                         text=(f"   overlap {sh['overlap']:.2f}  \u00b7  "
                               f"{sh['changed_items']} items would change  \u00b7  "
                               f"topics {sh['baseline_topics']} \u2192 {sh['candidate_topics']}"),
                         font=(FONT_MONO, 10), text_color=C.INK_DIM,
                         anchor="w").pack(anchor="w")
            if sh.get("topics_lost"):
                ctk.CTkLabel(lab_out,
                             text="   topics that would stop being served: "
                                  + ", ".join(TOPICS.get(t, {}).get("short", t)
                                              for t in sh["topics_lost"][:5]),
                             font=(FONT_BODY, 10), text_color=C.STAMP,
                             anchor="w").pack(anchor="w")

        app.after(150, poll)

    lab_btn = ghost_button(li, "Run shadow trial", run_lab)
    lab_btn.pack(anchor="w")

    # ---- model manager ----
    mm = model_manager_status(conn)
    mc = card(scroll)
    mc.pack(fill="x", pady=(0, 12))
    mi = ctk.CTkFrame(mc, fg_color="transparent")
    mi.pack(fill="x", padx=18, pady=14)
    ctk.CTkLabel(mi, text="Model Manager", font=(FONT_DISPLAY, 14, "bold"),
                 text_color=C.INK, anchor="w").pack(anchor="w")
    ctk.CTkLabel(mi, text=f"This machine suits the \u201c{mm['recommended_tier']}\u201d tier. "
                          "Nothing is downloaded automatically.",
                 font=(FONT_BODY, 11), text_color=C.INK_DIM,
                 anchor="w").pack(anchor="w", pady=(4, 8))
    for m in mm["models"]:
        row = ctk.CTkFrame(mi, fg_color="transparent", height=0)
        row.pack(fill="x", pady=2)
        ok = m["status"] == "supported"
        ctk.CTkLabel(row, text=("\u2713" if ok else "\u2717"),
                     font=(FONT_BODY, 12, "bold"), width=20,
                     text_color=(C.FOREST if ok else C.INK_DIM),
                     anchor="w").pack(side="left")
        ctk.CTkLabel(row, text=m["repo"], font=(FONT_MONO, 10),
                     text_color=C.INK, width=250, anchor="w").pack(side="left")
        ctk.CTkLabel(row, text=f"{m['params']:>6}  {m['disk_gb']:>5.2f} GB",
                     font=(FONT_MONO, 10), text_color=C.INK_DIM,
                     width=110, anchor="w").pack(side="left")
        ctk.CTkLabel(row, text=m["detail"][:52], font=(FONT_BODY, 10),
                     text_color=(C.INK_DIM if ok else C.BRASS_DARK),
                     anchor="w").pack(side="left")
        ctk.CTkLabel(mi, text=f"      {m['role']}", font=(FONT_BODY, 9),
                     text_color=C.INK_DIM, anchor="w").pack(anchor="w")

    # ---- exact setup commands, in the app rather than in a README ----
    def _build_setup(_parent):
        si = ctk.CTkFrame(_parent, fg_color="transparent")
        si.pack(fill="x", padx=4, pady=4)
        intro = ctk.CTkLabel(
            si,
            text=("Each tier is additive and entirely optional \u2014 the app runs "
                  "offline on the first one alone, and every model path degrades "
                  "to a working floor. Nothing is installed or downloaded "
                  "automatically."),
            font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w", justify="left")
        intro.pack(anchor="w", fill="x", pady=(0, 10))
        bind_autowrap(intro, scroll, padding=90)

        for name, size, cmds, why in INSTALL_TIERS:
            ctk.CTkLabel(si, text=f"{name}  \u00b7  {size}",
                         font=(FONT_BODY, 12, "bold"), text_color=C.INK,
                         anchor="w").pack(anchor="w", pady=(10, 2))
            wl = ctk.CTkLabel(si, text=why, font=(FONT_BODY, 10),
                              text_color=C.INK_DIM, anchor="w", justify="left")
            wl.pack(anchor="w", fill="x")
            bind_autowrap(wl, scroll, padding=100)
            for cmd in cmds:
                box = ctk.CTkFrame(si, fg_color=C.PAPER_LINE, corner_radius=4)
                box.pack(fill="x", pady=2)
                ctk.CTkLabel(box, text="  " + cmd, font=(FONT_MONO, 10),
                             text_color=C.INK, anchor="w",
                             justify="left").pack(anchor="w", fill="x", pady=4)

        ctk.CTkLabel(si, text="Pre-fetch the models", font=(FONT_BODY, 12, "bold"),
                     text_color=C.INK, anchor="w").pack(anchor="w", pady=(14, 2))
        pf = ctk.CTkLabel(
            si,
            text=("A first-use download inside a study session stalls the app for "
                  "minutes with no useful progress signal, so fetch them ahead of "
                  "time."),
            font=(FONT_BODY, 10), text_color=C.INK_DIM, anchor="w", justify="left")
        pf.pack(anchor="w", fill="x")
        bind_autowrap(pf, scroll, padding=100)
        for cmd in model_download_commands():
            box = ctk.CTkFrame(si, fg_color=C.PAPER_LINE, corner_radius=4)
            box.pack(fill="x", pady=1)
            ctk.CTkLabel(box, text="  " + cmd, font=(FONT_MONO, 10),
                         text_color=C.INK, anchor="w").pack(anchor="w", fill="x", pady=3)

        def copy_all():
            text = "\n".join(
                [c for _n, _s, cs, _w in INSTALL_TIERS for c in cs]
                + [""] + model_download_commands())
            try:
                app.clipboard_clear()
                app.clipboard_append(text)
                app.toast("Full setup copied to the clipboard.", kind="good")
            except Exception as e:
                app.toast(f"Could not copy: {e}", kind="warn")

        primary_button(si, "Copy the whole setup", copy_all).pack(anchor="w",
                                                                  pady=(14, 0))

        # ---- worker roles ----
        ctk.CTkLabel(si, text="Worker roles", font=(FONT_BODY, 12, "bold"),
                     text_color=C.INK, anchor="w").pack(anchor="w", pady=(16, 2))
        rl = ctk.CTkLabel(
            si,
            text=("Language models invent and interrogate alternatives; "
                  "deterministic systems decide what counts as evidence. The "
                  "confuser and the differentiator must be DIFFERENT models \u2014 "
                  "neither may grade its own output, which is the requirement the "
                  "candidate bank exists to enforce."),
            font=(FONT_BODY, 10), text_color=C.INK_DIM, anchor="w", justify="left")
        rl.pack(anchor="w", fill="x", pady=(0, 6))
        bind_autowrap(rl, scroll, padding=100)
        for role, (kind, key, desc) in WORKER_ROLES.items():
            rr = ctk.CTkFrame(si, fg_color="transparent", height=0)
            rr.pack(fill="x", pady=1)
            kcol = {"deterministic": C.FOREST, "model": C.BRASS_DARK}.get(kind, C.INK)
            ctk.CTkLabel(rr, text=role, font=(FONT_BODY, 11, "bold"),
                         text_color=C.INK, width=150, anchor="w").pack(side="left")
            ctk.CTkLabel(rr, text=kind, font=(FONT_BODY, 10), text_color=kcol,
                         width=95, anchor="w").pack(side="left")
            repo = MODEL_CATALOG.get(key, {}).get("repo", "\u2014") if key else "\u2014"
            ctk.CTkLabel(rr, text=repo, font=(FONT_MONO, 9),
                         text_color=C.INK_DIM, anchor="w").pack(side="left")

    def _build_behaviour_trials(box):
        """Where each trialled behaviour stands. A behaviour that cannot be
        read here is a behaviour nobody can retire, so everything that
        enters through behaviour_arm appears -- including the ones that
        have not yet been offered a single occasion."""
        any_row = False
        for name, spec in BEHAVIOUR_TRIALS.items():
            st = behaviour_trial_state(app.conn, name)
            if st is None:
                continue
            any_row = True
            c = card(box, fg_color=C.PAPER_DIM)
            c.pack(fill="x", pady=(0, 8))
            inner = ctk.CTkFrame(c, fg_color="transparent", height=0)
            inner.pack(fill="x", padx=16, pady=12)
            head = ctk.CTkFrame(inner, fg_color="transparent", height=0)
            head.pack(fill="x")
            ctk.CTkLabel(head, text=name.replace("_", " "), font=(FONT_BODY, 12, "bold"),
                         text_color=C.INK, anchor="w").pack(side="left")
            settled = behaviour_settled(app.conn, name)
            verdict = {"accumulating": "still gathering",
                       "helps": "measured better here",
                       "harms": "measured worse here — switched off",
                       "settled-unproven": "no effect either way on this much data"}.get(
                           st["verdict"], st["verdict"])
            ctk.CTkLabel(head, text=("on" if settled == "on" else
                                     "off" if settled == "off" else "50/50"),
                         font=(FONT_MONO, 11), text_color=C.BRASS_DARK).pack(side="right")
            scored = st["n_on"] + st["n_off"]
            if st["assigned"] == 0:
                body = ("Not offered yet — no occasion of the kind this "
                        "behaviour attaches to has come up.")
            elif st["pairs"] == 0:
                body = (f"{st['assigned']} occasion{'s' if st['assigned'] != 1 else ''} offered, "
                        f"{scored} scored, none paired yet. Nothing to compare until "
                        "an occasion with the behaviour meets one without it.")
            else:
                bits = [f"{st['pairs']} paired occasion{'s' if st['pairs'] != 1 else ''}"]
                if st["mean_on"] is not None and st["mean_off"] is not None:
                    bits.append(f"{st['mean_on']*100:.0f}% with, {st['mean_off']*100:.0f}% without")
                # The running bound is worth showing only once it says
                # something: at a handful of pairs an anytime-valid interval
                # spans most of the scale, and printing "-61 points" invites
                # a conclusion the data cannot support.
                if st["lcb"] is not None and st["pairs"] >= spec["floor"]:
                    bits.append(f"lower bound {st['lcb']*100:+.1f} points")
                body = " · ".join(bits) + f". {verdict.capitalize()}."
                if st["pairs"] < spec["floor"]:
                    body += (f" The bound stays hidden until {spec['floor']} pairs, "
                             "because before that it spans most of the scale.")
            bl = ctk.CTkLabel(inner, text=body, font=(FONT_BODY, 12), text_color=C.INK,
                              anchor="w", justify="left")
            bl.pack(anchor="w", fill="x", pady=(4, 0))
            bind_autowrap(bl, box, padding=90)
            ml = ctk.CTkLabel(inner, text=f"Measured on: {spec['outcome']}. {spec['basis']}",
                              font=(FONT_BODY, 11), text_color=C.INK_DIM,
                              anchor="w", justify="left")
            ml.pack(anchor="w", fill="x", pady=(4, 0))
            bind_autowrap(ml, box, padding=90)
        if not any_row:
            ctk.CTkLabel(box, text="No behaviours are under trial.",
                         font=(FONT_BODY, 12), text_color=C.INK_DIM,
                         anchor="w").pack(anchor="w")

    def _build_intervention_trials(box):
        """Where each identified contrast stands, and how the next action is
        actually being ranked. Two things belong together here: a trial is
        only legible next to the objective it is overriding, and an objective
        is only honest if it says which of its terms is measured."""
        def _wrap(parent, text, font, colour, pady=(0, 0)):
            lab = ctk.CTkLabel(parent, text=text, font=font, text_color=colour,
                               anchor="w", justify="left")
            lab.pack(anchor="w", fill="x", pady=pady)
            bind_autowrap(lab, box, padding=90)
            return lab

        for name, spec in INTERVENTION_TRIALS.items():
            st = intervention_trial_state(app.conn, name)
            status = intervention_trial_status(app.conn, name)
            if st is None:
                continue
            c = card(box, fg_color=C.PAPER_DIM)
            c.pack(fill="x", pady=(0, 8))
            inner = ctk.CTkFrame(c, fg_color="transparent", height=0)
            inner.pack(fill="x", padx=16, pady=12)
            head = ctk.CTkFrame(inner, fg_color="transparent", height=0)
            head.pack(fill="x")
            ctk.CTkLabel(head, text=name.replace("_", " "),
                         font=(FONT_BODY, 12, "bold"), text_color=C.INK,
                         anchor="w").pack(side="left")
            ctk.CTkLabel(head,
                         text=(status["settled"] or
                               f"{len(status['active_arms'])} arms running"),
                         font=(FONT_MONO, 11),
                         text_color=C.BRASS_DARK).pack(side="right")
            _wrap(inner,
                  (f"{st['assigned']} occasion{'s' if st['assigned'] != 1 else ''} "
                   f"assigned, {st['scored']} scored. Reference arm: "
                   f"{spec['reference']}. Washout "
                   f"{spec['washout_hours']:.0f}h"
                   + (", first exposures only" if spec["first_exposure_only"] else "")
                   + "."),
                  (FONT_BODY, 12), C.INK, pady=(4, 0))
            for arm, v in st["contrasts"].items():
                if v["pairs"] == 0:
                    body = (f"{arm} vs {spec['reference']}: nothing paired yet — "
                            "still gathering.")
                elif not v["bound_visible"]:
                    body = (f"{arm} vs {spec['reference']}: {v['pairs']} of "
                            f"{spec['floor']} pairs. Still gathering; no bound is "
                            "reported, because at this many pairs it would span "
                            "most of the scale.")
                else:
                    body = (f"{arm} vs {spec['reference']}: {v['pairs']} pairs, "
                            f"difference {v['mean_diff']*100:+.0f} points, "
                            f"lower bound {v['lcb']*100:+.1f} points — "
                            f"{v['verdict']}.")
                if arm in status["dropped"]:
                    body += f" Dropped from assignment: {status['dropped'][arm]}."
                _wrap(inner, "   " + body, (FONT_BODY, 11), C.INK, pady=(2, 0))
            _wrap(inner,
                  (f"Measured on: {spec['outcome']}. Randomises: "
                   + "; ".join(spec["randomises"])
                   + f". Withheld arm costs: {spec['withheld_cost']}"),
                  (FONT_BODY, 11), C.INK_DIM, pady=(4, 0))

        # ---- the objective, term by term, with its basis ----
        ctk.CTkLabel(box, text="How the next action is ranked",
                     font=(FONT_BODY, 12, "bold"), text_color=C.INK,
                     anchor="w").pack(anchor="w", pady=(14, 2))
        try:
            ranked = rank_interventions(app.conn)
        except Exception as e:
            _audit(app.conn, "objective_render_failed", f"{type(e).__name__}: {e}")
            ranked = []
        if ranked:
            lam_i = ranked[0]["lambda_info"]
            lam_c = ranked[0]["lambda_cost"]
            _wrap(box,
                  (f"score = learning gain + {lam_i:.2f} × information gain "
                   f"− {lam_c:.2f} × cost. Information about you is not "
                   "learning in you; the two are weighed, not conflated. Both "
                   "weights are governed thresholds."),
                  (FONT_BODY, 11), C.INK_DIM, pady=(0, 6))
            for r in ranked:
                rc = card(box, fg_color=C.PAPER_DIM)
                rc.pack(fill="x", pady=(0, 6))
                ri2 = ctk.CTkFrame(rc, fg_color="transparent", height=0)
                ri2.pack(fill="x", padx=16, pady=10)
                rh = ctk.CTkFrame(ri2, fg_color="transparent", height=0)
                rh.pack(fill="x")
                ctk.CTkLabel(rh, text=r["label"], font=(FONT_BODY, 12, "bold"),
                             text_color=C.INK, anchor="w").pack(side="left")
                ctk.CTkLabel(rh, text=f"{r['score']:+.3f}", font=(FONT_MONO, 11),
                             text_color=C.BRASS_DARK).pack(side="right")
                for term, value, basis in (
                        ("learning gain", f"{r['gain']:+.3f}", r["gain_basis"]),
                        ("information gain", f"{r['info']:+.3f}", r["info_basis"]),
                        ("cost", f"{r['cost']:.3f}",
                         f"{r['cost_basis']} ({r['minutes']:.0f} min, "
                         f"load {r['load']:.2f})")):
                    _wrap(ri2, f"   {term} {value} — {basis}",
                          (FONT_BODY, 10), C.INK_DIM, pady=(1, 0))

        # ---- disclosure ----
        disc = trial_disclosure(app.conn)
        dc = card(box, fg_color=C.PAPER_DIM)
        dc.pack(fill="x", pady=(12, 0))
        di = ctk.CTkFrame(dc, fg_color="transparent", height=0)
        di.pack(fill="x", padx=16, pady=12)
        ctk.CTkLabel(di, text=disc["heading"], font=(FONT_BODY, 12, "bold"),
                     text_color=C.INK, anchor="w").pack(anchor="w")
        _wrap(di, disc["body"], (FONT_BODY, 11), C.INK, pady=(4, 0))
        for t in disc["trials"]:
            _wrap(di, f"   • {t['name']} ({t['status']}) — varies "
                      f"{t['what']}. Measured on {t['outcome']}.",
                  (FONT_BODY, 10), C.INK_DIM, pady=(1, 0))
        _wrap(di,
              ("This wording is here so it is ready the day this app has a "
               "learner who is not its author. A single-learner system whose "
               "learner is its developer does not require it; a second learner "
               "does, and copy that does not exist cannot be shown."),
              (FONT_BODY, 10), C.INK_DIM, pady=(6, 0))

    lazy_section(scroll, "Intervention trials and the selection objective",
                 "Which of two defensible actions actually helps, and how the "
                 "next one is ranked.",
                 _build_intervention_trials)

    lazy_section(scroll, "Behaviour trials",
                 "Additions that change what the learner sees, and whether they earned it.",
                 _build_behaviour_trials)

    lazy_section(scroll, "Setup: libraries and models",
                 "The exact commands, and which worker each model plays.",
                 _build_setup)

    # ---- content factory ----
    def _build_factory(_parent):
        st_f = factory_status(conn)
        fi = ctk.CTkFrame(_parent, fg_color="transparent")
        fi.pack(fill="x", padx=4, pady=4)
        note = ctk.CTkLabel(
            fi,
            text=("Targets come from the distinguishability audit \u2014 places the bank "
                  "has already proven it cannot see clearly. Verification is "
                  "deterministic and runs with no model; only generation needs one, "
                  "and only template-backed maths can be generated safely without."),
            font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w", justify="left")
        note.pack(anchor="w", fill="x", pady=(0, 8))
        bind_autowrap(note, scroll, padding=90)
        for t in st_f["targets"][:6]:
            ctk.CTkLabel(fi,
                         text=f"   [{t['certificate']}] {t['kind']} in "
                              f"{TOPICS.get(t['topic'], {}).get('short', t['topic'])} "
                              f"\u2014 {t['why']}"[:104],
                         font=(FONT_BODY, 10), text_color=C.INK,
                         anchor="w").pack(anchor="w")
        out_f = ctk.CTkFrame(fi, fg_color="transparent", height=0)
        out_f.pack(fill="x", pady=(8, 0))

        def run_gen():
            for w in out_f.winfo_children():
                w.destroy()
            res = factory_with_generator(conn)
            v = res.get("verdict") or res.get("status")
            col = {"accept": C.FOREST, "reject": C.STAMP}.get(v, C.INK_DIM)
            ctk.CTkLabel(out_f, text=f"Result: {v}", font=(FONT_BODY, 11, "bold"),
                         text_color=col, anchor="w").pack(anchor="w")
            if res.get("candidate"):
                ctk.CTkLabel(out_f, text="   " + res["candidate"]["q"][:96],
                             font=(FONT_BODY, 10), text_color=C.INK,
                             anchor="w").pack(anchor="w")
                emp = res.get("empirical") or {}
                kd = res.get("knowledge") or {}
                ctk.CTkLabel(out_f,
                             text=f"   structural {res['structural']['passed']} \u00b7 "
                                  f"analytic separation {emp.get('separation')} \u00b7 "
                                  f"knowledge dependence {kd.get('status', 'unavailable')}",
                             font=(FONT_MONO, 10), text_color=C.INK_DIM,
                             anchor="w").pack(anchor="w")
            nb = res.get("note") or res.get("reason") or ""
            if nb:
                lb = ctk.CTkLabel(out_f, text="   " + nb, font=(FONT_BODY, 10),
                                  text_color=C.INK_DIM, anchor="w", justify="left")
                lb.pack(anchor="w", fill="x")
                bind_autowrap(lb, scroll, padding=100)

        ghost_button(fi, "Generate a candidate", run_gen).pack(anchor="w", pady=(8, 0))

        cc = consistency_check(conn)
        ctk.CTkLabel(fi,
                     text=("Content consistency: "
                           + ("clean" if cc["clean"] else "; ".join(cc["issues"])[:80])),
                     font=(FONT_BODY, 10, "bold"),
                     text_color=(C.FOREST if cc["clean"] else C.STAMP),
                     anchor="w").pack(anchor="w", pady=(10, 0))

    lazy_section(scroll, "Content factory",
                 "Manufacture diagnostic evidence for gaps the audit already found.",
                 _build_factory)

    # ---- candidate bank: generated content awaiting human review ----
    def _build_candidates(_parent):
        st_c = candidate_bank_status(conn)
        ci = ctk.CTkFrame(_parent, fg_color="transparent")
        ci.pack(fill="x", padx=4, pady=4)
        note = ctk.CTkLabel(
            ci,
            text=("Generated items land here, never in the live bank. Each must pass "
                  "structure, an INDEPENDENT solve that never sees the keyed answer, "
                  "and a simulated separation check \u2014 and then a human. "
                  "Generation, verification and approval are three different "
                  "authorities."),
            font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w", justify="left")
        note.pack(anchor="w", fill="x", pady=(0, 8))
        bind_autowrap(note, scroll, padding=90)
        ctk.CTkLabel(ci,
                     text=(f"{st_c['total']} candidates \u00b7 "
                           f"{st_c['awaiting_review']} awaiting review \u00b7 "
                           f"{st_c['live']} promoted"),
                     font=(FONT_BODY, 11, "bold"), text_color=C.INK,
                     anchor="w").pack(anchor="w", pady=(0, 6))

        out_c = ctk.CTkFrame(ci, fg_color="transparent", height=0)
        out_c.pack(fill="x")

        def refresh():
            for w in out_c.winfo_children():
                w.destroy()
            rows = candidates(conn, limit=8)
            if not rows:
                ctk.CTkLabel(out_c, text="No candidates yet.", font=(FONT_BODY, 11),
                             text_color=C.INK_DIM, anchor="w").pack(anchor="w")
                return
            for r in rows:
                rc = card(out_c)
                rc.pack(fill="x", pady=3)
                ri = ctk.CTkFrame(rc, fg_color="transparent")
                ri.pack(fill="x", padx=12, pady=8)
                scol = {"verified": C.FOREST, "rejected": C.STAMP,
                        "promoted": C.FOREST, "approved": C.BRASS_DARK}.get(
                            r["state"], C.INK_DIM)
                hdr = ctk.CTkFrame(ri, fg_color="transparent", height=0)
                hdr.pack(fill="x")
                ctk.CTkLabel(hdr, text=f"#{r['candidate_id']}  {r['state'].upper()}",
                             font=(FONT_BODY, 11, "bold"), text_color=scol,
                             anchor="w").pack(side="left")
                ctk.CTkLabel(hdr, text=r["generator"] or "", font=(FONT_BODY, 10),
                             text_color=C.INK_DIM, anchor="e").pack(side="right")
                sl = ctk.CTkLabel(ri, text=(r["stem"] or "")[:150],
                                  font=(FONT_BODY, 11), text_color=C.INK,
                                  anchor="w", justify="left")
                sl.pack(anchor="w", fill="x", pady=(2, 0))
                bind_autowrap(sl, scroll, padding=110)
                if r["verify_notes"]:
                    nl = ctk.CTkLabel(ri, text=r["verify_notes"][:160],
                                      font=(FONT_BODY, 9), text_color=C.INK_DIM,
                                      anchor="w", justify="left")
                    nl.pack(anchor="w", fill="x")
                    bind_autowrap(nl, scroll, padding=110)
                if r["state"] in ("verified", "approved"):
                    brow2 = ctk.CTkFrame(ri, fg_color="transparent", height=0)
                    brow2.pack(anchor="w", pady=(6, 0))
                    def _approve(cid=r["candidate_id"]):
                        # Promotion registers the asset the candidate was
                        # authored to be, so the skill's completeness moves.
                        aid = promote_candidate_as_asset(conn, cid, notes="human approved")
                        if aid:
                            app.toast(f"Candidate #{cid} promoted to the live bank "
                                      f"and registered as asset #{aid}.", kind="good")
                        else:
                            app.toast(f"Candidate #{cid} could not be promoted from its "
                                      "current state.", kind="warn")
                        refresh()
                    def _reject(cid=r["candidate_id"]):
                        set_candidate_state(conn, cid, "rejected", "human rejected")
                        app.toast(f"Candidate #{cid} rejected.", kind="info")
                        refresh()
                    primary_button(brow2, "Promote", _approve).pack(side="left", padx=(0, 8))
                    ghost_button(brow2, "Reject", _reject).pack(side="left")

        # Local generation status, stated plainly. "The generator is off"
        # previously meant "no API key" even on a machine that could run a
        # model locally.
        try:
            _lg = local_generation_status()
        except Exception:
            _lg = {"ready": False, "reason": "local backend unavailable"}
        lcol = C.FOREST if _lg.get("ready") else C.BRASS_DARK
        ctk.CTkLabel(ci,
                     text=("Local generation: "
                           + (f"ready \u2014 {_lg.get('generator','')} writes, "
                              f"{_lg.get('solver','')} solves blind"
                              if _lg.get("ready") else "not available")),
                     font=(FONT_BODY, 11, "bold"), text_color=lcol,
                     anchor="w").pack(anchor="w", pady=(6, 1))
        if not _lg.get("ready"):
            rl = ctk.CTkLabel(ci, text="   " + (_lg.get("reason") or ""),
                              font=(FONT_BODY, 10), text_color=C.INK_DIM,
                              anchor="w", justify="left")
            rl.pack(anchor="w", fill="x", pady=(0, 6))
            bind_autowrap(rl, scroll, padding=100)

        def _gen_work(wc):
            """The generation itself, on a worker connection. The planned
            pipeline first, when the completeness audit has an asset to
            plan for (it targets a named gap and registers the asset on
            promotion); otherwise the audit-driven path, local first and
            the API only when the local path produced nothing."""
            if authoring_plan(wc, 1, for_generator=True):
                res = generate_and_verify_planned(wc, allow_paid=True)
                if res.get("status") in ("generated", "human_required"):
                    return res
            if _lg.get("ready"):
                res = generate_and_verify_local(wc)
                if res.get("status") in ("generated", "refused", "load_failed"):
                    return res
            return generate_and_verify(wc, allow_paid=True)

        def _gen_report(res):
            st = res.get("status")
            if st == "generated" and "kept" in res:
                # The planned pipeline: several alternatives, each verified.
                kept = res.get("kept") or []
                disc = res.get("discarded") or []
                states = ", ".join(f"#{k['candidate_id']} {k['state']}" for k in kept)
                app.toast((f"{len(kept)} kept ({states}); {len(disc)} discarded"
                           if kept else f"All {len(disc)} drafts discarded")[:130],
                          kind=("good" if kept else "info"))
            elif st == "generated":
                app.toast(f"Candidate #{res.get('candidate_id')} \u2192 {res.get('state')}"[:130],
                          kind="good")
            elif st == "human_required":
                app.toast((res.get("note") or "")[:130], kind="info")
            elif st == "refused":
                app.toast((res.get("note") or "")[:130], kind="good")
            elif st == "load_failed":
                # A model that never ran is a broken install, not a refusal.
                app.toast(("Local model could not be loaded: "
                           + (res.get("reason") or ""))[:130], kind="warn")
            elif st == "no_targets":
                app.toast("The audit found nothing needing new content.", kind="info")
            elif st == "no_generator":
                app.toast((res.get("note") or "")[:130], kind="info")
            else:
                app.toast(str(st)[:130], kind="info")
            refresh()

        def gen_one():
            # Model loading and two inferences (or a network round-trip) take
            # tens of seconds; on the Tk thread that is a frozen window and a
            # button that queues a second run. Worker thread on its own
            # connection, polled with `after`, button disabled meanwhile.
            gen_btn.configure(state="disabled", text="Generating\u2026")
            h = {}

            def w():
                wc = None
                try:
                    wc = db_connect()
                    h["r"] = _gen_work(wc)
                except Exception as e:
                    h["e"] = f"{type(e).__name__}: {e}"
                finally:
                    if wc is not None:
                        try:
                            wc.close()
                        except Exception:
                            pass

            import threading
            threading.Thread(target=w, daemon=True).start()

            def poll():
                if not gen_btn.winfo_exists():
                    return
                if "r" not in h and "e" not in h:
                    app.after(200, poll); return
                gen_btn.configure(state="normal", text="Generate a candidate")
                if "e" in h:
                    app.toast(("Generation failed: " + h["e"])[:130], kind="warn")
                    return
                _gen_report(h["r"])

            poll()

        gen_btn = ghost_button(ci, "Generate a candidate", gen_one)
        gen_btn.pack(anchor="w", pady=(8, 6))
        refresh()

    lazy_section(scroll, "Candidate bank",
                 "Generated content awaiting independent verification and human approval.",
                 _build_candidates)

    # ---- evidence graph ----
    try:
        gs = graph_stats(conn)
    except Exception:
        gs = None
    if gs and gs["total"]:
        gc = card(scroll)
        gc.pack(fill="x", pady=(0, 12))
        gi = ctk.CTkFrame(gc, fg_color="transparent")
        gi.pack(fill="x", padx=18, pady=14)
        ctk.CTkLabel(gi, text="Evidence graph", font=(FONT_DISPLAY, 14, "bold"),
                     text_color=C.INK, anchor="w").pack(anchor="w")
        ctk.CTkLabel(gi,
                     text=(f"{gs['total']} edges  \u00b7  {gs['verified']} verified  "
                           f"\u00b7  {gs['inferred']} inferred. An inferred edge is the "
                           "system's own guess and is never treated as authored fact."),
                     font=(FONT_BODY, 11), text_color=C.INK_DIM,
                     anchor="w").pack(anchor="w", pady=(4, 8))
        for et, prov, cnt, ver in gs["by_type"][:8]:
            row = ctk.CTkFrame(gi, fg_color="transparent", height=0)
            row.pack(fill="x", pady=1)
            ctk.CTkLabel(row, text=et, font=(FONT_MONO, 10), text_color=C.INK,
                         width=190, anchor="w").pack(side="left")
            ctk.CTkLabel(row, text=prov, font=(FONT_BODY, 10),
                         text_color=(C.FOREST if prov == "authored" else
                                     C.BRASS_DARK if prov == "measured" else C.STAMP),
                         width=90, anchor="w").pack(side="left")
            ctk.CTkLabel(row, text=f"{cnt} edges  ({ver} verified)",
                         font=(FONT_MONO, 10), text_color=C.INK_DIM,
                         anchor="w").pack(side="left")

    # ---- the expert pool ----
    pool = expert_pool_status(conn)
    pc = card(scroll)
    pc.pack(fill="x", pady=(0, 12))
    pi = ctk.CTkFrame(pc, fg_color="transparent")
    pi.pack(fill="x", padx=18, pady=14)
    ctk.CTkLabel(pi, text="Expert pool", font=(FONT_DISPLAY, 14, "bold"),
                 text_color=C.INK, anchor="w").pack(anchor="w", pady=(0, 6))
    for e in pool["experts"]:
        row = ctk.CTkFrame(pi, fg_color="transparent", height=0)
        row.pack(fill="x", pady=2)
        ctk.CTkLabel(row, text=("\u2713" if e["available"] else "\u2717"),
                     font=(FONT_BODY, 12, "bold"), width=20,
                     text_color=(C.FOREST if e["available"] else C.INK_DIM),
                     anchor="w").pack(side="left")
        ctk.CTkLabel(row, text=f"{e['label']}  (tier {e['tier']})",
                     font=(FONT_BODY, 11), text_color=C.INK,
                     width=250, anchor="w").pack(side="left")
        ctk.CTkLabel(row, text=e["reason"][:56], font=(FONT_BODY, 10),
                     text_color=C.INK_DIM, anchor="w").pack(side="left")


def _elapsed_since(started):
    """Seconds since a time.monotonic() mark, or None when there is no mark.
    Mission screens pass this as time_taken so the pace model sees a real
    response time rather than a constant; None is what the estimators
    already treat as "not measured"."""
    if started is None:
        return None
    return max(1, int(round(time.monotonic() - started)))

def _mission_item_ids(conn, mission_id):
    """Item ids named in a mission's gate evidence ("... on q23")."""
    out = set()
    for r in _safe_query(conn, "SELECT detail FROM mission_evidence WHERE mission_id=?",
                         (mission_id,)) or []:
        for tok in re.findall(r"\bon (\S+)", r["detail"] or ""):
            if tok in QUIZ_BANK:
                out.add(tok)
    return out

def _last_served_at(conn, qid):
    rows = _safe_query(conn, "SELECT MAX(timestamp) t FROM attempts WHERE question_id=?",
                       (qid,))
    return (rows[0]["t"] if rows else None) or ""

def run_delayed_check(app, parent, conn, mission_id, on_done=None):
    """The spacing-interval retrieval that closes a mission.

    Deliberately minimal and deliberately unassisted: one item, no hints, no
    explanation beforehand. The question this answers is whether the repair
    survived a night, and any scaffolding at this point would answer a
    different question."""
    brief = mission_brief(conn, mission_id)
    st = mission_state(conn, mission_id)
    if not brief or not st:
        if on_done:
            on_done()
        return
    for w in parent.winfo_children():
        w.destroy()
    wrap = ctk.CTkScrollableFrame(parent, fg_color="transparent")
    wrap.pack(fill="both", expand=True, padx=34, pady=(18, 14))

    ctk.CTkLabel(wrap, text="Delayed check", font=(FONT_BODY, 10, "bold"),
                 text_color=C.BRASS_DARK, anchor="w").pack(anchor="w")
    ctk.CTkLabel(wrap, text=brief["label"], font=(FONT_DISPLAY, 20, "bold"),
                 text_color=C.INK, anchor="w", justify="left",
                 wraplength=760).pack(anchor="w", pady=(2, 4))
    ctk.CTkLabel(wrap,
                 text=f'You repaired this {st["age_hours"]:.0f} hours ago. One '
                      "item, no hints \u2014 this is the check that decides "
                      "whether it held.",
                 font=(FONT_BODY, 12), text_color=C.INK_DIM, anchor="w",
                 justify="left", wraplength=740).pack(anchor="w", pady=(0, 14))

    # Prefer an item the repair sequence did NOT use: the transfer item
    # (pool[-1] on a two-item skill) was answered at the end of the repair,
    # so re-serving it measures recognition. Items the mission touched are
    # named in its evidence; anything else on the skill comes first, then
    # the least-recently-served of the rest.
    pool = [QUIZ_BANK[i] for i in brief["items"] if i in QUIZ_BANK]
    used_ids = _mission_item_ids(conn, mission_id)
    fresh = [q for q in pool if q["id"] not in used_ids]
    probe = (fresh[0] if fresh else
             min(pool, key=lambda q: _last_served_at(conn, q["id"])) if pool else None)
    if probe is None:
        ctk.CTkLabel(wrap, text="No item available for this check.",
                     font=(FONT_BODY, 12), text_color=C.INK_DIM,
                     anchor="w").pack(anchor="w")
        primary_button(wrap, "Back", on_done or (lambda: app.show_view("dashboard"))
                       ).pack(anchor="w", pady=(12, 0))
        return
    shown_at = time.monotonic()
    c = card(wrap)
    c.pack(fill="x")
    inner = ctk.CTkFrame(c, fg_color="transparent")
    inner.pack(fill="x", padx=20, pady=16)
    ql = ctk.CTkLabel(inner, text=probe["q"], font=(FONT_BODY, 13),
                      text_color=C.INK, anchor="w", justify="left")
    ql.pack(anchor="w", fill="x", pady=(0, 10))
    bind_autowrap(ql, wrap, padding=110)

    def choose(idx):
        correct = (idx == probe["a"])
        record_gate(conn, mission_id, "delayed", correct,
                    f"delayed retrieval on {probe['id']}")
        record_attempt(conn, "quiz", probe["id"], probe["topic"], correct, 0,
                       probe.get("a_irt", 1.0), probe.get("b_irt", 0.0),
                       _elapsed_since(shown_at), chosen=idx, question=probe)
        closed = close_mission_if_proven(conn, mission_id)
        for w in wrap.winfo_children():
            w.destroy()
        rc = card(wrap)
        rc.pack(fill="x")
        ri = ctk.CTkFrame(rc, fg_color="transparent")
        ri.pack(fill="x", padx=20, pady=18)
        ctk.CTkLabel(ri,
                     text=("Repaired." if closed else
                           ("Held \u2014 but other gates are still open."
                            if correct else
                            "It did not hold. The mission stays open and the "
                            "delayed check will come round again.")),
                     font=(FONT_DISPLAY, 17, "bold"),
                     text_color=(C.FOREST if closed or correct else C.STAMP),
                     anchor="w").pack(anchor="w")
        if probe.get("exp"):
            el = ctk.CTkLabel(ri, text=probe["exp"], font=(FONT_BODY, 12),
                              text_color=C.INK, anchor="w", justify="left")
            el.pack(anchor="w", fill="x", pady=(8, 0))
            bind_autowrap(el, wrap, padding=110)
        primary_button(ri, "Done",
                       on_done or (lambda: app.show_view("dashboard"))
                       ).pack(anchor="w", pady=(16, 0))

    for i, opt in enumerate(probe.get("opts", [])):
        ghost_button(inner, f"{'ABCD'[i]}.  {opt[:88]}",
                     lambda i_=i: choose(i_)).pack(anchor="w", fill="x", pady=2)


def run_mission(app, parent, conn, mission_id, on_done=None):
    """Walk the learner through the repair sequence that EARNS the gates.

    Until now the gates could only be set from code, which made the mission
    a scoreboard with no game attached. This is the game: a fixed sequence
    that follows the order the review specifies, and which cannot be
    short-circuited by reading.

        1. Commit    -- name the rule that made your wrong answer look right
        2. Predict   -- classify a contrast pair BEFORE any feedback
        3. Confront  -- why that rule fails, shown only after committing
        4. Restate   -- write the corrected rule from memory
        5. Transfer  -- apply it to an item from the same skill

    The ordering is the intervention. Showing the explanation before the
    prediction converts the whole thing into reading comprehension: the
    learner nods along, recognises the right answer, and learns nothing,
    because recognition is not retrieval. Step 3 is therefore gated behind
    step 2 having been answered, not merely displayed.
    """
    brief = mission_brief(conn, mission_id)
    if not brief:
        if on_done:
            on_done()
        return

    st = mission_state(conn, mission_id)
    for w in parent.winfo_children():
        w.destroy()

    wrap = ctk.CTkScrollableFrame(parent, fg_color="transparent")
    wrap.pack(fill="both", expand=True, padx=34, pady=(18, 14))

    state = {"step": 0, "commit": "", "prediction": None, "restate": "",
             "shown_at": None}

    pool = [QUIZ_BANK[i] for i in brief["items"] if i in QUIZ_BANK]

    def finish():
        close_mission_if_proven(conn, mission_id)
        if on_done:
            on_done()
        else:
            app.show_view("checklist")

    def header():
        ctk.CTkLabel(wrap, text="Repair mission", font=(FONT_BODY, 10, "bold"),
                     text_color=C.BRASS_DARK, anchor="w").pack(anchor="w")
        ctk.CTkLabel(wrap, text=brief["label"], font=(FONT_DISPLAY, 20, "bold"),
                     text_color=C.INK, anchor="w", justify="left",
                     wraplength=760).pack(anchor="w", pady=(2, 6))
        tl = ctk.CTkLabel(wrap, text=brief["target"], font=(FONT_BODY, 12),
                          text_color=C.INK_DIM, anchor="w", justify="left")
        tl.pack(anchor="w", fill="x", pady=(0, 4))
        bind_autowrap(tl, wrap, padding=90)
        steps = ["Commit", "Predict", "Confront", "Restate", "Transfer"]
        ctk.CTkLabel(wrap,
                     text=f"Step {min(state['step'] + 1, len(steps))} of "
                          f"{len(steps)} \u2014 {steps[min(state['step'], len(steps)-1)]}",
                     font=(FONT_BODY, 11, "bold"), text_color=C.BRASS_DARK,
                     anchor="w").pack(anchor="w", pady=(8, 2))
        row = ctk.CTkFrame(wrap, fg_color="transparent", height=0)
        row.pack(anchor="w", pady=(2, 14))
        for i, s_ in enumerate(steps):
            done = i < state["step"]
            here = i == state["step"]
            ctk.CTkLabel(row, text=("\u2713 " if done else "") + s_,
                         font=(FONT_BODY, 11, "bold" if here else "normal"),
                         text_color=(C.FOREST if done else
                                     C.INK if here else C.INK_DIM)
                         ).pack(side="left", padx=(0, 16))

    def render():
        for w in wrap.winfo_children():
            w.destroy()
        header()
        c = card(wrap)
        c.pack(fill="x", pady=(0, 12))
        inner = ctk.CTkFrame(c, fg_color="transparent")
        inner.pack(fill="x", padx=20, pady=16)
        # Response time for the two answered steps is measured from here.
        state["shown_at"] = time.monotonic()

        # ---- 1. COMMIT ----
        if state["step"] == 0:
            ctk.CTkLabel(inner, text="What made your answer look right?",
                         font=(FONT_DISPLAY, 15, "bold"), text_color=C.INK,
                         anchor="w").pack(anchor="w")
            q = ctk.CTkLabel(
                inner,
                text=(brief["hypothesis"] or
                      "Write the rule you were using, in your own words."),
                font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w",
                justify="left")
            q.pack(anchor="w", fill="x", pady=(4, 10))
            bind_autowrap(q, wrap, padding=110)
            ctk.CTkLabel(inner, text="Say it before you see anything else. "
                                     "Naming the wrong rule is what makes it "
                                     "possible to replace.",
                         font=(FONT_BODY, 10, "italic"), text_color=C.BRASS_DARK,
                         anchor="w").pack(anchor="w", pady=(0, 6))
            box = ctk.CTkTextbox(inner, height=90, font=(FONT_BODY, 12),
                                 fg_color=C.PAPER, text_color=C.INK,
                                 border_width=1, border_color=C.PAPER_LINE)
            box.pack(fill="x", pady=(0, 10))

            def go():
                state["commit"] = box.get("1.0", "end").strip()
                state["step"] = 1
                render()
            primary_button(inner, "Continue", go).pack(anchor="w")

        # ---- 2. PREDICT (before any feedback) ----
        elif state["step"] == 1:
            ctk.CTkLabel(inner, text="Now classify this one",
                         font=(FONT_DISPLAY, 15, "bold"), text_color=C.INK,
                         anchor="w").pack(anchor="w")
            if brief["decisive"]:
                dl = ctk.CTkLabel(inner, text="The distinction at stake: "
                                              + brief["decisive"],
                                  font=(FONT_BODY, 11), text_color=C.BRASS_DARK,
                                  anchor="w", justify="left")
                dl.pack(anchor="w", fill="x", pady=(4, 8))
                bind_autowrap(dl, wrap, padding=110)
            probe = pool[0] if pool else None
            if not probe:
                state["step"] = 3
                render()
                return
            pl = ctk.CTkLabel(inner, text=probe["q"], font=(FONT_BODY, 13),
                              text_color=C.INK, anchor="w", justify="left")
            pl.pack(anchor="w", fill="x", pady=(4, 10))
            bind_autowrap(pl, wrap, padding=110)
            ctk.CTkLabel(inner, text="Commit to an answer. Nothing is revealed "
                                     "until you do.",
                         font=(FONT_BODY, 10, "italic"), text_color=C.BRASS_DARK,
                         anchor="w").pack(anchor="w", pady=(0, 8))

            def choose(idx, q_=probe):
                state["prediction"] = idx
                correct = (idx == q_["a"])
                record_gate(conn, mission_id, "discrimination", correct,
                            f"chose option {idx} on {q_['id']}")
                record_attempt(conn, "quiz", q_["id"], q_["topic"], correct, 0,
                               q_.get("a_irt", 1.0), q_.get("b_irt", 0.0),
                               _elapsed_since(state["shown_at"]), chosen=idx,
                               question=q_)
                state["step"] = 2
                render()

            for i, opt in enumerate(probe.get("opts", [])):
                ghost_button(inner, f"{'ABCD'[i]}.  {opt[:88]}",
                             lambda i_=i: choose(i_)).pack(anchor="w", fill="x",
                                                           pady=2)

        # ---- 3. CONFRONT ----
        elif state["step"] == 2:
            probe = pool[0] if pool else None
            ok = probe and state["prediction"] == probe["a"]
            ctk.CTkLabel(inner,
                         text=("Right \u2014 and here is why."
                               if ok else "Not that one. Here is where the rule "
                                          "you named breaks."),
                         font=(FONT_DISPLAY, 15, "bold"),
                         text_color=(C.FOREST if ok else C.STAMP),
                         anchor="w").pack(anchor="w")
            if state["commit"]:
                ctk.CTkLabel(inner, text="You said you were using:",
                             font=(FONT_BODY, 10, "bold"), text_color=C.BRASS_DARK,
                             anchor="w").pack(anchor="w", pady=(8, 2))
                cl = ctk.CTkLabel(inner, text="\u201c" + state["commit"][:400] + "\u201d",
                                  font=(FONT_BODY, 11, "italic"),
                                  text_color=C.INK_DIM, anchor="w", justify="left")
                cl.pack(anchor="w", fill="x")
                bind_autowrap(cl, wrap, padding=110)
            if probe and probe.get("exp"):
                el = ctk.CTkLabel(inner, text=probe["exp"], font=(FONT_BODY, 12),
                                  text_color=C.INK, anchor="w", justify="left")
                el.pack(anchor="w", fill="x", pady=(10, 0))
                bind_autowrap(el, wrap, padding=110)
            for sec in brief["sections"][:2]:
                ctk.CTkLabel(inner, text=sec["heading"], font=(FONT_BODY, 11, "bold"),
                             text_color=C.BRASS_DARK, anchor="w").pack(anchor="w",
                                                                       pady=(10, 2))
                for line in sec["lines"][:2]:
                    sl_ = ctk.CTkLabel(inner, text="\u2022  " + str(line),
                                       font=(FONT_BODY, 11), text_color=C.INK,
                                       anchor="w", justify="left")
                    sl_.pack(anchor="w", fill="x")
                    bind_autowrap(sl_, wrap, padding=118)

            def go():
                state["step"] = 3
                render()
            primary_button(inner, "Continue", go).pack(anchor="w", pady=(14, 0))

        # ---- 4. RESTATE ----
        elif state["step"] == 3:
            ctk.CTkLabel(inner, text="State the corrected rule from memory",
                         font=(FONT_DISPLAY, 15, "bold"), text_color=C.INK,
                         anchor="w").pack(anchor="w")
            ctk.CTkLabel(inner,
                         text="Close the explanation in your head first. Writing "
                              "it in your own words is the retrieval that makes "
                              "it stick; copying it back does nothing.",
                         font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w",
                         justify="left", wraplength=700).pack(anchor="w",
                                                              pady=(4, 10))
            box = ctk.CTkTextbox(inner, height=110, font=(FONT_BODY, 12),
                                 fg_color=C.PAPER, text_color=C.INK,
                                 border_width=1, border_color=C.PAPER_LINE)
            box.pack(fill="x", pady=(0, 10))

            def go():
                txt = box.get("1.0", "end").strip()
                state["restate"] = txt
                # Graded on substance, not wording: a restatement shorter than
                # a phrase is not a rule, and one that merely echoes the
                # question is not retrieval.
                ref = ""
                for sec in brief["sections"]:
                    if sec["key"] in ("core", "qual", "disc", "disc2"):
                        ref = " ".join(str(l) for l in sec["lines"])
                        break
                passed, why = grade_own_words(conn, mission_id, txt, ref)
                record_gate(conn, mission_id, "own_words", passed,
                            f"{why} | {txt[:160]}")
                state["step"] = 4
                render()
            primary_button(inner, "Submit", go).pack(anchor="w")

        # ---- 5. TRANSFER ----
        else:
            # Never the Predict item: its explanation was on screen one step
            # ago, so answering it again is recognition and would record
            # the transfer gate as passed on nothing.
            predicted = pool[0]["id"] if pool else None
            others = [q for q in pool if q["id"] != predicted]
            probe = others[0] if others else None
            same_rule = probe is not None
            if probe is None:
                # Single-item skill: the gate is waived (mission_state
                # records the waiver as evidence). The session still ends
                # in retrieval -- a neighbouring item from outside the
                # brief -- but that answer is practice, not proof of
                # transfer, and is labelled as such.
                topic = SKILLS.get(brief["skill"], {}).get("topic")
                near = transfer_probe_for(conn, {"items": brief["items"],
                                                 "topics": [topic] if topic else []}, n=1)
                probe = near[0] if near else None
            ctk.CTkLabel(inner,
                         text=("Now a different item, same rule" if same_rule else
                               "No second item on this rule \u2014 a neighbour instead"),
                         font=(FONT_DISPLAY, 15, "bold"), text_color=C.INK,
                         anchor="w").pack(anchor="w")
            if not same_rule:
                ctk.CTkLabel(inner,
                             text=("The bank holds only one item on this skill, so "
                                   "transfer cannot be proven here \u2014 a content gap, "
                                   "not a gap in you. That gate is waived for this "
                                   "mission."
                                   + (" Finish with a related item from the same "
                                      "topic; it counts as practice, not as proof."
                                      if probe else "")),
                             font=(FONT_BODY, 12), text_color=C.BRASS_DARK,
                             anchor="w", justify="left",
                             wraplength=700).pack(anchor="w", pady=(6, 12))
            if not probe:
                primary_button(inner, "Finish", finish).pack(anchor="w")
                return
            pl = ctk.CTkLabel(inner, text=probe["q"], font=(FONT_BODY, 13),
                              text_color=C.INK, anchor="w", justify="left")
            pl.pack(anchor="w", fill="x", pady=(6, 10))
            bind_autowrap(pl, wrap, padding=110)

            def choose(idx, q_=probe):
                correct = (idx == q_["a"])
                if same_rule:
                    record_gate(conn, mission_id, "transfer", correct,
                                f"chose {idx} on {q_['id']}")
                record_attempt(conn, "quiz", q_["id"], q_["topic"], correct, 0,
                               q_.get("a_irt", 1.0), q_.get("b_irt", 0.0),
                               _elapsed_since(state["shown_at"]), chosen=idx,
                               question=q_)
                show_outcome(correct)

            for i, opt in enumerate(probe.get("opts", [])):
                ghost_button(inner, f"{'ABCD'[i]}.  {opt[:88]}",
                             lambda i_=i: choose(i_)).pack(anchor="w", fill="x",
                                                           pady=2)

    def show_outcome(last_ok):
        for w in wrap.winfo_children():
            w.destroy()
        stn = mission_state(conn, mission_id)
        c = card(wrap)
        c.pack(fill="x", pady=(0, 12))
        inner = ctk.CTkFrame(c, fg_color="transparent")
        inner.pack(fill="x", padx=20, pady=18)
        ctk.CTkLabel(inner, text="Where this repair stands",
                     font=(FONT_DISPLAY, 17, "bold"), text_color=C.INK,
                     anchor="w").pack(anchor="w", pady=(0, 8))
        names = {"discrimination": "Immediate contrast",
                 "own_words": "Rule stated from memory",
                 "delayed": "Recall after a spacing interval",
                 "transfer": "Applied to a different item"}
        for gname in MISSION_GATES:
            done = gname in stn["passed"]
            locked = gname == "delayed" and not stn["delayed_eligible"] and not done
            txt = ("Waived — single-item skill" if gname in stn.get("waived", ()) else
                   "Passed" if done else
                   ("Due later" if locked else "Not yet demonstrated"))
            r_ = ctk.CTkFrame(inner, fg_color="transparent", height=0)
            r_.pack(fill="x", pady=2)
            ctk.CTkLabel(r_, text=names[gname], font=(FONT_BODY, 12),
                         text_color=C.INK, width=260, anchor="w").pack(side="left")
            ctk.CTkLabel(r_, text=txt, font=(FONT_BODY, 12, "bold"),
                         text_color=(C.FOREST if done else
                                     C.BRASS_DARK if locked else C.INK_DIM),
                         anchor="w").pack(side="left")
        status = "Repaired" if stn["complete"] else "Repair in progress"
        ctk.CTkLabel(inner, text="Status: " + status,
                     font=(FONT_BODY, 13, "bold"),
                     text_color=(C.FOREST if stn["complete"] else C.BRASS_DARK),
                     anchor="w").pack(anchor="w", pady=(12, 2))
        if stn.get("blocked_note"):
            bl = ctk.CTkLabel(inner, text=stn["blocked_note"], font=(FONT_BODY, 11),
                              text_color=C.INK_DIM, anchor="w", justify="left")
            bl.pack(anchor="w", fill="x", pady=(4, 0))
            bind_autowrap(bl, wrap, padding=110)
        primary_button(inner, "Done", finish).pack(anchor="w", pady=(16, 0))

    render()


def view_learning_lab(app, parent):
    """THE LEARNING LAB.

    Everything the adaptive machinery produces has, until now, been reachable
    only by knowing where to look: open a topic, expand a breakdown, click
    the right sub-skill. A learner who did not know that path saw none of
    it. This is the screen that makes the machinery legible in one place --
    what is being repaired right now, what the system believes about you and
    on what evidence, and which parts of the map are load-bearing.

    Deliberately NOT a dashboard of numbers. Every block here answers "and
    therefore what should I do", because a screen that only reports is the
    thing this app has repeatedly had to be rescued from.
    """
    conn = app.conn
    scroll = ctk.CTkScrollableFrame(parent, fg_color="transparent")
    scroll.pack(fill="both", expand=True, padx=30, pady=(20, 10))

    section_title(scroll, "Repairs",
                  "What is being fixed right now, and what proof is still "
                  "outstanding before it counts as fixed.").pack(anchor="w", pady=(0, 16))

    # ---------------------------------------------------------------
    # 1. WHAT TO DO RIGHT NOW
    # ---------------------------------------------------------------
    try:
        due = missions_due_now(conn)
    except Exception:
        due = {"repair": [], "delayed": [], "waiting": 0}

    c = card(scroll, fg_color=C.NAVY)
    c.pack(fill="x", pady=(0, 16))
    inner = ctk.CTkFrame(c, fg_color="transparent")
    inner.pack(fill="x", padx=22, pady=18)
    ctk.CTkLabel(inner, text="Right now", font=(FONT_BODY, 10, "bold"),
                 text_color=C.BRASS).pack(anchor="w")

    if due["delayed"]:
        st0 = due["delayed"][0]
        lab = SKILLS.get(st0["skill"], {}).get("label", st0["skill"])
        ctk.CTkLabel(inner, text="A repair is ready to be checked",
                     font=(FONT_DISPLAY, 18, "bold"), text_color=C.CREAM,
                     anchor="w", justify="left",
                     wraplength=640).pack(anchor="w", pady=(3, 4))
        dl = ctk.CTkLabel(
            inner,
            text=(f"{lab} \u2014 repaired {st0['age_hours']:.0f} hours ago. "
                  "One item, no hints, decides whether it held."),
            font=(FONT_BODY, 12), text_color=C.GOLD_SOFT, anchor="w",
            justify="left")
        dl.pack(anchor="w", fill="x")
        bind_autowrap(dl, scroll, padding=110)
        primary_button(inner, "Take the delayed check",
                       lambda mid=st0["mission_id"]: run_delayed_check(
                           app, parent, conn, mid,
                           on_done=lambda: app.show_view("learninglab"))
                       ).pack(anchor="w", pady=(12, 0))

    elif due["repair"]:
        st0 = due["repair"][0]
        ctk.CTkLabel(inner, text="Continue the open repair",
                     font=(FONT_DISPLAY, 18, "bold"), text_color=C.CREAM,
                     anchor="w").pack(anchor="w", pady=(3, 4))
        tl = ctk.CTkLabel(inner, text=st0["target"], font=(FONT_BODY, 12),
                          text_color=C.GOLD_SOFT, anchor="w", justify="left")
        tl.pack(anchor="w", fill="x")
        bind_autowrap(tl, scroll, padding=110)
        ctk.CTkLabel(inner, text="Still to prove: " + ", ".join(st0["outstanding"]),
                     font=(FONT_BODY, 10), text_color=C.NAVY_3,
                     anchor="w").pack(anchor="w", pady=(6, 0))
        primary_button(inner, "Continue",
                       lambda mid=st0["mission_id"]: run_mission(
                           app, parent, conn, mid,
                           on_done=lambda: app.show_view("learninglab"))
                       ).pack(anchor="w", pady=(12, 0))
    else:
        ctk.CTkLabel(inner, text="No repair outstanding",
                     font=(FONT_DISPLAY, 18, "bold"), text_color=C.CREAM,
                     anchor="w").pack(anchor="w", pady=(3, 4))
        nl = ctk.CTkLabel(
            inner,
            text=("Nothing is currently diagnosed as a specific wrong rule. "
                  "Answer more items and repairs will open themselves \u2014 they "
                  "are compiled from your errors, not scheduled in advance."),
            font=(FONT_BODY, 12), text_color=C.GOLD_SOFT, anchor="w",
            justify="left")
        nl.pack(anchor="w", fill="x")
        bind_autowrap(nl, scroll, padding=110)
        ghost_button(inner, "Practise", lambda: app.show_view("adaptive")).pack(
            anchor="w", pady=(12, 0))

    if due.get("waiting"):
        ctk.CTkLabel(inner,
                     text=f"{due['waiting']} repair(s) waiting on a spacing "
                          "interval before they can be closed.",
                     font=(FONT_BODY, 10), text_color=C.NAVY_3,
                     anchor="w").pack(anchor="w", pady=(10, 0))

    # ---------------------------------------------------------------
    # 2. WHAT THE SYSTEM BELIEVES ABOUT YOU
    # ---------------------------------------------------------------
    def _build_beliefs(_p):
        try:
            bl = active_beliefs(conn, limit=10)
        except Exception:
            bl = []
        bi = ctk.CTkFrame(_p, fg_color="transparent")
        bi.pack(fill="x", padx=4, pady=4)
        note = ctk.CTkLabel(
            bi,
            text=("Each of these is a HYPOTHESIS drawn from your answer "
                  "patterns \u2014 the same answers are also consistent with "
                  "guessing or time pressure. They are shown so you can "
                  "disagree with them, not so you accept them."),
            font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w",
            justify="left")
        note.pack(anchor="w", fill="x", pady=(0, 10))
        bind_autowrap(note, scroll, padding=90)
        if not bl:
            ctk.CTkLabel(bi, text="No belief hypotheses yet.",
                         font=(FONT_BODY, 11), text_color=C.INK_DIM,
                         anchor="w").pack(anchor="w")
            return
        for b in bl:
            bv = belief_view(conn, b["belief_id"])
            if not bv:
                continue
            bc = card(bi)
            bc.pack(fill="x", pady=4)
            bb = ctk.CTkFrame(bc, fg_color="transparent")
            bb.pack(fill="x", padx=14, pady=10)
            lab = SKILLS.get(bv["skill"], {}).get("label", bv["skill"])
            col = {"reopened": C.STAMP, "repaired": C.FOREST,
                   "provisionally_repaired": C.BRASS_DARK}.get(bv["state"], C.INK)
            hdr = ctk.CTkFrame(bb, fg_color="transparent", height=0)
            hdr.pack(fill="x")
            ctk.CTkLabel(hdr, text=lab, font=(FONT_BODY, 12, "bold"),
                         text_color=C.INK, anchor="w").pack(side="left")
            ctk.CTkLabel(hdr, text=bv["state"].replace("_", " "),
                         font=(FONT_BODY, 11, "bold"), text_color=col,
                         anchor="e").pack(side="right")
            hl = ctk.CTkLabel(bb, text=bv["hypothesis"], font=(FONT_BODY, 11),
                              text_color=C.INK_DIM, anchor="w", justify="left")
            hl.pack(anchor="w", fill="x", pady=(3, 4))
            bind_autowrap(hl, scroll, padding=110)
            ctk.CTkLabel(bb, text=belief_summary_line(bv), font=(FONT_BODY, 11),
                         text_color=col, anchor="w", justify="left",
                         wraplength=620).pack(anchor="w")
            ctk.CTkLabel(
                bb,
                text=(f"   {len(bv['supports'])} supporting \u00b7 "
                      f"{len(bv['weakens'])} weakening"
                      + (f" \u00b7 reopened {bv['reopen_count']}\u00d7"
                         if bv["reopen_count"] else "")),
                font=(FONT_BODY, 9), text_color=C.INK_DIM,
                anchor="w").pack(anchor="w", pady=(4, 0))
            ghost_button(bb, "Open the brief",
                         lambda s_=bv["skill"]: show_skill_note(conn, s_, app)
                         ).pack(anchor="w", pady=(8, 0))

    lazy_section(scroll, "What the system believes about you",
                 "Hypotheses, their evidence, and their repair state.",
                 _build_beliefs)

    # ---------------------------------------------------------------
    # 3. THE MAP: WHERE THE WEIGHT SITS
    # ---------------------------------------------------------------
    def _build_map(_p):
        mi = ctk.CTkFrame(_p, fg_color="transparent")
        mi.pack(fill="x", padx=4, pady=4)
        try:
            cut = next_uncertainty_cut(conn)
        except Exception:
            cut = None
        if cut:
            ctk.CTkLabel(mi, text="The single most consequential gap",
                         font=(FONT_BODY, 11, "bold"), text_color=C.BRASS_DARK,
                         anchor="w").pack(anchor="w")
            cl = ctk.CTkLabel(mi, text=cut["why"], font=(FONT_BODY, 12),
                              text_color=C.INK, anchor="w", justify="left")
            cl.pack(anchor="w", fill="x", pady=(2, 12))
            bind_autowrap(cl, scroll, padding=100)

        # Weakest skills, prerequisite-aware, straight from the graph.
        rows = []
        for tid in TOPICS:
            sids = topic_skill_ids(tid)
            if len(sids) < 2:
                continue
            try:
                post = dina_topic_posterior(conn, tid)
            except Exception:
                post = None
            if not post:
                continue
            for sid, m in post["skill_mastery"].items():
                rows.append((m, sid, tid, post.get("n", 0)))
        rows.sort()
        if rows:
            ctk.CTkLabel(mi, text="Weakest sub-skills, load-bearing first",
                         font=(FONT_BODY, 11, "bold"), text_color=C.BRASS_DARK,
                         anchor="w").pack(anchor="w", pady=(4, 4))
        for m, sid, tid, nobs in rows[:10]:
            r_ = ctk.CTkFrame(mi, fg_color="transparent", height=0)
            r_.pack(fill="x", pady=1)
            lab = SKILLS.get(sid, {}).get("label", sid)
            sl = ctk.CTkLabel(r_, text=lab, font=(FONT_BODY, 11),
                              text_color=C.INK, width=290, anchor="w")
            sl.pack(side="left")
            try:
                b = upstream_bottleneck(conn, sid)
            except Exception:
                b = None
            tag = ("rests on " + b["label"][:30]) if b else TOPICS[tid]["short"][:26]
            ctk.CTkLabel(r_, text=tag, font=(FONT_BODY, 10),
                         text_color=(C.STAMP if b else C.INK_DIM),
                         width=230, anchor="w").pack(side="left")
            ctk.CTkLabel(r_, text=f"{m*100:.0f}%", font=(FONT_MONO, 10),
                         text_color=(C.STAMP if m < 0.35 else C.BRASS_DARK),
                         width=46, anchor="e").pack(side="left")
            for tgt in (sl, getattr(sl, "_label", None)):
                if tgt is None:
                    continue
                try:
                    tgt.bind("<Button-1>",
                             lambda _e, s_=sid: show_skill_note(conn, s_, app))
                    tgt.configure(cursor="hand2")
                except Exception:
                    pass

    lazy_section(scroll, "Your knowledge map",
                 "Where the weight sits, and what rests on what.",
                 _build_map)

    # The guide compiler used to be duplicated here. It belongs in the
    # Study Guide view, next to the guide itself; two compilers in two
    # places under two names was the same confusion the tab rename fixed.
    gl = ctk.CTkLabel(
        scroll,
        text=("Your focused study guide lives in Study \u2192 Study Guide, "
              "with its own page-count and export controls."),
        font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w", justify="left")
    gl.pack(anchor="w", fill="x", pady=(10, 4))
    bind_autowrap(gl, scroll, padding=90)
    ghost_button(scroll, "Open the Study Guide",
                 lambda: app.show_view("studyguide")).pack(anchor="w",
                                                           pady=(4, 10))


def view_study_guide(app, parent):
    """THE STUDY GUIDE.

    The primary study surface. Not a popup per skill and not a file you have
    to export first -- the twenty pages that drill into what is actually
    failing, readable in the app, with a contents list you can jump around.

    Everything here is fragility-weighted: page budget goes where mastery is
    low and exam weight is high. A skill at 96% gets a line at the back.
    """
    conn = app.conn
    outer = ctk.CTkFrame(parent, fg_color="transparent")
    outer.pack(fill="both", expand=True, padx=26, pady=(18, 10))

    head = ctk.CTkFrame(outer, fg_color="transparent")
    head.pack(fill="x")
    section_title(head, "Study Guide",
                  "The material that is actually failing, worked in full.").pack(
                      anchor="w", pady=(0, 10))

    state = {"pages": 20, "targets": [], "sel": 0}

    # A live label, refreshed by build(). The first version was written once
    # at view construction, so switching to "Everything" left it still
    # reporting the 20-page figure -- the one number a person changing the
    # budget is actually looking at.
    size_note = ctk.CTkLabel(head, text="", font=(FONT_BODY, 10),
                             text_color=C.INK_DIM, anchor="w", justify="left",
                             wraplength=900)
    size_note.pack(anchor="w", pady=(2, 6))

    body = ctk.CTkFrame(outer, fg_color="transparent")
    body.pack(fill="both", expand=True)
    body.grid_columnconfigure(1, weight=1)
    body.grid_rowconfigure(0, weight=1)

    # CTkScrollableFrame overrides grid_propagate to take no arguments, so
    # the usual grid_propagate(False) raises. Width is fixed by the column
    # instead, which is the supported route.
    nav = ctk.CTkScrollableFrame(body, fg_color=C.PAPER_DIM, width=248)
    nav.grid(row=0, column=0, sticky="nsw", padx=(0, 14))
    body.grid_columnconfigure(0, weight=0, minsize=248)

    read = ctk.CTkScrollableFrame(body, fg_color="transparent")
    read.grid(row=0, column=1, sticky="nsew")

    def render_reader():
        for w in read.winfo_children():
            w.destroy()
        if not state["targets"]:
            ctk.CTkLabel(read,
                         text="Nothing has enough evidence yet to build a focused "
                              "guide. Answer some questions and this fills with "
                              "the material you are actually missing.",
                         font=(FONT_BODY, 12), text_color=C.INK_DIM,
                         anchor="w", justify="left",
                         wraplength=760).pack(anchor="w", pady=20)
            return
        r = state["targets"][state["sel"]]
        sid = r["skill"]
        W = 780

        mat = content_maturity(conn, sid)
        ctk.CTkLabel(read, text=SKILLS.get(sid, {}).get("label", sid),
                     font=(FONT_DISPLAY, 22, "bold"), text_color=C.INK,
                     anchor="w", justify="left",
                     wraplength=W).pack(anchor="w")

        mrow = ctk.CTkFrame(read, fg_color="transparent", height=0)
        mrow.pack(anchor="w", fill="x", pady=(4, 2))
        mcol = {"gold": C.FOREST, "silver": C.BRASS_DARK, "bronze": C.BRASS_DARK,
                "draft": C.STAMP, "gap": C.STAMP}[mat["key"]]
        ctk.CTkLabel(mrow, text=mat["label"].upper(),
                     font=(FONT_BODY, 10, "bold"), text_color=mcol,
                     anchor="w").pack(side="left", padx=(0, 10))
        ctk.CTkLabel(mrow,
                     text=(f'you are at {r["mastery"]*100:.0f}%  \u00b7  '
                           f'{TOPICS[r["topic"]]["short"]}  \u00b7  '
                           f'~{_exam_weight(r["topic"]):.0f} exam questions'),
                     font=(FONT_BODY, 11), text_color=C.INK_DIM,
                     anchor="w").pack(side="left")
        # The maturity label is worthless if its meaning is a mystery.
        ctk.CTkLabel(read, text=mat["meaning"], font=(FONT_BODY, 10),
                     text_color=mcol, anchor="w", justify="left",
                     wraplength=W).pack(anchor="w", pady=(0, 12))

        dense = dense_skill_content(conn, sid)

        def heading(t, col=C.BRASS_DARK):
            ctk.CTkLabel(read, text=t, font=(FONT_BODY, 13, "bold"),
                         text_color=col, anchor="w").pack(anchor="w",
                                                          pady=(14, 4))

        for blk in dense["blocks"]:
            if blk["kind"] == "distinction" and blk["rows"]:
                heading("Ask this first")
                for d_ in blk["rows"]:
                    ctk.CTkLabel(read, text="\u21c4  " + d_["pair"],
                                 font=(FONT_BODY, 12, "bold"), text_color=C.INK,
                                 anchor="w", justify="left",
                                 wraplength=W).pack(anchor="w", pady=(4, 0))
                    if d_["decider"]:
                        ctk.CTkLabel(read, text="     decided by: " + d_["decider"],
                                     font=(FONT_BODY, 12), text_color=C.FOREST,
                                     anchor="w", justify="left",
                                     wraplength=W - 20).pack(anchor="w")
                    for side in (d_["this"], d_["other"]):
                        if side:
                            ctk.CTkLabel(read, text="     " + side,
                                         font=(FONT_BODY, 11),
                                         text_color=C.INK_DIM, anchor="w",
                                         justify="left",
                                         wraplength=W - 20).pack(anchor="w")
            if blk["kind"] == "definition" and blk["rows"]:
                heading("Terms")
                for d_ in blk["rows"]:
                    ctk.CTkLabel(read, text="\u2022  " + str(d_),
                                 font=(FONT_BODY, 12), text_color=C.INK,
                                 anchor="w", justify="left",
                                 wraplength=W).pack(anchor="w", pady=1)

        # ---- the comparison table ----
        # Prose makes the reader hold four definitions in their head and diff
        # them. A table does the diffing on the page, and its columns come
        # from the deciding facts the confusion pairs already assert.
        try:
            tbl = comparison_table(conn, r["topic"])
        except Exception:
            tbl = None
        if tbl and len(tbl["concepts"]) >= 2:
            heading("Side by side")
            for con in tbl["concepts"][:6]:
                crow = ctk.CTkFrame(read, fg_color=C.PAPER_DIM, corner_radius=6)
                crow.pack(fill="x", pady=2)
                ci = ctk.CTkFrame(crow, fg_color="transparent")
                ci.pack(fill="x", padx=12, pady=7)
                ctk.CTkLabel(ci, text=con["name"], font=(FONT_BODY, 12, "bold"),
                             text_color=C.INK, anchor="w", justify="left",
                             wraplength=W - 40).pack(anchor="w")
                for dim, txt in list(con["dims"].items())[:2]:
                    ctk.CTkLabel(ci, text=f"   {dim}: {txt}",
                                 font=(FONT_BODY, 11), text_color=C.INK_DIM,
                                 anchor="w", justify="left",
                                 wraplength=W - 50).pack(anchor="w")

        # ---- worked cases, every option ----
        heading("Worked cases")
        for q in r["items"]:
            ctk.CTkLabel(read, text=q["q"], font=(FONT_BODY, 13, "bold"),
                         text_color=C.INK, anchor="w", justify="left",
                         wraplength=W).pack(anchor="w", pady=(10, 4))
            for o in _option_analysis(q):
                mark = "\u2713" if o["correct"] else "\u2717"
                col = C.FOREST if o["correct"] else C.STAMP
                ctk.CTkLabel(read,
                             text=f'{mark}  {o["letter"]}.  {o["text"]}',
                             font=(FONT_BODY, 12,
                                   "bold" if o["correct"] else "normal"),
                             text_color=col if o["correct"] else C.INK,
                             anchor="w", justify="left",
                             wraplength=W - 10).pack(anchor="w")
                if o["why"]:
                    src = ("" if o["correct"] or
                           o.get("src") == "authored misconception"
                           else f"   [{o.get('src','')}]")
                    ctk.CTkLabel(read, text="      " + o["why"] + src,
                                 font=(FONT_BODY, 11), text_color=C.INK_DIM,
                                 anchor="w", justify="left",
                                 wraplength=W - 30).pack(anchor="w")

        for blk in dense["blocks"]:
            if blk["kind"] == "trap" and blk["rows"]:
                heading("Traps", C.STAMP)
                for t_ in blk["rows"][:4]:
                    ctk.CTkLabel(read, text="\u2022  " + str(t_),
                                 font=(FONT_BODY, 12), text_color=C.INK,
                                 anchor="w", justify="left",
                                 wraplength=W).pack(anchor="w", pady=1)
            if blk["kind"] == "related" and blk["rows"]:
                heading("The same rule, different facts")
                for r_ in blk["rows"][:4]:
                    ctk.CTkLabel(read, text="\u2022  " + r_["stem"],
                                 font=(FONT_BODY, 12), text_color=C.INK,
                                 anchor="w", justify="left",
                                 wraplength=W).pack(anchor="w", pady=(5, 0))
                    ctk.CTkLabel(read, text="      " + r_["why"],
                                 font=(FONT_BODY, 11), text_color=C.INK_DIM,
                                 anchor="w", justify="left",
                                 wraplength=W - 30).pack(anchor="w")
            if blk["kind"] == "prereq" and blk["rows"]:
                heading("Fix this first", C.STAMP)
                for t_ in blk["rows"]:
                    ctk.CTkLabel(read, text="\u2022  " + str(t_),
                                 font=(FONT_BODY, 12), text_color=C.INK,
                                 anchor="w", justify="left",
                                 wraplength=W).pack(anchor="w")

        brow = ctk.CTkFrame(read, fg_color="transparent", height=0)
        brow.pack(anchor="w", pady=(18, 6))
        primary_button(brow, "Practise this now",
                       lambda ids=[q["id"] for q in r["items"]]: (
                           QuestionSession(
                               app, parent,
                               [QUIZ_BANK[i] for i in ids if i in QUIZ_BANK],
                               "quiz", SKILLS.get(sid, {}).get("label", sid),
                               "Straight from the guide.", allow_hints=True,
                               collect_diagnostics=True,
                               on_finish=lambda s: render_result_screen(
                                   app, parent, s, lambda: app.show_view("studyguide"))))
                       ).pack(side="left", padx=(0, 8))
        ghost_button(brow, "Full brief for this skill",
                     lambda s_=sid: show_skill_note(conn, s_, app)).pack(side="left",
                                                                         padx=(0, 8))

        # Every practice surface in the app serves ONE skill. An exam section
        # mixes them, and interleaving is the condition under which
        # discrimination is actually trained -- blocked practice produces
        # confidence that collapses when the neighbouring concept appears.
        def _mixed(tid=r["topic"]):
            pool = mixed_practice_set(conn, tid, 8)
            if not pool:
                app.toast("Not enough items in this topic to interleave.",
                          kind="warn")
                return
            QuestionSession(app, parent, pool, "quiz",
                            f"Mixed set \u2014 {TOPICS[tid]['short']}",
                            "Sub-skills interleaved, weakest first \u2014 closer "
                            "to how the exam presents them.",
                            allow_hints=True, collect_diagnostics=True,
                            on_finish=lambda s: render_result_screen(
                                app, parent, s, lambda: app.show_view("studyguide")))
        ghost_button(brow, "Mixed set from this topic", _mixed).pack(side="left")

        if state["sel"] + 1 < len(state["targets"]):
            ghost_button(read, "Next chapter \u2192",
                         lambda: (state.update(sel=state["sel"] + 1),
                                  render_nav(), render_reader())).pack(
                             anchor="w", pady=(10, 0))

    def render_nav():
        for w in nav.winfo_children():
            w.destroy()
        ctk.CTkLabel(nav, text="Contents", font=(FONT_BODY, 11, "bold"),
                     text_color=C.BRASS_DARK, anchor="w").pack(anchor="w",
                                                               padx=10, pady=(8, 6))
        for i, r in enumerate(state["targets"]):
            live = (i == state["sel"])
            lab = SKILLS.get(r["skill"], {}).get("label", r["skill"])
            b = ctk.CTkButton(
                nav, text=f'{i+1}. {lab[:26]}\n     {r["mastery"]*100:.0f}%',
                anchor="w", height=42, corner_radius=6,
                font=(FONT_BODY, 11, "bold" if live else "normal"),
                fg_color=(C.BRASS if live else "transparent"),
                hover_color=C.PAPER_LINE,
                text_color=("#221A0C" if live else C.INK),
                command=(lambda i_=i: (state.update(sel=i_), render_nav(),
                                       render_reader())))
            b.pack(fill="x", padx=6, pady=1)

    def build(pages=20):
        for w in nav.winfo_children():
            w.destroy()
        ctk.CTkLabel(nav, text="Building\u2026", font=(FONT_BODY, 11),
                     text_color=C.INK_DIM).pack(padx=10, pady=10)
        app.update_idletasks()
        try:
            chosen, _all = focus_targets(conn, pages)
        except Exception:
            chosen = []
        state["targets"] = chosen
        state["sel"] = 0
        try:
            _all = focus_targets(conn, 999)[1]
            words = sum(r["material"] * 4.6 for r in chosen)
            size_note.configure(
                text=(f'{len(chosen)} of {len(_all)} sub-skills worked in full '
                      f'\u2014 about {words/450:.0f} pages, '
                      f'{sum(len(r["items"]) for r in chosen)} questions fully '
                      'analysed. '
                      + ("This is everything the authored corpus supports; "
                         "beyond this there is no more verified material to "
                         "draw on."
                         if len(chosen) >= len(_all) else
                         "Raise the budget to cover more.")))
        except Exception:
            pass
        # The budget buttons are built once; the highlight has to follow
        # the budget actually in force, which is also what _export uses.
        for pg, b in budget_btns.items():
            live = (pg == state["pages"])
            b.configure(fg_color=(C.BRASS if live else C.PAPER_DIM),
                        text_color=("#221A0C" if live else C.INK))
        render_nav()
        render_reader()

    ctrl = ctk.CTkFrame(head, fg_color="transparent", height=0)
    ctrl.pack(anchor="w", pady=(0, 8))
    # The budget was capped at 40 in the UI while the compiler happily
    # produces 165 pages -- the ceiling is the corpus, not the code, and
    # hiding the larger settings made the guide look far shorter than it
    # can actually be. "Everything" covers all 172 skills at full depth
    # with every option analysed.
    budget_btns = {}
    for pg, lab in ((10, "10 pages"), (20, "20 pages"), (40, "40 pages"),
                    (100, "100 pages"), (999, "Everything")):
        budget_btns[pg] = ctk.CTkButton(
            ctrl, text=lab, height=26, corner_radius=6,
            font=(FONT_BODY, 10, "bold"),
            fg_color=(C.BRASS if pg == state["pages"] else C.PAPER_DIM),
            hover_color=C.BRASS_DARK,
            text_color=("#221A0C" if pg == state["pages"] else C.INK),
            command=(lambda p_=pg: (state.update(pages=p_), build(p_))))
        budget_btns[pg].pack(side="left", padx=(0, 6))

    def _export():
        try:
            from tkinter import filedialog
            path = filedialog.asksaveasfilename(
                defaultextension=".md", initialfile="focus_guide.md",
                filetypes=[("Markdown", "*.md")])
            if not path:
                return
            st = export_focus_guide(conn, path, pages=state["pages"])
            app.toast(f"{st['words']:,} words \u00b7 ~{st['approx_pages']:.0f} "
                      f"pages \u00b7 {st['counterexamples']} counterexamples.",
                      kind="good")
        except Exception as e:
            app.toast(f"Export failed: {e}", kind="warn")

    def _export_full(revision_only):
        try:
            from tkinter import filedialog
            path = filedialog.asksaveasfilename(
                defaultextension=".md",
                initialfile=("revision_guide.md" if revision_only
                             else "full_reference.md"),
                filetypes=[("Markdown", "*.md")])
            if not path:
                return
            st = export_study_guide(conn, path, include_solid=not revision_only)
            app.toast(f"{st['words']:,} words \u00b7 {st['skill_sections']} "
                      f"skills \u00b7 ~{st['approx_pages']:.0f} pages.",
                      kind="good")
        except Exception as e:
            app.toast(f"Export failed: {e}", kind="warn")

    # Three exports, named for what they ARE rather than for the verb. The
    # old pair lived in Settings under names that collided with this view's.
    ctk.CTkLabel(ctrl, text="  save:", font=(FONT_BODY, 10),
                 text_color=C.INK_DIM).pack(side="left", padx=(12, 4))
    ghost_button(ctrl, "This guide", _export).pack(side="left", padx=(0, 6))
    ghost_button(ctrl, "Full reference (all 172)",
                 lambda: _export_full(False)).pack(side="left", padx=(0, 6))
    ghost_button(ctrl, "Weak areas only",
                 lambda: _export_full(True)).pack(side="left")

    build(state["pages"])
def view_loop(app, parent):
    """THE LOOP, as one screen.

    V1 spread the cycle across eight tabs. This is the cycle: what was
    observed, what was diagnosed, what is prescribed and why, the study
    packet built from the failures, and what will count as proof -- in
    order, on one page, with a button that runs the next turn.
    """
    conn = app.conn
    scroll = ctk.CTkScrollableFrame(parent, fg_color="transparent")
    scroll.pack(fill="both", expand=True, padx=30, pady=(18, 10))
    section_title(scroll, "Learning Loop",
                  "Test \u2192 diagnose \u2192 prescribe \u2192 study what you got wrong "
                  "\u2192 prove it \u2192 test again.").pack(anchor="w", pady=(0, 10))

    holder = ctk.CTkFrame(scroll, fg_color="transparent")
    holder.pack(fill="x")
    state = {"cycle": None}
    W = 860

    def stage(title, n, col=C.BRASS_DARK):
        ctk.CTkLabel(holder, text=f"{n}  {title}", font=(FONT_DISPLAY, 15, "bold"),
                     text_color=col, anchor="w").pack(anchor="w", pady=(18, 4))

    def line(txt, col=C.INK, size=12, bold=False, indent=0):
        lb = ctk.CTkLabel(holder, text=(" " * indent) + txt,
                          font=(FONT_BODY, size, "bold" if bold else "normal"),
                          text_color=col, anchor="w", justify="left", wraplength=W)
        lb.pack(anchor="w", pady=1)
        return lb

    def render(cyc, stored=False):
        for w in holder.winfo_children():
            w.destroy()
        if not cyc:
            hist = loop_history(conn, 1)
            if hist:
                line(f"Last turn: {hist[0]['started_at'][:16]} on {hist[0]['n_evidence']} "
                     "answers \u2014 its details were not kept. Press the button to "
                     "run a fresh turn.", C.INK_DIM)
            else:
                line("No cycle has run yet. Press the button to run one turn of the "
                     "loop on everything you have answered so far.", C.INK_DIM)
            return
        ob, dg, rx, pk, vf = (cyc["observed"], cyc["diagnosis"], cyc["prescription"],
                              cyc["packet"], cyc["verification"])
        if stored:
            line(f"Last turn: {str(ob.get('observed_at', ''))[:16]} on {ob['n']} answers. "
                 "This is what it saw and prescribed; press the button to run a "
                 "fresh turn.", C.INK_DIM, 10)

        stage("OBSERVED", "\u2460")
        flags = {}
        for e in ob["evidence"]:
            for fl in e["flags"]:
                flags[fl] = flags.get(fl, 0) + 1
        line(f"{ob['n']} recent answers, evidence-weighted. "
             + (f"Flags: " + ", ".join(f"{k} \u00d7{v}" for k, v in flags.items())
                if flags else "No unusual answers."), C.INK_DIM)
        if ob["rt_model"]:
            line(f"Your pace: median ~{math.exp(ob['rt_model'][0]):.0f}s; anything under "
                 f"~{math.exp(ob['rt_model'][0] - 1.5*ob['rt_model'][1]):.0f}s is flagged "
                 "as a guess for you specifically.", C.INK_DIM, 11)

        stage("DIAGNOSED", "\u2461")
        sm = dg["summary"]
        line(f"{dg['n_skills']} skills with evidence \u00b7 {sm['weak']} weak \u00b7 "
             f"{sm['fading']} fading \u00b7 {sm['misconceptions']} misconception(s) \u00b7 "
             f"{sm['blocked']} blocked by a prerequisite", C.INK, 12, True)
        extra = []
        if sm.get("pressure"):
            extra.append(f"{sm['pressure']} collapse only under a clock")
        if sm.get("content_gap"):
            extra.append(f"{sm['content_gap']} have too little content to teach from")
        if sm.get("unmeasurable"):
            extra.append(f"{sm['unmeasurable']} cannot be distinguished by the bank")
        if extra:
            line("  \u00b7  ".join(extra), C.BRASS_DARK, 11)
        gg = dg.get("generalization")
        if gg and gg.get("status") == "ok" and gg.get("gap", 0) > 0.2:
            line(f"Memorisation warning: familiar items {gg['seed_accuracy']*100:.0f}% vs "
                 f"changed variants {gg['variant_accuracy']*100:.0f}%. Strong scores may "
                 "reflect familiarity, not the rule.", C.STAMP, 11, True)
        if dg["root_causes"]:
            rc = dg["root_causes"][0]
            line(f"Root cause: {rc['label']} \u2014 several weak skills rest on it.",
                 C.STAMP, 12, True)
        for f in dg["findings"][:6]:
            col = C.STAMP if f["decayed_mastery"] < 0.35 else C.BRASS_DARK
            ret = f["retention"]
            line(f"\u2022 {f['label'][:56]}  \u2014  {f['decayed_mastery']*100:.0f}%"
                 + (f" (was {f['mastery']*100:.0f}% before decay)"
                    if ret and ret['retrievability'] is not None
                    and ret['retrievability'] < 0.95 else "")
                 + f"  \u00b7  {f['stance']}"
                 + (f"  \u00b7  {f['confident_wrong']} confident-wrong" if f["confident_wrong"] else ""),
                 col, 11)
            # Every claim carries its evidence: the percentage above is a
            # measurement only to the extent this line says it is.
            ecol = {"high": C.FOREST, "moderate": C.BRASS_DARK}.get(
                f.get("evidence_level"), C.INK_DIM)
            line(f"{str(f.get('evidence_level','')).upper()} confidence \u2014 "
                 f"{f.get('evidence_text','')}", ecol, 10, indent=4)

        if dg.get("unassessable"):
            line(f"{len(dg['unassessable'])} skill(s) with answers were NOT assessed: "
                 "the bank lacks the material to measure them. Routed to content "
                 "authoring, not to you.", C.INK_DIM, 11)
            for u in dg["unassessable"][:4]:
                line(f"\u2022 {u['label'][:60]}  [{(u.get('maturity') or '?').upper()}]"
                     + (f"  missing: {', '.join(u['maturity_missing'])}"
                        if u.get("maturity_missing") else ""),
                     C.INK_DIM, 10, indent=4)

        stage("PRESCRIBED", "\u2462")
        for i, r in enumerate(rx["interventions"], 1):
            kcol = C.STAMP if r["kind"] == "content_repair" else C.INK
            line(f"{i}. {r['label']}  [{r['kind'].replace('_', ' ')}]  \u00b7  "
                 f"{r.get('evidence_level', 'moderate')} confidence", kcol, 12, True)
            line(r["why"], C.INK_DIM, 11, indent=4)
            if r.get("measured"):
                line(f"measured on you: {r['measured']['intervention']} "
                     f"{r['measured']['lift']*100:+.0f} pts over {r['measured']['n']} use(s)",
                     C.FOREST, 10, indent=4)

        stage("STUDY PACKET \u2014 built from your failures", "\u2463")
        line(f"{pk['words']:,} words, {len(pk['chapters'])} chapter(s). Each opens with "
             "the item you missed, the option you chose, why it looked right and "
             "is wrong, then the rule, then an untreated item to apply it to.",
             C.INK_DIM, 11)
        for ch in pk["chapters"][:3]:
            fails = [s for s in ch["sections"] if s["kind"] == "failures"]
            nf = sum(len(s["items"]) for s in fails)
            line(f"\u2022 {ch['label'][:56]} \u2014 {nf} failure(s) worked, "
                 + ("ends in retrieval" if any(s["kind"] == "retrieval" for s in ch["sections"])
                    else "no untreated item available"), C.INK, 11)

        brow = ctk.CTkFrame(holder, fg_color="transparent", height=0)
        brow.pack(anchor="w", pady=(8, 0))

        def _export():
            try:
                from tkinter import filedialog
                path = filedialog.asksaveasfilename(
                    defaultextension=".md", initialfile="study_packet.md",
                    filetypes=[("Markdown", "*.md")])
                if not path:
                    return
                with open(path, "w", encoding="utf-8") as fh:
                    fh.write(pk["markdown"])
                app.toast(f"Packet written: {pk['words']:,} words.", kind="good")
            except Exception as e:
                app.toast(f"Export failed: {e}", kind="warn")
        primary_button(brow, "Open the packet as a document", _export).pack(
            side="left", padx=(0, 8))
        if rx["interventions"]:
            ghost_button(brow, "Open the first brief",
                         lambda s_=rx["interventions"][0]["skill"]:
                         show_skill_note(conn, s_, app)).pack(side="left")

        stage("PROOF REQUIRED", "\u2464")
        if vf.get("ripe_delayed"):
            r0 = vf["ripe_delayed"][0]
            line(f"A repair from {r0['age_hours']:.0f}h ago is ready for its delayed check: "
                 f"{r0['label'][:50]}. That comes first.", C.FOREST, 12, True)
            ghost_button(holder, "Take the delayed check now",
                         lambda mid=r0["mission_id"]: run_delayed_check(
                             app, parent, conn, mid,
                             on_done=lambda: app.show_view("loop"))
                         ).pack(anchor="w", pady=(4, 8))
        for v in vf["plan"][:5]:
            line(f"\u2022 {v['label'][:56]}: " + ", ".join(v["outstanding"])
                 + (f"  (delayed check unlocks after {v['delayed_at_hours']:.0f}h)"
                    if "delayed" in v["outstanding"] else ""), C.INK, 11)
        if vf["plan"] and vf["plan"][0].get("proof_set"):
            ps = vf["plan"][0]["proof_set"]
            ghost_button(holder, f"Prove it on an interleaved set ({len(ps)} items)",
                         lambda ids=ps: QuestionSession(
                             app, parent, [QUIZ_BANK[i] for i in ids if i in QUIZ_BANK],
                             "quiz", "Proof set", "Interleaved across the topic.",
                             allow_hints=False, collect_diagnostics=True,
                             on_finish=lambda s: render_result_screen(
                                 app, parent, s, lambda: app.show_view("loop")))
                         ).pack(anchor="w", pady=(6, 0))
        if vf["plan"] and vf["plan"][0]["mission_id"]:
            ghost_button(holder, "Start the first repair",
                         lambda mid=vf["plan"][0]["mission_id"]: run_mission(
                             app, parent, conn, mid,
                             on_done=lambda: app.show_view("loop"))
                         ).pack(anchor="w", pady=(8, 0))

        stage("THE LOOP JUDGING ITSELF", "\u2465", C.INK_DIM)
        eff = loop_effectiveness(conn)
        if len(eff) < 2:
            line("After two or more cycles this shows whether earlier prescriptions "
                 "moved the skills they targeted.", C.INK_DIM, 11)
        else:
            for e in eff[:5]:
                then = (f"{e['mastery_then']*100:.0f}%" if e.get("mastery_then") is not None
                        else "unrecorded")
                now = (f"{e['mastery_now']*100:.0f}%" if e.get("mastery_now") is not None
                       else "unknown")
                line(f"\u2022 cycle {e['cycle_id']}: {SKILLS.get(e['skill'], {}).get('label', e['skill'])[:44]}"
                     f" \u2014 {then} then ('{e['stance_then']}'), {now} now"
                     + (f"  \u00b7  {e['outcome']}" if e.get("outcome") else "  \u00b7  open"),
                     C.INK_DIM, 11)

    def run():
        for w in holder.winfo_children():
            w.destroy()
        line("Running one turn of the loop\u2026", C.INK_DIM)
        app.update_idletasks()
        try:
            state["cycle"] = run_learning_cycle(conn)
        except Exception as e:
            for w in holder.winfo_children():
                w.destroy()
            line(f"The loop could not complete: {e}", C.STAMP)
            return
        render(state["cycle"])

    ctrl = ctk.CTkFrame(scroll, fg_color="transparent", height=0)
    ctrl.pack(anchor="w", pady=(0, 6), before=holder)
    primary_button(ctrl, "Run one turn of the loop", run).pack(side="left", padx=(0, 8))
    ghost_button(ctrl, "Practise (feeds the next turn)",
                 lambda: app.show_view("quiz")).pack(side="left")

    # On entry, show the last turn as it was run so its prescription,
    # packet and proof plan are reachable without re-running the loop.
    state["cycle"] = loop_last_cycle(conn)
    render(state["cycle"], stored=True)

# ============================================================================
# FAILURE POINT EXPLORER (semantic, optional)
# ============================================================================

def view_explorer(app, parent):
    conn = app.conn
    wrap = ctk.CTkFrame(parent, fg_color="transparent")
    wrap.pack(fill="both", expand=True, padx=32, pady=28)
    section_title(wrap, "Failure Point Explorer", "Groups your misses by underlying conceptual similarity, not just the fixed topic tags.").pack(anchor="w", pady=(0, 16))
    mode_info_disclosure(wrap, "explorer")

    api_key = get_setting(conn, "anthropic_api_key", "")

    # Do NOT call semantic_available() here -- on first use it performs the
    # actual `import sentence_transformers` (pulling in transformers/torch),
    # which blocks the UI thread for many seconds. The worker below probes
    # it from inside the thread and reports back; until then this screen
    # shows a neutral loading state.
    #
    # Only show the hard "nothing available" screen when BOTH paths are
    # closed -- no local model AND no API key. If an API key is configured,
    # fall through to the loading state below; the worker tries the local
    # model first and uses the API as a genuine alternative, not just an
    # error message, when the local stack isn't available.
    # The precomputed vectors ship with the app, so clustering is now
    # ALWAYS possible -- this guard predates that and would otherwise
    # short-circuit to a "nothing available" screen before the worker ever
    # ran the offline path. Only block when there is genuinely nothing:
    # no embeddings, no local model, and no API key.
    if (not embeddings_available()) and semantic_available_cached() is False and not api_key:
        c = card(wrap, fg_color=C.PAPER_DIM)
        c.pack(fill="x")
        inner = ctk.CTkFrame(c, fg_color="transparent")
        inner.pack(fill="x", padx=20, pady=18)
        msg = ctk.CTkLabel(inner, text="This needs either the sentence-transformers package (a small local "
                           "Hugging Face model, ~80MB, runs on CPU, no GPU needed) or an Anthropic API key "
                           "set in Settings, which lets this cluster your misses via the API instead of a "
                           "local model.\n\nTo install the local package:\n\n"
                           "    pip install sentence-transformers\n\nThen click \u2018Check again\u2019 below "
                           "-- no need to restart the app. Everything else here works fine without either.",
                           font=(FONT_MONO, 12), text_color=C.INK, anchor="w", justify="left")
        msg.pack(anchor="w", fill="x")
        bind_autowrap(msg, wrap, padding=48)
        # A failed check used to be cached for the entire life of the running
        # process -- fixing the real cause (e.g. a stray file shadowing a
        # standard-library module) while the app kept running had no visible
        # effect until a full restart, because nothing ever re-checked. This
        # button forces an immediate, uncached re-check instead of making
        # the user wait out the retry cooldown or close and reopen the app.
        def recheck():
            reset_semantic_check()
            app.show_view("explorer")
        primary_button(inner, "Check again", recheck).pack(anchor="w", pady=(14, 0))
        return

    status_lbl = ctk.CTkLabel(wrap, text="Loading...", font=(FONT_BODY, 13), text_color=C.INK_DIM)
    status_lbl.pack(anchor="w", pady=(10, 0))

    result_holder = {}

    def worker():
        # A sqlite3 connection belongs to the thread that created it. `conn`
        # (=app.conn) was created on the main thread, so it cannot be used
        # here -- this worker opens its own short-lived connection instead.
        # (This exact bug was fixed once before and regressed when this view
        # was later edited wholesale to add the pressure-profile card; the
        # fix didn't survive that rewrite.)
        wconn = None
        try:
            wconn = db_connect()
            # The capability ladder decides which backend to use, rather
            # than a hardcoded order. It picks the strongest tier this
            # machine can actually sustain and walks down on failure, so a
            # workstation gets encoder-quality clustering while a
            # locked-down laptop still gets the precomputed floor -- and
            # neither has to be configured by the learner.
            result_holder["status"] = "Grouping your misses\u2026"
            clusters, tier_used, note = semantic_cluster_best(wconn)
            if clusters:
                infos = [describe_cluster(wconn, c) for c in clusters[:8]]
                result_holder["clusters"] = list(zip(clusters[:8], infos))
                result_holder["tier"] = tier_used
                if tier_used in (1, 2):
                    try:
                        result_holder["model"] = _get_embed_model()
                    except Exception:
                        pass
                return
            result_holder["clusters"] = []
            result_holder["tier"] = tier_used
            return
        except Exception as e:
            result_holder["error"] = f"Clustering failed: {e}"
        finally:
            if wconn is not None:
                try:
                    wconn.close()
                except Exception:
                    pass

    import threading
    t = threading.Thread(target=worker, daemon=True)
    t.start()

    def poll():
        # The worker thread keeps running after the user navigates away
        # (parent.after fires on the persistent content frame, not on this
        # view's own widgets), so wrap/status_lbl can already be destroyed
        # by the time this callback runs. Stop touching anything and stop
        # rescheduling the moment that's true, rather than crashing on a
        # destroyed widget or silently leaking a polling loop forever.
        if not wrap.winfo_exists():
            return
        if "status" in result_holder:
            try:
                status_lbl.configure(text=result_holder["status"])
            except tk.TclError:
                return
        if t.is_alive():
            parent.after(150, poll)
            return
        render_results()

    def render_results():
        if not wrap.winfo_exists():
            return
        for w in wrap.winfo_children():
            w.destroy()
        section_title(wrap, "Failure Point Explorer", "Groups your misses by underlying conceptual similarity.").pack(anchor="w", pady=(0, 16))

        if result_holder.get("error"):
            ctk.CTkLabel(wrap, text=result_holder["error"], font=(FONT_BODY, 13), text_color=C.STAMP).pack(anchor="w")
            return

        clusters = result_holder.get("clusters", [])
        if not clusters:
            ctk.CTkLabel(wrap, text="Not enough missed-question data yet for patterns to emerge (need at "
                         "least two misses that cluster together). Take a Quiz or the Diagnostic first.",
                         font=(FONT_BODY, 13), text_color=C.INK_DIM, wraplength=560, justify="left",
                         anchor="w").pack(anchor="w")
            return

        listing = ctk.CTkScrollableFrame(wrap, fg_color="transparent", height=420)
        listing.pack(fill="both", expand=True, pady=(0, 12))

        for i, (cluster, info) in enumerate(clusters, 1):
            c = card(listing)
            c.pack(fill="x", pady=4)
            inner = ctk.CTkFrame(c, fg_color="transparent")
            inner.pack(fill="x", padx=16, pady=12)
            topic_summary = ", ".join(f"{TOPICS[t]['short']} ({n})" for t, n in info["topic_counts"].most_common(3))
            header_row = ctk.CTkFrame(inner, fg_color="transparent", height=0)
            header_row.pack(anchor="w", fill="x")
            ctk.CTkLabel(header_row, text=f"Cluster {i} \u2014 {len(info['members'])} missed questions",
                        font=(FONT_DISPLAY, 14, "bold"), text_color=C.NAVY, anchor="w").pack(side="left")
            # API-based clusters (cluster_via_api) come with a short label
            # naming the shared concept directly, something the local
            # embedding path has no equivalent for -- surface it when present.
            if cluster.get("label"):
                ctk.CTkLabel(header_row, text="  \u00b7  \u201c" + cluster["label"] + "\u201d",
                            font=(FONT_DISPLAY, 14, "italic"), text_color=C.BRASS_DARK,
                            anchor="w").pack(side="left")
            ctk.CTkLabel(inner, text=f"Topics involved: {topic_summary}", font=(FONT_BODY, 11),
                        text_color=C.INK_DIM, anchor="w").pack(anchor="w", pady=(2, 0))
            if info["rep_q"]:
                rep_lbl = ctk.CTkLabel(inner, text=f"Representative miss: \u201c{info['rep_q']['q'][:130]}\u201d",
                                       font=(FONT_BODY, 12), text_color=C.INK, anchor="w", justify="left")
                rep_lbl.pack(anchor="w", fill="x", pady=(4, 0))
                bind_autowrap(rep_lbl, wrap, padding=48)
            if info["error_type_counts"]:
                et_str = ", ".join(f"{k}: {v}" for k, v in info["error_type_counts"].items())
                ctk.CTkLabel(inner, text=f"Tagged as: {et_str}", font=(FONT_BODY, 11), text_color=C.BRASS_DARK,
                            anchor="w").pack(anchor="w", pady=(2, 6))

            def drill(cl=cluster):
                pool = [QUIZ_BANK[m] for m in cl["members"] if m in QUIZ_BANK]
                random.shuffle(pool)

                def on_finish(summary):
                    render_result_screen(app, parent, summary, lambda: app.show_view("explorer"))

                QuestionSession(app, parent, pool, "quiz", "Cluster Drill", f"{len(pool)} questions from this cluster",
                               allow_hints=True, collect_diagnostics=True, on_finish=on_finish)

            # ---- diagnose -> treat -> verify on a probe outside the cluster ----
            # "Drill this cluster" re-serves the same items, which measures
            # re-exposure. This path diagnoses what the cluster represents,
            # picks the treatment with the best measured lift for THIS
            # learner, and verifies it on untreated items of the same skill.
            def treat(cl=cluster):
                members = [m for m in cl["members"] if m in QUIZ_BANK]
                diag = diagnose_cluster(app.conn, members)
                if not diag:
                    app.toast("Could not diagnose this cluster.", kind="warn")
                    return
                # One occasion key for this (cluster, day): it fixes the arm
                # before the remedy is delivered and names the row the
                # transfer probe will score.
                occ = remedy_occasion_key(diag)
                iv = select_intervention(app.conn, diag, key=occ)
                probe = transfer_probe_for(app.conn, diag, n=4)
                if not probe:
                    app.toast("No transfer probe available outside this cluster.",
                              kind="warn")
                    return
                pre_rows = _safe_query(
                    app.conn, """SELECT correct FROM attempts WHERE question_id IN ({})
                                  ORDER BY id DESC LIMIT 8""".format(
                        ",".join("?" * len(members))), tuple(members))
                pre_c = sum(1 for r in pre_rows if r["correct"])
                rid = open_remedy(app.conn, diag, iv["type"], pre_c,
                                  max(1, len(pre_rows)), selection=iv)

                treat_pool = [QUIZ_BANK[m] for m in members]

                def after_probe(summary):
                    got = summary.get("correct", 0) if isinstance(summary, dict) else 0
                    tot = summary.get("total", len(probe)) if isinstance(summary, dict) else len(probe)
                    res = close_remedy(app.conn, rid, got, tot)
                    # The trial's declared observable, scored exactly once:
                    # accuracy on items OUTSIDE the treated cluster, which is
                    # the only score that distinguishes a remedy that worked
                    # from one that merely re-exposed.
                    if iv.get("trial") and tot:
                        record_intervention_outcome(app.conn, iv["trial"],
                                                    iv.get("occasion_key"), got / tot)
                    if res:
                        app.toast(f"{iv['label']}: {res['lift']*100:+.0f} pts on "
                                  f"untreated items of the same skill.",
                                  kind=("good" if res["lift"] > 0 else "info"))
                    app.show_view("explorer")

                def after_treatment(_s):
                    QuestionSession(app, parent, probe, "quiz",
                                    "Transfer probe",
                                    "Different items, same skill \u2014 this checks the "
                                    "remedy transferred rather than just familiarised.",
                                    allow_hints=False, collect_diagnostics=False,
                                    on_finish=after_probe)

                QuestionSession(app, parent, treat_pool, "quiz",
                                iv["label"], iv["detail"],
                                allow_hints=True, collect_diagnostics=True,
                                on_finish=after_treatment)

            brow = ctk.CTkFrame(inner, fg_color="transparent", height=0)
            brow.pack(anchor="w", fill="x")
            ghost_button(brow, "Drill this cluster", drill).pack(side="left", padx=(0, 8))
            primary_button(brow, "Diagnose & treat", treat).pack(side="left")

        # Name the backend that produced these clusters. Analysis quality
        # differs materially between tiers, so presenting results without
        # saying which produced them would be misleading.
        tier_used = result_holder.get("tier")
        if tier_used is not None and tier_used in SEMANTIC_TIERS:
            ctk.CTkLabel(wrap,
                text="Grouped using: " + SEMANTIC_TIERS[tier_used]["name"] +
                     ("  \u00b7  change in Settings" if tier_used == 0 else ""),
                font=(FONT_BODY, 10), text_color=C.INK_DIM,
                anchor="w").pack(anchor="w", pady=(2, 8))

        model = result_holder.get("model")
        # The embedding-space search box below is genuinely a local-model-
        # only feature -- a live per-keystroke similarity search via API
        # calls would be slow and costly, so this isn't reimplemented for
        # the API path. Rather than show a box that silently does nothing on
        # every click, it's simply not rendered when there's no local model;
        # the FTS5-based Search view already covers keyword search either way.
        if model is None:
            return
        search_card = card(wrap, fg_color=C.PAPER_DIM)
        search_card.pack(fill="x")
        sinner = ctk.CTkFrame(search_card, fg_color="transparent")
        sinner.pack(fill="x", padx=16, pady=14)
        ctk.CTkLabel(sinner, text="Semantic search", font=(FONT_DISPLAY, 14, "bold"), text_color=C.INK,
                    anchor="w").pack(anchor="w")
        ctk.CTkLabel(sinner, text="Describe what's tripping you up in your own words.", font=(FONT_BODY, 11),
                    text_color=C.INK_DIM, anchor="w").pack(anchor="w", pady=(2, 8))
        row = ctk.CTkFrame(sinner, fg_color="transparent")
        row.pack(fill="x")
        query_entry = styled_entry(row, font=(FONT_BODY, 12), placeholder_text="e.g. dual agency conflicts")
        query_entry.pack(side="left", fill="x", expand=True, padx=(0, 8))
        results_area = ctk.CTkFrame(wrap, fg_color="transparent")
        results_area.pack(fill="x", pady=(10, 0))

        def do_search():
            query = query_entry.get().strip()
            if not query or model is None:
                return
            for w in results_area.winfo_children():
                w.destroy()
            qvec = [float(x) for x in model.encode([query], normalize_embeddings=True)[0]]
            q_cache = get_question_embeddings(model)
            scored = sorted(QUIZ_LIST, key=lambda q: -cosine(qvec, q_cache[q["id"]]))[:5]
            for q in scored:
                topic = TOPICS[q["topic"]]
                hist = conn.execute("SELECT correct FROM attempts WHERE question_id=?", (q["id"],)).fetchall()
                hist_str = f"{sum(r['correct'] for r in hist)}/{len(hist)} correct so far" if hist else "not attempted yet"
                row_lbl = ctk.CTkLabel(results_area, text=f"[{topic['short']}] {q['q'][:100]}  \u2014  {hist_str}",
                                       font=(FONT_BODY, 12), text_color=C.INK, anchor="w", justify="left")
                row_lbl.pack(anchor="w", fill="x", pady=3)
                bind_autowrap(row_lbl, wrap, padding=48)

        primary_button(row, "Search", do_search, width=90).pack(side="left")

    parent.after(150, poll)

