    ranked = sorted(frag.items(), key=lambda kv: kv[1]["score"], reverse=True)
    studied = [(tid, f) for tid, f in ranked if f["n"] > 0]
    if studied:
        flist = card(scroll)
        flist.pack(fill="x", pady=(0, 16))
        finner = ctk.CTkFrame(flist, fg_color="transparent")
        finner.pack(fill="x", padx=16, pady=12)
        # Only the weakest handful are shown up front. The list is sorted
