# ===========================================================================
# V8 -- TRAJECTORY OBSERVATIONS, LOGGED PROPENSITIES, PORTION READINESS
# ===========================================================================

def _ensure_column(conn, table, column, declaration):
    """Idempotent column add. Called from the owning schema initialiser."""
    try:
        cols = {r[1] for r in conn.execute(f"PRAGMA table_info({table})").fetchall()}
        if cols and column not in cols:
            conn.execute(f"ALTER TABLE {table} ADD COLUMN {column} {declaration}")
            conn.commit()
    except sqlite3.Error as e:
        _audit(conn, "schema_column_failed", f"{table}.{column}: {type(e).__name__}: {e}")


def _is_secret_setting(key):
    k = str(key or "")
    return k in BACKUP_SECRET_SETTINGS or k.startswith("fabric_token_")


# ---- observations at declared horizons, captured only inside their window ----
#
# A delayed observation means something only if it was taken near the delay it
# is labelled with. A sweep that runs whenever the app happens to open would
# otherwise record today's state under every overdue horizon. So each horizon
# has a window [h, h + tolerance]; inside it the state is captured, after it
# the horizon is recorded as MISSED with no state, and a missed horizon is
# never back-filled.
#
# Other interventions in the window are recorded as covariates, not used as an
# exclusion filter. Excluding occasions that were followed by another
# intervention conditions on something the treatment itself can cause (a
# repair triggered by a miss), which biases the contrast. The identified
# contrast is the randomised assignment with time-ordered pairing and washout
# that the trial machinery already implements.

TRAJECTORY_OBS_HORIZONS_H = (20.0, 72.0, 168.0)


def trajectory_obs_tolerance_h(horizon_h):
    return max(6.0, 0.5 * float(horizon_h))


def init_trajectory_observation_schema(conn):
    conn.executescript("""
    CREATE TABLE IF NOT EXISTS trajectory_observations (
        trajectory_id      INTEGER NOT NULL,
        horizon_hours      REAL NOT NULL,
        status             TEXT NOT NULL,         -- 'captured' | 'missed'
        observed_at        TEXT,
        actual_delay_hours REAL,
        state_snapshot     TEXT,
        window_actions     TEXT,
        n_window_actions   INTEGER,
        PRIMARY KEY (trajectory_id, horizon_hours)
    );
    """)
    conn.commit()


def capture_trajectory_observations(conn, horizons=TRAJECTORY_OBS_HORIZONS_H,
                                    now=None, tolerance_fn=None):
    """Capture every horizon whose window is open now; mark missed every
    horizon whose window has closed uncaptured. Returns (captured, missed)."""
    tol = tolerance_fn or trajectory_obs_tolerance_h
    try:
        init_trajectory_schema(conn)
        init_trajectory_observation_schema(conn)
        now = now or datetime.now()
        rows = _safe_query(conn, "SELECT trajectory_id, opened_at FROM state_trajectories "
                                 "ORDER BY opened_at ASC")
        done = {(r["trajectory_id"], r["horizon_hours"]) for r in _safe_query(
            conn, "SELECT trajectory_id, horizon_hours FROM trajectory_observations")}
        snap = None
        captured = missed = 0
        for r in rows:
            try:
                opened = datetime.fromisoformat(r["opened_at"])
            except (TypeError, ValueError):
                continue
            elapsed = (now - opened).total_seconds() / 3600.0
            for h in horizons:
                h = float(h)
                if (r["trajectory_id"], h) in done or elapsed < h:
                    continue
                if elapsed <= h + tol(h):
                    if snap is None:
                        snap = json.dumps(trajectory_state_snapshot(conn))
                    acts = _safe_query(conn, "SELECT trajectory_id, action, assignment "
                                             "FROM state_trajectories WHERE trajectory_id<>? "
                                             "AND opened_at>? AND opened_at<=?",
                                       (r["trajectory_id"], r["opened_at"], now.isoformat()))
                    conn.execute("INSERT OR IGNORE INTO trajectory_observations VALUES "
                                 "(?,?,?,?,?,?,?,?)",
                                 (r["trajectory_id"], h, "captured", now.isoformat(),
                                  round(elapsed, 3), snap,
                                  json.dumps([dict(a) for a in acts]), len(acts)))
                    captured += 1
                else:
                    conn.execute("INSERT OR IGNORE INTO trajectory_observations VALUES "
                                 "(?,?,?,?,?,?,?,?)",
                                 (r["trajectory_id"], h, "missed", None, None, None, None, None))
                    missed += 1
        if captured or missed:
            conn.commit()
        return captured, missed
    except (sqlite3.Error, TypeError, ValueError) as e:
        _audit(conn, "trajectory_observation_failed", f"{type(e).__name__}: {e}")
        return 0, 0


def trajectory_observation_set(conn, horizon_hours=72.0):
    """Export for a future transition fit: each occasion with its assignment,
    logged propensity, the observation at this horizon (or its absence), and
    window covariates. Nothing is upgraded: a policy-assigned occasion stays
    descriptive whatever its window looked like."""
    init_trajectory_observation_schema(conn)
    rows = _safe_query(conn, """
        SELECT t.trajectory_id, t.learner, t.occasion_key, t.action, t.assignment, t.trial,
               t.propensity, t.arm_set, t.state_before, t.opened_at,
               o.status, o.observed_at, o.actual_delay_hours, o.state_snapshot,
               o.n_window_actions, o.window_actions
        FROM state_trajectories t
        LEFT JOIN trajectory_observations o
               ON o.trajectory_id=t.trajectory_id AND o.horizon_hours=?
        ORDER BY t.learner, t.opened_at""", (float(horizon_hours),))

    def _j(x, d=None):
        try:
            return json.loads(x) if x else d
        except (TypeError, ValueError):
            return d
    rev = _skill_items()
    recs = [{"trajectory_id": r["trajectory_id"], "learner": r["learner"],
             "occasion_key": r["occasion_key"], "action": r["action"],
             "assignment": r["assignment"], "trial": r["trial"],
             "propensity": r["propensity"], "arm_set": _j(r["arm_set"], []),
             "state_before": _j(r["state_before"], {}), "opened_at": r["opened_at"],
             "status": r["status"] or "pending", "observed_at": r["observed_at"],
             "actual_delay_hours": r["actual_delay_hours"],
             "state_after": _j(r["state_snapshot"]),
             "n_post_treatment_events": r["n_window_actions"],
             "post_treatment_events": _j(r["window_actions"], []),
             "active_days_prior_7": _active_days_before(conn, r["opened_at"]),
             "reconstructed": reconstruct_decay(conn, _j(r["state_before"], {}),
                                                r["opened_at"], horizon_hours, _rev=rev)}
            for r in rows]
    for x in recs:
        x["engagement_stratum"] = _engagement_stratum(x["active_days_prior_7"])
    decided = [x for x in recs if x["status"] in ("captured", "missed")]
    rates = {}
    for x in decided:
        c, n = rates.get(x["engagement_stratum"], (0, 0))
        rates[x["engagement_stratum"]] = (c + (x["status"] == "captured"), n + 1)
    for x in recs:
        c, n = rates.get(x["engagement_stratum"], (0, 0))
        p = (c + 1) / (n + 2)
        x["p_observed"] = round(p, 4)
        x["ipw_observed"] = round(1.0 / p, 4) if x["status"] == "captured" else None
    return {"schema": "recursa.trajectory_observations.v2",
            "horizon_hours": float(horizon_hours), "records": recs,
            # Later events are recorded because they happened, not so they can be
            # adjusted for: if treatment A changes whether B follows, holding B
            # fixed estimates something other than A's total effect. A fitter
            # must say which effect it estimates (total, controlled direct, or
            # dynamic regime) and use a method that matches.
            "estimand_required": True,
            "post_treatment_events_are": "sequence_record_not_adjustment_set",
            "causal_use": "randomized records only, with observation weights",
            "observation_model": ("capture modelled as MAR given 7-day engagement "
                                  "stratum; p_observed shrunk Beta(1,1)"),
            "reconstructed_basis": "scheduler decay only; not a behavioural observation",
            "n": len(recs),
            "captured": sum(1 for x in recs if x["status"] == "captured"),
            "missed": sum(1 for x in recs if x["status"] == "missed"),
            "randomized_with_propensity": sum(1 for x in recs if x["assignment"] == "randomized"
                                              and x["propensity"] is not None)}


def intervention_propensity(conn, name, key):
    rows = _safe_query(conn, "SELECT propensity FROM intervention_occasions "
                             "WHERE name=? AND key=?", (name, str(key)))
    return rows[0]["propensity"] if rows else None


# ---- portion-wise readiness --------------------------------------------------
#
# The New Jersey salesperson examination is passed only when BOTH portions,
# national and state, are passed at the same sitting. A single probability
# over a pooled 110-item score can report readiness while one portion fails.
# Each portion therefore gets its own ability posterior, partially pooled
# toward the learner's overall estimate, and readiness is the probability that
# both portions clear.

PORTION_ITEMS = {"National": 80, "NJ-Specific": 30}
PORTION_PASS_PCT = 70.0
PORTION_POOL_SD = 0.6        # how far a portion's ability may sit from overall


def portion_pass_probability(theta, se, items, n_exam, pass_pct=PORTION_PASS_PCT):
    """P(portion score >= pass_pct) integrating over N(theta, se^2). Pure."""
    if not items or n_exam <= 0:
        return None
    se = max(float(se or 0.0), 0.05)
    w = [math.exp(-0.5 * ((t - theta) / se) ** 2) for t in THETA_GRID]
    tw = sum(w)
    p = 0.0
    for t, wt in zip(THETA_GRID, w):
        wt /= tw
        if wt < 1e-7:
            continue
        ps = [irt_p3(t, a, b, GUESS_C) for a, b in items]
        mean_p = sum(ps) / len(ps)
        var = sum(x * (1 - x) for x in ps) / len(ps)
        e = mean_p * 100.0
        sd = math.sqrt(max(var * n_exam, 1e-9)) / n_exam * 100.0
        p += wt * (1.0 - _phi((pass_pct - e) / sd))
    return max(0.0, min(1.0, p))


def _portion_items(group):
    return [(q.get("a_irt", 1.0), q.get("b_irt", 0.0)) for q in QUIZ_LIST
            if TOPICS.get(q.get("topic"), {}).get("group") == group]


def _portion_pass_given_theta(items, n_exam, pass_pct=PORTION_PASS_PCT):
    """P(portion score >= pass_pct | theta) on THETA_GRID. No theta uncertainty
    here; the posterior supplies it."""
    out = []
    for t in THETA_GRID:
        ps = [irt_p3(t, a, b, GUESS_C) for a, b in items]
        e = sum(ps) / len(ps) * 100.0
        var = sum(x * (1 - x) for x in ps) / len(ps)
        sd = math.sqrt(max(var * n_exam, 1e-9)) / n_exam * 100.0
        out.append(1.0 - _phi((pass_pct - e) / sd))
    return out


def _loglik_grid(resp):
    ll = []
    for t in THETA_GRID:
        s = 0.0
        for a, b, c in resp:
            p = min(max(irt_p3(t, a, b, GUESS_C), 1e-9), 1 - 1e-9)
            s += math.log(p) if c else math.log(1 - p)
        ll.append(s)
    return ll


def _temper(resp, ll, prior_var):
    """Widen a portion's likelihood by the item-calibration inflation the
    pooled estimator already applies, as a power posterior: exponent
    v / (v + inflation), where v is the untempered posterior variance. With
    no responses there is nothing to widen."""
    if not resp:
        return ll, 1.0
    mx = max(ll)
    lp = [x - mx - 0.5 * (t - POPULATION_PRIOR_MU) ** 2 / prior_var
          for x, t in zip(ll, THETA_GRID)]
    m2 = max(lp)
    w = [math.exp(x - m2) for x in lp]
    tw = sum(w)
    mean = sum(t * x for t, x in zip(THETA_GRID, w)) / tw
    v = sum((t - mean) ** 2 * x for t, x in zip(THETA_GRID, w)) / tw
    good_a = [a for a, _b, _c in resp if a is not None and math.isfinite(a) and 0 < a <= 20]
    infl = calibration_inflation(len(resp), (sum(good_a) / len(good_a)) if good_a else 1.0)
    lam = v / (v + infl) if (v + infl) > 0 else 1.0
    return [x * lam for x in ll], lam


def joint_portion_readiness(resp_by_portion, items_by_portion,
                            prior_mu=None, prior_sd=None, tau=PORTION_POOL_SD):
    """P(national passes AND state passes) from a JOINT posterior over
    (theta_N, theta_S). Pure.

    Model: theta_g = mu + delta_g, mu ~ N(prior_mu, prior_sd^2), delta_g ~ N(0, tau^2).
    Integrating mu out gives a bivariate normal prior with variance
    prior_sd^2 + tau^2 and covariance prior_sd^2, so evidence on one portion
    informs the other through the shared ability -- and each response is
    counted exactly once, in its own portion's likelihood. The two portions
    are positively correlated a posteriori, so P(both) is computed on the
    joint grid rather than as a product of marginals."""
    mu = POPULATION_PRIOR_MU if prior_mu is None else prior_mu
    sd = POPULATION_PRIOR_SD if prior_sd is None else prior_sd
    var, cov = sd * sd + tau * tau, sd * sd
    det = var * var - cov * cov
    inv_a, inv_b = var / det, -cov / det            # inverse of [[var,cov],[cov,var]]
    gN, gS = "National", "NJ-Specific"
    llN, lamN = _temper(resp_by_portion.get(gN, []), _loglik_grid(resp_by_portion.get(gN, [])), var)
    llS, lamS = _temper(resp_by_portion.get(gS, []), _loglik_grid(resp_by_portion.get(gS, [])), var)
    pN = _portion_pass_given_theta(items_by_portion[gN], PORTION_ITEMS[gN])
    pS = _portion_pass_given_theta(items_by_portion[gS], PORTION_ITEMS[gS])
    dev = [t - mu for t in THETA_GRID]
    logw = [[-0.5 * (inv_a * dn * dn + 2 * inv_b * dn * ds + inv_a * ds * ds) + ln + ls
             for ds, ls in zip(dev, llS)] for dn, ln in zip(dev, llN)]
    mx = max(max(r) for r in logw)
    w = [[math.exp(x - mx) for x in r] for r in logw]
    tw = sum(sum(r) for r in w)
    p_both = pn_m = ps_m = en = es = enn = ess = ens = 0.0
    for i, r in enumerate(w):
        for j, x in enumerate(r):
            x /= tw
            p_both += x * pN[i] * pS[j]
            pn_m += x * pN[i]
            ps_m += x * pS[j]
            tn, ts = THETA_GRID[i], THETA_GRID[j]
            en += x * tn; es += x * ts
            enn += x * tn * tn; ess += x * ts * ts; ens += x * tn * ts
    vn, vs = max(enn - en * en, 1e-12), max(ess - es * es, 1e-12)
    return {"p_both": max(0.0, min(1.0, p_both)),
            "portions": {gN: pn_m, gS: ps_m},
            "abilities": {gN: {"theta": en, "se": math.sqrt(vn),
                               "n": len(resp_by_portion.get(gN, [])), "temper": lamN},
                          gS: {"theta": es, "se": math.sqrt(vs),
                               "n": len(resp_by_portion.get(gS, [])), "temper": lamS}},
            "correlation": (ens - en * es) / math.sqrt(vn * vs),
            "model": "joint_hierarchical_v1"}


def portion_responses(conn, group):
    topics = [tid for tid, t in TOPICS.items() if t.get("group") == group]
    if not topics:
        return []
    rows = _safe_query(conn, f"""SELECT question_id, a_irt, b_irt, correct, timestamp
        FROM attempts WHERE a_irt IS NOT NULL AND topic_id IN ({','.join('?' * len(topics))})
          AND (hint_level IS NULL OR hint_level < ?)
          AND {MEASUREMENT_MODE_SQL}
        ORDER BY id DESC LIMIT 600""", (*topics, HEAVY_HINT_THRESHOLD))
    rows = model_feed_filter(conn, rows)
    return [(r["a_irt"], r["b_irt"], r["correct"]) for r in rows
            if r["a_irt"] is not None and math.isfinite(r["a_irt"])]


def portion_readiness(conn):
    resp = {g: portion_responses(conn, g) for g in PORTION_ITEMS}
    items = {g: _portion_items(g) for g in PORTION_ITEMS}
    if not all(items.values()):
        return {"p_both": None, "portions": {}, "abilities": {}, "model": "unavailable"}
    return joint_portion_readiness(resp, items)


# ---- standing catalogue: the V8 classes -------------------------------------

def _probe_promotion_path_reachable(conn, inject=False):
    """Class: a governance tightening that removes the only path to the state
    it guards, so the human action it claims to require can no longer
    succeed."""
    saved = {k: set(v) for k, v in CANDIDATE_TRANSITIONS.items()}
    try:
        if inject:
            CANDIDATE_TRANSITIONS["approved"] = {"rejected"}
        init_candidate_schema(conn)
        cid = store_candidate(conn, {"q": "Probe?", "opts": ["a", "b", "c", "d"], "a": 1,
                                     "exp": "e", "topic": next(iter(TOPICS)),
                                     "skills": [next(iter(SKILLS))], "source": "",
                                     "family": "structural"}, generator="probe")
        set_candidate_state(conn, cid, "verified", "probe gates passed")
        aid = promote_candidate_as_asset(conn, cid, notes="probe human approval")
        if not aid:
            return False, "a verified candidate cannot be promoted by the human action"
        return True, "a verified candidate reaches the live bank through the Promote action"
    finally:
        CANDIDATE_TRANSITIONS.clear()
        CANDIDATE_TRANSITIONS.update(saved)


def _probe_observation_inside_window(conn, inject=False):
    """Class: a delayed observation labelled with a horizon it was not taken
    near, so a fit reads today's state as a 20-hour outcome."""
    init_trajectory_schema(conn)
    opened = datetime.now() - timedelta(days=20)
    conn.execute("INSERT INTO state_trajectories (learner, occasion_key, action, assignment, "
                 "state_before, opened_at) VALUES ('local','probe-old','retrieval','randomized',"
                 "'{}',?)", (opened.isoformat(),))
    conn.commit()
    tol = (lambda h: 1e9) if inject else None
    capture_trajectory_observations(conn, tolerance_fn=tol)
    bad = [r for r in _safe_query(conn, "SELECT horizon_hours, actual_delay_hours, status "
                                        "FROM trajectory_observations")
           if r["status"] == "captured" and r["actual_delay_hours"] is not None
           and r["actual_delay_hours"] > r["horizon_hours"] + trajectory_obs_tolerance_h(r["horizon_hours"])]
    if bad:
        return False, (f"{len(bad)} observation(s) captured outside their horizon window, "
                       f"e.g. {bad[0]['horizon_hours']:.0f}h at {bad[0]['actual_delay_hours']:.0f}h")
    n_missed = conn.execute("SELECT COUNT(*) FROM trajectory_observations "
                            "WHERE status='missed'").fetchone()[0]
    return True, f"a 20-day-old occasion records {n_missed} missed horizons and no mislabelled state"


def _probe_unpromoted_grader(conn, inject=False):
    """Class: a new evidence producer that changes the learner's record on the
    day it is switched on, before any promotion."""
    decide = (lambda g, l, r: (g["score_pct"], "gpu", g["score_pct"])) if inject \
        else free_recall_score_decision
    res = {"uncertain": False, "score_pct": 92.0}
    score, _m, shadow = decide(res, 41.0, "canary")
    if score != 41.0:
        return False, f"at canary the fabric grade ({score}) entered the record"
    score2, _m2, _s2 = decide(res, 41.0, "active")
    return True, (f"canary keeps the incumbent score (41.0, shadow {shadow}); "
                  f"active uses the fabric grade ({score2})")


def _probe_readiness_by_portion(conn, inject=False):
    """Class: a readiness claim over a pooled score for an examination passed
    portion by portion."""
    items = {"National": [(1.0, -0.5)] * 40, "NJ-Specific": [(1.0, -0.5)] * 20}
    resp = {"National": [(1.0, -0.5, 1)] * 36 + [(1.0, -0.5, 0)] * 4,
            "NJ-Specific": [(1.0, -0.5, 1)] * 7 + [(1.0, -0.5, 0)] * 9}
    joint = joint_portion_readiness(resp, items)
    p_state = joint["portions"]["NJ-Specific"]
    if inject:
        pooled_resp = resp["National"] + resp["NJ-Specific"]
        ll = _loglik_grid(pooled_resp)
        lp = [x - 0.5 * ((t - POPULATION_PRIOR_MU) / POPULATION_PRIOR_SD) ** 2
              for x, t in zip(ll, THETA_GRID)]
        m = max(lp)
        w = [math.exp(x - m) for x in lp]
        tw = sum(w)
        th = sum(t * x for t, x in zip(THETA_GRID, w)) / tw
        se = math.sqrt(sum((t - th) ** 2 * x for t, x in zip(THETA_GRID, w)) / tw)
        p = portion_pass_probability(th, se, items["National"] + items["NJ-Specific"], 110)
    else:
        p = joint["p_both"]
    if p is None or p > p_state + 1e-9:
        return False, (f"readiness {p:.2f} exceeds the state portion's own "
                       f"pass probability {p_state:.2f}")
    return True, f"strong national, weak state: readiness {p:.2f} <= state portion {p_state:.2f}"


register_adversarial_class("promotion_path_unreachable", {
    "title": "A governance rule that removes the path it guards",
    "failure_class": ("A transition table tightened in the name of human approval "
                      "that leaves the approval action unable to succeed, so the "
                      "factory's output can never be served."),
    "invariant": "A verified candidate reaches the live bank through the human Promote action.",
    "found_in": "Review of a V6 rewrite that removed verified -> promoted.",
    "probe": _probe_promotion_path_reachable,
})

register_adversarial_class("observation_outside_horizon_window", {
    "title": "A delayed observation filed under the wrong horizon",
    "failure_class": ("Observations captured whenever a sweep happens to run, stamped "
                      "with every overdue horizon, so today's state is read as a "
                      "20-hour, 72-hour and 168-hour outcome at once."),
    "invariant": ("A captured observation lies within its horizon's window; an "
                  "expired window is recorded as missed with no state."),
    "found_in": "Review of a V6 rewrite's multi-horizon capture.",
    "probe": _probe_observation_inside_window,
})

register_adversarial_class("unpromoted_grader_moves_record", {
    "title": "An evidence producer live before promotion",
    "failure_class": ("A grader, scorer or judge that changes how evidence is produced "
                      "the moment it is enabled, with no canary and no shadow period."),
    "invariant": "Below the active rung, the incumbent score enters the record and the new one is shadowed.",
    "found_in": "V7 private-GPU grading audit.",
    "probe": _probe_unpromoted_grader,
})

register_adversarial_class("readiness_over_pooled_score", {
    "title": "Readiness claimed on a pooled score",
    "failure_class": ("One probability over a combined score for an examination that "
                      "must be passed portion by portion."),
    "invariant": "Readiness never exceeds the weakest portion's own pass probability.",
    "found_in": "V7 audit of predict_pass_probability.",
    "probe": _probe_readiness_by_portion,
})


