from dataclasses import dataclass
from types import MappingProxyType as _Frozen


# ---- 1. assignment as a record, not a string --------------------------------

@dataclass(frozen=True)
class AssignmentRecord:
    """How one occasion's treatment was chosen.

    mechanism 'randomized': hashed over the arms available on this occasion;
    propensity is known by design and arm_set is exactly those arms.
    mechanism 'settled': the trial has concluded and returns its winner
    deterministically; there is no randomization, so no propensity, and the
    occasion is policy evidence, not trial evidence."""
    trial: str
    key: str
    arm: str
    mechanism: str
    propensity: object = None
    arm_set: tuple = ()

    @property
    def randomized(self):
        return self.mechanism == "randomized"


def intervention_assignment(conn, name, key, candidates=None, state_tag=None, subject=None):
    spec = INTERVENTION_TRIALS.get(name)
    if not spec or getattr(_GOV_LOCAL, "replay", False):
        return None
    status = intervention_trial_status(conn, name)
    if status["settled"] is not None:
        if candidates is not None and status["settled"] not in candidates:
            return None
        return AssignmentRecord(trial=name, key=str(key), arm=status["settled"],
                                mechanism="settled", propensity=None,
                                arm_set=(status["settled"],))
    arms = [a for a in status["active_arms"] if candidates is None or a in candidates]
    if len(arms) < 2:
        return None
    h = hashlib.sha256(f"intervention-{name}-{key}".encode()).hexdigest()
    arm = arms[int(h[:8], 16) % len(arms)]
    prop, arm_set = 1.0 / len(arms), tuple(arms)
    try:
        init_intervention_trial_schema(conn)
        _ensure_column(conn, "intervention_occasions", "propensity", "REAL")
        _ensure_column(conn, "intervention_occasions", "arm_set", "TEXT")
        conn.execute("INSERT OR IGNORE INTO intervention_occasions "
                     "(name, key, arm, subject, state_tag, assigned_at, propensity, arm_set) "
                     "VALUES (?,?,?,?,?,?,?,?)",
                     (name, str(key), arm, None if subject is None else str(subject),
                      None if state_tag is None else str(state_tag),
                      datetime.now().isoformat(), prop, json.dumps(arms)))
        conn.commit()
        row = _safe_query(conn, "SELECT arm, propensity, arm_set FROM intervention_occasions "
                                "WHERE name=? AND key=?", (name, str(key)))
        if row:
            # An occasion already assigned keeps its arm AND the design it was
            # assigned under; a later change in available arms does not
            # rewrite what the original draw was.
            arm = row[0]["arm"]
            if row[0]["propensity"] is not None:
                prop = float(row[0]["propensity"])
            try:
                arm_set = tuple(json.loads(row[0]["arm_set"])) if row[0]["arm_set"] else arm_set
            except (TypeError, ValueError):
                pass
    except sqlite3.Error as e:
        _audit(conn, "intervention_assign_failed", f"{name} {type(e).__name__}: {e}")
    return AssignmentRecord(trial=name, key=str(key), arm=arm, mechanism="randomized",
                            propensity=prop, arm_set=arm_set)


# ---- 2. human approval as a privileged, atomic operation ---------------------

_HUMAN_APPROVAL = object()          # module-private authority token
PRIVILEGED_CANDIDATE_MOVES = {("verified", "approved"), ("approved", "promoted")}


def approve_and_promote_candidate(conn, candidate_id, note):
    """verified -> approved -> promoted in ONE transaction, plus the live
    asset. Nothing is committed unless every step succeeds."""
    rows = _safe_query(conn, "SELECT * FROM candidate_items WHERE candidate_id=?",
                       (candidate_id,))
    if not rows or rows[0]["state"] not in ("verified", "approved"):
        return None, (rows[0]["state"] if rows else "missing")
    r = rows[0]
    now = datetime.now().isoformat()
    try:
        if r["state"] == "verified":
            conn.execute("UPDATE candidate_items SET state='approved', reviewed_at=?, "
                         "reviewer_note=? WHERE candidate_id=? AND state='verified'",
                         (now, ("human approved: " + note)[:300], candidate_id))
        cur = conn.execute("UPDATE candidate_items SET state='promoted', reviewed_at=?, "
                           "reviewer_note=? WHERE candidate_id=? AND state='approved'",
                           (now, note[:300], candidate_id))
        if cur.rowcount != 1:
            raise sqlite3.IntegrityError("candidate changed state during approval")
        return r, None
    except sqlite3.Error as e:
        conn.rollback()
        return None, f"{type(e).__name__}: {e}"


# ---- 3. versioned cognitive state ---------------------------------------------

COGNITIVE_STATE_SCHEMA = "recursa.cognitive_state.v1"
COGNITIVE_STATE_FIELDS = {
    "learner_state": ("skills", "n_solid", "phase"),
    "measurement_state": ("theta", "n_measured", "portions", "calibration", "pressure",
                          "model_disagreement"),
    "context_state": ("days_to_exam", "hour_local", "weekday", "attempts_total"),
    "uncertainty": ("theta_se", "portion_se"),
    "missingness": (),
    "model_versions": ("cognitive_state", "fsrs_library", "grader_rung", "readiness_model"),
}


@dataclass(frozen=True)
class CognitiveStateV1:
    at: str
    learner_state: object
    measurement_state: object
    context_state: object
    uncertainty: object
    missingness: object
    model_versions: object
    schema: str = COGNITIVE_STATE_SCHEMA

    def to_dict(self):
        d = {"schema": self.schema, "at": self.at}
        for ns in COGNITIVE_STATE_FIELDS:
            d[ns] = json.loads(json.dumps(dict(getattr(self, ns)), default=str))
        # Compatibility mirror for V6-V8 readers of the flat snapshot.
        ls, ms, un = d["learner_state"], d["measurement_state"], d["uncertainty"]
        d.update({"skills": ls.get("skills", {}), "n_solid": ls.get("n_solid"),
                  "phase": ls.get("phase"), "theta": ms.get("theta"),
                  "theta_se": un.get("theta_se"), "n_measured": ms.get("n_measured")})
        return d


def validate_cognitive_state(d):
    """Problems with a snapshot dict: wrong or absent schema, a missing
    namespace, or a declared field that is neither present nor explained in
    missingness. Absent-and-explained is valid; absent-and-silent is drift."""
    problems = []
    if not isinstance(d, dict) or d.get("schema") != COGNITIVE_STATE_SCHEMA:
        return [f"schema is {None if not isinstance(d, dict) else d.get('schema')!r}"]
    miss = d.get("missingness") or {}
    for ns, fields in COGNITIVE_STATE_FIELDS.items():
        if not isinstance(d.get(ns), dict):
            problems.append(f"namespace {ns} missing")
            continue
        for f in fields:
            if f not in d[ns] and f"{ns}.{f}" not in miss:
                problems.append(f"{ns}.{f} absent without a missingness reason")
    return problems


def trajectory_state_snapshot(conn):
    """The inferred state as CognitiveStateV1, serialised. Every gather
    degrades to an ABSENT field with its reason in `missingness`; a reading
    that could not be taken is never recorded as a number."""
    L, M, X, U, V, miss = {}, {}, {}, {}, {}, {}
    today_iso = date.today().isoformat()

    def _gather(path, fn):
        try:
            fn()
        except Exception as e:                       # recorded, never silent
            miss[path] = f"{type(e).__name__}: {str(e)[:80]}"

    def _skills():
        L["skills"] = {}
        for sid, st in _skill_rows(conn).items():
            v = _contract_skill_vector(st, today_iso)
            L["skills"][sid] = {
                "reps": v["attempts"], "streak": v["initial_streak"],
                "relearn": v["relearn_sessions"], "solid": bool(v["relearn_complete"]),
                "recall": None if v["recall"] is None else round(v["recall"], 3),
                "due": bool(v["due"]),
                # enough of the scheduler state to reconstruct decay later
                "fsrs": {k: st.get(k) for k in ("state", "step", "stability", "difficulty",
                                                "due_date", "last_reviewed", "half_life")}}
        L["n_solid"] = sum(1 for s in L["skills"].values() if s["solid"])
    _gather("learner_state.skills", _skills)
    if "skills" not in L:
        miss.setdefault("learner_state.n_solid", "skills unavailable")
    _gather("learner_state.phase", lambda: L.__setitem__("phase", learner_phase(conn)))

    def _theta():
        th, se, n = ability_with_se(conn)[:3]
        M["theta"] = None if th is None else round(float(th), 3)
        U["theta_se"] = None if se is None else round(float(se), 3)
        M["n_measured"] = n
    _gather("measurement_state.theta", _theta)
    if "theta" not in M:
        miss.setdefault("measurement_state.n_measured", "theta unavailable")
        miss.setdefault("uncertainty.theta_se", "theta unavailable")

    def _portions():
        pr = portion_readiness(conn)
        M["portions"] = {g: {"theta": round(a["theta"], 3), "n": a["n"]}
                         for g, a in pr.get("abilities", {}).items()}
        U["portion_se"] = {g: round(a["se"], 3) for g, a in pr.get("abilities", {}).items()}
        V["readiness_model"] = pr.get("model")
    _gather("measurement_state.portions", _portions)
    if "portions" not in M:
        miss.setdefault("uncertainty.portion_se", "portions unavailable")
        miss.setdefault("model_versions.readiness_model", "portions unavailable")

    def _cal():
        cal = calibration_metrics(conn)
        M["calibration"] = ({k: cal.get(k) for k in ("ece", "brier", "resolution", "n")}
                            if cal else None)
    _gather("measurement_state.calibration", _cal)

    def _pressure():
        prof = pressure_profile(conn)
        M["pressure"] = {"gap": prof.get("penalty"), "accuracy_gap": prof.get("acc_gap"),
                         "confident": bool(prof.get("confident")),
                         "pressure_limited": bool(prof.get("pressure_limited"))}
    _gather("measurement_state.pressure", _pressure)

    def _disagree():
        out = {}
        for tid in TOPICS:
            bm = blended_mastery(conn, tid)
            if bm and len(bm) >= 4:
                out[tid] = {"blend": bm[0], "bkt": bm[1], "pfa": bm[2], "disagreement": bm[3]}
        M["model_disagreement"] = out
    _gather("measurement_state.model_disagreement", _disagree)

    now = datetime.now()
    _gather("context_state.days_to_exam", lambda: X.__setitem__("days_to_exam", days_to_exam(conn)))
    X["hour_local"], X["weekday"] = now.hour, now.weekday()
    _gather("context_state.attempts_total", lambda: X.__setitem__(
        "attempts_total", conn.execute("SELECT COUNT(*) FROM attempts").fetchone()[0]))

    V["cognitive_state"] = COGNITIVE_STATE_SCHEMA
    V["fsrs_library"] = bool(FSRS_AVAILABLE)
    _gather("model_versions.grader_rung", lambda: V.__setitem__(
        "grader_rung", get_setting(conn, GRADER_SETTING_RUNG, "canary") or "canary"))

    snap = CognitiveStateV1(at=now.isoformat(), learner_state=_Frozen(L),
                            measurement_state=_Frozen(M), context_state=_Frozen(X),
                            uncertainty=_Frozen(U), missingness=_Frozen(miss),
                            model_versions=_Frozen(V)).to_dict()
    return snap


# ---- 4. the legacy export, marked as what it is -------------------------------

def transition_training_set(conn, include_open=False):
    """DEPRECATED name. Returns the legacy descriptive export with its
    limitations stated in the payload; causal work reads
    trajectory_observation_set()."""
    out = legacy_descriptive_transition_training_set(conn, include_open=include_open)
