# Exception marks in priority order. The low-evidence halo is a background
# treatment, never a mark, so it does not spend the budget.
MARK_PRIORITY = ("repair", "retest", "review", "moving")
MARK_TEXT = {"repair": "a mix-up being repaired", "retest": "a confident miss coming back",
             "review": "review due", "moving": "can move forward today"}
MARK_SYMBOL = {"repair": "\u2726", "retest": "\u21ba", "review": "\u25f7", "moving": "\u25b8"}
LOD_MARK_BUDGET = {"course": 0, "domain": 1, "skill": None}


def node_marks(node):
    """All exception marks for a node, in priority order."""
    have = set(node.get("overlays") or ())
    if node.get("tier") == TIER_REVIEW_SOON:
        have.add("review")
    return [m for m in MARK_PRIORITY if m in have]


def marks_for_lod(node, lod):
    budget = LOD_MARK_BUDGET[lod]
    marks = node_marks(node)
    return marks if budget is None else marks[:budget]


