from tkinter import ttk


def vis_reduced_motion(conn):
    try:
        return get_setting(conn, "reduce_motion", "0") == "1"
    except Exception:
        return False


def vis_animate(widget, duration_ms, step, done=None, reduced=False):
    """Ease-out tween. Under reduced motion the end state is drawn at once."""
    if reduced or duration_ms <= 0:
        step(1.0)
        if done:
            done()
        return
    t0 = time.time()

    def tick():
        try:
            if not widget.winfo_exists():
                return
        except tk.TclError:
            return
        t = min(1.0, (time.time() - t0) * 1000.0 / duration_ms)
        step(1 - (1 - t) ** 3)
        if t < 1.0:
            widget.after(16, tick)
        elif done:
            done()
    tick()


def vis_draw_glyph(cv, x, y, r, glyph, overlays=(), tags=(), dim=False, fill_override=None,
                   focus=False):
    P = VIS_PALETTE
    fill = glyph["fill"] if fill_override is None else fill_override
    fill_col = P["outline_empty"] if dim else P["fill"]
    if "little_evidence" in overlays and not dim:
        cv.create_oval(x - r - 5, y - r - 5, x + r + 5, y + r + 5, outline=P["halo"],
                       dash=(2, 3), tags=tags)
    if "mixed_evidence" in overlays and not dim:
        # Contradicted evidence: a dash-dot ring, a different shape from the
        # dotted 'little evidence' halo, so the two never read alike.
        cv.create_oval(x - r - 5, y - r - 5, x + r + 5, y + r + 5, outline=P["halo"],
                       dash=(8, 3, 2, 3), width=2, tags=tags)
    if glyph["outer"]:
        cv.create_oval(x - r - 7, y - r - 7, x + r + 7, y + r + 7,
                       outline=(P["outline_empty"] if dim else P["outer"]), width=2, tags=tags)
    kw = {"dash": (3, 2)} if glyph["dash"] else {}
    cv.create_oval(x - r, y - r, x + r, y + r, fill=P["fill_track"],
                   outline=(P["outline_empty"] if glyph["dash"] or dim else P["outline"]),
                   width=1, tags=tags, **kw)
    inset = max(1.5, r * 0.14)
    if fill >= 0.999:
        cv.create_oval(x - r + inset, y - r + inset, x + r - inset, y + r - inset,
                       fill=fill_col, outline="", tags=tags)
    elif fill > 0.001:
        cv.create_arc(x - r + inset, y - r + inset, x + r - inset, y + r - inset, start=90,
                      extent=-359.9 * fill, fill=fill_col, outline="", style="pieslice", tags=tags)
    if glyph["ring"]:
        cv.create_oval(x - r - 3, y - r - 3, x + r + 3, y + r + 3,
                       outline=(P["outline_empty"] if dim else P["ring"]), width=2, tags=tags)
    if glyph["clock"]:
        cr = max(4, r * 0.5)
        cx, cy = x + r * 0.8, y - r * 0.8
        cv.create_oval(cx - cr, cy - cr, cx + cr, cy + cr, fill=P["surface"], outline=P["clock"],
                       width=1.5, tags=tags)
        cv.create_line(cx, cy, cx, cy - cr * 0.65, fill=P["clock"], width=1.5, tags=tags)
        cv.create_line(cx, cy, cx + cr * 0.5, cy, fill=P["clock"], width=1.5, tags=tags)
    fs = max(7, int(r * 0.75))
    if "repair" in overlays:
        cv.create_text(x + r * 0.95, y + r * 0.9, text="\u2726", fill=P["repair"],
                       font=(FONT_BODY, fs, "bold"), tags=tags)
    if "retest" in overlays:
        cv.create_text(x - r * 0.95, y + r * 0.9, text="\u21ba", fill=P["retest"],
                       font=(FONT_BODY, fs, "bold"), tags=tags)
    if "moving" in overlays:
        cv.create_text(x + r + fs * 0.7, y, text="\u25b8", fill=P["focus"],
                       font=(FONT_BODY, fs), tags=tags)
    if focus:
        cv.create_rectangle(x - r - 10, y - r - 10, x + r + 10, y + r + 10, outline=P["focus"],
                            dash=(2, 2), tags=tags)


class VisCanvasTip:
    """A tooltip drawn on the canvas itself: no extra windows, no focus steal."""
    def __init__(self, cv):
        self.cv = cv

    def show(self, x, y, lines):
        self.hide()
        text = "\n".join(l for l in lines if l)
        if not text:
            return
        t = self.cv.create_text(x + 14, y + 12, text=text, anchor="nw", fill=C.CREAM,
                                font=(FONT_BODY, 10), width=260, tags=("vis_tip",))
        x0, y0, x1, y1 = self.cv.bbox(t)
        w = int(self.cv.winfo_width() or 800)
        h = int(self.cv.winfo_height() or 600)
        dx = min(0, w - x1 - 6)
        dy = min(0, h - y1 - 6)
        self.cv.move(t, dx, dy)
        x0, y0, x1, y1 = self.cv.bbox(t)
        r = self.cv.create_rectangle(x0 - 7, y0 - 5, x1 + 7, y1 + 5, fill=C.NAVY, outline="",
                                     tags=("vis_tip",))
        self.cv.tag_raise(t, r)

    def hide(self):
        self.cv.delete("vis_tip")


# ---- sessions started from the visual surfaces -------------------------------

def vis_items_for_skills(conn, sids, per_skill=2, limit=12):
    try:
        today_q = {r["question_id"] for r in _safe_query(
            conn, "SELECT DISTINCT question_id FROM attempts WHERE substr(timestamp,1,10) >= ?",
            (date.today().isoformat(),))}
    except Exception:
        today_q = set()
    items = []
    for sid in sids:
        qs = sorted(items_for_skill(sid), key=lambda q: (q["id"] in today_q, q["id"]))
        for q in qs[:per_skill]:
            if len(items) < limit and all(i["q"]["id"] != q["id"] for i in items):
                items.append({"q": q, "movement": "work", "pretest": False, "retest": False,
                              "skill": sid})
    return items


def vis_launch_session(app, parent, plan, title, subtitle, back_view="map", meta=None):
    """Start a session and capture the learner-facing state before it, so the
    debrief can report Learning Events rather than only tier changes."""
    conn = app.conn
    try:
        before = vis_snapshot(conn)
    except Exception:
        before = None
    served = sorted({it.get("skill") for it in plan["items"] if it.get("skill")})
    log_exploration_items(conn, plan)

    def on_finish(summary):
        summary.update(meta or {})
        if before is not None:
            summary["vis_before"] = before
            summary["tiers_before"] = before["tiers"]
            summary["vis_served"] = served
        complete_session_events(conn, summary)
        render_result_screen(app, parent, summary, lambda: app.show_view(back_view))
    for w in parent.winfo_children():
        w.destroy()
    QuestionSession(app, parent, None, "quiz", title, subtitle, allow_hints=False,
                    collect_diagnostics=False, composed_plan=plan, on_finish=on_finish)


def vis_start_practice(app, parent, sids, title, subtitle_extra="", meta=None):
    conn = app.conn
    items = vis_items_for_skills(conn, sids)
    if not items:
        app.toast("No questions are available for that yet.", kind="info")
        return
    plan = {"items": items, "n_items": len(items), "est_minutes": max(2, len(items)),
            "retest_max": 0, "focus_topic": SKILLS.get(sids[0], {}).get("topic"), "phase": None,
            "planned_mean_p": None}
    vis_launch_session(app, parent, plan, title,
                       f"{_plural(len(items), 'question')} · untimed" + subtitle_extra, meta=meta)


def vis_start_constrained(app, parent, tid, back_view="map", minutes=None, meta=None):
    plan = compose_area_session(app.conn, tid, minutes)
    if plan and not plan.get("items"):
        plan = None
    name = TOPICS[tid].get("short") or TOPICS[tid]["name"]
    if not plan:
        app.toast(f"Nothing in {name} can be put into a session right now.", kind="info")
        return
    stages = " \u2192 ".join(st["title"] for st in present_session_trajectory(plan))
    vis_launch_session(app, parent, plan, f"Session: {name}",
                       f"{_plural(plan['n_items'], 'question')} · {stages}", back_view=back_view, meta=meta)


def vis_distinction_context(sid_a, sid_b):
    parts, why = [], ""
    for p in vis_confusion_pairs():
        if {p["a"], p["b"]} == {sid_a, sid_b}:
            why = p["why"]
    for sid in (sid_a, sid_b):
        qs = items_for_skill(sid)
        exp = qs[0]["exp"] if qs else ""
        parts.append(f"{SKILLS[sid]['label']}: {exp}")
    return why, "\n\n".join(parts)


def vis_explain_distinction(app, sid_a, sid_b, out_label):
    """Tell two skills apart. Offline: the authored explanations and reason,
    side by side. With the compute fabric: a short contrast written only from
    that material, with its legal claims checked by a model of another family.
    With only an API key: the same contrast, labelled as not independently
    checked."""
    conn = app.conn
    why, context = vis_distinction_context(sid_a, sid_b)
    offline = ((why + "\n\n") if why else "") + context
    cfg = gpu_config(conn)
    api = get_setting(conn, "anthropic_api_key", "") or ""
    out_label.configure(text=offline)
    if not cfg and not api:
        return
    out_label.configure(text=offline + "\n\nWriting a short contrast\u2026")
    sys_p = ("You explain the difference between two New Jersey real-estate concepts for a "
             "licensing candidate. Use ONLY the MATERIAL. Three short sentences: what each is, "
             "and the one question that tells them apart. No citations not in the material.")
    user = "MATERIAL:\n" + offline
    holder = {}

    def work():
        if cfg:
            used = {}
            text, err = gpu_chat(cfg, "generator", sys_p, user, max_tokens=260,
                                 parse_json=False, used=used)
            if text:
                claims = extract_legal_claims(text)
                verdicts, verr = gpu_verify_claims(cfg, claims, offline,
                                                   exclude_family=used.get("family"))
                text = annotate_grounding(text, gpu_ungrounded_citations(text, offline),
                                          claims, verdicts, verr)
            holder["text"], holder["err"] = text, err
        else:
            text, err = _anthropic_call(api, sys_p, user, max_tokens=260, parse_json=False)
            holder["text"] = (text + "\n\n[Not independently checked.]") if text else None
            holder["err"] = err
    import threading
    t = threading.Thread(target=work, daemon=True)
    t.start()

    def poll():
        if t.is_alive():
            out_label.after(200, poll)
            return
        try:
            if not out_label.winfo_exists():
                return
        except tk.TclError:
            return
        if holder.get("text"):
            out_label.configure(text=holder["text"] + "\n\nFrom the course material:\n" + offline)
        else:
            out_label.configure(text=offline)
    out_label.after(200, poll)


# ---- the map ---------------------------------------------------------------------

def vis_draw_node(cv, x, y, r, node, lod, tags=(), dim=False, focus=False, style="dashed"):
    """A skill at area level: coarse glyph, the low-evidence halo as background,
    and at most LOD_MARK_BUDGET marks as a badge. Resolution rises by zoom."""
    thin = "little_evidence" in (node.get("overlays") or ())
    if thin and style == "faded" and not dim:
        # Faded encoding: a lighter fill instead of the dashed halo (study-kit variant).
        saved = VIS_PALETTE["fill"]
        VIS_PALETTE["fill"] = _blend_hex(saved, VIS_PALETTE.get("fill_track", C.PAPER), FADED_BLEND)
        try:
            vis_draw_glyph(cv, x, y, r, node["coarse_glyph"], (), tags=tags, dim=dim, focus=focus)
        finally:
            VIS_PALETTE["fill"] = saved
    else:
        rings = tuple(o for o in ("little_evidence", "mixed_evidence") if o in (node.get("overlays") or ()))
        vis_draw_glyph(cv, x, y, r, node["coarse_glyph"], rings, tags=tags, dim=dim, focus=focus)
    for i, m in enumerate(marks_for_lod(node, lod)):
        bx, by = x + r * 0.95, y - r * 0.95 + i * r * 0.9
        br = max(6, r * 0.55)
        cv.create_oval(bx - br, by - br, bx + br, by + br, fill=C.PAPER, outline=VIS_PALETTE["clock"],
                       width=1.5, tags=tags)
        cv.create_text(bx, by, text=MARK_SYMBOL[m], fill=VIS_PALETTE["clock"],
                       font=(FONT_BODY, max(7, int(br * 1.1)), "bold"), tags=tags)


def vis_draw_rail(cv, x0, y0, x1, h, rail, dim=False):
    """Coarse-state counts as one horizontal rail. Strong is anchored at the
    left edge and Not started at the right edge, so both extremes share a
    baseline across areas. Segments differ by fill pattern as well as tone,
    and the counts are printed beside the rail, so colour is never needed."""
    total = max(1, rail["total"])
    width = x1 - x0
    x = x0
    style = {COARSE_STRONG: (C.NAVY, None), COARSE_BUILDING: (C.NAVY_3, "hatch"),
             COARSE_STARTED: (C.GOLD_SOFT, "dots"), COARSE_NOT_STARTED: (C.PAPER, "dash")}
    for seg in rail["segments"]:
        if not seg["n"]:
            continue
        w = width * seg["n"] / total
        fill, pat = style[seg["state"]]
        if dim:
            fill = C.PAPER_LINE if seg["state"] != COARSE_NOT_STARTED else C.PAPER
        kw = {"dash": (3, 2)} if pat == "dash" else {}
        cv.create_rectangle(x, y0, x + w, y0 + h, fill=fill, outline=C.INK_DIM, width=1, **kw)
        if pat == "hatch" and w > 6:
            for hx in range(int(x) + 3, int(x + w), 6):
                cv.create_line(hx, y0 + h - 1, min(hx + h - 2, x + w - 1), y0 + 1, fill=C.PAPER_DIM)
        elif pat == "dots" and w > 6:
            for hx in range(int(x) + 3, int(x + w) - 1, 5):
                cv.create_oval(hx - 1, y0 + h / 2 - 1, hx + 1, y0 + h / 2 + 1, fill=C.INK_DIM, outline="")
        x += w


def vis_announce(app, text):
    """One route for anything a screen reader should hear. The status line is
    a plain ttk label (read by Tk's accessibility support where the Tk build
    has it); when the learner turns on spoken announcements, the same text is
    also sent to the platform's speech, because a Tk 8.6 build exposes little
    to screen readers on its own. Only contract vocabulary is passed."""
    if not text or VIS_FORBIDDEN.search(text):
        return False
    try:
        var = getattr(app, "_vis_status_var", None)
        if var is not None:
            var.set(text)
    except Exception:
        pass
    try:
        if get_setting(app.conn, "speak_announcements", "0") != "1":
            return True
    except Exception:
        return True
    try:
        from accessible_output2.outputs.auto import Auto  # optional
        Auto().output(text)
        return True
    except Exception:
        pass
    import shutil
    import subprocess
    cmd = None
    if sys.platform == "darwin" and shutil.which("say"):
        cmd = ["say", text]
    elif os.name == "nt":
        cmd = ["powershell", "-NoProfile", "-Command",
               "Add-Type -AssemblyName System.Speech; (New-Object System.Speech.Synthesis."
               "SpeechSynthesizer).Speak($args[0])", text]
    elif shutil.which("spd-say"):
        cmd = ["spd-say", text]
    if cmd:
        try:
            subprocess.Popen(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except Exception:
            pass
    return True


def vis_legend(parent):
    holder = ctk.CTkFrame(parent, fg_color="transparent")
    body = card(holder, fg_color=C.PAPER_DIM)
    cv = tk.Canvas(body, height=150, bg=C.PAPER_DIM, highlightthickness=0, width=300)
    cv.pack(fill="x", padx=12, pady=8)
    cv.create_text(8, 10, anchor="w", text="Each skill", font=(FONT_BODY, 9, "bold"), fill=C.INK)
    for i, c in enumerate((COARSE_NOT_STARTED, COARSE_STARTED, COARSE_BUILDING, COARSE_STRONG)):
        x = 26 + i * 70
        vis_draw_glyph(cv, x, 34, 10, COARSE_GLYPH[c])
        cv.create_text(x, 56, text=c.lower(), font=(FONT_BODY, 9), fill=C.INK_DIM)
    cv.create_text(8, 78, anchor="w", text="One mark, most important first", font=(FONT_BODY, 9, "bold"), fill=C.INK)
    for i, m in enumerate(MARK_PRIORITY):
        x = 16 + (i % 2) * 150
        y = 98 + (i // 2) * 20
        cv.create_text(x, y, anchor="w", text=f"{MARK_SYMBOL[m]}  {MARK_TEXT[m]}", font=(FONT_BODY, 9), fill=C.INK_DIM)
    cv.create_text(8, 140, anchor="w", text="Dotted halo: not much evidence · dash-dot: results mixed lately",
                   font=(FONT_BODY, 9), fill=C.INK_DIM)
    state = {"open": False}
    btn = ghost_button(holder, "How to read the map", None, width=170)

    def flip():
        state["open"] = not state["open"]
        if state["open"]:
            body.pack(fill="x", pady=(6, 0))
            btn.configure(text="Hide the key")
        else:
            body.pack_forget()
            btn.configure(text="How to read the map")
    btn.configure(command=flip)
    btn.pack(anchor="w")
    return holder


MAP_STATE_SETTING = "map_view_state"
VIS_MAP_FILTERS = ("All", "Moving", "Review", "Repairs", "Not started")
VIS_EDGE_MODES = ("On selection", "All", "Off")
MAP_DRAWER_BREAKPOINT = 960      # below this body width the inspector becomes a drawer
MAP_MIN_CANVAS = 560             # the map never docks narrower than this
MAP_PANEL_WIDTH = 330


def vis_node_matches(node, flt):
    if flt == "All":
        return True
    if flt == "Moving":
        return "moving" in node["overlays"] or node["coarse"] == COARSE_BUILDING
    if flt == "Review":
        return node["tier"] == TIER_REVIEW_SOON
    if flt == "Repairs":
        return "repair" in node["overlays"] or "retest" in node["overlays"]
    if flt == "Not started":
        return node["tier"] == TIER_NOT_STARTED
    return True


def vis_edges_to_draw(links, mode, focus_sids):
    """Which links an area view draws: none, all, or only those touching the
    selected (or hovered) skills. The graph is never drawn whole by default."""
    if mode == "Off":
        return {"confusions": [], "stubs": [], "prereqs": []}
    if mode == "All":
        return links
    f = set(s for s in focus_sids if s)
    return {"confusions": [c for c in links["confusions"] if c["a"] in f or c["b"] in f],
            "stubs": [s for s in links["stubs"] if s["inside"] in f],
            "prereqs": [p for p in links["prereqs"] if p["pre"] in f or p["dep"] in f]}


class CourseMap(ctk.CTkFrame):
    """Course -> area -> skill, one object that zooms, with a synchronized
    list mirror, search, persistent state, a visible compare mode, edges on
    demand, and an inspector that docks or slides over by width."""

    def __init__(self, parent, app, vs=None, compact=False, height=520, on_navigate=None,
                 persist=True, depth="Standard"):
        super().__init__(parent, fg_color="transparent")
        self.app, self.conn, self.compact = app, app.conn, compact
        self.depth = depth if depth in DEPTH_ORDER else "Standard"
        self.show = set(blocks_for("map", self.depth))
        self.vs = vs if vs is not None else gather_visual_state(self.conn)
        self.domains = {d["tid"]: d for d in present_course_map(self.vs)}
        self.nodes = {n["sid"]: n for d in self.domains.values() for n in d["nodes"]}
        self.edges = vis_prereq_edges(self.conn)
        self.graph = build_nav_graph(self.domains, self.edges)
        _lf = tkfont.Font(family=FONT_BODY, size=9, weight="bold")
        self._label_measure, self._label_linespace = _lf.measure, _lf.metrics("linespace")
        self.level, self.tid, self.sid, self.compare_sid = "course", None, None, None
        self.flt, self.focus_idx, self.kb = "All", 0, False
        self.edge_mode, self.hover_sid, self.compare_pending = "On selection", None, False
        self.hit, self.history = [], []
        self.reduced = vis_reduced_motion(self.conn)
        self.on_navigate = on_navigate
        self.persist = persist and not compact
        self.drawer = False
        self.mirror = None
        if not compact:
            top = ctk.CTkFrame(self, fg_color="transparent")
            top.pack(fill="x", pady=(0, 6))
            self.crumbs = ctk.CTkFrame(top, fg_color="transparent")
            self.crumbs.pack(side="left")
            right = ctk.CTkFrame(top, fg_color="transparent")
            right.pack(side="right")
            self.search_var = tk.StringVar()
            self.search_entry = ttk.Entry(right, textvariable=self.search_var, width=22)
            self.search_entry.pack(side="left", padx=(0, 6))
            self.search_entry.insert(0, "")
            self.search_entry.bind("<KeyRelease>", lambda e: self._search_changed())
            self.search_entry.bind("<Return>", lambda e: self._search_pick(0))
            self.search_entry.bind("<Escape>", lambda e: self._search_clear())
            ctk.CTkLabel(right, text="Find a skill", font=(FONT_BODY, 10), text_color=C.INK_DIM).pack(side="left", padx=(0, 10))
            self.flt_var = ctk.StringVar(value="All")
            row_f = ctk.CTkFrame(self, fg_color="transparent")
            if "filters" in self.show:
                row_f.pack(fill="x", pady=(0, 4))
            ctk.CTkLabel(row_f, text="Show:", font=(FONT_BODY, 10), text_color=C.INK_DIM).pack(side="left")
            ctk.CTkSegmentedButton(row_f, values=list(VIS_MAP_FILTERS), variable=self.flt_var,
                                   command=self._set_filter).pack(side="left", padx=(4, 0))
            row2 = ctk.CTkFrame(self, fg_color="transparent")
            row2.pack(fill="x", pady=(0, 4))
            self.edge_var = ctk.StringVar(value=self.edge_mode)
            if "links_control" in self.show:
                ctk.CTkLabel(row2, text="Links:", font=(FONT_BODY, 10), text_color=C.INK_DIM).pack(side="left")
                ctk.CTkSegmentedButton(row2, values=[m for m in VIS_EDGE_MODES
                                                     if m != "All" or "all_links" in self.show],
                                       variable=self.edge_var, command=self._set_edges).pack(side="left", padx=(4, 12))
            # A native ttk control, so the accessible list is itself reachable by
            # assistive technology that reads Tk widgets. Alt+L from anywhere.
            self.mirror_btn = ttk.Button(row2, text="List view (Alt+L)", command=self.toggle_mirror)
            self.mirror_btn.pack(side="left")
            # V9: the same structure, opened where any screen reader can walk it.
            self.web_btn = ttk.Button(row2, text="Open for screen readers", command=lambda: vis_open_web_map(app))
            self.web_btn.pack(side="left", padx=(6, 0))
            vis_bind_global_shortcuts(app)
            app._active_map = self
            self.bind("<Destroy>", lambda e: (setattr(app, "_active_map", None)
                                              if e.widget is self and getattr(app, "_active_map", None) is self else None))
            self.drawer_btn = ghost_button(row2, "Details \u25b8", self.toggle_drawer, width=90)
            self.banner = ctk.CTkLabel(row2, text="", font=(FONT_BODY, 11, "bold"), text_color=C.BRASS_DARK)
            self.banner.pack(side="left", padx=12)
            self.results = ctk.CTkFrame(self, fg_color=C.PAPER_DIM, corner_radius=8)
        self.body = ctk.CTkFrame(self, fg_color="transparent")
        self.body.pack(fill="both", expand=True)
        self.cv = tk.Canvas(self.body, height=height, bg=C.PAPER, highlightthickness=0,
                            takefocus=1, cursor="hand2")
        self.cv.pack(side="left", fill="both", expand=True)
        self.tip = VisCanvasTip(self.cv)
        if not compact:
            self.panel = ctk.CTkScrollableFrame(self.body, width=MAP_PANEL_WIDTH, fg_color=C.PAPER_DIM,
                                                corner_radius=10)
            self.panel.pack(side="left", fill="y", padx=(10, 0))
            self.status_var = tk.StringVar(value="")
            app._vis_status_var = self.status_var
            ttk.Label(self, textvariable=self.status_var).pack(anchor="w", pady=(4, 0))
            self.mirror_holder = ctk.CTkFrame(self, fg_color="transparent")
            self.body.bind("<Configure>", lambda e: self._responsive(e.width))
        else:
            self.panel = None
        self.cv.bind("<Configure>", lambda e: self.redraw())
        for wheel in ("<MouseWheel>", "<Button-4>", "<Button-5>"):
            self.cv.bind(wheel, self._wheel)
        self.cv.bind("<Motion>", self._on_motion)
        self.cv.bind("<Leave>", lambda e: self._leave())
        self.cv.bind("<Button-1>", self._on_click)
        self.cv.bind("<Shift-Button-1>", lambda e: self._on_click(e, shift=True))
        for key, fn in (("<Left>", lambda e: self._move(-1)), ("<Right>", lambda e: self._move(1)),
                        ("<Up>", lambda e: self._move(-self._cols())),
                        ("<Down>", lambda e: self._move(self._cols())),
                        ("<Return>", lambda e: self._activate()), ("<Escape>", lambda e: self._escape()),
                        ("<BackSpace>", lambda e: self.back()), ("<Alt-Left>", lambda e: self.back()),
                        ("<slash>", lambda e: self._focus_search()), ("<c>", lambda e: self.start_compare())):
            self.cv.bind(key, fn)
        if self.persist:
            self._restore_state()
        # Depth sets the ceiling on what the map shows (V9.4).
        if self.edge_mode == "All" and "all_links" not in self.show:
            self.edge_mode = "On selection"
        if "links_on_selection" not in self.show:
            self.edge_mode = "Off"
        if "filters" not in self.show:
            self.flt = "All"
        if not compact and vis_accessible_mode(self.conn) and (self.mirror is None or not self.mirror.winfo_ismapped()):
            self.after_idle(lambda: (self.mirror is None or not self.mirror.winfo_ismapped()) and self.toggle_mirror())
        self._render_crumbs()
        self._render_panel()
        self.after_idle(self.redraw)

    def _alt_list(self):
        try:
            if self.winfo_exists() and self.winfo_ismapped():
                self.toggle_mirror()
                if self.mirror is not None and self.mirror.winfo_ismapped():
                    self.mirror.tree.focus_set()
        except tk.TclError:
            pass
        return "break"

    # -- state ------------------------------------------------------------------
    def state(self):
        return {"level": self.level, "tid": self.tid, "sid": self.sid, "compare_sid": self.compare_sid,
                "flt": self.flt, "edge_mode": self.edge_mode,
                "mirror": bool(self.mirror is not None and self.mirror.winfo_ismapped())}

    def _save_state(self):
        if not self.persist:
            return
        try:
            set_setting(self.conn, MAP_STATE_SETTING, json.dumps(self.state()))
        except Exception:
            pass

    def _restore_state(self):
        try:
            st = json.loads(get_setting(self.conn, MAP_STATE_SETTING, "") or "{}")
        except ValueError:
            st = {}
        if st.get("tid") in self.domains:
            self.level, self.tid = st.get("level", "course"), st["tid"]
        if st.get("sid") in SKILLS and self.tid == SKILLS[st["sid"]]["topic"]:
            self.sid = st["sid"]
        if st.get("compare_sid") in SKILLS and self.sid:
            self.compare_sid = st["compare_sid"]
        if st.get("flt") in VIS_MAP_FILTERS:
            self.flt = st["flt"]
            self.flt_var.set(self.flt)
        if st.get("edge_mode") in VIS_EDGE_MODES:
            self.edge_mode = st["edge_mode"]
            self.edge_var.set(self.edge_mode)
        if st.get("mirror"):
            self.after_idle(self.toggle_mirror)

    def _push(self):
        self.history.append((self.level, self.tid, self.sid, self.compare_sid))
        self.history = self.history[-30:]

    def back(self):
        if not self.history:
            return "break"
        self.level, self.tid, self.sid, self.compare_sid = self.history.pop()
        self._after_nav(push=False)
        return "break"

    def _after_nav(self, push=True):
        self.tip.hide()
        self.redraw()
        self._render_crumbs()
        self._render_panel()
        self._sync_mirror()
        self._save_state()

    # -- navigation ---------------------------------------------------------------
    def _cols(self):
        return 6 if self.level == "course" else vis_domain_grid(self.tid, self._cw())[0]

    def _cw(self):
        return max(320, int(self.cv.winfo_width() or 800))

    def _ch(self):
        return max(160, int(self.cv.winfo_height() or 520))

    def _targets(self):
        return [h for h in self.hit + getattr(self, "link_hits", []) if h[0] in ("domain", "skill", "confusion", "stub")]

    def _move(self, d):
        tg = self._targets()
        if tg:
            self.kb = True
            self.focus_idx = (self.focus_idx + d) % len(tg)
            self.redraw()
            k, ident, bbox = self._targets()[self.focus_idx % len(self._targets())]
            # Keep the keyboard target in view on a scrolled area.
            try:
                sr = [float(v) for v in str(self.cv.cget("scrollregion")).split()]
                extent = sr[3] if len(sr) == 4 and sr[3] > 0 else self._ch()
                top, bottom = self.cv.canvasy(0), self.cv.canvasy(self._ch())
                if bbox[1] < top or bbox[3] > bottom:
                    self.cv.yview_moveto(max(0.0, (bbox[1] - 24) / extent))
            except (tk.TclError, ValueError):
                pass
            lines = self._tip_lines(k, ident)
            self.tip.show(bbox[2] - 20, bbox[1], lines)
            vis_announce(self.app, ". ".join(l for l in lines[:3] if l))
        return "break"

    def _activate(self):
        tg = self._targets()
        if not tg:
            return
        k, ident, _ = tg[self.focus_idx % len(tg)]
        self._act(k, ident)

    def _act(self, kind, ident, shift=False):
        if kind == "domain":
            self.open_domain(ident)
        elif kind == "skill":
            self.select_skill(ident, shift=shift)
        elif kind == "confusion":
            self._push()
            self.sid, self.compare_sid = ident["a"], ident["b"]
            self._after_nav()
            self._render_panel(explain=True)
        elif kind == "stub":
            self.select_skill(ident["outside"])

    def _escape(self):
        if self.compare_pending:
            self.compare_pending = False
            self._banner("")
            return "break"
        return self.zoom_out()

    def _set_filter(self, value):
        self.flt = value
        self.redraw()
        self._save_state()

    def _set_edges(self, value):
        self.edge_mode = value
        self.redraw()
        self._save_state()

    def _banner(self, text):
        if not self.compact:
            self.banner.configure(text=text)
            if text:
                vis_announce(self.app, text)

    def start_compare(self):
        if "compare_mode" not in self.show:
            return "break"
        if not self.sid:
            self._banner("Choose a skill first, then compare.")
            return "break"
        self.compare_pending = True
        self._banner("Select one more skill to compare \u00b7 Esc to cancel")
        return "break"

    def open_domain(self, tid, animate=True):
        if self.compact and self.on_navigate:
            self.on_navigate(tid, None)
            return
        bbox = next((h[2] for h in self.hit if h[0] == "domain" and h[1] == tid), None)
        self._push()

        def finish():
            self.level, self.tid, self.sid, self.compare_sid, self.focus_idx = "domain", tid, None, None, 0
            self._after_nav()
            vis_announce(self.app, f"{self.domains[tid]['name']}: {present_domain_rail(self.domains[tid])['words']}")
        if bbox and animate:
            self._zoom_rect(bbox, (0, 0, self._cw(), self._ch()), finish)
        else:
            finish()

    def select_skill(self, sid, shift=False):
        tid = SKILLS[sid]["topic"]
        if self.compact and self.on_navigate:
            self.on_navigate(tid, sid)
            return
        self._push()
        if (shift or self.compare_pending) and "compare_mode" in self.show and self.sid and self.sid != sid:
            self.compare_sid = sid
            self.compare_pending = False
            self._banner("")
        else:
            self.sid, self.compare_sid = sid, None
        self.level, self.tid = "domain", tid
        self._after_nav()
        if self.drawer and not self.panel.winfo_ismapped():
            # On a narrow layout, choosing a skill is asking for its details.
            self.toggle_drawer()
        vis_announce(self.app, nav_graph_description(self.graph, f"skill:{sid}"))

    def select_skill_clear(self):
        self._push()
        self.sid, self.compare_sid = None, None
        self._after_nav()

    def zoom_out(self):
        if self.level == "domain":
            tid = self.tid
            full = (0, 0, self._cw(), self._ch())
            self._push()

            def finish():
                self.level, self.tid, self.sid, self.compare_sid = "course", None, None, None
                self.focus_idx = vis_domain_order().index(tid)
                self._after_nav()
            lay = vis_course_layout(self._cw(), self._ch())
            self._zoom_rect(full, lay.get(tid, full), finish)
        return "break"

    def _zoom_rect(self, a, b, done):
        def step(t):
            self.cv.delete("vis_zoom")
            r = [a[i] + (b[i] - a[i]) * t for i in range(4)]
            self.cv.create_rectangle(*r, outline=C.BRASS, width=2, fill=C.PAPER_DIM, tags=("vis_zoom",))
        vis_animate(self.cv, 200, step, lambda: (self.cv.delete("vis_zoom"), done()), reduced=self.reduced)

    # -- search -----------------------------------------------------------------
    def _focus_search(self):
        if not self.compact:
            self.search_entry.focus_set()
        return "break"

    def _search_changed(self):
        for w_ in self.results.winfo_children():
            w_.destroy()
        res = vis_search(self.search_var.get(), conn=self.conn)
        self._search_results = res
        if not res:
            self.results.pack_forget()
            return
        self.results.pack(fill="x", pady=(0, 6), before=self.body)
        for i, r in enumerate(res):
            ctk.CTkButton(self.results, text=f"{r['label']}  \u00b7  {r['area']}", anchor="w",
                          fg_color="transparent", hover_color=C.PAPER_LINE, text_color=C.INK,
                          font=(FONT_BODY, 11), height=26,
                          command=lambda i=i: self._search_pick(i)).pack(fill="x", padx=6, pady=1)

    def _search_pick(self, i):
        res = getattr(self, "_search_results", None) or vis_search(self.search_var.get(), conn=self.conn)
        if not res or i >= len(res):
            return "break"
        sid = res[i]["sid"]
        self._search_clear()
        self.select_skill(sid)
        self._flash(sid)
        return "break"

    def _search_clear(self):
        if self.compact:
            return
        self.search_var.set("")
        for w_ in self.results.winfo_children():
            w_.destroy()
        self.results.pack_forget()

    def _flash(self, sid, cycles=2):
        """A brief ring at the found skill; bounded, and skipped under reduced motion."""
        if self.reduced:
            return
        count = {"n": 0}

        def tick():
            try:
                if not self.cv.winfo_exists():
                    return
            except tk.TclError:
                return
            self.cv.delete("vis_flash")
            pos = next((h[2] for h in self.hit if h[0] == "skill" and h[1] == sid), None)
            if pos and count["n"] % 2 == 0:
                x0, y0, x1, y1 = pos
                self.cv.create_oval(x0 - 6, y0 - 6, x1 + 6, y0 + (x1 - x0) + 6, outline=C.BRASS, width=3,
                                    tags=("vis_flash",))
            count["n"] += 1
            if count["n"] < cycles * 2:
                self.cv.after(260, tick)
            else:
                self.cv.delete("vis_flash")
        tick()

    # -- responsive inspector ---------------------------------------------------------
    def _responsive(self, width):
        want_drawer = width < MAP_DRAWER_BREAKPOINT or (width - MAP_PANEL_WIDTH - 10) < MAP_MIN_CANVAS
        if want_drawer == self.drawer:
            return
        self.drawer = want_drawer
        if want_drawer:
            self.panel.pack_forget()
            self.drawer_btn.pack(side="left", padx=(8, 0), before=self.banner)
        else:
            self.panel.place_forget()
            self.drawer_btn.pack_forget()
            self.panel.pack(side="left", fill="y", padx=(10, 0))

    def toggle_drawer(self):
        if not self.drawer:
            return
        if self.panel.winfo_ismapped():
            self.panel.place_forget()
        else:
            self.panel.place(relx=1.0, rely=0.0, anchor="ne", relheight=1.0, in_=self.body)
            self.panel.lift()

    # -- accessible mirror ---------------------------------------------------------------
    def toggle_mirror(self):
        if self.compact:
            return
        if self.mirror is not None and self.mirror.winfo_ismapped():
            self.mirror_holder.pack_forget()
            self.mirror_btn.configure(text="List view (Alt+L)")
            self._save_state()
            return
        if self.mirror is None:
            self.mirror = MapMirror(self.mirror_holder, self)
            self.mirror.pack(fill="both", expand=True)
        self.mirror_holder.pack(fill="x", pady=(8, 0))
        self.mirror_btn.configure(text="Hide list (Alt+L)")
        self._sync_mirror()
        self._save_state()

    def _sync_mirror(self):
        if self.mirror is not None:
            self.mirror.sync()

    # -- drawing -----------------------------------------------------------------------
    def redraw(self):
        self.cv.delete("all")
        self.hit = []
        self.link_hits = []
        self._pos = None
        self.redraw_count = getattr(self, "redraw_count", 0) + 1
        if self.level == "course":
            self.cv.configure(scrollregion=(0, 0, self._cw(), self._ch()))
            self.cv.yview_moveto(0)
            self._draw_course()
        else:
            self._draw_domain()

    def _wheel(self, e):
        if self.level != "domain":
            return
        delta = -1 if (getattr(e, "delta", 0) > 0 or getattr(e, "num", 0) == 4) else 1
        self.cv.yview_scroll(delta, "units")
        return "break"

    def _draw_course(self):
        w, h = self._cw(), self._ch()
        lay = vis_course_layout(w, h, cols=6, pad=(8 if self.compact else 12),
                                header=(18 if self.compact else 26))
        bands = {}
        for tid, (x0, y0, x1, y1) in lay.items():
            g = self.domains[tid]["group"]
            bands[g] = min(bands.get(g, y0), y0)
        for g, y in bands.items():
            self.cv.create_text(12, y - (9 if self.compact else 13), text=g.upper(), anchor="w",
                                fill=C.BRASS_DARK, font=(FONT_BODY, 8 if self.compact else 9, "bold"))
        for idx, tid in enumerate(vis_domain_order()):
            d = self.domains[tid]
            rail = present_domain_rail(d)
            x0, y0, x1, y1 = lay[tid]
            focused = self.kb and idx == self.focus_idx
            matches = sum(1 for n in d["nodes"] if vis_node_matches(n, self.flt))
            self.cv.create_rectangle(x0, y0, x1, y1, fill=C.PAPER_DIM,
                                     outline=(C.BRASS if d["is_focus"] or focused else C.PAPER_LINE),
                                     width=(2 if d["is_focus"] or focused else 1))
            fs = 9 if self.compact else 11
            title = self.cv.create_text(x0 + 8, y0 + 6, text=d["short"], anchor="nw", fill=C.INK,
                                        font=(FONT_BODY, fs, "bold"), width=(x1 - x0 - 14))
            tb = self.cv.bbox(title) or (x0, y0, x1, y0 + 18)
            ry = tb[3] + (4 if self.compact else 8)
            rh = 8 if self.compact else 12
            if ry + rh < y1 - 2:
                vis_draw_rail(self.cv, x0 + 8, ry, x1 - 8, rh, rail,
                              dim=(self.flt != "All" and matches == 0))
            if not self.compact:
                self.cv.create_text(x0 + 8, ry + rh + 6, text=rail["words"], anchor="nw", fill=C.INK_DIM,
                                    font=(FONT_BODY, 9), width=(x1 - x0 - 14))
                marks = "  ".join(f"{MARK_SYMBOL[m]}{rail['marks'][m]}" for m in MARK_PRIORITY if rail["marks"][m])
                if marks:
                    self.cv.create_text(x1 - 6, y1 - 5, text=marks, anchor="se", fill=C.BRASS_DARK,
                                        font=(FONT_BODY, 9))
                if self.flt != "All":
                    self.cv.create_text(x0 + 8, y1 - 5, anchor="sw", fill=C.INK,
                                        font=(FONT_BODY, 9, "bold"),
                                        text=(f"{matches} {self.flt.lower()}" if matches else ""))
            self.hit.append(("domain", tid, (x0, y0, x1, y1)))

    def _draw_domain(self):
        w, h = self._cw(), self._ch()
        d = self.domains[self.tid]
        rail = present_domain_rail(d)
        self.cv.create_text(14, 10, text=d["name"], anchor="nw", fill=C.INK, font=(FONT_DISPLAY, 14, "bold"))
        vis_draw_rail(self.cv, 14, 38, min(w - 14, 360), 10, rail)
        self.cv.create_text(min(w - 14, 360) + 10, 43, text=rail["words"], anchor="w", fill=C.INK_DIM,
                            font=(FONT_BODY, 10))
        extent = vis_domain_extent(self.tid, w, h, top=62, measure=self._label_measure, linespace=self._label_linespace)
        self.cv.configure(scrollregion=(0, 0, w, extent))
        if extent > h:
            self.cv.create_text(w - 12, h - 8, anchor="se", fill=C.INK_DIM, font=(FONT_BODY, 9),
                                text="Scroll for more skills in this area")
        pos = vis_domain_layout(self.tid, w, h, top=62, measure=self._label_measure, linespace=self._label_linespace)
        # Links live on their own tagged layer (see _draw_links).
        self._pos, self._w_last = pos, w
        self._draw_links(pos, w)
        cols = self._cols()
        cw = (w - 48) / cols
        for idx, sid in enumerate(vis_skills_of(self.tid)):
            n = self.nodes[sid]
            x, y = pos[sid]
            r = 15
            sel = sid in (self.sid, self.compare_sid)
            match = vis_node_matches(n, self.flt)
            vis_draw_node(self.cv, x, y, r, n if "evidence_overlays" in self.show else dict(
                              n, overlays=[o for o in n["overlays"] if o not in ("little_evidence", "mixed_evidence")]),
                          "domain", dim=not match,
                          focus=(self.kb and idx == self.focus_idx), style=uncertainty_style(self.conn, self.app))
            if sel:
                self.cv.create_oval(x - r - 11, y - r - 11, x + r + 11, y + r + 11, outline=C.BRASS, width=3)
            lt = self.cv.create_text(x, y + r + 12, text=n["label"], anchor="n", width=cw - 12,
                                     fill=(C.INK if match else C.INK_DIM),
                                     font=(FONT_BODY, 9, "bold" if sel else "normal"), justify="center")
            lb = self.cv.bbox(lt)
            if lb:
                plate = self.cv.create_rectangle(lb[0] - 3, lb[1] - 1, lb[2] + 3, lb[3] + 1, fill=C.PAPER, outline="")
                self.cv.tag_lower(plate, lt)
            self.hit.append(("skill", sid, (x - r - 8, y - r - 8, x + r + 8, y + r + 30)))
        if self.edge_mode == "On selection" and not self.sid:
            all_links = present_domain_links(self.edges, self.tid)
            n_links = len(all_links["confusions"]) + len(all_links["prereqs"])
            if n_links:
                self.cv.create_text(w - 12, 12, anchor="ne", fill=C.INK_DIM, font=(FONT_BODY, 9),
                                    text="Links appear when you point at or choose a skill")

    def _draw_links(self, pos, w):
        """The link layer alone, tagged, under the nodes. Hover repaints this
        and nothing else."""
        self.cv.delete("vis_links")
        self.link_hits = []
        if self.level != "domain" or not pos:
            return {"confusions": [], "stubs": [], "prereqs": []}
        links = vis_edges_to_draw(present_domain_links(self.edges, self.tid), self.edge_mode,
                                  (self.sid, self.compare_sid, self.hover_sid))
        tg = ("vis_links",)
        for p in links["prereqs"]:
            (xa, ya), (xb, yb) = pos[p["pre"]], pos[p["dep"]]
            self.cv.create_line(xa, ya, xb, yb, fill=VIS_PALETTE["link_prereq"], width=1.5,
                                arrow=tk.LAST, arrowshape=(9, 11, 4), tags=tg)
        for c in links["confusions"]:
            (xa, ya), (xb, yb) = pos[c["a"]], pos[c["b"]]
            mx, my = (xa + xb) / 2, (ya + yb) / 2 - 30
            self.cv.create_line(xa, ya, mx, my, xb, yb, smooth=True, dash=(6, 4), width=2,
                                fill=VIS_PALETTE["link_confusion"], tags=tg)
            t = self.cv.create_text(mx, my, text="\u2194", fill=VIS_PALETTE["link_confusion"],
                                    font=(FONT_BODY, 13, "bold"), tags=tg)
            self.link_hits.append(("confusion", c, self.cv.bbox(t)))
        for s in links["stubs"]:
            x, y = pos[s["inside"]]
            ex = w - 10 if x > w / 2 else 10
            self.cv.create_line(x, y, (x + ex) / 2, y + 16, dash=(3, 4), fill=VIS_PALETTE["link_confusion"], tags=tg)
            t = self.cv.create_text((x + ex) / 2, y + 26, text=f"\u2194 {s['outside_domain']}",
                                    fill=C.BRASS_DARK, font=(FONT_BODY, 8), tags=tg)
            self.link_hits.append(("stub", s, self.cv.bbox(t)))
        self.cv.tag_lower("vis_links")
        return links

    # -- pointer ------------------------------------------------------------------------
    def _hit_at(self, x, y):
        for k, ident, bb in reversed(self.hit + [h for h in getattr(self, "link_hits", [])]):
            if bb and bb[0] <= x <= bb[2] and bb[1] <= y <= bb[3]:
                return k, ident, bb
        return None

    def _tip_lines(self, kind, ident):
        if kind == "domain":
            d = self.domains[ident]
            rail = present_domain_rail(d)
            extra = [f"{MARK_TEXT[m]}: {rail['marks'][m]}" for m in MARK_PRIORITY if rail["marks"][m]]
            return [d["name"], rail["words"], " · ".join(extra), "Click to open."]
        if kind == "skill":
            n = self.nodes[ident]
            marks = [MARK_TEXT[m] for m in node_marks(n)]
            for _o in ("little_evidence", "mixed_evidence"):
                if _o in n["overlays"]:
                    marks.append(VIS_OVERLAY_TEXT[_o])
            return [n["label"], n["tier"] + (f" · {n['step']}" if n["step"] else ""), n["next"],
                    ", ".join(marks), "Click for details."]
        if kind == "confusion":
            return [f"Often mixed up: {SKILLS[ident['a']]['label']} and {SKILLS[ident['b']]['label']}",
                    ident.get("why") or "", "Click to tell them apart."]
        if kind == "stub":
            return [f"Often mixed up with {ident['outside_label']} ({ident['outside_domain']})",
                    ident.get("why") or "", "Click to go there."]
        return []

    def _on_motion(self, e):
        e.x, e.y = int(self.cv.canvasx(e.x)), int(self.cv.canvasy(e.y))
        h = self._hit_at(e.x, e.y)
        new_hover = h[1] if h and h[0] == "skill" else None
        if new_hover != self.hover_sid and self.level == "domain" and self.edge_mode == "On selection":
            self.hover_sid = new_hover
            self._draw_links(getattr(self, "_pos", None), self._cw())
            h = self._hit_at(e.x, e.y)
        if h:
            self.tip.show(e.x, e.y, self._tip_lines(h[0], h[1]))
        else:
            self.tip.hide()

    def _leave(self):
        self.tip.hide()
        if self.hover_sid:
            self.hover_sid = None
            self._draw_links(getattr(self, "_pos", None), self._cw())

    def _on_click(self, e, shift=False):
        self.cv.focus_set()
        h = self._hit_at(int(self.cv.canvasx(e.x)), int(self.cv.canvasy(e.y)))
        if h:
            self._act(h[0], h[1], shift=shift)
        return "break"

    # -- chrome ---------------------------------------------------------------------------
    def _render_crumbs(self):
        if self.compact:
            return
        for w_ in self.crumbs.winfo_children():
            w_.destroy()
        ghost_button(self.crumbs, "Course", lambda: self.zoom_out(), width=80).pack(side="left")
        if self.level == "domain":
            ctk.CTkLabel(self.crumbs, text="\u203a", text_color=C.INK_DIM).pack(side="left", padx=4)
            ghost_button(self.crumbs, TOPICS[self.tid].get("short") or TOPICS[self.tid]["name"],
                         lambda: self.select_skill_clear(), width=120).pack(side="left")
        if self.sid:
            ctk.CTkLabel(self.crumbs, text="\u203a  " + SKILLS[self.sid]["label"][:40],
                         text_color=C.INK, font=(FONT_BODY, 12)).pack(side="left", padx=6)
        if self.history:
            ghost_button(self.crumbs, "\u2190 Back", self.back, width=70).pack(side="left", padx=(8, 0))

    def _panel_text(self, text, size=11, color=C.INK, bold=False, pady=(2, 0)):
        lbl = ctk.CTkLabel(self.panel, text=text, font=(FONT_BODY, size, "bold" if bold else "normal"),
                           text_color=color, anchor="w", justify="left", wraplength=300)
        lbl.pack(anchor="w", fill="x", padx=12, pady=pady)
        return lbl

    def _render_panel(self, explain=False):
        if self.panel is None:
            return
        for w_ in self.panel.winfo_children():
            w_.destroy()
        if self.level == "course":
            self._panel_text("The course", 14, bold=True, pady=(10, 2))
            self._panel_text("Each square is one exam area. Its bar counts every skill in it: strong at the "
                             "left edge, not started at the right. Open an area to see its skills.", color=C.INK_DIM)
            tot = {c: 0 for c in COARSE_ORDER}
            for d in self.domains.values():
                for seg in present_domain_rail(d)["segments"]:
                    tot[seg["state"]] += seg["n"]
            gcv = tk.Canvas(self.panel, height=24 * 4 + 8, bg=C.PAPER_DIM, highlightthickness=0, width=300)
            gcv.pack(anchor="w", padx=12, pady=(10, 0))
            for i, c in enumerate(COARSE_ORDER):
                vis_draw_glyph(gcv, 14, 14 + i * 24, 8, COARSE_GLYPH[c])
                gcv.create_text(34, 14 + i * 24, anchor="w", text=f"{c}: {tot[c]}", font=(FONT_BODY, 10), fill=C.INK)
            vis_legend(self.panel).pack(anchor="w", padx=12, pady=(10, 10))
            return
        if self.sid and self.compare_sid:
            return self._render_compare(explain)
        if self.sid:
            return self._render_skill()
        d = self.domains[self.tid]
        rail = present_domain_rail(d)
        self._panel_text(d["name"], 14, bold=True, pady=(10, 2))
        self._panel_text(rail["words"], color=C.INK_DIM)
        links = present_domain_links(self.edges, self.tid)
        n_links = len(links["confusions"]) + len(links["stubs"])
        if n_links:
            self._panel_text(f"{_plural(n_links, 'mix-up pair')} in this area. Point at a skill to see its "
                             "links, or show all links above.", color=C.INK_DIM, pady=(8, 0))
        moving = [n for n in d["nodes"] if vis_node_matches(n, "Moving")]
        if moving:
            self._panel_text("In motion here", bold=True, pady=(10, 0))
            for n in moving[:6]:
                ghost_button(self.panel, f"{n['label'][:38]} · {n['coarse'].lower()}",
                             lambda s=n["sid"]: self.select_skill(s)).pack(anchor="w", padx=12, pady=2)
        primary_button(self.panel, "Compose a session for this area",
                       lambda: vis_start_constrained(self.app, self.app.content, self.tid)
                       ).pack(anchor="w", padx=12, pady=(12, 10))

    def _render_skill(self):
        sid = self.sid
        n = self.nodes[sid]
        detail = self.vs["detail"].get(sid)
        timeline = gather_skill_timeline(self.conn, sid)
        confs = [{"other": (p["b"] if p["a"] == sid else p["a"]),
                  "other_label": SKILLS[p["b"] if p["a"] == sid else p["a"]]["label"], "why": p["why"]}
                 for p in vis_confusion_pairs() if sid in (p["a"], p["b"])]
        pre = [SKILLS[a]["label"] for a, b in self.edges if b == sid]
        qa = present_skill_queries(n, detail, timeline, confs, pre)
        head = tk.Canvas(self.panel, height=54, width=300, bg=C.PAPER_DIM, highlightthickness=0)
        head.pack(anchor="w", padx=12, pady=(10, 0))
        # The inspector is the one place the full eight-tier vocabulary is drawn.
        vis_draw_glyph(head, 24, 27, 16, n["glyph"], [o for o in n["overlays"] if o == "little_evidence"])
        head.create_text(54, 16, anchor="w", text=(n["tier"] if "inspector_tier_word" in self.show else n["coarse"]),
                         font=(FONT_BODY, 13, "bold"), fill=C.INK)
        head.create_text(54, 36, anchor="w", text=n["next"], font=(FONT_BODY, 10), fill=C.INK_DIM)
        self._panel_text(n["label"], 12, bold=True, pady=(4, 0))
        if n["step"]:
            self._panel_text(n["step"], color=C.INK_DIM)
        for m in node_marks(n):
            self._panel_text(f"{MARK_SYMBOL[m]}  {MARK_TEXT[m]}", color=C.BRASS_DARK)
        if "little_evidence" in n["overlays"] and "evidence_overlays" in self.show:
            self._panel_text(("Lighter fill" if uncertainty_style(self.conn, self.app) == "faded" else "Dashed halo")
                             + ": not much evidence yet", color=C.INK_DIM)
        if "mixed_evidence" in n["overlays"] and "evidence_overlays" in self.show:
            self._panel_text("Dash-dot ring: results have been mixed lately, so it will come up again soon",
                             color=C.INK_DIM)
        pts = present_timeline(timeline, detail)
        if pts:
            tl = tk.Canvas(self.panel, height=64, width=300, bg=C.PAPER_DIM, highlightthickness=0)
            tl.pack(anchor="w", padx=12, pady=(8, 0))
            k = len(pts)
            xs = [30 + i * (240 / max(1, k - 1)) for i in range(k)] if k > 1 else [150]
            tl.create_line(xs[0], 22, xs[-1], 22, fill=C.PAPER_LINE, width=2)
            for x, p in zip(xs, pts):
                if p["kind"] == "next":
                    tl.create_oval(x - 6, 16, x + 6, 28, outline=C.BRASS, width=2, dash=(2, 2))
                else:
                    fillc = C.NAVY if p["kind"] == "held" else (C.GOLD_SOFT if p["kind"] == "mixed" else C.PAPER)
                    tl.create_oval(x - 6, 16, x + 6, 28, fill=fillc, outline=C.INK_DIM)
                    if p["note"]:
                        tl.create_text(x, 8, text="\u21ba", fill=C.NAVY_2, font=(FONT_BODY, 9, "bold"))
                tl.create_text(x, 42, text=p["when"], fill=C.INK_DIM, font=(FONT_BODY, 8), width=60)
            self._panel_text("Filled: recalled · half: mixed · open: missed · dashed: next.", 9, C.INK_DIM)
        for title, body in (("Why is it " + n["tier"] + "?", [qa["why"]]),
                            ("What is this based on?", qa["evidence"]),
                            ("What would change it?", [qa["change"]])):
            self._expander(title, body)
        if confs or pre:
            self._panel_text("Connected skills", bold=True, pady=(10, 0))
            for c in confs:
                row = ctk.CTkFrame(self.panel, fg_color="transparent")
                row.pack(anchor="w", fill="x", padx=12, pady=(2, 4))
                ghost_button(row, "\u2194 " + c["other_label"][:38],
                             lambda o=c["other"]: self.select_skill(o)).pack(anchor="w")
                ghost_button(row, "Tell these two apart", lambda o=c["other"]: (
                    setattr(self, "compare_sid", o), self._after_nav(), self._render_panel(explain=True)),
                    width=160).pack(anchor="w", pady=(2, 0))
            for lab in pre:
                self._panel_text("Builds on: " + lab, color=C.INK_DIM)
        if "compare_mode" in self.show:
            ghost_button(self.panel, "Compare with another skill", self.start_compare).pack(anchor="w", padx=12, pady=(12, 2))
        primary_button(self.panel, "Practise this skill",
                       lambda: vis_start_practice(self.app, self.app.content,
                                                  [sid] + [c["other"] for c in confs[:1]],
                                                  f"Practice: {n['label'][:40]}")
                       ).pack(anchor="w", padx=12, pady=(6, 4))
        ghost_button(self.panel, "I think this is wrong",
                     lambda: self.app.show_view("learnermodel")).pack(anchor="w", padx=12, pady=(0, 12))

    def _render_compare(self, explain=False):
        a, b = self.sid, self.compare_sid
        na, nb = self.nodes[a], self.nodes[b]
        self._panel_text("Side by side", 14, bold=True, pady=(10, 4))
        cvp = tk.Canvas(self.panel, height=70, width=300, bg=C.PAPER_DIM, highlightthickness=0)
        cvp.pack(anchor="w", padx=12)
        for x, n in ((70, na), (230, nb)):
            vis_draw_glyph(cvp, x, 24, 14, n["glyph"])
            cvp.create_text(x, 52, text=n["tier"], font=(FONT_BODY, 10, "bold"), fill=C.INK)
        self._panel_text(f"{na['label']}: {na['evidence']}, {na['next']}.")
        self._panel_text(f"{nb['label']}: {nb['evidence']}, {nb['next']}.", pady=(4, 0))
        why, _ctx = vis_distinction_context(a, b)
        if why:
            self._panel_text("Why they get mixed up: " + why, color=C.INK_DIM, pady=(8, 0))
        out = self._panel_text("", pady=(8, 0))
        ghost_button(self.panel, "Tell these apart",
                     lambda: vis_explain_distinction(self.app, a, b, out)).pack(anchor="w", padx=12, pady=(8, 2))
        primary_button(self.panel, "Practise both",
                       lambda: vis_start_practice(self.app, self.app.content, [a, b], "Telling them apart")
                       ).pack(anchor="w", padx=12, pady=(4, 4))
        ghost_button(self.panel, "End comparison", self.select_skill_clear).pack(anchor="w", padx=12, pady=(0, 12))
        if explain:
            vis_explain_distinction(self.app, a, b, out)

    def _expander(self, title, lines):
        holder = ctk.CTkFrame(self.panel, fg_color="transparent")
        holder.pack(anchor="w", fill="x", padx=12, pady=(6, 0))
        body = ctk.CTkLabel(holder, text="\n".join(lines), font=(FONT_BODY, 11), text_color=C.INK,
                            anchor="w", justify="left", wraplength=290)
        state = {"open": False}
        btn = ctk.CTkButton(holder, text="\u25b8 " + title, anchor="w", fg_color="transparent",
                            hover_color=C.PAPER_LINE, text_color=C.INK, font=(FONT_BODY, 11, "bold"), height=26)

        def flip():
            state["open"] = not state["open"]
            btn.configure(text=("\u25be " if state["open"] else "\u25b8 ") + title)
            if state["open"]:
                body.pack(anchor="w", fill="x", padx=(16, 0))
                vis_announce(self.app, body.cget("text"))
            else:
                body.pack_forget()
        btn.configure(command=flip)
        btn.pack(anchor="w", fill="x")


class MapMirror(ttk.Frame):
    """The map as a native tree: areas with their skills, each row carrying the
    same words the canvas draws. Built from plain ttk widgets (not
    CustomTkinter, which draws on a canvas) so assistive technology that reads
    Tk widgets can reach it. Selection is shared with the canvas both ways."""

    def __init__(self, parent, cmap):
        super().__init__(parent)
        self.cmap = cmap
        self._syncing = False
        cols = ("state", "next", "marks")
        self.tree = ttk.Treeview(self, columns=cols, height=12, selectmode="browse")
        self.tree.heading("#0", text="Area or skill")
        self.tree.heading("state", text="Where it stands")
        self.tree.heading("next", text="Next")
        self.tree.heading("marks", text="Asks of you now")
        self.tree.column("#0", width=320)
        self.tree.column("state", width=150)
        self.tree.column("next", width=170)
        self.tree.column("marks", width=220)
        sb = ttk.Scrollbar(self, orient="vertical", command=self.tree.yview)
        self.tree.configure(yscrollcommand=sb.set)
        self.tree.pack(side="left", fill="both", expand=True)
        sb.pack(side="left", fill="y")
        # One navigation graph (build_nav_graph) is the structure; this tree
        # is one rendering of it, the canvas another, the web map a third.
        graph = cmap.graph if getattr(cmap, "graph", None) else build_nav_graph(cmap.domains, cmap.edges)
        self.graph = graph
        for aid in graph["children"]["course"]:
            an = graph["nodes"][aid]
            self.tree.insert("", "end", iid=aid, text=an["label"], values=(an["words"], "", ""))
            for sk in graph["children"][aid]:
                n = graph["nodes"][sk]
                self.tree.insert(aid, "end", iid=sk, text=n["label"],
                                 values=(n["tier"], n["next"], ", ".join(n["marks"])))
                for k, (rel, other) in enumerate(graph["relations"].get(n["sid"], [])):
                    self.tree.insert(sk, "end", iid=f"rel:{n['sid']}:{k}:{other}",
                                     text=f"{rel}: {SKILLS[other]['label']}",
                                     values=(graph["nodes"][f"skill:{other}"]["tier"], "", ""))
        self.tree.bind("<<TreeviewSelect>>", self._on_select)
        self.tree.bind("<Return>", self._on_select)
        self.tree.bind("<KeyPress>", self._type_ahead, add="+")
        self._typed, self._typed_at = "", 0.0

    def _on_select(self, _e=None):
        if self._syncing:
            return
        sel = self.tree.selection()
        if not sel:
            return
        kind, ident = sel[0].split(":", 1)
        if kind == "rel":
            other = ident.split(":")[-1]
            if other in SKILLS:
                self.cmap.select_skill(other)
            return
        if kind == "area" and not (self.cmap.level == "domain" and self.cmap.tid == ident and not self.cmap.sid):
            self.cmap.open_domain(ident, animate=False)
        elif kind == "skill" and self.cmap.sid != ident:
            self.cmap.select_skill(ident)

    def _type_ahead(self, e):
        """Typing letters jumps to the next area or skill whose name starts with
        them, the way native lists behave."""
        ch = getattr(e, "char", "")
        if not ch or len(ch) != 1 or not ch.isprintable() or ch.isspace():
            return
        now = time.time()
        self._typed = (self._typed if now - self._typed_at < 1.0 else "") + ch.lower()
        self._typed_at = now
        order = []
        for a in self.tree.get_children(""):
            order.append(a)
            if self.tree.item(a, "open"):
                order.extend(self.tree.get_children(a))
        cur = self.tree.focus()
        start = order.index(cur) + (0 if len(self._typed) > 1 else 1) if cur in order else 0
        for i in range(len(order)):
            iid = order[(start + i) % len(order)]
            if str(self.tree.item(iid, "text")).lower().startswith(self._typed):
                self.tree.selection_set(iid)
                self.tree.focus(iid)
                self.tree.see(iid)
                return "break"

    def sync(self):
        target = (f"skill:{self.cmap.sid}" if self.cmap.sid else
                  f"area:{self.cmap.tid}" if self.cmap.tid else None)
        self._syncing = True
        try:
            if target and self.tree.exists(target):
                parent = self.tree.parent(target)
                if parent:
                    self.tree.item(parent, open=True)
                self.tree.selection_set(target)
                self.tree.focus(target)
                self.tree.see(target)
            else:
                self.tree.selection_remove(self.tree.selection())
        finally:
            self.after_idle(lambda: setattr(self, "_syncing", False))


# ---- trajectory, causal chain, ladder path, in motion ----------------------------------

def vis_draw_trajectory(parent, stages, reduced=False, dark=True):
    bg = C.NAVY if dark else C.PAPER
    fg = C.CREAM if dark else C.INK
    fg_dim = C.GOLD_SOFT if dark else C.INK_DIM
    cv = tk.Canvas(parent, height=86, bg=bg, highlightthickness=0)
    cv.pack(fill="x", pady=(4, 10))
    tip = VisCanvasTip(cv)
    detail = ctk.CTkLabel(parent, text="", font=(FONT_BODY, 11), text_color=fg_dim, anchor="w",
                          justify="left", wraplength=640)
    state = {"hit": [], "shown": None}

    def draw(progress=1.0):
        cv.delete("all")
        state["hit"] = []
        w = max(400, int(cv.winfo_width() or 700))
        k = len(stages) + 1
        xs = [62 + i * (w - 124) / max(1, k - 1) for i in range(k)]
        visible = progress * k
        for i in range(k - 1):
            if i + 1 <= visible:
                cv.create_line(xs[i] + 14, 30, xs[i + 1] - 14, 30, fill=C.BRASS, width=2)
        for i, x in enumerate(xs):
            if i > visible:
                break
            if i < len(stages):
                s = stages[i]
                cv.create_oval(x - 13, 17, x + 13, 43, fill=bg, outline=C.BRASS, width=2)
                cv.create_text(x, 30, text=str(s["n"]), fill=fg, font=(FONT_BODY, 11, "bold"))
                cv.create_text(x, 56, text=s["title"], fill=fg, font=(FONT_BODY, 10, "bold"))
                if s["skills"]:
                    room = max(8, int(min((w - 124) / max(1, k - 1), 2 * (x - 4)) / 6.5))
                    lab = s["skills"][0]
                    cv.create_text(x, 72, text=lab[:room] + ("\u2026" if len(lab) > room else ""),
                                   fill=fg_dim, font=(FONT_BODY, 8))
                state["hit"].append((x - 40, 10, x + 40, 80, s))
            else:
                cv.create_oval(x - 9, 21, x + 9, 39, fill=C.BRASS, outline="")
                cv.create_text(x, 56, text="Done", fill=fg, font=(FONT_BODY, 10, "bold"))

    def at(e):
        for x0, y0, x1, y1, s in state["hit"]:
            if x0 <= e.x <= x1 and y0 <= e.y <= y1:
                return s
        return None

    def motion(e):
        s = at(e)
        if s:
            tip.show(e.x, e.y, [f"{s['title']} · {_plural(s['n'], 'question')}", s["purpose"],
                                ", ".join(s["skills"][:4])])
        else:
            tip.hide()

    def click(e):
        s = at(e)
        if not s:
            return
        if state["shown"] == s["key"]:
            detail.pack_forget()
            state["shown"] = None
            return
        state["shown"] = s["key"]
        detail.configure(text=f"{s['title']}: {s['purpose']}"
                         + (f"\nSkills: {', '.join(s['skills'])}." if s["skills"] else ""))
        detail.pack(anchor="w", fill="x", pady=(0, 8))
    cv.bind("<Motion>", motion)
    cv.bind("<Leave>", lambda e: tip.hide())
    cv.bind("<Button-1>", click)
    cv.bind("<Configure>", lambda e: draw(1.0))
    vis_animate(cv, 600, lambda t: draw(t), reduced=reduced)
    return cv


def vis_why_chain(parent, steps):
    wrapf = ctk.CTkFrame(parent, fg_color="transparent")
    wrapf.pack(fill="x")
    marks = {"evidence": ("Noticed", C.PAPER), "reading": ("So", C.PAPER), "action": ("Today", C.NAVY)}
    merged = []
    for s in steps:
        if merged and merged[-1]["kind"] == s["kind"] == "evidence":
            merged[-1] = {"kind": "evidence", "text": merged[-1]["text"] + "\n" + s["text"]}
        else:
            merged.append(dict(s))
    steps = merged
    for i, s in enumerate(steps):
        head, bg = marks[s["kind"]]
        row = ctk.CTkFrame(wrapf, fg_color=bg, corner_radius=8, border_width=1,
                           border_color=C.PAPER_LINE)
        row.pack(fill="x", pady=(0, 2))
        ctk.CTkLabel(row, text=head, width=64, anchor="w", font=(FONT_BODY, 10, "bold"),
                     text_color=(C.GOLD_SOFT if bg == C.NAVY else C.BRASS_DARK)).pack(side="left", padx=(10, 4), pady=6)
        lbl = ctk.CTkLabel(row, text=s["text"], anchor="w", justify="left", font=(FONT_BODY, 11),
                           text_color=(C.CREAM if bg == C.NAVY else C.INK))
        lbl.pack(side="left", fill="x", expand=True, padx=(0, 10), pady=6)
        bind_autowrap(lbl, row, padding=90)
        if i < len(steps) - 1:
            ctk.CTkLabel(wrapf, text="\u2193", text_color=C.BRASS_DARK, font=(FONT_BODY, 11),
                         height=14).pack(anchor="w", padx=34)
    return wrapf


LADDER_PULSE_CYCLES = 3
LADDER_PULSE_STEP_MS = 80


class LadderPath(ctk.CTkFrame):
    def __init__(self, parent, app, path, closest, compact=False, on_open=None):
        super().__init__(parent, fg_color="transparent")
        self.app, self.path, self.closest, self.compact = app, path, closest, compact
        self.sel = next((p["rung"] for p in path if p["state"] == "current"), None)
        self.on_open = on_open
        self.cv = tk.Canvas(self, height=(70 if compact else 76 * max(1, len(path)) + 20),
                            bg=C.PAPER, highlightthickness=0, cursor="hand2")
        self.cv.pack(fill="x")
        self.detail = ctk.CTkFrame(self, fg_color="transparent")
        if not compact:
            self.detail.pack(fill="x", pady=(8, 0))
        self.hit = []
        self.reduced = vis_reduced_motion(app.conn)
        self.pulse = 0.0
        self.pulsing = not self.reduced
        self.cv.bind("<Configure>", lambda e: self.draw())
        self.cv.bind("<Button-1>", self.click)
        self._render_detail()
        if self.pulsing:
            self._tick()

    def _tick(self):
        try:
            if not self.cv.winfo_exists():
                return
        except tk.TclError:
            return
        # Three gentle cycles when the path appears, then still: an ambient
        # indicator that redraws forever costs power and says nothing new.
        self.pulse += 0.25
        if self.pulse >= LADDER_PULSE_CYCLES * 2 * math.pi:
            self.pulse = 0.0
            self.pulsing = False
            self.draw()
            return
        self.draw()
        self.cv.after(LADDER_PULSE_STEP_MS, self._tick)

    def draw(self):
        cv = self.cv
        cv.delete("all")
        self.hit = []
        if not self.path:
            return
        w = max(300, int(cv.winfo_width() or 600))
        k = len(self.path)
        pts = []
        for i, p in enumerate(self.path):
            if self.compact:
                x, y = 30 + i * (w - 60) / max(1, k - 1), 26
            else:
                x, y = 44, 30 + (k - 1 - i) * 76
            pts.append((x, y))
        for i in range(k - 1):
            (xa, ya), (xb, yb) = pts[i], pts[i + 1]
            locked = self.path[i + 1]["state"] == "locked"
            cv.create_line(xa, ya, xb, yb, fill=(C.PAPER_LINE if locked else C.BRASS), width=3,
                           dash=((4, 4) if locked else ()))
        for (x, y), p in zip(pts, self.path):
            r = 13
            if p["state"] == "current":
                rr = r + 4 + 2 * math.sin(self.pulse)
                cv.create_oval(x - rr, y - rr, x + rr, y + rr, outline=C.BRASS, width=2)
                cv.create_oval(x - r, y - r, x + r, y + r, fill=C.BRASS, outline="")
            elif p["state"] == "open":
                cv.create_oval(x - r, y - r, x + r, y + r, fill=C.NAVY, outline="")
            else:
                cv.create_oval(x - r, y - r, x + r, y + r, fill=C.PAPER, outline=C.PAPER_LINE, width=2,
                               dash=(3, 2))
            cv.create_text(x, y, text=str(p["rung"]), fill=(C.PAPER if p["state"] != "locked" else C.INK_DIM),
                           font=(FONT_BODY, 10, "bold"))
            if self.compact:
                cv.create_text(x, y + 26, text=p["label"][:18], fill=C.INK_DIM, font=(FONT_BODY, 8))
                self.hit.append((x - 30, y - 20, x + 30, y + 36, p))
            else:
                st = {"current": "You are here", "open": "Open", "locked": "Locked"}[p["state"]]
                cv.create_text(x + 30, y - 8, text=p["label"], anchor="w", fill=C.INK,
                               font=(FONT_BODY, 12, "bold" if p["rung"] == self.sel else "normal"))
                cv.create_text(x + 30, y + 10, text=st + (f" \u2014 {p['condition']}" if p["condition"] else ""),
                               anchor="w", fill=C.INK_DIM, font=(FONT_BODY, 10), width=w - 90)
                self.hit.append((0, y - 30, w, y + 30, p))

    def click(self, e):
        for x0, y0, x1, y1, p in self.hit:
            if x0 <= e.x <= x1 and y0 <= e.y <= y1:
                if self.compact:
                    (self.on_open or (lambda: self.app.show_view("practice")))()
                    return
                self.sel = p["rung"]
                self.draw()
                self._render_detail()
                return

    def _render_detail(self):
        if self.compact:
            return
        for w_ in self.detail.winfo_children():
            w_.destroy()
        p = next((x for x in self.path if x["rung"] == self.sel), None)
        if not p:
            return
        c = card(self.detail)
        c.pack(fill="x")
        inner = ctk.CTkFrame(c, fg_color="transparent")
        inner.pack(fill="x", padx=16, pady=12)
        ctk.CTkLabel(inner, text=f"Rung {p['rung']} · {p['label']}", font=(FONT_BODY, 13, "bold"),
                     text_color=C.INK, anchor="w").pack(anchor="w")
        if p["commit"]:
            ctk.CTkLabel(inner, text=p["commit"], font=(FONT_BODY, 11), text_color=C.INK, anchor="w",
                         justify="left", wraplength=620).pack(anchor="w", pady=(2, 0))
        if p["state"] == "locked":
            ctk.CTkLabel(inner, text=p["condition"], font=(FONT_BODY, 11, "italic"), text_color=C.INK_DIM,
                         anchor="w", justify="left", wraplength=620).pack(anchor="w", pady=(4, 0))
            if self.closest:
                ctk.CTkLabel(inner, text="Closest to going solid:", font=(FONT_BODY, 11, "bold"),
                             text_color=C.INK, anchor="w").pack(anchor="w", pady=(8, 2))
                for s in self.closest[:5]:
                    ghost_button(inner, f"{s['label'][:44]} · {s['step']} · {s['next']}",
                                 lambda sid=s["sid"]: vis_go_map(self.app, sid)).pack(anchor="w", pady=1)
        else:
            def go(key=p["key"], tier=p["tier"]):
                self.app._ladder_tier = tier
                self.app.show_view(key)
            primary_button(inner, "Open", go, width=90).pack(anchor="w", pady=(8, 0))


def vis_go_map(app, sid=None, tid=None):
    app._map_focus = {"sid": sid, "tid": tid or (SKILLS[sid]["topic"] if sid else None)}
    app.show_view("map")


def vis_in_motion(parent, app, vs):
    items = present_in_motion(vs)
    if not items:
        ctk.CTkLabel(parent, text="Nothing is mid-ladder yet. Skills appear here once they start "
                     "spaced recall.", font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w",
                     justify="left", wraplength=300).pack(anchor="w", padx=12, pady=8)
        return
    for n in items:
        row = ctk.CTkFrame(parent, fg_color="transparent", cursor="hand2")
        row.pack(fill="x", padx=10, pady=4)
        cv = tk.Canvas(row, width=300, height=46, bg=C.PAPER_DIM, highlightthickness=0, cursor="hand2")
        cv.pack(fill="x")
        vis_draw_glyph(cv, 18, 18, 10, n["glyph"], n["overlays"])
        cv.create_text(36, 11, text=n["label"][:40], anchor="w", font=(FONT_BODY, 10, "bold"), fill=C.INK)
        for i in range(n["need"]):
            x = 40 + i * 18
            cv.create_oval(x - 5, 29, x + 5, 39, fill=(C.NAVY if i < n["done"] else C.PAPER),
                           outline=C.INK_DIM)
        cv.create_text(40 + n["need"] * 18, 34, text=n["next"], anchor="w", font=(FONT_BODY, 9),
                       fill=C.INK_DIM)
