EVENT_SYMBOL = {"moved": "\u2197", "review_cleared": "\u2713", "ready": "\u25ce", "step": "\u25cf",
                "retest": "\u21ba", "repair_started": "\u2726", "repair_closed": "\u2726",
                "review_due": "\u25f7", "ready_paused": "\u25cb", "evidence": "\u2022", "back": "\u21b2"}
EVENT_HEAD = {"moved": "Moved forward", "review_cleared": "Review done", "ready": "Ready under a clock",
              "step": "A step further", "retest": "Revisited", "repair_started": "Repair started",
              "repair_closed": "Repair closed", "review_due": "Due for review",
              "ready_paused": "Strong", "evidence": "More evidence", "back": "Back a step"}


def vis_render_events(parent, app, events, animate=True, limit=12):
    """Learning Events as a persistent list: each keeps its before and after in
    words, and a brief glyph transition orients the eye. Motion is never the
    only record of the change. Every row opens the skill on the map."""
    reduced = vis_reduced_motion(app.conn) or not animate
    for ev in events[:limit]:
        cv = tk.Canvas(parent, height=42, bg=C.PAPER, highlightthickness=0, cursor="hand2")
        cv.pack(fill="x", pady=1)
        gb, ga = COARSE_GLYPH[ev["coarse_before"]], COARSE_GLYPH[ev["coarse_after"]]
        # Static parts are drawn once; only the settling glyph is redrawn per
        # frame, by tag, so a list of events never rebuilds whole rows.
        cv.create_text(14, 21, text=EVENT_SYMBOL[ev["kind"]], fill=C.BRASS_DARK, font=(FONT_BODY, 13, "bold"))
        cv.create_text(100, 12, text=f"{EVENT_HEAD[ev['kind']]} \u00b7 {ev['label'][:60]}", anchor="w",
                       font=(FONT_BODY, 11, "bold"), fill=C.INK)
        cv.create_text(100, 30, text=ev["text"], anchor="w", font=(FONT_BODY, 10), fill=C.INK_DIM)
        if ev["coarse_before"] != ev["coarse_after"]:
            vis_draw_glyph(cv, 42, 21, 9, gb)
            cv.create_text(60, 21, text="\u2192", fill=C.INK_DIM, font=(FONT_BODY, 10))

            def draw(t, cv=cv, gb=gb, ga=ga):
                cv.delete("vis_settle")
                mid = dict(ga)
                mid["ring"] = ga["ring"] and t > 0.8
                vis_draw_glyph(cv, 78, 21, 9, mid, tags=("vis_settle",),
                               fill_override=gb["fill"] + (ga["fill"] - gb["fill"]) * t)
            vis_animate(cv, 650, draw, reduced=reduced)
        else:
            vis_draw_glyph(cv, 60, 21, 9, ga)
        cv.bind("<Button-1>", lambda e, s_=ev["sid"]: vis_go_map(app, s_))
    if len(events) > limit:
        ctk.CTkLabel(parent, text=f"and {len(events) - limit} more on the map.", font=(FONT_BODY, 11),
                     text_color=C.INK_DIM, anchor="w").pack(anchor="w")


def vis_render_session_events(app, wrap, summary):
    """The debrief's Learning Events, optionally preceded by one reflection
    question. The prompt is a governed behaviour trial, asked at most once a
    day; its outcome is the next session's confidence-accuracy agreement,
    measured against right and wrong answers, not against the model."""
    conn = app.conn
    before = summary.get("vis_before")
    if before is None:
        return None
    # Written once at completion (complete_session_events); this screen only
    # renders. A summary that never went through completion is shown, not stored.
    events = summary.get("learning_events")
    if events is None:
        try:
            after = vis_snapshot(conn)
            before = dict(before)
            for k in ("detail", "answers", "retests", "repairs"):
                before.setdefault(k, after[k])
            events = present_learning_events(before, after, summary.get("vis_served") or summary.get("served_skills"))
        except Exception as e:
            _audit(conn, "learning_events_render_failed", f"{type(e).__name__}: {e}")
            return None
    session_key = summary.get("session_key") or summary.get("session_uuid") or learning_session_id(summary)
    box = card(wrap)
    box.pack(fill="x", pady=(16, 0))
    inner = ctk.CTkFrame(box, fg_color="transparent")
    inner.pack(fill="x", padx=16, pady=12)
    ctk.CTkLabel(inner, text="What moved", font=(FONT_BODY, 12, "bold"), text_color=C.INK,
                 anchor="w").pack(anchor="w", pady=(0, 4))
    if not events:
        ctk.CTkLabel(inner, text="Nothing recorded for this session.", font=(FONT_BODY, 11),
                     text_color=C.INK_DIM, anchor="w").pack(anchor="w")
        return events
    key, already = reflection_occasion_today(conn)
    cands = reflection_candidates(events, key)
    try:
        init_reflection_schema(conn)
        this_session = conn.execute("SELECT 1 FROM reflection_judgments WHERE session_key=?",
                                    (session_key,)).fetchone() is not None
    except sqlite3.Error:
        this_session = False
    ask = (cands is not None and not already and not this_session
           and behaviour_arm(conn, "reflect_before_reveal", key))
    body = ctk.CTkFrame(inner, fg_color="transparent")
    if not ask:
        body.pack(fill="x")
        vis_render_events(body, app, events)
        return events
    q = ctk.CTkFrame(inner, fg_color="transparent")
    q.pack(fill="x")
    ctk.CTkLabel(q, text="Before you look: which of these moved forward today?",
                 font=(FONT_BODY, 12), text_color=C.INK, anchor="w", justify="left",
                 wraplength=640).pack(anchor="w", pady=(0, 6))
    moved = cands["moved"]

    def reveal(choice):
        ident = score_reflection_choice(choice, cands["correct"])
        try:
            conn.execute("INSERT INTO reflection_judgments (made_at, occasion_key, prompt, choice, actual, "
                         "candidates, identified, session_key, n_options) VALUES (?,?,?,?,?,?,?,?,?)",
                         (datetime.now().isoformat(), key, "moved_forward_today", choice,
                          json.dumps(moved), json.dumps([o["sid"] for o in cands["options"]]),
                          ident, session_key, cands["n_options"]))
            conn.commit()
        except sqlite3.Error as e:
            _audit(conn, "reflection_record_failed", f"{type(e).__name__}: {e}")
        q.destroy()
        body.pack(fill="x")
        if choice in SKILLS:
            note = (f"You picked {SKILLS[choice]['label']}. "
                    + ("It did move forward." if ident else "That one practised without moving; what moved is below."))
        else:
            note = ""
        if note:
            ctk.CTkLabel(body, text=note, font=(FONT_BODY, 11, "italic"), text_color=C.INK_DIM, anchor="w",
                         justify="left", wraplength=640).pack(anchor="w", pady=(0, 4))
            vis_announce(app, note)
        vis_render_events(body, app, events)
    row = ctk.CTkFrame(q, fg_color="transparent")
    row.pack(anchor="w")
    for c in cands["options"]:
        ghost_button(row, c["label"][:34], lambda s_=c["sid"]: reveal(s_)).pack(side="left", padx=(0, 6), pady=2)
    row2 = ctk.CTkFrame(q, fg_color="transparent")
    row2.pack(anchor="w", pady=(6, 0))
    ghost_button(row2, "Not sure \u2014 show me", lambda: reveal("unsure")).pack(side="left")
    return events


