VIS_ACTION_TARGETS = ("today", "map", "practice", "insights", "learnermodel", "loop",
                      "learninglab", "transfer", "diagnostic", "adaptive", "examsettings", "exameve")


# ---- standing catalogue: visual invariants ---------------------------------------

def _vis_seed_state():
    sids = sorted(SKILLS)
    tiers = {}
    for i, s in enumerate(sids[:60]):
        tiers[s] = VIS_TIER_ORDER[i % len(VIS_TIER_ORDER)]
    detail = {s: {"stage": "spaced", "done": 1 + (i % 2), "need": 3, "eligible_today": bool(i % 2),
                  "close": (i % 2) == 1} for i, s in enumerate(sids[10:16])}
    return {"tiers": tiers, "detail": detail, "answers": {s: i for i, s in enumerate(sids[:40])},
            "last_seen": {}, "repairs": {sids[3]: 1}, "retests": {sids[4]: 2},
            "due_on": {sids[5]: (date.today() + timedelta(days=3)).isoformat()},
            "focus": None, "ladder": [], "headline": "", "reason": "", "n_solid": 4, "n_total": len(SKILLS)}


def _vis_all_text(obj):
    if isinstance(obj, str):
        yield obj
    elif isinstance(obj, dict):
        for k, v in obj.items():
            if k in ("glyph", "before_glyph", "after_glyph", "sid", "tid", "item_ids", "qid", "a", "b",
                     "inside", "outside", "pre", "dep", "key", "tier_counts", "counts"):
                continue
            yield from _vis_all_text(v)
    elif isinstance(obj, (list, tuple)):
        for v in obj:
            yield from _vis_all_text(v)


def _probe_visual_no_numeric_leak(conn, inject=False):
    vs = _vis_seed_state()
    sids = sorted(SKILLS)
    plan = {"items": [{"q": QUIZ_BANK[next(iter(items_for_skill(s)))["id"]] if items_for_skill(s) else next(iter(QUIZ_BANK.values())),
                       "movement": m, "retest": m == "work" and i == 1, "pretest": m == "work" and i == 2,
                       "skill": s} for i, (s, m) in enumerate(zip(sids[:6], ["warm", "work", "work", "work", "close", "close"]))],
            "est_minutes": 12}
    traj = present_session_trajectory(plan)
    outputs = [present_course_map(vs), traj, present_why_chain(vs, plan, traj),
               present_in_motion(vs), present_closest_to_unlock(vs),
               present_session_changes({sids[0]: TIER_BUILDING}, {sids[0]: TIER_STEADY}),
               present_compare_alternative(vs, traj, vis_domain_order()[0]),
               present_skill_queries(present_skill_node(vs, sids[10]), vs["detail"].get(sids[10]),
                                     [{"date": date.today().isoformat(), "right": 1, "wrong": 0,
                                       "confident_wrong": 0}], [], [])]
    domains = present_course_map(vs)
    outputs += [[present_domain_rail(d) for d in domains],
                present_learning_events({"tiers": {sids[0]: TIER_BUILDING}, "detail": {}, "answers": {}, "retests": {sids[1]: 1}, "repairs": []},
                                        {"tiers": {sids[0]: TIER_STEADY}, "detail": {}, "answers": {sids[2]: 3}, "retests": {}, "repairs": [sids[3]]},
                                        served=[sids[4]]),
                vis_search("escrow deposit"), mirror_relations([]).get(sorted(SKILLS)[0], []),
                {"marks": [MARK_TEXT[m] for m in MARK_PRIORITY], "coarse": list(COARSE_ORDER)}]
    if inject:
        outputs.append({"text": "recall probability 0.62"})
    for o in outputs:
        for t in _vis_all_text(o):
            m = VIS_FORBIDDEN.search(t)
            if m:
                return False, f"a learner-facing presenter emitted {m.group(0)!r} in {t[:60]!r}"
    return True, f"{len(outputs)} presenters emit words, tiers, counts and dates only"


def _probe_visual_no_red(conn, inject=False):
    pal = dict(VIS_PALETTE)
    if inject:
        pal["fill"] = C.STAMP
    bad = [k for k, v in pal.items() if str(v).lower() in (C.STAMP.lower(), C.STAMP_DIM.lower())]
    src = _module_source() or ""
    seg = src[src.find("# V8.2 -- VISUAL COMPONENTS AND LEARNER VIEWS"):src.find("# ---- standing catalogue: visual invariants")]
    if "C.STAMP" in seg:
        bad.append("visual components reference C.STAMP")
    if bad:
        return False, "red encodes learner state: " + ", ".join(bad)
    return True, "no learner-state palette entry or visual component uses red"


def _probe_visual_spatial_stability(conn, inject=False):
    a = vis_course_layout(900, 520)
    b = vis_course_layout(900, 520)
    tid = vis_domain_order()[0]
    da = vis_domain_layout(tid, 700, 500)
    if inject:
        # the class: order by state, so a skill that moves up the ladder moves on screen
        vs = _vis_seed_state()
        vs["tiers"][vis_skills_of(tid)[0]] = TIER_STRONG
        order = sorted(vis_skills_of(tid), key=lambda s: (-vis_tier_rank(vs["tiers"].get(s, TIER_NOT_STARTED)), s))
        db = {s: da[t] for s, t in zip(order, vis_skills_of(tid))}
        if db == da:
            order = list(reversed(order))
            db = {s: da[t] for s, t in zip(order, vis_skills_of(tid))}
    else:
        db = vis_domain_layout(tid, 700, 500)
    if a != b or da != db:
        return False, "a skill's position depends on its state"
    return True, "course and domain layouts are functions of the curriculum and canvas size only"


def _probe_visual_shape_distinct(conn, inject=False):
    sig = {t: vis_glyph_signature(t) for t in VIS_TIER_ORDER}
    coarse = {c: tuple(COARSE_GLYPH[c][k] for k in ("fill", "ring", "outer", "clock", "dash")) for c in COARSE_ORDER}
    if len(set(coarse.values())) != len(coarse):
        return False, "coarse states distinguishable only by colour"
    if inject:
        sig[TIER_STEADY] = sig[TIER_BUILDING]
    dup = [t for t in VIS_TIER_ORDER if list(sig.values()).count(sig[t]) > 1]
    if dup:
        return False, "tiers distinguishable only by colour: " + ", ".join(dup)
    return True, f"{len(sig)} tiers, {len(set(sig.values()))} distinct shape signatures"


def _probe_visual_trajectory_complete(conn, inject=False):
    qs = list(QUIZ_BANK.values())[:9]
    moves = ["warm", "warm", "work", "work", "work", "work", "work", "close", "close"]
    plan = {"items": [{"q": q, "movement": m, "retest": i == 3, "pretest": i == 4,
                       "partner_of": ("x" if i == 5 else None), "skill": None}
                      for i, (q, m) in enumerate(zip(qs, moves))]}
    traj = present_session_trajectory(plan)
    if inject:
        traj = [{"key": "work", "n": 5, "item_ids": [], "title": ", ".join(sorted(set(moves)))}]
    ids = [i for s in traj for i in s["item_ids"]]
    if sorted(ids) != sorted(q["id"] for q in qs) or sum(s["n"] for s in traj) != len(qs):
        return False, "the session picture loses or duplicates planned items"
    keys = [s["key"] for s in traj]
    if keys != sorted(keys, key=_STAGE_ORDER.index):
        return False, "stages are out of session order"
    return True, f"{len(qs)} items in {len(traj)} stages: " + " \u2192 ".join(s["title"] for s in traj)


def _probe_visual_ladder_matches_contract(conn, inject=False):
    rungs = ladder_rungs(conn)
    path = present_ladder_path(rungs)
    if inject:
        path = [dict(p, state=("open" if p["state"] == "locked" else p["state"])) for p in path]
    for r, p in zip(sorted(rungs, key=lambda x: x["rung"]), path):
        if bool(r["open"]) != (p["state"] != "locked"):
            return False, f"rung {r['rung']} drawn as {p['state']} but the contract says open={r['open']}"
    cur = [p for p in path if p["state"] == "current"]
    if len(cur) > 1:
        return False, "more than one rung drawn as current"
    return True, f"{len(path)} rungs drawn exactly as the contract opens them"


def _probe_visual_changes_real(conn, inject=False):
    sids = sorted(SKILLS)[:4]
    before = {sids[0]: TIER_BUILDING, sids[1]: TIER_STRONG, sids[2]: TIER_FAMILIAR}
    after = {sids[0]: TIER_STEADY, sids[1]: TIER_STRONG, sids[2]: TIER_FAMILIAR, sids[3]: TIER_NOT_STARTED}
    ch = present_session_changes(before, after)
    if inject:
        ch = ch + [{"sid": sids[1], "before": TIER_STRONG, "after": TIER_STRONG}]
    wrong = [c for c in ch if c["before"] == c["after"]]
    if wrong or [c["sid"] for c in ch] != [sids[0]]:
        return False, "the debrief shows movement that did not happen"
    rs = present_session_changes({sids[0]: TIER_STRONG}, {sids[0]: TIER_REVIEW_SOON})
    if rs[0]["direction"] != "schedule":
        return False, "a review becoming due is shown as a loss"
    return True, "only real tier changes are shown; review-due is a schedule change, not a step back"


def _probe_visual_actions_resolve(conn, inject=False):
    targets = list(VIS_ACTION_TARGETS) + [k for k, _l, _b in WORKSHOP_TOOLS]
    if inject:
        targets.append("progress_dashboard_v2")
    missing = sorted({t for t in targets if t not in VIEW_MAP})
    nav = [k for _g, items in NAV_GROUPS for k, _l in items]
    missing += [k for k in nav if k not in VIEW_MAP]
    if missing:
        return False, "interactive targets with no view: " + ", ".join(missing)
    return True, f"{len(set(targets))} interactive targets and {len(nav)} navigation entries all resolve"


def _probe_visual_reduced_motion(conn, inject=False):
    frames = []

    class _W:
        def winfo_exists(self):
            return True

        def after(self, ms, fn):
            frames.append(ms)
            if len(frames) < 200:
                fn()
    seen = []
    if inject:
        vis_animate(_W(), 300, lambda t: seen.append(t), reduced=False)
        vis_animate_ok = len(seen) == 1
    else:
        set_setting(conn, "reduce_motion", "1")
        vis_animate(_W(), 300, lambda t: seen.append(t), reduced=vis_reduced_motion(conn))
        vis_animate_ok = seen == [1.0]
    if not vis_animate_ok:
        return False, f"motion ran {len(seen)} frames with reduced motion on"
    return True, "with reduced motion on, every transition draws its end state in one frame"


def _probe_visual_compare_descriptive(conn, inject=False):
    vs = _vis_seed_state()
    out = present_compare_alternative(vs, [{"key": "revisit", "n": 2}], vis_domain_order()[1])
    lines = out["recommended"] + out["alternative"] + out["waiting"]
    if inject:
        lines.append("Choosing this will likely raise your chance of passing.")
    bad = [l for l in lines if VIS_PREDICTIVE.search(l) or VIS_FORBIDDEN.search(l)]
    if bad:
        return False, f"a comparison predicts outcomes: {bad[0]!r}"
    return True, "the alternative-session comparison describes contents and what waits, and predicts nothing"


for _name, _spec in (
    ("visual_numeric_leak", {"title": "A picture that smuggles a number",
        "failure_class": "Richer visuals reintroducing internal quantities as labels or tooltips.",
        "invariant": "Visual presenters emit words, tiers, counts and dates only.",
        "found_in": "V8.2 visual surface design.", "probe": _probe_visual_no_numeric_leak}),
    ("visual_red_state", {"title": "Red used for a place on the map",
        "failure_class": "Low progress drawn in the colour reserved for errors and destructive actions.",
        "invariant": "No learner-state palette entry or visual component uses red.",
        "found_in": "Review of the V8 learner-model constellation.", "probe": _probe_visual_no_red}),
    ("visual_spatial_instability", {"title": "Skills that move when learning happens",
        "failure_class": "Position encoding state, so the map rearranges and spatial memory fails.",
        "invariant": "Layout is a function of curriculum and canvas size only.",
        "found_in": "Review of the V8 constellation layout.", "probe": _probe_visual_spatial_stability}),
    ("visual_colour_only", {"title": "State distinguishable only by colour",
        "failure_class": "Two tiers drawn with the same shape and told apart by hue alone.",
        "invariant": "Every tier has a distinct shape signature.",
        "found_in": "V8.2 accessibility requirement.", "probe": _probe_visual_shape_distinct}),
    ("visual_trajectory_lossy", {"title": "A session picture that drops the plan",
        "failure_class": "The composed session reduced to a label, or stages that lose or repeat items.",
        "invariant": "Every planned item appears in exactly one stage, in session order.",
        "found_in": "Review of V8 Today (movements joined into a string).",
        "probe": _probe_visual_trajectory_complete}),
    ("visual_ladder_disagrees", {"title": "A ladder drawing with its own rules",
        "failure_class": "The visual path deciding openness separately from the contract.",
        "invariant": "Every rung is drawn open exactly when the contract opens it.",
        "found_in": "V8.2 ladder path.", "probe": _probe_visual_ladder_matches_contract}),
    ("visual_invented_movement", {"title": "Movement shown that did not happen",
        "failure_class": "A debrief animating skills that were practised but did not change tier.",
        "invariant": "Only real tier changes appear; review-due is a schedule change.",
        "found_in": "V8.2 session changes.", "probe": _probe_visual_changes_real}),
    ("visual_dead_end", {"title": "A clickable thing that goes nowhere",
        "failure_class": "Direct manipulation targets or navigation entries naming views that do not exist.",
        "invariant": "Every interactive target and nav entry resolves to a registered view.",
        "found_in": "V8.2 navigation restructure.", "probe": _probe_visual_actions_resolve}),
    ("visual_motion_ignores_setting", {"title": "Motion that ignores reduced motion",
        "failure_class": "Animated transitions running for a learner who turned motion off.",
        "invariant": "With reduced motion on, transitions draw their end state in one frame.",
        "found_in": "V8.2 motion layer.", "probe": _probe_visual_reduced_motion}),
    ("visual_comparison_predicts", {"title": "A choice between sessions framed as a prediction",
        "failure_class": "An alternative-action comparison promising outcomes the evidence cannot support.",
        "invariant": "Comparisons describe what a session contains and what waits.",
        "found_in": "V8.2 alternative-session comparison.", "probe": _probe_visual_compare_descriptive}),
):
    register_adversarial_class(_name, _spec)


# ---- V8.3 visual invariants ---------------------------------------------------------

def _probe_v83_no_silent_truncation(conn, inject=False):
    vs = _vis_seed_state()
    for d in present_course_map(vs):
        rail = present_domain_rail(d)
        total = sum(seg["n"] for seg in rail["segments"])
        if inject:
            total = min(total, 6)
        if total != len(vis_skills_of(d["tid"])) or rail["total"] != total:
            return False, f"{d['short']}: the course view accounts for {total} of {len(vis_skills_of(d['tid']))} skills"
    order = [seg["state"] for seg in present_domain_rail(present_course_map(vs)[0])["segments"]]
    if order[0] != COARSE_STRONG or order[-1] != COARSE_NOT_STARTED:
        return False, "rail extremes are not anchored (Strong left, Not started right)"
    return True, f"all {len(SKILLS)} skills counted across {len(TOPICS)} area rails, extremes anchored"


def _probe_v83_mark_budget(conn, inject=False):
    node = {"tier": TIER_REVIEW_SOON, "overlays": ["repair", "retest", "moving", "little_evidence"]}
    budget = dict(LOD_MARK_BUDGET)
    if inject:
        budget["domain"] = None
    course = node_marks(node)[:budget["course"]] if budget["course"] is not None else node_marks(node)
    domain = node_marks(node)[:budget["domain"]] if budget["domain"] is not None else node_marks(node)
    if len(course) != 0 or len(domain) > 1:
        return False, f"marks drawn: course {len(course)}, area {len(domain)}"
    if domain != ["repair"] or "little_evidence" in node_marks(node):
        return False, "the mark shown is not the highest-priority one, or the halo spends the budget"
    if len(node_marks(node)) != 4:
        return False, "the inspector does not receive every mark"
    return True, "course 0 marks, area 1 (highest priority), inspector all; halo is background"


def _probe_v83_coarse_mapping(conn, inject=False):
    mapping = dict(COARSE_OF)
    if inject:
        mapping[TIER_STEADY] = COARSE_STARTED
    missing = [t for t in VIS_TIER_ORDER if t not in mapping]
    ranks = [COARSE_ORDER[::-1].index(mapping[t]) for t in VIS_TIER_ORDER[:6]]
    if missing or ranks != sorted(ranks):
        return False, "coarse states do not preserve the ladder order of the eight tiers"
    return True, "eight tiers fold into four coarse states without reordering the ladder"


def _probe_v83_events_acknowledge_practice(conn, inject=False):
    sid = sorted(SKILLS)[0]
    before = {"tiers": {sid: TIER_BUILDING}, "detail": {sid: {"stage": "spaced", "done": 1, "need": 3}},
              "answers": {sid: 4}, "retests": {}, "repairs": []}
    same = {"tiers": {sid: TIER_BUILDING}, "detail": {sid: {"stage": "spaced", "done": 1, "need": 3}},
            "answers": {sid: 6}, "retests": {}, "repairs": []}
    step = {"tiers": {sid: TIER_BUILDING}, "detail": {sid: {"stage": "spaced", "done": 2, "need": 3}},
            "answers": {sid: 6}, "retests": {}, "repairs": []}
    ev_same = present_learning_events(before, same, served=[sid])
    ev_step = present_learning_events(before, step, served=[sid])
    if inject:
        ev_same = [e for e in present_session_changes(before["tiers"], same["tiers"])]
    if not ev_same or ev_same[0].get("kind") != "evidence":
        return False, "practice with no tier change produced no event"
    if not ev_step or ev_step[0]["kind"] != "step":
        return False, "a spaced day held within a tier was not reported"
    return True, "same-tier practice and a held spaced day both appear as events"


def _probe_v83_nav_highlight(conn, inject=False):
    nav = {k for _g, items in NAV_GROUPS for k, _l in items}
    table = dict(NAV_HIGHLIGHT)
    if inject:
        table["quiz"] = "workshop"
    bad = [f"{k}->{v}" for k, v in table.items() if v not in nav]
    unmapped = [k for k in VIEW_MAP if k not in nav and k not in table
                and k not in {x for x, _l in AUTHOR_NAV}]
    if bad or unmapped:
        return False, "views with no lit destination: " + ", ".join(bad + unmapped)
    return True, f"every learner view lights one of {sorted(nav)}"


def _plan_signature(plan):
    return [(it["q"]["id"], it["movement"], bool(it.get("retest")), bool(it.get("pretest")))
            for it in (plan or {}).get("items", [])]


def _probe_v831_one_composer(conn, inject=False):
    """Class: a counterfactual built by a second policy. The area alternative
    must be the same composer under a constraint, which also means a
    constraint admitting every area must reproduce the recommendation."""
    init_schema(conn)
    sid_list = sorted(SKILLS)
    for i, sid in enumerate(sid_list[:40]):
        qs = items_for_skill(sid)
        if qs:
            conn.execute("INSERT INTO attempts (question_id, topic_id, correct, a_irt, b_irt, mode, timestamp, confidence) "
                         "VALUES (?,?,?,?,?,?,?,?)", (qs[0]["id"], qs[0]["topic"], i % 3 != 0, qs[0]["a_irt"],
                                                      qs[0]["b_irt"], "quiz", datetime.now().isoformat(), 2))
            record_skill_evidence(conn, sid, i % 3 != 0, 30, 2, "quiz", question=qs[0])
    conn.commit()
    rec = compose_session(conn)
    everything = compose_session(conn, constraints={"topics": list(TOPICS)})
    if inject:
        everything = {"items": list(rec["items"])[:-1]}
    if _plan_signature(rec) != _plan_signature(everything):
        return False, "a constraint admitting every area does not reproduce the recommendation"
    for tid in vis_domain_order()[:6]:
        alt = compose_area_session(conn, tid)
        stray = [it for it in alt["items"] if it["q"]["topic"] != tid
                 or (it.get("skill") and SKILLS.get(it["skill"], {}).get("topic") != tid)]
        if stray:
            return False, f"the {tid} alternative contains {len(stray)} item(s) from other areas"
    src = _module_source() or ""
    if re.search(r"^def (vis_item_value|compose_constrained_session|knapsack_select)\(", src, re.M):
        return False, "a second session objective is still defined"
    return True, "all-area constraint reproduces the recommendation; area alternatives stay in their area"


def _probe_v831_events_idempotent(conn, inject=False):
    sid = sorted(SKILLS)[0]
    evs = present_learning_events({"tiers": {sid: TIER_BUILDING}, "detail": {sid: {"stage": "spaced", "done": 1, "need": 3}}},
                                  {"tiers": {sid: TIER_BUILDING}, "detail": {sid: {"stage": "spaced", "done": 2, "need": 3}}},
                                  served=[sid])
    key = learning_session_id({"attempt_id_start": 41})
    record_learning_events(conn, evs, key)
    if inject:
        conn.execute("DROP INDEX IF EXISTS ux_learning_events_identity")
        conn.execute("INSERT INTO learning_events (occurred_at, session_key, kind, skill_id, before_tier, after_tier, text) "
                     "SELECT occurred_at, session_key, kind, skill_id, before_tier, after_tier, text FROM learning_events")
        conn.commit()
    else:
        record_learning_events(conn, evs, key)
        record_learning_events(conn, evs, learning_session_id({"attempt_id_start": 41}))
    n = conn.execute("SELECT COUNT(*) FROM learning_events WHERE session_key=?", (key,)).fetchone()[0]
    if n != len(evs):
        return False, f"one session's {len(evs)} event(s) stored {n} times over"
    return True, f"re-rendering a debrief three times stores its {len(evs)} event(s) once"


def _probe_v831_strong_group_words(conn, inject=False):
    sid = sorted(SKILLS)[0]
    expect = {(TIER_REVIEW_SOON, TIER_STRONG): "review_cleared",
              (TIER_REVIEW_SOON, TIER_READY_FOR_SIMULATION): "review_cleared",
              (TIER_STRONG, TIER_READY_FOR_SIMULATION): "ready",
              (TIER_STRONG, TIER_REVIEW_SOON): "review_due",
              (TIER_READY_FOR_SIMULATION, TIER_REVIEW_SOON): "review_due",
              (TIER_READY_FOR_SIMULATION, TIER_STRONG): "ready_paused"}
    for (b, a), kind in expect.items():
        ev = present_learning_events({"tiers": {sid: b}}, {"tiers": {sid: a}})
        got = "review_due" if inject else (ev[0]["kind"] if ev else None)
        if got != kind:
            return False, f"{b} \u2192 {a} reported as {got!r}, not {kind!r}"
    return True, "all six changes within Strong are named for what they are"


def _probe_v831_reflection_answerable(conn, inject=False):
    """Superseded in V9.1: the class keeps its name and now runs _probe_v91_reflection_standard."""
    return _probe_v91_reflection_standard(conn, inject)


def _probe_v831_area_density(conn, inject=False):
    """Superseded in V9.1: the class keeps its name and now runs _probe_v91_label_collision."""
    return _probe_v91_label_collision(conn, inject)


def _probe_v831_mirror_graph_parity(conn, inject=False):
    edges = vis_prereq_edges(conn) or [(sorted(SKILLS)[0], sorted(SKILLS)[1])]
    rel = mirror_relations(edges)
    if inject:
        rel = {k: [r for r in v if r[0] != "Often confused with"] for k, v in rel.items()}
    for p in vis_confusion_pairs():
        if ("Often confused with", p["b"]) not in rel.get(p["a"], []) or ("Often confused with", p["a"]) not in rel.get(p["b"], []):
            return False, f"the list view cannot follow the mix-up link {p['a']} \u2194 {p['b']}"
    for pre, dep in edges:
        if ("Builds on", pre) not in rel.get(dep, []) or ("Leads to", dep) not in rel.get(pre, []):
            return False, f"the list view cannot follow the prerequisite {pre} \u2192 {dep}"
    return True, f"every link the map can draw is a navigable row in the list ({sum(map(len, rel.values()))} rows)"


def _probe_v831_accessible_entry(conn, inject=False):
    src = _module_source() or ""
    seg = src[src.find("class CourseMap(ctk.CTkFrame):"):src.find("class MapMirror(ttk.Frame):")]
    if inject:
        seg = seg.replace('ttk.Button(row2, text="List view (Alt+L)"', 'ghost_button(row2, "List view"')
    if 'self.mirror_btn = ttk.Button(' not in seg:
        return False, "the control that opens the accessible list is not a native widget"
    if '"<Alt-l>"' not in seg and "vis_bind_global_shortcuts(app)" not in seg:
        return False, "the accessible list has no keyboard shortcut"
    if "vis_accessible_mode(self.conn)" not in seg:
        return False, "accessible mode does not open the list by default"
    return True, "the list view opens from a native button, from Alt+L, and by default in accessible mode"


def _probe_v831_search_shared_index(conn, inject=False):
    init_schema(conn)
    n_idx = conn.execute("SELECT COUNT(*) FROM content_search WHERE kind='skill'").fetchone()[0]
    if inject:
        n_idx = 0
    if n_idx != len(SKILLS):
        return False, f"the shared search index holds {n_idx} of {len(SKILLS)} skills"
    misses = []
    for sid, meta in SKILLS.items():
        res = [r["sid"] for r in vis_search(meta["label"], limit=5, conn=conn)]
        if sid not in res:
            misses.append(meta["label"])
    if misses:
        return False, f"{len(misses)} skill(s) not found by their own name, e.g. {misses[0]!r}"
    a = [r["sid"] for r in vis_search("escrow deposit", conn=conn)]
    if a != [r["sid"] for r in vis_search("escrow deposit", conn=conn)]:
        return False, "the same query lists differently"
    return True, f"map search reads the same FTS5 index as Search; all {len(SKILLS)} skills found by name"


def _probe_v83_week_movement_first(conn, inject=False):
    wk = present_week(conn)
    lines = list(wk["movement"])
    if inject:
        lines.insert(0, "5 day streak")
    bad = [l for l in lines if re.search(r"streak|in a row of days|don't break|keep it up", l, re.I)]
    if bad or VIS_FORBIDDEN.search(" ".join(lines)):
        return False, f"the weekly view leads with activity or streak language: {bad[:1]}"
    if "practised_days" not in wk or wk.get("movement") is None:
        return False, "movement lines missing"
    return True, "the week leads with movement; activity is secondary context"


def _probe_v83_edges_on_demand(conn, inject=False):
    pairs = vis_confusion_pairs()
    tid = next((SKILLS[p["a"]]["topic"] for p in pairs if SKILLS[p["a"]]["topic"] == SKILLS[p["b"]]["topic"]), None)
    if tid is None:
        return True, "no in-area pairs to check"
    links = present_domain_links([], tid)
    mode = "All" if inject else "On selection"
    none_selected = vis_edges_to_draw(links, mode, [])
    if none_selected["confusions"] or none_selected["prereqs"]:
        return False, "links drawn with nothing selected"
    sel = vis_edges_to_draw(links, "On selection", [links["confusions"][0]["a"]])
    if not sel["confusions"]:
        return False, "selecting a skill does not reveal its links"
    return True, "no links until a skill is pointed at or chosen; its own links then appear"


def _probe_v83_bounded_ambient_motion(conn, inject=False):
    cycles = float("inf") if inject else LADDER_PULSE_CYCLES
    frames = cycles * 2 * math.pi / 0.25
    if not math.isfinite(frames) or frames * LADDER_PULSE_STEP_MS > 10000:
        return False, "the ladder pulse redraws without end"
    return True, f"ladder pulse stops after {LADDER_PULSE_CYCLES} cycles (~{frames * LADDER_PULSE_STEP_MS / 1000:.0f} s)"


def _probe_v83_search_resolves(conn, inject=False):
    checks = 0
    for sid, meta in list(SKILLS.items())[:40]:
        word = max(re.findall(r"[A-Za-z]{5,}", meta["label"]) or [""], key=len)
        if not word:
            continue
        res = vis_search(word, conn=conn)
        if inject:
            res = res[1:]
        if sid not in [r["sid"] for r in vis_search(meta["label"], conn=conn)[:3]] and not inject:
            return False, f"searching the full name does not find {meta['label']!r}"
        if inject and sid not in [r["sid"] for r in res]:
            return False, f"{meta['label']!r} is not reachable from search"
        if [r["sid"] for r in vis_search(word, conn=conn)] != [r["sid"] for r in vis_search(word, conn=conn)]:
            return False, "the same query lists differently"
        checks += 1
    return True, f"{checks} skills found by name; repeated queries list identically"


def _probe_v83_reflection_measured_on_performance(conn, inject=False):
    init_schema(conn)
    base = conn.execute("SELECT COALESCE(MAX(id),0) FROM attempts").fetchone()[0]
    q = next(iter(QUIZ_BANK.values()))
    for conf, ok in ((3, 1), (3, 1), (3, 0), (1, 0)):
        conn.execute("INSERT INTO attempts (question_id, topic_id, correct, mode, timestamp, confidence) "
                     "VALUES (?,?,?,?,?,?)", (q["id"], q["topic"], ok, "quiz", datetime.now().isoformat(), conf))
    conn.commit()
    s1 = session_calibration_score(conn, base)
    conn.execute("UPDATE attempts SET correct = 1 - correct WHERE id > ?", (base,))
    conn.commit()
    s2 = session_calibration_score(conn, base)
    if inject:
        s2 = s1
    if s1 is None or s2 is None or abs(s1 - s2) < 1e-9:
        return False, "the trial outcome does not respond to right and wrong answers"
    import inspect
    src = inspect.getsource(session_calibration_score)
    if re.search(r"learner_state|tiers|ability_with_se|mastery", src):
        return False, "the trial outcome reads the model rather than performance"
    return True, "the reflection trial is scored on confidence against correctness only"


def _probe_v83_announcements_contract_safe(conn, inject=False):
    class _App:
        pass
    app = _App()
    app.conn = conn
    said = []

    class _Var:
        def set(self, t):
            said.append(t)
    app._vis_status_var = _Var()
    vis_announce(app, "Agency creation, Building, can move today")
    blocked = vis_announce(app, "recall probability 0.62") if not inject else (said.append("0.62") or True)
    if any(VIS_FORBIDDEN.search(t) for t in said) or blocked is not False:
        return False, "an announcement carried an internal number"
    return True, "announcements pass contract vocabulary and refuse internal numbers"


