# ===========================================================================
# V8.4 -- EXPLORATION, COVERAGE, RANDOMIZED EVALUATION, ONE NAVIGATION GRAPH
# ===========================================================================
# The recursive loop at the schedule timescale: the composer chooses items,
# those answers train the models, and the models steer the composer. Data
# gathered only where the policy chose to look is confounded by the policy
# (Chaney, Stewart & Engelhardt 2018): it homogenises what is practised and
# biases held-out evaluation. Three guards close the loop:
#   1. a small, logged exploration share: some sessions swap one expendable
#      work item for a skill the composer has stopped visiting, chosen with a
#      known probability;
#   2. a coverage floor: every skill that has been started is measured again
#      within EXPLORATION_STALE_DAYS, and the stale list is the exploration pool;
#   3. model changes are evaluated on the randomized occasions only, weighted
#      by the inverse of their logged propensity.

EXPLORATION_SHARE = 0.15          # probability a session carries one exploration item
EXPLORATION_STALE_DAYS = 21


def _exploration_key(conn):
    try:
        wm = conn.execute("SELECT COALESCE(MAX(id), 0) FROM attempts").fetchone()[0]
    except sqlite3.Error:
        wm = 0
    return f"{date.today().isoformat()}|{wm}"


def _unit_hash(text):
    return int(hashlib.sha256(text.encode()).hexdigest()[:12], 16) / float(16 ** 12)


def coverage_report(conn, days=EXPLORATION_STALE_DAYS, topics=None):
    """Started skills with no measured answer in the last `days` days."""
    since = (date.today() - timedelta(days=days)).isoformat()
    recent, ever = set(), set()
    try:
        for r in _safe_query(conn, "SELECT question_id, MAX(substr(timestamp,1,10)) d FROM attempts "
                                   "WHERE mode IS NULL OR mode NOT IN ('pretest','freerecall') "
                                   "GROUP BY question_id"):
            for sid in Q_MATRIX.get(r["question_id"], []):
                ever.add(sid)
                if r["d"] and r["d"] >= since:
                    recent.add(sid)
    except Exception:
        pass
    allowed = set(topics or TOPICS)
    stale = sorted(s for s in ever - recent if s in SKILLS and SKILLS[s]["topic"] in allowed)
    return {"stale": stale, "measured_recently": len(recent), "started": len(ever), "days": days}


def exploration_decision(key, pool, share=None):
    """Deterministic in the occasion key, so a plan composed twice for the same
    occasion is identical. Returns (skill or None, propensity of that skill).
    The share is read when called, so a governed change takes effect at once."""
    share = EXPLORATION_SHARE if share is None else share
    if not pool:
        return None, None
    if _unit_hash("explore-gate|" + key) >= share:
        return None, None
    idx = int(_unit_hash("explore-pick|" + key) * len(pool)) % len(pool)
    return sorted(pool)[idx], share / len(pool)


def apply_exploration(conn, plan, seen_q, allowed_topics):
    """Swap one expendable work item for an item of a stale skill, when the
    occasion's draw says so. Runs AFTER the time budget, so the logged
    propensity is the probability of being served, not merely of being picked
    before trimming. Records the occasion's eligibility either way, so the
    evaluation knows how many occasions could have explored."""
    key = _exploration_key(conn)
    pool = coverage_report(conn, topics=allowed_topics)["stale"] + contradicted_skills(conn, allowed_topics)
    pool = sorted(set(s for s in pool if any(q["id"] not in seen_q for q in items_for_skill(s))
                  and all(it.get("skill") != s for it in plan)))
    target = next((i for i in range(len(plan) - 1, -1, -1)
                   if plan[i].get("movement") == "work" and not (plan[i].get("retest") or plan[i].get("mission_id")
                                                                 or plan[i].get("partner_of") or plan[i].get("pretest"))), None)
    if not pool or target is None:
        return None
    share = exploration_share_now(conn)
    sid, prop = exploration_decision(key, pool, share=share)
    meta = {"key": key, "pool": pool, "explored": sid, "propensity": prop, "share": share}
    if not sid:
        return {"eligible_only": meta}
    q = next(q for q in items_for_skill(sid) if q["id"] not in seen_q)
    gone = plan[target]
    seen_q.discard(gone["q"]["id"])
    seen_q.add(q["id"])
    plan[target] = {"q": q, "skill": sid, "pretest": False, "movement": "work",
                    "explore": {"key": key, "propensity": prop, "pool_size": len(pool),
                                "share": share}}
    return {"explored": plan[target], "meta": meta}


def trim_plan_to_minutes(plan, minutes, seconds_per_item):
    """Fit a plan to a time budget by removing the most expendable work items
    first (partners, then pretests, then plain due items, then exploration),
    never the opener, the closer, a retest or a repair gate."""
    if not minutes:
        return plan
    budget = int(minutes * 60)

    def cost():
        return len(plan) * seconds_per_item

    def rank(it):
        if it.get("movement") != "work" or it.get("retest") or it.get("mission_id"):
            return None
        if it.get("partner_of"):
            return 0
        if it.get("pretest"):
            return 1
        if it.get("explore"):
            return 3
        return 2
    while cost() > budget:
        cands = [(rank(it), -i) for i, it in enumerate(plan) if rank(it) is not None]
        if not cands:
            break
        _r, neg_i = min(cands)
        plan.pop(-neg_i)
    return plan


def init_exploration_schema(conn):
    conn.execute("""CREATE TABLE IF NOT EXISTS exploration_occasions (
        occasion_key TEXT, question_id TEXT, skill_id TEXT, propensity REAL, pool_size INTEGER,
        served_at TEXT, PRIMARY KEY (occasion_key, question_id))""")
    for col, decl in (("occasion_id", "TEXT"), ("session_uuid", "TEXT"), ("pool_json", "TEXT")):
        _ensure_column(conn, "exploration_occasions", col, decl)
    conn.execute("CREATE TABLE IF NOT EXISTS exploration_launches (occasion_id TEXT PRIMARY KEY, "
                 "session_uuid TEXT, occasion_key TEXT, pool_json TEXT, explored_skill TEXT, "
                 "explored_question TEXT, propensity REAL, share REAL, launched_at TEXT)")
    _ensure_column(conn, "attempts", "session_uuid", "TEXT")
    _ensure_column(conn, "attempts", "exploration_occasion_id", "TEXT")
    conn.commit()


def log_exploration_items(conn, plan):
    """Called when a session actually starts. Every eligible occasion is a
    launch with its own id and session UUID, whether or not it explored; an
    explored item's question is mapped to that id so the one answer that
    serves it is stamped exactly (stamp_attempt_context)."""
    plan = plan or {}
    meta = plan.get("exploration_meta")
    if not meta:
        return 0
    if not plan.get("session_uuid"):
        plan["session_uuid"] = str(uuid.uuid4())
    try:
        init_exploration_schema(conn)
        occ_id = plan.get("exploration_occasion_id") or str(uuid.uuid4())
        plan["exploration_occasion_id"] = occ_id
        explored_q = next((it["q"]["id"] for it in plan.get("items", []) if it.get("explore")), None)
        conn.execute("INSERT OR IGNORE INTO exploration_launches VALUES (?,?,?,?,?,?,?,?,?)",
                     (occ_id, plan["session_uuid"], meta["key"], json.dumps(meta["pool"]), meta.get("explored"),
                      explored_q, meta.get("propensity"), meta.get("share"), datetime.now().isoformat()))
        if explored_q:
            conn.execute("INSERT OR IGNORE INTO exploration_occasions (occasion_key, question_id, skill_id, "
                         "propensity, pool_size, served_at, occasion_id, session_uuid, pool_json) "
                         "VALUES (?,?,?,?,?,?,?,?,?)",
                         (meta["key"], explored_q, meta["explored"], meta["propensity"], len(meta["pool"]),
                          datetime.now().isoformat(), occ_id, plan["session_uuid"], json.dumps(meta["pool"])))
            plan["exploration_ids"] = {explored_q: occ_id}
        conn.commit()
        return 1 if explored_q else 0
    except sqlite3.Error as e:
        _audit(conn, "exploration_log_failed", f"{type(e).__name__}: {e}")
        return 0


_ACTIVE_SESSION_CTX = {"uuid": None, "explore": {}}


def session_context_begin(session):
    plan = session.composed_plan or {}
    session.session_uuid = plan.get("session_uuid") or str(uuid.uuid4())
    _ACTIVE_SESSION_CTX["uuid"] = session.session_uuid
    _ACTIVE_SESSION_CTX["explore"] = dict(plan.get("exploration_ids") or {})


def session_context_end(session):
    if _ACTIVE_SESSION_CTX.get("uuid") == getattr(session, "session_uuid", None):
        _ACTIVE_SESSION_CTX["uuid"] = None
        _ACTIVE_SESSION_CTX["explore"] = {}


def stamp_attempt_context(conn, row_id, question_id):
    """Stamp the answer row with its session and, for the first answer to an
    exploration item in that session, the exploration occasion. Identity is
    carried, never inferred later from time or question."""
    ctx = _ACTIVE_SESSION_CTX
    if not ctx.get("uuid") or not row_id:
        return
    occ = ctx["explore"].pop(question_id, None)
    try:
        _ensure_column(conn, "attempts", "session_uuid", "TEXT")
        _ensure_column(conn, "attempts", "exploration_occasion_id", "TEXT")
        conn.execute("UPDATE attempts SET session_uuid=?, exploration_occasion_id=? WHERE id=?",
                     (ctx["uuid"], occ, row_id))
        conn.commit()
    except sqlite3.Error as e:
        _audit(conn, "attempt_stamp_failed", f"{type(e).__name__}: {e}")


def randomized_evaluation_rows(conn):
    """Answers that served an exploration occasion, joined by the occasion id
    stamped on the exact attempt row, with inverse-propensity weights."""
    try:
        init_exploration_schema(conn)
        rows = _safe_query(conn, """SELECT a.id, a.question_id, a.correct, e.propensity, e.skill_id, e.occasion_id
            FROM attempts a JOIN exploration_occasions e ON a.exploration_occasion_id = e.occasion_id""")
    except Exception:
        rows = []
    return [{"attempt_id": r["id"], "question_id": r["question_id"], "skill_id": r["skill_id"],
             "occasion_id": r["occasion_id"], "correct": int(r["correct"]),
             "weight": 1.0 / max(1e-9, float(r["propensity"]))} for r in rows]


def ope_estimates(occasions, dm=None):
    """Off-policy estimates of the average loss over all (eligible occasion,
    pool skill) pairs, from occasions where one pool skill was explored with a
    known probability. Pure.

    occasions: [{"pool": [skill...], "explored": skill or None,
                 "propensity": p or None, "loss": observed loss or None}]
    dm(skill) -> modelled loss for that skill (direct-method component).

    Returns IPS (Horvitz-Thompson), SNIPS (self-normalized), DR (doubly
    robust, when dm is given), plus the diagnostics that decide whether any of
    them is worth reading: effective sample size, the largest weight, the
    number of observed and eligible occasions, and pool coverage."""
    pairs = sum(len(o["pool"]) for o in occasions)
    obs = [o for o in occasions if o.get("explored") and o.get("loss") is not None and o.get("propensity")]
    w = [1.0 / o["propensity"] for o in obs]
    out = {"n_eligible": len(occasions), "n_observed": len(obs), "pairs": pairs,
           "ess": ((sum(w) ** 2) / sum(x * x for x in w)) if w else 0.0, "w_max": max(w) if w else None,
           "coverage": (len({o["explored"] for o in obs}) / max(1, len({s for o in occasions for s in o["pool"]})))}
    if not obs or not pairs:
        out.update({"ips": None, "snips": None, "dr": None})
        return out
    out["ips"] = sum(wi * o["loss"] for wi, o in zip(w, obs)) / pairs
    out["snips"] = sum(wi * o["loss"] for wi, o in zip(w, obs)) / sum(w)
    if dm is not None:
        base = sum(dm(s) for o in occasions for s in o["pool"])
        corr = sum(wi * (o["loss"] - dm(o["explored"])) for wi, o in zip(w, obs))
        out["dr"] = (base + corr) / pairs
    else:
        out["dr"] = None
    return out


OPE_MIN_ESS = 20


def evaluate_on_randomized(conn, predict, reference=None):
    """Brier loss of predict(skill_id) -> probability, estimated off-policy on
    exploration occasions only. `reference(skill_id)` supplies the direct
    model for the doubly robust estimate (expected Brier of `predict` if the
    reference probability were true). Returns None below OPE_MIN_ESS, with the
    diagnostics that explain why."""
    try:
        init_exploration_schema(conn)
        launches = _safe_query(conn, """SELECT l.occasion_id, l.pool_json, l.explored_skill, l.propensity
            FROM exploration_launches l
            WHERE EXISTS (SELECT 1 FROM attempts a WHERE a.session_uuid = l.session_uuid)""")
        answered = {r["occasion_id"]: r for r in randomized_evaluation_rows(conn)}
    except Exception:
        return None
    occasions = []
    for r in launches:
        pool = json.loads(r["pool_json"] or "[]")
        hit = answered.get(r["occasion_id"])
        loss = None
        if hit is not None:
            loss = (predict(hit["skill_id"]) - hit["correct"]) ** 2
        occasions.append({"pool": pool, "explored": r["explored_skill"] if hit else None,
                          "propensity": r["propensity"], "loss": loss})
    def expected_brier(s):
        p, q = predict(s), reference(s)
        return q * (1 - p) ** 2 + (1 - q) * p ** 2
    est = ope_estimates(occasions, expected_brier if reference is not None else None)
    est["unanswered_explorations"] = sum(1 for r in launches if r["explored_skill"]) - est["n_observed"]
    est["readable"] = est["ess"] >= OPE_MIN_ESS
    return est


# ---- one navigation graph --------------------------------------------------------------

def build_nav_graph(domains, edges):
    """The single navigable structure behind the canvas keys, the list view,
    the web map and announcements (after Elavsky, Nadolskis & Moritz 2023:
    structure, input and rendering as separate modules)."""
    nodes = {"course": {"kind": "course", "label": "The course", "parent": None, "words": ""}}
    children = {"course": []}
    for tid in vis_domain_order():
        d = domains[tid]
        aid = f"area:{tid}"
        nodes[aid] = {"kind": "area", "label": d["name"], "parent": "course",
                      "words": present_domain_rail(d)["words"], "tid": tid}
        children["course"].append(aid)
        children[aid] = []
        for n in d["nodes"]:
            sid_ = f"skill:{n['sid']}"
            nodes[sid_] = {"kind": "skill", "label": n["label"], "parent": aid, "sid": n["sid"],
                           "tier": n["tier"], "next": n["next"],
                           "marks": [MARK_TEXT[m] for m in node_marks(n)]}
            children[aid].append(sid_)
    return {"nodes": nodes, "children": children, "relations": mirror_relations(edges)}


def nav_graph_description(graph, node_id):
    """What a screen reader or announcement says for a node, in contract words."""
    n = graph["nodes"][node_id]
    if n["kind"] == "area":
        return f"{n['label']}, area, {n['words']}"
    if n["kind"] == "skill":
        rel = graph["relations"].get(n["sid"], [])
        extra = f", {len(rel)} related skill{'s' if len(rel) != 1 else ''}" if rel else ""
        marks = (", " + ", ".join(n["marks"])) if n["marks"] else ""
        return f"{n['label']}, {n['tier']}, {n['next']}{marks}{extra}"
    return "The course"


# ---- standing catalogue: V8.4 ----------------------------------------------------------

def _probe_v84_hover_no_full_redraw(conn, inject=False):
    import inspect
    src_motion = inspect.getsource(CourseMap._on_motion)
    src_leave = inspect.getsource(CourseMap._leave)
    if inject:
        src_motion += "\n        self.redraw()"
    if "self.redraw()" in src_motion or "self.redraw()" in src_leave:
        return False, "pointing at a skill rebuilds the whole area canvas"
    if "_draw_links" not in src_motion:
        return False, "hover does not repaint the link layer"
    return True, "hover repaints only the tagged link layer; nodes and labels are untouched"


def _probe_v84_time_budget(conn, inject=False):
    qs = list(QUIZ_BANK.values())
    plan = ([{"q": qs[0], "movement": "warm"}, {"q": qs[1], "movement": "warm"}]
            + [{"q": qs[2], "movement": "work", "retest": True},
               {"q": qs[3], "movement": "work", "mission_id": 1}]
            + [{"q": qs[4 + i], "movement": "work", **({"pretest": True} if i % 3 == 0 else {})} for i in range(8)]
            + [{"q": qs[20], "movement": "close"}])
    out = trim_plan_to_minutes(list(plan), 8, 84) if not inject else list(plan)
    if len(out) * 84 > 8 * 60:
        return False, f"a plan of {len(out)} items exceeds its 8-minute budget"
    kept = {id(it["q"]) for it in out}
    must = [plan[0], plan[1], plan[2], plan[3], plan[-1]]
    if any(id(it["q"]) not in kept for it in must):
        return False, "the opener, closer, a retest or a repair gate was trimmed"
    if trim_plan_to_minutes(list(plan), None, 84) != plan:
        return False, "no budget changed the plan"
    return True, f"an 8-minute budget keeps {len(out)} items; openers, closers, retests and repairs survive"


def _probe_v84_exploration_propensity(conn, inject=False):
    pool = [f"s{i}" for i in range(7)]
    picks = {}
    n_explore = 0
    for k in range(6000):
        sid, prop = exploration_decision(f"key{k}", pool)
        if sid:
            n_explore += 1
            picks[sid] = picks.get(sid, 0) + 1
            if abs(prop - EXPLORATION_SHARE / len(pool)) > 1e-12:
                return False, f"logged propensity {prop} is not share / pool size"
    rate = n_explore / 6000.0
    if inject:
        rate = 0.5
    if abs(rate - EXPLORATION_SHARE) > 0.02:
        return False, f"exploration occurred on {rate:.3f} of occasions against a share of {EXPLORATION_SHARE}"
    expected = n_explore / len(pool)
    chi2 = sum((picks.get(sid_, 0) - expected) ** 2 / expected for sid_ in pool)
    if inject:
        chi2 = 99.0
    # df = 6, alpha = 0.001 critical value 22.46: fail only on clear non-uniformity.
    if len(picks) != len(pool) or chi2 > 22.46:
        return False, f"the exploration pick is not uniform over the stale pool (chi-square {chi2:.1f})"
    if exploration_decision("same", pool) != exploration_decision("same", pool):
        return False, "the decision is not deterministic in its occasion"
    return True, (f"explores on {rate:.1%} of occasions, uniform over the pool (chi-square {chi2:.1f} "
                  "on 6 df), propensity logged exactly")


def _probe_v84_coverage_floor(conn, inject=False):
    init_schema(conn)
    sid_a, sid_b = sorted(s for s in SKILLS if items_for_skill(s))[:2]
    qa, qb = items_for_skill(sid_a)[0], items_for_skill(sid_b)[0]
    old = (date.today() - timedelta(days=EXPLORATION_STALE_DAYS + 5)).isoformat() + "T10:00:00"
    conn.execute("INSERT INTO attempts (question_id, topic_id, correct, mode, timestamp) VALUES (?,?,?,?,?)",
                 (qa["id"], qa["topic"], 1, "quiz", old))
    conn.execute("INSERT INTO attempts (question_id, topic_id, correct, mode, timestamp) VALUES (?,?,?,?,?)",
                 (qb["id"], qb["topic"], 1, "quiz", datetime.now().isoformat()))
    conn.commit()
    rep = coverage_report(conn)
    stale = [s for s in rep["stale"] if s != sid_a] if inject else rep["stale"]
    if sid_a not in stale or sid_b in stale:
        return False, "a skill unmeasured past the floor is not in the exploration pool, or a fresh one is"
    return True, f"skills unmeasured for {EXPLORATION_STALE_DAYS} days enter the exploration pool; fresh ones do not"


def _probe_v84_randomized_evaluation(conn, inject=False):
    """Superseded in V9.1: the class keeps its name and now runs _probe_v91_exact_identity."""
    return _probe_v91_exact_identity(conn, inject)


def _probe_v84_one_navigation_graph(conn, inject=False):
    import inspect
    vs = _vis_seed_state()
    domains = {d["tid"]: d for d in present_course_map(vs)}
    g = build_nav_graph(domains, [])
    for tid in TOPICS:
        kids = [g["nodes"][k]["sid"] for k in g["children"][f"area:{tid}"]]
        if kids != vis_skills_of(tid):
            return False, f"the graph and the area view disagree about {tid}"
    if sum(len(g["children"][f"area:{t}"]) for t in TOPICS) != len(SKILLS):
        return False, "the graph does not hold every skill once"
    src = inspect.getsource(MapMirror.__init__)
    if inject:
        src = src.replace("build_nav_graph", "present_course_map")
    if "build_nav_graph" not in src:
        return False, "the list view builds its own structure instead of reading the graph"
    if any(VIS_FORBIDDEN.search(nav_graph_description(g, k)) for k in list(g["nodes"])[:60]):
        return False, "a graph description carries an internal number"
    return True, "canvas, list and descriptions read one navigation graph holding every skill once"


for _name, _spec in (
    ("v84_hover_full_redraw", {"title": "Pointing that rebuilds the picture",
        "failure_class": "Hover handlers that clear and redraw every item to change a few.",
        "invariant": "Hover repaints only the link layer.", "found_in": "V8.3.1 self-review.",
        "probe": _probe_v84_hover_no_full_redraw}),
    ("v84_session_overruns_budget", {"title": "A session longer than the time asked for",
        "failure_class": "A time budget that trims what the learner most needs, or is ignored.",
        "invariant": "Budgets are met by trimming partners, pretests, then due items; never openers, closers, retests or repairs.",
        "found_in": "V8.3.1 self-review.", "probe": _probe_v84_time_budget}),
    ("v84_exploration_unlogged", {"title": "Exploration without a known probability",
        "failure_class": "Varying what is served without recording how likely it was, so nothing can be evaluated.",
        "invariant": "Exploration occurs at its share, uniformly over the pool, with propensity logged exactly.",
        "found_in": "Chaney et al. 2018 applied to the composer loop.", "probe": _probe_v84_exploration_propensity}),
    ("v84_coverage_collapse", {"title": "Skills the policy stops looking at",
        "failure_class": "A closed loop that never re-measures what it stopped serving.",
        "invariant": "Skills unmeasured past the floor form the exploration pool.",
        "found_in": "Chaney et al. 2018 applied to the composer loop.", "probe": _probe_v84_coverage_floor}),
    ("v84_confounded_evaluation", {"title": "Evaluating on data the policy chose",
        "failure_class": "Model changes judged on answers to items the current policy selected.",
        "invariant": "Evaluation reads exploration rows only, inverse-propensity weighted.",
        "found_in": "Chaney et al. 2018; Doroudi, Aleven & Brunskill 2019.", "probe": _probe_v84_randomized_evaluation}),
    ("v84_two_structures", {"title": "Visual and accessible views built separately",
        "failure_class": "Canvas, list and speech each deriving their own structure, free to disagree.",
        "invariant": "All read one navigation graph that holds every skill once.",
        "found_in": "Data Navigator (Elavsky et al. 2023) architecture.", "probe": _probe_v84_one_navigation_graph}),
):
    register_adversarial_class(_name, _spec)


# ===========================================================================
# V8.5 -- THE QUESTION SCREEN AS TRIALS, AND AN ACCURACY-GATED SUGGESTION STRIP
# ===========================================================================
# Two changes inside the question screen, each entering as a governed
# behaviour trial rather than as a default:
#   * calm_timer: under a practice clock, show whole minutes until the last
#     five, and never colour time or pace in red. The PSI exam simulation
#     keeps the real countdown, because rehearsing the real display is its job.
#   * lookalike_note: after a miss on an item with an authored lookalike, name
#     the lookalike and the one fact that separates them.
# And one adaptive region on Today (Gajos et al.: accuracy of adaptation
# drives benefit; split, spatially stable regions help): a suggestion strip
# in a fixed position, shown only on trial occasions until a suggestion kind
# has earned a measured hit rate, then shown only if it keeps it.

BEHAVIOUR_TRIALS["calm_timer"] = {
    "share": 0.5, "floor": 8, "settle_at": 30,
    "outcome": "accuracy over served items on the timed practice set",
    "basis": ("Test-anxiety research on time-pressure displays; kept out of the exam simulation, "
              "which rehearses the real countdown."),
}
BEHAVIOUR_TRIALS["lookalike_note"] = {
    "share": 0.5, "floor": 8, "settle_at": 30,
    "outcome": "correctness on later items of the same skill in the same session",
    "basis": "Contrastive feedback for confusable concepts (discrimination learning; Kornell & Bjork 2008).",
}
BEHAVIOUR_TRIALS["suggestion_strip"] = {
    "share": 0.5, "floor": 8, "settle_at": 30, "unproven_default": "off",
    "outcome": ("whether any candidate skill moved forward within 72 hours of an eligible occasion, "
                "scored identically whether the strip was shown or not"),
    "basis": "Adaptive UI accuracy and split regions (Gajos, Czerwinski, Tan & Weld 2006; Gajos et al. 2008).",
}
CALM_TIMER_SECONDS_SHOWN = 300


def timer_display(remaining, calm, exam=False):
    """(text, colour) for the practice clock. Calm: whole minutes until the
    last five, then minutes and seconds; never red. Control: the V6 display."""
    remaining = max(0, int(remaining))
    mins, secs = remaining // 60, remaining % 60
    if calm:
        if remaining > CALM_TIMER_SECONDS_SHOWN:
            m = int(math.ceil(remaining / 60.0))
            return f"\u23f1 about {m} min left", C.NAVY
        return f"\u23f1 {mins}:{secs:02d}", C.NAVY
    if exam:
        # The exam simulation keeps the real countdown it rehearses.
        return f"\u23f1 {mins}:{secs:02d}", (C.STAMP if remaining < 60 else C.NAVY)
    return f"\u23f1 {mins}:{secs:02d}", C.NAVY


def calm_timer_arm(session):
    if not session.timed or getattr(session, "exam_mode", False):
        return False
    key = f"{session.record_mode}@{getattr(session, '_attempt_id_at_start', 0)}"
    session._calm_key = key
    try:
        return bool(behaviour_arm(session.conn, "calm_timer", key))
    except Exception:
        return False


def lookalike_for_item(qid):
    """(partner skill id, reason) for an item with an authored lookalike."""
    try:
        partner_q, why = enriched_confusion_partner(qid)
    except Exception:
        return None, None
    if not partner_q or partner_q not in QUIZ_BANK:
        return None, None
    own = set(Q_MATRIX.get(qid, []))
    sid = next((s for s in Q_MATRIX.get(partner_q, []) if s in SKILLS and s not in own), None)
    return sid, why


def lookalike_outcome(later_rows, skill_id):
    """Mean correctness of later answers on items of the noted skill, or None."""
    qids = {q["id"] for q in items_for_skill(skill_id)}
    vals = [int(r["correct"]) for r in later_rows if r["question_id"] in qids]
    return (sum(vals) / len(vals)) if vals else None


def settle_question_screen_trials(session, summary):
    conn = session.conn
    if getattr(session, "_calm_key", None) is not None:
        try:
            # V9.4: the calm clock targets disruption, so its outcome is completion.
            record_behaviour_outcome(conn, "calm_timer", session._calm_key, 1.0)
            ans, init = summary.get("answers") or [], summary.get("initial_answers") or []
            churn = sum(1 for a, b in zip(ans, init) if a is not None and b is not None and a != b)
            conn.execute("CREATE TABLE IF NOT EXISTS timer_trial_details (key TEXT PRIMARY KEY, completed INTEGER, "
                         "churn_items INTEGER)")
            conn.execute("INSERT OR REPLACE INTO timer_trial_details VALUES (?,?,?)", (session._calm_key, 1, churn))
            conn.commit()
        except Exception:
            pass
    for note in getattr(session, "_lookalike_notes", []):
        try:
            rows = _safe_query(conn, "SELECT question_id, correct FROM attempts WHERE id > ? ORDER BY id",
                               (note["after_attempt"],))
            val = lookalike_outcome([r for r in rows if r["question_id"] != note["qid"]], note["skill"])
            if val is not None:
                record_behaviour_outcome(conn, "lookalike_note", note["key"], val)
        except Exception:
            pass


def render_lookalike_note(session, q):
    """After a miss, name the lookalike when this occasion's arm is on."""
    own_skill = next((s for s in Q_MATRIX.get(q["id"], []) if s in SKILLS), None)
    partner, why = lookalike_for_item(q["id"])
    if not partner or not own_skill:
        return False
    try:
        wm = session.conn.execute("SELECT COALESCE(MAX(id),0) FROM attempts").fetchone()[0]
    except sqlite3.Error:
        wm = 0
    key = f"{q['id']}@{getattr(session, '_attempt_id_at_start', 0)}"
    if not behaviour_arm(session.conn, "lookalike_note", key):
        return False
    text = f"Easy to mix up with {SKILLS[partner]['label']}."
    if why:
        text += f" What separates them: {why}"
    ctk.CTkLabel(session.feedback_area, text=text, font=(FONT_BODY, 12), text_color=C.INK,
                 anchor="w", justify="left", wraplength=620).pack(anchor="w", pady=(4, 0))
    session._lookalike_notes = getattr(session, "_lookalike_notes", []) + [
        {"key": key, "qid": q["id"], "skill": own_skill, "after_attempt": wm}]
    return True


# ---- suggestion strip ----------------------------------------------------------------

SUGGESTION_FLOOR = 5
SUGGESTION_MIN_HIT_RATE = 0.6
SUGGESTION_KINDS = ("tell_apart", "area_review")


SUGGESTION_OUTCOME_HOURS = 72


def init_suggestion_schema(conn):
    conn.execute("""CREATE TABLE IF NOT EXISTS suggestion_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT, shown_at TEXT, kind TEXT, skills TEXT,
        occasion_key TEXT, accepted INTEGER DEFAULT 0, outcome INTEGER)""")
    for col, decl in (("arm", "TEXT"), ("shown", "INTEGER"), ("accepted_outcome", "INTEGER")):
        _ensure_column(conn, "suggestion_log", col, decl)
    conn.commit()


def suggestion_hit_rate(conn, kind):
    """PRECISION, not effect: among suggestions the learner accepted, how often
    the accepted session moved a suggested skill. Acceptance happens after
    showing, so this can never decide whether showing helps."""
    init_suggestion_schema(conn)
    rows = conn.execute("SELECT accepted_outcome FROM suggestion_log WHERE kind=? AND accepted=1 "
                        "AND accepted_outcome IS NOT NULL", (kind,)).fetchall()
    n = len(rows)
    return {"n": n, "precision": (sum(r[0] for r in rows) / n) if n else None}


def suggestion_gate(conn, kind, occasion_key):
    """Whether this eligible occasion shows its suggestion. The behaviour trial
    decides: randomized while it runs, then on if it proved help, off if it
    proved harm or never resolved (an adaptive element has no outside
    evidence to fall back on). Precision is reported, never used here."""
    settled = behaviour_settled(conn, "suggestion_strip")
    if settled is not None:
        return settled == "on", "settled"
    return bool(behaviour_arm(conn, "suggestion_strip", occasion_key)), "trial"


def present_suggestions(vs, limit=2):
    """Candidate suggestions in contract words. Pure."""
    out = []
    for p in vis_confusion_pairs():
        ta, tb = vs["tiers"].get(p["a"], TIER_NOT_STARTED), vs["tiers"].get(p["b"], TIER_NOT_STARTED)
        if TIER_NOT_STARTED in (ta, tb):
            continue
        if vs["retests"].get(p["a"]) or vs["retests"].get(p["b"]) or COARSE_OF[ta] != COARSE_OF[tb]:
            out.append({"kind": "tell_apart", "skills": [p["a"], p["b"]],
                        "text": f"Tell apart {SKILLS[p['a']]['label']} and {SKILLS[p['b']]['label']}",
                        "why": p["why"] or "These two are often mixed up."})
            break
    best = None
    for tid in vis_domain_order():
        n = sum(1 for s in vis_skills_of(tid) if vs["tiers"].get(s) == TIER_REVIEW_SOON)
        if n >= 2 and (best is None or n > best[1]):
            best = (tid, n)
    if best:
        name = TOPICS[best[0]].get("short") or TOPICS[best[0]]["name"]
        out.append({"kind": "area_review", "skills": [s for s in vis_skills_of(best[0])
                                                        if vs["tiers"].get(s) == TIER_REVIEW_SOON],
                    "tid": best[0], "text": f"Reviews due in {name}",
                    "why": f"{_plural(best[1], 'skill')} there finished the ladder and are due a review."})
    return out[:limit]


def record_suggestion_outcome(conn, suggestion_id, events):
    """Precision record for an accepted suggestion (not the trial outcome)."""
    try:
        init_suggestion_schema(conn)
        row = conn.execute("SELECT skills, accepted_outcome FROM suggestion_log WHERE id=?", (suggestion_id,)).fetchone()
        if not row or row[1] is not None:
            return None
        skills = set(json.loads(row[0] or "[]"))
        hit = int(any(e["kind"] in LEARNING_EVENT_ADVANCES and e["sid"] in skills for e in events))
        conn.execute("UPDATE suggestion_log SET accepted_outcome=? WHERE id=?", (hit, suggestion_id))
        conn.commit()
        return hit
    except (sqlite3.Error, ValueError):
        return None


def suggestion_window_outcome(conn, skills, shown_at, hours=SUGGESTION_OUTCOME_HOURS):
    """The trial outcome, identical for both arms: did any of the candidate
    skills move forward in any session within the window after the occasion?"""
    init_learning_events_schema(conn)
    end = (datetime.fromisoformat(shown_at) + timedelta(hours=hours)).isoformat()
    marks = ",".join("?" * len(LEARNING_EVENT_ADVANCES))
    sk = ",".join("?" * len(skills)) or "''"
    row = conn.execute(f"SELECT 1 FROM learning_events WHERE kind IN ({marks}) AND skill_id IN ({sk}) "
                       "AND occurred_at >= ? AND occurred_at <= ? LIMIT 1",
                       (*LEARNING_EVENT_ADVANCES, *skills, shown_at, end)).fetchone()
    return 1 if row else 0


def settle_suggestion_outcomes(conn, now=None):
    """Score every eligible occasion whose window has closed, shown or not, and
    feed it to the trial. Returns the number scored."""
    init_suggestion_schema(conn)
    now = now or datetime.now()
    cutoff = (now - timedelta(hours=SUGGESTION_OUTCOME_HOURS)).isoformat()
    rows = conn.execute("SELECT id, skills, shown_at, occasion_key FROM suggestion_log "
                        "WHERE outcome IS NULL AND arm IS NOT NULL AND shown_at <= ?", (cutoff,)).fetchall()
    for r in rows:
        y = suggestion_window_outcome(conn, json.loads(r[1] or "[]"), r[2])
        conn.execute("UPDATE suggestion_log SET outcome=? WHERE id=?", (y, r[0]))
        record_behaviour_outcome(conn, "suggestion_strip", r[3], y)
    conn.commit()
    return len(rows)


def vis_suggestion_strip(app, parent, vs):
    """The one adaptive region: fixed position under Today's action. Every
    eligible occasion is logged with its arm, shown or not, and scored later
    on the same outcome, so the strip is judged by what showing it does."""
    conn = app.conn
    init_suggestion_schema(conn)
    try:
        settle_suggestion_outcomes(conn)
    except Exception as e:
        _audit(conn, "suggestion_settle_failed", f"{type(e).__name__}: {e}")
    try:
        settle_explain_outcomes(conn)
    except Exception as e:
        _audit(conn, "explain_settle_failed", f"{type(e).__name__}: {e}")
    key = date.today().isoformat()
    shown = []
    for s in present_suggestions(vs):
        occ = f"{key}|{s['kind']}"
        prior = conn.execute("SELECT id, shown FROM suggestion_log WHERE occasion_key=? AND skills=?",
                             (occ, json.dumps(s["skills"]))).fetchone()
        if prior:
            sid_, on = prior[0], bool(prior[1])
        else:
            on, basis = suggestion_gate(conn, s["kind"], occ)
            cur = conn.execute("INSERT INTO suggestion_log (shown_at, kind, skills, occasion_key, arm, shown) "
                               "VALUES (?,?,?,?,?,?)", (datetime.now().isoformat(), s["kind"],
                                                        json.dumps(s["skills"]), occ, "on" if on else "off",
                                                        1 if on else 0))
            conn.commit()
            sid_ = cur.lastrowid
        if on:
            shown.append((s, sid_))
    if not shown:
        return None
    strip = card(parent, fg_color=C.PAPER)
    strip.pack(fill="x", pady=(0, 14))
    inner = ctk.CTkFrame(strip, fg_color="transparent")
    inner.pack(fill="x", padx=16, pady=10)
    ctk.CTkLabel(inner, text="Suggested for you", font=(FONT_BODY, 12, "bold"), text_color=C.INK,
                 anchor="w").pack(anchor="w")
    trial_running = behaviour_settled(conn, "suggestion_strip") is None
    for s, sid_ in shown:
        row = ctk.CTkFrame(inner, fg_color="transparent")
        row.pack(fill="x", pady=(4, 0))

        def accept(s=s, sid_=sid_):
            conn.execute("UPDATE suggestion_log SET accepted=1 WHERE id=?", (sid_,))
            conn.commit()
            meta = {"suggestion_id": sid_}
            if s["kind"] == "area_review":
                vis_start_constrained(app, app.content, s["tid"], back_view="today", meta=meta)
            else:
                vis_start_practice(app, app.content, s["skills"], s["text"], meta=meta)
        ghost_button(row, "Start", accept, width=70).pack(side="right")
        ctk.CTkLabel(row, text=s["text"], font=(FONT_BODY, 12), text_color=C.INK, anchor="w").pack(anchor="w")
        ctk.CTkLabel(row, text=s["why"] + ("  (being tried out)" if trial_running else ""),
                     font=(FONT_BODY, 10), text_color=C.INK_DIM, anchor="w", justify="left",
                     wraplength=560).pack(anchor="w")
    return strip


# ---- standing catalogue: V8.5 ----------------------------------------------------------

def _probe_v85_calm_timer(conn, inject=False):
    for rem in (1800, 301, 299, 59, 5):
        text, col = timer_display(rem, True)
        if inject and rem < 60:
            col = C.STAMP
        if col in (C.STAMP, C.STAMP_DIM):
            return False, f"the calm clock turns red at {rem} seconds"
        if rem > CALM_TIMER_SECONDS_SHOWN and re.search(r"\d+:\d\d", text):
            return False, "the calm clock shows seconds before the last five minutes"
    if (timer_display(59, False)[1] == C.STAMP or timer_display(1800, False)[0] != "\u23f1 30:00"
            or timer_display(59, False, exam=True)[1] != C.STAMP):
        return False, "a practice clock turns red, or the exam simulation lost its real countdown"

    class _S:
        timed, exam_mode, record_mode, _attempt_id_at_start = True, True, "exam", 1
        conn = None
    if calm_timer_arm(_S()) is not False:
        return False, "the exam simulation is entered into the calm-clock trial"
    import inspect
    if "settle_question_screen_trials" not in inspect.getsource(QuestionSession.finish):
        return False, "the trial outcome is never recorded"
    return True, "calm arm: minutes until the last five; neither practice arm is red; the exam keeps its countdown"


def _probe_v85_lookalike_outcome(conn, inject=False):
    sid = next(s for s in SKILLS if len(items_for_skill(s)) >= 2)
    q1, q2 = items_for_skill(sid)[:2]
    other = next(q for q in QUIZ_BANK.values() if sid not in Q_MATRIX.get(q["id"], []))
    rows = [{"question_id": other["id"], "correct": 0}, {"question_id": q2["id"], "correct": 1}]
    val = lookalike_outcome(rows, sid)
    if inject:
        val = 0.5
    if val != 1.0:
        return False, f"the note's outcome read {val}, not the later answer on the noted skill"
    if lookalike_outcome([{"question_id": other["id"], "correct": 1}], sid) is not None:
        return False, "an occasion with no later item on the skill was scored"
    full = _module_source() or ""
    start = full.find("class QuestionSession")
    src = full[start:full.find("\nclass ", start + 10)] if start >= 0 else ""
    call = src.find("render_lookalike_note(self, q)")
    guard = src.rfind("if not correct:", 0, call)
    if call < 0 or guard < 0 or call - guard > 2500:
        return False, "the lookalike note is not confined to missed answers"
    return True, "the note appears after misses only; its outcome is later answers on that skill, or none"


def _probe_v85_suggestion_gate(conn, inject=False):
    """Superseded in V9.1: the class keeps its name and now runs _probe_v91_suggestion_causal."""
    return _probe_v91_suggestion_causal(conn, inject)


for _name, _spec in (
    ("v85_clock_pressure", {"title": "A practice clock that alarms",
        "failure_class": "Time displays that turn red or count seconds when minutes would do, untested.",
        "invariant": "The calm clock never turns red and shows seconds only in the last five minutes; the exam keeps the real clock; outcomes are recorded.",
        "found_in": "V8.5 question screen.", "probe": _probe_v85_calm_timer}),
    ("v85_lookalike_note_unmeasured", {"title": "Feedback added without a measure",
        "failure_class": "An in-question note shown on correct answers, or judged by something other than later answers on the skill.",
        "invariant": "Shown after misses only; outcome is later same-skill answers in the session.",
        "found_in": "V8.5 question screen.", "probe": _probe_v85_lookalike_outcome}),
    ("v85_adaptation_without_accuracy", {"title": "An adaptive region that has not earned its place",
        "failure_class": "Suggestions shown by default, kept after they stop helping, or moving around the screen.",
        "invariant": "Trial occasions until measured; shown only while the hit rate holds; fixed position.",
        "found_in": "Gajos et al. 2008 applied to Today.", "probe": _probe_v85_suggestion_gate}),
):
    register_adversarial_class(_name, _spec)


# ===========================================================================
# V9 -- REACH AND EVIDENCE: A SCREEN-READER MAP AND A HUMAN EVALUATION KIT
# ===========================================================================
# Two things no amount of invariant testing supplies.
#
# Reach. Python 3.12 ships Tk 8.6, which exposes little to NVDA, JAWS or
# VoiceOver, and CustomTkinter draws on canvases. The one navigation graph
# (build_nav_graph) is therefore also rendered as a local HTML page using the
# WAI-ARIA tree pattern, opened in the learner's own browser, where the
# browser accessibility API can expose the structure to screen readers. That
# reach is a hypothesis until it is tested with NVDA, JAWS and VoiceOver. It is written to the app's own folder, uses
# no network, carries only contract words, and is regenerated on request.
#
# Evidence. The claim that learners can read this surface is a hypothesis.
# The study kit runs a short think-aloud protocol beside the app: comprehension
# tasks answered in the participant's own words (scored later against what the
# app showed at that moment), the System Usability Scale, NASA-TLX raw
# workload, and a single-item anxiety rating before and after. It writes a
# local JSON record and never touches the learner model.

WEB_MAP_FILENAME = "accessible_map.html"


def _html_escape(text):
    return (str(text).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
            .replace('"', "&quot;"))


def render_accessible_map_html(graph, generated_words=""):
    """The navigation graph as a WAI-ARIA tree page. Pure: graph in, HTML out."""
    esc = _html_escape
    parts = []
    for aid in graph["children"]["course"]:
        kids = []
        for sk in graph["children"][aid]:
            n = graph["nodes"][sk]
            rels = graph["relations"].get(n["sid"], [])
            rel_html = ""
            if rels:
                rel_items = "".join(
                    f'<li role="treeitem" aria-level="3" tabindex="-1" data-kind="relation" '
                    f'data-target="skill:{esc(other)}">{esc(rel)}: {esc(SKILLS[other]["label"])} '
                    f'<span class="hint">(press Enter to go there)</span></li>' for rel, other in rels)
                rel_html = f'<ul role="group">{rel_items}</ul>'
            desc = nav_graph_description(graph, sk)
            expanded = ' aria-expanded="false"' if rels else ""
            kids.append(f'<li role="treeitem" aria-level="2" tabindex="-1" id="{esc(sk)}" data-kind="skill"'
                        f'{expanded}><span class="label">{esc(desc)}</span>{rel_html}</li>')
        parts.append(f'<li role="treeitem" aria-level="1" tabindex="-1" id="{esc(aid)}" data-kind="area" '
                     f'aria-expanded="false"><span class="label">{esc(nav_graph_description(graph, aid))}</span>'
                     f'<ul role="group">{"".join(kids)}</ul></li>')
    first = graph["children"]["course"][0] if graph["children"]["course"] else ""
    return f"""<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Your course map</title>
<style>
:root {{ --paper:#faf6ee; --ink:#1d2433; --dim:#5b6475; --brass:#8a6a2f; --focus:#1f4e8c; }}
@media (prefers-color-scheme: dark) {{ :root {{ --paper:#141922; --ink:#e9e4d8; --dim:#aab1bf; --brass:#d2b27a; --focus:#8fb6ff; }} }}
body {{ background:var(--paper); color:var(--ink); font:17px/1.55 system-ui, -apple-system, "Segoe UI", sans-serif; margin:2rem auto; max-width:60rem; padding:0 1rem; }}
h1 {{ font-family: Georgia, serif; }}
.hint {{ color:var(--dim); font-size:.9em; }}
[role=tree], [role=group] {{ list-style:none; padding-left:1.4rem; margin:.2rem 0; }}
[role=treeitem] {{ padding:.25rem .4rem; border-radius:.35rem; }}
[role=treeitem][aria-expanded=false] > [role=group] {{ display:none; }}
[role=treeitem]:focus {{ outline:3px solid var(--focus); outline-offset:2px; }}
[data-kind=area] > .label {{ font-weight:600; }}
#status {{ position:absolute; left:-9999px; }}
</style></head>
<body><main>
<h1>Your course map</h1>
<p>Every exam area, each skill in it, and how skills connect. Use the arrow keys: Up and Down move,
Right opens an area or skill, Left closes it or goes back up, Home and End jump, and Enter on a
connection goes to that skill. Typing a letter jumps to the next item starting with it.</p>
<p class="hint">{esc(generated_words)}</p>
<ul role="tree" aria-label="Course map">{"".join(parts)}</ul>
<div id="status" role="status" aria-live="polite"></div>
</main>
<script>
(function() {{
  const tree = document.querySelector('[role=tree]');
  const status = document.getElementById('status');
  function visible() {{
    return Array.from(tree.querySelectorAll('[role=treeitem]')).filter(el => {{
      let p = el.parentElement.closest('[role=treeitem]');
      while (p) {{ if (p.getAttribute('aria-expanded') === 'false') return false; p = p.parentElement.closest('[role=treeitem]'); }}
      return true;
    }});
  }}
  function focusItem(el) {{
    tree.querySelectorAll('[role=treeitem]').forEach(i => i.tabIndex = -1);
    el.tabIndex = 0; el.focus();
  }}
  function openPath(el) {{
    let p = el.parentElement.closest('[role=treeitem]');
    while (p) {{ p.setAttribute('aria-expanded', 'true'); p = p.parentElement.closest('[role=treeitem]'); }}
  }}
  let typed = '', typedAt = 0;
  tree.addEventListener('keydown', e => {{
    const items = visible(); const cur = document.activeElement; const i = items.indexOf(cur);
    if (i < 0) return;
    const exp = cur.getAttribute('aria-expanded');
    if (e.key === 'ArrowDown') {{ if (items[i+1]) focusItem(items[i+1]); }}
    else if (e.key === 'ArrowUp') {{ if (items[i-1]) focusItem(items[i-1]); }}
    else if (e.key === 'Home') {{ focusItem(items[0]); }}
    else if (e.key === 'End') {{ focusItem(items[items.length-1]); }}
    else if (e.key === 'ArrowRight') {{
      if (exp === 'false') cur.setAttribute('aria-expanded', 'true');
      else if (exp === 'true') {{ const c = cur.querySelector('[role=treeitem]'); if (c) focusItem(c); }}
    }}
    else if (e.key === 'ArrowLeft') {{
      if (exp === 'true') cur.setAttribute('aria-expanded', 'false');
      else {{ const p = cur.parentElement.closest('[role=treeitem]'); if (p) focusItem(p); }}
    }}
    else if (e.key === 'Enter' && cur.dataset.target) {{
      const t = document.getElementById(cur.dataset.target);
      if (t) {{ openPath(t); focusItem(t); status.textContent = 'Moved to ' + t.querySelector('.label').textContent; }}
    }}
    else if (e.key.length === 1 && /\\S/.test(e.key)) {{
      const now = Date.now(); typed = (now - typedAt < 1000 ? typed : '') + e.key.toLowerCase(); typedAt = now;
      const start = typed.length > 1 ? i : i + 1;
      for (let k = 0; k < items.length; k++) {{
        const el = items[(start + k) % items.length];
        if (el.textContent.trim().toLowerCase().startsWith(typed)) {{ focusItem(el); break; }}
      }}
    }}
    else return;
    e.preventDefault();
  }});
  const first = document.getElementById('{esc(first)}');
  if (first) focusItem(first);
}})();
</script></body></html>"""


def export_accessible_map(conn, folder=None):
    vs = gather_visual_state(conn)
    domains = {d["tid"]: d for d in present_course_map(vs)}
    graph = build_nav_graph(domains, vis_prereq_edges(conn))
    html = render_accessible_map_html(graph, f"Made {date.today().strftime('%B')} {date.today().day}. "
                                             "Open it again from the app to refresh it.")
    folder = folder or APP_DIR
    os.makedirs(folder, exist_ok=True)
    path = os.path.join(folder, WEB_MAP_FILENAME)
    with open(path, "w", encoding="utf-8") as fh:
        fh.write(html)
    return path


def vis_open_web_map(app):
    try:
        path = export_accessible_map(app.conn)
        import webbrowser
        webbrowser.open("file://" + os.path.abspath(path))
        vis_announce(app, "The course map opened in your web browser.")
        return path
    except Exception as e:
        _audit(app.conn, "web_map_failed", f"{type(e).__name__}: {e}")
        app.toast("The map could not be opened in the browser.", kind="info")
        return None


# ---- human evaluation kit ----------------------------------------------------------------

SUS_ITEMS = (
    "I think that I would like to use this system frequently.",
    "I found the system unnecessarily complex.",
    "I thought the system was easy to use.",
    "I think that I would need the support of a technical person to be able to use this system.",
    "I found the various functions in this system were well integrated.",
    "I thought there was too much inconsistency in this system.",
    "I would imagine that most people would learn to use this system very quickly.",
    "I found the system very cumbersome to use.",
    "I felt very confident using the system.",
    "I needed to learn a lot of things before I could get going with this system.",
)
TLX_ITEMS = (
    ("Mental demand", "How mentally demanding was the task?"),
    ("Physical demand", "How physically demanding was the task?"),
    ("Temporal demand", "How hurried or rushed was the pace of the task?"),
    ("Performance", "How successful were you in accomplishing what you were asked to do? (0 perfect, 20 failure)"),
    ("Effort", "How hard did you have to work to accomplish your level of performance?"),
    ("Frustration", "How insecure, discouraged, irritated, stressed, and annoyed were you?"),
)
STUDY_TASKS = (
    {"id": "where_stand", "view": "map",
     "prompt": "Open the Map. Choose an area that seems to need attention. What does the Map say is happening there?"},
    {"id": "why_today", "view": "today",
     "prompt": "Open Today. Why do you think the app chose today's session for you?"},
    {"id": "what_moved", "view": "insights",
     "prompt": "Open Insights. What moved forward for you last session?"},
    {"id": "uncertain", "view": "map",
     "prompt": "Find a skill where the app has little evidence so far. How can you tell?"},
    {"id": "tell_apart", "view": "map",
     "prompt": "Find two skills that are easy to mix up and compare them. What separates them?"},
)


def sus_score(responses):
    """System Usability Scale (Brooke 1996): ten items rated 1-5. Odd items
    contribute r-1, even items 5-r; the sum times 2.5 gives 0-100."""
    if len(responses) != 10 or any(r not in (1, 2, 3, 4, 5) for r in responses):
        return None
    total = sum((r - 1) if i % 2 == 0 else (5 - r) for i, r in enumerate(responses))
    return total * 2.5


def tlx_raw(responses):
    """NASA-TLX raw (unweighted) workload: mean of six subscales on 0-20,
    rescaled to 0-100."""
    if len(responses) != 6 or any(not (0 <= r <= 20) for r in responses):
        return None
    return sum(responses) / 6.0 * 5.0


def study_truth_snapshot(conn, task_id, app=None):
    """What the app showed, in its own words, taken when the task OPENS. For
    Today it is the view model Today actually drew (app._today_view_model),
    never a plan recomposed later."""
    vs = gather_visual_state(conn)
    domains = present_course_map(vs)
    taken = datetime.now().isoformat(timespec="seconds")
    if task_id == "where_stand":
        return {"taken_at": taken, "areas": {d["name"]: present_domain_rail(d)["words"] for d in domains}}
    if task_id == "why_today":
        vm = getattr(app, "_today_view_model", None) if app is not None else None
        if vm:
            return {"taken_at": taken, "source": "today_as_drawn", **vm}
        return {"taken_at": taken, "source": "unavailable"}
    if task_id == "what_moved":
        try:
            ev = json.loads(get_setting(conn, "last_session_changes", "") or "[]")
        except ValueError:
            ev = []
        return {"taken_at": taken, "events": ev}
    if task_id == "uncertain":
        return {"taken_at": taken, "little_evidence": sorted(
            SKILLS[n["sid"]]["label"] for d in domains for n in d["nodes"] if "little_evidence" in n["overlays"])[:40]}
    if task_id == "tell_apart":
        return {"taken_at": taken, "pairs": [(SKILLS[p["a"]]["label"], SKILLS[p["b"]]["label"], p["why"])
                                             for p in vis_confusion_pairs()][:40]}
    return {"taken_at": taken}


def study_record(participant, consent, pre_anxiety, tasks, sus, tlx, post_anxiety, notes=""):
    return {"schema": "recursa.study.v1", "participant": participant, "consent": bool(consent),
            "app": "Recursa V9", "recorded_at": datetime.now().isoformat(timespec="seconds"),
            "anxiety": {"before": pre_anxiety, "after": post_anxiety},
            "tasks": tasks, "sus": {"responses": sus, "score": sus_score(sus)},
            "tlx": {"responses": tlx, "raw": tlx_raw(tlx)}, "notes": notes}


def write_study_record(record, folder=None):
    folder = folder or os.path.join(APP_DIR, "study")
    os.makedirs(folder, exist_ok=True)
    safe = re.sub(r"[^A-Za-z0-9_-]", "_", record.get("participant") or "participant")
    path = os.path.join(folder, f"{safe}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.json")
    with open(path, "w", encoding="utf-8") as fh:
        json.dump(record, fh, indent=2)
    return path


class StudyBar(ctk.CTkToplevel):
    """A small always-on-top window that walks a participant through the
    protocol while they use the app itself."""

    def __init__(self, app, participant, pre_anxiety):
        super().__init__(app)
        self.app, self.participant, self.pre = app, participant, pre_anxiety
        self.title("Study session")
        self.geometry("460x360")
        self.attributes("-topmost", True)
        self.idx, self.tasks, self.t0 = 0, [], time.time()
        self.body = ctk.CTkFrame(self, fg_color=C.PAPER)
        self.body.pack(fill="both", expand=True)
        self._task()

    def _clear(self):
        for w in self.body.winfo_children():
            w.destroy()

    def _task(self):
        self._clear()
        if self.idx >= len(STUDY_TASKS):
            return self._sus()
        t = STUDY_TASKS[self.idx]
        self.app.show_view(t["view"])
        try:
            self.app.update_idletasks()
        except tk.TclError:
            pass
        # Frozen now, when the task opens: this is what the participant sees.
        self._shown_at_open = study_truth_snapshot(self.app.conn, t["id"], app=self.app)
        self.t0 = time.time()
        ctk.CTkLabel(self.body, text=f"Task {self.idx + 1} of {len(STUDY_TASKS)}", font=(FONT_BODY, 11),
                     text_color=C.INK_DIM).pack(anchor="w", padx=14, pady=(12, 0))
        ctk.CTkLabel(self.body, text=t["prompt"], font=(FONT_BODY, 13), text_color=C.INK, wraplength=420,
                     justify="left", anchor="w").pack(anchor="w", padx=14, pady=(4, 8))
        self.box = ctk.CTkTextbox(self.body, height=140)
        self.box.pack(fill="x", padx=14)
        ctk.CTkLabel(self.body, text="Think aloud as you look. Write what you would tell a friend.",
                     font=(FONT_BODY, 10), text_color=C.INK_DIM).pack(anchor="w", padx=14, pady=(4, 0))
        primary_button(self.body, "Next", self._next_task).pack(anchor="e", padx=14, pady=10)

    def _next_task(self):
        t = STUDY_TASKS[self.idx]
        self.tasks.append({"id": t["id"], "prompt": t["prompt"], "answer": self.box.get("1.0", "end").strip(),
                           "seconds": round(time.time() - self.t0, 1), "shown": self._shown_at_open})
        self.idx += 1
        self._task()

    def _scale_page(self, title, items, lo, hi, on_done, labels=None):
        self._clear()
        frame = ctk.CTkScrollableFrame(self.body, fg_color=C.PAPER)
        frame.pack(fill="both", expand=True, padx=6, pady=6)
        ctk.CTkLabel(frame, text=title, font=(FONT_BODY, 13, "bold"), text_color=C.INK).pack(anchor="w", padx=8)
        vars_ = []
        for text in items:
            ctk.CTkLabel(frame, text=text, font=(FONT_BODY, 11), text_color=C.INK, wraplength=400,
                         justify="left", anchor="w").pack(anchor="w", padx=8, pady=(8, 0))
            var = ctk.StringVar(value="")
            vals = [str(x) for x in range(lo, hi + 1)]
            ctk.CTkSegmentedButton(frame, values=vals, variable=var).pack(anchor="w", padx=8)
            vars_.append(var)
        if labels:
            ctk.CTkLabel(frame, text=labels, font=(FONT_BODY, 10), text_color=C.INK_DIM).pack(anchor="w", padx=8)
        err = ctk.CTkLabel(frame, text="", font=(FONT_BODY, 10), text_color=C.BRASS_DARK)
        err.pack(anchor="w", padx=8)

        def done():
            if any(v.get() == "" for v in vars_):
                err.configure(text="Please answer every item.")
                return
            on_done([int(v.get()) for v in vars_])
        primary_button(frame, "Next", done).pack(anchor="e", padx=8, pady=10)
        self._scale_vars = vars_

    def _sus(self):
        self._scale_page("How was it to use?", SUS_ITEMS, 1, 5, self._got_sus, "1 strongly disagree \u2026 5 strongly agree")

    def _got_sus(self, r):
        self.sus = r
        self._scale_page("Workload", [q for _n, q in TLX_ITEMS], 0, 20, self._got_tlx, "0 very low \u2026 20 very high")

    def _got_tlx(self, r):
        self.tlx = r
        self._scale_page("And now", ["How anxious do you feel right now?"], 0, 10, self._finish,
                         "0 not at all \u2026 10 extremely")

    def _finish(self, r):
        rec = study_record(self.participant, True, self.pre, self.tasks, self.sus, self.tlx, r[0])
        rec["uncertainty_style"] = study_uncertainty_style(self.participant)
        rec["depth"] = depth_snapshot(self.app.conn)
        self.path = write_study_record(rec)
        self.app._uncertainty_style_override = None
        self._clear()
        ctk.CTkLabel(self.body, text="Thank you. The session is saved.", font=(FONT_BODY, 13, "bold"),
                     text_color=C.INK).pack(anchor="w", padx=14, pady=(16, 4))
        ctk.CTkLabel(self.body, text=self.path, font=(FONT_BODY, 10), text_color=C.INK_DIM, wraplength=420,
                     justify="left").pack(anchor="w", padx=14)
        ghost_button(self.body, "Close", self.destroy).pack(anchor="e", padx=14, pady=12)


def view_study(app, parent):
    wrap = ctk.CTkScrollableFrame(parent, fg_color="transparent")
    wrap.pack(fill="both", expand=True, padx=28, pady=22)
    section_title(wrap, "Evaluation study",
                  "A short think-aloud session for testing whether the app is understood. Run it with a "
                  "facilitator; it saves a local record and changes nothing in the learner's progress.").pack(
        anchor="w", fill="x", pady=(0, 12))
    c = card(wrap)
    c.pack(fill="x")
    i = ctk.CTkFrame(c, fg_color="transparent")
    i.pack(fill="x", padx=16, pady=14)
    ctk.CTkLabel(i, text="Participant code (no names)", font=(FONT_BODY, 12, "bold"), text_color=C.INK).pack(anchor="w")
    code = ctk.CTkEntry(i, width=200)
    code.pack(anchor="w", pady=(4, 10))
    consent = ctk.BooleanVar(value=False)
    ctk.CTkCheckBox(i, text=("The participant has read the information sheet, agrees to take part, knows they "
                             "can stop at any time, and agrees to their answers being saved on this computer."),
                    variable=consent).pack(anchor="w")
    ctk.CTkLabel(i, text="Before starting: how anxious do you feel right now? (0 not at all \u2026 10 extremely)",
                 font=(FONT_BODY, 12), text_color=C.INK).pack(anchor="w", pady=(12, 2))
    anx = ctk.StringVar(value="")
    ctk.CTkSegmentedButton(i, values=[str(x) for x in range(0, 11)], variable=anx).pack(anchor="w")
    msg = ctk.CTkLabel(i, text="", font=(FONT_BODY, 11), text_color=C.BRASS_DARK)
    msg.pack(anchor="w", pady=(8, 0))

    def begin():
        if not consent.get() or not code.get().strip() or anx.get() == "":
            msg.configure(text="A participant code, consent, and the anxiety rating are needed to begin.")
            return
        # The encoding variant lasts only for the study session (no saved setting).
        app._uncertainty_style_override = study_uncertainty_style(code.get().strip())
        app._study_bar = StudyBar(app, code.get().strip(), int(anx.get()))
    primary_button(i, "Begin the session", begin).pack(anchor="w", pady=(12, 0))
    ctk.CTkLabel(wrap, text=("The facilitator protocol, scoring guide and analysis plan are in "
                             "recursa_v9_human_evaluation_protocol.md."),
                 font=(FONT_BODY, 11), text_color=C.INK_DIM, anchor="w").pack(anchor="w", pady=(10, 0))


# ---- standing catalogue: V9 -----------------------------------------------------------------

def _probe_v9_web_map(conn, inject=False):
    from html.parser import HTMLParser
    vs = _vis_seed_state()
    domains = {d["tid"]: d for d in present_course_map(vs)}
    pairs = vis_confusion_pairs()
    edges = [(pairs[0]["a"], pairs[0]["b"])] if pairs else []
    graph = build_nav_graph(domains, edges)
    html = render_accessible_map_html(graph)
    if inject:
        html = html.replace('role="tree"', 'class="tree"')

    class P(HTMLParser):
        def __init__(self):
            super().__init__()
            self.roles, self.levels, self.text, self.stack_ok = {}, {}, [], True

        def handle_starttag(self, tag, attrs):
            a = dict(attrs)
            if "role" in a:
                self.roles[a["role"]] = self.roles.get(a["role"], 0) + 1
            if a.get("role") == "treeitem":
                self.levels[a.get("aria-level")] = self.levels.get(a.get("aria-level"), 0) + 1
                if a.get("data-kind") in ("area", "skill") and not a.get("id"):
                    self.stack_ok = False

        def handle_data(self, data):
            self.text.append(data)
    p = P()
    body = html.split("<body>", 1)[1].split("<script>", 1)[0]
    p.feed(body)
    n_rel = sum(len(v) for v in graph["relations"].values())
    if p.roles.get("tree") != 1:
        return False, "the page has no single ARIA tree"
    if p.levels.get("1") != len(TOPICS) or p.levels.get("2") != len(SKILLS) or p.levels.get("3", 0) != n_rel:
        return False, f"tree levels {p.levels} do not match the navigation graph"
    if not p.stack_ok:
        return False, "an area or skill item cannot be targeted by a connection"
    words = " ".join(p.text)
    if VIS_FORBIDDEN.search(words):
        return False, f"the web map carries an internal number: {VIS_FORBIDDEN.search(words).group(0)!r}"
    if re.search(r"https?://|src=|<link ", html):
        return False, "the web map reaches outside the local file"
    return True, (f"one ARIA tree: {len(TOPICS)} areas, {len(SKILLS)} skills, {n_rel} connection rows; "
                  "contract words only; no network")


def _probe_v9_study_scoring(conn, inject=False):
    all_agree = [5, 1, 5, 1, 5, 1, 5, 1, 5, 1]
    neutral = [3] * 10
    s1, s2 = sus_score(all_agree), sus_score(neutral)
    if inject:
        s1 = sum(all_agree) * 2.5
    if s1 != 100.0 or s2 != 50.0 or sus_score([1] * 9) is not None:
        return False, f"SUS scoring is wrong (best case {s1}, neutral {s2})"
    if tlx_raw([20] * 6) != 100.0 or tlx_raw([0] * 6) != 0.0 or tlx_raw([21] * 6) is not None:
        return False, "NASA-TLX raw scoring is wrong"
    full = _module_source() or ""
    seg = full[full.find("# ---- human evaluation kit"):full.find("# ---- standing catalogue: V9")]
    for forbidden in ("record_attempt(", "record_skill_evidence(", "record_behaviour_outcome(",
                      "set_setting(", "record_learning_events("):
        if forbidden in seg:
            return False, f"the study kit writes to the learner model ({forbidden})"
    return True, "SUS and NASA-TLX raw score correctly; the study kit never writes learner state"


def _probe_v9_study_truth_is_screen(conn, inject=False):
    init_schema(conn)
    snap = {t["id"]: study_truth_snapshot(conn, t["id"]) for t in STUDY_TASKS}
    if inject:
        snap["where_stand"] = {"theta": 0.42}
    text = json.dumps(snap)
    if VIS_FORBIDDEN.search(text) or "theta" in text:
        return False, "comprehension is scored against model numbers rather than what the screen showed"
    if set(snap) != {t["id"] for t in STUDY_TASKS}:
        return False, "a study task has no record of what the screen showed"
    return True, "every task records the words the screen showed, never model numbers"


for _name, _spec in (
    ("v9_screen_reader_unreachable", {"title": "A map no screen reader can walk",
        "failure_class": "An accessible structure that exists in code but not in any accessibility API the learner has.",
        "invariant": "The navigation graph renders as one local ARIA tree with every area, skill and connection, in contract words.",
        "found_in": "Tk 8.6 accessibility limits; Data Navigator structure pattern.", "probe": _probe_v9_web_map}),
    ("v9_study_contaminates_learner", {"title": "An evaluation that changes what it measures",
        "failure_class": "Study instruments scored wrongly, or study sessions writing to the learner model.",
        "invariant": "SUS and NASA-TLX raw score to their published formulas; the kit writes only its own record.",
        "found_in": "V9 human evaluation kit.", "probe": _probe_v9_study_scoring}),
    ("v9_comprehension_vs_model", {"title": "Understanding judged against the model",
        "failure_class": "Scoring whether a learner understood by comparing to internal estimates they never saw.",
        "invariant": "Each task stores the words the screen showed at that moment.",
        "found_in": "V9 human evaluation kit.", "probe": _probe_v9_study_truth_is_screen}),
):
    register_adversarial_class(_name, _spec)

VIEW_MAP["study"] = view_study


# ===========================================================================
# V9.1 -- MEASUREMENT VALIDITY: IDENTITY, OFF-POLICY ESTIMATES, CAUSAL UI TRIALS
# ===========================================================================
# V9 made the adaptive loop and the interface measurable. V9.1 makes the
# measurements valid:
#   * identity is carried, never inferred: every answer row holds its session
#     UUID, and the one answer that served an exploration item holds that
#     occasion's id;
#   * exploration is assigned after the time budget, and every eligible
#     launch is logged, so propensities and denominators are the real ones;
#   * off-policy evaluation reports IPS, self-normalized IPS and a doubly
#     robust estimate with effective sample size and the largest weight, and
#     refuses to be read below a floor;
#   * the suggestion strip is judged by what showing it does on every eligible
#     occasion, shown or not, not by the sessions a learner chose to accept;
#   * study truth is frozen when a task opens, and Today's is the plan it drew;
#   * reflection prompts have exactly one right answer and a known chance rate;
#   * Learning Events are written once when a session completes;
#   * one global shortcut, keyboard focus kept in view, labels that cannot
#     collide, and accessibility claims stated as hypotheses.

# Trials that act on the same occasions and outcomes, and how they are kept
# interpretable. Assignment hashes include the trial name, so arms are
# independent (a factorial design); a pair listed here is additionally
# analysed for interaction before either is promoted.
TRIAL_OVERLAPS = {
    ("calm_timer", "reappraisal"): "Both act before or during timed practice and read timed-set accuracy. "
                                   "Independent hashes make it a 2x2 factorial; check the interaction before promoting either.",
    ("lookalike_note", "reflect_before_reveal"): "Both follow misses within a session; the note's outcome is in-session, "
                                                 "the reflection's is next-session calibration, so they do not share an observable.",
}


def vis_bind_global_shortcuts(app):
    """Bind app-wide shortcuts once, routed to whichever map is active, so
    opening the Map many times never stacks handlers."""
    if getattr(app, "_global_shortcuts_bound", False):
        return False
    app._global_shortcuts_bound = True

    def alt_l(_e=None):
        m = getattr(app, "_active_map", None)
        try:
            if m is not None and m.winfo_exists():
                return m._alt_list()
        except tk.TclError:
            pass
        return "break"
    app.bind("<Alt-l>", alt_l)
    return True


def exploration_cost_report(conn):
    """What exploration costs: the share of served work items that were
    exploration items, over logged launches."""
    try:
        init_exploration_schema(conn)
        launches = conn.execute("SELECT COUNT(*) FROM exploration_launches").fetchone()[0]
        explored = conn.execute("SELECT COUNT(*) FROM exploration_launches WHERE explored_skill IS NOT NULL").fetchone()[0]
        answered = conn.execute("SELECT COUNT(*) FROM attempts WHERE exploration_occasion_id IS NOT NULL").fetchone()[0]
        served = conn.execute("SELECT COUNT(*) FROM attempts WHERE session_uuid IN "
                              "(SELECT session_uuid FROM exploration_launches)").fetchone()[0]
    except sqlite3.Error:
        return None
    return {"launches": launches, "explored": explored, "exploration_answers": answered,
            "answers_in_those_sessions": served,
            "share_of_answers": (answered / served) if served else None}


