def _probe_v91_exact_identity(conn, inject=False):
    init_schema(conn)
    init_exploration_schema(conn)
    q = list(QUIZ_BANK.values())[0]

    class _S:
        composed_plan = {"session_uuid": "S-1", "exploration_ids": {q["id"]: "OCC-1"}}
    s = _S()
    session_context_begin(s)
    conn.execute("INSERT INTO exploration_occasions (occasion_key, question_id, skill_id, propensity, pool_size, "
                 "served_at, occasion_id, session_uuid, pool_json) VALUES (?,?,?,?,?,?,?,?,?)",
                 ("k", q["id"], "s", 0.05, 3, datetime.now().isoformat(), "OCC-1", "S-1", "[]"))
    ids = []
    for ok in (1, 0):
        cur = conn.execute("INSERT INTO attempts (question_id, topic_id, correct, mode, timestamp) VALUES (?,?,?,?,?)",
                           (q["id"], q["topic"], ok, "composed", datetime.now().isoformat()))
        stamp_attempt_context(conn, cur.lastrowid, q["id"])
        ids.append(cur.lastrowid)
    session_context_end(s)
    cur = conn.execute("INSERT INTO attempts (question_id, topic_id, correct, mode, timestamp) VALUES (?,?,?,?,?)",
                       (q["id"], q["topic"], 1, "quiz", datetime.now().isoformat()))
    stamp_attempt_context(conn, cur.lastrowid, q["id"])
    conn.commit()
    if inject:
        conn.execute("UPDATE attempts SET exploration_occasion_id='OCC-1' WHERE question_id=?", (q["id"],))
        conn.commit()
    rows = randomized_evaluation_rows(conn)
    if [r["attempt_id"] for r in rows] != [ids[0]]:
        return False, f"{len(rows)} rows attributed to one exploration occasion"
    stamped = conn.execute("SELECT COUNT(*) FROM attempts WHERE session_uuid='S-1'").fetchone()[0]
    if stamped != 2:
        return False, "answers inside the session are not all stamped with its UUID, or one outside is"
    return True, "only the first answer to the explored item carries the occasion; session UUIDs stamped exactly"


def _probe_v91_ope(conn, inject=False):
    rng = random.Random(7)
    skills = [f"s{i}" for i in range(12)]
    truth_p = {s: 0.2 + 0.6 * i / 11 for i, s in enumerate(skills)}
    pred = {s: min(0.95, max(0.05, truth_p[s] + (0.25 if i % 3 == 0 else -0.1))) for i, s in enumerate(skills)}
    true_loss = {s: truth_p[s] * (1 - pred[s]) ** 2 + (1 - truth_p[s]) * pred[s] ** 2 for s in skills}
    ests = {"ips": [], "snips": [], "dr": []}
    target = None
    for _rep in range(60):
        occs, tl = [], 0.0
        for _o in range(160):
            pool = rng.sample(skills, rng.randint(3, 10))
            tl += sum(true_loss[s] for s in pool)
            share = 0.5
            if rng.random() < share:
                s = rng.choice(pool)
                y = 1 if rng.random() < truth_p[s] else 0
                occs.append({"pool": pool, "explored": s, "propensity": share / len(pool), "loss": (pred[s] - y) ** 2})
            else:
                occs.append({"pool": pool, "explored": None, "propensity": None, "loss": None})
        target = tl / sum(len(o["pool"]) for o in occs)
        e = ope_estimates(occs, dm=(lambda s: 0.25) if inject else (lambda s: true_loss[s] * 0.9 + 0.02))
        for k in ests:
            ests[k].append(e[k] - target)
    bias = {k: sum(v) / len(v) for k, v in ests.items()}
    sd = {k: (sum(x * x for x in v) / len(v)) ** 0.5 for k, v in ests.items()}
    if inject:
        bias["ips"] += 0.2
    if any(abs(bias[k]) > 0.02 for k in ("ips", "snips")):
        return False, f"IPS/SNIPS biased: {bias}"
    if abs(bias["dr"]) > 0.02 or sd["dr"] > sd["ips"]:
        return False, f"DR biased or noisier than IPS with a near-correct model (bias {bias['dr']:.3f}, sd {sd['dr']:.3f} vs {sd['ips']:.3f})"
    diag = ope_estimates([{"pool": ["a", "b"], "explored": "a", "propensity": 0.25, "loss": 0.1},
                          {"pool": ["a", "b", "c", "d"], "explored": "c", "propensity": 0.0625, "loss": 0.2}])
    if not (abs(diag["ess"] - (20.0 ** 2) / (16 + 256)) < 1e-9 and diag["w_max"] == 16.0):
        return False, "effective sample size or maximum weight is computed wrongly"
    return True, (f"over 60 replications IPS, SNIPS and DR are unbiased (|bias| <= 0.02); DR spread "
                  f"{sd['dr']:.3f} vs IPS {sd['ips']:.3f}; ESS and max weight exact")


def _probe_v91_exploration_after_budget(conn, inject=False):
    src = _module_source() or ""
    seg = src[src.find("def compose_session(conn, constraints=None):"):]
    seg = seg[:seg.find("\ndef ", 10)]
    i_trim, i_exp = seg.find("trim_plan_to_minutes("), seg.find("apply_exploration(")
    if inject:
        i_trim, i_exp = i_exp, i_trim
    if i_trim < 0 or i_exp < 0 or i_exp < i_trim:
        return False, "exploration is assigned before the time budget, so logged propensity is not serving probability"
    if "exploration_meta" not in seg:
        return False, "the plan does not carry the occasion's eligibility for logging"
    return True, "exploration is assigned after trimming; every eligible launch is logged"


def _probe_v91_suggestion_causal(conn, inject=False):
    init_schema(conn)
    init_suggestion_schema(conn)
    init_learning_events_schema(conn)
    sid = sorted(SKILLS)[0]
    old = (datetime.now() - timedelta(hours=SUGGESTION_OUTCOME_HOURS + 5)).isoformat()
    later = (datetime.now() - timedelta(hours=SUGGESTION_OUTCOME_HOURS)).isoformat()
    for key, arm in (("d1|tell_apart", "on"), ("d2|tell_apart", "off")):
        behaviour_arm(conn, "suggestion_strip", key)
        conn.execute("INSERT INTO suggestion_log (shown_at, kind, skills, occasion_key, arm, shown) VALUES (?,?,?,?,?,?)",
                     (old, "tell_apart", json.dumps([sid]), key, arm, 1 if arm == "on" else 0))
    conn.execute("INSERT INTO learning_events (occurred_at, session_key, kind, skill_id, before_tier, after_tier, text) "
                 "VALUES (?,?,?,?,?,?,?)", (later, "x", "step", sid, "Building", "Building", "t"))
    conn.commit()
    n = settle_suggestion_outcomes(conn)
    scored = conn.execute("SELECT arm, outcome FROM suggestion_log ORDER BY arm").fetchall()
    trial = conn.execute("SELECT COUNT(*) FROM behaviour_occasions WHERE name='suggestion_strip' AND outcome IS NOT NULL").fetchone()[0]
    if inject:
        trial = 1
    if n != 2 or [tuple(r) for r in scored] != [("off", 1), ("on", 1)] or trial != 2:
        return False, "eligible occasions are not scored on the same outcome in both arms"
    import inspect
    gate_src = inspect.getsource(suggestion_gate)
    if "hit_rate" in gate_src or "accepted" in gate_src:
        return False, "showing the strip is decided from accepted sessions"
    if BEHAVIOUR_TRIALS["suggestion_strip"].get("unproven_default") != "off":
        return False, "an unresolved adaptive-UI trial defaults to showing"
    return True, "both arms scored on one window outcome; the gate reads the trial, not acceptance; unresolved means off"


def _probe_v91_reflection_standard(conn, inject=False):
    sids = sorted(SKILLS)
    ev = ([{"sid": sids[i], "label": str(i), "kind": "moved"} for i in range(3)]
          + [{"sid": sids[10 + i], "label": str(i), "kind": "evidence"} for i in range(5)])
    for day in range(20):
        c = reflection_candidates(ev, f"day{day}")
        opts = [o["sid"] for o in c["options"]]
        movers = [s for s in opts if s in sids[:3]]
        if inject:
            movers = movers + movers
        if len(movers) != 1 or c["correct"] != movers[0] or c["n_options"] != len(opts) or abs(c["chance"] - 1 / len(opts)) > 1e-12:
            return False, f"a prompt has {len(movers)} right answers or an unrecorded chance rate"
    if score_reflection_choice("none", c["correct"]) != 0 or score_reflection_choice(c["correct"], c["correct"]) != 1:
        return False, "choices are scored against more than the one mover"
    full = _module_source() or ""
    seg = full[full.find("def vis_render_session_events"):]
    seg = seg[:seg.find("\ndef ", 10)]
    if '"None of these"' in seg:
        return False, "a guaranteed-wrong 'None of these' option is still offered"
    return True, "every prompt has exactly one mover among its options and records its chance rate"


def _probe_v91_label_collision(conn, inject=False):
    worst = None
    for tid in TOPICS:
        for w in (MAP_MIN_CANVAS, 800, 1100):
            cols, rows = vis_domain_grid(tid, w)
            label_w = (w - 48) / cols - 12
            pos = vis_domain_layout(tid, w, 200, top=62)
            sids = vis_skills_of(tid)
            for i, s in enumerate(sids):
                x, y = pos[s]
                bottom = y + VIS_NODE_RADIUS + VIS_LABEL_GAP + vis_label_lines(SKILLS[s]["label"], label_w) * VIS_LABEL_LINESPACE
                for j in range(i + 1, len(sids)):
                    x2, y2 = pos[sids[j]]
                    if y2 <= y:
                        continue
                    if abs(x2 - x) < label_w and (y2 - VIS_NODE_RADIUS) < bottom + (0 if not inject else 400):
                        worst = (tid, w, SKILLS[s]["label"])
                        return False, f"{tid} at {w}px: the label '{worst[2][:40]}' reaches the next row"
    return True, "at 560, 800 and 1100 px every wrapped label ends before the next row's disc"


