# ===========================================================================
# V9.3 -- METHODS FROM THE WIDER PROGRAM, APPLIED WHERE THEY FIT ONE LEARNER
# ===========================================================================
# Seven transfers, each verified as a gap in V9.2 before it was built:
#   1. Trial verdicts expire (identification decays and can be reactivated):
#      a settled verdict reopens, at a low share, after a phase change, after
#      TRIAL_VERDICT_TTL_DAYS, or after the learner model is seen to drift.
#      A verdict of measured harm never reopens by itself.
#   2. A drift monitor on the learner model: a test martingale on calibration
#      residuals (answer minus predicted probability) that is valid at every
#      stopping time (Ville). An alarm reopens trials and doubles exploration
#      for a week, so the loop re-measures what it may have mis-modelled.
#   3. Decision thresholds derived from declared costs (Elkan 2001): the
#      simulation-ready recall bar is C_FP / (C_FP + C_FN), with both costs
#      stated in words.
#   4. Four evidence states per skill (Belnap): supported, contradicted by
#      recent answers ("mixed"), underdetermined ("little evidence"), not
#      started. Mixed skills join the exploration pool.
#   5. Controller cues calibrated on simulated calm learners: the sliding cue
#      now also requires the window's accuracy to be improbably low given the
#      success rate the plan expected, which cut calm false cues several-fold.
#   6. A closed-loop ablation harness: run the real composer on a simulated
#      learner with each schedule-level layer switched off in turn.
#   7. e-BH across concurrent trials: a trial's "helps" stands only if it
#      survives false-discovery control across all trials running at once.
# And an estimator for lookalike interference, gated by the sample-size ladder.

import random as _random_v93

# ---- 1. trial verdicts that expire ---------------------------------------------

TRIAL_VERDICT_TTL_DAYS = 28
TRIAL_REOPEN_SHARE = 0.2


def init_trial_epochs_schema(conn):
    conn.execute("CREATE TABLE IF NOT EXISTS behaviour_epochs (name TEXT, started_at TEXT, reason TEXT, share REAL)")
    conn.execute("CREATE TABLE IF NOT EXISTS behaviour_settlements (name TEXT, verdict TEXT, trial_verdict TEXT, "
                 "settled_at TEXT, phase TEXT)")
    conn.commit()


def behaviour_epoch(conn, name):
    try:
        init_trial_epochs_schema(conn)
        r = conn.execute("SELECT started_at, reason, share FROM behaviour_epochs WHERE name=? "
                         "ORDER BY started_at DESC LIMIT 1", (name,)).fetchone()
    except sqlite3.Error:
        return None
    return {"started_at": r[0], "reason": r[1], "share": r[2]} if r else None


def behaviour_epoch_start(conn, name):
    ep = behaviour_epoch(conn, name)
    return ep["started_at"] if ep else ""


def behaviour_share(conn, name):
    spec = BEHAVIOUR_TRIALS.get(name) or {}
    ep = behaviour_epoch(conn, name)
    return float(ep["share"]) if ep and ep.get("share") is not None else float(spec.get("share", 0.5))


def record_trial_settlement(conn, name, out, trial_verdict):
    try:
        init_trial_epochs_schema(conn)
        conn.execute("INSERT INTO behaviour_settlements VALUES (?,?,?,?,?)",
                     (name, out, trial_verdict, datetime.now().isoformat(), learner_phase(conn)))
        conn.commit()
    except Exception:
        pass


def verdict_expiry_reason(conn, name, now=None):
    """Why the current epoch's settled verdict should reopen, or None."""
    now = now or datetime.now()
    try:
        init_trial_epochs_schema(conn)
        r = conn.execute("SELECT verdict, trial_verdict, settled_at, phase FROM behaviour_settlements "
                         "WHERE name=? AND settled_at >= ? ORDER BY settled_at DESC LIMIT 1",
                         (name, behaviour_epoch_start(conn, name))).fetchone()
    except sqlite3.Error:
        return None
    if not r:
        return None
    verdict, trial_verdict, settled_at, phase = r
    if trial_verdict == "harms":
        return None
    try:
        age = (now - datetime.fromisoformat(settled_at)).days
    except ValueError:
        age = 0
    if age >= TRIAL_VERDICT_TTL_DAYS:
        return f"verdict older than {TRIAL_VERDICT_TTL_DAYS} days"
    try:
        if learner_phase(conn) != phase:
            return "learner phase changed"
    except Exception:
        pass
    try:
        init_drift_schema(conn)
        if conn.execute("SELECT 1 FROM model_drift_events WHERE at > ? LIMIT 1", (settled_at,)).fetchone():
            return "learner model drifted after the verdict"
    except sqlite3.Error:
        pass
    return None


def reopen_trial(conn, name, reason):
    init_trial_epochs_schema(conn)
    conn.execute("INSERT INTO behaviour_epochs VALUES (?,?,?,?)",
                 (name, datetime.now().isoformat(), reason, TRIAL_REOPEN_SHARE))
    conn.commit()
    _BEHAVIOUR_STATE.pop(name, None)
    _audit(conn, "behaviour_reopened", f"{name}: {reason}")


# ---- 2. drift monitor ----------------------------------------------------------------

DRIFT_ALPHA = 0.01
DRIFT_BETS = (-0.5, -0.25, 0.25, 0.5)
DRIFT_EXPLORATION_SHARE = 0.30
DRIFT_EXPLORATION_DAYS = 7


def calibration_eprocess(pairs, bets=DRIFT_BETS):
    """Mixture test martingale for H0: E[y | p] = p, over (y, p) pairs in
    arrival order. Each factor 1 + lambda (y - p) has expectation one under
    H0 and stays positive for |lambda| < 1, so the mixture is an e-process and
    P(sup >= 1/alpha) <= alpha by Ville's inequality. Returns the running
    maximum, the final value, and the direction of the best bet."""
    wealth = [1.0] * len(bets)
    running_max, best_dir = 1.0, 0
    for y, p in pairs:
        r = float(y) - float(p)
        wealth = [w * (1.0 + b * r) for w, b in zip(wealth, bets)]
        m = sum(wealth) / len(wealth)
        if m > running_max:
            running_max = m
            best_dir = 1 if bets[max(range(len(bets)), key=lambda i: wealth[i])] > 0 else -1
    return {"max": running_max, "final": sum(wealth) / len(wealth), "direction": best_dir, "n": len(pairs)}


def init_drift_schema(conn):
    conn.execute("CREATE TABLE IF NOT EXISTS model_drift_events (at TEXT, direction INTEGER, n INTEGER, "
                 "evalue REAL, last_attempt_id INTEGER)")
    conn.commit()


def model_drift_check(conn):
    """Run the monitor over measured answers since the last alarm. An alarm is
    recorded once and resets the monitor; it reopens settled trials (through
    verdict_expiry_reason) and raises exploration for a week."""
    init_drift_schema(conn)
    try:
        start = int(get_setting(conn, "drift_reset_attempt_id", "0") or 0)
    except ValueError:
        start = 0
    try:
        rows = measurement_rows(conn, where="id > ? AND theta_at IS NOT NULL AND a_irt IS NOT NULL",
                                params=(start,), columns="id, correct, theta_at, a_irt, b_irt")
    except Exception:
        return None
    pairs = [(r["correct"], irt_p3(float(r["theta_at"]), float(r["a_irt"]), float(r["b_irt"] or 0.0)))
             for r in rows]
    if not pairs:
        return None
    res = calibration_eprocess(pairs)
    if res["max"] >= 1.0 / DRIFT_ALPHA:
        last = rows[-1]["id"]
        conn.execute("INSERT INTO model_drift_events VALUES (?,?,?,?,?)",
                     (datetime.now().isoformat(), res["direction"], res["n"], res["max"], last))
        conn.commit()
        set_setting(conn, "drift_reset_attempt_id", str(last))
        _audit(conn, "model_drift", f"direction {res['direction']} after {res['n']} answers")
        return {"alarm": True, **res}
    return {"alarm": False, **res}


def exploration_share_now(conn):
    try:
        init_drift_schema(conn)
        since = (datetime.now() - timedelta(days=DRIFT_EXPLORATION_DAYS)).isoformat()
        recent = conn.execute("SELECT 1 FROM model_drift_events WHERE at >= ? LIMIT 1", (since,)).fetchone()
    except sqlite3.Error:
        recent = None
    return DRIFT_EXPLORATION_SHARE if recent else EXPLORATION_SHARE


# ---- 4. evidence states -------------------------------------------------------------

EVIDENCE_RECENT_WINDOW = 6
EVIDENCE_MIXED_MIN_ANSWERS = 4
EVIDENCE_MIXED_MAX_ACCURACY = 0.5


def skill_evidence_state(tier, answers, recent):
    """Belnap's four values for a skill's standing, from the ladder and the
    most recent measured answers: 'underdetermined' (too little evidence),
    'contradicted' (the ladder says building or strong, recent answers say
    otherwise), 'supported', or 'not_started'."""
    if tier == TIER_NOT_STARTED:
        return "not_started"
    if answers < 3:
        return "underdetermined"
    n, correct = recent or (0, 0)
    if (COARSE_OF.get(tier) in (COARSE_BUILDING, COARSE_STRONG) and n >= EVIDENCE_MIXED_MIN_ANSWERS
            and correct / n <= EVIDENCE_MIXED_MAX_ACCURACY):
        return "contradicted"
    return "supported"


def gather_recent_accuracy(conn, window=EVIDENCE_RECENT_WINDOW):
    out, counts = {}, {}
    try:
        rows = measurement_rows(conn, columns="question_id, correct", order="id DESC", limit=4000)
    except Exception:
        rows = []
    for r in rows:
        for sid in Q_MATRIX.get(r["question_id"], []):
            if counts.get(sid, 0) >= window:
                continue
            counts[sid] = counts.get(sid, 0) + 1
            n, c = out.get(sid, (0, 0))
            out[sid] = (n + 1, c + int(r["correct"]))
    return out


# ---- 5. controller calibration --------------------------------------------------------

CONTROLLER_FALSE_CUE_TARGET = 0.15      # cues per 14-item session for a calm learner
SLIDING_TAIL_ALPHA = 0.02


def binom_lower_tail(k, n, p):
    return sum(math.comb(n, i) * p ** i * (1 - p) ** (n - i) for i in range(0, k + 1))


def simulate_calm_cues(p, sessions=2000, n_items=14, seed=0, expected_p=None, slide_after=None, slide_p=0.3):
    """Cues per session from the real signal functions on a simulated learner
    whose timing is stationary and whose accuracy is p (or drops to slide_p
    after slide_after items). Returns cues per session by signal."""
    rng = _random_v93.Random(seed)
    totals, sessions_with_cue_after_slide = {}, 0
    for _s in range(sessions):
        win, last, cued_late = [], -99, False
        for i in range(n_items):
            pi = slide_p if (slide_after is not None and i >= slide_after) else p
            z = rng.gauss(0, 1)
            win.append({"correct": rng.random() < pi, "z": z, "rt": 30.0 * 2 ** (0.4 * z)})
            win = win[-CONTROLLER_WINDOW:]
            sig, _m = compute_session_signal(win, True, "personal", 0.50, expected_p=expected_p)
            if not sig:
                sig, _m = rt_variability_signal(win, 0.75)
            if not sig or sig == "two_wrong" or i - last < CONTROLLER_COOLDOWN:
                continue
            last = i
            totals[sig] = totals.get(sig, 0) + 1
            if slide_after is not None and i >= slide_after:
                cued_late = True
        sessions_with_cue_after_slide += int(cued_late)
    out = {k: v / sessions for k, v in totals.items()}
    out["all"] = sum(totals.values()) / sessions
    if slide_after is not None:
        out["detected_slides"] = sessions_with_cue_after_slide / sessions
    return out


# ---- 6. closed-loop ablation ----------------------------------------------------------

ABLATION_LAYERS = ("exploration", "retest_escalation", "lookalike_interleaving", "mixed_in_pool")


ABLATION_MECHANISMS = ("hypercorrection_return", "lookalike_interference")


def closed_loop_ablation(days=10, seed=1, disable=(), topics=None, mechanisms=()):
    """Run the real composer for `days` simulated days on a simulated learner
    with each skill's true retention decaying and strengthening on successful
    spaced retrieval, with the listed schedule-level layers disabled. Returns
    true mean retention over all in-scope skills seven days after the last session,
    the number of skills practised, and answers given. Headless: UI-level
    layers (cues, notes, strips) are ablated by their own randomized trials.

    `mechanisms` switches on learner effects that some layers exist to answer:
    'hypercorrection_return' (a confident miss not retested within seven days
    returns as an entrenched error) and 'lookalike_interference' (practising
    one of a confusable pair weakens the other). A layer's measured value is
    only as general as the mechanisms the simulated learner has."""
    import tempfile as _tf
    rng = _random_v93.Random(seed)
    g = globals()
    saved = {k: g[k] for k in ("date", "datetime", "EXPLORATION_SHARE", "RETEST_ESCALATED_EXTRA",
                               "confusable_partner_skill", "EVIDENCE_MIXED_MIN_ANSWERS")}
    base = datetime(2026, 1, 5, 9, 0, 0)
    clock = {"offset": 0.0}

    class _D(date):
        @classmethod
        def today(cls):
            d = (base + timedelta(days=clock["offset"])).date()
            return cls(d.year, d.month, d.day)

    class _DT(datetime):
        @classmethod
        def now(cls, tz=None):
            t = base + timedelta(days=clock["offset"])
            return cls(t.year, t.month, t.day, t.hour, t.minute, t.second, t.microsecond, tzinfo=tz)
    tmpdir = _tf.mkdtemp()
    conn = sqlite3.connect(os.path.join(tmpdir, "ablation.db"))
    conn.row_factory = sqlite3.Row
    try:
        g["date"], g["datetime"] = _D, _DT
        if "exploration" in disable:
            g["EXPLORATION_SHARE"] = 0.0
        if "retest_escalation" in disable:
            g["RETEST_ESCALATED_EXTRA"] = 0
        if "lookalike_interleaving" in disable:
            g["confusable_partner_skill"] = lambda *_a, **_k: None
        if "mixed_in_pool" in disable:
            g["EVIDENCE_MIXED_MIN_ANSWERS"] = 10 ** 6
        init_schema(conn)
        skills = sorted(s for s in SKILLS if items_for_skill(s) and (topics is None or SKILLS[s]["topic"] in topics))
        prior = {s: rng.uniform(0.05, 0.35) for s in skills}
        stab = {s: 0.0 for s in skills}
        last = {s: None for s in skills}

        entrenched = {}          # skill -> day of an uncorrected confident miss
        partners = {}
        for pr in vis_confusion_pairs():
            partners.setdefault(pr["a"], set()).add(pr["b"])
            partners.setdefault(pr["b"], set()).add(pr["a"])

        def retention(s, t):
            if stab[s] <= 0 or last[s] is None:
                base_r = prior[s]
            else:
                base_r = prior[s] + (1 - prior[s]) * math.exp(-(t - last[s]) / stab[s])
            if "hypercorrection_return" in mechanisms and s in entrenched and t - entrenched[s] >= 7:
                base_r *= 0.5
            return base_r
        answers = 0
        for day in range(days):
            clock["offset"] = day
            try:
                plan = compose_session(conn, constraints=({"topics": sorted(topics)} if topics else None))
            except Exception as e:
                _audit(conn, "ablation_compose_failed", f"{type(e).__name__}: {e}")
                if os.environ.get("RECURSA_ABLATION_DEBUG"):
                    import traceback
                    traceback.print_exc()
                plan = {"items": []}
            for k, it in enumerate(plan.get("items", [])):
                clock["offset"] = day + k * 0.001
                q, s = it["q"], it.get("skill")
                if s not in stab:
                    continue
                p = 0.25 + 0.75 * retention(s, day)
                ok = rng.random() < p
                # Confidence tracks retention loosely, so confident misses occur (and
                # the retest layers have something to act on).
                conf = 3 if rng.random() < 0.3 + 0.6 * retention(s, day) else (2 if rng.random() < 0.6 else 1)
                record_attempt(conn, "composed", q["id"], q["topic"], ok, 0, q.get("a_irt", 1.0),
                               q.get("b_irt", 0.0), 45, confidence=conf, question=q)
                if not ok and conf == 3:
                    try:
                        init_pending_retests_schema(conn)
                        conn.execute("INSERT INTO pending_retests (question_id, reason, created_at) VALUES (?,?,?)",
                                     (q["id"], "confident_miss", datetime.now().isoformat()))
                        conn.commit()
                    except sqlite3.Error:
                        pass
                answers += 1
                gap = (day - last[s]) if last[s] is not None else 0
                if ok:
                    stab[s] = max(1.0, stab[s] * (1.6 + 0.2 * min(gap, 5)) if stab[s] > 0 else 1.0)
                    if s in entrenched and day - entrenched[s] < 7:
                        entrenched.pop(s, None)        # corrected in time
                else:
                    stab[s] = max(0.5, stab[s] * 0.5) if stab[s] > 0 else 0.0
                    if conf == 3:
                        entrenched.setdefault(s, day)
                last[s] = day
                if "lookalike_interference" in mechanisms:
                    for o in partners.get(s, ()):
                        if o in stab and stab[o] > 0:
                            stab[o] *= 0.7
        end = days - 1 + 7
        started = [s for s in skills if last[s] is not None]
        # Over every in-scope skill, practised or not: a layer that reaches more
        # skills is credited for it, one that concentrates practice is not.
        mean_ret = sum(retention(s, end) for s in skills) / len(skills) if skills else 0.0
        return {"retention_7d": mean_ret, "skills_practised": len(started), "answers": answers,
                "disabled": sorted(disable), "mechanisms": sorted(mechanisms)}
    finally:
        for k, v in saved.items():
            g[k] = v
        conn.close()


# ---- 7. e-BH across concurrent trials --------------------------------------------------

TRIAL_FDR_ALPHA = 0.10


def trial_help_evalue(conn, name):
    pairs = _behaviour_pairs(conn, name)
    if not pairs:
        return 1.0
    return math.exp(min(700.0, _e_log_wealth([(d, -1.0, 1.0) for d in pairs], 0, 0.0)))


def ebh_select(evalues, alpha=TRIAL_FDR_ALPHA):
    """e-BH (Wang & Ramdas 2022): reject the k* largest e-values, where k* is
    the largest k with e_(k) >= n / (alpha k). Valid under arbitrary dependence."""
    n = len(evalues)
    order = sorted(evalues.items(), key=lambda kv: -kv[1])
    k_star = 0
    for k in range(1, n + 1):
        if order[k - 1][1] >= n / (alpha * k):
            k_star = k
    return {name for name, _e in order[:k_star]}


def trials_ebh(conn, alpha=TRIAL_FDR_ALPHA):
    names = sorted(BEHAVIOUR_TRIALS)
    return ebh_select({n: trial_help_evalue(conn, n) for n in names}, alpha)


# ---- 8. lookalike interference (gated) -------------------------------------------------

register_capability("lookalike_interference", rung="n=1", live=False,
    label="Interference between lookalike skills",
    quantity="measurement_rows", threshold=1500,
    why=("One pooled coefficient across all authored pairs is estimable for one learner, but the "
         "comparison needs many answers on each partner both with and without the other practised "
         "in between, and at fewer than about 1,500 measured answers the interval spans no effect "
         "and a large one alike."),
    unlocks="A pooled estimate of how practising one of a confusable pair changes recall of the other.",
    satisfied_by="About 1,500 measured answers spread across the authored confusable pairs.")


def lookalike_interference_estimate(conn):
    """Mean calibration residual (answer minus predicted) on a pair member when
    its partner WAS practised since that member's previous answer, minus the
    same when it was not. Negative means interference. Refuses below the gate."""
    gate = capability_available(conn, "lookalike_interference")
    if not gate["available"]:
        return {"available": False, "reason": gate.get("refusal") or gate.get("reason")}
    rows = measurement_rows(conn, where="theta_at IS NOT NULL AND a_irt IS NOT NULL",
                            columns="id, question_id, correct, theta_at, a_irt, b_irt")
    partner = {}
    for p in vis_confusion_pairs():
        partner.setdefault(p["a"], set()).add(p["b"])
        partner.setdefault(p["b"], set()).add(p["a"])
    last_seen, exposed_res, clean_res = {}, [], []
    for r in rows:
        sids = [s for s in Q_MATRIX.get(r["question_id"], []) if s in SKILLS]
        resid = r["correct"] - irt_p3(float(r["theta_at"]), float(r["a_irt"]), float(r["b_irt"] or 0.0))
        for s in sids:
            if s in partner and s in last_seen:
                touched = any(last_seen.get(o, -1) > last_seen[s] for o in partner[s])
                (exposed_res if touched else clean_res).append(resid)
        for s in sids:
            last_seen[s] = r["id"]
    if len(exposed_res) < 30 or len(clean_res) < 30:
        return {"available": False, "reason": "too few answers in one of the two conditions"}

    def mv(xs):
        m = sum(xs) / len(xs)
        return m, sum((x - m) ** 2 for x in xs) / (len(xs) - 1) / len(xs)
    me, ve = mv(exposed_res)
    mc, vc = mv(clean_res)
    d, se = me - mc, math.sqrt(ve + vc)
    return {"available": True, "difference": d, "se": se, "ci": (d - 1.96 * se, d + 1.96 * se),
            "n_exposed": len(exposed_res), "n_clean": len(clean_res),
            "resolved": abs(d) > 1.96 * se}


# ---- standing catalogue: V9.3 ------------------------------------------------------------

def _probe_v93_retest_trial(conn, inject=False):
    """Restated in V9.4: escalation is governed by measurement, not randomization."""
    return _probe_v94_retest_switch_measured(conn, inject)


def _probe_v93_verdicts_expire(conn, inject=False):
    init_schema(conn)
    init_behaviour_schema(conn)
    init_trial_epochs_schema(conn)
    name = "calm_timer"
    old = (datetime.now() - timedelta(days=TRIAL_VERDICT_TTL_DAYS + 2)).isoformat()
    conn.execute("INSERT INTO behaviour_settlements VALUES (?,?,?,?,?)", (name, "on", "helps", old, learner_phase(conn)))
    conn.execute("INSERT INTO behaviour_settlements VALUES (?,?,?,?,?)", ("reappraisal", "off", "harms", old, "Z"))
    conn.commit()
    r1 = verdict_expiry_reason(conn, name) if not inject else None
    r2 = verdict_expiry_reason(conn, "reappraisal")
    if not r1:
        return False, "a verdict older than its time-to-live does not reopen"
    if r2 is not None:
        return False, "a verdict of measured harm reopened by itself"
    reopen_trial(conn, name, r1)
    if abs(behaviour_share(conn, name) - TRIAL_REOPEN_SHARE) > 1e-12:
        return False, "a reopened trial does not run at its low share"
    if behaviour_epoch_start(conn, name) <= old:
        return False, "a reopened trial still reads its old occasions"
    import inspect
    src = inspect.getsource(_behaviour_pairs) + inspect.getsource(behaviour_trial_state)
    if src.count("behaviour_epoch_start(conn, name)") < 2:
        return False, "trial evidence is not restricted to the current epoch"
    return True, "stale or drifted verdicts reopen at a low share on fresh occasions; harm stays settled"


def _probe_v93_drift_monitor(conn, inject=False):
    rng = _random_v93.Random(5)
    false_alarms, detected, delays = 0, 0, []
    reps = 250
    for _ in range(reps):
        ps = [rng.uniform(0.3, 0.9) for _ in range(400)]
        calm = [(1 if rng.random() < p else 0, p) for p in ps]
        if calibration_eprocess(calm)["max"] >= 1 / DRIFT_ALPHA:
            false_alarms += 1
        shifted = [(1 if rng.random() < (p if i < 100 else max(0.02, p - 0.2)) else 0, p) for i, p in enumerate(ps)]
        wealth_hit = None
        pairs = []
        for i, pr in enumerate(shifted):
            pairs.append(pr)
            if i >= 100 and i % 10 == 0 and calibration_eprocess(pairs)["max"] >= 1 / DRIFT_ALPHA:
                wealth_hit = i - 100
                break
        if wealth_hit is not None:
            detected += 1
            delays.append(wealth_hit)
    fa = false_alarms / reps
    if inject:
        fa = 0.2
    if fa > 1.5 * DRIFT_ALPHA:
        return False, f"false alarm rate {fa:.3f} on a well-calibrated learner"
    if detected / reps < 0.8:
        return False, f"a 20-point calibration drop detected in only {detected / reps:.0%} of runs"
    med = sorted(delays)[len(delays) // 2]
    return True, (f"calibrated learner: {fa:.1%} false alarms (alpha {DRIFT_ALPHA}); 20-point drop found in "
                  f"{detected / reps:.0%} of runs, median {med} answers after it began")


def _probe_v93_cost_thresholds(conn, inject=False):
    for name, spec in DECISION_COSTS.items():
        if not all(str(spec.get(k, "")).strip() for k in ("fp", "fn")) or spec["c_fp"] <= 0 or spec["c_fn"] <= 0:
            return False, f"decision {name} does not state both costs in words and numbers"
    thr = decision_threshold("sim_ready_recall")
    if inject:
        thr = 0.5
    if abs(CONTRACT_SIM_READY_RECALL - thr) > 1e-12 or abs(thr - 11.5 / 12.5) > 1e-12:
        return False, "the simulation-ready bar is not derived from its declared costs"
    return True, "every registered decision threshold is C_FP / (C_FP + C_FN) with both costs stated"


def _probe_v93_evidence_states(conn, inject=False):
    cases = [((TIER_NOT_STARTED, 0, None), "not_started"), ((TIER_FAMILIAR, 2, (2, 1)), "underdetermined"),
             ((TIER_STRONG, 12, (5, 2)), "contradicted"), ((TIER_STRONG, 12, (5, 4)), "supported"),
             ((TIER_ATTEMPTED, 8, (5, 1)), "supported")]
    for args, want in cases:
        got = skill_evidence_state(*args) if not inject else "supported"
        if got != want:
            return False, f"evidence state for {args} is {got!r}, expected {want!r}"
    vs = _vis_seed_state()
    sid = next(s for s in SKILLS if vs["tiers"].get(s) not in (TIER_NOT_STARTED, None))
    vs = dict(vs)
    vs["answers"] = dict(vs["answers"]); vs["answers"][sid] = 12
    vs["tiers"] = dict(vs["tiers"]); vs["tiers"][sid] = TIER_STRONG
    vs["recent"] = {sid: (5, 1)}
    ov = _skill_overlays(vs, sid)
    if "mixed_evidence" not in ov or "little_evidence" in ov:
        return False, "a contradicted skill is not shown as mixed, or is confused with little evidence"
    if VIS_FORBIDDEN.search(VIS_OVERLAY_TEXT["mixed_evidence"]):
        return False, "the mixed-evidence words carry a number"
    return True, "four evidence states; contradicted skills are shown as mixed, distinct from little evidence"


def _probe_v93_controller_calibration(conn, inject=False):
    worst = 0.0
    for p in (0.65, 0.75, 0.85):
        r = simulate_calm_cues(p, sessions=1500, seed=int(p * 100), expected_p=(None if inject else p))
        worst = max(worst, r["all"])
    if worst > CONTROLLER_FALSE_CUE_TARGET:
        return False, f"a calm learner receives {worst:.2f} cues per session (target {CONTROLLER_FALSE_CUE_TARGET})"
    slide = simulate_calm_cues(0.75, sessions=1500, seed=9, expected_p=0.75, slide_after=6, slide_p=0.2)
    if slide["detected_slides"] < 0.5:
        return False, f"a genuine slide is cued in only {slide['detected_slides']:.0%} of sessions"
    return True, (f"calm learners at 65-85% get at most {worst:.2f} cues per session; a real slide is cued in "
                  f"{slide['detected_slides']:.0%} of sessions")


def _probe_v93_ablation_harness(conn, inject=False):
    a = closed_loop_ablation(days=3, seed=2, topics={"t10", "t18"})
    b = closed_loop_ablation(days=3, seed=2, topics={"t10", "t18"})
    if inject:
        b = dict(b, retention_7d=b["retention_7d"] + 0.1)
    if a != b:
        return False, "the ablation harness is not reproducible for a fixed seed"
    if a["answers"] <= 0 or not (0.0 <= a["retention_7d"] <= 1.0):
        return False, "the harness does not drive the real composer"
    if date is not _REAL_DATE or datetime is not _REAL_DATETIME:
        return False, "the harness leaked its simulated clock"
    return True, f"reproducible headless run of the real composer ({a['answers']} answers), clock restored"


def _probe_v93_trial_fdr(conn, inject=False):
    rng = _random_v93.Random(3)
    false_disc, reps = 0, 400
    for _ in range(reps):
        es = {f"t{i}": 1.0 / max(1e-9, rng.random()) for i in range(7)}
        chosen = ebh_select(es) if not inject else {k for k, e in es.items() if e >= 1 / TRIAL_FDR_ALPHA}
        false_disc += int(bool(chosen))
    fwer = false_disc / reps
    if fwer > TRIAL_FDR_ALPHA * 1.3:
        return False, f"under seven null trials some trial is declared helpful {fwer:.0%} of the time"
    strong = ebh_select({"a": 500.0, **{f"n{i}": 1.0 for i in range(6)}})
    if strong != {"a"}:
        return False, "a strongly supported trial does not survive e-BH"
    import inspect
    if "trials_ebh(conn)" not in inspect.getsource(behaviour_trial_state):
        return False, "trial verdicts ignore false-discovery control across trials"
    return True, f"seven null trials: any false 'helps' in {fwer:.1%} of runs (alpha {TRIAL_FDR_ALPHA}); strong effects survive"


def _probe_v93_interference_gated(conn, inject=False):
    init_schema(conn)
    est = lookalike_interference_estimate(conn) if not inject else {"available": True}
    if est.get("available"):
        return False, "the interference estimate is produced below its sample-size gate"
    if "not identified" not in str(est.get("reason", "")).lower() and "short" not in str(est.get("reason", "")):
        return False, "the refusal does not state the distance to the gate"
    return True, "interference is refused below 1,500 measured answers, with the distance stated"


